function Test-FileTransferFallbackTailOwnerKeyMatchesEvent {
    param(
        [Parameter(Mandatory = $true)]$Event,
        [Parameter(Mandatory = $true)][string]$OwnerKeyField,
        [switch]$Peer
    )

    $ownerKey = ConvertTo-FileTransferFallbackTailPairingValue (
        Get-FileTransferEventField -Event $Event -Name $OwnerKeyField -Default '')
    $expectedOwnerKey = Get-FileTransferFallbackTailOwnerKeyForEvent -Event $Event -Peer:$Peer
    return $ownerKey -ne '(none)' -and
        $expectedOwnerKey -ne '(invalid)' -and
        [string]::Equals($ownerKey, $expectedOwnerKey, [System.StringComparison]::Ordinal)
}

function Get-FileTransferFallbackTailPairKeyEvidence {
    param(
        [AllowNull()][AllowEmptyString()][string]$PairKey,
        [AllowNull()][AllowEmptyString()][string]$OwnerKey,
        [long]$BridgeRecoveryGeneration = -1
    )

    $rawPairKey = ConvertTo-FileTransferFallbackTailPairingValue $PairKey
    $rawOwnerKey = ConvertTo-FileTransferFallbackTailPairingValue $OwnerKey
    $parts = if ($rawPairKey -eq '(none)') { @() } else { @($rawPairKey.Split('|')) }
    $valid = $false
    $format = 'malformed'
    $canonicalPairKey = '(none)'
    if ($parts.Count -eq 7) {
        $valid = $true
        $format = 'canonical_7'
        $canonicalPairKey = $rawPairKey
    }
    elseif ($parts.Count -eq 8) {
        $legacyBridgeGeneration = 0L
        $valid = $BridgeRecoveryGeneration -ge 0 -and
            [long]::TryParse([string]$parts[5], [ref]$legacyBridgeGeneration) -and
            $legacyBridgeGeneration -eq $BridgeRecoveryGeneration
        $format = 'legacy_bridge_scoped_8'
        $canonicalPairKey = '{0}|{1}|{2}|{3}|{4}|{5}|{6}' -f
            $parts[0], $parts[1], $parts[2], $parts[3], $parts[4], $parts[6], $parts[7]
    }
    elseif ($parts.Count -eq 9 -and
        $rawOwnerKey -ne '(none)' -and
        [string]::Equals($rawPairKey, $rawOwnerKey, [System.StringComparison]::Ordinal)) {
        $ownerBridgeGeneration = 0L
        $valid = $BridgeRecoveryGeneration -ge 0 -and
            [long]::TryParse([string]$parts[6], [ref]$ownerBridgeGeneration) -and
            $ownerBridgeGeneration -eq $BridgeRecoveryGeneration
        $format = 'owner_derived'
        $canonicalPairKey = '{0}|{1}|{2}|{3}|{4}|{5}|{6}' -f
            $parts[0], $parts[1], $parts[2], $parts[3], $parts[4], $parts[7], $parts[8]
    }

    return [pscustomobject]@{
        Valid = $valid
        RawPairKey = $rawPairKey
        CanonicalPairKey = $canonicalPairKey
        Format = $format
    }
}

function Get-FileTransferFallbackTailPairedYieldValidation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$events = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$quiescentYieldEvents = @(
        $events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_quiescent_yield_granted' })
    [object[]]$yieldProofSentEvents = @(
        $events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_yield_proof_sent' })
    [object[]]$yieldProofReceivedEvents = @(
        $events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_yield_proof_received' })
    [object[]]$schema2YieldEvents = @(
        @($quiescentYieldEvents + $yieldProofSentEvents + $yieldProofReceivedEvents) |
            Where-Object { (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 })
    [object[]]$schema2PairedEvents = @(
        $events |
            Where-Object {
                $_.EventName -eq 'filetransfer_fallback_tail_paired_yield_granted' -and
                (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2
            })
    $validPairedEvents = New-Object System.Collections.Generic.List[object]
    $validPairedEvidence = New-Object System.Collections.Generic.List[object]
    $invalidPairedEvents = New-Object System.Collections.Generic.List[object]
    $localStableFields = @(
        'authority_id',
        'predecessor_authority_id',
        'transfer_id',
        'session_id',
        'direction',
        'route',
        'protocol_version',
        'live_route_epoch',
        'runtime_generation',
        'terminal_generation',
        'leg_generation',
        'transport_epoch',
        'bridge_recovery_generation',
        'checkpoint_request_id',
        'owner_key',
        'pair_key',
        'yield_generation')
    $peerLocalScopeFields = @(
        'transfer_id',
        'session_id',
        'direction',
        'route',
        'protocol_version',
        'live_route_epoch',
        'leg_generation',
        'transport_epoch',
        'bridge_recovery_generation',
        'checkpoint_request_id')

    foreach ($pairedEvent in @($schema2PairedEvents)) {
        $pairedSequence = [int64]$pairedEvent.Sequence
        $localAuthorityIdRaw = Get-FileTransferEventField `
            -Event $pairedEvent `
            -Name 'authority_id' `
            -Default '__missing__'
        $localPredecessorAuthorityIdRaw = Get-FileTransferEventField `
            -Event $pairedEvent `
            -Name 'predecessor_authority_id' `
            -Default '__missing__'
        $peerAuthorityIdRaw = Get-FileTransferEventField `
            -Event $pairedEvent `
            -Name 'peer_authority_id' `
            -Default '__missing__'
        $peerPredecessorAuthorityIdRaw = Get-FileTransferEventField `
            -Event $pairedEvent `
            -Name 'peer_predecessor_authority_id' `
            -Default '__missing__'
        $localAuthorityId = ConvertTo-FileTransferFallbackTailPairingValue $localAuthorityIdRaw
        $peerAuthorityId = ConvertTo-FileTransferFallbackTailPairingValue $peerAuthorityIdRaw
        $peerPredecessorAuthorityId = ConvertTo-FileTransferFallbackTailPairingValue $peerPredecessorAuthorityIdRaw
        $peerAuthorityIdRedacted = $peerAuthorityIdRaw -in @('[redacted]', 'redacted', '(redacted)')
        $peerPredecessorAuthorityIdRedacted =
            $peerPredecessorAuthorityIdRaw -in @('[redacted]', 'redacted', '(redacted)')
        $peerYieldGeneration = Get-FileTransferEventInt64Field -Event $pairedEvent -Name 'peer_yield_generation' -Default 0
        $localBridgeGeneration = Get-FileTransferEventInt64Field -Event $pairedEvent -Name 'bridge_recovery_generation' -Default -1
        $localOwnerKey = Get-FileTransferEventField -Event $pairedEvent -Name 'owner_key' -Default ''
        $localPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
            -PairKey (Get-FileTransferEventField -Event $pairedEvent -Name 'pair_key' -Default '') `
            -OwnerKey $localOwnerKey `
            -BridgeRecoveryGeneration $localBridgeGeneration
        $localSharedPairKey = Get-FileTransferFallbackTailSharedPairKeyForEvent -Event $pairedEvent
        $peerBridgeGenerationFromGrant = Get-FileTransferEventInt64Field `
            -Event $pairedEvent `
            -Name 'peer_bridge_recovery_generation' `
            -Default -1
        $pairFormatsSupportBridgeDifference = $localBridgeGeneration -eq $peerBridgeGenerationFromGrant -or
            $localPairEvidence.Format -eq 'canonical_7'
        $localTupleComplete = $localAuthorityIdRaw -ne '__missing__' -and
            $localPredecessorAuthorityIdRaw -ne '__missing__' -and
            $peerAuthorityIdRaw -ne '__missing__' -and
            $peerPredecessorAuthorityIdRaw -ne '__missing__' -and
            $localAuthorityId -ne '(none)' -and
            ($peerAuthorityIdRedacted -or $peerAuthorityId -ne '(none)') -and
            $peerYieldGeneration -gt 0 -and
            (Test-FileTransferFallbackTailOwnerKeyMatchesEvent -Event $pairedEvent -OwnerKeyField 'owner_key') -and
            $localPairEvidence.Valid -and
            $pairFormatsSupportBridgeDifference -and
            $localSharedPairKey -ne '(invalid)' -and
            [string]::Equals(
                [string]$localPairEvidence.CanonicalPairKey,
                $localSharedPairKey,
                [System.StringComparison]::Ordinal)
        if (-not $localTupleComplete) {
            $invalidPairedEvents.Add($pairedEvent) | Out-Null
            continue
        }

        [object[]]$localQuiescent = @($quiescentYieldEvents | Where-Object {
            [int64]$_.Sequence -lt $pairedSequence -and
            (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 -and
            (Test-FileTransferAuthorityFieldsEqual `
                -LeftLine ([string]$pairedEvent.RawLine) `
                -RightLine ([string]$_.RawLine) `
                -Fields $localStableFields)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        [object[]]$localSent = @($yieldProofSentEvents | Where-Object {
            [int64]$_.Sequence -lt $pairedSequence -and
            (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 -and
            (Test-FileTransferAuthorityFieldsEqual `
                -LeftLine ([string]$pairedEvent.RawLine) `
                -RightLine ([string]$_.RawLine) `
                -Fields $localStableFields)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        [object[]]$peerReceived = @($yieldProofReceivedEvents | Where-Object {
            $received = $_
            $receivedAuthorityIdRaw = Get-FileTransferEventField `
                -Event $received `
                -Name 'authority_id' `
                -Default '__missing__'
            $receivedPredecessorIdRaw = Get-FileTransferEventField `
                -Event $received `
                -Name 'predecessor_authority_id' `
                -Default '__missing__'
            if ([int64]$received.Sequence -ge $pairedSequence -or
                (Get-FileTransferAuthoritySchema -Line ([string]$received.RawLine)) -lt 2 -or
                $receivedAuthorityIdRaw -eq '__missing__' -or
                $receivedPredecessorIdRaw -eq '__missing__' -or
                $receivedAuthorityIdRaw -in @('[redacted]', 'redacted', '(redacted)') -or
                (-not $peerAuthorityIdRedacted -and
                    $peerAuthorityId -ne (ConvertTo-FileTransferFallbackTailPairingValue $receivedAuthorityIdRaw)) -or
                (-not $peerPredecessorAuthorityIdRedacted -and
                    $peerPredecessorAuthorityId -ne (ConvertTo-FileTransferFallbackTailPairingValue $receivedPredecessorIdRaw)) -or
                $peerYieldGeneration -ne (Get-FileTransferEventInt64Field -Event $received -Name 'yield_generation' -Default 0) -or
                -not (Test-FileTransferAuthorityFieldsEqual `
                    -LeftLine ([string]$pairedEvent.RawLine) `
                    -RightLine ([string]$received.RawLine) `
                    -Fields $peerLocalScopeFields) -or
                -not (Test-FileTransferFallbackTailOwnerKeyMatchesEvent -Event $received -OwnerKeyField 'owner_key' -Peer)) {
                return $false
            }

            foreach ($peerFieldName in @(
                    'leg_generation',
                    'live_route_epoch',
                    'transport_epoch',
                    'bridge_recovery_generation',
                    'checkpoint_request_id')) {
                $pairedPeerValueRaw = Get-FileTransferEventField `
                    -Event $pairedEvent `
                    -Name ('peer_' + $peerFieldName) `
                    -Default '__missing__'
                $receivedPeerValueRaw = Get-FileTransferEventField `
                    -Event $received `
                    -Name ('peer_' + $peerFieldName) `
                    -Default '__missing__'
                $pairedPeerValue = ConvertTo-FileTransferFallbackTailPairingValue $pairedPeerValueRaw
                $receivedPeerValue = ConvertTo-FileTransferFallbackTailPairingValue $receivedPeerValueRaw
                if ($pairedPeerValueRaw -eq '__missing__' -or
                    $receivedPeerValueRaw -eq '__missing__' -or
                    -not [string]::Equals($pairedPeerValue, $receivedPeerValue, [System.StringComparison]::Ordinal)) {
                    return $false
                }
            }

            $pairedDirection = Get-FileTransferEventField -Event $pairedEvent -Name 'direction' -Default ''
            $expectedPeerDirection = if ($pairedDirection -eq 'inbound') { 'outbound' } elseif ($pairedDirection -eq 'outbound') { 'inbound' } else { '(invalid)' }
            $receivedPeerDirection = Get-FileTransferEventField -Event $received -Name 'peer_direction' -Default ''
            if ($expectedPeerDirection -eq '(invalid)' -or
                -not [string]::Equals(
                    $expectedPeerDirection,
                    $receivedPeerDirection,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }

            $peerBridgeGeneration = Get-FileTransferEventInt64Field -Event $received -Name 'peer_bridge_recovery_generation' -Default -1
            $peerOwnerKey = Get-FileTransferEventField -Event $received -Name 'owner_key' -Default ''
            $peerPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
                -PairKey (Get-FileTransferEventField -Event $received -Name 'pair_key' -Default '') `
                -OwnerKey $peerOwnerKey `
                -BridgeRecoveryGeneration $peerBridgeGeneration
            $peerSharedPairKey = Get-FileTransferFallbackTailSharedPairKeyForEvent -Event $received -Peer
            $pairFormatsSupportBridgeDifference = $localBridgeGeneration -eq $peerBridgeGeneration -or
                ($localPairEvidence.Format -eq 'canonical_7' -and
                    $peerPairEvidence.Format -eq 'canonical_7')
            if (-not $peerPairEvidence.Valid -or
                -not $pairFormatsSupportBridgeDifference -or
                $peerSharedPairKey -eq '(invalid)' -or
                -not [string]::Equals(
                    [string]$peerPairEvidence.CanonicalPairKey,
                    $peerSharedPairKey,
                    [System.StringComparison]::Ordinal) -or
                -not [string]::Equals(
                    [string]$peerPairEvidence.CanonicalPairKey,
                    [string]$localPairEvidence.CanonicalPairKey,
                    [System.StringComparison]::Ordinal)) {
                return $false
            }

            $receivedRawPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $received -Name 'pair_key' -Default '')
            $declaredPeerRawPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $pairedEvent -Name 'peer_raw_pair_key' -Default '')
            $declaredPeerCanonicalPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $pairedEvent -Name 'peer_canonical_pair_key' -Default '')
            $declaredPeerOwnerKey = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $pairedEvent -Name 'peer_owner_key' -Default '')
            $declaredPeerPairKeyFormat = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $pairedEvent -Name 'peer_pair_key_format' -Default '')
            return $declaredPeerOwnerKey -ne '(none)' -and
                $declaredPeerRawPairKey -ne '(none)' -and
                $declaredPeerCanonicalPairKey -ne '(none)' -and
                [string]::Equals(
                    $declaredPeerOwnerKey,
                    (ConvertTo-FileTransferFallbackTailPairingValue $peerOwnerKey),
                    [System.StringComparison]::Ordinal) -and
                [string]::Equals(
                    $declaredPeerRawPairKey,
                    $receivedRawPairKey,
                    [System.StringComparison]::Ordinal) -and
                [string]::Equals(
                    $declaredPeerCanonicalPairKey,
                    [string]$peerPairEvidence.CanonicalPairKey,
                    [System.StringComparison]::Ordinal) -and
                [string]::Equals(
                    $declaredPeerPairKeyFormat,
                    [string]$peerPairEvidence.Format,
                    [System.StringComparison]::Ordinal)
        } | Sort-Object Sequence -Descending)
        # A copied peer authority may be intentionally redacted in the paired
        # event.  Treat it as absent, not mismatched, and corroborate it only
        # when exactly one schema-2 authority-bearing peer proof matches the
        # remaining complete tuple.  Ambiguity stays fail-closed.
        if ($localQuiescent.Count -gt 0 -and $localSent.Count -gt 0 -and $peerReceived.Count -eq 1) {
            $validPairedEvents.Add($pairedEvent) | Out-Null
            $validPairedEvidence.Add([pscustomobject]@{
                PairedEvent = $pairedEvent
                LocalQuiescentEvent = $localQuiescent[0]
                LocalSentEvent = $localSent[0]
                PeerReceivedEvent = $peerReceived[0]
            }) | Out-Null
        }
        else {
            $invalidPairedEvents.Add($pairedEvent) | Out-Null
        }
    }

    return [pscustomobject]@{
        Schema2YieldEvents = $schema2YieldEvents
        Schema2PairedEvents = $schema2PairedEvents
        ValidPairedEvents = @($validPairedEvents.ToArray())
        ValidPairedEvidence = @($validPairedEvidence.ToArray())
        InvalidPairedEvents = @($invalidPairedEvents.ToArray())
    }
}

function Get-FileTransferFallbackTailCoordinatorAggregateCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$events = @(
        $Events |
            Where-Object { $null -ne $_ } |
            Sort-Object Sequence, LineNumber)
    [object[]]$yieldEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_yield_issued'
    })
    [object[]]$localReceiptEvents = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_fallback_tail_local_proof_receipt_decided',
            'filetransfer_fallback_tail_local_proof_receipt_applied',
            'filetransfer_fallback_tail_local_proof_receipt_rejected')
    })
    [object[]]$peerReceiptEvents = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_fallback_tail_peer_proof_receipt_decided',
            'filetransfer_fallback_tail_peer_proof_receipt_applied',
            'filetransfer_fallback_tail_peer_proof_receipt_rejected')
    })
    [object[]]$pairingEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_pairing_committed'
    })
    [object[]]$reservationEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_paired_release_reserved'
    })
    [object[]]$consumptionEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_paired_release_consumed'
    })
    [object[]]$carryForwardEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_paired_release_carried_forward'
    })
    [object[]]$reauthorizationStagedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_transport_epoch_reauthorization_staged'
    })
    [object[]]$reauthorizationReboundEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_transport_epoch_reauthorization_rebound'
    })
    [object[]]$reauthorizationSuccessorEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_transport_epoch_reauthorization_successor_issued'
    })
    [object[]]$reauthorizationInvalidatedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_transport_epoch_reauthorization_invalidated'
    })

    function Get-FallbackTailAggregateField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = ''
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default '__missing__'
            if ($value -ne '__missing__') {
                return [string]$value
            }
        }

        return $Default
    }

    function Test-FallbackTailAggregateAccepted {
        param([Parameter(Mandatory = $true)]$Event)

        $status = Get-FallbackTailAggregateField `
            -Event $Event `
            -Names @('decision_status', 'status') `
            -Default ''
        if ([string]::IsNullOrWhiteSpace($status)) {
            $decisionReason = Get-FallbackTailAggregateField `
                -Event $Event `
                -Names @('decision_reason') `
                -Default ''
            if ($decisionReason -in @(
                    'accepted',
                    'Accepted',
                    'idempotent',
                    'Idempotent',
                    'current',
                    'Current')) {
                return $true
            }

            return $Event.EventName -in @(
                'filetransfer_fallback_tail_local_proof_receipt_applied',
                'filetransfer_fallback_tail_peer_proof_receipt_applied')
        }

        return $status -in @(
            'Accepted',
            'Idempotent',
            'accepted',
            'idempotent',
            'Applied',
            'applied',
            'Committed',
            'committed',
            'Consumed',
            'consumed')
    }

    function Test-FallbackTailAggregateBefore {
        param(
            [Parameter(Mandatory = $true)]$Earlier,
            [Parameter(Mandatory = $true)]$Later
        )

        if ([int64]$Earlier.Sequence -lt [int64]$Later.Sequence) {
            return $true
        }
        if ([int64]$Earlier.Sequence -gt [int64]$Later.Sequence) {
            return $false
        }

        return [int64]$Earlier.LineNumber -lt [int64]$Later.LineNumber
    }

    function Test-FallbackTailAggregateRequiredValue {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Name,
            [switch]$AllowNone
        )

        $value = Get-FileTransferEventField -Event $Event -Name $Name -Default '__missing__'
        if ($value -eq '__missing__' -or [string]::IsNullOrWhiteSpace($value)) {
            return $false
        }

        return $AllowNone -or $value -notin @('(none)', 'none')
    }

    function Test-FallbackTailAggregateYieldShape {
        param([Parameter(Mandatory = $true)]$Event)

        if (-not (Test-FallbackTailAggregateAccepted -Event $Event)) {
            return $false
        }

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'authority_id',
                'owner_key',
                'pair_key',
                'data_session_identity')) {
            if (-not (Test-FallbackTailAggregateRequiredValue -Event $Event -Name $field)) {
                return $false
            }
        }
        foreach ($field in @(
                'predecessor_authority_id',
                'checkpoint_request_id')) {
            if (-not (Test-FallbackTailAggregateRequiredValue -Event $Event -Name $field -AllowNone)) {
                return $false
            }
        }

        return (Get-FileTransferEventInt64Field -Event $Event -Name 'protocol_version' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'route_publication_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'route_commit_generation' -Default -1) -ge 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'yield_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'live_route_epoch' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'runtime_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'terminal_generation' -Default -1) -ge 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'leg_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'bridge_recovery_generation' -Default -1) -ge 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'transport_epoch' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'checkpoint_generation' -Default -1) -ge 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'data_session_generation' -Default 0) -gt 0
    }

    function Test-FallbackTailAggregateLocalTuple {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'predecessor_authority_id',
                'yield_generation',
                'owner_key',
                'pair_key',
                'route',
                'protocol_version',
                'route_publication_generation',
                'route_commit_generation',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'bridge_recovery_generation',
                'transport_epoch',
                'checkpoint_generation',
                'checkpoint_request_id',
                'data_session_identity',
                'data_session_generation')) {
            $left = Get-FileTransferEventField -Event $Anchor -Name $field -Default '__missing__'
            $right = Get-FileTransferEventField -Event $Candidate -Name $field -Default '__missing__'
            if ($left -eq '__missing__' -or
                $right -eq '__missing__' -or
                -not [string]::Equals($left, $right, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailAggregateProofIdentity {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [switch]$Peer
        )

        $identityNames = if ($Peer) {
            @(
                'peer_observation_identity',
                'observation_identity',
                'peer_proof_identity',
                'proof_identity')
        }
        else {
            @('proof_identity', 'local_proof_identity', 'observation_identity')
        }
        $fingerprintNames = if ($Peer) {
            @('peer_frame_fingerprint', 'frame_fingerprint', 'proof_frame_fingerprint')
        }
        else {
            @('local_frame_fingerprint', 'frame_fingerprint', 'proof_frame_fingerprint')
        }
        $identity = Get-FallbackTailAggregateField -Event $Event -Names $identityNames -Default ''
        $fingerprint = Get-FallbackTailAggregateField `
            -Event $Event `
            -Names $fingerprintNames `
            -Default ''
        return -not [string]::IsNullOrWhiteSpace($identity) -and
            $identity -notin @('(none)', 'none') -and
            -not [string]::IsNullOrWhiteSpace($fingerprint) -and
            $fingerprint -notin @('(none)', 'none')
    }

    function Test-FallbackTailAggregatePairingReceiptIdentity {
        param(
            [Parameter(Mandatory = $true)]$Pairing,
            [Parameter(Mandatory = $true)]$Receipt,
            [switch]$Peer
        )

        $identityNames = if ($Peer) {
            @('peer_observation_identity', 'peer_proof_identity', 'observation_identity', 'proof_identity')
        }
        else {
            @('local_proof_identity', 'proof_identity', 'observation_identity')
        }
        $fingerprintNames = if ($Peer) {
            @('peer_frame_fingerprint', 'proof_frame_fingerprint', 'frame_fingerprint')
        }
        else {
            @('local_frame_fingerprint', 'proof_frame_fingerprint', 'frame_fingerprint')
        }
        $pairingIdentity = Get-FallbackTailAggregateField `
            -Event $Pairing `
            -Names $identityNames `
            -Default ''
        $receiptIdentity = Get-FallbackTailAggregateField `
            -Event $Receipt `
            -Names $identityNames `
            -Default ''
        $pairingFingerprint = Get-FallbackTailAggregateField `
            -Event $Pairing `
            -Names $fingerprintNames `
            -Default ''
        $receiptFingerprint = Get-FallbackTailAggregateField `
            -Event $Receipt `
            -Names $fingerprintNames `
            -Default ''
        return -not [string]::IsNullOrWhiteSpace($pairingIdentity) -and
            $pairingIdentity -notin @('(none)', 'none') -and
            [string]::Equals(
                $pairingIdentity,
                $receiptIdentity,
                [System.StringComparison]::Ordinal) -and
            -not [string]::IsNullOrWhiteSpace($pairingFingerprint) -and
            $pairingFingerprint -notin @('(none)', 'none') -and
            [string]::Equals(
                $pairingFingerprint,
                $receiptFingerprint,
                [System.StringComparison]::Ordinal)
    }

    function Test-FallbackTailAggregatePeerReceiptMatch {
        param(
            [Parameter(Mandatory = $true)]$Pairing,
            [Parameter(Mandatory = $true)]$Receipt
        )

        if (-not (Test-FallbackTailAggregateAccepted -Event $Receipt) -or
            -not (Test-FallbackTailAggregateProofIdentity -Event $Receipt -Peer) -or
            -not (Test-FallbackTailAggregatePairingReceiptIdentity `
                -Pairing $Pairing `
                -Receipt $Receipt `
                -Peer) -or
            -not (Test-FallbackTailAggregateLocalTuple -Anchor $Pairing -Candidate $Receipt)) {
            return $false
        }

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'live_route_epoch',
                'transport_epoch',
                'checkpoint_request_id')) {
            $left = Get-FileTransferEventField -Event $Pairing -Name $field -Default '__missing__'
            $right = Get-FileTransferEventField -Event $Receipt -Name $field -Default '__missing__'
            if ($left -eq '__missing__' -or
                $right -eq '__missing__' -or
                -not [string]::Equals($left, $right, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $pairingPairKey = Get-FileTransferEventField -Event $Pairing -Name 'pair_key' -Default '__missing__'
        $receiptPairKey = Get-FallbackTailAggregateField `
            -Event $Receipt `
            -Names @('peer_pair_key', 'pair_key') `
            -Default '__missing__'
        if ($pairingPairKey -eq '__missing__' -or
            $receiptPairKey -eq '__missing__' -or
            -not [string]::Equals($pairingPairKey, $receiptPairKey, [System.StringComparison]::Ordinal)) {
            return $false
        }

        $peerAuthorityId = Get-FileTransferEventField -Event $Pairing -Name 'peer_authority_id' -Default '__missing__'
        $receiptAuthorityId = Get-FallbackTailAggregateField `
            -Event $Receipt `
            -Names @('peer_authority_id', 'authority_id') `
            -Default '__missing__'
        $peerPredecessorId = Get-FileTransferEventField `
            -Event $Pairing `
            -Name 'peer_predecessor_authority_id' `
            -Default '__missing__'
        $receiptPredecessorId = Get-FallbackTailAggregateField `
            -Event $Receipt `
            -Names @('peer_predecessor_authority_id', 'predecessor_authority_id') `
            -Default '__missing__'
        $peerYieldGeneration = Get-FileTransferEventField `
            -Event $Pairing `
            -Name 'peer_yield_generation' `
            -Default '__missing__'
        $receiptYieldGeneration = Get-FallbackTailAggregateField `
            -Event $Receipt `
            -Names @('peer_yield_generation', 'yield_generation') `
            -Default '__missing__'
        if ($peerAuthorityId -eq '__missing__' -or
            $peerAuthorityId -in @('(none)', 'none') -or
            $receiptAuthorityId -eq '__missing__' -or
            $peerPredecessorId -eq '__missing__' -or
            $receiptPredecessorId -eq '__missing__' -or
            $peerYieldGeneration -eq '__missing__' -or
            $receiptYieldGeneration -eq '__missing__' -or
            $peerAuthorityId -ne $receiptAuthorityId -or
            $peerPredecessorId -ne $receiptPredecessorId -or
            $peerYieldGeneration -ne $receiptYieldGeneration) {
            return $false
        }

        foreach ($peerField in @(
                'peer_direction',
                'peer_owner_key',
                'peer_pair_key',
                'peer_live_route_epoch',
                'peer_leg_generation',
                'peer_bridge_recovery_generation',
                'peer_transport_epoch',
                'peer_checkpoint_request_id')) {
            $left = Get-FileTransferEventField -Event $Pairing -Name $peerField -Default '__missing__'
            $right = Get-FileTransferEventField -Event $Receipt -Name $peerField -Default '__missing__'
            if ($left -eq '__missing__' -or
                $right -eq '__missing__' -or
                -not [string]::Equals($left, $right, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $pairingDirection = Get-FileTransferEventField -Event $Pairing -Name 'direction' -Default ''
        $receiptDirection = Get-FileTransferEventField -Event $Receipt -Name 'direction' -Default ''
        $receiptPeerDirection = Get-FileTransferEventField -Event $Receipt -Name 'peer_direction' -Default ''
        $expectedPeerDirection = if ($pairingDirection -eq 'inbound') {
            'outbound'
        }
        elseif ($pairingDirection -eq 'outbound') {
            'inbound'
        }
        else {
            ''
        }
        return -not [string]::IsNullOrWhiteSpace($expectedPeerDirection) -and
            $receiptDirection -eq $pairingDirection -and
            $receiptPeerDirection -eq $expectedPeerDirection
    }

    function Get-FallbackTailAggregatePairingKey {
        param([Parameter(Mandatory = $true)]$Event)

        return (@(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'pairing_generation') | ForEach-Object {
                Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
            }) -join '|'
    }

    function Get-FallbackTailAggregateReleaseKey {
        param([Parameter(Mandatory = $true)]$Event)

        $parts = @(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'pairing_generation',
                'retry_authority_id',
                'install_generation') | ForEach-Object {
                Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
            }
        $parts += Get-FallbackTailAggregateField `
            -Event $Event `
            -Names @('retry_attempt_generation', 'dispatch_attempt_generation') `
            -Default '(missing)'
        return $parts -join '|'
    }

    function Get-FallbackTailAggregateReservationKey {
        param([Parameter(Mandatory = $true)]$Event)

        $parts = @(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'pairing_generation',
                'reservation_generation',
                'retry_authority_id') | ForEach-Object {
                Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
            }
        $parts += Get-FallbackTailAggregateField `
            -Event $Event `
            -Names @('retry_attempt_generation', 'dispatch_attempt_generation') `
            -Default '(missing)'
        return $parts -join '|'
    }

    $validPairingEvidence = New-Object System.Collections.Generic.List[object]
    $pairingBoundaries = @{}
    foreach ($pairing in $pairingEvents) {
        $pairingKey = Get-FallbackTailAggregatePairingKey -Event $pairing
        if (-not $pairingBoundaries.ContainsKey($pairingKey)) {
            $pairingBoundaries[$pairingKey] = [pscustomobject]@{
                FirstEvent = $pairing
                ValidEvent = $null
                InvalidRawCount = 0
            }
        }
        $boundary = $pairingBoundaries[$pairingKey]
        $valid = Test-FallbackTailAggregateAccepted -Event $pairing
        [object[]]$matchingYields = @()
        [object[]]$matchingLocalReceipts = @()
        [object[]]$matchingPeerReceipts = @()
        if ($valid) {
            $matchingYields = @($yieldEvents | Where-Object {
                (Test-FallbackTailAggregateBefore -Earlier $_ -Later $pairing) -and
                (Test-FallbackTailAggregateYieldShape -Event $_) -and
                (Test-FallbackTailAggregateLocalTuple -Anchor $pairing -Candidate $_)
            } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
            $matchingLocalReceipts = @($localReceiptEvents | Where-Object {
                (Test-FallbackTailAggregateBefore -Earlier $_ -Later $pairing) -and
                (Test-FallbackTailAggregateAccepted -Event $_) -and
                (Test-FallbackTailAggregateProofIdentity -Event $_) -and
                (Test-FallbackTailAggregatePairingReceiptIdentity `
                    -Pairing $pairing `
                    -Receipt $_) -and
                (Test-FallbackTailAggregateLocalTuple -Anchor $pairing -Candidate $_)
            } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
            $matchingPeerReceipts = @($peerReceiptEvents | Where-Object {
                (Test-FallbackTailAggregateBefore -Earlier $_ -Later $pairing) -and
                (Test-FallbackTailAggregatePeerReceiptMatch -Pairing $pairing -Receipt $_)
            } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
            $valid = $matchingYields.Count -eq 1 -and
                $matchingLocalReceipts.Count -eq 1 -and
                $matchingPeerReceipts.Count -eq 1 -and
                (Get-FileTransferEventInt64Field -Event $pairing -Name 'pairing_generation' -Default 0) -gt 0
        }

        if ($valid) {
            if ($null -eq $boundary.ValidEvent) {
                $boundary.ValidEvent = $pairing
                $validPairingEvidence.Add([pscustomobject]@{
                    PairingEvent = $pairing
                    YieldEvent = $matchingYields[0]
                    LocalReceiptEvent = $matchingLocalReceipts[0]
                    PeerReceiptEvent = $matchingPeerReceipts[0]
                }) | Out-Null
            }
        }
        else {
            $boundary.InvalidRawCount = [int]$boundary.InvalidRawCount + 1
        }
    }

    [object[]]$validPairingEvents = @(
        $pairingBoundaries.Values |
            Where-Object { $null -ne $_.ValidEvent } |
            ForEach-Object { $_.ValidEvent } |
            Sort-Object Sequence, LineNumber)
    [object[]]$invalidPairingEvents = @(
        $pairingBoundaries.Values |
            Where-Object { $null -eq $_.ValidEvent } |
            ForEach-Object { $_.FirstEvent } |
            Sort-Object Sequence, LineNumber)
    $pairingInvalidRawCount = @(
        $pairingBoundaries.Values |
            ForEach-Object { [int]$_.InvalidRawCount } |
            Measure-Object -Sum).Sum
    if ($null -eq $pairingInvalidRawCount) {
        $pairingInvalidRawCount = 0
    }
    $pairingRecoveredCount = @(
        $pairingBoundaries.Values |
            Where-Object {
                [int]$_.InvalidRawCount -gt 0 -and $null -ne $_.ValidEvent
            }).Count

    $carryForwardBoundaries = @{}
    foreach ($carryForward in $carryForwardEvents) {
        $carryForwardKey = (@(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'pairing_generation',
                'carry_forward_target_transport_epoch') | ForEach-Object {
                Get-FileTransferEventField `
                    -Event $carryForward `
                    -Name $_ `
                    -Default '(missing)'
            }) -join '|'
        if (-not $carryForwardBoundaries.ContainsKey($carryForwardKey)) {
            $carryForwardBoundaries[$carryForwardKey] = [pscustomobject]@{
                FirstEvent = $carryForward
                ValidEvent = $null
                SourcePairingEvent = $null
                InvalidRawCount = 0
            }
        }

        $boundary = $carryForwardBoundaries[$carryForwardKey]
        $sourceEpoch = Get-FileTransferEventInt64Field `
            -Event $carryForward `
            -Name 'carry_forward_source_transport_epoch' `
            -Default 0
        $targetEpoch = Get-FileTransferEventInt64Field `
            -Event $carryForward `
            -Name 'carry_forward_target_transport_epoch' `
            -Default 0
        $historicalAuthorityId = Get-FileTransferEventField `
            -Event $carryForward `
            -Name 'historical_release_authority_id' `
            -Default ''
        $historicalGeneration = Get-FileTransferEventInt64Field `
            -Event $carryForward `
            -Name 'historical_release_generation' `
            -Default 0
        [object[]]$matchingSourcePairings = @()
        $valid = Test-FallbackTailAggregateAccepted -Event $carryForward
        if ($valid -and
            $sourceEpoch -gt 0 -and
            $targetEpoch -gt $sourceEpoch -and
            (Get-FileTransferEventInt64Field -Event $carryForward -Name 'transport_epoch' -Default 0) -eq
                $targetEpoch -and
            (Get-FileTransferEventField -Event $carryForward -Name 'authority_id' -Default '') -eq
                $historicalAuthorityId -and
            (Get-FileTransferEventInt64Field -Event $carryForward -Name 'yield_generation' -Default 0) -eq
                $historicalGeneration -and
            (Get-FileTransferEventField -Event $carryForward -Name 'owner_key' -Default '') -eq
                (Get-FileTransferEventField -Event $carryForward -Name 'carry_forward_target_owner_key' -Default '') -and
            (Get-FileTransferEventField -Event $carryForward -Name 'pair_key' -Default '') -eq
                (Get-FileTransferEventField -Event $carryForward -Name 'carry_forward_target_pair_key' -Default '')) {
            $matchingSourcePairings = @($validPairingEvents | Where-Object {
                (Test-FallbackTailAggregateBefore -Earlier $_ -Later $carryForward) -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $carryForward -Name 'session_id' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $carryForward -Name 'transfer_id' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq
                    (Get-FileTransferEventField -Event $carryForward -Name 'direction' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq
                    $historicalAuthorityId -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'yield_generation' -Default 0) -eq
                    $historicalGeneration -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'pairing_generation' -Default 0) -eq
                    (Get-FileTransferEventInt64Field -Event $carryForward -Name 'pairing_generation' -Default 0) -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'transport_epoch' -Default 0) -eq
                    $sourceEpoch -and
                (Get-FileTransferEventField -Event $_ -Name 'owner_key' -Default '') -eq
                    (Get-FileTransferEventField -Event $carryForward -Name 'carry_forward_source_owner_key' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'pair_key' -Default '') -eq
                    (Get-FileTransferEventField -Event $carryForward -Name 'carry_forward_source_pair_key' -Default '')
            } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
            $valid = $matchingSourcePairings.Count -eq 1
        }
        else {
            $valid = $false
        }

        if ($valid) {
            if ($null -eq $boundary.ValidEvent) {
                $boundary.ValidEvent = $carryForward
                $boundary.SourcePairingEvent = $matchingSourcePairings[0]
            }
        }
        else {
            $boundary.InvalidRawCount = [int]$boundary.InvalidRawCount + 1
        }
    }

    [object[]]$validCarryForwardEvents = @(
        $carryForwardBoundaries.Values |
            Where-Object { $null -ne $_.ValidEvent } |
            ForEach-Object { $_.ValidEvent } |
            Sort-Object Sequence, LineNumber)
    [object[]]$invalidCarryForwardEvents = @(
        $carryForwardBoundaries.Values |
            Where-Object { $null -eq $_.ValidEvent } |
            ForEach-Object { $_.FirstEvent } |
            Sort-Object Sequence, LineNumber)
    $carryForwardInvalidRawCount = @(
        $carryForwardBoundaries.Values |
            ForEach-Object { [int]$_.InvalidRawCount } |
            Measure-Object -Sum).Sum
    if ($null -eq $carryForwardInvalidRawCount) {
        $carryForwardInvalidRawCount = 0
    }
    $carryForwardRecoveredCount = @(
        $carryForwardBoundaries.Values |
            Where-Object {
                [int]$_.InvalidRawCount -gt 0 -and $null -ne $_.ValidEvent
            }).Count

    $reservationBoundaries = @{}
    foreach ($reservation in $reservationEvents) {
        $reservationKey = Get-FallbackTailAggregateReservationKey -Event $reservation
        if (-not $reservationBoundaries.ContainsKey($reservationKey)) {
            $reservationBoundaries[$reservationKey] = [pscustomobject]@{
                FirstEvent = $reservation
                ValidEvent = $null
                InvalidRawCount = 0
            }
        }
        $boundary = $reservationBoundaries[$reservationKey]
        $valid = Test-FallbackTailAggregateAccepted -Event $reservation
        $retryAuthorityId = Get-FileTransferEventField `
            -Event $reservation `
            -Name 'retry_authority_id' `
            -Default ''
        $attemptGeneration = [int64](Get-FallbackTailAggregateField `
            -Event $reservation `
            -Names @('retry_attempt_generation', 'dispatch_attempt_generation') `
            -Default '0')
        $reservationGeneration = Get-FileTransferEventInt64Field `
            -Event $reservation `
            -Name 'reservation_generation' `
            -Default 0
        $installGeneration = Get-FileTransferEventInt64Field `
            -Event $reservation `
            -Name 'install_generation' `
            -Default -1
        if ($valid -and
            (-not [string]::IsNullOrWhiteSpace($retryAuthorityId)) -and
            $retryAuthorityId -notin @('(none)', 'none') -and
            $attemptGeneration -gt 0 -and
            $reservationGeneration -gt 0 -and
            $installGeneration -eq 0 -and
            (Get-FileTransferEventField -Event $reservation -Name 'release_kind' -Default '') -eq
                'FallbackPairedTailYield' -and
            (Get-FileTransferEventField -Event $reservation -Name 'release_outcome' -Default '') -eq
                'Quiescent') {
            $directPairingMatch = @($validPairingEvents | Where-Object {
                (Test-FallbackTailAggregateBefore -Earlier $_ -Later $reservation) -and
                (Test-FallbackTailAggregateLocalTuple -Anchor $reservation -Candidate $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'pairing_generation' -Default '') -eq
                    (Get-FileTransferEventField -Event $reservation -Name 'pairing_generation' -Default '')
            }).Count -eq 1
            $carryForwardMatch = @($validCarryForwardEvents | Where-Object {
                (Test-FallbackTailAggregateBefore -Earlier $_ -Later $reservation) -and
                (Test-FallbackTailAggregateLocalTuple -Anchor $reservation -Candidate $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'pairing_generation' -Default '') -eq
                    (Get-FileTransferEventField -Event $reservation -Name 'pairing_generation' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'historical_release_authority_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $reservation -Name 'authority_id' -Default '') -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'historical_release_generation' -Default 0) -eq
                    (Get-FileTransferEventInt64Field -Event $reservation -Name 'yield_generation' -Default 0)
            }).Count -eq 1
            $valid = $directPairingMatch -or $carryForwardMatch
        }
        else {
            $valid = $false
        }

        if ($valid) {
            if ($null -eq $boundary.ValidEvent) {
                $boundary.ValidEvent = $reservation
            }
        }
        else {
            $boundary.InvalidRawCount = [int]$boundary.InvalidRawCount + 1
        }
    }

    [object[]]$validReservationEvents = @(
        $reservationBoundaries.Values |
            Where-Object { $null -ne $_.ValidEvent } |
            ForEach-Object { $_.ValidEvent } |
            Sort-Object Sequence, LineNumber)
    [object[]]$invalidReservationEvents = @(
        $reservationBoundaries.Values |
            Where-Object { $null -eq $_.ValidEvent } |
            ForEach-Object { $_.FirstEvent } |
            Sort-Object Sequence, LineNumber)
    $reservationInvalidRawCount = @(
        $reservationBoundaries.Values |
            ForEach-Object { [int]$_.InvalidRawCount } |
            Measure-Object -Sum).Sum
    if ($null -eq $reservationInvalidRawCount) {
        $reservationInvalidRawCount = 0
    }
    $reservationRecoveredCount = @(
        $reservationBoundaries.Values |
            Where-Object {
                [int]$_.InvalidRawCount -gt 0 -and $null -ne $_.ValidEvent
            }).Count

    [object[]]$installEvents = @($events | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_retry_dispatch_decision_staged',
            'runtime_unlock_retry_dispatch_install_receipt_issued',
            'runtime_unlock_retry_dispatch_install_committed',
            'runtime_unlock_retry_dispatch_install_rejected',
            'runtime_unlock_retry_lifecycle_stage_decided',
            'runtime_unlock_retry_dispatch_authority_granted')
    })
    [object[]]$effectiveGrantEvents = @()
    if ($installEvents.Count -gt 0) {
        $installProof = Get-FileTransferRuntimeUnlockRetryDispatchInstallProof -Events $installEvents
        $effectiveGrantEvents = @($installProof.EffectiveGrantEvents)
    }

    $consumptionBoundaries = @{}
    foreach ($consumption in $consumptionEvents) {
        $consumptionKey = Get-FallbackTailAggregateReleaseKey -Event $consumption
        if (-not $consumptionBoundaries.ContainsKey($consumptionKey)) {
            $consumptionBoundaries[$consumptionKey] = [pscustomobject]@{
                FirstEvent = $consumption
                ValidEvent = $null
                InvalidRawCount = 0
            }
        }
        $boundary = $consumptionBoundaries[$consumptionKey]
        $valid = Test-FallbackTailAggregateAccepted -Event $consumption
        $retryAuthorityId = Get-FileTransferEventField `
            -Event $consumption `
            -Name 'retry_authority_id' `
            -Default ''
        $installGeneration = Get-FileTransferEventInt64Field `
            -Event $consumption `
            -Name 'install_generation' `
            -Default 0
        $attemptGeneration = [int64](Get-FallbackTailAggregateField `
            -Event $consumption `
            -Names @('retry_attempt_generation', 'dispatch_attempt_generation') `
            -Default '0')
        [object[]]$matchingReservations = @()
        [object[]]$matchingGrants = @()
        if ($valid -and
            -not [string]::IsNullOrWhiteSpace($retryAuthorityId) -and
            $retryAuthorityId -notin @('(none)', 'none') -and
            $installGeneration -gt 0 -and
            $attemptGeneration -gt 0) {
            $matchingReservations = @($validReservationEvents | Where-Object {
                (Test-FallbackTailAggregateBefore -Earlier $_ -Later $consumption) -and
                (Test-FallbackTailAggregateLocalTuple -Anchor $consumption -Candidate $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'pairing_generation' -Default '') -eq
                    (Get-FileTransferEventField -Event $consumption -Name 'pairing_generation' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'retry_authority_id' -Default '') -eq
                    $retryAuthorityId -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'reservation_generation' -Default 0) -eq
                    (Get-FileTransferEventInt64Field -Event $consumption -Name 'reservation_generation' -Default 0) -and
                (Get-FileTransferEventField -Event $_ -Name 'release_kind' -Default '') -eq
                    (Get-FileTransferEventField -Event $consumption -Name 'release_kind' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'release_outcome' -Default '') -eq
                    (Get-FileTransferEventField -Event $consumption -Name 'release_outcome' -Default '') -and
                [int64](Get-FallbackTailAggregateField `
                    -Event $_ `
                    -Names @('retry_attempt_generation', 'dispatch_attempt_generation') `
                    -Default '0') -eq $attemptGeneration
            } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
            $matchingGrants = @($effectiveGrantEvents | Where-Object {
                (Test-FallbackTailAggregateBefore -Earlier $_ -Later $consumption) -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $consumption -Name 'session_id' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $consumption -Name 'transfer_id' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq
                    (Get-FileTransferEventField -Event $consumption -Name 'direction' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq
                    $retryAuthorityId -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -eq
                    $installGeneration -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'dispatch_attempt_generation' -Default 0) -eq
                    $attemptGeneration -and
                (Get-FileTransferEventField -Event $_ -Name 'release_kind' -Default '') -eq
                    'FallbackPairedTailYield' -and
                (Get-FileTransferEventField -Event $_ -Name 'release_authority_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $consumption -Name 'authority_id' -Default '') -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'release_generation' -Default 0) -eq
                    (Get-FileTransferEventInt64Field -Event $consumption -Name 'yield_generation' -Default 0) -and
                (Get-FileTransferEventField -Event $_ -Name 'release_outcome' -Default '') -eq
                    'Quiescent'
            } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
            $valid = $matchingReservations.Count -eq 1 -and $matchingGrants.Count -eq 1
        }
        else {
            $valid = $false
        }

        if ($valid) {
            if ($null -eq $boundary.ValidEvent) {
                $boundary.ValidEvent = $consumption
            }
        }
        else {
            $boundary.InvalidRawCount = [int]$boundary.InvalidRawCount + 1
        }
    }

    [object[]]$validConsumptionEvents = @(
        $consumptionBoundaries.Values |
            Where-Object { $null -ne $_.ValidEvent } |
            ForEach-Object { $_.ValidEvent } |
            Sort-Object Sequence, LineNumber)
    [object[]]$invalidConsumptionEvents = @(
        $consumptionBoundaries.Values |
            Where-Object { $null -eq $_.ValidEvent } |
            ForEach-Object { $_.FirstEvent } |
            Sort-Object Sequence, LineNumber)
    $consumptionInvalidRawCount = @(
        $consumptionBoundaries.Values |
            ForEach-Object { [int]$_.InvalidRawCount } |
            Measure-Object -Sum).Sum
    if ($null -eq $consumptionInvalidRawCount) {
        $consumptionInvalidRawCount = 0
    }
    $consumptionRecoveredCount = @(
        $consumptionBoundaries.Values |
            Where-Object {
                [int]$_.InvalidRawCount -gt 0 -and $null -ne $_.ValidEvent
            }).Count
    [string[]]$validConsumptionReservationKeys = @(
        $validConsumptionEvents |
            ForEach-Object { Get-FallbackTailAggregateReservationKey -Event $_ } |
            Sort-Object -Unique)
    [string[]]$attemptedConsumptionReservationKeys = @(
        $consumptionEvents |
            ForEach-Object { Get-FallbackTailAggregateReservationKey -Event $_ } |
            Sort-Object -Unique)
    [object[]]$unconsumedReservationEvents = @(
        $validReservationEvents |
            Where-Object {
                $key = Get-FallbackTailAggregateReservationKey -Event $_
                $key -notin $validConsumptionReservationKeys -and
                    $key -notin $attemptedConsumptionReservationKeys
            } |
            Sort-Object Sequence, LineNumber)

    $validReauthorizationSuccessors = New-Object System.Collections.Generic.List[object]
    $invalidReauthorizationSuccessors = New-Object System.Collections.Generic.List[object]
    [object[]]$descriptorEvents = @(
        @($reauthorizationStagedEvents + $reauthorizationReboundEvents) |
            Sort-Object Sequence, LineNumber)

    function Test-FallbackTailAggregateReauthorizationDescriptorShape {
        param([Parameter(Mandatory = $true)]$Event)

        $targetEpoch = Get-FileTransferEventInt64Field `
            -Event $Event `
            -Name 'target_transport_epoch' `
            -Default 0
        $targetBridgeGeneration = Get-FileTransferEventInt64Field `
            -Event $Event `
            -Name 'bridge_recovery_generation' `
            -Default -1
        $checkpointRequestId = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'checkpoint_request_id' -Default '')
        $checkpointLeaseGeneration = Get-FileTransferEventInt64Field `
            -Event $Event `
            -Name 'checkpoint_lease_generation' `
            -Default -1
        $checkpointLeaseState = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'checkpoint_lease_state' -Default '')
        $checkpointLeaseRequestId = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'checkpoint_lease_request_id' -Default '')
        $checkpointLeaseReason = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'checkpoint_lease_reason' -Default '')
        $dataSessionIdentity = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'data_session_identity' -Default '')
        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'predecessor_authority_id',
                'source_owner_key',
                'source_pair_key',
                'target_owner_key',
                'target_pair_key')) {
            if (-not (Test-FallbackTailAggregateRequiredValue -Event $Event -Name $field)) {
                return $false
            }
        }

        if ((Get-FileTransferEventInt64Field -Event $Event -Name 'target_transport_decision_generation' -Default 0) -le 0 -or
            -not [string]::Equals(
                (Get-FileTransferEventField -Event $Event -Name 'target_transport_decision_action' -Default ''),
                'Adopt',
                [System.StringComparison]::Ordinal) -or
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Event -Name 'target_transport_decision_reason' -Default '')) -eq '(none)' -or
            (Get-FileTransferEventInt64Field -Event $Event -Name 'target_transport_decision_epoch' -Default -1) -ne
                $targetEpoch -or
            (Get-FileTransferEventInt64Field -Event $Event -Name 'target_transport_decision_bridge_recovery_generation' -Default -2) -ne
                $targetBridgeGeneration -or
            (Get-FileTransferEventInt64Field -Event $Event -Name 'checkpoint_generation' -Default -1) -lt 0 -or
            $checkpointLeaseGeneration -lt 0 -or
            $dataSessionIdentity -eq '(none)') {
            return $false
        }

        if ($checkpointLeaseGeneration -eq 0) {
            return $checkpointLeaseState -eq '(none)' -and
                $checkpointLeaseRequestId -eq '(none)' -and
                $checkpointLeaseReason -eq '(none)'
        }

        return $checkpointLeaseState -ne '(none)' -and
            $checkpointLeaseRequestId -eq $checkpointRequestId -and
            $checkpointLeaseReason -ne '(none)'
    }

    function Test-FallbackTailAggregateReauthorizationPredecessorTuple {
        param(
            [Parameter(Mandatory = $true)]$Yield,
            [Parameter(Mandatory = $true)]$Reauthorization
        )

        foreach ($fields in @(
                [pscustomobject]@{ Yield = 'authority_id'; Evidence = 'predecessor_authority_id' },
                [pscustomobject]@{ Yield = 'yield_generation'; Evidence = 'predecessor_yield_generation' },
                [pscustomobject]@{ Yield = 'owner_key'; Evidence = 'source_owner_key' },
                [pscustomobject]@{ Yield = 'pair_key'; Evidence = 'source_pair_key' },
                [pscustomobject]@{ Yield = 'route_publication_generation'; Evidence = 'source_route_publication_generation' },
                [pscustomobject]@{ Yield = 'route_commit_generation'; Evidence = 'source_route_commit_generation' },
                [pscustomobject]@{ Yield = 'protocol_version'; Evidence = 'predecessor_protocol_version' },
                [pscustomobject]@{ Yield = 'live_route_epoch'; Evidence = 'predecessor_live_route_epoch' },
                [pscustomobject]@{ Yield = 'runtime_generation'; Evidence = 'source_runtime_generation' },
                [pscustomobject]@{ Yield = 'runtime_generation'; Evidence = 'predecessor_runtime_generation' },
                [pscustomobject]@{ Yield = 'terminal_generation'; Evidence = 'predecessor_terminal_generation' },
                [pscustomobject]@{ Yield = 'leg_generation'; Evidence = 'predecessor_leg_generation' },
                [pscustomobject]@{ Yield = 'bridge_recovery_generation'; Evidence = 'predecessor_bridge_recovery_generation' },
                [pscustomobject]@{ Yield = 'transport_epoch'; Evidence = 'source_transport_epoch' },
                [pscustomobject]@{ Yield = 'checkpoint_request_id'; Evidence = 'predecessor_checkpoint_request_id' })) {
            $yieldValue = Get-FileTransferEventField `
                -Event $Yield `
                -Name $fields.Yield `
                -Default '__missing__'
            $reauthorizationValue = Get-FileTransferEventField `
                -Event $Reauthorization `
                -Name $fields.Evidence `
                -Default '__missing__'
            if ($yieldValue -eq '__missing__' -or
                $reauthorizationValue -eq '__missing__' -or
                -not [string]::Equals(
                    $yieldValue,
                    $reauthorizationValue,
                    [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $yieldRoute = Get-FileTransferEventField -Event $Yield -Name 'route' -Default ''
        $predecessorRoute = Get-FileTransferEventField `
            -Event $Reauthorization `
            -Name 'predecessor_route' `
            -Default ''
        return $yieldRoute -eq 'post_tuna_fallback_v6' -and
            $predecessorRoute -in @('2', 'PostTunaFallbackV6', 'post_tuna_fallback_v6')
    }

    function Test-FallbackTailAggregateReauthorizationSuccessorTuple {
        param(
            [Parameter(Mandatory = $true)]$Successor,
            [Parameter(Mandatory = $true)]$Yield
        )

        foreach ($fields in @(
                [pscustomobject]@{ Yield = 'authority_id'; Evidence = 'successor_authority_id' },
                [pscustomobject]@{ Yield = 'predecessor_authority_id'; Evidence = 'predecessor_authority_id' },
                [pscustomobject]@{ Yield = 'yield_generation'; Evidence = 'successor_yield_generation' },
                [pscustomobject]@{ Yield = 'owner_key'; Evidence = 'target_owner_key' },
                [pscustomobject]@{ Yield = 'owner_key'; Evidence = 'successor_owner_key' },
                [pscustomobject]@{ Yield = 'pair_key'; Evidence = 'target_pair_key' },
                [pscustomobject]@{ Yield = 'pair_key'; Evidence = 'successor_pair_key' },
                [pscustomobject]@{ Yield = 'route_publication_generation'; Evidence = 'route_publication_generation' },
                [pscustomobject]@{ Yield = 'route_commit_generation'; Evidence = 'route_commit_generation' },
                [pscustomobject]@{ Yield = 'protocol_version'; Evidence = 'successor_protocol_version' },
                [pscustomobject]@{ Yield = 'live_route_epoch'; Evidence = 'successor_live_route_epoch' },
                [pscustomobject]@{ Yield = 'runtime_generation'; Evidence = 'target_runtime_generation' },
                [pscustomobject]@{ Yield = 'runtime_generation'; Evidence = 'successor_runtime_generation' },
                [pscustomobject]@{ Yield = 'terminal_generation'; Evidence = 'terminal_generation' },
                [pscustomobject]@{ Yield = 'terminal_generation'; Evidence = 'successor_terminal_generation' },
                [pscustomobject]@{ Yield = 'leg_generation'; Evidence = 'leg_generation' },
                [pscustomobject]@{ Yield = 'leg_generation'; Evidence = 'successor_leg_generation' },
                [pscustomobject]@{ Yield = 'bridge_recovery_generation'; Evidence = 'bridge_recovery_generation' },
                [pscustomobject]@{ Yield = 'bridge_recovery_generation'; Evidence = 'successor_bridge_recovery_generation' },
                [pscustomobject]@{ Yield = 'transport_epoch'; Evidence = 'target_transport_epoch' },
                [pscustomobject]@{ Yield = 'checkpoint_generation'; Evidence = 'checkpoint_generation' },
                [pscustomobject]@{ Yield = 'checkpoint_request_id'; Evidence = 'checkpoint_request_id' },
                [pscustomobject]@{ Yield = 'checkpoint_request_id'; Evidence = 'successor_checkpoint_request_id' },
                [pscustomobject]@{ Yield = 'data_session_identity'; Evidence = 'data_session_identity' },
                [pscustomobject]@{ Yield = 'data_session_generation'; Evidence = 'data_session_generation' })) {
            $yieldValue = Get-FileTransferEventField `
                -Event $Yield `
                -Name $fields.Yield `
                -Default '__missing__'
            $successorValue = Get-FileTransferEventField `
                -Event $Successor `
                -Name $fields.Evidence `
                -Default '__missing__'
            if ($yieldValue -eq '__missing__' -or
                $successorValue -eq '__missing__' -or
                -not [string]::Equals(
                    $yieldValue,
                    $successorValue,
                    [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $yieldRoute = Get-FileTransferEventField -Event $Yield -Name 'route' -Default ''
        $successorRoute = Get-FileTransferEventField `
            -Event $Successor `
            -Name 'successor_route' `
            -Default ''
        return $yieldRoute -eq 'post_tuna_fallback_v6' -and
            $successorRoute -in @('2', 'PostTunaFallbackV6', 'post_tuna_fallback_v6')
    }

    foreach ($successor in $reauthorizationSuccessorEvents) {
        $successorAuthorityId = Get-FallbackTailAggregateField `
            -Event $successor `
            -Names @('successor_authority_id', 'authority_id') `
            -Default ''
        $predecessorAuthorityId = Get-FileTransferEventField `
            -Event $successor `
            -Name 'predecessor_authority_id' `
            -Default ''
        $targetEpoch = Get-FileTransferEventInt64Field `
            -Event $successor `
            -Name 'target_transport_epoch' `
            -Default (Get-FileTransferEventInt64Field -Event $successor -Name 'transport_epoch' -Default 0)
        $sourceEpoch = Get-FileTransferEventInt64Field `
            -Event $successor `
            -Name 'source_transport_epoch' `
            -Default 0
        $reauthorizationGeneration = Get-FileTransferEventInt64Field `
            -Event $successor `
            -Name 'reauthorization_generation' `
            -Default 0
        [object[]]$matchingDescriptors = @($descriptorEvents | Where-Object {
            (Test-FallbackTailAggregateBefore -Earlier $_ -Later $successor) -and
            (Test-FallbackTailAggregateReauthorizationDescriptorShape -Event $_) -and
            (Test-FallbackTailAggregateReauthorizationDescriptorShape -Event $successor) -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in
                @('Accepted', 'Idempotent', 'accepted', 'idempotent') -and
            (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq
                (Get-FileTransferEventField -Event $successor -Name 'session_id' -Default '') -and
            (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq
                (Get-FileTransferEventField -Event $successor -Name 'transfer_id' -Default '') -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq
                (Get-FileTransferEventField -Event $successor -Name 'direction' -Default '') -and
            (Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '') -eq
                $predecessorAuthorityId -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'reauthorization_generation' -Default 0) -eq
                $reauthorizationGeneration -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'target_transport_epoch' -Default 0) -eq
                $targetEpoch -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'source_transport_epoch' -Default 0) -eq
                $sourceEpoch -and
            (Get-FileTransferEventField -Event $_ -Name 'source_owner_key' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'source_owner_key' -Default '__missing__') -and
            (Get-FileTransferEventField -Event $_ -Name 'source_pair_key' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'source_pair_key' -Default '__missing__') -and
            (Get-FileTransferEventField -Event $_ -Name 'target_owner_key' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'target_owner_key' -Default '__missing__') -and
            (Get-FileTransferEventField -Event $_ -Name 'target_pair_key' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'target_pair_key' -Default '__missing__') -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'source_runtime_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'source_runtime_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'source_route_publication_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'source_route_publication_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'source_route_commit_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'source_route_commit_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'predecessor_yield_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'predecessor_yield_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'predecessor_route' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'predecessor_route' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'predecessor_protocol_version' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'predecessor_protocol_version' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'predecessor_live_route_epoch' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'predecessor_live_route_epoch' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'predecessor_runtime_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'predecessor_runtime_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'predecessor_terminal_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'predecessor_terminal_generation' -Default -1) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'predecessor_leg_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'predecessor_leg_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'predecessor_bridge_recovery_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'predecessor_bridge_recovery_generation' -Default -1) -and
            (Get-FileTransferEventField -Event $_ -Name 'predecessor_checkpoint_request_id' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'predecessor_checkpoint_request_id' -Default '__missing__') -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'target_runtime_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'target_runtime_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'terminal_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'terminal_generation' -Default -1) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'leg_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_recovery_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'bridge_recovery_generation' -Default -1) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_decision_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'bridge_decision_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'target_transport_decision_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'target_transport_decision_generation' -Default 0) -and
            (Get-FileTransferEventField -Event $_ -Name 'target_transport_decision_action' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'target_transport_decision_action' -Default '__missing__') -and
            (Get-FileTransferEventField -Event $_ -Name 'target_transport_decision_reason' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'target_transport_decision_reason' -Default '__missing__') -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'target_transport_decision_epoch' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'target_transport_decision_epoch' -Default -1) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'target_transport_decision_bridge_recovery_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'target_transport_decision_bridge_recovery_generation' -Default -1) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'route_publication_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'route_publication_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'route_commit_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'route_commit_generation' -Default 0) -and
            (Get-FileTransferEventField -Event $_ -Name 'checkpoint_request_id' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'checkpoint_request_id' -Default '__missing__') -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'checkpoint_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'checkpoint_generation' -Default -1) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'checkpoint_lease_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'checkpoint_lease_generation' -Default -1) -and
            (Get-FileTransferEventField -Event $_ -Name 'checkpoint_lease_state' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'checkpoint_lease_state' -Default '__missing__') -and
            (Get-FileTransferEventField -Event $_ -Name 'checkpoint_lease_request_id' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'checkpoint_lease_request_id' -Default '__missing__') -and
            (Get-FileTransferEventField -Event $_ -Name 'checkpoint_lease_reason' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'checkpoint_lease_reason' -Default '__missing__') -and
            (Get-FileTransferEventField -Event $_ -Name 'data_session_identity' -Default '__missing__') -eq
                (Get-FileTransferEventField -Event $successor -Name 'data_session_identity' -Default '__missing__') -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'data_session_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $successor -Name 'data_session_generation' -Default 0)
        } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
        [object[]]$matchingPredecessorYields = @($yieldEvents | Where-Object {
            (Test-FallbackTailAggregateBefore -Earlier $_ -Later $successor) -and
            (Test-FallbackTailAggregateYieldShape -Event $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq
                (Get-FileTransferEventField -Event $successor -Name 'session_id' -Default '') -and
            (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq
                (Get-FileTransferEventField -Event $successor -Name 'transfer_id' -Default '') -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq
                (Get-FileTransferEventField -Event $successor -Name 'direction' -Default '') -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq
                $predecessorAuthorityId -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'transport_epoch' -Default 0) -eq
                $sourceEpoch -and
            (Test-FallbackTailAggregateReauthorizationPredecessorTuple `
                -Yield $_ `
                -Reauthorization $successor)
        } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
        [object[]]$matchingSuccessorYields = @($yieldEvents | Where-Object {
            (Test-FallbackTailAggregateBefore -Earlier $_ -Later $successor) -and
            (Test-FallbackTailAggregateYieldShape -Event $_) -and
            (Test-FallbackTailAggregateReauthorizationSuccessorTuple `
                -Successor $successor `
                -Yield $_)
        } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
        [object[]]$matchingPairing = @()
        if ($matchingSuccessorYields.Count -eq 1) {
            $successorYield = $matchingSuccessorYields[0]
            $matchingPairing = @($validPairingEvents | Where-Object {
                (Test-FallbackTailAggregateBefore -Earlier $successor -Later $_) -and
                (Test-FallbackTailAggregateLocalTuple `
                    -Anchor $_ `
                    -Candidate $successorYield)
            } | Select-Object -First 1)
        }
        if ((Test-FallbackTailAggregateAccepted -Event $successor) -and
            -not [string]::IsNullOrWhiteSpace($successorAuthorityId) -and
            $successorAuthorityId -notin @('(none)', 'none') -and
            -not [string]::IsNullOrWhiteSpace($predecessorAuthorityId) -and
            $predecessorAuthorityId -notin @('(none)', 'none') -and
            $successorAuthorityId -ne $predecessorAuthorityId -and
            $sourceEpoch -gt 0 -and
            $targetEpoch -gt $sourceEpoch -and
            $reauthorizationGeneration -gt 0 -and
            $matchingPredecessorYields.Count -eq 1 -and
            $matchingDescriptors.Count -eq 1 -and
            $matchingSuccessorYields.Count -eq 1 -and
            $matchingPairing.Count -eq 1) {
            $validReauthorizationSuccessors.Add($successor) | Out-Null
        }
        else {
            $invalidReauthorizationSuccessors.Add($successor) | Out-Null
        }
    }

    $reauthorizationLineages = @{}
    $deduplicatedValidReauthorizationSuccessors =
        New-Object System.Collections.Generic.List[object]
    foreach ($successor in @(
            $validReauthorizationSuccessors.ToArray() |
                Sort-Object Sequence, LineNumber)) {
        $lineageKey = (@(
                'session_id',
                'transfer_id',
                'direction',
                'predecessor_authority_id',
                'source_transport_epoch',
                'source_owner_key',
                'source_pair_key') | ForEach-Object {
                Get-FileTransferEventField `
                    -Event $successor `
                    -Name $_ `
                    -Default '(missing)'
            }) -join '|'
        $successorIdentity = '{0}|{1}' -f
            (Get-FallbackTailAggregateField `
                -Event $successor `
                -Names @('successor_authority_id', 'authority_id') `
                -Default '(missing)'),
            (Get-FileTransferEventInt64Field `
                -Event $successor `
                -Name 'target_transport_epoch' `
                -Default 0)
        if (-not $reauthorizationLineages.ContainsKey($lineageKey)) {
            $reauthorizationLineages[$lineageKey] = $successorIdentity
            $deduplicatedValidReauthorizationSuccessors.Add($successor) | Out-Null
            continue
        }

        if ($reauthorizationLineages[$lineageKey] -ne $successorIdentity) {
            # Once a successor is issued, a later epoch must name that successor as
            # its predecessor. A second distinct successor on the original lineage
            # is an invented intermediate authority, not idempotent evidence.
            $invalidReauthorizationSuccessors.Add($successor) | Out-Null
        }
    }
    [object[]]$validReauthorizationSuccessorEvents =
        @($deduplicatedValidReauthorizationSuccessors.ToArray())

    [object[]]$invalidEvents = @(
        @(
            $invalidPairingEvents +
            $invalidCarryForwardEvents +
            $invalidReservationEvents +
            $unconsumedReservationEvents +
            $invalidConsumptionEvents +
            $invalidReauthorizationSuccessors.ToArray()) |
            Sort-Object Sequence, LineNumber -Unique)
    $authoritativeEventCount =
        $yieldEvents.Count +
        $localReceiptEvents.Count +
        $peerReceiptEvents.Count +
        $pairingEvents.Count +
        $reservationEvents.Count +
        $consumptionEvents.Count +
        $carryForwardEvents.Count +
        $reauthorizationStagedEvents.Count +
        $reauthorizationReboundEvents.Count +
        $reauthorizationSuccessorEvents.Count +
        $reauthorizationInvalidatedEvents.Count
    $verdict = if ($invalidEvents.Count -gt 0) {
        'fail'
    }
    elseif ($validConsumptionEvents.Count -gt 0 -or
        $validPairingEvents.Count -gt 0 -or
        $validReauthorizationSuccessors.Count -gt 0) {
        'pass'
    }
    elseif ($authoritativeEventCount -gt 0) {
        'pending'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        Verdict = $verdict
        AuthoritativeEventCount = $authoritativeEventCount
        YieldIssuedCount = $yieldEvents.Count
        LocalProofReceiptDecidedCount = $localReceiptEvents.Count
        PeerProofReceiptDecidedCount = $peerReceiptEvents.Count
        PairingCommittedCount = $pairingEvents.Count
        ValidPairingCount = $validPairingEvents.Count
        PairedReleaseReservedCount = $reservationEvents.Count
        ValidPairedReleaseReservedCount = $validReservationEvents.Count
        PairedReleaseConsumedCount = $consumptionEvents.Count
        ValidPairedReleaseConsumedCount = $validConsumptionEvents.Count
        PairedReleaseCarryForwardCount = $carryForwardEvents.Count
        ValidPairedReleaseCarryForwardCount = $validCarryForwardEvents.Count
        InvalidRawCount = [int]$pairingInvalidRawCount +
            [int]$carryForwardInvalidRawCount +
            [int]$reservationInvalidRawCount +
            $unconsumedReservationEvents.Count +
            [int]$consumptionInvalidRawCount +
            $invalidReauthorizationSuccessors.Count
        InvalidDistinctCount = $invalidEvents.Count +
            $pairingRecoveredCount +
            $carryForwardRecoveredCount +
            $reservationRecoveredCount +
            $consumptionRecoveredCount
        InvalidRecoveredCount = $pairingRecoveredCount +
            $carryForwardRecoveredCount +
            $reservationRecoveredCount +
            $consumptionRecoveredCount
        InvalidUnresolvedCount = $invalidEvents.Count
        InvalidEvents = $invalidEvents
        ValidPairingEvents = $validPairingEvents
        ValidPairingEvidence = @($validPairingEvidence.ToArray())
        ValidReservationEvents = $validReservationEvents
        ValidConsumptionEvents = $validConsumptionEvents
        ValidCarryForwardEvents = $validCarryForwardEvents
        ReauthorizationStagedCount = $reauthorizationStagedEvents.Count
        ReauthorizationReboundCount = $reauthorizationReboundEvents.Count
        ReauthorizationSuccessorIssuedCount = $reauthorizationSuccessorEvents.Count
        ReauthorizationInvalidatedCount = $reauthorizationInvalidatedEvents.Count
        ValidReauthorizationSuccessorEvents = $validReauthorizationSuccessorEvents
    }
}

function Get-FileTransferFallbackTailYieldAuthorityRejectionEvents {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [string[]]$rejectionReasons = @(
        'legacy_authority_missing',
        'authority_malformed',
        'authority_tuple_mismatch',
        'predecessor_mismatch',
        'late_predecessor',
        'peer_yield_authority_invalid',
        'peer_yield_authority_tuple_mismatch',
        'peer_yield_authority_predecessor_mismatch',
        'peer_yield_generation_regressed')
    return @($Events | Where-Object {
            $_.EventName -eq 'filetransfer_fallback_tail_yield_local_authority_rejected' -or
            ($_.EventName -eq 'filetransfer_fallback_tail_yield_proof_stale_ignored' -and
                $rejectionReasons -contains (Get-FileTransferEventField -Event $_ -Name 'reason' -Default ''))
        })
}

function Get-FileTransferFallbackTailBridgeRecoveryPairingProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$events = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$mismatchEvents = @(
        $events |
            Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_owner_generation_mismatch' }
    )
    [object[]]$routePublicationEvents = @(
        $events |
            Where-Object {
                 $_.EventName -in @(
                     'filetransfer_route_selected',
                     'filetransfer_route_transitioned',
                     'filetransfer_live_route_epoch_started',
                     'filetransfer_live_route_epoch_recovered',
                     'filetransfer_route_hint_authorized_publication_accepted',
                     'filetransfer_runtime_started')
            }
    )
    [object[]]$fallbackLegAuthorityEvents = @(
        $events |
            Where-Object {
                $_.EventName -in @(
                     'filetransfer_fallback_leg_authority_started',
                     'filetransfer_fallback_leg_transport_epoch_adopted',
                     'filetransfer_fallback_leg_authority_completed',
                     'filetransfer_fallback_leg_authority_superseded_by_route_hint',
                     'filetransfer_leg_frozen',
                     'filetransfer_fallback_tail_terminal_proof_consumed')
            }
    )
    [object[]]$transferTerminalEvents = @(
        $events |
            Where-Object {
                $_.EventName -in @(
                    'transfer_terminal',
                    'file_transfer_inbound_terminal',
                    'file_transfer_outbound_terminal')
            })
    [object[]]$quiescentYieldEvents = @(
        $events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_quiescent_yield_granted' }
    )
    [object[]]$yieldProofSentEvents = @(
        $events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_yield_proof_sent' }
    )
    [object[]]$yieldProofReceivedEvents = @(
        $events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_yield_proof_received' }
    )
    [object[]]$pairedYieldEvents = @(
        $events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_paired_yield_granted' }
    )
    [object[]]$terminalProofEvents = @(
        $events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_terminal_proof_consumed' }
    )
    $pairedYieldValidation = Get-FileTransferFallbackTailPairedYieldValidation -Events $events

    function ConvertTo-FallbackTailPairingValue {
        param([AllowEmptyString()][string]$Value)

        if ([string]::IsNullOrWhiteSpace($Value) -or $Value -in @('none', '(none)')) {
            return '(none)'
        }

        return $Value
    }

    function Test-FallbackTailPairingScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate,
            [switch]$RequireDirection
        )

        foreach ($fieldName in @('transfer_id', 'session_id')) {
            $anchorValue = ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $Anchor -Name $fieldName -Default '')
            $candidateValue = ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $Candidate -Name $fieldName -Default '')
            if ($anchorValue -eq '(none)' -or
                $candidateValue -eq '(none)' -or
                -not [string]::Equals($anchorValue, $candidateValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        if ($RequireDirection) {
            $anchorDirection = ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $Anchor -Name 'direction' -Default '')
            $candidateDirection = ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default '')
            if ($anchorDirection -eq '(none)' -or
                -not [string]::Equals($anchorDirection, $candidateDirection, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailTerminalProofShape {
        param([Parameter(Mandatory = $true)]$Event)

        $direction = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'direction' -Default '')
        $transferId = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'transfer_id' -Default '')
        $sessionId = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'session_id' -Default '')
        $reason = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'reason' -Default '')
        $committedChunk = Get-FileTransferEventInt64Field `
            -Event $Event `
            -Name 'committed_chunk' `
            -Default -1
        $chunkCount = Get-FileTransferEventInt64Field `
            -Event $Event `
            -Name 'chunk_count' `
            -Default 0

        return $direction -in @('inbound', 'outbound') -and
            $transferId -ne '(none)' -and
            $sessionId -ne '(none)' -and
            (Get-FileTransferEventField -Event $Event -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'protocol_version' -Default 0) -eq 6 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'live_route_epoch' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'leg_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Event -Name 'transport_epoch' -Default -1) -ge 0 -and
            $committedChunk -ge 0 -and
            $chunkCount -gt 0 -and
            $reason -ne '(none)'
    }

    function Test-FallbackTailTerminalProofMatchesMismatch {
        param(
            [Parameter(Mandatory = $true)]$Mismatch,
            [Parameter(Mandatory = $true)]$TerminalProof
        )

        if (-not (Test-FallbackTailTerminalProofShape -Event $TerminalProof) -or
            [int64]$TerminalProof.Sequence -le [int64]$Mismatch.Sequence -or
            -not (Test-FallbackTailPairingScopeMatch `
                -Anchor $Mismatch `
                -Candidate $TerminalProof `
                -RequireDirection) -or
            (Get-FileTransferEventInt64Field -Event $TerminalProof -Name 'live_route_epoch' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'live_route_epoch' -Default 0) -or
            (Get-FileTransferEventInt64Field -Event $TerminalProof -Name 'leg_generation' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'leg_generation' -Default 0) -or
            (Get-FileTransferEventInt64Field -Event $TerminalProof -Name 'transport_epoch' -Default -1) -ne
                (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'transport_epoch' -Default -1)) {
            return $false
        }

        $mismatchLegId = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Mismatch -Name 'leg_id' -Default '')
        $terminalLegId = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $TerminalProof -Name 'leg_id' -Default '')
        return $mismatchLegId -eq '(none)' -or
            $terminalLegId -eq '(none)' -or
            [string]::Equals($mismatchLegId, $terminalLegId, [System.StringComparison]::Ordinal)
    }

    function Test-FallbackTailPreciseBridgeRecoveryMismatch {
        param([Parameter(Mandatory = $true)]$Event)

        $direction = Get-FileTransferEventField -Event $Event -Name 'direction' -Default ''
        $peerDirection = Get-FileTransferEventField -Event $Event -Name 'peer_direction' -Default ''
        $expectedPeerDirection = if ($direction -eq 'inbound') { 'outbound' } elseif ($direction -eq 'outbound') { 'inbound' } else { '(invalid)' }
        if ((Get-FileTransferEventField -Event $Event -Name 'route' -Default '') -ne 'post_tuna_fallback_v6' -or
            (Get-FileTransferEventInt64Field -Event $Event -Name 'protocol_version' -Default 0) -ne 6 -or
            $expectedPeerDirection -eq '(invalid)' -or
            -not [string]::Equals(
                $expectedPeerDirection,
                $peerDirection,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        $liveRouteEpoch = Get-FileTransferEventInt64Field -Event $Event -Name 'live_route_epoch' -Default 0
        $peerLiveRouteEpoch = Get-FileTransferEventInt64Field -Event $Event -Name 'peer_live_route_epoch' -Default 0
        $transportEpoch = Get-FileTransferEventInt64Field -Event $Event -Name 'transport_epoch' -Default -1
        $peerTransportEpoch = Get-FileTransferEventInt64Field -Event $Event -Name 'peer_transport_epoch' -Default -1
        $bridgeGeneration = Get-FileTransferEventInt64Field -Event $Event -Name 'bridge_recovery_generation' -Default 0
        $peerBridgeGeneration = Get-FileTransferEventInt64Field -Event $Event -Name 'peer_bridge_recovery_generation' -Default 0
        $yieldGeneration = Get-FileTransferEventInt64Field -Event $Event -Name 'yield_generation' -Default 0
        if ($liveRouteEpoch -le 0 -or
            $peerLiveRouteEpoch -ne $liveRouteEpoch -or
            $transportEpoch -lt 0 -or
            $peerTransportEpoch -ne $transportEpoch -or
            $bridgeGeneration -le 0 -or
            $peerBridgeGeneration -le 0 -or
            $peerBridgeGeneration -eq $bridgeGeneration -or
            $yieldGeneration -le 0) {
            return $false
        }

        $mismatchKind = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'mismatch_kind' -Default '')
        $decisionReason = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'decision_reason' -Default '')
        $authoritySchema = Get-FileTransferAuthoritySchema -Line ([string]$Event.RawLine)
        if (($authoritySchema -ge 2 -and
                ($mismatchKind -ne 'bridge_recovery_generation' -or
                    $decisionReason -ne 'bridge_recovery_generation_mismatch')) -or
            ($authoritySchema -lt 2 -and
                (($mismatchKind -ne '(none)' -and $mismatchKind -ne 'bridge_recovery_generation') -or
                    ($decisionReason -ne '(none)' -and $decisionReason -ne 'bridge_recovery_generation_mismatch')))) {
            return $false
        }

        $checkpoint = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'checkpoint_request_id' -Default '')
        $peerCheckpoint = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'peer_checkpoint_request_id' -Default '')
        if (-not [string]::Equals($checkpoint, $peerCheckpoint, [System.StringComparison]::Ordinal)) {
            return $false
        }

        $expectedPairKey = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'expected_pair_key' -Default '')
        $peerPairKey = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Event -Name 'peer_pair_key' -Default '')
        if ($expectedPairKey -eq '(none)' -or
            $peerPairKey -eq '(none)' -or
            -not (Test-FileTransferFallbackTailOwnerKeyMatchesEvent `
                -Event $Event `
                -OwnerKeyField 'expected_owner_key') -or
            -not (Test-FileTransferFallbackTailOwnerKeyMatchesEvent `
                -Event $Event `
                -OwnerKeyField 'peer_owner_key' `
                -Peer)) {
            return $false
        }

        $expectedPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
            -PairKey $expectedPairKey `
            -OwnerKey (Get-FileTransferEventField -Event $Event -Name 'expected_owner_key' -Default '') `
            -BridgeRecoveryGeneration $bridgeGeneration
        $peerPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
            -PairKey $peerPairKey `
            -OwnerKey (Get-FileTransferEventField -Event $Event -Name 'peer_owner_key' -Default '') `
            -BridgeRecoveryGeneration $peerBridgeGeneration
        $expectedSharedPairKey = Get-FileTransferFallbackTailSharedPairKeyForEvent -Event $Event
        $peerSharedPairKey = Get-FileTransferFallbackTailSharedPairKeyForEvent -Event $Event -Peer
        return $expectedPairEvidence.Valid -and
            $peerPairEvidence.Valid -and
            $expectedPairEvidence.Format -eq 'legacy_bridge_scoped_8' -and
            $peerPairEvidence.Format -eq 'legacy_bridge_scoped_8' -and
            $expectedSharedPairKey -ne '(invalid)' -and
            $peerSharedPairKey -ne '(invalid)' -and
            [string]::Equals($expectedSharedPairKey, $peerSharedPairKey, [System.StringComparison]::Ordinal) -and
            [string]::Equals(
                [string]$expectedPairEvidence.CanonicalPairKey,
                $expectedSharedPairKey,
                [System.StringComparison]::Ordinal) -and
            [string]::Equals(
                [string]$peerPairEvidence.CanonicalPairKey,
                $peerSharedPairKey,
                [System.StringComparison]::Ordinal)
    }

    function Get-FallbackTailCurrentRoutePublicationState {
        param([Parameter(Mandatory = $true)]$Mismatch)

        $mismatchSequence = [int64]$Mismatch.Sequence
        $runtimeGeneration = Get-FileTransferEventInt64Field -Event $Mismatch -Name 'runtime_generation' -Default 0
        [object[]]$scopedPublications = @(
            $routePublicationEvents |
                Where-Object {
                    [int64]$_.Sequence -lt $mismatchSequence -and
                    (Test-FallbackTailPairingScopeMatch -Anchor $Mismatch -Candidate $_ -RequireDirection)
                }
        )
        if ($scopedPublications.Count -eq 0) {
            return [pscustomobject]@{ Status = 'missing'; Event = $null }
        }

        $maxPublicationGeneration = 0L
        foreach ($candidate in $scopedPublications) {
            $candidateGeneration = Get-FileTransferEventInt64Field `
                -Event $candidate `
                -Name 'route_publication_generation' `
                -Default 0
            if ($candidateGeneration -gt $maxPublicationGeneration) {
                $maxPublicationGeneration = $candidateGeneration
            }
        }
        if ($maxPublicationGeneration -le 0) {
            return [pscustomobject]@{ Status = 'missing'; Event = $null }
        }

        [object[]]$completeCurrentGenerationPublications = @(
            $scopedPublications |
                Where-Object {
                    $candidate = $_
                    $actionKind = Get-FileTransferEventField `
                        -Event $candidate `
                        -Name 'route_publication_action_kind' `
                        -Default ''
                    (Get-FileTransferEventInt64Field `
                        -Event $candidate `
                        -Name 'route_publication_generation' `
                        -Default 0) -eq $maxPublicationGeneration -and
                    (Get-FileTransferEventInt64Field -Event $candidate -Name 'runtime_generation' -Default 0) -gt 0 -and
                    (Get-FileTransferEventInt64Field -Event $candidate -Name 'terminal_generation' -Default -1) -ge 0 -and
                    (Get-FileTransferEventInt64Field -Event $candidate -Name 'leg_generation' -Default 0) -gt 0 -and
                    -not [string]::IsNullOrWhiteSpace(
                        (Get-FileTransferEventField -Event $candidate -Name 'route' -Default '')) -and
                    (Get-FileTransferEventInt64Field -Event $candidate -Name 'protocol_version' -Default 0) -gt 0 -and
                    -not [string]::IsNullOrWhiteSpace(
                        (Get-FileTransferEventField -Event $candidate -Name 'target_route' -Default '')) -and
                    (Get-FileTransferEventInt64Field -Event $candidate -Name 'target_protocol_version' -Default 0) -gt 0 -and
                    -not [string]::IsNullOrWhiteSpace(
                        (Get-FileTransferEventField -Event $candidate -Name 'target_transport' -Default '')) -and
                    $actionKind -in @('RoutePublication', 'RouteCommitPublication') -and
                    ($actionKind -ne 'RouteCommitPublication' -or
                        (Get-FileTransferEventInt64Field `
                            -Event $candidate `
                            -Name 'route_commit_generation' `
                            -Default 0) -gt 0) -and
                    (Get-FileTransferEventField `
                        -Event $candidate `
                        -Name 'coordinator_decision_reason' `
                        -Default '') -eq 'accepted'
                })
        if ($completeCurrentGenerationPublications.Count -eq 0) {
            return [pscustomobject]@{ Status = 'missing'; Event = $null }
        }

        [object[]]$preferredPublications = @(
            $completeCurrentGenerationPublications |
                Where-Object { $_.EventName -eq 'filetransfer_route_selected' } |
                Sort-Object Sequence -Descending |
                Select-Object -First 1)
        if ($preferredPublications.Count -eq 0) {
            [object[]]$preferredPublications = @(
                $completeCurrentGenerationPublications |
                    Where-Object { $_.EventName -eq 'filetransfer_route_hint_authorized_publication_accepted' } |
                    Sort-Object Sequence -Descending |
                    Select-Object -First 1)
        }
        if ($preferredPublications.Count -eq 0) {
            [object[]]$preferredPublications = @(
                $completeCurrentGenerationPublications |
                    Sort-Object Sequence -Descending |
                    Select-Object -First 1)
        }

        $latest = $preferredPublications[0]
        $isCurrent = (Get-FileTransferEventField -Event $latest -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'protocol_version' -Default 0) -eq 6 -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'live_route_epoch' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'live_route_epoch' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'leg_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'leg_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'route_publication_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'runtime_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'terminal_generation' -Default -1) -ge 0 -and
            ($runtimeGeneration -le 0 -or
                (Get-FileTransferEventInt64Field -Event $latest -Name 'runtime_generation' -Default 0) -eq $runtimeGeneration) -and
            (Get-FileTransferEventField -Event $latest -Name 'target_route' -Default '') -eq 'post_tuna_fallback_v6' -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'target_protocol_version' -Default 0) -eq 6 -and
            (Get-FileTransferEventField -Event $latest -Name 'target_transport' -Default '') -eq 'regular_nkn' -and
            (Get-FileTransferEventField -Event $latest -Name 'route_publication_action_kind' -Default '') -eq 'RoutePublication' -and
            (Get-FileTransferEventField -Event $latest -Name 'coordinator_decision_reason' -Default '') -eq 'accepted'
        return [pscustomobject]@{
            Status = if ($isCurrent) { 'current' } else { 'stale' }
            Event = $latest
        }
    }

    function Get-FallbackTailCurrentLegAuthorityState {
        param([Parameter(Mandatory = $true)]$Mismatch)

        $mismatchSequence = [int64]$Mismatch.Sequence
        $checkpoint = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Mismatch -Name 'checkpoint_request_id' -Default '')
        [object[]]$priorTerminals = @(
            $transferTerminalEvents |
                Where-Object {
                    [int64]$_.Sequence -lt $mismatchSequence -and
                    (Test-FallbackTailPairingScopeMatch -Anchor $Mismatch -Candidate $_) -and
                    (
                        ($_.EventName -eq 'file_transfer_inbound_terminal' -and
                            (Get-FileTransferEventField -Event $Mismatch -Name 'direction' -Default '') -eq 'inbound') -or
                        ($_.EventName -eq 'file_transfer_outbound_terminal' -and
                            (Get-FileTransferEventField -Event $Mismatch -Name 'direction' -Default '') -eq 'outbound') -or
                        ($_.EventName -eq 'transfer_terminal' -and
                            [string]::Equals(
                                (Get-FileTransferEventField -Event $_ -Name 'direction' -Default ''),
                                (Get-FileTransferEventField -Event $Mismatch -Name 'direction' -Default ''),
                                [System.StringComparison]::OrdinalIgnoreCase))
                    )
                } |
                Sort-Object Sequence -Descending |
                Select-Object -First 1)
        if ($priorTerminals.Count -gt 0) {
            return [pscustomobject]@{ Status = 'stale'; Event = $priorTerminals[0] }
        }

        [object[]]$hardLegBarriers = @(
            $fallbackLegAuthorityEvents |
                Where-Object {
                    [int64]$_.Sequence -lt $mismatchSequence -and
                    $_.EventName -in @(
                        'filetransfer_fallback_leg_authority_superseded_by_route_hint',
                        'filetransfer_leg_frozen',
                        'filetransfer_fallback_tail_terminal_proof_consumed') -and
                    (Test-FallbackTailPairingScopeMatch -Anchor $Mismatch -Candidate $_ -RequireDirection) -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -eq
                        (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'leg_generation' -Default 0)
                } |
                Sort-Object Sequence -Descending |
                Select-Object -First 1)
        if ($hardLegBarriers.Count -gt 0) {
            return [pscustomobject]@{ Status = 'stale'; Event = $hardLegBarriers[0] }
        }

        [object[]]$scopedAuthorityMutations = @(
            $fallbackLegAuthorityEvents |
                Where-Object {
                    [int64]$_.Sequence -lt $mismatchSequence -and
                    (Test-FallbackTailPairingScopeMatch -Anchor $Mismatch -Candidate $_ -RequireDirection) -and
                    $_.EventName -in @(
                        'filetransfer_fallback_leg_authority_started',
                        'filetransfer_fallback_leg_transport_epoch_adopted')
                } |
                Sort-Object Sequence -Descending |
                Select-Object -First 1
        )
        if ($scopedAuthorityMutations.Count -eq 0) {
            return [pscustomobject]@{ Status = 'missing'; Event = $null }
        }

        $latest = $scopedAuthorityMutations[0]
        if ($latest.EventName -notin @(
                'filetransfer_fallback_leg_authority_started',
                'filetransfer_fallback_leg_transport_epoch_adopted')) {
            return [pscustomobject]@{ Status = 'stale'; Event = $latest }
        }

        $currentCheckpoint = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $latest -Name 'current_checkpoint_request_id' -Default (
                Get-FileTransferEventField -Event $latest -Name 'checkpoint_request_id' -Default ''))
        $isCurrent = (Get-FileTransferEventField -Event $latest -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'protocol_version' -Default 0) -eq 6 -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'live_route_epoch' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'live_route_epoch' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'leg_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'leg_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'transport_epoch' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'transport_epoch' -Default -1) -and
            (Get-FileTransferEventInt64Field -Event $latest -Name 'bridge_recovery_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'bridge_recovery_generation' -Default 0) -and
            $currentCheckpoint -eq $checkpoint
        [object[]]$corroboratingCompletion = @(
            $fallbackLegAuthorityEvents |
                Where-Object {
                    $_.EventName -eq 'filetransfer_fallback_leg_authority_completed' -and
                    [int64]$_.Sequence -gt [int64]$latest.Sequence -and
                    [int64]$_.Sequence -lt $mismatchSequence -and
                    (Test-FallbackTailPairingScopeMatch -Anchor $Mismatch -Candidate $_ -RequireDirection) -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'live_route_epoch' -Default 0) -eq
                        (Get-FileTransferEventInt64Field -Event $latest -Name 'live_route_epoch' -Default 0) -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -eq
                        (Get-FileTransferEventInt64Field -Event $latest -Name 'leg_generation' -Default 0) -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'transport_epoch' -Default -1) -eq
                        (Get-FileTransferEventInt64Field -Event $latest -Name 'transport_epoch' -Default -1) -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_recovery_generation' -Default 0) -eq
                        (Get-FileTransferEventInt64Field -Event $latest -Name 'bridge_recovery_generation' -Default 0)
                } |
                Sort-Object Sequence -Descending |
                Select-Object -First 1)
        return [pscustomobject]@{
            Status = if ($isCurrent) { 'current' } else { 'stale' }
            Event = $latest
            CorroboratingEvent = if ($corroboratingCompletion.Count -gt 0) {
                $corroboratingCompletion[0]
            }
            else {
                $null
            }
        }
    }

    function Find-FallbackTailMatchingSentProof {
        param([Parameter(Mandatory = $true)]$Mismatch)

        $mismatchSequence = [int64]$Mismatch.Sequence
        $peerDirection = Get-FileTransferEventField -Event $Mismatch -Name 'peer_direction' -Default ''
        $peerCheckpoint = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Mismatch -Name 'peer_checkpoint_request_id' -Default '')
        $peerOwnerKey = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $Mismatch -Name 'peer_owner_key' -Default '')
        $peerBridgeGeneration = Get-FileTransferEventInt64Field `
            -Event $Mismatch `
            -Name 'peer_bridge_recovery_generation' `
            -Default -1
        $peerPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
            -PairKey (Get-FileTransferEventField -Event $Mismatch -Name 'peer_pair_key' -Default '') `
            -OwnerKey $peerOwnerKey `
            -BridgeRecoveryGeneration $peerBridgeGeneration
        $mismatchAuthoritySchema = Get-FileTransferAuthoritySchema -Line ([string]$Mismatch.RawLine)
        $mismatchAuthorityIdRaw = Get-FileTransferEventField `
            -Event $Mismatch `
            -Name 'authority_id' `
            -Default '__missing__'
        $mismatchPredecessorIdRaw = Get-FileTransferEventField `
            -Event $Mismatch `
            -Name 'predecessor_authority_id' `
            -Default '__missing__'
        $mismatchAuthorityId = ConvertTo-FallbackTailPairingValue $mismatchAuthorityIdRaw
        $mismatchPredecessorId = ConvertTo-FallbackTailPairingValue $mismatchPredecessorIdRaw
        if ($mismatchAuthoritySchema -ge 2 -and
            ($mismatchAuthorityIdRaw -eq '__missing__' -or
                $mismatchPredecessorIdRaw -eq '__missing__' -or
                $mismatchAuthorityId -eq '(none)')) {
            return @()
        }

        return @(
            $yieldProofSentEvents |
                Where-Object {
                    $candidate = $_
                    $candidateDirection = Get-FileTransferEventField -Event $candidate -Name 'direction' -Default ''
                    $candidateCheckpoint = ConvertTo-FallbackTailPairingValue (
                        Get-FileTransferEventField -Event $candidate -Name 'checkpoint_request_id' -Default '')
                    $basicMatch = [int64]$candidate.Sequence -lt $mismatchSequence
                    $basicMatch = $basicMatch -and
                        (Test-FallbackTailPairingScopeMatch -Anchor $Mismatch -Candidate $candidate)
                    $basicMatch = $basicMatch -and
                        [string]::Equals(
                            $candidateDirection,
                            $peerDirection,
                            [System.StringComparison]::OrdinalIgnoreCase)
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferAuthoritySchema -Line ([string]$candidate.RawLine)) -ge 2
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferEventField -Event $candidate -Name 'route' -Default '') -eq 'post_tuna_fallback_v6'
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferEventInt64Field -Event $candidate -Name 'protocol_version' -Default 0) -eq 6
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferEventInt64Field -Event $candidate -Name 'live_route_epoch' -Default 0) -eq
                            (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'peer_live_route_epoch' -Default 0)
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferEventInt64Field -Event $candidate -Name 'leg_generation' -Default 0) -eq
                            (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'peer_leg_generation' -Default 0)
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferEventInt64Field -Event $candidate -Name 'transport_epoch' -Default -1) -eq
                            (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'peer_transport_epoch' -Default -1)
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferEventInt64Field -Event $candidate -Name 'bridge_recovery_generation' -Default 0) -eq
                            (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'peer_bridge_recovery_generation' -Default 0)
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferEventInt64Field -Event $candidate -Name 'yield_generation' -Default 0) -eq
                            (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'yield_generation' -Default 0)
                    $basicMatch = $basicMatch -and $candidateCheckpoint -eq $peerCheckpoint
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferEventInt64Field -Event $candidate -Name 'peer_visible_any' -Default 0) -gt 0
                    $basicMatch = $basicMatch -and
                        (Get-FileTransferEventInt64Field -Event $candidate -Name 'accepted_any' -Default 0) -gt 0
                    $basicMatch = $basicMatch -and
                        (Test-FileTransferFallbackTailOwnerKeyMatchesEvent `
                            -Event $candidate `
                            -OwnerKeyField 'owner_key')
                    if (-not $basicMatch) {
                        return $false
                    }

                    $candidateOwnerKey = ConvertTo-FallbackTailPairingValue (
                        Get-FileTransferEventField -Event $candidate -Name 'owner_key' -Default '')
                    $candidatePairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
                        -PairKey (Get-FileTransferEventField -Event $candidate -Name 'pair_key' -Default '') `
                        -OwnerKey $candidateOwnerKey `
                        -BridgeRecoveryGeneration $peerBridgeGeneration
                    $candidateSharedPairKey = Get-FileTransferFallbackTailSharedPairKeyForEvent -Event $candidate
                    if (-not $peerPairEvidence.Valid -or
                        -not $candidatePairEvidence.Valid -or
                        $candidateSharedPairKey -eq '(invalid)' -or
                        -not [string]::Equals($candidateOwnerKey, $peerOwnerKey, [System.StringComparison]::Ordinal) -or
                        -not [string]::Equals(
                            [string]$candidatePairEvidence.RawPairKey,
                            [string]$peerPairEvidence.RawPairKey,
                            [System.StringComparison]::Ordinal) -or
                        $candidatePairEvidence.Format -ne $peerPairEvidence.Format -or
                        -not [string]::Equals(
                            [string]$candidatePairEvidence.CanonicalPairKey,
                            [string]$peerPairEvidence.CanonicalPairKey,
                            [System.StringComparison]::Ordinal) -or
                        -not [string]::Equals(
                            [string]$candidatePairEvidence.CanonicalPairKey,
                            $candidateSharedPairKey,
                            [System.StringComparison]::Ordinal)) {
                        return $false
                    }

                    if ($mismatchAuthoritySchema -ge 2) {
                        return $mismatchAuthorityId -eq (ConvertTo-FallbackTailPairingValue (
                                Get-FileTransferEventField -Event $candidate -Name 'authority_id' -Default '')) -and
                            $mismatchPredecessorId -eq (ConvertTo-FallbackTailPairingValue (
                                Get-FileTransferEventField -Event $candidate -Name 'predecessor_authority_id' -Default ''))
                    }

                    return $true
                } |
                Sort-Object Sequence -Descending |
                Select-Object -First 1
        )
    }

    function Test-FallbackTailPairingRecovered {
        param(
            [Parameter(Mandatory = $true)]$Mismatch,
            [Parameter(Mandatory = $true)]$Publication,
            [Parameter(Mandatory = $true)]$SentProof
        )

        $mismatchSequence = [int64]$Mismatch.Sequence
        $localBridgeGeneration = Get-FileTransferEventInt64Field -Event $Mismatch -Name 'bridge_recovery_generation' -Default 0
        $peerBridgeGeneration = Get-FileTransferEventInt64Field -Event $Mismatch -Name 'peer_bridge_recovery_generation' -Default 0
        $yieldGeneration = Get-FileTransferEventInt64Field -Event $Mismatch -Name 'yield_generation' -Default 0
        $mismatchExpectedPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
            -PairKey (Get-FileTransferEventField -Event $Mismatch -Name 'expected_pair_key' -Default '') `
            -OwnerKey (Get-FileTransferEventField -Event $Mismatch -Name 'expected_owner_key' -Default '') `
            -BridgeRecoveryGeneration (Get-FileTransferEventInt64Field `
                -Event $Mismatch `
                -Name 'bridge_recovery_generation' `
                -Default -1)
        $sentAuthorityId = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $SentProof -Name 'authority_id' -Default '')
        $sentPredecessorAuthorityId = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $SentProof -Name 'predecessor_authority_id' -Default '')
        $sentDirection = Get-FileTransferEventField -Event $SentProof -Name 'direction' -Default ''
        $sentCheckpoint = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $SentProof -Name 'checkpoint_request_id' -Default '')
        $sentOwnerKey = ConvertTo-FallbackTailPairingValue (
            Get-FileTransferEventField -Event $SentProof -Name 'owner_key' -Default '')
        $sentPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
            -PairKey (Get-FileTransferEventField -Event $SentProof -Name 'pair_key' -Default '') `
            -OwnerKey $sentOwnerKey `
            -BridgeRecoveryGeneration (Get-FileTransferEventInt64Field `
                -Event $SentProof `
                -Name 'bridge_recovery_generation' `
                -Default -1)
        $sentYieldGeneration = Get-FileTransferEventInt64Field `
            -Event $SentProof `
            -Name 'yield_generation' `
            -Default 0

        foreach ($pairEvidence in @($lifecycleValidPairedEvidence.ToArray() | Sort-Object {
                    [int64]$_.PairedEvent.Sequence
                })) {
            $paired = $pairEvidence.PairedEvent
            $pairedBridgeGeneration = Get-FileTransferEventInt64Field `
                -Event $paired `
                -Name 'bridge_recovery_generation' `
                -Default -1
            $pairedPeerBridgeGeneration = Get-FileTransferEventInt64Field `
                -Event $paired `
                -Name 'peer_bridge_recovery_generation' `
                -Default -1
            $pairedPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
                -PairKey (Get-FileTransferEventField -Event $paired -Name 'pair_key' -Default '') `
                -OwnerKey (Get-FileTransferEventField -Event $paired -Name 'owner_key' -Default '') `
                -BridgeRecoveryGeneration $pairedBridgeGeneration
            $peerReceived = $pairEvidence.PeerReceivedEvent
            $receivedAuthorityId = ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $peerReceived -Name 'authority_id' -Default '')
            $receivedPredecessorAuthorityId = ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $peerReceived -Name 'predecessor_authority_id' -Default '')
            $receivedYieldGeneration = Get-FileTransferEventInt64Field `
                -Event $peerReceived `
                -Name 'yield_generation' `
                -Default 0
            $receivedOwnerKey = ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $peerReceived -Name 'owner_key' -Default '')
            $receivedPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
                -PairKey (Get-FileTransferEventField -Event $peerReceived -Name 'pair_key' -Default '') `
                -OwnerKey $receivedOwnerKey `
                -BridgeRecoveryGeneration (Get-FileTransferEventInt64Field `
                    -Event $peerReceived `
                    -Name 'peer_bridge_recovery_generation' `
                    -Default -1)
            $exactPeerAuthority = $receivedAuthorityId -eq $sentAuthorityId -and
                $receivedPredecessorAuthorityId -eq $sentPredecessorAuthorityId -and
                $receivedYieldGeneration -eq $sentYieldGeneration
            $directPeerSuccessor = $receivedAuthorityId -ne '(none)' -and
                $receivedAuthorityId -ne $sentAuthorityId -and
                $receivedPredecessorAuthorityId -eq $sentAuthorityId -and
                $receivedYieldGeneration -gt $sentYieldGeneration
            $peerAuthorityChainMatches = $exactPeerAuthority -or $directPeerSuccessor
            $peerTupleMatches = $sentPairEvidence.Valid -and
                $receivedPairEvidence.Valid -and
                [string]::Equals(
                    (Get-FileTransferEventField -Event $peerReceived -Name 'peer_direction' -Default ''),
                    $sentDirection,
                    [System.StringComparison]::OrdinalIgnoreCase) -and
                (Get-FileTransferEventInt64Field -Event $peerReceived -Name 'peer_live_route_epoch' -Default 0) -eq
                    (Get-FileTransferEventInt64Field -Event $SentProof -Name 'live_route_epoch' -Default 0) -and
                (Get-FileTransferEventInt64Field -Event $peerReceived -Name 'peer_leg_generation' -Default 0) -eq
                    (Get-FileTransferEventInt64Field -Event $SentProof -Name 'leg_generation' -Default 0) -and
                (Get-FileTransferEventInt64Field -Event $peerReceived -Name 'peer_transport_epoch' -Default -1) -eq
                    (Get-FileTransferEventInt64Field -Event $SentProof -Name 'transport_epoch' -Default -1) -and
                (Get-FileTransferEventInt64Field -Event $peerReceived -Name 'peer_bridge_recovery_generation' -Default -1) -eq
                    (Get-FileTransferEventInt64Field -Event $SentProof -Name 'bridge_recovery_generation' -Default -1) -and
                (ConvertTo-FallbackTailPairingValue (
                    Get-FileTransferEventField -Event $peerReceived -Name 'peer_checkpoint_request_id' -Default '')) -eq
                    $sentCheckpoint -and
                [string]::Equals($receivedOwnerKey, $sentOwnerKey, [System.StringComparison]::Ordinal) -and
                [string]::Equals(
                    [string]$receivedPairEvidence.CanonicalPairKey,
                    [string]$sentPairEvidence.CanonicalPairKey,
                    [System.StringComparison]::Ordinal)
            if ($exactPeerAuthority) {
                $peerTupleMatches = $peerTupleMatches -and
                    $receivedPairEvidence.Format -eq $sentPairEvidence.Format -and
                    [string]::Equals(
                        [string]$receivedPairEvidence.RawPairKey,
                        [string]$sentPairEvidence.RawPairKey,
                        [System.StringComparison]::Ordinal)
            }
            $completeChainAfterMismatch = [int64]$pairEvidence.LocalQuiescentEvent.Sequence -gt $mismatchSequence -and
                [int64]$pairEvidence.LocalSentEvent.Sequence -gt $mismatchSequence -and
                [int64]$pairEvidence.PeerReceivedEvent.Sequence -gt $mismatchSequence -and
                [int64]$paired.Sequence -gt $mismatchSequence
            $candidateMatches = $completeChainAfterMismatch
            $candidateMatches = $candidateMatches -and $peerAuthorityChainMatches
            $candidateMatches = $candidateMatches -and $peerTupleMatches
            $candidateMatches = $candidateMatches -and
                (Test-FallbackTailPairingScopeMatch -Anchor $Mismatch -Candidate $paired -RequireDirection)
            $candidateMatches = $candidateMatches -and
                (Get-FileTransferEventField -Event $paired -Name 'route' -Default '') -eq 'post_tuna_fallback_v6'
            $candidateMatches = $candidateMatches -and
                (Get-FileTransferEventInt64Field -Event $paired -Name 'protocol_version' -Default 0) -eq 6
            $candidateMatches = $candidateMatches -and
                (Get-FileTransferEventInt64Field -Event $paired -Name 'live_route_epoch' -Default 0) -eq
                    (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'live_route_epoch' -Default 0)
            $candidateMatches = $candidateMatches -and
                (Get-FileTransferEventInt64Field -Event $paired -Name 'transport_epoch' -Default -1) -eq
                    (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'transport_epoch' -Default -1)
            $candidateMatches = $candidateMatches -and $pairedBridgeGeneration -ge $localBridgeGeneration
            $candidateMatches = $candidateMatches -and $pairedPeerBridgeGeneration -eq $peerBridgeGeneration
            $candidateMatches = $candidateMatches -and $mismatchExpectedPairEvidence.Valid
            $candidateMatches = $candidateMatches -and $pairedPairEvidence.Valid
            $candidateMatches = $candidateMatches -and [string]::Equals(
                [string]$pairedPairEvidence.CanonicalPairKey,
                [string]$mismatchExpectedPairEvidence.CanonicalPairKey,
                [System.StringComparison]::Ordinal)
            $candidateMatches = $candidateMatches -and
                (Get-FileTransferEventInt64Field -Event $paired -Name 'peer_yield_generation' -Default 0) -ge $yieldGeneration
            if (-not $candidateMatches) {
                continue
            }

            $grantPublicationState = Get-FallbackTailCurrentRoutePublicationState -Mismatch $paired
            $grantAuthorityState = Get-FallbackTailCurrentLegAuthorityState -Mismatch $paired
            if ($grantPublicationState.Status -eq 'current' -and $grantAuthorityState.Status -eq 'current') {
                return $true
            }
        }

        $terminalProof = @($terminalProofEvents | Where-Object {
            Test-FallbackTailTerminalProofMatchesMismatch `
                -Mismatch $Mismatch `
                -TerminalProof $_
        } | Select-Object -First 1).Count -gt 0
        if ($terminalProof) {
            return $true
        }

        $publicationGeneration = Get-FileTransferEventInt64Field -Event $Publication -Name 'route_publication_generation' -Default 0
        [object[]]$secondTunaPublications = @($routePublicationEvents | Where-Object {
            [int64]$_.Sequence -gt $mismatchSequence -and
            (Test-FallbackTailPairingScopeMatch -Anchor $Mismatch -Candidate $_ -RequireDirection) -and
            $_.EventName -eq 'filetransfer_route_selected' -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'route_publication_generation' -Default 0) -gt $publicationGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'file_tuna_v4' -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'protocol_version' -Default 0) -eq 4 -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'live_route_epoch' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'runtime_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'terminal_generation' -Default -1) -ge 0 -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventField -Event $_ -Name 'target_route' -Default '') -eq 'file_tuna_v4' -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'target_protocol_version' -Default 0) -eq 4 -and
            (Get-FileTransferEventField -Event $_ -Name 'target_transport' -Default '') -eq 'tuna' -and
            (Get-FileTransferEventField -Event $_ -Name 'route_publication_action_kind' -Default '') -eq 'RouteCommitPublication' -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'route_commit_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventField -Event $_ -Name 'coordinator_decision_reason' -Default '') -eq 'accepted'
        } | Sort-Object Sequence)
        foreach ($secondTuna in $secondTunaPublications) {
            $terminalBeforePublication = @($transferTerminalEvents | Where-Object {
                [int64]$_.Sequence -gt $mismatchSequence -and
                [int64]$_.Sequence -lt [int64]$secondTuna.Sequence -and
                (Test-FallbackTailPairingScopeMatch -Anchor $Mismatch -Candidate $_)
            } | Select-Object -First 1).Count -gt 0
            if (-not $terminalBeforePublication) {
                return $true
            }
        }

        return $false
    }

    $lifecycleValidPairedEvents = New-Object System.Collections.Generic.List[object]
    $lifecycleValidPairedEvidence = New-Object System.Collections.Generic.List[object]
    $lifecycleInvalidPairedEvents = New-Object System.Collections.Generic.List[object]
    foreach ($pairEvidence in @($pairedYieldValidation.ValidPairedEvidence | Sort-Object {
                [int64]$_.PairedEvent.Sequence
            })) {
        $pairedEvent = $pairEvidence.PairedEvent
        $pairedPublicationState = Get-FallbackTailCurrentRoutePublicationState -Mismatch $pairedEvent
        $pairedAuthorityState = Get-FallbackTailCurrentLegAuthorityState -Mismatch $pairedEvent
        if ($pairedPublicationState.Status -eq 'current' -and $pairedAuthorityState.Status -eq 'current') {
            $lifecycleValidPairedEvents.Add($pairedEvent) | Out-Null
            $lifecycleValidPairedEvidence.Add($pairEvidence) | Out-Null
        }
        else {
            $lifecycleInvalidPairedEvents.Add($pairedEvent) | Out-Null
        }
    }

    [object[]]$preciseRawEvents = @($mismatchEvents | Where-Object { Test-FallbackTailPreciseBridgeRecoveryMismatch -Event $_ })
    $qualifiedByIdentity = @{}
    $qualifiedRawCount = 0
    $qualifiedSequences = New-Object System.Collections.Generic.List[long]
    $staleDiagnosticSequences = New-Object System.Collections.Generic.List[long]
    foreach ($mismatch in @($preciseRawEvents | Sort-Object Sequence, LineNumber)) {
        $publicationState = Get-FallbackTailCurrentRoutePublicationState -Mismatch $mismatch
        $authorityState = Get-FallbackTailCurrentLegAuthorityState -Mismatch $mismatch
        if ($publicationState.Status -eq 'stale' -or $authorityState.Status -eq 'stale') {
            $staleDiagnosticSequences.Add([int64]$mismatch.Sequence) | Out-Null
            continue
        }

        $sentProof = @(Find-FallbackTailMatchingSentProof -Mismatch $mismatch)
        if ($publicationState.Status -ne 'current' -or
            $authorityState.Status -ne 'current' -or
            $sentProof.Count -eq 0) {
            continue
        }

        $qualifiedRawCount++
        $qualifiedSequences.Add([int64]$mismatch.Sequence) | Out-Null
        $hasCurrentAuthorityTuple = (Get-FileTransferAuthoritySchema -Line ([string]$mismatch.RawLine)) -ge 2
        $authorityId = if ($hasCurrentAuthorityTuple) {
            ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $mismatch -Name 'authority_id' -Default '')
        }
        else {
            ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $sentProof[0] -Name 'authority_id' -Default '')
        }
        $predecessorAuthorityId = if ($hasCurrentAuthorityTuple) {
            ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $mismatch -Name 'predecessor_authority_id' -Default '')
        }
        else {
            ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $sentProof[0] -Name 'predecessor_authority_id' -Default '')
        }
        $expectedPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
            -PairKey (Get-FileTransferEventField -Event $mismatch -Name 'expected_pair_key' -Default '') `
            -OwnerKey (Get-FileTransferEventField -Event $mismatch -Name 'expected_owner_key' -Default '') `
            -BridgeRecoveryGeneration (Get-FileTransferEventInt64Field `
                -Event $mismatch `
                -Name 'bridge_recovery_generation' `
                -Default -1)
        $peerPairEvidence = Get-FileTransferFallbackTailPairKeyEvidence `
            -PairKey (Get-FileTransferEventField -Event $mismatch -Name 'peer_pair_key' -Default '') `
            -OwnerKey (Get-FileTransferEventField -Event $mismatch -Name 'peer_owner_key' -Default '') `
            -BridgeRecoveryGeneration (Get-FileTransferEventInt64Field `
                -Event $mismatch `
                -Name 'peer_bridge_recovery_generation' `
                -Default -1)
        [object[]]$identityParts = @(
            (Get-FileTransferEventField -Event $mismatch -Name 'transfer_id' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'session_id' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'direction' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'peer_direction' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'route' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'protocol_version' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'live_route_epoch' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'leg_generation' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'transport_epoch' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'bridge_recovery_generation' -Default ''),
            (ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $mismatch -Name 'checkpoint_request_id' -Default '')),
            (Get-FileTransferEventField -Event $mismatch -Name 'peer_live_route_epoch' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'peer_leg_generation' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'peer_transport_epoch' -Default ''),
            (Get-FileTransferEventField -Event $mismatch -Name 'peer_bridge_recovery_generation' -Default ''),
            (ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $mismatch -Name 'peer_checkpoint_request_id' -Default '')),
            (ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $mismatch -Name 'expected_owner_key' -Default '')),
            $expectedPairEvidence.RawPairKey,
            $expectedPairEvidence.Format,
            (ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $mismatch -Name 'peer_owner_key' -Default '')),
            $peerPairEvidence.RawPairKey,
            $peerPairEvidence.Format,
            (Get-FileTransferEventField -Event $mismatch -Name 'yield_generation' -Default ''),
            $authorityId,
            $predecessorAuthorityId,
            (Get-FileTransferEventField -Event $publicationState.Event -Name 'route_publication_generation' -Default ''),
            (Get-FileTransferEventField -Event $publicationState.Event -Name 'runtime_generation' -Default ''),
            (Get-FileTransferEventField -Event $publicationState.Event -Name 'terminal_generation' -Default ''),
            (Get-FileTransferEventField -Event $publicationState.Event -Name 'leg_generation' -Default ''),
            (Get-FileTransferEventField -Event $publicationState.Event -Name 'route_commit_generation' -Default ''),
            (Get-FileTransferEventField -Event $publicationState.Event -Name 'route_publication_action_kind' -Default ''),
            $authorityState.Event.EventName,
            (Get-FileTransferEventField -Event $authorityState.Event -Name 'live_route_epoch' -Default ''),
            (Get-FileTransferEventField -Event $authorityState.Event -Name 'leg_generation' -Default ''),
            (Get-FileTransferEventField -Event $authorityState.Event -Name 'transport_epoch' -Default ''),
            (Get-FileTransferEventField -Event $authorityState.Event -Name 'bridge_recovery_generation' -Default ''),
            (ConvertTo-FallbackTailPairingValue (
                Get-FileTransferEventField -Event $authorityState.Event -Name 'current_checkpoint_request_id' -Default (
                    Get-FileTransferEventField -Event $authorityState.Event -Name 'checkpoint_request_id' -Default '')))
        )
        $identity = ConvertTo-Json -InputObject $identityParts -Compress -Depth 2
        if (-not $qualifiedByIdentity.ContainsKey($identity)) {
            $qualifiedByIdentity[$identity] = [pscustomobject]@{
                Event = $mismatch
                Publication = $publicationState.Event
                SentProof = $sentProof[0]
            }
        }
    }

    $unresolvedEvents = New-Object System.Collections.Generic.List[object]
    $recoveredCount = 0
    foreach ($identity in @($qualifiedByIdentity.Keys | Sort-Object)) {
        $entry = $qualifiedByIdentity[$identity]
        if (Test-FallbackTailPairingRecovered `
                -Mismatch $entry.Event `
                -Publication $entry.Publication `
                -SentProof $entry.SentProof) {
            $recoveredCount++
        }
        else {
            $unresolvedEvents.Add($entry.Event) | Out-Null
        }
    }

    [long[]]$qualifiedSequenceArray = @($qualifiedSequences.ToArray())
    [long[]]$staleDiagnosticSequenceArray = @($staleDiagnosticSequences.ToArray())
    [object[]]$otherMismatchEvents = @(
        $mismatchEvents | Where-Object {
            [int64]$_.Sequence -notin $qualifiedSequenceArray -and
            [int64]$_.Sequence -notin $staleDiagnosticSequenceArray
        }
    )
    $verdict = if ($unresolvedEvents.Count -gt 0) {
        'fail'
    }
    elseif ($qualifiedByIdentity.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        Verdict = $verdict
        RawCount = $preciseRawEvents.Count
        QualifiedRawCount = $qualifiedRawCount
        UncorrelatedCount = $preciseRawEvents.Count - $qualifiedRawCount - $staleDiagnosticSequences.Count
        StaleDiagnosticCount = $staleDiagnosticSequences.Count
        DistinctCount = $qualifiedByIdentity.Count
        RecoveredCount = $recoveredCount
        UnresolvedCount = $unresolvedEvents.Count
        CandidateEvents = @($unresolvedEvents.ToArray() | Sort-Object Sequence, LineNumber)
        LifecycleValidPairedEvents = @($lifecycleValidPairedEvents.ToArray())
        LifecycleValidPairedEvidence = @($lifecycleValidPairedEvidence.ToArray())
        LifecycleInvalidPairedEvents = @($lifecycleInvalidPairedEvents.ToArray())
        ValidTerminalProofEvents = @($terminalProofEvents | Where-Object {
            Test-FallbackTailTerminalProofShape -Event $_
        })
        OtherOwnerGenerationMismatchEvents = $otherMismatchEvents
    }
}

function Get-FileTransferFallbackTailTransportEpochReauthorizationProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$events = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$suppressedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_retired_owner_update_suppressed'
    })
    [object[]]$adoptionEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_leg_transport_epoch_adopted'
    })
    [object[]]$retirementEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_recovery_owner_retired_after_yield'
    })
    [object[]]$reauthorizationStagedEvents = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_fallback_tail_transport_epoch_reauthorization_staged',
            'filetransfer_fallback_tail_transport_epoch_reauthorization_rebound')
    })
    [object[]]$reauthorizationSuccessorEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_transport_epoch_reauthorization_successor_issued'
    })
    [object[]]$reauthorizationInvalidatedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_transport_epoch_reauthorization_invalidated'
    })
    [object[]]$yieldEvents = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_fallback_tail_quiescent_yield_granted',
            'filetransfer_fallback_tail_yield_issued')
    })
    [object[]]$proofSentEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_yield_proof_sent'
    })
    $coordinatorAggregateProof =
        Get-FileTransferFallbackTailCoordinatorAggregateCorrelation -Events $events
    [object[]]$coordinatorPairedEvents = @($coordinatorAggregateProof.ValidPairingEvents)
    [object[]]$pairedEvents = @(
        @(
            (Get-FileTransferFallbackTailPairedYieldValidation -Events $events).ValidPairedEvents +
            $coordinatorPairedEvents) |
            Sort-Object Sequence, LineNumber -Unique)
    [object[]]$terminalProofEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_terminal_proof_consumed'
    })
    [object[]]$tunaPublicationEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_route_selected' -and
        (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'file_tuna_v4' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'protocol_version' -Default 0) -eq 4 -and
        (Get-FileTransferEventField -Event $_ -Name 'target_route' -Default '') -eq 'file_tuna_v4' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'target_protocol_version' -Default 0) -eq 4 -and
        (Get-FileTransferEventField -Event $_ -Name 'target_transport' -Default '') -eq 'tuna' -and
        (Get-FileTransferEventField -Event $_ -Name 'route_publication_action_kind' -Default '') -eq 'RouteCommitPublication' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'route_commit_generation' -Default 0) -gt 0 -and
        (Get-FileTransferEventField -Event $_ -Name 'coordinator_decision_reason' -Default '') -eq 'accepted'
    })
    [object[]]$mismatchEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_owner_generation_mismatch'
    })
    [object[]]$peerProofReceivedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_yield_proof_received'
    })
    [object[]]$localYieldBlockedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_local_yield_blocked'
    })

    function Test-FallbackTailTransportReauthorizationScope {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate,
            [switch]$IgnoreDirection
        )

        foreach ($fieldName in @('session_id', 'transfer_id')) {
            $left = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Anchor -Name $fieldName -Default '')
            $right = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Candidate -Name $fieldName -Default '')
            if ($left -eq '(none)' -or
                $right -eq '(none)' -or
                -not [string]::Equals($left, $right, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        if (-not $IgnoreDirection) {
            $leftDirection = Get-FileTransferEventField -Event $Anchor -Name 'direction' -Default ''
            $rightDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
            if (-not [string]::Equals(
                    $leftDirection,
                    $rightDirection,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailTransportReauthorizationRuntimeScope {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate,
            [long]$ExpectedTransportEpoch,
            [switch]$CandidateUsesCurrentCheckpoint
        )

        if (-not (Test-FallbackTailTransportReauthorizationScope -Anchor $Anchor -Candidate $Candidate)) {
            return $false
        }

        foreach ($fieldName in @('route', 'protocol_version', 'live_route_epoch', 'leg_generation', 'bridge_recovery_generation')) {
            $left = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Anchor -Name $fieldName -Default '')
            $right = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Candidate -Name $fieldName -Default '')
            if ($left -eq '(none)' -or
                $right -eq '(none)' -or
                -not [string]::Equals($left, $right, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        if ((Get-FileTransferEventInt64Field -Event $Candidate -Name 'transport_epoch' -Default -1) -ne
            $ExpectedTransportEpoch) {
            return $false
        }

        $anchorCheckpoint = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Anchor -Name 'checkpoint_request_id' -Default '')
        $candidateCheckpointName = if ($CandidateUsesCurrentCheckpoint) {
            'current_checkpoint_request_id'
        }
        else {
            'checkpoint_request_id'
        }
        $candidateCheckpoint = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Candidate -Name $candidateCheckpointName -Default (
                Get-FileTransferEventField -Event $Candidate -Name 'checkpoint_request_id' -Default ''))
        return [string]::Equals(
            $anchorCheckpoint,
            $candidateCheckpoint,
            [System.StringComparison]::Ordinal)
    }

    function Test-FallbackTailTransportReauthorizationFieldMap {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [Parameter(Mandatory = $true)][hashtable]$FieldMap
        )

        foreach ($leftFieldName in @($FieldMap.Keys)) {
            $rightFieldName = [string]$FieldMap[$leftFieldName]
            $leftRaw = Get-FileTransferEventField -Event $Left -Name $leftFieldName -Default '__missing__'
            $rightRaw = Get-FileTransferEventField -Event $Right -Name $rightFieldName -Default '__missing__'
            $leftValue = ConvertTo-FileTransferFallbackTailPairingValue $leftRaw
            $rightValue = ConvertTo-FileTransferFallbackTailPairingValue $rightRaw
            if ($leftRaw -eq '__missing__' -or
                $rightRaw -eq '__missing__' -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailTransportReauthorizationDescriptor {
        param(
            [Parameter(Mandatory = $true)]$Entry,
            [Parameter(Mandatory = $true)]$Descriptor
        )

        $anchor = $Entry.Event
        $predecessor = $Entry.Predecessor
        if (-not (Test-FallbackTailTransportReauthorizationScope -Anchor $anchor -Candidate $Descriptor)) {
            return $false
        }

        $predecessorAuthorityId = [string]$Entry.PredecessorAuthorityId
        $predecessorOwnerKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $predecessor -Name 'owner_key' -Default '')
        $predecessorPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $predecessor -Name 'pair_key' -Default '')
        if ($predecessorOwnerKey -eq '(none)' -or
            $predecessorPairKey -eq '(none)' -or
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Descriptor -Name 'predecessor_authority_id' -Default '')) -ne
                $predecessorAuthorityId -or
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Descriptor -Name 'source_owner_key' -Default '')) -ne
                $predecessorOwnerKey -or
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Descriptor -Name 'source_pair_key' -Default '')) -ne
                $predecessorPairKey -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'source_transport_epoch' -Default -1) -ne
                [long]$Entry.PreviousTransportEpoch -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'target_transport_epoch' -Default -1) -ne
                [long]$Entry.CurrentTransportEpoch -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'reauthorization_generation' -Default 0) -le 0 -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'predecessor_yield_generation' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $predecessor -Name 'yield_generation' -Default 0) -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'predecessor_protocol_version' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $predecessor -Name 'protocol_version' -Default 0) -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'predecessor_live_route_epoch' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $predecessor -Name 'live_route_epoch' -Default 0) -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'predecessor_runtime_generation' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $predecessor -Name 'runtime_generation' -Default 0) -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'source_runtime_generation' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $predecessor -Name 'runtime_generation' -Default 0) -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'predecessor_terminal_generation' -Default -1) -ne
                (Get-FileTransferEventInt64Field -Event $predecessor -Name 'terminal_generation' -Default -1) -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'predecessor_leg_generation' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $predecessor -Name 'leg_generation' -Default 0) -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'predecessor_bridge_recovery_generation' -Default -1) -ne
                (Get-FileTransferEventInt64Field -Event $predecessor -Name 'bridge_recovery_generation' -Default -1) -or
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Descriptor -Name 'predecessor_checkpoint_request_id' -Default '')) -ne
                (ConvertTo-FileTransferFallbackTailPairingValue (
                    Get-FileTransferEventField -Event $predecessor -Name 'checkpoint_request_id' -Default ''))) {
            return $false
        }

        $targetOwnerKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Descriptor -Name 'target_owner_key' -Default '')
        $targetPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Descriptor -Name 'target_pair_key' -Default '')
        $ownerParts = if ($targetOwnerKey -eq '(none)') { @() } else { @($targetOwnerKey.Split('|')) }
        $pairParts = if ($targetPairKey -eq '(none)') { @() } else { @($targetPairKey.Split('|')) }
        $targetCheckpoint = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $Descriptor -Name 'checkpoint_request_id' -Default '')
        $hasCoordinatorExactTargetScope =
            (Get-FileTransferEventField `
                -Event $Descriptor `
                -Name 'target_transport_decision_generation' `
                -Default '__missing__') -ne '__missing__'
        if ($ownerParts.Count -ne 9 -or
            $pairParts.Count -ne 7 -or
            $ownerParts[0] -ne (Get-FileTransferEventField -Event $Descriptor -Name 'session_id' -Default '') -or
            $ownerParts[1] -ne (Get-FileTransferEventField -Event $Descriptor -Name 'transfer_id' -Default '') -or
            $ownerParts[2] -ne 'post_tuna_fallback_v6' -or
            $ownerParts[3] -ne '6' -or
            $ownerParts[4] -ne (Get-FileTransferEventField -Event $predecessor -Name 'live_route_epoch' -Default '') -or
            $ownerParts[5] -ne (Get-FileTransferEventField -Event $Descriptor -Name 'leg_generation' -Default '') -or
            $ownerParts[6] -ne (Get-FileTransferEventField -Event $Descriptor -Name 'bridge_recovery_generation' -Default '') -or
            $ownerParts[7] -ne ([string]$Entry.CurrentTransportEpoch) -or
            (ConvertTo-FileTransferFallbackTailPairingValue $ownerParts[8]) -ne $targetCheckpoint -or
            $pairParts[0] -ne $ownerParts[0] -or
            $pairParts[1] -ne $ownerParts[1] -or
            $pairParts[2] -ne $ownerParts[2] -or
            $pairParts[3] -ne $ownerParts[3] -or
            $pairParts[4] -ne $ownerParts[4] -or
            $pairParts[5] -ne $ownerParts[7] -or
            (ConvertTo-FileTransferFallbackTailPairingValue $pairParts[6]) -ne $targetCheckpoint -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'target_runtime_generation' -Default 0) -le 0 -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'terminal_generation' -Default -1) -lt 0 -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'leg_generation' -Default 0) -le 0 -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'bridge_recovery_generation' -Default -1) -lt 0 -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'bridge_decision_generation' -Default 0) -le 0 -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'route_publication_generation' -Default 0) -le 0 -or
            (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'data_session_generation' -Default 0) -le 0) {
            return $false
        }

        if ($hasCoordinatorExactTargetScope) {
            $checkpointGeneration = Get-FileTransferEventInt64Field `
                -Event $Descriptor `
                -Name 'checkpoint_generation' `
                -Default -1
            $checkpointLeaseGeneration = Get-FileTransferEventInt64Field `
                -Event $Descriptor `
                -Name 'checkpoint_lease_generation' `
                -Default -1
            $checkpointLeaseState = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Descriptor -Name 'checkpoint_lease_state' -Default '')
            $checkpointLeaseRequestId = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Descriptor -Name 'checkpoint_lease_request_id' -Default '')
            $checkpointLeaseReason = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Descriptor -Name 'checkpoint_lease_reason' -Default '')
            $dataSessionIdentity = ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $Descriptor -Name 'data_session_identity' -Default '')
            if ((Get-FileTransferEventInt64Field -Event $Descriptor -Name 'target_transport_decision_generation' -Default 0) -le 0 -or
                -not [string]::Equals(
                    (Get-FileTransferEventField -Event $Descriptor -Name 'target_transport_decision_action' -Default ''),
                    'Adopt',
                    [System.StringComparison]::Ordinal) -or
                (ConvertTo-FileTransferFallbackTailPairingValue (
                    Get-FileTransferEventField -Event $Descriptor -Name 'target_transport_decision_reason' -Default '')) -eq '(none)' -or
                (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'target_transport_decision_epoch' -Default -1) -ne
                    [long]$Entry.CurrentTransportEpoch -or
                (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'target_transport_decision_bridge_recovery_generation' -Default -1) -ne
                    (Get-FileTransferEventInt64Field -Event $Descriptor -Name 'bridge_recovery_generation' -Default -2) -or
                $checkpointGeneration -lt 0 -or
                $checkpointLeaseGeneration -lt 0 -or
                $dataSessionIdentity -eq '(none)') {
                return $false
            }

            if ($checkpointLeaseGeneration -eq 0) {
                if ($checkpointLeaseState -ne '(none)' -or
                    $checkpointLeaseRequestId -ne '(none)' -or
                    $checkpointLeaseReason -ne '(none)') {
                    return $false
                }
            }
            elseif ($checkpointLeaseState -eq '(none)' -or
                $checkpointLeaseRequestId -ne $targetCheckpoint -or
                $checkpointLeaseReason -eq '(none)') {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailTransportReauthorizationRecovered {
        param(
            [Parameter(Mandatory = $true)]$Entry
        )

        $anchor = $Entry.Event
        $anchorSequence = [int64]$anchor.Sequence
        $predecessorAuthorityId = [string]$Entry.PredecessorAuthorityId
        $legacyDescriptorFields = @(
            'authority_schema',
            'direction',
            'session_id',
            'transfer_id',
            'predecessor_authority_id',
            'predecessor_yield_generation',
            'reauthorization_generation',
            'source_owner_key',
            'source_pair_key',
            'target_owner_key',
            'target_pair_key',
            'source_transport_epoch',
            'target_transport_epoch',
            'source_runtime_generation',
            'target_runtime_generation',
            'predecessor_route',
            'predecessor_protocol_version',
            'predecessor_live_route_epoch',
            'predecessor_runtime_generation',
            'predecessor_terminal_generation',
            'predecessor_leg_generation',
            'predecessor_bridge_recovery_generation',
            'predecessor_checkpoint_request_id',
            'terminal_generation',
            'leg_generation',
            'bridge_recovery_generation',
            'bridge_decision_generation',
            'route_publication_generation',
            'route_commit_generation',
            'checkpoint_request_id',
            'data_session_generation')
        $coordinatorExactDescriptorFields = @(
            'target_transport_decision_generation',
            'target_transport_decision_action',
            'target_transport_decision_reason',
            'target_transport_decision_epoch',
            'target_transport_decision_bridge_recovery_generation',
            'checkpoint_generation',
            'checkpoint_lease_generation',
            'checkpoint_lease_state',
            'checkpoint_lease_request_id',
            'checkpoint_lease_reason',
            'data_session_identity')
        [object[]]$staged = @($reauthorizationStagedEvents | Where-Object {
            [int64]$_.Sequence -gt $anchorSequence -and
            (Test-FallbackTailTransportReauthorizationDescriptor -Entry $Entry -Descriptor $_)
        } | Sort-Object Sequence)
        foreach ($stage in $staged) {
            [string[]]$descriptorFields = @($legacyDescriptorFields)
            if ((Get-FileTransferEventField `
                    -Event $stage `
                    -Name 'target_transport_decision_generation' `
                    -Default '__missing__') -ne '__missing__') {
                $descriptorFields = @($legacyDescriptorFields + $coordinatorExactDescriptorFields)
            }
            [object[]]$issuedEvents = @($reauthorizationSuccessorEvents | Where-Object {
                $issued = $_
                [int64]$_.Sequence -gt [int64]$stage.Sequence -and
                (Test-FileTransferAuthorityFieldsEqual `
                    -LeftLine ([string]$stage.RawLine) `
                    -RightLine ([string]$_.RawLine) `
                    -Fields $descriptorFields) -and
                @($reauthorizationInvalidatedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$stage.Sequence -and
                    [int64]$_.Sequence -lt [int64]$issued.Sequence -and
                    (Test-FileTransferAuthorityFieldsEqual `
                        -LeftLine ([string]$stage.RawLine) `
                        -RightLine ([string]$_.RawLine) `
                        -Fields $descriptorFields)
                } | Select-Object -First 1).Count -eq 0
            } | Sort-Object Sequence)
            foreach ($issued in $issuedEvents) {
                $successorAuthorityId = ConvertTo-FileTransferFallbackTailPairingValue (
                    Get-FileTransferEventField -Event $issued -Name 'successor_authority_id' -Default '')
                $successorYieldGeneration = Get-FileTransferEventInt64Field `
                    -Event $issued `
                    -Name 'successor_yield_generation' `
                    -Default 0
                if ($successorAuthorityId -eq '(none)' -or
                    $successorAuthorityId -eq $predecessorAuthorityId -or
                    $successorYieldGeneration -ne
                        ((Get-FileTransferEventInt64Field `
                            -Event $issued `
                            -Name 'predecessor_yield_generation' `
                            -Default 0) + 1) -or
                    -not (Test-FallbackTailTransportReauthorizationFieldMap `
                        -Left $issued `
                        -Right $issued `
                        -FieldMap @{
                            successor_owner_key = 'target_owner_key'
                            successor_pair_key = 'target_pair_key'
                            successor_runtime_generation = 'target_runtime_generation'
                            successor_terminal_generation = 'terminal_generation'
                            successor_leg_generation = 'leg_generation'
                            successor_bridge_recovery_generation = 'bridge_recovery_generation'
                            successor_checkpoint_request_id = 'checkpoint_request_id'
                        })) {
                    continue
                }

                $successorFieldMap = @{
                    successor_authority_id = 'authority_id'
                    predecessor_authority_id = 'predecessor_authority_id'
                    successor_yield_generation = 'yield_generation'
                    successor_owner_key = 'owner_key'
                    successor_pair_key = 'pair_key'
                    successor_protocol_version = 'protocol_version'
                    successor_live_route_epoch = 'live_route_epoch'
                    successor_runtime_generation = 'runtime_generation'
                    successor_terminal_generation = 'terminal_generation'
                    successor_leg_generation = 'leg_generation'
                    target_transport_epoch = 'transport_epoch'
                    successor_bridge_recovery_generation = 'bridge_recovery_generation'
                    successor_checkpoint_request_id = 'checkpoint_request_id'
                }
                [object[]]$successorYields = @($yieldEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$issued.Sequence -and
                    (Test-FallbackTailTransportReauthorizationScope -Anchor $issued -Candidate $_) -and
                    (Test-FallbackTailTransportReauthorizationFieldMap `
                        -Left $issued `
                        -Right $_ `
                        -FieldMap $successorFieldMap)
                } | Sort-Object Sequence)
                foreach ($successorYield in $successorYields) {
                    $localAuthorityFields = @(
                        'authority_id',
                        'predecessor_authority_id',
                        'transfer_id',
                        'session_id',
                        'direction',
                        'route',
                        'protocol_version',
                        'live_route_epoch',
                        'runtime_generation',
                        'terminal_generation',
                        'leg_generation',
                        'transport_epoch',
                        'bridge_recovery_generation',
                        'checkpoint_request_id',
                        'owner_key',
                        'pair_key',
                        'yield_generation')
                    if (@($coordinatorPairedEvents | Where-Object {
                            [int64]$_.Sequence -gt [int64]$successorYield.Sequence -and
                            (Test-FileTransferAuthorityFieldsEqual `
                                -LeftLine ([string]$successorYield.RawLine) `
                                -RightLine ([string]$_.RawLine) `
                                -Fields $localAuthorityFields)
                        } | Select-Object -First 1).Count -gt 0) {
                        return $true
                    }

                    [object[]]$sent = @($proofSentEvents | Where-Object {
                        [int64]$_.Sequence -gt [int64]$successorYield.Sequence -and
                        (Test-FileTransferAuthorityFieldsEqual `
                            -LeftLine ([string]$successorYield.RawLine) `
                            -RightLine ([string]$_.RawLine) `
                            -Fields $localAuthorityFields)
                    } | Sort-Object Sequence | Select-Object -First 1)
                    if ($sent.Count -gt 0 -and
                        @($pairedEvents | Where-Object {
                            [int64]$_.Sequence -gt [int64]$sent[0].Sequence -and
                            (Test-FileTransferAuthorityFieldsEqual `
                                -LeftLine ([string]$successorYield.RawLine) `
                                -RightLine ([string]$_.RawLine) `
                                -Fields $localAuthorityFields)
                        } | Select-Object -First 1).Count -gt 0) {
                        return $true
                    }
                }

                $terminalFieldMap = @{
                    predecessor_authority_id = 'predecessor_authority_id'
                    successor_authority_id = 'successor_authority_id'
                    reauthorization_generation = 'reauthorization_generation'
                    successor_protocol_version = 'protocol_version'
                    successor_live_route_epoch = 'live_route_epoch'
                    successor_runtime_generation = 'runtime_generation'
                    successor_terminal_generation = 'terminal_generation'
                    successor_leg_generation = 'leg_generation'
                    target_transport_epoch = 'transport_epoch'
                    successor_bridge_recovery_generation = 'bridge_recovery_generation'
                    successor_checkpoint_request_id = 'checkpoint_request_id'
                }
                if (@($terminalProofEvents | Where-Object {
                        [int64]$_.Sequence -gt [int64]$issued.Sequence -and
                        (Test-FallbackTailTransportReauthorizationScope -Anchor $issued -Candidate $_) -and
                        (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq
                            'post_tuna_fallback_v6' -and
                        (ConvertTo-FileTransferFallbackTailPairingValue (
                            Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '')) -eq
                            $successorAuthorityId -and
                        (Test-FallbackTailTransportReauthorizationFieldMap `
                            -Left $issued `
                            -Right $_ `
                            -FieldMap $terminalFieldMap)
                    } | Select-Object -First 1).Count -gt 0) {
                    return $true
                }
            }
        }

        return @($tunaPublicationEvents | Where-Object {
            [int64]$_.Sequence -gt $anchorSequence -and
            (Test-FallbackTailTransportReauthorizationScope -Anchor $anchor -Candidate $_)
        } | Select-Object -First 1).Count -gt 0
    }

    $qualifiedByIdentity = @{}
    $corroboratingMismatchSequences = New-Object System.Collections.Generic.List[long]
    $rawCount = 0
    foreach ($suppressed in $suppressedEvents) {
        if ((Get-FileTransferEventField -Event $suppressed -Name 'route' -Default '') -ne 'post_tuna_fallback_v6' -or
            (Get-FileTransferEventInt64Field -Event $suppressed -Name 'protocol_version' -Default 0) -ne 6) {
            continue
        }

        $currentEpoch = Get-FileTransferEventInt64Field -Event $suppressed -Name 'current_transport_epoch' -Default (
            Get-FileTransferEventInt64Field -Event $suppressed -Name 'transport_epoch' -Default -1)
        [object[]]$adoptions = @($adoptionEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$suppressed.Sequence -and
            (Test-FallbackTailTransportReauthorizationRuntimeScope `
                -Anchor $suppressed `
                -Candidate $_ `
                -ExpectedTransportEpoch $currentEpoch `
                -CandidateUsesCurrentCheckpoint)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($adoptions.Count -eq 0) {
            continue
        }

        $previousEpoch = Get-FileTransferEventInt64Field `
            -Event $adoptions[0] `
            -Name 'previous_transport_epoch' `
            -Default -1
        if ($previousEpoch -le 0 -or $currentEpoch -le $previousEpoch) {
            continue
        }

        [object[]]$predecessorYields = @($yieldEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$adoptions[0].Sequence -and
            (Test-FallbackTailTransportReauthorizationRuntimeScope `
                -Anchor $suppressed `
                -Candidate $_ `
                -ExpectedTransportEpoch $previousEpoch)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($predecessorYields.Count -eq 0) {
            continue
        }

        $predecessor = $predecessorYields[0]
        $predecessorAuthorityId = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $predecessor -Name 'authority_id' -Default '')
        $predecessorOwnerKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $predecessor -Name 'owner_key' -Default '')
        $predecessorPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $predecessor -Name 'pair_key' -Default '')
        $predecessorPredecessorAuthorityId = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $predecessor -Name 'predecessor_authority_id' -Default '')
        $predecessorYieldGeneration = Get-FileTransferEventInt64Field `
            -Event $predecessor `
            -Name 'yield_generation' `
            -Default 0
        if ($predecessorAuthorityId -eq '(none)' -or
            $predecessorOwnerKey -eq '(none)' -or
            $predecessorPairKey -eq '(none)' -or
            $predecessorYieldGeneration -le 0 -or
            -not (Test-FileTransferFallbackTailOwnerKeyMatchesEvent `
                -Event $predecessor `
                -OwnerKeyField 'owner_key')) {
            continue
        }

        $retired = @($retirementEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$suppressed.Sequence -and
            (Test-FallbackTailTransportReauthorizationScope -Anchor $suppressed -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'protocol_version' -Default 0) -eq 6 -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'live_route_epoch' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $suppressed -Name 'live_route_epoch' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $suppressed -Name 'leg_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'transport_epoch' -Default -1) -eq $previousEpoch
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($retired.Count -eq 0) {
            continue
        }

        $suppressionSchemaFields = @(
            'current_transport_epoch',
            'retired_transport_epoch',
            'current_owner_key',
            'retired_owner_key',
            'scope_relation',
            'decision_reason')
        $suppressionSchemaValues = @{}
        $hasPopulatedSuppressionSchema = $false
        foreach ($fieldName in $suppressionSchemaFields) {
            $fieldValue = Get-FileTransferEventField `
                -Event $suppressed `
                -Name $fieldName `
                -Default '__missing__'
            $suppressionSchemaValues[$fieldName] = $fieldValue
            if ($fieldValue -ne '__missing__') {
                $hasPopulatedSuppressionSchema = $true
            }
        }

        if ($hasPopulatedSuppressionSchema) {
            if (@($suppressionSchemaFields | Where-Object {
                    $suppressionSchemaValues[$_] -eq '__missing__'
                }).Count -gt 0 -or
                $suppressionSchemaValues['scope_relation'] -ne 'cross_transport_epoch' -or
                $suppressionSchemaValues['decision_reason'] -ne
                    'retired_owner_cross_transport_epoch_suppression' -or
                (Get-FileTransferEventInt64Field `
                    -Event $suppressed `
                    -Name 'current_transport_epoch' `
                    -Default -1) -ne $currentEpoch -or
                (Get-FileTransferEventInt64Field `
                    -Event $suppressed `
                    -Name 'retired_transport_epoch' `
                    -Default -1) -ne $previousEpoch -or
                (ConvertTo-FileTransferFallbackTailPairingValue (
                    [string]$suppressionSchemaValues['current_owner_key'])) -ne
                    (ConvertTo-FileTransferFallbackTailPairingValue (
                        Get-FileTransferEventField -Event $suppressed -Name 'owner_key' -Default '')) -or
                (ConvertTo-FileTransferFallbackTailPairingValue (
                    [string]$suppressionSchemaValues['retired_owner_key'])) -ne $predecessorOwnerKey -or
                -not (Test-FileTransferFallbackTailOwnerKeyMatchesEvent `
                    -Event $suppressed `
                    -OwnerKeyField 'current_owner_key')) {
                continue
            }

            $ownerKeyRelation = Get-FileTransferEventField `
                -Event $suppressed `
                -Name 'owner_key_relation' `
                -Default ''
            if (-not [string]::IsNullOrWhiteSpace($ownerKeyRelation) -and
                $ownerKeyRelation -ne 'different') {
                continue
            }
        }

        [object[]]$successorBeforeSuppression = @($yieldEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$adoptions[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$suppressed.Sequence -and
            (Test-FallbackTailTransportReauthorizationRuntimeScope `
                -Anchor $suppressed `
                -Candidate $_ `
                -ExpectedTransportEpoch $currentEpoch) -and
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '')) -eq
                $predecessorAuthorityId
        })
        if ($successorBeforeSuppression.Count -gt 0) {
            continue
        }

        $rawCount++
        [object[]]$identityParts = @(
            (Get-FileTransferEventField -Event $suppressed -Name 'session_id' -Default ''),
            (Get-FileTransferEventField -Event $suppressed -Name 'transfer_id' -Default ''),
            (Get-FileTransferEventField -Event $suppressed -Name 'direction' -Default ''),
            (Get-FileTransferEventField -Event $suppressed -Name 'live_route_epoch' -Default ''),
            (Get-FileTransferEventField -Event $suppressed -Name 'leg_generation' -Default ''),
            (Get-FileTransferEventField -Event $suppressed -Name 'bridge_recovery_generation' -Default ''),
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $suppressed -Name 'checkpoint_request_id' -Default '')),
            $previousEpoch,
            $currentEpoch,
            $predecessorAuthorityId,
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $predecessor -Name 'predecessor_authority_id' -Default '')),
            (Get-FileTransferEventField -Event $predecessor -Name 'yield_generation' -Default ''),
            $predecessorOwnerKey,
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $predecessor -Name 'pair_key' -Default '')))
        $identity = ConvertTo-Json -InputObject $identityParts -Compress -Depth 2
        if (-not $qualifiedByIdentity.ContainsKey($identity) -or
            [int64]$suppressed.Sequence -lt [int64]$qualifiedByIdentity[$identity].Event.Sequence) {
            $qualifiedByIdentity[$identity] = [pscustomobject]@{
                Event = $suppressed
                Adoption = $adoptions[0]
                Predecessor = $predecessor
                PredecessorAuthorityId = $predecessorAuthorityId
                PreviousTransportEpoch = $previousEpoch
                CurrentTransportEpoch = $currentEpoch
            }
        }

        foreach ($mismatch in @($mismatchEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$suppressed.Sequence -and
                (Test-FallbackTailTransportReauthorizationRuntimeScope `
                    -Anchor $suppressed `
                    -Candidate $_ `
                    -ExpectedTransportEpoch $currentEpoch) -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'peer_transport_epoch' -Default -1) -eq $previousEpoch -and
                (ConvertTo-FileTransferFallbackTailPairingValue (
                    Get-FileTransferEventField -Event $_ -Name 'peer_owner_key' -Default '')) -eq
                    $predecessorOwnerKey -and
                (ConvertTo-FileTransferFallbackTailPairingValue (
                    Get-FileTransferEventField -Event $_ -Name 'peer_pair_key' -Default '')) -eq
                    $predecessorPairKey -and
                (ConvertTo-FileTransferFallbackTailPairingValue (
                    Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '')) -eq
                    $predecessorPredecessorAuthorityId -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'yield_generation' -Default 0) -eq
                    $predecessorYieldGeneration -and
                (Get-FileTransferEventField -Event $_ -Name 'mismatch_kind' -Default '') -eq 'pair_scope_mismatch' -and
                (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq 'pair_scope_mismatch'
            })) {
            $corroboratingMismatchSequences.Add([int64]$mismatch.Sequence) | Out-Null
        }
    }

    foreach ($blocked in $localYieldBlockedEvents) {
        if ((Get-FileTransferEventField -Event $blocked -Name 'route' -Default '') -ne
                'post_tuna_fallback_v6' -or
            (Get-FileTransferEventInt64Field -Event $blocked -Name 'protocol_version' -Default 0) -ne 6 -or
            (Get-FileTransferEventField -Event $blocked -Name 'source' -Default '') -ne
                'fallback_tail_peer_yield' -or
            (Get-FileTransferEventField -Event $blocked -Name 'decision_reason' -Default '') -ne
                'fallback_tail_local_owner_work_pending') {
            continue
        }

        $currentEpoch = Get-FileTransferEventInt64Field `
            -Event $blocked `
            -Name 'transport_epoch' `
            -Default -1
        [object[]]$adoptions = @($adoptionEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$blocked.Sequence -and
            (Test-FallbackTailTransportReauthorizationRuntimeScope `
                -Anchor $blocked `
                -Candidate $_ `
                -ExpectedTransportEpoch $currentEpoch `
                -CandidateUsesCurrentCheckpoint)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($adoptions.Count -eq 0) {
            continue
        }

        $previousEpoch = Get-FileTransferEventInt64Field `
            -Event $adoptions[0] `
            -Name 'previous_transport_epoch' `
            -Default -1
        if ($previousEpoch -le 0 -or $currentEpoch -le $previousEpoch) {
            continue
        }

        [object[]]$predecessorYields = @($yieldEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$adoptions[0].Sequence -and
            (Test-FallbackTailTransportReauthorizationRuntimeScope `
                -Anchor $blocked `
                -Candidate $_ `
                -ExpectedTransportEpoch $previousEpoch)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($predecessorYields.Count -eq 0) {
            continue
        }

        $predecessor = $predecessorYields[0]
        $predecessorAuthorityId = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $predecessor -Name 'authority_id' -Default '')
        $predecessorOwnerKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $predecessor -Name 'owner_key' -Default '')
        $predecessorPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $predecessor -Name 'pair_key' -Default '')
        if ($predecessorAuthorityId -eq '(none)' -or
            $predecessorOwnerKey -eq '(none)' -or
            $predecessorPairKey -eq '(none)' -or
            (Get-FileTransferEventInt64Field -Event $predecessor -Name 'yield_generation' -Default 0) -le 0 -or
            -not (Test-FileTransferFallbackTailOwnerKeyMatchesEvent `
                -Event $predecessor `
                -OwnerKeyField 'owner_key')) {
            continue
        }

        [object[]]$retired = @($retirementEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$blocked.Sequence -and
            (Test-FallbackTailTransportReauthorizationScope -Anchor $blocked -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq
                'post_tuna_fallback_v6' -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'protocol_version' -Default 0) -eq 6 -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'live_route_epoch' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $blocked -Name 'live_route_epoch' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -eq
                (Get-FileTransferEventInt64Field -Event $blocked -Name 'leg_generation' -Default 0) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'transport_epoch' -Default -1) -eq
                $previousEpoch
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($retired.Count -eq 0) {
            continue
        }

        $canonicalOwnerKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $blocked -Name 'canonical_owner_key' -Default '')
        $canonicalPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $blocked -Name 'canonical_pair_key' -Default '')
        $localOwnerKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $blocked -Name 'local_owner_key' -Default '')
        $localPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $blocked -Name 'local_pair_key' -Default '')
        $peerOwnerKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $blocked -Name 'peer_owner_key' -Default '')
        $peerPairKey = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $blocked -Name 'peer_pair_key' -Default '')
        $canonicalOwnerParts = @($canonicalOwnerKey.Split('|'))
        $canonicalPairParts = @($canonicalPairKey.Split('|'))
        $checkpoint = ConvertTo-FileTransferFallbackTailPairingValue (
            Get-FileTransferEventField -Event $blocked -Name 'checkpoint_request_id_snapshot' -Default (
                Get-FileTransferEventField -Event $blocked -Name 'checkpoint_request_id' -Default ''))
        if ($canonicalOwnerParts.Count -ne 9 -or
            $canonicalPairParts.Count -ne 7 -or
            $canonicalOwnerParts[0] -ne (Get-FileTransferEventField -Event $blocked -Name 'session_id' -Default '') -or
            $canonicalOwnerParts[1] -ne (Get-FileTransferEventField -Event $blocked -Name 'transfer_id' -Default '') -or
            $canonicalOwnerParts[2] -ne 'post_tuna_fallback_v6' -or
            $canonicalOwnerParts[3] -ne '6' -or
            $canonicalOwnerParts[4] -ne (Get-FileTransferEventField -Event $blocked -Name 'live_route_epoch' -Default '') -or
            $canonicalOwnerParts[5] -ne (Get-FileTransferEventField -Event $blocked -Name 'leg_generation' -Default '') -or
            $canonicalOwnerParts[6] -ne (Get-FileTransferEventField -Event $blocked -Name 'bridge_recovery_generation' -Default '') -or
            $canonicalOwnerParts[7] -ne ([string]$currentEpoch) -or
            (ConvertTo-FileTransferFallbackTailPairingValue $canonicalOwnerParts[8]) -ne $checkpoint -or
            $canonicalPairParts[0] -ne $canonicalOwnerParts[0] -or
            $canonicalPairParts[1] -ne $canonicalOwnerParts[1] -or
            $canonicalPairParts[2] -ne $canonicalOwnerParts[2] -or
            $canonicalPairParts[3] -ne $canonicalOwnerParts[3] -or
            $canonicalPairParts[4] -ne $canonicalOwnerParts[4] -or
            $canonicalPairParts[5] -ne $canonicalOwnerParts[7] -or
            (ConvertTo-FileTransferFallbackTailPairingValue $canonicalPairParts[6]) -ne $checkpoint -or
            $peerOwnerKey -ne $canonicalOwnerKey -or
            $peerPairKey -ne $canonicalPairKey -or
            $localOwnerKey -ne $predecessorOwnerKey -or
            $localPairKey -ne $predecessorPairKey) {
            continue
        }

        [object[]]$peerProofs = @($peerProofReceivedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$adoptions[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$blocked.Sequence -and
            (Test-FallbackTailTransportReauthorizationRuntimeScope `
                -Anchor $blocked `
                -Candidate $_ `
                -ExpectedTransportEpoch $currentEpoch) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'authority_schema' -Default 0) -eq 2 -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'peer_transport_epoch' -Default -1) -eq
                $currentEpoch -and
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $_ -Name 'owner_key' -Default '')) -eq
                $canonicalOwnerKey -and
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $_ -Name 'pair_key' -Default '')) -eq
                $canonicalPairKey
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($peerProofs.Count -eq 0) {
            continue
        }

        $entry = [pscustomobject]@{
            Event = $blocked
            Adoption = $adoptions[0]
            Predecessor = $predecessor
            PredecessorAuthorityId = $predecessorAuthorityId
            PreviousTransportEpoch = $previousEpoch
            CurrentTransportEpoch = $currentEpoch
        }
        [object[]]$matchingMismatchEvents = @($mismatchEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$adoptions[0].Sequence -and
            [int64]$_.Sequence -gt [int64]$predecessor.Sequence -and
            (Test-FallbackTailTransportReauthorizationScope -Anchor $blocked -Candidate $_) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'transport_epoch' -Default -1) -eq
                $previousEpoch -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'peer_transport_epoch' -Default -1) -eq
                $currentEpoch -and
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $_ -Name 'expected_owner_key' -Default '')) -eq
                $predecessorOwnerKey -and
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $_ -Name 'expected_pair_key' -Default '')) -eq
                $predecessorPairKey -and
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $_ -Name 'peer_owner_key' -Default '')) -eq
                $canonicalOwnerKey -and
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $_ -Name 'peer_pair_key' -Default '')) -eq
                $canonicalPairKey -and
            (Get-FileTransferEventField -Event $_ -Name 'mismatch_kind' -Default '') -eq
                'pair_scope_mismatch' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
                'pair_scope_mismatch'
        })
        foreach ($mismatch in $matchingMismatchEvents) {
            $corroboratingMismatchSequences.Add([int64]$mismatch.Sequence) | Out-Null
        }

        if (@($reauthorizationStagedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$adoptions[0].Sequence -and
                [int64]$_.Sequence -lt [int64]$blocked.Sequence -and
                (Test-FallbackTailTransportReauthorizationDescriptor -Entry $entry -Descriptor $_)
            } | Select-Object -First 1).Count -gt 0) {
            continue
        }

        $rawCount++
        [object[]]$identityParts = @(
            (Get-FileTransferEventField -Event $blocked -Name 'session_id' -Default ''),
            (Get-FileTransferEventField -Event $blocked -Name 'transfer_id' -Default ''),
            (Get-FileTransferEventField -Event $blocked -Name 'direction' -Default ''),
            (Get-FileTransferEventField -Event $blocked -Name 'live_route_epoch' -Default ''),
            (Get-FileTransferEventField -Event $blocked -Name 'leg_generation' -Default ''),
            (Get-FileTransferEventField -Event $blocked -Name 'bridge_recovery_generation' -Default ''),
            $checkpoint,
            $previousEpoch,
            $currentEpoch,
            $predecessorAuthorityId,
            (ConvertTo-FileTransferFallbackTailPairingValue (
                Get-FileTransferEventField -Event $predecessor -Name 'predecessor_authority_id' -Default '')),
            (Get-FileTransferEventField -Event $predecessor -Name 'yield_generation' -Default ''),
            $predecessorOwnerKey,
            $predecessorPairKey)
        $identity = ConvertTo-Json -InputObject $identityParts -Compress -Depth 2
        if (-not $qualifiedByIdentity.ContainsKey($identity) -or
            [int64]$blocked.Sequence -lt [int64]$qualifiedByIdentity[$identity].Event.Sequence) {
            $qualifiedByIdentity[$identity] = $entry
        }

    }

    $unresolvedEvents = New-Object System.Collections.Generic.List[object]
    $recoveredCount = 0
    foreach ($identity in @($qualifiedByIdentity.Keys | Sort-Object)) {
        $entry = $qualifiedByIdentity[$identity]
        if (Test-FallbackTailTransportReauthorizationRecovered -Entry $entry) {
            $recoveredCount++
        }
        else {
            $unresolvedEvents.Add($entry.Event) | Out-Null
        }
    }

    $verdict = if ($unresolvedEvents.Count -gt 0) {
        'fail'
    }
    elseif ($qualifiedByIdentity.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }
    return [pscustomobject]@{
        Verdict = $verdict
        RawCount = $rawCount
        DistinctCount = $qualifiedByIdentity.Count
        RecoveredCount = $recoveredCount
        UnresolvedCount = $unresolvedEvents.Count
        UnresolvedCandidateEvents = @($unresolvedEvents.ToArray() | Sort-Object Sequence, LineNumber)
        CorroboratingMismatchSequences = @($corroboratingMismatchSequences.ToArray() | Select-Object -Unique)
        CoordinatorAggregateProof = $coordinatorAggregateProof
    }
}

function Get-FileTransferFallbackTailReconciliationProof {
    param(
        [Parameter(Mandatory = $true)]$Summary
    )

    [object[]]$events = @($Summary.TransferEvents)
    [object[]]$postTunaRouteSelected = @(
        $events |
            Where-Object {
                $_.EventName -eq 'filetransfer_route_selected' -and
                (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6'
            }
    )
    $hasPostTunaFallbackEvidence = $postTunaRouteSelected.Count -gt 0 -or
        @($events | Where-Object { (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' }).Count -gt 0
    [object[]]$zeroCreditBreakerEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_zero_credit_breaker' })
    [object[]]$staleFrontierRetiredEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_stale_frontier_retired' })
    [object[]]$requestedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_reconciliation_requested' })
    [object[]]$acceptedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_reconciliation_accepted' })
    [object[]]$progressForcedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_v6_post_tuna_fallback_frontier_progress_state_forced' })
    [object[]]$progressCoalescedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_progress_coalesced' })
    [object[]]$terminalProofConsumedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_terminal_proof_consumed' })
    [object[]]$quiescentYieldEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_quiescent_yield_granted' })
    [object[]]$coordinatorYieldIssuedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_yield_issued' })
    [object[]]$yieldProofSentEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_yield_proof_sent' })
    [object[]]$yieldProofReceivedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_yield_proof_received' })
    [object[]]$pairedYieldGrantedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_paired_yield_granted' })
    [object[]]$ownerGenerationMismatchEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_owner_generation_mismatch' })
    $bridgeRecoveryGenerationPairingProof = Get-FileTransferFallbackTailBridgeRecoveryPairingProof -Events $events
    [object[]]$validTerminalProofConsumedEvents = @($bridgeRecoveryGenerationPairingProof.ValidTerminalProofEvents)
    $transportEpochReauthorizationProof =
        Get-FileTransferFallbackTailTransportEpochReauthorizationProof -Events $events
    $fallbackTailCoordinatorAggregateProof =
        $transportEpochReauthorizationProof.CoordinatorAggregateProof
    [long[]]$transportEpochCorroboratingMismatchSequences = @(
        $transportEpochReauthorizationProof.CorroboratingMismatchSequences)
    [object[]]$otherOwnerGenerationMismatchEvents = @(
        $bridgeRecoveryGenerationPairingProof.OtherOwnerGenerationMismatchEvents |
            Where-Object { [int64]$_.Sequence -notin $transportEpochCorroboratingMismatchSequences })
    [object[]]$localYieldBlockedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_local_yield_blocked' })
    [object[]]$proofReplayLocalYieldBlockedEvents = @(
        $localYieldBlockedEvents |
            Where-Object { (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq 'fallback_proof_replay_pending' }
    )
    [object[]]$staleYieldProofIgnoredEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_yield_proof_stale_ignored' })
    [object[]]$yieldAuthorityRejectedEvents = @(
        Get-FileTransferFallbackTailYieldAuthorityRejectionEvents -Events $events
    )
    [object[]]$frontierRepairAuthorityGrantedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_frontier_repair_authority_granted' })
    [object[]]$frontierRepairAuthorityRejectedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_frontier_repair_authority_rejected' })
    [object[]]$frontierRepairDispatchedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_frontier_repair_dispatched' })
    [object[]]$frontierRepairStalledEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_frontier_repair_stalled' })
    [object[]]$frontierRepairContractSettledEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_frontier_repair_contract_settled' })
    [object[]]$frontierRepairSettledStalledEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_frontier_repair_settled_stalled' -or
        ($_.EventName -eq 'filetransfer_fallback_frontier_repair_contract_settled' -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'SettledStalled')
    })
    [object[]]$frontierRepairProgressObservedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_frontier_repair_progress_observed' -or
        ($_.EventName -eq 'filetransfer_fallback_frontier_repair_contract_settled' -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'ProgressObserved') -or
        $_.EventName -eq 'filetransfer_v4_frontier_stall_missing_range_filled' -or
        $_.EventName -eq 'filetransfer_v4_frontier_repair_batch_applied' -or
        $_.EventName -eq 'filetransfer_frontier_gap_repair_filled'
    })
    [object[]]$frontierRequestDeliveryAcceptedEvents = @(
        $events |
            Where-Object {
                $_.EventName -eq 'filetransfer_control_plane_delivery_result' -and
                (Get-FileTransferEventField -Event $_ -Name 'kind' -Default '') -eq 'frontier_request' -and
                (Get-FileTransferEventField -Event $_ -Name 'frame_type' -Default '') -eq 'filetransfer.frontier_request.v6' -and
                (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'protocol_version' -Default 0) -eq 6 -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'peer_visible_any' -Default 0) -gt 0 -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'accepted_any' -Default 0) -gt 0
            } |
            Sort-Object Sequence
    )
    [object[]]$frontierRequestDeliveryObservedEvents = @(
        $events |
            Where-Object {
                $_.EventName -eq 'filetransfer_control_plane_delivery_observed' -and
                (Get-FileTransferEventField -Event $_ -Name 'kind' -Default '') -eq 'frontier_request' -and
                (Get-FileTransferEventField -Event $_ -Name 'frame_type' -Default '') -eq 'filetransfer.frontier_request.v6' -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'peer_visible_any' -Default 0) -gt 0 -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'accepted_any' -Default 0) -gt 0
            } |
            Sort-Object Sequence
    )
    [object[]]$frontierRequestReceiveDispatchAttemptedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_v6_frontier_request_receive_dispatch_attempted' } | Sort-Object Sequence)
    [object[]]$frontierRequestReceiveDispatchedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_v6_frontier_request_receive_dispatched' } | Sort-Object Sequence)
    [object[]]$frontierRequestReceiveDispatchRejectedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_v6_frontier_request_receive_dispatch_rejected' } | Sort-Object Sequence)
    [object[]]$frontierRequestReceiveDispatchCoalescedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_v6_frontier_request_receive_dispatch_coalesced' } | Sort-Object Sequence)
    [object[]]$outboundQuiescentYieldEvents = @(
        $quiescentYieldEvents |
            Where-Object { (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' }
    )
    [object[]]$inboundQuiescentYieldEvents = @(
        $quiescentYieldEvents |
            Where-Object { (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'inbound' }
    )
    [object[]]$quiescenceTimeoutEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_fallback_tail_quiescence_timeout' })
    [object[]]$runtimeUnlockWaitingForFallbackEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_runtime_unlock_waiting_for_fallback_survival' })
    [object[]]$runtimeUnlockProbeRejectedByFallbackEvents = @(
        $events |
            Where-Object {
                $_.EventName -eq 'runtime_unlock_precommit_probe_rejected_for_fallback_survival' -or
                ($_.EventName -eq 'runtime_unlock_tuna_probe_ack_sent' -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'accepted' -Default 1) -eq 0 -and
                    ((Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -like '*fallback*'))
            }
    )
    [object[]]$runtimeUnlockProbeRejectedByInboundFallbackEvents = @(
        $runtimeUnlockProbeRejectedByFallbackEvents |
            Where-Object {
                (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'inbound' -or
                (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'inbound_fallback_tail_not_yielded'
            }
    )
    [object[]]$sendSlotRetiredEvents = @(
        $events |
            Where-Object {
                $_.EventName -eq 'filetransfer_post_tuna_fallback_state_refresh_send_inflight_retired' -and
                (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'tail_reconciliation_forced'
            }
    )
    [object[]]$receiveRecoveryRequestedEvents = @(
        $events |
            Where-Object {
                $_.EventName -eq 'filetransfer_post_tuna_fallback_state_refresh_receive_recovery_requested' -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'tail_reconciliation' -Default 0) -gt 0
            }
    )
    [object[]]$normalZeroCreditTailStateRefreshEvents = @(
        $events |
            Where-Object {
                $_.EventName -eq 'filetransfer_v6_regular_nkn_state_refresh_requested' -and
                (Get-FileTransferEventField -Event $_ -Name 'priority' -Default '') -eq 'state_refresh' -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'available_credit_chunks' -Default 1) -le 0 -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'highest_accepted_chunk_index' -Default -1) -ge
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'remote_frontier_chunk_index' -Default 0)
            }
    )
    [object[]]$failureEvents = @(
        $events |
            Where-Object {
                if ($_.EventName -eq 'session_liveness_timeout' -or
                    $_.EventName -eq 'filetransfer_live_progress_timeout' -or
                    $_.EventName -eq 'filetransfer_gui_progress_timeout') {
                    return $true
                }

                if ($_.EventName -eq 'file_transfer_inbound_terminal' -or
                    $_.EventName -eq 'file_transfer_outbound_terminal') {
                    return (
                        (Get-FileTransferEventField -Event $_ -Name 'state' -Default '') -ne 'Completed' -or
                        (Get-FileTransferEventField -Event $_ -Name 'error_code' -Default '(none)') -ne '(none)'
                    )
                }

                if ($_.EventName -eq 'transfer_terminal') {
                    return (Get-FileTransferEventField -Event $_ -Name 'error_code' -Default '(none)') -ne '(none)'
                }

                return $false
            }
    )
    [object[]]$cleanTerminalEvents = @(
        $events |
            Where-Object {
                if ($_.EventName -eq 'file_transfer_inbound_terminal' -or
                    $_.EventName -eq 'file_transfer_outbound_terminal') {
                    return (
                        (Get-FileTransferEventField -Event $_ -Name 'state' -Default '') -eq 'Completed' -and
                        (Get-FileTransferEventField -Event $_ -Name 'error_code' -Default '(none)') -in @('', '(none)', 'none')
                    )
                }

                if ($_.EventName -eq 'transfer_terminal') {
                    return (Get-FileTransferEventField -Event $_ -Name 'error_code' -Default '(none)') -in @('', '(none)', 'none')
                }

                return $false
            }
    )

    function Test-FallbackFrontierRepairScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($fieldName in @('transfer_id', 'session_id')) {
            $anchorValue = Get-FileTransferEventField -Event $Anchor -Name $fieldName -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $fieldName -Default ''
            if (-not [string]::IsNullOrWhiteSpace($anchorValue) -and
                $anchorValue -ne '(none)' -and
                -not [string]::IsNullOrWhiteSpace($candidateValue) -and
                $candidateValue -ne '(none)' -and
                $anchorValue -ne $candidateValue) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackFrontierRepairTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-FallbackFrontierRepairScopeMatch -Anchor $Anchor -Candidate $Candidate)) {
            return $false
        }

        $anchorSchema = Get-FileTransferAuthoritySchema -Line ([string]$Anchor.RawLine)
        $candidateSchema = Get-FileTransferAuthoritySchema -Line ([string]$Candidate.RawLine)
        if ($anchorSchema -ge 2 -or $candidateSchema -ge 2) {
            if ($anchorSchema -lt 2 -or $candidateSchema -lt 2) {
                return $false
            }

            return Test-FileTransferAuthorityTupleMatch `
                -LeftLine ([string]$Anchor.RawLine) `
                -RightLine ([string]$Candidate.RawLine)
        }

        $anchorRepairKey = Get-FileTransferEventField -Event $Anchor -Name 'repair_request_key' -Default ''
        $candidateRepairKey = Get-FileTransferEventField -Event $Candidate -Name 'repair_request_key' -Default ''
        if ([string]::IsNullOrWhiteSpace($anchorRepairKey) -or
            $anchorRepairKey -eq '(none)' -or
            [string]::IsNullOrWhiteSpace($candidateRepairKey) -or
            $candidateRepairKey -eq '(none)') {
            return $false
        }

        return $anchorRepairKey -eq $candidateRepairKey
    }

    function Test-FallbackFrontierRepairHasLaterProgress {
        param([Parameter(Mandatory = $true)]$DispatchEvent)

        $dispatchSequence = [int64]$DispatchEvent.Sequence
        return @($frontierRepairProgressObservedEvents | Where-Object {
            [int64]$_.Sequence -gt $dispatchSequence -and
            (Test-FallbackFrontierRepairTupleMatch -Anchor $DispatchEvent -Candidate $_)
        }).Count -gt 0
    }

    function Test-FallbackFrontierRepairHasLaterDispatch {
        param([Parameter(Mandatory = $true)]$AuthorityEvent)

        $authoritySequence = [int64]$AuthorityEvent.Sequence
        return @($frontierRepairDispatchedEvents | Where-Object {
            [int64]$_.Sequence -gt $authoritySequence -and
            (Test-FallbackFrontierRepairTupleMatch -Anchor $AuthorityEvent -Candidate $_)
        }).Count -gt 0
    }

    function Test-FallbackFrontierRepairStallHasLaterSuccessor {
        param([Parameter(Mandatory = $true)]$StallEvent)

        $settlement = @($frontierRepairContractSettledEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$StallEvent.Sequence -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'SettledStalled' -and
                (Test-FallbackFrontierRepairTupleMatch -Anchor $StallEvent -Candidate $_)
            } | Sort-Object Sequence | Select-Object -First 1)
        if ($settlement.Count -ne 1) {
            return $false
        }

        return @($frontierRepairAuthorityGrantedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$settlement[0].Sequence -and
                (Test-FallbackFrontierRepairSuccessorTupleMatch -Predecessor $StallEvent -Successor $_)
            }).Count -eq 1
    }

    function Test-FallbackFrontierRepairSuccessorTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Predecessor,
            [Parameter(Mandatory = $true)]$Successor
        )

        if ((Get-FileTransferAuthoritySchema -Line ([string]$Predecessor.RawLine)) -lt 2 -or
            (Get-FileTransferAuthoritySchema -Line ([string]$Successor.RawLine)) -lt 2) {
            return $false
        }

        $predecessorAuthorityId = Get-FileTransferEventField -Event $Predecessor -Name 'authority_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($predecessorAuthorityId) -or
            $predecessorAuthorityId -eq '(none)' -or
            (Get-FileTransferEventField -Event $Successor -Name 'predecessor_authority_id' -Default '') -ne $predecessorAuthorityId) {
            return $false
        }

        foreach ($fieldName in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'bridge_decision_generation',
                'checkpoint_request_id',
                'route_publication_generation',
                'route_commit_generation',
                'repair_request_key',
                'range_fingerprint',
                'frontier_chunk_index',
                'durable_received_highest_chunk_index',
                'range_count',
                'requested_chunk_count',
                'source_kind',
                'priority',
                'recovery_mode',
                'target_transport')) {
            $predecessorValue = Get-FileTransferEventField -Event $Predecessor -Name $fieldName -Default ''
            $successorValue = Get-FileTransferEventField -Event $Successor -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($predecessorValue) -or
                [string]::IsNullOrWhiteSpace($successorValue) -or
                $predecessorValue -ne $successorValue) {
                return $false
            }
        }

        $predecessorGeneration = Get-FileTransferEventInt64Field -Event $Predecessor -Name 'repair_generation' -Default -1
        $successorGeneration = Get-FileTransferEventInt64Field -Event $Successor -Name 'repair_generation' -Default -1
        return $predecessorGeneration -ge 0 -and $successorGeneration -eq ($predecessorGeneration + 1)
    }

    function Test-FallbackFrontierRepairHasLaterFailure {
        param([Parameter(Mandatory = $true)]$Anchor)

        $anchorSequence = [int64]$Anchor.Sequence
        return @($failureEvents | Where-Object {
            [int64]$_.Sequence -gt $anchorSequence -and
            (Test-FallbackFrontierRepairScopeMatch -Anchor $Anchor -Candidate $_)
        }).Count -gt 0
    }

    function Test-FallbackFrontierRepairHasLaterCleanTerminal {
        param([Parameter(Mandatory = $true)]$Anchor)

        $anchorSequence = [int64]$Anchor.Sequence
        return @($cleanTerminalEvents | Where-Object {
            [int64]$_.Sequence -gt $anchorSequence -and
            (Test-FallbackFrontierRepairScopeMatch -Anchor $Anchor -Candidate $_)
        }).Count -gt 0
    }

    function Test-FallbackFrontierRequestHasLaterDispatchOutcome {
        param([Parameter(Mandatory = $true)]$DeliveryEvent)

        $deliverySequence = [int64]$DeliveryEvent.Sequence
        if (@($frontierRequestReceiveDispatchedEvents + $frontierRequestReceiveDispatchRejectedEvents + $frontierRequestReceiveDispatchCoalescedEvents | Where-Object {
            [int64]$_.Sequence -gt $deliverySequence -and
            (Test-FallbackFrontierRequestDispatchTupleMatch -Anchor $DeliveryEvent -Candidate $_)
        }).Count -gt 0) {
            return $true
        }

        foreach ($observed in @($frontierRequestDeliveryObservedEvents | Where-Object {
                    [int64]$_.Sequence -gt $deliverySequence -and
                    (Test-FallbackFrontierRequestObservedDeliveryTupleMatch -Delivery $DeliveryEvent -Observed $_)
                })) {
            if (@($frontierRepairDispatchedEvents | Where-Object {
                        [int64]$_.Sequence -gt [int64]$observed.Sequence -and
                        (Test-FallbackFrontierRequestObservedRepairDispatchTupleMatch -Observed $observed -Dispatch $_)
                    }).Count -gt 0) {
                return $true
            }
        }

        return $false
    }

    function Test-FallbackFrontierRequestObservedDeliveryTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Delivery,
            [Parameter(Mandatory = $true)]$Observed
        )

        if ((Get-FileTransferAuthoritySchema -Line ([string]$Delivery.RawLine)) -lt 2 -or
            (Get-FileTransferAuthoritySchema -Line ([string]$Observed.RawLine)) -lt 2) {
            return $false
        }

        foreach ($fieldName in @(
                'authority_id',
                'control_plane_generation',
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'leg_generation',
                'bridge_recovery_generation',
                'transport_epoch',
                'checkpoint_request_id',
                'kind',
                'frame_type',
                'reason',
                'repair_request_id',
                'request_correlation_id',
                'first_start_chunk_index',
                'first_chunk_count',
                'range_count',
                'recovery_mode',
                'priority')) {
            $deliveryValue = Get-FileTransferEventField -Event $Delivery -Name $fieldName -Default ''
            $observedValue = Get-FileTransferEventField -Event $Observed -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($deliveryValue) -or
                [string]::IsNullOrWhiteSpace($observedValue) -or
                $deliveryValue -ne $observedValue) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackFrontierRequestObservedRepairDispatchTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Observed,
            [Parameter(Mandatory = $true)]$Dispatch
        )

        if ((Get-FileTransferAuthoritySchema -Line ([string]$Dispatch.RawLine)) -lt 2 -or
            (Get-FileTransferEventField -Event $Dispatch -Name 'source_kind' -Default '') -ne 'ReceiverRequest' -or
            (Get-FileTransferEventField -Event $Dispatch -Name 'stage' -Default '') -ne 'receiver_request_send' -or
            (Get-FileTransferEventInt64Field -Event $Dispatch -Name 'dispatch_observed' -Default 0) -ne 1) {
            return $false
        }

        foreach ($fieldName in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'leg_generation',
                'bridge_recovery_generation',
                'transport_epoch',
                'checkpoint_request_id',
                'range_fingerprint',
                'range_count',
                'recovery_mode',
                'priority')) {
            $observedValue = Get-FileTransferEventField -Event $Observed -Name $fieldName -Default ''
            $dispatchValue = Get-FileTransferEventField -Event $Dispatch -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($observedValue) -or
                [string]::IsNullOrWhiteSpace($dispatchValue) -or
                $observedValue -ne $dispatchValue) {
                return $false
            }
        }

        $repairKey = Get-FileTransferEventField -Event $Observed -Name 'repair_request_key' -Default ''
        $dispatchRepairKey = Get-FileTransferEventField -Event $Dispatch -Name 'repair_request_key' -Default ''
        if ([string]::IsNullOrWhiteSpace($repairKey) -or $repairKey -eq '(none)' -or
            $repairKey -ne $dispatchRepairKey) {
            return $false
        }

        if (@($frontierRepairAuthorityGrantedEvents | Where-Object {
                    [int64]$_.Sequence -lt [int64]$Dispatch.Sequence -and
                    (Test-FallbackFrontierRequestRepairAuthorityGrantTupleMatch -Grant $_ -Dispatch $Dispatch)
                }).Count -ne 1) {
            return $false
        }

        $repairRequestId = Get-FileTransferEventField -Event $Observed -Name 'repair_request_id' -Default ''
        $dispatchRepairRequestId = Get-FileTransferEventField -Event $Dispatch -Name 'primary_protocol_repair_request_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($dispatchRepairRequestId)) {
            $dispatchRepairRequestId = Get-FileTransferEventField -Event $Dispatch -Name 'protocol_repair_request_id' -Default ''
        }
        $requestCorrelationId = Get-FileTransferEventField -Event $Observed -Name 'request_correlation_id' -Default ''
        $dispatchCorrelationId = Get-FileTransferEventField -Event $Dispatch -Name 'primary_request_correlation_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($dispatchCorrelationId)) {
            $dispatchCorrelationId = Get-FileTransferEventField -Event $Dispatch -Name 'request_correlation_id' -Default ''
        }
        if ([string]::IsNullOrWhiteSpace($repairRequestId) -or
            $repairRequestId -ne $dispatchRepairRequestId -or
            [string]::IsNullOrWhiteSpace($requestCorrelationId) -or
            $requestCorrelationId -ne $dispatchCorrelationId) {
            return $false
        }

        $firstStart = Get-FileTransferEventInt64Field -Event $Observed -Name 'first_start_chunk_index' -Default -1
        $firstCount = Get-FileTransferEventInt64Field -Event $Observed -Name 'requested_chunk_count' -Default -1
        if ($firstCount -lt 0) {
            $firstCount = Get-FileTransferEventInt64Field -Event $Observed -Name 'first_chunk_count' -Default -1
        }
        return $firstStart -ge 0 -and
            $firstStart -eq (Get-FileTransferEventInt64Field -Event $Dispatch -Name 'frontier_chunk_index' -Default -1) -and
            $firstCount -gt 0 -and
            $firstCount -eq (Get-FileTransferEventInt64Field -Event $Dispatch -Name 'requested_chunk_count' -Default -1)
    }

    function Test-FallbackFrontierRequestRepairAuthorityGrantTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Grant,
            [Parameter(Mandatory = $true)]$Dispatch
        )

        if ((Get-FileTransferAuthoritySchema -Line ([string]$Grant.RawLine)) -lt 2) {
