                'filetransfer_v6_receiver_state_sent',
                'filetransfer_v4_state_sent')
        }
        'checkpoint' {
            return $name -in @(
                'filetransfer_fallback_checkpoint_requested',
                'filetransfer_fallback_checkpoint_accepted',
