function New-FileTransferFileTunaV4DataPathCorrelationIndex {
    param([object[]]$Events = @())

    $payloadEvents = @{}
    $writerSequenceEvents = @{}
    $terminalEventsByScope = @{}
    $receiverTransitionsByWriterScope = @{}
    $orderedEvents = @($Events | Sort-Object Sequence, LineNumber)
    $buildVisitCount = 0L

    foreach ($event in @($orderedEvents)) {
        $buildVisitCount++
        $payloadKey =
            Get-FileTransferFileTunaV4DataPathPayloadIdentityKey -Event $event
        if (-not [string]::IsNullOrWhiteSpace($payloadKey)) {
            Add-FileTransferFileTunaV4DataPathIndexEvent `
                -Lookup $payloadEvents `
                -Key $payloadKey `
                -Event $event
        }

        $writerId =
            Get-FileTransferEventField -Event $event -Name 'log_writer_id' -Default ''
        $writerSequence =
            Get-FileTransferEventInt64Field `
                -Event $event `
                -Name 'log_writer_sequence' `
                -Default 0
        if (-not [string]::IsNullOrWhiteSpace($writerId) -and
            $writerSequence -gt 0) {
            $writerKey = $writerId.ToLowerInvariant()
            if (-not $writerSequenceEvents.ContainsKey($writerKey)) {
                $writerSequenceEvents[$writerKey] = @{}
            }

            $sequenceKey = [string]$writerSequence
            Add-FileTransferFileTunaV4DataPathIndexEvent `
                -Lookup $writerSequenceEvents[$writerKey] `
                -Key $sequenceKey `
                -Event $event
        }

        $scopeKey =
            Get-FileTransferFileTunaV4DataPathTransferScopeKey -Event $event
        if ($event.EventName -in @(
                'file_transfer_outbound_terminal',
                'file_transfer_inbound_terminal',
                'transfer_terminal',
                'filetransfer_runtime_terminalized') -and
            -not [string]::IsNullOrWhiteSpace($scopeKey)) {
            Add-FileTransferFileTunaV4DataPathIndexEvent `
                -Lookup $terminalEventsByScope `
                -Key $scopeKey `
                -Event $event
        }

        if ($event.EventName -eq 'filetransfer_route_transitioned' -and
            -not [string]::IsNullOrWhiteSpace($writerId) -and
            -not [string]::IsNullOrWhiteSpace($scopeKey)) {
            $writerScopeKey =
                "{0}|{1}" -f $writerId.ToLowerInvariant(), $scopeKey
            Add-FileTransferFileTunaV4DataPathIndexEvent `
                -Lookup $receiverTransitionsByWriterScope `
                -Key $writerScopeKey `
                -Event $event
        }
    }

    return [pscustomobject]@{
        OrderedEvents = $orderedEvents
        PayloadEvents = $payloadEvents
        WriterSequenceEvents = $writerSequenceEvents
        TerminalEventsByScope = $terminalEventsByScope
        ReceiverTransitionsByWriterScope = $receiverTransitionsByWriterScope
        Statistics = [ordered]@{
            build_visit_count = $buildVisitCount
            bounded_lookup_visit_count = 0L
            payload_key_count = $payloadEvents.Count
            writer_count = $writerSequenceEvents.Count
        }
    }
}

function Get-FileTransferFileTunaV4DataPathIndexedPayloadEvents {
    param(
        [Parameter(Mandatory = $true)]$Index,
        [Parameter(Mandatory = $true)]$Event
    )

    $key = Get-FileTransferFileTunaV4DataPathPayloadIdentityKey -Event $Event
    if ([string]::IsNullOrWhiteSpace($key) -or
        -not $Index.PayloadEvents.ContainsKey($key)) {
        return @()
    }

    [object[]]$events = $Index.PayloadEvents[$key].ToArray()
    $Index.Statistics.bounded_lookup_visit_count += $events.Count
    return $events
}

function Get-FileTransferFileTunaV4DataPathIndexedWriterWindow {
    param(
        [Parameter(Mandatory = $true)]$Index,
        [Parameter(Mandatory = $true)][string]$WriterId,
        [Parameter(Mandatory = $true)][int64]$AfterSequence,
        [int]$WindowSize = 8
    )

    if ([string]::IsNullOrWhiteSpace($WriterId) -or $WindowSize -le 0) {
        return @()
    }

    $writerKey = $WriterId.ToLowerInvariant()
    if (-not $Index.WriterSequenceEvents.ContainsKey($writerKey)) {
        return @()
    }

    $events = New-Object System.Collections.Generic.List[object]
    $sequenceLookup = $Index.WriterSequenceEvents[$writerKey]
    for ($offset = 1; $offset -le $WindowSize; $offset++) {
        $Index.Statistics.bounded_lookup_visit_count++
        $sequenceKey = [string]($AfterSequence + $offset)
        if ($sequenceLookup.ContainsKey($sequenceKey)) {
            foreach ($event in $sequenceLookup[$sequenceKey].ToArray()) {
                $events.Add($event) | Out-Null
            }
        }
    }

    return @($events.ToArray())
}

function Get-FileTransferFileTunaV4DataPathIndexedTerminalEvents {
    param(
        [Parameter(Mandatory = $true)]$Index,
        [Parameter(Mandatory = $true)]$Event
    )

    $key = Get-FileTransferFileTunaV4DataPathTransferScopeKey -Event $Event
    if ([string]::IsNullOrWhiteSpace($key) -or
        -not $Index.TerminalEventsByScope.ContainsKey($key)) {
        return @()
    }

    [object[]]$events = $Index.TerminalEventsByScope[$key].ToArray()
    $Index.Statistics.bounded_lookup_visit_count += $events.Count
    return $events
}

function Get-FileTransferFileTunaV4DataPathIndexedReceiverTransitions {
    param(
        [Parameter(Mandatory = $true)]$Index,
        [Parameter(Mandatory = $true)]$Event,
        [Parameter(Mandatory = $true)][string]$WriterId
    )

    $scopeKey =
        Get-FileTransferFileTunaV4DataPathTransferScopeKey -Event $Event
    if ([string]::IsNullOrWhiteSpace($scopeKey) -or
        [string]::IsNullOrWhiteSpace($WriterId)) {
        return @()
    }

    $key = "{0}|{1}" -f $WriterId.ToLowerInvariant(), $scopeKey
    if (-not $Index.ReceiverTransitionsByWriterScope.ContainsKey($key)) {
        return @()
    }

    [object[]]$events =
        $Index.ReceiverTransitionsByWriterScope[$key].ToArray()
    $Index.Statistics.bounded_lookup_visit_count += $events.Count
    return $events
}

function Test-FileTransferFileTunaV4DataPathMismatchRejectedFailClosed {
    param(
        [Parameter(Mandatory = $true)]$Mismatch,
        [Parameter(Mandatory = $true)][object[]]$Events,
        $DataPathIndex = $null
    )

    if ($null -eq $DataPathIndex) {
        $DataPathIndex =
            New-FileTransferFileTunaV4DataPathCorrelationIndex -Events $Events
    }

    $proofDirection = Get-FileTransferEventField -Event $Mismatch -Name 'proof_direction' -Default ''
    if ($Mismatch.EventName -ne 'filetransfer_data_path_receive_result' -and
        -not ($Mismatch.EventName -eq 'filetransfer_tuna_data_path_mismatch' -and $proofDirection -eq 'receive')) {
        return $false
    }

    $writerId = Get-FileTransferEventField -Event $Mismatch -Name 'log_writer_id' -Default ''
    $writerSequence = Get-FileTransferEventInt64Field -Event $Mismatch -Name 'log_writer_sequence' -Default 0
    if ([string]::IsNullOrWhiteSpace($writerId) -or $writerSequence -le 0) {
        return $false
    }

    $ignoredWindowAnchorSequence = $writerSequence
    if ($Mismatch.EventName -eq 'filetransfer_data_path_receive_result') {
        [object[]]$exactMismatchCompanions = @(
            Get-FileTransferFileTunaV4DataPathIndexedWriterWindow `
                -Index $DataPathIndex `
                -WriterId $writerId `
                -AfterSequence $writerSequence |
            Where-Object {
                $companion = $_
                if ($companion.EventName -ne 'filetransfer_tuna_data_path_mismatch' -or
                    (Get-FileTransferEventField -Event $companion -Name 'proof_direction' -Default '') -ne 'receive' -or
                    (Get-FileTransferEventField -Event $companion -Name 'mismatch_reason' -Default '') -ne 'file_tuna_v4_resolved_to_regular_nkn' -or
                    -not [string]::Equals(
                        (Get-FileTransferEventField -Event $companion -Name 'log_writer_id' -Default ''),
                        $writerId,
                        [System.StringComparison]::OrdinalIgnoreCase) -or
                    (Get-FileTransferEventInt64Field -Event $companion -Name 'log_writer_sequence' -Default 0) -le $writerSequence -or
                    (Get-FileTransferEventInt64Field -Event $companion -Name 'log_writer_sequence' -Default 0) -gt ($writerSequence + 8) -or
                    (Get-FileTransferEventField -Event $companion -Name 'actual_transport' -Default '') -ne 'regular_nkn' -or
                    (Get-FileTransferEventField -Event $companion -Name 'delivery_transport' -Default '') -ne 'regular_nkn' -or
                    (Get-FileTransferEventField -Event $companion -Name 'target_transport' -Default '') -ne 'tuna' -or
                    (Get-FileTransferEventInt64Field -Event $companion -Name 'raw_payload_bytes' -Default 0) -ne
                        (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'raw_payload_bytes' -Default 0) -or
                    (Get-FileTransferEventInt64Field -Event $companion -Name 'batch_chunk_count' -Default 0) -ne
                        (Get-FileTransferEventInt64Field -Event $Mismatch -Name 'batch_chunk_count' -Default 0) -or
                    -not (Test-FileTransferFileTunaV4DataPathRangeMatches -Intent $Mismatch -Actual $companion)) {
                    return $false
                }

                foreach ($fieldName in @(
                        'transfer_id',
                        'session_id',
                        'frame_type',
                        'direction',
                        'route',
                        'protocol_version',
                        'live_route_epoch',
                        'runtime_generation',
                        'terminal_generation',
                        'leg_generation',
                        'route_publication_generation',
                        'route_commit_generation')) {
                    $mismatchFieldValue = Get-FileTransferEventField `
                        -Event $Mismatch `
                        -Name $fieldName `
                        -Default ''
                    $companionFieldValue = Get-FileTransferEventField `
                        -Event $companion `
                        -Name $fieldName `
                        -Default ''
                    if ([string]::IsNullOrWhiteSpace($mismatchFieldValue) -or
                        [string]::IsNullOrWhiteSpace($companionFieldValue)) {
                        return $false
                    }

                    if (-not [string]::Equals(
                            $mismatchFieldValue,
                            $companionFieldValue,
                            [System.StringComparison]::OrdinalIgnoreCase)) {
                        return $false
                    }
                }

                if (-not (Test-FileTransferFileTunaV4DataPathHasRange -Event $Mismatch) -or
                    -not (Test-FileTransferFileTunaV4DataPathHasRange -Event $companion)) {
                    return $false
                }

                return $true
            })
        if ($exactMismatchCompanions.Count -ne 1) {
            return $false
        }

        $ignoredWindowAnchorSequence = Get-FileTransferEventInt64Field `
            -Event $exactMismatchCompanions[0] `
            -Name 'log_writer_sequence' `
            -Default 0
    }

    $mismatchSequence = if ($null -ne $Mismatch.PSObject.Properties['Sequence']) { [int64]$Mismatch.Sequence } else { 0L }
    [object[]]$ignoredEvents = @(
        Get-FileTransferFileTunaV4DataPathIndexedWriterWindow `
            -Index $DataPathIndex `
            -WriterId $writerId `
            -AfterSequence $ignoredWindowAnchorSequence |
        Where-Object {
            $_.EventName -eq 'filetransfer_data_frame_ignored' -and
            (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
                'file_tuna_v4_payload_requires_tuna'
        })
    foreach ($ignored in @($ignoredEvents)) {
        $ignoredWriterId = Get-FileTransferEventField -Event $ignored -Name 'log_writer_id' -Default ''
        $ignoredWriterSequence = Get-FileTransferEventInt64Field -Event $ignored -Name 'log_writer_sequence' -Default 0
        if (-not [string]::Equals($writerId, $ignoredWriterId, [System.StringComparison]::OrdinalIgnoreCase) -or
            $ignoredWriterSequence -le $ignoredWindowAnchorSequence -or
            $ignoredWriterSequence -gt ($ignoredWindowAnchorSequence + 8)) {
            continue
        }

        $scopeMatches = $true
        foreach ($fieldName in @('transfer_id', 'session_id', 'frame_type', 'route', 'protocol_version')) {
            $mismatchValue = Get-FileTransferEventField -Event $Mismatch -Name $fieldName -Default ''
            $ignoredValue = Get-FileTransferEventField -Event $ignored -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($mismatchValue) -or
                [string]::IsNullOrWhiteSpace($ignoredValue) -or
                -not [string]::Equals($mismatchValue, $ignoredValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                $scopeMatches = $false
                break
            }
        }

        if (-not $scopeMatches -or
            -not (Test-FileTransferFileTunaV4DataPathRangeMatches -Intent $Mismatch -Actual $ignored)) {
            continue
        }

        $actualTransport = Get-FileTransferEventField -Event $ignored -Name 'actual_transport' -Default ''
        $targetTransport = Get-FileTransferEventField -Event $ignored -Name 'target_transport' -Default ''
        if ($actualTransport -ne 'regular_nkn' -or $targetTransport -ne 'tuna') {
            continue
        }

        $mismatchTransferId = Get-FileTransferEventField -Event $Mismatch -Name 'transfer_id' -Default ''
        $mismatchSessionId = Get-FileTransferEventField -Event $Mismatch -Name 'session_id' -Default ''
        $mismatchFrameType = Get-FileTransferEventField -Event $Mismatch -Name 'frame_type' -Default ''
        $mismatchRangeStart = Get-FileTransferFileTunaV4DataPathRangeStart -Event $Mismatch
        $mismatchRangeEndExclusive = Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $Mismatch
        $mismatchRawBytes = Get-FileTransferEventInt64Field -Event $Mismatch -Name 'raw_payload_bytes' -Default 0
        $mismatchChunkCount = Get-FileTransferEventInt64Field -Event $Mismatch -Name 'batch_chunk_count' -Default 0
        [object[]]$sourceSends = @(
            Get-FileTransferFileTunaV4DataPathIndexedPayloadEvents `
                -Index $DataPathIndex `
                -Event $Mismatch |
            Where-Object {
                $_.EventName -eq 'filetransfer_data_path_send_result' -and
                $_.Sequence -lt $mismatchSequence -and
                (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
                (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'regular_nkn_v4_fast' -and
                (Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '4' -and
                (Get-FileTransferEventField -Event $_ -Name 'actual_transport' -Default '') -eq 'regular_nkn' -and
                (Get-FileTransferEventField -Event $_ -Name 'delivery_transport' -Default '') -eq 'regular_nkn' -and
                (Get-FileTransferEventField -Event $_ -Name 'delivery_result' -Default '') -eq 'sent' -and
                (Get-FileTransferEventField -Event $_ -Name 'target_transport' -Default '') -eq 'regular_nkn' -and
                (Get-FileTransferEventField -Event $_ -Name 'target_route' -Default '') -eq 'regular_nkn_v4_fast' -and
                (Get-FileTransferEventField -Event $_ -Name 'target_protocol_version' -Default '') -eq '4' -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'runtime_generation' -Default 0) -gt 0 -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -gt 0 -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'route_publication_generation' -Default 0) -gt 0 -and
                [string]::Equals((Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default ''), $mismatchTransferId, [System.StringComparison]::OrdinalIgnoreCase) -and
                [string]::Equals((Get-FileTransferEventField -Event $_ -Name 'session_id' -Default ''), $mismatchSessionId, [System.StringComparison]::OrdinalIgnoreCase) -and
                [string]::Equals((Get-FileTransferEventField -Event $_ -Name 'frame_type' -Default ''), $mismatchFrameType, [System.StringComparison]::OrdinalIgnoreCase) -and
                (Get-FileTransferFileTunaV4DataPathRangeStart -Event $_) -eq $mismatchRangeStart -and
                (Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $_) -eq $mismatchRangeEndExclusive -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'raw_payload_bytes' -Default 0) -eq $mismatchRawBytes -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'batch_chunk_count' -Default 0) -eq $mismatchChunkCount
            } | Sort-Object Sequence -Descending)
        foreach ($sourceSend in @($sourceSends)) {
            $sourceWriterId = Get-FileTransferEventField -Event $sourceSend -Name 'log_writer_id' -Default ''
            if ([string]::IsNullOrWhiteSpace($sourceWriterId) -or
                [string]::Equals($sourceWriterId, $writerId, [System.StringComparison]::OrdinalIgnoreCase)) {
                continue
            }

            $sourceRawBytes = Get-FileTransferEventInt64Field -Event $sourceSend -Name 'raw_payload_bytes' -Default 0
            $sourceChunkCount = Get-FileTransferEventInt64Field -Event $sourceSend -Name 'batch_chunk_count' -Default 0
            if ($sourceRawBytes -le 0 -or $mismatchRawBytes -le 0 -or $sourceRawBytes -ne $mismatchRawBytes -or
                $sourceChunkCount -le 0 -or $mismatchChunkCount -le 0 -or $sourceChunkCount -ne $mismatchChunkCount) {
                continue
            }

            [object[]]$terminalBoundaries = @(
                Get-FileTransferFileTunaV4DataPathIndexedTerminalEvents `
                    -Index $DataPathIndex `
                    -Event $Mismatch |
                Where-Object {
                    $_.Sequence -gt $sourceSend.Sequence -and
                    $_.Sequence -lt $mismatchSequence -and
                    $_.EventName -in @(
                        'file_transfer_outbound_terminal',
                        'file_transfer_inbound_terminal',
                        'transfer_terminal',
                        'filetransfer_runtime_terminalized') -and
                    [string]::Equals(
                        (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default ''),
                        $mismatchTransferId,
                        [System.StringComparison]::OrdinalIgnoreCase) -and
                    [string]::Equals(
                        (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default ''),
                        $mismatchSessionId,
                        [System.StringComparison]::OrdinalIgnoreCase)
                })
            if ($terminalBoundaries.Count -gt 0) {
                continue
            }

            [object[]]$receiverTransitions = @(
                Get-FileTransferFileTunaV4DataPathIndexedReceiverTransitions `
                    -Index $DataPathIndex `
                    -Event $Mismatch `
                    -WriterId $writerId |
                Where-Object {
                    $_.EventName -eq 'filetransfer_route_transitioned' -and
                    $_.Sequence -gt $sourceSend.Sequence -and
                    $_.Sequence -lt $mismatchSequence -and
                    (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'inbound' -and
                    (Get-FileTransferEventField -Event $_ -Name 'previous_route' -Default '') -eq 'regular_nkn_v4_fast' -and
                    (Get-FileTransferEventField -Event $_ -Name 'new_route' -Default '') -eq 'file_tuna_v4' -and
                    [string]::Equals(
                        (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                        $writerId,
                        [System.StringComparison]::OrdinalIgnoreCase)
                } | Sort-Object Sequence -Descending)
            $matchingReceiverTransitionCount = 0
            foreach ($receiverTransition in @($receiverTransitions)) {
                $transitionMatches = $true
                foreach ($fieldName in @(
                        'transfer_id',
                        'session_id',
                        'route',
                        'protocol_version',
                        'live_route_epoch',
                        'runtime_generation',
                        'terminal_generation',
                        'leg_generation',
                        'route_publication_generation',
                        'route_commit_generation')) {
                    $transitionValue = Get-FileTransferEventField -Event $receiverTransition -Name $fieldName -Default ''
                    $mismatchValue = Get-FileTransferEventField -Event $Mismatch -Name $fieldName -Default ''
                    if ([string]::IsNullOrWhiteSpace($transitionValue) -or
                        [string]::IsNullOrWhiteSpace($mismatchValue) -or
                        -not [string]::Equals($transitionValue, $mismatchValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                        $transitionMatches = $false
                        break
                    }
                }

                if ($transitionMatches) {
                    $matchingReceiverTransitionCount++
                }
            }
            if ($matchingReceiverTransitionCount -eq 1) {
                return $true
            }
        }
    }

    return $false
}

function Test-FileTransferFileTunaV4DataPathScopeMatches {
    param(
        [Parameter(Mandatory = $true)]$Intent,
        [Parameter(Mandatory = $true)]$Actual
    )

    foreach ($fieldName in @('transfer_id', 'session_id', 'route_publication_generation', 'runtime_generation', 'terminal_generation', 'leg_generation', 'live_route_epoch')) {
        $intentValue = Get-FileTransferEventField -Event $Intent -Name $fieldName -Default ''
        if ([string]::IsNullOrWhiteSpace($intentValue)) {
            continue
        }

        $actualValue = Get-FileTransferEventField -Event $Actual -Name $fieldName -Default ''
        if ([string]::IsNullOrWhiteSpace($actualValue) -or
            -not [string]::Equals($intentValue, $actualValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Get-FileTransferFileTunaV4DataPathScopeKey {
    param([Parameter(Mandatory = $true)]$Event)

    $values = New-Object System.Collections.Generic.List[string]
    foreach ($fieldName in @('transfer_id', 'session_id', 'route_publication_generation', 'runtime_generation', 'terminal_generation', 'leg_generation', 'live_route_epoch')) {
        $value = Get-FileTransferEventField -Event $Event -Name $fieldName -Default ''
        if ([string]::IsNullOrWhiteSpace($value)) {
            return ''
        }

        $values.Add($value.ToLowerInvariant()) | Out-Null
    }

    return [string]::Join('|', $values)
}

function Get-FileTransferFileTunaV4DataPathRangeKey {
    param([Parameter(Mandatory = $true)]$Event)

    $scopeKey = Get-FileTransferFileTunaV4DataPathScopeKey -Event $Event
    if ([string]::IsNullOrWhiteSpace($scopeKey) -or
        -not (Test-FileTransferFileTunaV4DataPathHasRange -Event $Event)) {
        return ''
    }

    $start = Get-FileTransferFileTunaV4DataPathRangeStart -Event $Event
    $endExclusive = Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $Event
    if ($start -lt 0 -or $endExclusive -le $start) {
        return ''
    }

    return ("{0}|{1}|{2}" -f $scopeKey, $start, $endExclusive)
}

function Get-FileTransferFileTunaV4DataPathRangeStart {
    param([Parameter(Mandatory = $true)]$Event)

    $start = Get-FileTransferEventInt64Field -Event $Event -Name 'start_chunk_index' -Default -1
    if ($start -ge 0) {
        return $start
    }

    $start = Get-FileTransferEventInt64Field -Event $Event -Name 'first_start_chunk_index' -Default -1
    if ($start -ge 0) {
        return $start
    }

    $chunkIndex = Get-FileTransferEventField -Event $Event -Name 'chunk_index' -Default ''
    if ($chunkIndex -match '^(\d+)(?:-(\d+))?$') {
        return [int64]$Matches[1]
    }

    return -1
}

function Get-FileTransferFileTunaV4DataPathRangeEndExclusive {
    param([Parameter(Mandatory = $true)]$Event)

    $endExclusive = Get-FileTransferEventInt64Field -Event $Event -Name 'last_end_chunk_exclusive' -Default -1
    if ($endExclusive -gt 0) {
        return $endExclusive
    }

    $start = Get-FileTransferFileTunaV4DataPathRangeStart -Event $Event
    if ($start -lt 0) {
        return -1
    }

    $chunkIndex = Get-FileTransferEventField -Event $Event -Name 'chunk_index' -Default ''
    if ($chunkIndex -match '^\d+-(\d+)$') {
        return [int64]$Matches[1] + 1
    }

    $count = Get-FileTransferEventInt64Field -Event $Event -Name 'batch_chunk_count' -Default 0
    if ($count -le 0) {
        $count = Get-FileTransferEventInt64Field -Event $Event -Name 'sent_chunk_count' -Default 0
    }
    if ($count -le 0) {
        $count = Get-FileTransferEventInt64Field -Event $Event -Name 'frame_chunk_count' -Default 0
    }

    if ($count -le 0) {
        return -1
    }

    return $start + $count
}

function Test-FileTransferFileTunaV4DataPathHasRange {
    param([Parameter(Mandatory = $true)]$Event)

    $start = Get-FileTransferFileTunaV4DataPathRangeStart -Event $Event
    $endExclusive = Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $Event
    return $start -ge 0 -and $endExclusive -gt $start
}

function Test-FileTransferFileTunaV4DataPathSequenceAllowsMatch {
    param(
        [Parameter(Mandatory = $true)]$Intent,
        [Parameter(Mandatory = $true)]$Actual
    )

    if ((Test-FileTransferFileTunaV4DataPathHasRange -Event $Intent) -and
        (Test-FileTransferFileTunaV4DataPathHasRange -Event $Actual)) {
        return $true
    }

    if ($null -ne $Intent.PSObject.Properties['Sequence'] -and
        $null -ne $Actual.PSObject.Properties['Sequence'] -and
        [int64]$Actual.Sequence -lt [int64]$Intent.Sequence) {
        return $false
    }

    return $true
}

function Test-FileTransferFileTunaV4DataPathRangeMatches {
    param(
        [Parameter(Mandatory = $true)]$Intent,
        [Parameter(Mandatory = $true)]$Actual
    )

    if (-not (Test-FileTransferFileTunaV4DataPathHasRange -Event $Intent) -or
        -not (Test-FileTransferFileTunaV4DataPathHasRange -Event $Actual)) {
        return $true
    }

    $intentStart = Get-FileTransferFileTunaV4DataPathRangeStart -Event $Intent
    $intentEndExclusive = Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $Intent
    $actualStart = Get-FileTransferFileTunaV4DataPathRangeStart -Event $Actual
    $actualEndExclusive = Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $Actual

    if ($Intent.EventName -eq 'filetransfer_v4_repair_sent') {
        return $actualStart -ge $intentStart -and
            $actualEndExclusive -le $intentEndExclusive
    }

    return $actualStart -eq $intentStart -and
        $actualEndExclusive -eq $intentEndExclusive
}

function Test-FileTransferFileTunaV4DataPathSendShapeMatches {
    param(
        [Parameter(Mandatory = $true)]$Intent,
        [Parameter(Mandatory = $true)]$Actual
    )

    $proofDirection = Get-FileTransferEventField -Event $Actual -Name 'proof_direction' -Default ''
    if ($proofDirection -ne 'receive' -and $proofDirection -ne 'send') {
        return $false
    }

    $intentBatchChunkCount = Get-FileTransferEventInt64Field -Event $Intent -Name 'batch_chunk_count' -Default 0
    $intentSentChunkCount = Get-FileTransferEventInt64Field -Event $Intent -Name 'sent_chunk_count' -Default 0
    $actualBatchChunkCount = Get-FileTransferEventInt64Field -Event $Actual -Name 'batch_chunk_count' -Default 0
    if ($actualBatchChunkCount -gt 0) {
        if ($Intent.EventName -eq 'filetransfer_v4_chunk_batch_sent' -and
            $intentBatchChunkCount -gt 0 -and
            $intentBatchChunkCount -ne $actualBatchChunkCount) {
            return $false
        }

        if ($Intent.EventName -eq 'filetransfer_v4_repair_sent' -and
            $intentSentChunkCount -gt 0 -and
            $actualBatchChunkCount -gt $intentSentChunkCount) {
            return $false
        }
    }

    return Test-FileTransferFileTunaV4DataPathRangeMatches -Intent $Intent -Actual $Actual
}

function Get-FileTransferRouteTransitionCorrelation {
    param(
        [object[]]$Events = @(),
        $RegisteredLeaseEvents = $null,
        $RetiredLeaseEvents = $null,
        [switch]$AlreadyChronologicallyOrdered,
        [switch]$EventNamePartitionsChronologicallyOrdered
    )

    # The correlator partitions the input by event name before performing any
    # chronology-sensitive lookup. Compact analysis supplies individually
    # chronological event-name buckets without materializing another global
    # 200k-record sort, while full analysis supplies one globally ordered list.
    [object[]]$orderedEvents = if (
        $AlreadyChronologicallyOrdered -or
        $EventNamePartitionsChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    function Get-RouteTransitionField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Name
        )

        $aliases = switch ($Name) {
            'operation_generation' { @('operation_generation', 'transition_generation') }
            'authority_id' { @('authority_id', 'operation_id', 'transition_authority_id') }
            'predecessor_authority_id' { @('predecessor_authority_id', 'predecessor_transition_authority_id') }
            'source_route_publication_generation' { @('source_route_publication_generation', 'route_publication_generation') }
            'source_data_session_generation' { @('source_data_session_generation', 'data_session_generation') }
            'captured_lease_fingerprint' { @('captured_lease_fingerprint', 'captured_send_fingerprint') }
            'completed_lease_fingerprint' { @('completed_lease_fingerprint', 'completed_send_fingerprint') }
            'peer_proof_generation' { @('peer_proof_generation', 'proof_generation') }
            'peer_proof_transport_epoch' { @('peer_proof_transport_epoch', 'proof_transport_epoch') }
            'peer_proof_kind' { @('peer_proof_kind', 'proof_kind') }
            'retained_frame_type' { @('retained_frame_type', 'frame_type', 'peer_proof_frame_type') }
            'retained_frame_transport_epoch' { @('retained_frame_transport_epoch', 'frame_transport_epoch', 'peer_proof_frame_transport_epoch') }
            'retained_frame_fingerprint' { @('retained_frame_fingerprint', 'frame_fingerprint', 'peer_frame_fingerprint', 'peer_proof_frame_sha256') }
            'frame_fingerprint' { @('frame_fingerprint', 'peer_frame_fingerprint', 'retained_frame_fingerprint', 'peer_proof_frame_sha256') }
            'status' { @('status', 'decision_status', 'apply_status', 'bind_status', 'pairing_status') }
            'outcome' { @('outcome', 'drain_outcome') }
            default { @($Name) }
        }

        foreach ($alias in @($aliases)) {
            $value = Get-FileTransferEventField -Event $Event -Name $alias -Default ''
            if ([string]::IsNullOrWhiteSpace($value) -or
                $value -in @('(none)', 'none', '(missing)', '__missing__')) {
                continue
            }
            if ($Name -in @('source_route', 'target_route')) {
                if ([string]::Equals($value, 'FileTunaV4', [System.StringComparison]::OrdinalIgnoreCase)) {
                    return 'file_tuna_v4'
                }
                if ([string]::Equals($value, 'PostTunaFallbackV6', [System.StringComparison]::OrdinalIgnoreCase)) {
                    return 'post_tuna_fallback_v6'
                }
                if ([string]::Equals($value, 'RegularNknV4Fast', [System.StringComparison]::OrdinalIgnoreCase)) {
                    return 'regular_nkn_v4_fast'
                }
            }
            if ($Name -in @('source_transport', 'target_transport')) {
                if ($value -in @('RegularNkn', 'regular_nkn', 'regularnkn')) {
                    return 'regular_nkn'
                }
                if ([string]::Equals($value, 'Tuna', [System.StringComparison]::OrdinalIgnoreCase)) {
                    return 'tuna'
                }
            }
            return $value
        }

        return ''
    }

    function Get-RouteTransitionIdentityKey {
        param([Parameter(Mandatory = $true)]$Event)

        $parts = New-Object System.Collections.Generic.List[string]
        foreach ($fieldName in @('session_id', 'transfer_id', 'direction', 'operation_generation', 'authority_id')) {
            $value = Get-RouteTransitionField -Event $Event -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($value)) {
                return ''
            }
            $parts.Add($value.ToLowerInvariant()) | Out-Null
        }
        return [string]::Join('|', $parts)
    }

    function Test-RouteTransitionIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Authority,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $key = Get-RouteTransitionIdentityKey -Event $Authority
        return -not [string]::IsNullOrWhiteSpace($key) -and
            $key -eq (Get-RouteTransitionIdentityKey -Event $Candidate)
    }

    function Test-RouteTransitionTransferScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Authority,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($fieldName in @('session_id', 'transfer_id', 'direction')) {
            $expected = Get-RouteTransitionField -Event $Authority -Name $fieldName
            $actual = Get-RouteTransitionField -Event $Candidate -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($expected) -or
                [string]::IsNullOrWhiteSpace($actual) -or
                -not [string]::Equals($expected, $actual, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-RouteTransitionAuthorityMatch {
        param(
            [Parameter(Mandatory = $true)]$Authority,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-RouteTransitionIdentityMatch -Authority $Authority -Candidate $Candidate)) {
            return $false
        }

        foreach ($fieldName in @(
                'transition_kind',
                'source_route',
                'source_protocol_version',
                'source_live_route_epoch',
                'source_runtime_generation',
                'source_route_publication_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_data_session_generation',
                'target_route',
                'target_protocol_version',
                'target_transport')) {
            $expected = Get-RouteTransitionField -Event $Authority -Name $fieldName
            $actual = Get-RouteTransitionField -Event $Candidate -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($expected) -or
                [string]::IsNullOrWhiteSpace($actual) -or
                -not [string]::Equals($expected, $actual, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-RouteTransitionStatus {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Allowed
        )

        $status = Get-RouteTransitionField -Event $Event -Name 'status'
        return $status -in $Allowed
    }

    function Test-RouteTransitionPreparedShape {
        param([Parameter(Mandatory = $true)]$Event)

        if ([string]::IsNullOrWhiteSpace((Get-RouteTransitionIdentityKey -Event $Event)) -or
            -not (Test-RouteTransitionStatus -Event $Event -Allowed @('Prepared', 'Idempotent'))) {
            return $false
        }

        $sourceRoute = Get-RouteTransitionField -Event $Event -Name 'source_route'
        $sourceProtocol = Get-RouteTransitionField -Event $Event -Name 'source_protocol_version'
        $targetRoute = Get-RouteTransitionField -Event $Event -Name 'target_route'
        $targetProtocol = Get-RouteTransitionField -Event $Event -Name 'target_protocol_version'
        $targetTransport = (Get-RouteTransitionField -Event $Event -Name 'target_transport').ToLowerInvariant()
        return ($sourceRoute -eq 'regular_nkn_v4_fast' -and
                $sourceProtocol -eq '4' -and
                $targetRoute -eq 'file_tuna_v4' -and
                $targetProtocol -eq '4' -and
                $targetTransport -eq 'tuna') -or
            ($sourceRoute -eq 'file_tuna_v4' -and
                $sourceProtocol -eq '4' -and
                $targetRoute -eq 'post_tuna_fallback_v6' -and
                $targetProtocol -eq '6' -and
                $targetTransport -eq 'regular_nkn') -or
            ($sourceRoute -eq 'post_tuna_fallback_v6' -and
                $sourceProtocol -eq '6' -and
                $targetRoute -eq 'file_tuna_v4' -and
                $targetProtocol -eq '4' -and
                $targetTransport -eq 'tuna') -or
            ($sourceRoute -eq 'regular_nkn_v4_fast' -and
                $sourceProtocol -eq '4' -and
                $targetRoute -eq 'post_tuna_fallback_v6' -and
                $targetProtocol -eq '6' -and
                $targetTransport -eq 'regular_nkn')
    }

    function Test-RouteTransitionReceiptComplete {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$Receipt
        )

        if (-not (Test-RouteTransitionAuthorityMatch -Authority $Prepared -Candidate $Receipt) -or
            -not (Test-RouteTransitionStatus -Event $Receipt -Allowed @('Accepted', 'Applied', 'Idempotent')) -or
            (Get-RouteTransitionField -Event $Receipt -Name 'outcome') -ne 'Completed') {
            return $false
        }

        $captured = Get-FileTransferEventInt64Field -Event $Receipt -Name 'captured_send_count' -Default -1
        if ($captured -lt 0) {
            $captured = Get-FileTransferEventInt64Field -Event $Receipt -Name 'captured_lease_count' -Default -1
        }
        $completed = Get-FileTransferEventInt64Field -Event $Receipt -Name 'completed_send_count' -Default -1
        if ($completed -lt 0) {
            $completed = Get-FileTransferEventInt64Field -Event $Receipt -Name 'completed_lease_count' -Default -1
        }
        $capturedFingerprint = Get-RouteTransitionField -Event $Receipt -Name 'captured_lease_fingerprint'
        $completedFingerprint = Get-RouteTransitionField -Event $Receipt -Name 'completed_lease_fingerprint'
        return $captured -ge 0 -and
            $captured -eq $completed -and
            -not [string]::IsNullOrWhiteSpace($capturedFingerprint) -and
            [string]::Equals($capturedFingerprint, $completedFingerprint, [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Test-RouteTransitionSourceScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-RouteTransitionTransferScopeMatch -Authority $Prepared -Candidate $Candidate)) {
            return $false
        }
        foreach ($fieldName in @(
                'source_route',
                'source_protocol_version',
                'source_live_route_epoch',
                'source_runtime_generation',
                'source_route_publication_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_data_session_generation')) {
            $expected = Get-RouteTransitionField -Event $Prepared -Name $fieldName
            $actual = Get-RouteTransitionField -Event $Candidate -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($expected) -or
                [string]::IsNullOrWhiteSpace($actual) -or
                -not [string]::Equals($expected, $actual, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Get-RouteTransitionLeaseTransferScopeKey {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [switch]$CanonicalPhysicalLease
        )

        if ($CanonicalPhysicalLease) {
            $fields = $Event.Fields
            if ($null -eq $fields) {
                return ''
            }
            $sessionId = if ($fields.ContainsKey('session_id')) {
                [string]$fields['session_id']
            } else { '' }
            $transferId = if ($fields.ContainsKey('transfer_id')) {
                [string]$fields['transfer_id']
            } else { '' }
            $direction = if ($fields.ContainsKey('direction')) {
                [string]$fields['direction']
            } else { '' }
            foreach ($value in @($sessionId, $transferId, $direction)) {
                if ([string]::IsNullOrWhiteSpace($value) -or
                    $value -in @('(none)', 'none', '(missing)', '__missing__')) {
                    return ''
                }
            }
            return "$sessionId|$transferId|$direction".ToLowerInvariant()
        }

        $parts = New-Object System.Collections.Generic.List[string]
        foreach ($fieldName in @('session_id', 'transfer_id', 'direction')) {
            $value = Get-RouteTransitionField -Event $Event -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($value)) {
                return ''
            }
            $parts.Add($value.ToLowerInvariant()) | Out-Null
        }
        return [string]::Join('|', $parts)
    }

    function Find-RouteTransitionFirstSourceScopeEventAfter {
        param(
            $Candidates,
            [Parameter(Mandatory = $true)]$Prepared,
            [long]$ExclusiveStart,
            [long]$ExclusiveEnd = [long]::MaxValue
        )

        $visitCount = 0L
        $exactScopeValidationCount = 0L
        $candidateCount = if ($null -eq $Candidates) {
            0
        }
        elseif ($null -ne $Candidates.PSObject.Properties['Count']) {
            [int]$Candidates.Count
        }
        else {
            1
        }
        if ($candidateCount -eq 0) {
            return [pscustomobject]@{
                Event = $null
                VisitCount = $visitCount
                ExactScopeValidationCount = $exactScopeValidationCount
            }
        }

        $low = 0
        $high = $candidateCount - 1
        $firstIndex = -1
        while ($low -le $high) {
            $visitCount++
            $mid = $low + [int](($high - $low) / 2)
            $candidate = if ($candidateCount -eq 1 -and
                $null -eq $Candidates.PSObject.Properties['Count']) {
                $Candidates
            }
            else {
                $Candidates[$mid]
            }
            if ([int64]$candidate.Sequence -gt $ExclusiveStart) {
                $firstIndex = $mid
                $high = $mid - 1
            }
            else {
                $low = $mid + 1
            }
        }

        $event = $null
        $expectedSourceRoute = Get-RouteTransitionField `
            -Event $Prepared `
            -Name 'source_route'
        $expectedSourceProtocol = Get-RouteTransitionField `
            -Event $Prepared `
            -Name 'source_protocol_version'
        $expectedLiveRouteEpoch = Get-RouteTransitionField `
            -Event $Prepared `
            -Name 'source_live_route_epoch'
        $expectedRuntimeGeneration = Get-RouteTransitionField `
            -Event $Prepared `
            -Name 'source_runtime_generation'
        for ($index = $firstIndex; $index -ge 0 -and $index -lt $candidateCount; $index++) {
            $visitCount++
            $candidate = if ($candidateCount -eq 1 -and
                $null -eq $Candidates.PSObject.Properties['Count']) {
                $Candidates
            }
            else {
                $Candidates[$index]
            }
            if ([int64]$candidate.Sequence -ge $ExclusiveEnd) {
                break
            }

            # Physical lease events use canonical source fields. Compare the
            # cheap immutable discriminator before invoking the complete tuple
            # matcher so target-route traffic cannot make the lookup quadratic.
            $fields = $candidate.Fields
            if ($null -eq $fields) {
                continue
            }
            $candidateSourceRoute = if ($fields.ContainsKey('source_route')) {
                [string]$fields['source_route']
            } else { '' }
            if ([string]::Equals(
                    $candidateSourceRoute,
                    'FileTunaV4',
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                $candidateSourceRoute = 'file_tuna_v4'
            }
            elseif ([string]::Equals(
                    $candidateSourceRoute,
                    'PostTunaFallbackV6',
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                $candidateSourceRoute = 'post_tuna_fallback_v6'
            }
            elseif ([string]::Equals(
                    $candidateSourceRoute,
                    'RegularNknV4Fast',
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                $candidateSourceRoute = 'regular_nkn_v4_fast'
            }
            if (-not [string]::Equals(
                    $candidateSourceRoute,
                    $expectedSourceRoute,
                    [System.StringComparison]::OrdinalIgnoreCase) -or
                -not $fields.ContainsKey('source_protocol_version') -or
                -not [string]::Equals(
                    [string]$fields['source_protocol_version'],
                    $expectedSourceProtocol,
                    [System.StringComparison]::OrdinalIgnoreCase) -or
                -not $fields.ContainsKey('source_live_route_epoch') -or
                -not [string]::Equals(
                    [string]$fields['source_live_route_epoch'],
                    $expectedLiveRouteEpoch,
                    [System.StringComparison]::OrdinalIgnoreCase) -or
                -not $fields.ContainsKey('source_runtime_generation') -or
                -not [string]::Equals(
                    [string]$fields['source_runtime_generation'],
                    $expectedRuntimeGeneration,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                continue
            }

            $exactScopeValidationCount++
            if (Test-RouteTransitionSourceScopeMatch `
                    -Prepared $Prepared `
                    -Candidate $candidate) {
                $event = $candidate
                break
            }
        }
        return [pscustomobject]@{
            Event = $event
            VisitCount = $visitCount
            ExactScopeValidationCount = $exactScopeValidationCount
        }
    }

    function Test-RouteTransitionTargetBoundary {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$Boundary
        )

        if (-not (Test-RouteTransitionTransferScopeMatch -Authority $Prepared -Candidate $Boundary)) {
            return $false
        }
        $targetRoute = Get-RouteTransitionField -Event $Prepared -Name 'target_route'
        $route = Get-RouteTransitionField -Event $Boundary -Name 'route'
        if ([string]::IsNullOrWhiteSpace($route)) {
            $route = Get-RouteTransitionField -Event $Boundary -Name 'new_route'
        }
        if ([string]::IsNullOrWhiteSpace($route)) {
            $route = Get-RouteTransitionField -Event $Boundary -Name 'current_route'
        }
        return $route -eq $targetRoute
    }

    function Get-RouteTransitionSignature {
        param([Parameter(Mandatory = $true)]$Event)

        return (@(
                'session_id',
                'transfer_id',
                'direction',
                'operation_generation',
                'authority_id',
                'predecessor_authority_id',
                'transition_kind',
                'source_route',
                'source_protocol_version',
                'source_live_route_epoch',
                'source_runtime_generation',
                'source_route_publication_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_data_session_generation',
                'target_route',
                'target_protocol_version',
                'target_transport') | ForEach-Object {
                    (Get-RouteTransitionField -Event $Event -Name $_).ToLowerInvariant()
                }) -join '|'
    }

    # Build the route-transition evidence partitions in one chronological pass.
    # The retained artifact can contain hundreds of thousands of physical lease
    # records, so repeatedly filtering the complete input here is prohibitively
    # expensive even though each semantic partition is small.
    $preparedEventList = New-Object System.Collections.Generic.List[object]
    $proofEventList = New-Object System.Collections.Generic.List[object]
    $pauseEventList = New-Object System.Collections.Generic.List[object]
    $drainingEventList = New-Object System.Collections.Generic.List[object]
    $supersessionEventList = New-Object System.Collections.Generic.List[object]
    $receiptEventList = New-Object System.Collections.Generic.List[object]
    $commitEventList = New-Object System.Collections.Generic.List[object]
    $invalidationEventList = New-Object System.Collections.Generic.List[object]
    $dispositionEventList = New-Object System.Collections.Generic.List[object]
    $frameAppliedEventList = New-Object System.Collections.Generic.List[object]
    $frameRejectedEventList = New-Object System.Collections.Generic.List[object]
    $leaseRegisteredEventsByTransferScope = @{}
    $leaseRetiredEventsByTransferScope = @{}
    $ownerBoundaryEventList = New-Object System.Collections.Generic.List[object]
    $availabilityEventList = New-Object System.Collections.Generic.List[object]
    $localProofConsumptionEventList = New-Object System.Collections.Generic.List[object]
    $terminalEventList = New-Object System.Collections.Generic.List[object]
    $fallbackBootstrapSkipEventList = New-Object System.Collections.Generic.List[object]
    $fallbackStartedEventList = New-Object System.Collections.Generic.List[object]
    $fallbackPendingEventList = New-Object System.Collections.Generic.List[object]
    $bootstrapDecisionEventList = New-Object System.Collections.Generic.List[object]
    $bootstrapReceiptEventList = New-Object System.Collections.Generic.List[object]
    $bootstrapAllReceiptEventList = New-Object System.Collections.Generic.List[object]
    $bootstrapExecutionEventList = New-Object System.Collections.Generic.List[object]
    $bootstrapPeerFrameDecisionEventList = New-Object System.Collections.Generic.List[object]
    $bootstrapPeerBoundaryBoundEventList = New-Object System.Collections.Generic.List[object]
    $bootstrapPhysicalSendEventList = New-Object System.Collections.Generic.List[object]
    $routeTransitionIndexBuildVisitCount = 0L
    $routeTransitionLeaseIndexBuildVisitCount = 0L
    $routeTransitionRegisteredLeaseIndexBuildVisitCount = 0L
    $routeTransitionRetiredLeaseIndexBuildVisitCount = 0L
    $routeTransitionBoundedLookupVisitCount = 0L
    $routeTransitionLeaseExactScopeValidationCount = 0L

    foreach ($event in @($orderedEvents)) {
        if ($null -eq $event) {
            continue
        }
        $routeTransitionIndexBuildVisitCount++
        switch ($event.EventName) {
            'filetransfer_route_transition_prepared' {
                $preparedEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_peer_proof_observed' {
                $proofEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_pause_bound' {
                $pauseEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_draining' {
                $drainingEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_supersession_decided' {
                $supersessionEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_drain_receipt_decided' {
                $receiptEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_committed' {
                $commitEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_invalidated' {
                $invalidationEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_disposition_applied' {
                $dispositionEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_retained_frame_applied' {
                $frameAppliedEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_retained_frame_rejected' {
                $frameRejectedEventList.Add($event) | Out-Null
            }
            'filetransfer_route_transition_physical_send_lease_registered' {
                $routeTransitionLeaseIndexBuildVisitCount++
                $routeTransitionRegisteredLeaseIndexBuildVisitCount++
                $transferScopeKey = Get-RouteTransitionLeaseTransferScopeKey `
                    -Event $event `
                    -CanonicalPhysicalLease
                if (-not [string]::IsNullOrWhiteSpace($transferScopeKey)) {
                    if (-not $leaseRegisteredEventsByTransferScope.ContainsKey($transferScopeKey)) {
                        $leaseRegisteredEventsByTransferScope[$transferScopeKey] =
                            New-Object System.Collections.Generic.List[object]
                    }
                    $leaseRegisteredEventsByTransferScope[$transferScopeKey].Add($event) | Out-Null
                }
            }
            'filetransfer_route_transition_physical_send_lease_retired' {
                $routeTransitionLeaseIndexBuildVisitCount++
                $routeTransitionRetiredLeaseIndexBuildVisitCount++
                $transferScopeKey = Get-RouteTransitionLeaseTransferScopeKey `
                    -Event $event `
                    -CanonicalPhysicalLease
                if (-not [string]::IsNullOrWhiteSpace($transferScopeKey)) {
                    if (-not $leaseRetiredEventsByTransferScope.ContainsKey($transferScopeKey)) {
                        $leaseRetiredEventsByTransferScope[$transferScopeKey] =
                            New-Object System.Collections.Generic.List[object]
                    }
                    $leaseRetiredEventsByTransferScope[$transferScopeKey].Add($event) | Out-Null
                }
            }
            { $_ -in @(
                    'filetransfer_leg_started',
                    'filetransfer_runtime_owner_workers_retired',
                    'filetransfer_route_transitioned',
                    'filetransfer_route_selected',
                    'filetransfer_route_hint_authorized_publication_accepted',
                    'filetransfer_runtime_started') } {
                $ownerBoundaryEventList.Add($event) | Out-Null
            }
            { $_ -in @(
                    'filetransfer_data_session_availability_changed',
                    'filetransfer_transport_availability_changed',
                    'filetransfer_runtime_availability_changed') } {
                if ((Get-RouteTransitionField -Event $event -Name 'available') -eq '1') {
                    $availabilityEventList.Add($event) | Out-Null
                }
            }
            'filetransfer_post_tuna_fallback_v6_route_consumed' {
                $localProofConsumptionEventList.Add($event) | Out-Null
            }
            { $_ -in @(
                    'file_transfer_outbound_terminal',
                    'file_transfer_inbound_terminal',
                    'transfer_terminal',
                    'filetransfer_runtime_terminalized') } {
                $terminalEventList.Add($event) | Out-Null
            }
            'nkn_bridge_post_tuna_fallback_proof_send_window_skipped' {
                if ((Get-RouteTransitionField -Event $event -Name 'reason') -eq
                    'no_active_post_tuna_fallback_runtime') {
                    $fallbackBootstrapSkipEventList.Add($event) | Out-Null
                }
            }
            'tuna_fallback_started' {
                $fallbackStartedEventList.Add($event) | Out-Null
            }
            { $_ -in @(
                    'tuna_fallback_filetransfer_evidence_requested',
                    'filetransfer_fallback_nkn_proof_pending',
                    'filetransfer_fallback_nkn_proof_unconfirmed',
                    'filetransfer_fallback_nkn_proof_waiting_for_v6_epoch') } {
                $fallbackPendingEventList.Add($event) | Out-Null
            }
            'filetransfer_fallback_v6_proof_bootstrap_decided' {
                if (((Get-RouteTransitionField -Event $event -Name 'decision_status') -in
                        @('Issued', 'Idempotent')) -or
                    ((Get-RouteTransitionField -Event $event -Name 'status') -in
                        @('Issued', 'Idempotent'))) {
                    $bootstrapDecisionEventList.Add($event) | Out-Null
                }
            }
            'filetransfer_fallback_v6_proof_bootstrap_receipt_applied' {
                $bootstrapAllReceiptEventList.Add($event) | Out-Null
                if ((Get-RouteTransitionField -Event $event -Name 'receipt_status') -eq
                        'Delivered' -and
                    (Get-RouteTransitionField -Event $event -Name 'application_status') -in
                        @('Applied', 'Idempotent')) {
                    $bootstrapReceiptEventList.Add($event) | Out-Null
                }
            }
            'filetransfer_fallback_v6_proof_bootstrap_execution_completed' {
                $bootstrapExecutionEventList.Add($event) | Out-Null
            }
            'filetransfer_fallback_v6_proof_bootstrap_peer_frame_decided' {
                $bootstrapPeerFrameDecisionEventList.Add($event) | Out-Null
            }
            'filetransfer_fallback_v6_proof_bootstrap_peer_boundary_bound' {
                $bootstrapPeerBoundaryBoundEventList.Add($event) | Out-Null
            }
            'filetransfer_data_path_send_result' {
                if ((Get-RouteTransitionField -Event $event -Name 'frame_type') -eq
                    'filetransfer.frontier_request.v6') {
                    $bootstrapPhysicalSendEventList.Add($event) | Out-Null
                }
            }
        }
    }

    # Compact analysis passes the high-volume, already ordered lease buckets
    # separately so its semantic route input does not materialize and walk a
    # second 200k-record combined array merely to partition by event name.
    foreach ($event in $RegisteredLeaseEvents) {
        if ($null -eq $event) {
            continue
        }
        $routeTransitionIndexBuildVisitCount++
        $routeTransitionLeaseIndexBuildVisitCount++
        $routeTransitionRegisteredLeaseIndexBuildVisitCount++
        $transferScopeKey = Get-RouteTransitionLeaseTransferScopeKey `
            -Event $event `
            -CanonicalPhysicalLease
        if (-not [string]::IsNullOrWhiteSpace($transferScopeKey)) {
            if (-not $leaseRegisteredEventsByTransferScope.ContainsKey($transferScopeKey)) {
                $leaseRegisteredEventsByTransferScope[$transferScopeKey] =
                    New-Object System.Collections.Generic.List[object]
            }
            $leaseRegisteredEventsByTransferScope[$transferScopeKey].Add($event) | Out-Null
        }
    }
    foreach ($event in $RetiredLeaseEvents) {
        if ($null -eq $event) {
            continue
        }
        $routeTransitionIndexBuildVisitCount++
        $routeTransitionLeaseIndexBuildVisitCount++
        $routeTransitionRetiredLeaseIndexBuildVisitCount++
        $transferScopeKey = Get-RouteTransitionLeaseTransferScopeKey `
            -Event $event `
            -CanonicalPhysicalLease
        if (-not [string]::IsNullOrWhiteSpace($transferScopeKey)) {
            if (-not $leaseRetiredEventsByTransferScope.ContainsKey($transferScopeKey)) {
                $leaseRetiredEventsByTransferScope[$transferScopeKey] =
                    New-Object System.Collections.Generic.List[object]
            }
            $leaseRetiredEventsByTransferScope[$transferScopeKey].Add($event) | Out-Null
        }
    }

    [object[]]$preparedEvents = @($preparedEventList.ToArray())
    [object[]]$proofEvents = @($proofEventList.ToArray())
    [object[]]$pauseEvents = @($pauseEventList.ToArray())
    [object[]]$drainingEvents = @($drainingEventList.ToArray())
    [object[]]$supersessionEvents = @($supersessionEventList.ToArray())
    [object[]]$receiptEvents = @($receiptEventList.ToArray())
    [object[]]$commitEvents = @($commitEventList.ToArray())
    [object[]]$invalidationEvents = @($invalidationEventList.ToArray())
    [object[]]$dispositionEvents = @($dispositionEventList.ToArray())
    [object[]]$frameAppliedEvents = @($frameAppliedEventList.ToArray())
    [object[]]$frameRejectedEvents = @($frameRejectedEventList.ToArray())
    [object[]]$ownerBoundaryEvents = @($ownerBoundaryEventList.ToArray())
    [object[]]$availabilityEvents = @($availabilityEventList.ToArray())
    [object[]]$localProofConsumptionEvents = @($localProofConsumptionEventList.ToArray())
    [object[]]$terminalEvents = @($terminalEventList.ToArray())
    [object[]]$fallbackBootstrapSkipEvents = @($fallbackBootstrapSkipEventList.ToArray())
    [object[]]$fallbackStartedEvents = @($fallbackStartedEventList.ToArray())
    [object[]]$fallbackPendingEvents = @($fallbackPendingEventList.ToArray())
    [object[]]$bootstrapDecisionEvents = @($bootstrapDecisionEventList.ToArray())
    [object[]]$bootstrapReceiptEvents = @($bootstrapReceiptEventList.ToArray())
    [object[]]$bootstrapExecutionEvents = @($bootstrapExecutionEventList.ToArray())
    [object[]]$bootstrapAllReceiptEvents = @($bootstrapAllReceiptEventList.ToArray())
    [object[]]$bootstrapPeerFrameDecisionEvents = @($bootstrapPeerFrameDecisionEventList.ToArray())
    [object[]]$bootstrapPeerBoundaryBoundEvents = @($bootstrapPeerBoundaryBoundEventList.ToArray())
    [object[]]$bootstrapPhysicalSendEvents = @($bootstrapPhysicalSendEventList.ToArray())

    $rawRecords = New-Object System.Collections.Generic.List[object]
    $distinctRecords = New-Object System.Collections.Generic.List[object]
    $distinctKeys = New-Object 'System.Collections.Generic.HashSet[string]'
    $fallbackBootstrapRawRecords = New-Object System.Collections.Generic.List[object]
    $fallbackBootstrapDistinctRecords = New-Object System.Collections.Generic.List[object]
    $fallbackBootstrapDistinctKeys = New-Object 'System.Collections.Generic.HashSet[string]'
    $fallbackBootstrapRecoveredKeys = New-Object 'System.Collections.Generic.HashSet[string]'
    $firstPreparedByKey = @{}
    $signatureByKey = @{}

    function Add-RouteTransitionCandidate {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Key,
            [Parameter(Mandatory = $true)][string]$Reason,
            [string]$Class = 'filetransfer_route_transition_incomplete',
            [switch]$Recovered
        )

        $record = [pscustomobject]@{
            Class = $Class
            Event = $Event
            Reason = $Reason
            DistinctKey = $Key
        }
        if ($Class -eq 'filetransfer_route_transition_tuna_v4_to_post_tuna_fallback_v6_proof_bootstrap_missing') {
            $fallbackBootstrapRawRecords.Add($record) | Out-Null
            if ($fallbackBootstrapDistinctKeys.Add($Key)) {
                $fallbackBootstrapDistinctRecords.Add($record) | Out-Null
            }
            if ($Recovered) {
                $fallbackBootstrapRecoveredKeys.Add($Key) | Out-Null
                return
            }
        }
        $rawRecords.Add($record) | Out-Null
        if ($distinctKeys.Add($Key)) {
            $distinctRecords.Add($record) | Out-Null
        }
    }

    foreach ($prepared in @($preparedEvents)) {
        if (-not (Test-RouteTransitionPreparedShape -Event $prepared)) {
            continue
        }
        $key = Get-RouteTransitionIdentityKey -Event $prepared
        $signature = Get-RouteTransitionSignature -Event $prepared
        if ($firstPreparedByKey.ContainsKey($key)) {
            if ($signatureByKey[$key] -ne $signature) {
                Add-RouteTransitionCandidate -Event $prepared -Key $key -Reason 'route_transition_authority_tuple_mutated'
            }
            continue
        }
        $firstPreparedByKey[$key] = $prepared
        $signatureByKey[$key] = $signature
    }

    foreach ($key in @($firstPreparedByKey.Keys)) {
        $prepared = $firstPreparedByKey[$key]
        $preparedSequence = [int64]$prepared.Sequence
        $targetRoute = Get-RouteTransitionField -Event $prepared -Name 'target_route'
        $candidateKey = "route-transition|$key"

        $allLifecycleEvents = @(
            $pauseEvents + $drainingEvents + $supersessionEvents + $receiptEvents +
            $commitEvents + $invalidationEvents + $dispositionEvents + $frameAppliedEvents +
            $frameRejectedEvents
        )
        $routeTransitionBoundedLookupVisitCount += [int64]$allLifecycleEvents.Count
        [object[]]$mutatedEvents = @($allLifecycleEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-RouteTransitionIdentityMatch -Authority $prepared -Candidate $_) -and
                -not (Test-RouteTransitionAuthorityMatch -Authority $prepared -Candidate $_)
            } | Sort-Object Sequence, LineNumber)
        if ($mutatedEvents.Count -gt 0) {
            Add-RouteTransitionCandidate -Event $mutatedEvents[0] -Key $candidateKey -Reason 'route_transition_authority_tuple_mutated'
            continue
        }

        [object[]]$pause = @($pauseEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-RouteTransitionAuthorityMatch -Authority $prepared -Candidate $_) -and
                (Test-RouteTransitionStatus -Event $_ -Allowed @('Accepted', 'Installed', 'Idempotent'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$draining = @($drainingEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-RouteTransitionAuthorityMatch -Authority $prepared -Candidate $_) -and
                (Test-RouteTransitionStatus -Event $_ -Allowed @('Draining', 'Idempotent'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$receipts = @($receiptEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-RouteTransitionReceiptComplete -Prepared $prepared -Receipt $_)
            } | Sort-Object Sequence, LineNumber)
        [object[]]$commits = @($commitEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-RouteTransitionAuthorityMatch -Authority $prepared -Candidate $_) -and
                (Test-RouteTransitionStatus -Event $_ -Allowed @('Committed', 'Idempotent'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$invalidations = @($invalidationEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-RouteTransitionAuthorityMatch -Authority $prepared -Candidate $_) -and
                (Test-RouteTransitionStatus -Event $_ -Allowed @('Invalidated', 'Idempotent'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$terminals = @($terminalEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-RouteTransitionTransferScopeMatch -Authority $prepared -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $routeTransitionBoundedLookupVisitCount += [int64](
            $pauseEvents.Count + $drainingEvents.Count + $receiptEvents.Count +
            $commitEvents.Count + $invalidationEvents.Count + $terminalEvents.Count)

        $commitSequence = if ($commits.Count -gt 0) { [int64]$commits[0].Sequence } else { [int64]::MaxValue }
        $invalidationSequence = if ($invalidations.Count -gt 0) { [int64]$invalidations[0].Sequence } else { [int64]::MaxValue }
        $terminalSequence = if ($terminals.Count -gt 0) { [int64]$terminals[0].Sequence } else { [int64]::MaxValue }
        $operationEnd = [Math]::Min($terminalSequence, [Math]::Min($commitSequence, $invalidationSequence))

        if ($targetRoute -eq 'post_tuna_fallback_v6') {
            $routeTransitionBoundedLookupVisitCount += [int64]$proofEvents.Count
            $peerProofGeneration = Get-RouteTransitionField -Event $prepared -Name 'peer_proof_generation'
            $peerProofTransportEpoch = Get-RouteTransitionField -Event $prepared -Name 'peer_proof_transport_epoch'
            $peerProofKind = Get-RouteTransitionField -Event $prepared -Name 'peer_proof_kind'
            $retainedFrameFingerprint = Get-RouteTransitionField -Event $prepared -Name 'retained_frame_fingerprint'
            if ($peerProofGeneration -in @('', '0') -or
                $peerProofTransportEpoch -in @('', '0') -or
                [string]::IsNullOrWhiteSpace($peerProofKind) -or
                [string]::IsNullOrWhiteSpace($retainedFrameFingerprint)) {
                Add-RouteTransitionCandidate -Event $prepared -Key $candidateKey -Reason 'fallback_route_transition_prepared_without_exact_peer_proof'
                continue
            }
            [object[]]$matchingProof = @($proofEvents | Where-Object {
                    [int64]$_.Sequence -lt $preparedSequence -and
                    (Test-RouteTransitionTransferScopeMatch -Authority $prepared -Candidate $_) -and
                    (Test-RouteTransitionStatus -Event $_ -Allowed @('Observed', 'Idempotent')) -and
                    (Get-RouteTransitionField -Event $_ -Name 'peer_proof_generation') -eq
                        $peerProofGeneration -and
                    (Get-RouteTransitionField -Event $_ -Name 'peer_proof_transport_epoch') -eq
                        $peerProofTransportEpoch -and
                    (Get-RouteTransitionField -Event $_ -Name 'peer_proof_kind') -eq
                        $peerProofKind -and
                    (Get-RouteTransitionField -Event $_ -Name 'retained_frame_transport_epoch') -eq
                        $peerProofTransportEpoch -and
                    (Get-RouteTransitionField -Event $_ -Name 'retained_frame_fingerprint') -eq
                        $retainedFrameFingerprint
                } | Sort-Object Sequence, LineNumber)
            if ($matchingProof.Count -eq 0) {
                Add-RouteTransitionCandidate -Event $prepared -Key $candidateKey -Reason 'fallback_route_transition_prepared_without_exact_peer_proof'
                continue
            }
        }

        if ($draining.Count -gt 0) {
            $transferScopeKey = Get-RouteTransitionLeaseTransferScopeKey -Event $prepared
            $registeredCandidates = $null
            if (-not [string]::IsNullOrWhiteSpace($transferScopeKey) -and
                $leaseRegisteredEventsByTransferScope.ContainsKey($transferScopeKey)) {
                $registeredCandidates = $leaseRegisteredEventsByTransferScope[$transferScopeKey]
            }
            $lateLease = Find-RouteTransitionFirstSourceScopeEventAfter `
                -Candidates $registeredCandidates `
                -Prepared $prepared `
                -ExclusiveStart ([int64]$draining[0].Sequence) `
                -ExclusiveEnd $operationEnd
            $routeTransitionBoundedLookupVisitCount += [int64]$lateLease.VisitCount
            $routeTransitionLeaseExactScopeValidationCount +=
                [int64]$lateLease.ExactScopeValidationCount
            if ($null -ne $lateLease.Event) {
                Add-RouteTransitionCandidate -Event $lateLease.Event -Key $candidateKey -Reason 'source_payload_lease_registered_after_route_transition_draining'
                continue
            }
        }

        $receiptSequence = if ($receipts.Count -gt 0) { [int64]$receipts[0].Sequence } else { [int64]::MaxValue }
        $routeTransitionBoundedLookupVisitCount += [int64](
            $ownerBoundaryEvents.Count + $availabilityEvents.Count +
            $localProofConsumptionEvents.Count)
        [object[]]$prematureOwner = @($ownerBoundaryEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                [int64]$_.Sequence -lt $receiptSequence -and
                [int64]$_.Sequence -lt $operationEnd -and
                (Test-RouteTransitionTargetBoundary -Prepared $prepared -Boundary $_)
            } | Sort-Object Sequence, LineNumber)
        if ($prematureOwner.Count -gt 0) {
            Add-RouteTransitionCandidate -Event $prematureOwner[0] -Key $candidateKey -Reason 'successor_owner_or_publication_installed_before_route_transition_drain'
            continue
        }

        [object[]]$prematureAvailability = @($availabilityEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                [int64]$_.Sequence -lt $operationEnd -and
                (Test-RouteTransitionTransferScopeMatch -Authority $prepared -Candidate $_)
            } | Sort-Object Sequence, LineNumber)
        if ($prematureAvailability.Count -gt 0) {
            Add-RouteTransitionCandidate -Event $prematureAvailability[0] -Key $candidateKey -Reason 'transport_availability_released_before_route_transition_commit'
            continue
        }

        [object[]]$localProofConsumption = @($localProofConsumptionEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                [int64]$_.Sequence -lt $operationEnd -and
                (Test-RouteTransitionTransferScopeMatch -Authority $prepared -Candidate $_)
            } | Sort-Object Sequence, LineNumber)
        if ($localProofConsumption.Count -gt 0) {
            Add-RouteTransitionCandidate -Event $localProofConsumption[0] -Key $candidateKey -Reason 'fallback_peer_proof_consumed_without_coordinator_transition_commit'
            continue
        }

        if ($commits.Count -gt 0) {
            $commit = $commits[0]
            if ($pause.Count -eq 0 -or
                $draining.Count -eq 0 -or
                [int64]$pause[0].Sequence -ge [int64]$draining[0].Sequence -or
                $receipts.Count -eq 0 -or
                [int64]$receipts[0].Sequence -ge [int64]$commit.Sequence) {
                Add-RouteTransitionCandidate -Event $commit -Key $candidateKey -Reason 'route_transition_committed_without_exact_ordered_drain'
                continue
            }

            $routeTransitionBoundedLookupVisitCount += [int64]$dispositionEvents.Count
            $transferScopeKey = Get-RouteTransitionLeaseTransferScopeKey -Event $prepared
            $retiredCandidates = $null
            if (-not [string]::IsNullOrWhiteSpace($transferScopeKey) -and
                $leaseRetiredEventsByTransferScope.ContainsKey($transferScopeKey)) {
                $retiredCandidates = $leaseRetiredEventsByTransferScope[$transferScopeKey]
            }
            $lateRetirement = Find-RouteTransitionFirstSourceScopeEventAfter `
                -Candidates $retiredCandidates `
                -Prepared $prepared `
                -ExclusiveStart ([int64]$commit.Sequence)
            $routeTransitionBoundedLookupVisitCount += [int64]$lateRetirement.VisitCount
            $routeTransitionLeaseExactScopeValidationCount +=
                [int64]$lateRetirement.ExactScopeValidationCount
            if ($null -ne $lateRetirement.Event) {
                Add-RouteTransitionCandidate -Event $lateRetirement.Event -Key $candidateKey -Reason 'old_scope_physical_send_completed_after_successor_owner_install'
                continue
            }

            [object[]]$matchingDispositions = @($dispositionEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$commit.Sequence -and
                    (Test-RouteTransitionAuthorityMatch -Authority $prepared -Candidate $_) -and
                    (
                        (Test-RouteTransitionStatus -Event $_ -Allowed @('Committed', 'Applied', 'Idempotent')) -or
                        (Get-RouteTransitionField -Event $_ -Name 'disposition') -eq 'committed'
                    )
                } | Sort-Object Sequence, LineNumber)
            if ($targetRoute -eq 'post_tuna_fallback_v6') {
                $routeTransitionBoundedLookupVisitCount += [int64](
                    $frameRejectedEvents.Count + $frameAppliedEvents.Count)
                [object[]]$frameRejected = @($frameRejectedEvents | Where-Object {
                        [int64]$_.Sequence -gt [int64]$commit.Sequence -and
                        (Test-RouteTransitionAuthorityMatch -Authority $prepared -Candidate $_)
                    } | Sort-Object Sequence, LineNumber)
                if ($frameRejected.Count -gt 0) {
                    Add-RouteTransitionCandidate -Event $frameRejected[0] -Key $candidateKey -Reason 'fallback_route_transition_retained_frame_rejected'
                    continue
                }

                [object[]]$framesApplied = @($frameAppliedEvents | Where-Object {
                        [int64]$_.Sequence -gt [int64]$commit.Sequence -and
                        (Test-RouteTransitionAuthorityMatch -Authority $prepared -Candidate $_) -and
                        (Test-RouteTransitionStatus -Event $_ -Allowed @('Applied', 'Idempotent'))
                    } | Sort-Object Sequence, LineNumber)
                if ($framesApplied.Count -eq 0 -and ($matchingDispositions.Count -gt 0 -or $terminals.Count -gt 0)) {
                    $anchor = if ($matchingDispositions.Count -gt 0) { $matchingDispositions[0] } else { $terminals[0] }
                    Add-RouteTransitionCandidate -Event $anchor -Key $candidateKey -Reason 'fallback_route_transition_retained_frame_not_applied'
                    continue
                }
                if ($framesApplied.Count -gt 1) {
                    Add-RouteTransitionCandidate -Event $framesApplied[1] -Key $candidateKey -Reason 'fallback_route_transition_retained_frame_applied_more_than_once'
                    continue
                }
                if ($matchingDispositions.Count -gt 0 -and
                    $framesApplied.Count -eq 1 -and
                    [int64]$matchingDispositions[0].Sequence -lt [int64]$framesApplied[0].Sequence) {
                    Add-RouteTransitionCandidate -Event $matchingDispositions[0] -Key $candidateKey -Reason 'fallback_availability_released_before_retained_frame_application'
                    continue
                }
            }

            if ($matchingDispositions.Count -eq 0) {
                Add-RouteTransitionCandidate -Event $commit -Key $candidateKey -Reason 'route_transition_committed_without_exact_disposition'
            }
            continue
        }

        if ($invalidations.Count -gt 0) {
            $routeTransitionBoundedLookupVisitCount += [int64]$dispositionEvents.Count
            [object[]]$matchingDispositions = @($dispositionEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$invalidations[0].Sequence -and
                    (Test-RouteTransitionAuthorityMatch -Authority $prepared -Candidate $_) -and
                    (
                        (Test-RouteTransitionStatus -Event $_ -Allowed @('Invalidated', 'Applied', 'Idempotent')) -or
                        (Get-RouteTransitionField -Event $_ -Name 'disposition') -in @('rolledback', 'terminalinvalidated', 'superseded')
                    )
                } | Sort-Object Sequence, LineNumber)
            if ($matchingDispositions.Count -eq 0) {
                Add-RouteTransitionCandidate -Event $invalidations[0] -Key $candidateKey -Reason 'route_transition_invalidated_without_exact_disposition'
            }
            continue
        }

        if ($terminals.Count -gt 0) {
            Add-RouteTransitionCandidate -Event $terminals[0] -Key $candidateKey -Reason 'route_transition_terminal_without_commit_or_invalidation'
        }
    }

    [string[]]$fallbackV6ProofBootstrapTupleFields = @(
        'session_id',
        'transfer_id',
        'direction',
        'authority_id',
        'bootstrap_generation',
        'fallback_epoch',
        'target_transport_epoch',
        'frame_kind',
        'source_route',
        'source_protocol_version',
        'source_live_route_epoch',
        'source_runtime_generation',
        'source_route_publication_generation',
        'source_route_commit_generation',
        'source_terminal_generation',
        'source_leg_generation',
        'source_transport_epoch',
        'source_bridge_recovery_generation',
        'source_data_session_generation',
        'target_route',
        'target_protocol_version',
        'target_transport')

    function Test-FallbackV6ProofBootstrapTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Command,
            [Parameter(Mandatory = $true)]$Candidate,
            [switch]$RequireWriter,
            [switch]$AllowAuthorityBoundSparse
        )

        $fieldsToMatch = if ($AllowAuthorityBoundSparse) {
            @(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'bootstrap_generation',
                'fallback_epoch',
                'target_transport_epoch')
        }
        else {
            $fallbackV6ProofBootstrapTupleFields
        }
        foreach ($fieldName in $fieldsToMatch) {
            $expected = Get-RouteTransitionField -Event $Command -Name $fieldName
            $actual = Get-RouteTransitionField -Event $Candidate -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($expected) -or
                [string]::IsNullOrWhiteSpace($actual) -or
                -not [string]::Equals(
                    $expected,
                    $actual,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        if ($RequireWriter) {
            $expectedWriter = Get-RouteTransitionField -Event $Command -Name 'log_writer_id'
            $actualWriter = Get-RouteTransitionField -Event $Candidate -Name 'log_writer_id'
            if ([string]::IsNullOrWhiteSpace($expectedWriter) -or
                [string]::IsNullOrWhiteSpace($actualWriter) -or
                -not [string]::Equals(
                    $expectedWriter,
                    $actualWriter,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Get-FallbackV6ProofBootstrapDistinctIdentityKey {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [switch]$IncludeWriter,
            [switch]$AllowAuthorityBoundSparse,
            [string]$Disposition = ''
        )

        $values = New-Object System.Collections.Generic.List[string]
        $fieldsToKey = if ($AllowAuthorityBoundSparse) {
            @(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'bootstrap_generation',
                'fallback_epoch',
                'target_transport_epoch',
                'frame_kind')
        }
        else {
            $fallbackV6ProofBootstrapTupleFields
        }
        foreach ($fieldName in $fieldsToKey) {
            $value = Get-RouteTransitionField -Event $Event -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($value)) {
                return ''
            }
            $values.Add($value.ToLowerInvariant()) | Out-Null
        }
        if ($IncludeWriter) {
            $writer = Get-RouteTransitionField -Event $Event -Name 'log_writer_id'
            if ([string]::IsNullOrWhiteSpace($writer)) {
                return ''
            }
            $values.Add($writer.ToLowerInvariant()) | Out-Null
        }
        if (-not [string]::IsNullOrWhiteSpace($Disposition)) {
            $values.Add($Disposition.ToLowerInvariant()) | Out-Null
        }
        return [string]::Join('|', $values)
    }

    function Test-FallbackV6ProofBootstrapPreparedScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Command,
            [Parameter(Mandatory = $true)]$Prepared
        )

        foreach ($fieldName in @(
                'session_id',
                'transfer_id',
                'direction',
                'source_route',
                'source_protocol_version',
                'source_live_route_epoch',
                'source_runtime_generation',
                'source_route_publication_generation',
                'source_route_commit_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_data_session_generation',
                'target_route',
                'target_protocol_version',
                'target_transport')) {
            $expected = Get-RouteTransitionField -Event $Command -Name $fieldName
            $actual = Get-RouteTransitionField -Event $Prepared -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($expected) -or
                [string]::IsNullOrWhiteSpace($actual) -or
                -not [string]::Equals(
                    $expected,
                    $actual,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    # The original bootstrap-missing correlation covered the pre-command gate.
    # Also retain the exact boundary where the coordinator did issue an outbound
    # proof command, but the proof-only frontier frame was rejected before a
    # physical send. Older retained slices redact the fixed rejection code, so
    # they are accepted only through one unique same-writer command interval.
    foreach ($execution in @($bootstrapExecutionEvents | Sort-Object Sequence, LineNumber)) {
        $routeTransitionBoundedLookupVisitCount += [int64](
            $bootstrapDecisionEvents.Count + $bootstrapAllReceiptEvents.Count +
            $bootstrapPhysicalSendEvents.Count + $bootstrapExecutionEvents.Count +
            $bootstrapPeerFrameDecisionEvents.Count + $preparedEvents.Count)
        if ((Get-RouteTransitionField -Event $execution -Name 'direction') -ne 'outbound' -or
            -not [string]::Equals(
                (Get-RouteTransitionField -Event $execution -Name 'frame_kind'),
                'FrontierRequest',
                [System.StringComparison]::OrdinalIgnoreCase) -or
            -not [string]::Equals(
                (Get-RouteTransitionField -Event $execution -Name 'receipt_status'),
                'Rejected',
                [System.StringComparison]::OrdinalIgnoreCase)) {
            continue
        }

        $frameFingerprint = Get-RouteTransitionField -Event $execution -Name 'frame_fingerprint'
        if (-not [string]::IsNullOrWhiteSpace($frameFingerprint)) {
            continue
        }

        $reasonCode = Get-RouteTransitionField -Event $execution -Name 'reason_code'
        if ([string]::IsNullOrWhiteSpace($reasonCode)) {
            $reasonCode = Get-RouteTransitionField -Event $execution -Name 'decision_reason'
        }
        $legacyRedactedReason = [string]::IsNullOrWhiteSpace($reasonCode) -or
            $reasonCode -in @('[redacted]', '(redacted)')
        if (-not $legacyRedactedReason -and
            $reasonCode -ne 'execution_invalid') {
            continue
        }

        [object[]]$matchingDecisionEvents = @($bootstrapDecisionEvents | Where-Object {
                [int64]$_.Sequence -lt [int64]$execution.Sequence -and
                (Test-FallbackV6ProofBootstrapTupleMatch `
                    -Command $_ `
                    -Candidate $execution `
                    -RequireWriter `
                    -AllowAuthorityBoundSparse)
            } | Sort-Object Sequence, LineNumber)
        $matchingDecisionIdentities = @{}
        foreach ($matchingDecision in $matchingDecisionEvents) {
            $identityKey = Get-FallbackV6ProofBootstrapDistinctIdentityKey `
                -Event $matchingDecision `
                -IncludeWriter `
                -Disposition 'command'
            if (-not [string]::IsNullOrWhiteSpace($identityKey) -and
                -not $matchingDecisionIdentities.ContainsKey($identityKey)) {
                $matchingDecisionIdentities[$identityKey] = $matchingDecision
            }
        }
        if ($matchingDecisionIdentities.Count -ne 1) {
            continue
        }
        $command = @($matchingDecisionIdentities.Values)[0]

        [object[]]$matchingRejectedReceiptEvents = @($bootstrapAllReceiptEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$execution.Sequence -and
                (Test-FallbackV6ProofBootstrapTupleMatch `
                    -Command $command `
                    -Candidate $_ `
                    -RequireWriter `
                    -AllowAuthorityBoundSparse) -and
                [string]::Equals(
                    (Get-RouteTransitionField -Event $_ -Name 'receipt_status'),
                    'Rejected',
                    [System.StringComparison]::OrdinalIgnoreCase) -and
                (Get-RouteTransitionField -Event $_ -Name 'application_status') -in
                    @('Applied', 'Idempotent')
            } | Sort-Object Sequence, LineNumber)
        $matchingRejectedReceiptIdentities = @{}
        foreach ($matchingRejectedReceipt in $matchingRejectedReceiptEvents) {
            $identityKey = Get-FallbackV6ProofBootstrapDistinctIdentityKey `
                -Event $matchingRejectedReceipt `
                -IncludeWriter `
                -AllowAuthorityBoundSparse `
                -Disposition 'rejected_receipt'
            if (-not [string]::IsNullOrWhiteSpace($identityKey) -and
                -not $matchingRejectedReceiptIdentities.ContainsKey($identityKey)) {
                $matchingRejectedReceiptIdentities[$identityKey] = $matchingRejectedReceipt
            }
        }
        if ($matchingRejectedReceiptIdentities.Count -ne 1) {
            continue
        }
        $rejectedReceipt = @($matchingRejectedReceiptIdentities.Values)[0]

        [object[]]$preRejectionSends = @($bootstrapPhysicalSendEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$command.Sequence -and
                [int64]$_.Sequence -lt [int64]$rejectedReceipt.Sequence -and
                (Get-RouteTransitionField -Event $_ -Name 'session_id') -eq
                    (Get-RouteTransitionField -Event $command -Name 'session_id') -and
                (Get-RouteTransitionField -Event $_ -Name 'transfer_id') -eq
                    (Get-RouteTransitionField -Event $command -Name 'transfer_id') -and
                (Get-RouteTransitionField -Event $_ -Name 'direction') -eq 'outbound' -and
                (Get-RouteTransitionField -Event $_ -Name 'transport_epoch') -eq
                    (Get-RouteTransitionField -Event $command -Name 'target_transport_epoch')
            } | Select-Object -First 1)
        if ($preRejectionSends.Count -gt 0) {
            continue
        }

        [object[]]$laterDelivered = @($bootstrapExecutionEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$rejectedReceipt.Sequence -and
                (Test-FallbackV6ProofBootstrapTupleMatch `
                    -Command $command `
                    -Candidate $_ `
                    -RequireWriter `
                    -AllowAuthorityBoundSparse) -and
                (Get-RouteTransitionField -Event $_ -Name 'receipt_status') -eq 'Delivered' -and
                -not [string]::IsNullOrWhiteSpace(
                    (Get-RouteTransitionField -Event $_ -Name 'frame_fingerprint'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$laterDeliveredReceiptEvents = @($bootstrapAllReceiptEvents | Where-Object {
                $laterDelivered.Count -gt 0 -and
                [int64]$_.Sequence -gt [int64]$laterDelivered[0].Sequence -and
                (Test-FallbackV6ProofBootstrapTupleMatch `
                    -Command $command `
                    -Candidate $_ `
                    -RequireWriter `
                    -AllowAuthorityBoundSparse) -and
                [string]::Equals(
                    (Get-RouteTransitionField -Event $_ -Name 'receipt_status'),
                    'Delivered',
                    [System.StringComparison]::OrdinalIgnoreCase) -and
                (Get-RouteTransitionField -Event $_ -Name 'application_status') -in
                    @('Applied', 'Idempotent')
            } | Sort-Object Sequence, LineNumber)
        $laterDeliveredReceiptIdentities = @{}
        foreach ($laterDeliveredReceipt in $laterDeliveredReceiptEvents) {
            $identityKey = Get-FallbackV6ProofBootstrapDistinctIdentityKey `
                -Event $laterDeliveredReceipt `
                -IncludeWriter `
                -AllowAuthorityBoundSparse `
                -Disposition 'delivered_receipt'
            if (-not [string]::IsNullOrWhiteSpace($identityKey) -and
                -not $laterDeliveredReceiptIdentities.ContainsKey($identityKey)) {
                $laterDeliveredReceiptIdentities[$identityKey] = $laterDeliveredReceipt
            }
        }
        $laterDeliveredReceipt = if ($laterDeliveredReceiptIdentities.Count -eq 1) {
            @($laterDeliveredReceiptIdentities.Values)[0]
        }
        else {
            $null
        }
        [object[]]$laterPeerFrame = @($bootstrapPeerFrameDecisionEvents | Where-Object {
                $null -ne $laterDeliveredReceipt -and
                [int64]$_.Sequence -gt [int64]$laterDeliveredReceipt.Sequence -and
                (Test-FallbackV6ProofBootstrapTupleMatch `
                    -Command $command `
                    -Candidate $_ `
                    -AllowAuthorityBoundSparse) -and
                (Get-RouteTransitionField -Event $_ -Name 'status') -in
                    @('Accepted', 'Idempotent')
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$laterPrepared = @($preparedEvents | Where-Object {
                $null -ne $laterDeliveredReceipt -and
                [int64]$_.Sequence -gt [int64]$laterDeliveredReceipt.Sequence -and
                (Test-FallbackV6ProofBootstrapPreparedScopeMatch `
                    -Command $command `
                    -Prepared $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($laterDelivered.Count -gt 0 -and
            $null -ne $laterDeliveredReceipt -and
            $laterPeerFrame.Count -gt 0 -and
            $laterPrepared.Count -gt 0) {
            continue
        }

        $candidateKey = Get-FallbackV6ProofBootstrapDistinctIdentityKey `
            -Event $command `
            -IncludeWriter
        if ([string]::IsNullOrWhiteSpace($candidateKey)) {
            continue
        }
        Add-RouteTransitionCandidate `
            -Event $execution `
            -Key $candidateKey `
            -Reason 'outbound_proof_only_frontier_request_rejected_by_ordinary_repair_codec' `
            -Class 'filetransfer_route_transition_tuna_v4_to_post_tuna_fallback_v6_proof_bootstrap_missing'
    }

    # A reciprocal bootstrap frame admitted by the exact command scope is not
    # yet a usable route-transition boundary.  It must be bound to the
    # coordinator-derived proof for that same immutable frame.
    foreach ($peerFrame in @($bootstrapPeerFrameDecisionEvents | Where-Object {
                (Get-RouteTransitionField -Event $_ -Name 'status') -in
                    @('Accepted', 'Idempotent') -and
                -not [string]::IsNullOrWhiteSpace(
                    (Get-RouteTransitionField -Event $_ -Name 'frame_fingerprint'))
            })) {
        $routeTransitionBoundedLookupVisitCount += [int64](
            $bootstrapDecisionEvents.Count + $bootstrapExecutionEvents.Count +
            $bootstrapReceiptEvents.Count + $bootstrapPeerBoundaryBoundEvents.Count +
            $preparedEvents.Count)

        [object[]]$matchingCommands = @($bootstrapDecisionEvents | Where-Object {
                (Test-FallbackV6ProofBootstrapTupleMatch `
                    -Command $_ `
                    -Candidate $peerFrame `
                    -RequireWriter `
                    -AllowAuthorityBoundSparse)
            } | Sort-Object Sequence, LineNumber)
        $commandIdentities = @{}
        foreach ($matchingCommand in $matchingCommands) {
            $identityKey = Get-FallbackV6ProofBootstrapDistinctIdentityKey `
                -Event $matchingCommand `
                -IncludeWriter `
                -Disposition 'command'
            if (-not [string]::IsNullOrWhiteSpace($identityKey) -and
                -not $commandIdentities.ContainsKey($identityKey)) {
                $commandIdentities[$identityKey] = $matchingCommand
            }
        }
        if ($commandIdentities.Count -ne 1) {
            continue
        }
        $command = @($commandIdentities.Values)[0]

        [object[]]$deliveredExecutions = @($bootstrapExecutionEvents | Where-Object {
                (Test-FallbackV6ProofBootstrapTupleMatch `
                    -Command $command `
                    -Candidate $_ `
                    -RequireWriter `
                    -AllowAuthorityBoundSparse) -and
                (Get-RouteTransitionField -Event $_ -Name 'receipt_status') -eq 'Delivered' -and
                -not [string]::IsNullOrWhiteSpace(
                    (Get-RouteTransitionField -Event $_ -Name 'frame_fingerprint'))
            } | Sort-Object Sequence, LineNumber)
        [object[]]$deliveredReceipts = @($bootstrapReceiptEvents | Where-Object {
                (Test-FallbackV6ProofBootstrapTupleMatch `
                    -Command $command `
                    -Candidate $_ `
                    -RequireWriter `
                    -AllowAuthorityBoundSparse)
            } | Sort-Object Sequence, LineNumber)
        if ($deliveredExecutions.Count -eq 0 -or $deliveredReceipts.Count -eq 0) {
            continue
        }

        $frameFingerprint = Get-RouteTransitionField -Event $peerFrame -Name 'frame_fingerprint'
        [object[]]$bound = @($bootstrapPeerBoundaryBoundEvents | Where-Object {
                (Test-FallbackV6ProofBootstrapTupleMatch `
                    -Command $command `
                    -Candidate $_ `
                    -RequireWriter `
                    -AllowAuthorityBoundSparse) -and
                (Get-RouteTransitionField -Event $_ -Name 'status') -in
                    @('Bound', 'Idempotent') -and
                (Get-RouteTransitionField -Event $_ -Name 'frame_fingerprint') -eq
                    $frameFingerprint -and
                (Get-RouteTransitionField -Event $_ -Name 'peer_proof_generation') -notin
                    @('', '0')
            } | Sort-Object Sequence, LineNumber)
        [object[]]$prepared = @($preparedEvents | Where-Object {
                $bound.Count -gt 0 -and
                (Test-FallbackV6ProofBootstrapPreparedScopeMatch `
                    -Command $command `
                    -Prepared $_) -and
                (Get-RouteTransitionField -Event $_ -Name 'retained_frame_fingerprint') -eq
                    $frameFingerprint -and
                (Get-RouteTransitionField -Event $_ -Name 'peer_proof_generation') -notin
                    @('', '0')
            } | Sort-Object Sequence, LineNumber)
        [object[]]$committed = @($commitEvents | Where-Object {
                $prepared.Count -gt 0 -and
                (Test-RouteTransitionAuthorityMatch -Authority $prepared[0] -Candidate $_) -and
                (Test-RouteTransitionStatus -Event $_ -Allowed @('Committed', 'Idempotent'))
            } | Sort-Object Sequence, LineNumber)
        [object[]]$retainedApplied = @($frameAppliedEvents | Where-Object {
                $prepared.Count -gt 0 -and
                (Test-RouteTransitionAuthorityMatch -Authority $prepared[0] -Candidate $_) -and
                (Get-RouteTransitionField -Event $_ -Name 'retained_frame_fingerprint') -eq
                    $frameFingerprint -and
                (Test-RouteTransitionStatus -Event $_ -Allowed @('Applied', 'Idempotent'))
            } | Sort-Object Sequence, LineNumber)
        [object[]]$committedDisposition = @($dispositionEvents | Where-Object {
                $prepared.Count -gt 0 -and
                (Test-RouteTransitionAuthorityMatch -Authority $prepared[0] -Candidate $_) -and
                ((Get-RouteTransitionField -Event $_ -Name 'disposition') -eq 'committed' -or
                 (Test-RouteTransitionStatus -Event $_ -Allowed @('Applied', 'Idempotent')))
            } | Sort-Object Sequence, LineNumber)

        $candidateKey = Get-FallbackV6ProofBootstrapDistinctIdentityKey `
            -Event $command `
            -IncludeWriter
        if ([string]::IsNullOrWhiteSpace($candidateKey)) {
            continue
        }
        Add-RouteTransitionCandidate `
            -Event $peerFrame `
            -Key $candidateKey `
            -Reason 'accepted_bootstrap_peer_frame_not_bound_to_coordinator_proof_frame_pair' `
            -Class 'filetransfer_route_transition_tuna_v4_to_post_tuna_fallback_v6_proof_bootstrap_missing' `
            -Recovered:($bound.Count -gt 0 -and
                $prepared.Count -gt 0 -and
                $committed.Count -gt 0 -and
                $retainedApplied.Count -gt 0 -and
                $committedDisposition.Count -gt 0)
    }

    foreach ($skip in $fallbackBootstrapSkipEvents) {
        $routeTransitionBoundedLookupVisitCount += [int64](
            $commitEvents.Count + $fallbackStartedEvents.Count +
            $fallbackPendingEvents.Count + $preparedEvents.Count +
            $bootstrapDecisionEvents.Count + $bootstrapReceiptEvents.Count +
            $proofEvents.Count)
        $skipSequence = [int64]$skip.Sequence
        $sessionId = Get-RouteTransitionField -Event $skip -Name 'session_id'
        $writerId = Get-RouteTransitionField -Event $skip -Name 'log_writer_id'
        if ([string]::IsNullOrWhiteSpace($sessionId) -or
            [string]::IsNullOrWhiteSpace($writerId)) {
            continue
        }

        [object[]]$matchingCommits = @($commitEvents | Where-Object {
                [int64]$_.Sequence -lt $skipSequence -and
                (Get-RouteTransitionField -Event $_ -Name 'session_id') -eq $sessionId -and
                (Get-RouteTransitionField -Event $_ -Name 'log_writer_id') -eq $writerId -and
                (Get-RouteTransitionField -Event $_ -Name 'target_route') -eq 'file_tuna_v4' -and
                (Get-RouteTransitionField -Event $_ -Name 'target_protocol_version') -eq '4'
            } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 2)
        if ($matchingCommits.Count -ne 1) {
            continue
        }

        $commit = $matchingCommits[0]
        $commitSequence = [int64]$commit.Sequence
        [object[]]$starts = @($fallbackStartedEvents | Where-Object {
                [int64]$_.Sequence -gt $commitSequence -and
                [int64]$_.Sequence -le $skipSequence -and
                (Get-RouteTransitionField -Event $_ -Name 'session_id') -eq $sessionId -and
                (Get-RouteTransitionField -Event $_ -Name 'log_writer_id') -eq $writerId
            } | Sort-Object Sequence, LineNumber)
        [object[]]$pending = @($fallbackPendingEvents | Where-Object {
                [int64]$_.Sequence -gt $commitSequence -and
                [int64]$_.Sequence -le $skipSequence -and
                (Get-RouteTransitionField -Event $_ -Name 'session_id') -eq $sessionId -and
                (Get-RouteTransitionField -Event $_ -Name 'log_writer_id') -eq $writerId
            })
        if ($starts.Count -eq 0 -or $pending.Count -eq 0) {
            continue
        }

        $fallbackEpoch = Get-RouteTransitionField -Event $starts[-1] -Name 'fallback_epoch'
        $transferId = Get-RouteTransitionField -Event $commit -Name 'transfer_id'
        $direction = Get-RouteTransitionField -Event $commit -Name 'direction'
        $deliveredBootstrap = @($bootstrapReceiptEvents | Where-Object {
                (Get-RouteTransitionField -Event $_ -Name 'session_id') -eq $sessionId -and
                (Get-RouteTransitionField -Event $_ -Name 'transfer_id') -eq $transferId -and
                (Get-RouteTransitionField -Event $_ -Name 'direction') -eq $direction -and
                (Get-RouteTransitionField -Event $_ -Name 'fallback_epoch') -eq $fallbackEpoch
            } | Select-Object -First 1)
        $acceptedBootstrapFrame = @($bootstrapPeerFrameDecisionEvents | Where-Object {
                $deliveredBootstrap.Count -gt 0 -and
                (Get-RouteTransitionField -Event $_ -Name 'session_id') -eq $sessionId -and
                (Get-RouteTransitionField -Event $_ -Name 'transfer_id') -eq $transferId -and
                (Get-RouteTransitionField -Event $_ -Name 'direction') -eq $direction -and
                (Get-RouteTransitionField -Event $_ -Name 'fallback_epoch') -eq $fallbackEpoch -and
                (Get-RouteTransitionField -Event $_ -Name 'status') -in
                    @('Accepted', 'Idempotent')
            } | Select-Object -First 1)
        if ($deliveredBootstrap.Count -gt 0 -and $acceptedBootstrapFrame.Count -gt 0) {
            continue
        }
        [object[]]$recoveryPrepared = @($preparedEvents | Where-Object {
                [int64]$_.Sequence -gt $skipSequence -and
                (Get-RouteTransitionField -Event $_ -Name 'session_id') -eq $sessionId -and
                (Get-RouteTransitionField -Event $_ -Name 'transfer_id') -eq $transferId -and
                (Get-RouteTransitionField -Event $_ -Name 'direction') -eq $direction -and
                (Get-RouteTransitionField -Event $_ -Name 'source_route') -eq 'file_tuna_v4' -and
                (Get-RouteTransitionField -Event $_ -Name 'target_route') -eq 'post_tuna_fallback_v6'
            } | Sort-Object Sequence, LineNumber)
        $recovered = $false
        if ($recoveryPrepared.Count -gt 0) {
            $prepared = $recoveryPrepared[0]
            [object[]]$decisions = @($bootstrapDecisionEvents | Where-Object {
                    [int64]$_.Sequence -gt $skipSequence -and
                    [int64]$_.Sequence -lt [int64]$prepared.Sequence -and
                    (Test-RouteTransitionTransferScopeMatch -Authority $commit -Candidate $_)
                })
            [object[]]$receipts = @($bootstrapReceiptEvents | Where-Object {
                    [int64]$_.Sequence -gt $skipSequence -and
                    [int64]$_.Sequence -lt [int64]$prepared.Sequence -and
                    (Test-RouteTransitionTransferScopeMatch -Authority $commit -Candidate $_)
                })
            [object[]]$proofs = @($proofEvents | Where-Object {
                    [int64]$_.Sequence -gt $skipSequence -and
                    [int64]$_.Sequence -lt [int64]$prepared.Sequence -and
                    (Test-RouteTransitionTransferScopeMatch -Authority $commit -Candidate $_)
                })
            $recovered = $decisions.Count -gt 0 -and
                $receipts.Count -gt 0 -and
                $proofs.Count -gt 0
        }
        if ($recovered) {
            continue
        }

        $commitAuthority = Get-RouteTransitionField -Event $commit -Name 'authority_id'
        $candidateKey = "fallback-v6-proof-bootstrap|$sessionId|$transferId|$direction|$commitAuthority|$fallbackEpoch"
        Add-RouteTransitionCandidate `
            -Event $skip `
            -Key $candidateKey.ToLowerInvariant() `
            -Reason 'post_tuna_fallback_v6_proof_bootstrap_gated_on_committed_target_runtime' `
            -Class 'filetransfer_route_transition_tuna_v4_to_post_tuna_fallback_v6_proof_bootstrap_missing'
    }

    foreach ($disposition in @($dispositionEvents | Sort-Object Sequence, LineNumber)) {
        $routeTransitionBoundedLookupVisitCount += [int64]$preparedEvents.Count
        if ((Get-RouteTransitionField -Event $disposition -Name 'disposition') -ne 'committed') {
            continue
        }
        $dispositionAuthorityId = Get-RouteTransitionField -Event $disposition -Name 'authority_id'
        [object[]]$successors = @($preparedEvents | Where-Object {
                [int64]$_.Sequence -lt [int64]$disposition.Sequence -and
                (Test-RouteTransitionTransferScopeMatch -Authority $disposition -Candidate $_) -and
                (Get-RouteTransitionField -Event $_ -Name 'predecessor_authority_id') -eq $dispositionAuthorityId
            } | Sort-Object Sequence, LineNumber)
        if ($successors.Count -gt 0) {
            $key = Get-RouteTransitionIdentityKey -Event $disposition
            if (-not [string]::IsNullOrWhiteSpace($key)) {
                Add-RouteTransitionCandidate -Event $disposition -Key ("stale-disposition|$key") -Reason 'stale_route_transition_disposition_mutated_successor'
            }
        }
    }

    [object[]]$genericRawRecords = @($rawRecords | Where-Object {
            $_.Class -eq 'filetransfer_route_transition_incomplete'
        })
    [object[]]$genericDistinctRecords = @($distinctRecords | Where-Object {
            $_.Class -eq 'filetransfer_route_transition_incomplete'
        })
    return [pscustomobject]@{
        RawCount = $genericRawRecords.Count
        DistinctCount = $genericDistinctRecords.Count
        RecoveredCount = 0
        UnresolvedCount = $genericDistinctRecords.Count
        Verdict = if ($genericDistinctRecords.Count -gt 0) { 'fail' } else { 'pass' }
        RawCandidateRecords = @($rawRecords.ToArray())
        CandidateRecords = @($distinctRecords.ToArray())
        UnresolvedCandidateRecords = @($distinctRecords.ToArray())
        FallbackV6ProofBootstrapMissingRawCount = $fallbackBootstrapRawRecords.Count
        FallbackV6ProofBootstrapMissingDistinctCount = $fallbackBootstrapDistinctRecords.Count
        FallbackV6ProofBootstrapMissingRecoveredCount = $fallbackBootstrapRecoveredKeys.Count
        FallbackV6ProofBootstrapMissingUnresolvedCount =
            $fallbackBootstrapDistinctRecords.Count - $fallbackBootstrapRecoveredKeys.Count
        IndexBuildVisitCount = $routeTransitionIndexBuildVisitCount
        LeaseIndexBuildVisitCount = $routeTransitionLeaseIndexBuildVisitCount
        RegisteredLeaseIndexBuildVisitCount =
            $routeTransitionRegisteredLeaseIndexBuildVisitCount
        RetiredLeaseIndexBuildVisitCount =
            $routeTransitionRetiredLeaseIndexBuildVisitCount
        LeaseExactScopeValidationCount =
            $routeTransitionLeaseExactScopeValidationCount
        BoundedLookupVisitCount = $routeTransitionBoundedLookupVisitCount
    }
}

function Get-FileTransferGuiLiveFallbackFaultWindowCorrelation {
    param(
        [object[]]$Events = @(),
        [string]$LiveRouteProofMode = 'None'
    )

    if (-not [string]::Equals(
            $LiveRouteProofMode,
            'RegularActivationCycle',
            [System.StringComparison]::OrdinalIgnoreCase)) {
        return [pscustomobject]@{
            RawCount = 0
            DistinctCount = 0
            RecoveredCount = 0
            UnresolvedCount = 0
            Verdict = 'pass'
            CandidateRecords = @()
            UnresolvedCandidateRecords = @()
        }
    }

    [object[]]$ordered = @($Events | Where-Object { $null -ne $_ } |
            Sort-Object Sequence, LineNumber)
    [object[]]$commits = @($ordered | Where-Object {
            $_.EventName -eq 'filetransfer_route_transition_committed' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in
                @('Committed', 'Idempotent') -and
            (Get-FileTransferEventField -Event $_ -Name 'target_route' -Default '') -eq
                'file_tuna_v4'
        })
    [object[]]$publications = @($ordered | Where-Object {
            $_.EventName -eq 'filetransfer_route_hint_authorized_publication_accepted'
        })
    [object[]]$dispositions = @($ordered | Where-Object {
            $_.EventName -eq 'filetransfer_route_transition_disposition_applied'
        })
    [object[]]$payloads = @($ordered | Where-Object {
            $_.EventName -in @(
                'filetransfer_data_path_send_result',
                'filetransfer_data_path_receive_result',
                'filetransfer_tuna_data_path_peer_visible')
        })
    [object[]]$terminals = @($ordered | Where-Object {
            $_.EventName -eq 'filetransfer_live_route_epoch_terminal' -and
            (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq
                'file_tuna_v4' -and
            (Get-FileTransferEventField -Event $_ -Name 'terminal_state' -Default '') -eq
                'completed'
        })
    [object[]]$fallbackBoundaries = @($ordered | Where-Object {
            ($_.EventName -eq 'tuna_acceleration_reset' -and
                (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
                    'header_switch_off') -or
            ($_.EventName -eq 'tuna_runtime_locked' -and
                (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
                    'header_switch_off') -or
            $_.EventName -in @(
                'tuna_fallback_started',
                'filetransfer_fallback_v6_proof_bootstrap_decided') -or
            ($_.EventName -eq 'filetransfer_route_transition_prepared' -and
                (Get-FileTransferEventField -Event $_ -Name 'source_route' -Default '') -eq
                    'file_tuna_v4' -and
                (Get-FileTransferEventField -Event $_ -Name 'target_route' -Default '') -eq
                    'post_tuna_fallback_v6')
        })

    function Test-FaultWindowScopeMatch {
        param($Left, $Right)

        foreach ($name in @('session_id', 'transfer_id', 'direction')) {
            $expected = Get-FileTransferEventField -Event $Left -Name $name -Default ''
            $actual = Get-FileTransferEventField -Event $Right -Name $name -Default ''
            if ([string]::IsNullOrWhiteSpace($expected) -or
                [string]::IsNullOrWhiteSpace($actual) -or
                -not [string]::Equals(
                    $expected,
                    $actual,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    $records = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($terminal in $terminals) {
        $terminalSequence = [int64]$terminal.Sequence
        [object[]]$matchingCommits = @($commits | Where-Object {
                [int64]$_.Sequence -lt $terminalSequence -and
                (Test-FaultWindowScopeMatch -Left $_ -Right $terminal)
            } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
        if ($matchingCommits.Count -ne 1) {
            continue
        }

        $commit = $matchingCommits[0]
        $commitSequence = [int64]$commit.Sequence
        $authorityId = Get-FileTransferEventField -Event $commit -Name 'authority_id' -Default ''
        $transitionGeneration = Get-FileTransferEventField -Event $commit -Name 'transition_generation' -Default ''
        $targetPublication = Get-FileTransferEventField -Event $commit -Name 'target_route_publication_generation' -Default ''
        $targetCommit = Get-FileTransferEventField -Event $commit -Name 'target_route_commit_generation' -Default ''
        [object[]]$publication = @($publications | Where-Object {
                [int64]$_.Sequence -ge $commitSequence -and
                [int64]$_.Sequence -lt $terminalSequence -and
                (Test-FaultWindowScopeMatch -Left $commit -Right $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq
                    'file_tuna_v4' -and
                (Get-FileTransferEventField -Event $_ -Name 'route_publication_generation' -Default '') -eq
                    $targetPublication -and
                (Get-FileTransferEventField -Event $_ -Name 'route_commit_generation' -Default '') -eq
                    $targetCommit
            } | Select-Object -First 1)
        [object[]]$disposition = @($dispositions | Where-Object {
                [int64]$_.Sequence -ge $commitSequence -and
                [int64]$_.Sequence -lt $terminalSequence -and
                (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq
                    $authorityId -and
                (Get-FileTransferEventField -Event $_ -Name 'transition_generation' -Default '') -eq
                    $transitionGeneration -and
                ((Get-FileTransferEventField -Event $_ -Name 'disposition' -Default '') -eq
                    'committed' -or
                 (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in
                    @('Applied', 'Idempotent'))
            } | Select-Object -First 1)
        [object[]]$payload = @($payloads | Where-Object {
                [int64]$_.Sequence -ge $commitSequence -and
                [int64]$_.Sequence -lt $terminalSequence -and
                (Test-FaultWindowScopeMatch -Left $commit -Right $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq
                    'file_tuna_v4' -and
                (Get-FileTransferEventField -Event $_ -Name 'route_commit_generation' -Default '') -eq
                    $targetCommit
            } | Select-Object -First 1)
        [object[]]$fallback = @($fallbackBoundaries | Where-Object {
                [int64]$_.Sequence -gt $commitSequence -and
                [int64]$_.Sequence -lt $terminalSequence -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $commit -Name 'session_id' -Default '')
            } | Select-Object -First 1)
        if ($publication.Count -ne 1 -or
            $disposition.Count -ne 1 -or
            $payload.Count -ne 1 -or
            $fallback.Count -ne 0) {
            continue
        }

        $sessionId = Get-FileTransferEventField -Event $terminal -Name 'session_id' -Default ''
        $transferId = Get-FileTransferEventField -Event $terminal -Name 'transfer_id' -Default ''
        $key = "gui-fallback-fault-window|$sessionId|$transferId"
        if (-not $seen.Add($key.ToLowerInvariant())) {
            continue
        }
        $records.Add([pscustomobject]@{
            Class = 'filetransfer_gui_live_fallback_fault_window_missed'
            Event = $terminal
            Reason = 'fallback_switch_off_not_injected_before_completed_transfer'
            DistinctKey = $key
        }) | Out-Null
    }

    return [pscustomobject]@{
        RawCount = $records.Count
        DistinctCount = $records.Count
        RecoveredCount = 0
        UnresolvedCount = $records.Count
        Verdict = if ($records.Count -gt 0) { 'fail' } else { 'pass' }
        CandidateRecords = @($records.ToArray())
        UnresolvedCandidateRecords = @($records.ToArray())
    }
}

function Get-FileTransferRouteTransitionLiveEpochProjectionCorrelation {
    param([object[]]$Events = @())

    [object[]]$orderedEvents =
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$commits = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_route_transition_committed' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in
                @('Committed', 'Idempotent')
        })
    [object[]]$publications = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_route_hint_authorized_publication_accepted'
        })
    [object[]]$dispositions = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_route_transition_disposition_applied'
        })
    [object[]]$payloadEvents = @($orderedEvents | Where-Object {
            $_.EventName -in @(
                'filetransfer_data_path_send_result',
                'filetransfer_data_path_receive_result',
                'filetransfer_tuna_data_path_peer_visible')
        })
    [object[]]$legacyEvents = @($orderedEvents | Where-Object {
            $_.EventName -in @(
                'filetransfer_route_transitioned',
                'filetransfer_route_selected',
                'filetransfer_live_route_epoch_started',
                'filetransfer_live_route_epoch_recovered')
        })
    [object[]]$frameAppliedEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_route_transition_retained_frame_applied'
        })

    function Get-ProjectionField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Name
        )

        $aliases = switch ($Name) {
            'authority_id' { @('authority_id', 'transition_authority_id') }
            'transition_generation' { @('transition_generation', 'operation_generation') }
            'runtime_generation' { @('runtime_generation', 'target_runtime_generation') }
            'terminal_generation' { @('terminal_generation', 'target_terminal_generation') }
            'leg_generation' { @('leg_generation', 'target_leg_generation') }
            'route_publication_generation' {
                @(
                    'route_publication_generation',
                    'target_route_publication_generation',
                    'resulting_route_publication_generation')
            }
            'route_commit_generation' {
                @(
                    'route_commit_generation',
                    'target_route_commit_generation',
                    'resulting_route_commit_generation')
            }
            'route' { @('route', 'target_route', 'projected_target_route') }
            'protocol_version' { @('protocol_version', 'target_protocol_version') }
            default { @($Name) }
        }
        foreach ($alias in @($aliases)) {
            $value = Get-FileTransferEventField -Event $Event -Name $alias -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                if ($Name -eq 'route') {
                    if ([string]::Equals(
                            $value,
                            'FileTunaV4',
                            [System.StringComparison]::OrdinalIgnoreCase)) {
                        return 'file_tuna_v4'
                    }
                    if ([string]::Equals(
                            $value,
                            'PostTunaFallbackV6',
                            [System.StringComparison]::OrdinalIgnoreCase)) {
                        return 'post_tuna_fallback_v6'
                    }
                    if ([string]::Equals(
                            $value,
                            'RegularNknV4Fast',
                            [System.StringComparison]::OrdinalIgnoreCase)) {
                        return 'regular_nkn_v4_fast'
                    }
                }
                return $value
            }
        }
        return ''
    }

    function Test-ProjectionFieldsEqual {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [Parameter(Mandatory = $true)][string[]]$Fields
        )

        foreach ($field in $Fields) {
            $leftValue = Get-ProjectionField -Event $Left -Name $field
            $rightValue = Get-ProjectionField -Event $Right -Name $field
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    $candidateRecords = New-Object System.Collections.Generic.List[object]
    $authoritativeRecords = New-Object System.Collections.Generic.List[object]
    $distinctKeys = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($commit in $commits) {
        $authorityId = Get-ProjectionField -Event $commit -Name 'authority_id'
        $transitionGeneration =
            Get-ProjectionField -Event $commit -Name 'transition_generation'
        $direction = Get-ProjectionField -Event $commit -Name 'direction'
        $sessionId = Get-ProjectionField -Event $commit -Name 'session_id'
        $transferId = Get-ProjectionField -Event $commit -Name 'transfer_id'
        if (@(
                $authorityId,
                $transitionGeneration,
                $direction,
                $sessionId,
                $transferId,
                (Get-ProjectionField -Event $commit -Name 'route'),
                (Get-ProjectionField -Event $commit -Name 'protocol_version'),
                (Get-ProjectionField -Event $commit -Name 'runtime_generation'),
                (Get-ProjectionField -Event $commit -Name 'leg_generation'),
                (Get-ProjectionField -Event $commit -Name 'route_publication_generation'),
                (Get-ProjectionField -Event $commit -Name 'route_commit_generation')) |
                Where-Object { [string]::IsNullOrWhiteSpace($_) } |
                Select-Object -First 1) {
            continue
        }

        $key = @(
            $sessionId,
            $transferId,
            $direction,
            $authorityId,
            $transitionGeneration) -join '|'
        if (-not $distinctKeys.Add($key.ToLowerInvariant())) {
            continue
        }

        [object[]]$matchingPublications = @($publications | Where-Object {
                [int64]$_.Sequence -gt [int64]$commit.Sequence -and
                (Test-ProjectionFieldsEqual -Left $commit -Right $_ -Fields @(
                        'session_id',
                        'transfer_id',
                        'direction',
                        'route',
                        'protocol_version',
                        'runtime_generation',
                        'terminal_generation',
                        'leg_generation',
                        'route_publication_generation',
                        'route_commit_generation'))
            } | Sort-Object Sequence, LineNumber)
        [object[]]$matchingDispositions = @($dispositions | Where-Object {
                [int64]$_.Sequence -gt [int64]$commit.Sequence -and
                (Test-ProjectionFieldsEqual -Left $commit -Right $_ -Fields @(
                        'session_id',
                        'transfer_id',
                        'direction',
                        'authority_id',
                        'transition_generation',
                        'route_publication_generation',
                        'route_commit_generation')) -and
                (
                    (Get-ProjectionField -Event $_ -Name 'disposition') -eq 'committed' -or
                    (Get-ProjectionField -Event $_ -Name 'decision_status') -in
                        @('Applied', 'Committed', 'Idempotent')
                )
            } | Sort-Object Sequence, LineNumber)
        if ($matchingPublications.Count -eq 0 -or $matchingDispositions.Count -eq 0) {
            continue
        }

        $targetRoute = Get-ProjectionField -Event $commit -Name 'route'
        $disposition = $matchingDispositions[0]
        if ($targetRoute -eq 'post_tuna_fallback_v6') {
            [object[]]$matchingFrames = @($frameAppliedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$commit.Sequence -and
                    [int64]$_.Sequence -lt [int64]$disposition.Sequence -and
                    (Test-ProjectionFieldsEqual -Left $commit -Right $_ -Fields @(
                            'session_id',
                            'transfer_id',
                            'direction',
                            'authority_id',
                            'transition_generation'))
                })
            if ($matchingFrames.Count -eq 0) {
                continue
            }
        }

        [object[]]$matchingPayloads = @($payloadEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$disposition.Sequence -and
                (Get-ProjectionField -Event $_ -Name 'delivery_result') -in
                    @('', 'sent', 'received', 'accepted', 'applied') -and
                (Test-ProjectionFieldsEqual -Left $commit -Right $_ -Fields @(
                        'session_id',
                        'transfer_id',
                        'direction',
                        'route',
                        'protocol_version',
                        'runtime_generation',
                        'terminal_generation',
                        'leg_generation',
                        'route_publication_generation',
                        'route_commit_generation'))
            } | Sort-Object Sequence, LineNumber)
        if ($matchingPayloads.Count -eq 0) {
            continue
        }

        $authoritativeRecords.Add([pscustomobject]@{
                Commit = $commit
                Publication = $matchingPublications[0]
                Disposition = $disposition
                Payload = $matchingPayloads[0]
                Key = $key
            }) | Out-Null

        $requiredProjectionNames = @(
            'filetransfer_route_transitioned',
            'filetransfer_route_selected',
            'filetransfer_live_route_epoch_started',
            'filetransfer_live_route_epoch_recovered')
        $missingProjection = $false
        foreach ($projectionName in $requiredProjectionNames) {
            [object[]]$matchingProjection = @($legacyEvents | Where-Object {
                    $_.EventName -eq $projectionName -and
                    [int64]$_.Sequence -gt [int64]$commit.Sequence -and
                    (Test-ProjectionFieldsEqual -Left $commit -Right $_ -Fields @(
                            'session_id',
                            'transfer_id',
                            'direction',
                            'route',
                            'protocol_version',
                            'runtime_generation',
                            'terminal_generation',
                            'leg_generation',
                            'route_publication_generation',
                            'route_commit_generation'))
                })
            if ($matchingProjection.Count -eq 0) {
                $missingProjection = $true
                break
            }
        }
        if ($missingProjection) {
            $candidateRecords.Add([pscustomobject]@{
                    Event = $commit
                    Reason =
                        'committed_route_transition_not_projected_to_live_route_epoch_evidence'
                    DistinctKey = $key
                }) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $candidateRecords.Count
        DistinctCount = $candidateRecords.Count
        RecoveredCount = 0
        UnresolvedCount = $candidateRecords.Count
        Verdict = if ($candidateRecords.Count -gt 0) { 'fail' } else { 'pass' }
        AuthoritativeRecords = @($authoritativeRecords.ToArray())
        CandidateRecords = @($candidateRecords.ToArray())
        UnresolvedCandidateRecords = @($candidateRecords.ToArray())
    }
}

function Get-FileTransferRegularV4ToTunaRouteTransitionCorrelation {
    param([object[]]$Events = @())

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$preparedEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_regular_v4_to_tuna_route_transition_prepared'
        })

    function Get-TransitionField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Name
        )

        $value = Get-FileTransferEventField -Event $Event -Name $Name -Default ''
        if ([string]::IsNullOrWhiteSpace($value) -and
            $Name -eq 'source_data_session_generation') {
            $value = Get-FileTransferEventField -Event $Event -Name 'data_session_generation' -Default ''
        }
        elseif ([string]::IsNullOrWhiteSpace($value) -and
            $Name -eq 'source_route_publication_generation') {
            $value = Get-FileTransferEventField -Event $Event -Name 'route_publication_generation' -Default ''
        }
        elseif ([string]::IsNullOrWhiteSpace($value) -and
            $Name -eq 'captured_lease_fingerprint') {
            $value = Get-FileTransferEventField -Event $Event -Name 'captured_send_fingerprint' -Default ''
        }
        elseif ([string]::IsNullOrWhiteSpace($value) -and
            $Name -eq 'completed_lease_fingerprint') {
            $value = Get-FileTransferEventField -Event $Event -Name 'completed_send_fingerprint' -Default ''
        }
        if ($value -in @('(none)', 'none', '(missing)', '__missing__')) {
            return ''
        }
        if ($Name -eq 'target_route' -and
            [string]::Equals(
                $value,
                'FileTunaV4',
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return 'file_tuna_v4'
        }
        return $value
    }

    function Get-TransitionIdentityKey {
        param([Parameter(Mandatory = $true)]$Event)

        $parts = New-Object System.Collections.Generic.List[string]
        foreach ($fieldName in @(
                'session_id',
                'transfer_id',
                'direction',
                'transition_generation',
                'authority_id')) {
            $value = Get-TransitionField -Event $Event -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($value)) {
                return ''
            }
            $parts.Add($value.ToLowerInvariant()) | Out-Null
        }
        return [string]::Join('|', $parts)
    }

    function Get-TransitionIdentityScopeKey {
        param([Parameter(Mandatory = $true)]$Event)

        $parts = New-Object System.Collections.Generic.List[string]
        foreach ($fieldName in @('session_id', 'transfer_id', 'direction')) {
            $value = Get-TransitionField -Event $Event -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($value)) {
                return ''
            }
            $parts.Add($value.ToLowerInvariant()) | Out-Null
        }
        return [string]::Join('|', $parts)
    }

    function Test-TransitionIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Authority,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $authorityKey = Get-TransitionIdentityKey -Event $Authority
        return -not [string]::IsNullOrWhiteSpace($authorityKey) -and
            $authorityKey -eq (Get-TransitionIdentityKey -Event $Candidate)
    }

    function Test-TransitionStatus {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Allowed
        )

        $status = Get-TransitionField -Event $Event -Name 'status'
        return -not [string]::IsNullOrWhiteSpace($status) -and
            $status -in $Allowed
    }

    function Test-TransitionTransferScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Authority,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $authorityKey = Get-TransitionIdentityScopeKey -Event $Authority
        return -not [string]::IsNullOrWhiteSpace($authorityKey) -and
            $authorityKey -eq (Get-TransitionIdentityScopeKey -Event $Candidate)
    }

    function Test-TransitionSourceScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Authority,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-TransitionTransferScopeMatch -Authority $Authority -Candidate $Candidate)) {
            return $false
        }

        foreach ($fieldName in @(
                'source_route',
                'source_protocol_version',
                'source_live_route_epoch',
                'source_runtime_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_route_publication_generation',
                'source_data_session_generation')) {
            $authorityValue = Get-TransitionField -Event $Authority -Name $fieldName
            $candidateValue = Get-TransitionField -Event $Candidate -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($authorityValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals(
                    $authorityValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-TransitionPartialAuthorityTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Authority,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-TransitionIdentityMatch -Authority $Authority -Candidate $Candidate)) {
            return $false
        }

        foreach ($fieldName in @(
                'source_runtime_generation',
                'source_route_publication_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_data_session_generation')) {
            $expected = Get-TransitionField -Event $Authority -Name $fieldName
            $actual = Get-TransitionField -Event $Candidate -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($expected) -or
                [string]::IsNullOrWhiteSpace($actual) -or
                -not [string]::Equals(
                    $expected,
                    $actual,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-TransitionCompleteAuthorityTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Authority,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-TransitionIdentityMatch -Authority $Authority -Candidate $Candidate)) {
            return $false
        }

        foreach ($fieldName in @(
                'source_route',
                'source_protocol_version',
                'source_live_route_epoch',
                'source_runtime_generation',
                'source_route_publication_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_data_session_generation',
                'transaction_generation',
                'offer_generation',
                'launch_generation',
                'tuna_path_lease_generation',
                'checkpoint_generation',
                'checkpoint_state_epoch',
                'checkpoint_contiguous_frontier',
                'checkpoint_durable_highest',
                'target_route',
                'target_protocol_version',
                'target_transport')) {
            $expected = Get-TransitionField -Event $Authority -Name $fieldName
            $actual = Get-TransitionField -Event $Candidate -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($expected) -or
                [string]::IsNullOrWhiteSpace($actual) -or
                -not [string]::Equals(
                    $expected,
                    $actual,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Get-TransitionAuthoritySignature {
        param([Parameter(Mandatory = $true)]$Event)

        return (@(
                'session_id',
                'transfer_id',
                'direction',
                'transition_generation',
                'authority_id',
                'source_route',
                'source_protocol_version',
                'source_live_route_epoch',
                'source_runtime_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_route_publication_generation',
                'source_data_session_generation',
                'transaction_generation',
                'offer_generation',
                'launch_generation',
                'tuna_path_lease_generation',
                'checkpoint_generation',
                'checkpoint_state_epoch',
                'checkpoint_contiguous_frontier',
                'checkpoint_durable_highest',
                'target_route',
                'target_protocol_version',
                'target_transport') | ForEach-Object {
                    (Get-TransitionField -Event $Event -Name $_).ToLowerInvariant()
                }) -join '|'
    }

    function Test-TransitionPreparedShape {
        param([Parameter(Mandatory = $true)]$Event)

        return (Test-TransitionStatus -Event $Event -Allowed @('Prepared', 'Idempotent')) -and
            -not [string]::IsNullOrWhiteSpace((Get-TransitionIdentityKey -Event $Event)) -and
            (Get-TransitionField -Event $Event -Name 'source_route') -eq 'regular_nkn_v4_fast' -and
            (Get-TransitionField -Event $Event -Name 'source_protocol_version') -eq '4' -and
            (Get-TransitionField -Event $Event -Name 'target_route') -eq 'file_tuna_v4' -and
            (Get-TransitionField -Event $Event -Name 'target_protocol_version') -eq '4' -and
            (Get-TransitionField -Event $Event -Name 'target_transport') -eq 'tuna'
    }

    function Test-TransitionReceiptComplete {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$Receipt
        )

        if (-not (Test-TransitionPartialAuthorityTupleMatch -Authority $Prepared -Candidate $Receipt) -or
            (Get-TransitionField -Event $Receipt -Name 'status') -notin @('Accepted', 'Idempotent')) {
            return $false
        }

        if ((Get-TransitionField -Event $Receipt -Name 'outcome') -ne 'Completed') {
            return $false
        }

        $captured = Get-FileTransferEventInt64Field -Event $Receipt -Name 'captured_send_count' -Default -1
        $completed = Get-FileTransferEventInt64Field -Event $Receipt -Name 'completed_send_count' -Default -1
        $capturedFingerprint = Get-TransitionField -Event $Receipt -Name 'captured_lease_fingerprint'
        $completedFingerprint = Get-TransitionField -Event $Receipt -Name 'completed_lease_fingerprint'
        return $captured -ge 0 -and
            $captured -eq $completed -and
            -not [string]::IsNullOrWhiteSpace($capturedFingerprint) -and
            [string]::Equals(
                $capturedFingerprint,
                $completedFingerprint,
                [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Test-TransitionPauseBound {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$PauseBound
        )

        if (-not (Test-TransitionPartialAuthorityTupleMatch -Authority $Prepared -Candidate $PauseBound)) {
            return $false
        }
        $status = Get-TransitionField -Event $PauseBound -Name 'status'
        if ([string]::IsNullOrWhiteSpace($status)) {
            $status = Get-TransitionField -Event $PauseBound -Name 'bind_status'
        }
        return $status -in @('Accepted', 'Installed', 'Idempotent')
    }

    function Test-TransitionAtomicCommitShape {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$Commit
        )

        if (-not (Test-TransitionIdentityMatch -Authority $Prepared -Candidate $Commit)) {
            return $false
        }

        $sourceRuntimeGeneration = Get-FileTransferEventInt64Field `
            -Event $Prepared `
            -Name 'source_runtime_generation' `
            -Default 0
        $sourceLegGeneration = Get-FileTransferEventInt64Field `
            -Event $Prepared `
            -Name 'source_leg_generation' `
            -Default 0
        $sourcePublicationGeneration = Get-FileTransferEventInt64Field `
            -Event $Prepared `
            -Name 'source_route_publication_generation' `
            -Default 0
        return (Get-FileTransferEventInt64Field -Event $Commit -Name 'target_runtime_generation' -Default 0) -gt
                $sourceRuntimeGeneration -and
            (Get-FileTransferEventInt64Field -Event $Commit -Name 'target_leg_generation' -Default 0) -gt
                $sourceLegGeneration -and
            (Get-FileTransferEventInt64Field -Event $Commit -Name 'target_route_publication_generation' -Default 0) -gt
                $sourcePublicationGeneration
    }

    function Test-TransitionPrecommitAckMatch {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$Ack
        )

        if (-not (Test-TransitionTransferScopeMatch -Authority $Prepared -Candidate $Ack)) {
            return $false
        }

        foreach ($fieldName in @(
                'transaction_generation',
                'offer_generation',
                'launch_generation',
                'tuna_path_lease_generation')) {
            $expected = Get-TransitionField -Event $Prepared -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($expected)) {
                continue
            }
            $actual = Get-TransitionField -Event $Ack -Name $fieldName
            if ([string]::IsNullOrWhiteSpace($actual) -or
                -not [string]::Equals(
                    $expected,
                    $actual,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-TransitionTerminalDisposition {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$Disposition,
            [Parameter(Mandatory = $true)][string]$ExpectedStatus
        )

        if (-not (Test-TransitionIdentityMatch -Authority $Prepared -Candidate $Disposition)) {
            return $false
        }
        $status = Get-TransitionField -Event $Disposition -Name 'status'
        if (-not [string]::IsNullOrWhiteSpace($status)) {
            return [string]::Equals(
                $status,
                $ExpectedStatus,
                [System.StringComparison]::OrdinalIgnoreCase)
        }

        $dispositionKind = Get-TransitionField -Event $Disposition -Name 'disposition'
        $applyStatus = Get-TransitionField -Event $Disposition -Name 'apply_status'
        if ($applyStatus -notin @('applied', 'idempotent')) {
            return $false
        }
        if ([string]::Equals(
                $ExpectedStatus,
                'Committed',
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $dispositionKind -eq 'committed'
        }
        return $dispositionKind -in @('rolledback', 'terminalinvalidated')
    }

    function Test-TransitionOwnerBoundary {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$Boundary
        )

        if (-not (Test-TransitionTransferScopeMatch -Authority $Prepared -Candidate $Boundary)) {
            return $false
        }

        if ($Boundary.EventName -eq 'filetransfer_leg_started') {
            return (Get-TransitionField -Event $Boundary -Name 'route') -eq 'file_tuna_v4'
        }
        if ($Boundary.EventName -eq 'filetransfer_runtime_owner_workers_retired') {
            return (Get-TransitionField -Event $Boundary -Name 'current_route') -eq 'file_tuna_v4'
        }
        return $Boundary.EventName -eq 'filetransfer_route_transitioned' -and
            (Get-TransitionField -Event $Boundary -Name 'new_route') -eq 'file_tuna_v4'
    }

    $rawCandidateRecords = New-Object System.Collections.Generic.List[object]
    $distinctCandidateRecords = New-Object System.Collections.Generic.List[object]
    $distinctKeys = New-Object 'System.Collections.Generic.HashSet[string]'
    $identityKeys = New-Object 'System.Collections.Generic.HashSet[string]'
    $firstPreparedByKey = @{}
    $preparedSignaturesByKey = @{}

    function Add-TransitionCandidate {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Key,
            [Parameter(Mandatory = $true)][string]$Reason
        )

        $record = [pscustomobject]@{
            Event = $Event
            Reason = $Reason
            DistinctKey = $Key
        }
        $rawCandidateRecords.Add($record) | Out-Null
        if ($distinctKeys.Add($Key)) {
            $distinctCandidateRecords.Add($record) | Out-Null
        }
    }

    foreach ($prepared in @($preparedEvents | Sort-Object Sequence, LineNumber)) {
        if (-not (Test-TransitionPreparedShape -Event $prepared)) {
            continue
        }

        $identityKey = Get-TransitionIdentityKey -Event $prepared
        $scopeKey = Get-TransitionIdentityScopeKey -Event $prepared
        [void]$identityKeys.Add($scopeKey)
        $signature = Get-TransitionAuthoritySignature -Event $prepared
        if ($firstPreparedByKey.ContainsKey($identityKey)) {
            if ($preparedSignaturesByKey[$identityKey] -ne $signature) {
                Add-TransitionCandidate `
                    -Event $prepared `
                    -Key ("transition|{0}" -f $identityKey) `
                    -Reason 'regular_v4_to_tuna_transition_authority_tuple_mutated'
            }
            continue
        }
        $firstPreparedByKey[$identityKey] = $prepared
        $preparedSignaturesByKey[$identityKey] = $signature
    }

    [object[]]$pauseBoundEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_regular_v4_to_tuna_route_transition_pause_bound'
        })
    [object[]]$drainingEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_regular_v4_to_tuna_route_transition_draining'
        })
    [object[]]$receiptEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_regular_v4_to_tuna_route_transition_drain_receipt_decided'
        })
    [object[]]$committedEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_regular_v4_to_tuna_route_transition_committed'
        })
    [object[]]$invalidatedEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_regular_v4_to_tuna_route_transition_invalidated'
        })
    [object[]]$dispositionEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_regular_v4_to_tuna_route_transition_disposition_applied'
        })
    [object[]]$registeredLeaseEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_regular_v4_physical_send_lease_registered'
        })
    [object[]]$precommitAckEvents = @($orderedEvents | Where-Object {
            $_.EventName -eq 'runtime_unlock_precommit_probe_acked'
        })
    [object[]]$ownerBoundaryEvents = @($orderedEvents | Where-Object {
            $_.EventName -in @(
                'filetransfer_leg_started',
                'filetransfer_runtime_owner_workers_retired',
                'filetransfer_route_transitioned')
        })
    [object[]]$terminalEvents = @($orderedEvents | Where-Object {
            $_.EventName -in @(
                'file_transfer_outbound_terminal',
                'file_transfer_inbound_terminal',
                'transfer_terminal',
                'filetransfer_runtime_terminalized')
        })

    foreach ($identityKey in @($firstPreparedByKey.Keys)) {
        $prepared = $firstPreparedByKey[$identityKey]
        $preparedSequence = [int64]$prepared.Sequence
        $candidateKey = "transition|$identityKey"

        [object[]]$mutatedLifecycleEvents = @(
            @($pauseBoundEvents | Where-Object {
                    [int64]$_.Sequence -gt $preparedSequence -and
                    (Test-TransitionIdentityMatch -Authority $prepared -Candidate $_) -and
                    (Test-TransitionStatus -Event $_ -Allowed @('Accepted', 'Installed', 'Idempotent')) -and
                    -not (Test-TransitionPartialAuthorityTupleMatch -Authority $prepared -Candidate $_)
                }) +
            @($drainingEvents | Where-Object {
                    [int64]$_.Sequence -gt $preparedSequence -and
                    (Test-TransitionIdentityMatch -Authority $prepared -Candidate $_) -and
                    (Test-TransitionStatus -Event $_ -Allowed @('Draining', 'Idempotent')) -and
                    -not (Test-TransitionCompleteAuthorityTupleMatch -Authority $prepared -Candidate $_)
                }) +
            @($receiptEvents | Where-Object {
                    [int64]$_.Sequence -gt $preparedSequence -and
                    (Test-TransitionIdentityMatch -Authority $prepared -Candidate $_) -and
                    (Test-TransitionStatus -Event $_ -Allowed @('Accepted', 'Idempotent')) -and
                    -not (Test-TransitionPartialAuthorityTupleMatch -Authority $prepared -Candidate $_)
                }) +
            @($committedEvents | Where-Object {
                    [int64]$_.Sequence -gt $preparedSequence -and
                    (Test-TransitionIdentityMatch -Authority $prepared -Candidate $_) -and
                    (Test-TransitionStatus -Event $_ -Allowed @('Committed', 'Idempotent')) -and
                    -not (Test-TransitionCompleteAuthorityTupleMatch -Authority $prepared -Candidate $_)
                }) +
            @($invalidatedEvents | Where-Object {
                    [int64]$_.Sequence -gt $preparedSequence -and
                    (Test-TransitionIdentityMatch -Authority $prepared -Candidate $_) -and
                    (Test-TransitionStatus -Event $_ -Allowed @('Invalidated', 'Idempotent')) -and
                    -not (Test-TransitionCompleteAuthorityTupleMatch -Authority $prepared -Candidate $_)
                }) |
                Sort-Object Sequence, LineNumber
        )
        if ($mutatedLifecycleEvents.Count -gt 0) {
            Add-TransitionCandidate `
                -Event $mutatedLifecycleEvents[0] `
                -Key $candidateKey `
                -Reason 'regular_v4_to_tuna_transition_authority_tuple_mutated'
            continue
        }

        [object[]]$pauseBound = @($pauseBoundEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-TransitionPauseBound -Prepared $prepared -PauseBound $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$draining = @($drainingEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-TransitionStatus -Event $_ -Allowed @('Draining', 'Idempotent')) -and
                (Test-TransitionCompleteAuthorityTupleMatch -Authority $prepared -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$receipts = @($receiptEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-TransitionIdentityMatch -Authority $prepared -Candidate $_)
            } | Sort-Object Sequence, LineNumber)
        [object[]]$acceptedReceipts = @($receipts | Where-Object {
                Test-TransitionReceiptComplete -Prepared $prepared -Receipt $_
            })
        [object[]]$committed = @($committedEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-TransitionStatus -Event $_ -Allowed @('Committed', 'Idempotent')) -and
                (Test-TransitionCompleteAuthorityTupleMatch -Authority $prepared -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$invalidated = @($invalidatedEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-TransitionStatus -Event $_ -Allowed @('Invalidated', 'Idempotent')) -and
                (Test-TransitionCompleteAuthorityTupleMatch -Authority $prepared -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)

        $terminalSequence = [int64]::MaxValue
        [object[]]$matchingTerminal = @($terminalEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                (Test-TransitionTransferScopeMatch -Authority $prepared -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($matchingTerminal.Count -gt 0) {
            $terminalSequence = [int64]$matchingTerminal[0].Sequence
        }

        $commitSequence = if ($committed.Count -gt 0) {
            [int64]$committed[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        $invalidationSequence = if ($invalidated.Count -gt 0) {
            [int64]$invalidated[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        $operationBoundarySequence = [Math]::Min(
            $terminalSequence,
            [Math]::Min($commitSequence, $invalidationSequence))

        if ($draining.Count -gt 0) {
            [object[]]$postDrainRegistrations = @($registeredLeaseEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$draining[0].Sequence -and
                    [int64]$_.Sequence -lt $operationBoundarySequence -and
                    (Test-TransitionSourceScopeMatch -Authority $prepared -Candidate $_)
                } | Sort-Object Sequence, LineNumber)
            if ($postDrainRegistrations.Count -gt 0) {
                Add-TransitionCandidate `
                    -Event $postDrainRegistrations[0] `
                    -Key $candidateKey `
                    -Reason 'regular_v4_payload_lease_registered_after_transition_draining'
                continue
            }
        }

        $receiptSequence = if ($acceptedReceipts.Count -gt 0) {
            [int64]$acceptedReceipts[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        [object[]]$prematureOwnerBoundaries = @($ownerBoundaryEvents | Where-Object {
                [int64]$_.Sequence -gt $preparedSequence -and
                [int64]$_.Sequence -lt $receiptSequence -and
                [int64]$_.Sequence -lt $operationBoundarySequence -and
                (Test-TransitionOwnerBoundary -Prepared $prepared -Boundary $_)
            } | Sort-Object Sequence, LineNumber)
        if ($prematureOwnerBoundaries.Count -gt 0) {
            Add-TransitionCandidate `
                -Event $prematureOwnerBoundaries[0] `
                -Key $candidateKey `
                -Reason 'tuna_owner_or_publication_installed_before_physical_drain_receipt'
            continue
        }

        if ($committed.Count -gt 0) {
            $commit = $committed[0]
            if ($pauseBound.Count -eq 0 -or
                $draining.Count -eq 0 -or
                [int64]$pauseBound[0].Sequence -ge [int64]$draining[0].Sequence) {
                Add-TransitionCandidate `
                    -Event $commit `
                    -Key $candidateKey `
                    -Reason 'regular_v4_to_tuna_transition_committed_without_exact_physical_drain_receipt'
                continue
            }

            [object[]]$matchingAck = @($precommitAckEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$draining[0].Sequence -and
                    [int64]$_.Sequence -lt [int64]$commit.Sequence -and
                    (Test-TransitionPrecommitAckMatch -Prepared $prepared -Ack $_)
                } | Sort-Object Sequence, LineNumber)
            if ($matchingAck.Count -eq 0) {
                Add-TransitionCandidate `
                    -Event $commit `
                    -Key $candidateKey `
                    -Reason 'regular_v4_to_tuna_transition_committed_without_acked_precommit_proof'
                continue
            }

            [object[]]$orderedAcceptedReceipts = @($acceptedReceipts | Where-Object {
                    [int64]$_.Sequence -gt [int64]$matchingAck[0].Sequence -and
                    [int64]$_.Sequence -lt [int64]$commit.Sequence
                } | Sort-Object Sequence, LineNumber)
            if ($orderedAcceptedReceipts.Count -eq 0) {
                Add-TransitionCandidate `
                    -Event $commit `
                    -Key $candidateKey `
                    -Reason 'regular_v4_to_tuna_transition_committed_without_exact_physical_drain_receipt'
                continue
            }

            if (-not (Test-TransitionAtomicCommitShape -Prepared $prepared -Commit $commit)) {
                Add-TransitionCandidate `
                    -Event $commit `
                    -Key $candidateKey `
                    -Reason 'regular_v4_to_tuna_transition_commit_owner_leg_publication_not_atomic'
                continue
            }

            [object[]]$matchingDisposition = @($dispositionEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$commit.Sequence -and
                    (Test-TransitionTerminalDisposition `
                        -Prepared $prepared `
                        -Disposition $_ `
                        -ExpectedStatus 'Committed')
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($matchingDisposition.Count -eq 0) {
                Add-TransitionCandidate `
                    -Event $commit `
                    -Key $candidateKey `
                    -Reason 'regular_v4_to_tuna_transition_committed_without_pause_disposition'
            }
            continue
        }

        if ($invalidated.Count -gt 0) {
            [object[]]$matchingDisposition = @($dispositionEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$invalidated[0].Sequence -and
                    (Test-TransitionTerminalDisposition `
                        -Prepared $prepared `
                        -Disposition $_ `
                        -ExpectedStatus 'Invalidated')
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($matchingDisposition.Count -eq 0) {
                Add-TransitionCandidate `
                    -Event $invalidated[0] `
                    -Key $candidateKey `
                    -Reason 'regular_v4_to_tuna_transition_invalidated_without_pause_disposition'
            }
            continue
        }

        if ($matchingTerminal.Count -gt 0) {
            Add-TransitionCandidate `
                -Event $matchingTerminal[0] `
                -Key $candidateKey `
                -Reason 'regular_v4_to_tuna_transition_terminal_without_commit_or_invalidation'
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidateRecords.Count
        DistinctCount = $distinctCandidateRecords.Count
        RecoveredCount = 0
        UnresolvedCount = $distinctCandidateRecords.Count
        Verdict = if ($distinctCandidateRecords.Count -gt 0) { 'fail' } else { 'pass' }
        RawCandidateRecords = @($rawCandidateRecords.ToArray())
        CandidateRecords = @($distinctCandidateRecords.ToArray())
        UnresolvedCandidateRecords = @($distinctCandidateRecords.ToArray())
        IdentityScopeKeys = @($identityKeys)
    }
}

function Get-FileTransferRouteTransitionDrainingTransportGraceCorrelation {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [object[]]$events = @(
        $Events |
            Where-Object { $null -ne $_ } |
            Sort-Object Sequence, LineNumber)

    function Get-RouteTransitionGraceField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Name
        )

        [string[]]$aliases = switch ($Name) {
            'operation_generation' {
                @('operation_generation', 'transition_generation')
            }
            'authority_id' {
                @('authority_id', 'operation_id', 'transition_authority_id')
            }
            'source_route_publication_generation' {
                @(
                    'source_route_publication_generation',
                    'route_publication_generation')
            }
            'source_data_session_generation' {
                @(
                    'source_data_session_generation',
                    'data_session_generation')
            }
            'status' {
                @('status', 'decision_status', 'apply_status', 'bind_status')
            }
            default { @($Name) }
        }
        foreach ($alias in $aliases) {
            $value = Get-FileTransferEventField `
                -Event $Event `
                -Name $alias `
                -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @(
                    '(none)',
                    'none',
                    '(missing)',
                    '__missing__')) {
                return $value
            }
        }
        return ''
    }

    function Get-RouteTransitionGraceDirection {
        param([Parameter(Mandatory = $true)]$Event)

        $direction = Get-RouteTransitionGraceField `
            -Event $Event `
            -Name 'direction'
        if (-not [string]::IsNullOrWhiteSpace($direction)) {
            return $direction.ToLowerInvariant()
        }
        if ($Event.EventName -eq 'file_transfer_outbound_terminal') {
            return 'outbound'
        }
        if ($Event.EventName -eq 'file_transfer_inbound_terminal') {
            return 'inbound'
        }
        return ''
    }

    function Test-RouteTransitionGraceTransferMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @('log_writer_id', 'session_id', 'transfer_id')) {
            $leftValue = Get-RouteTransitionGraceField `
                -Event $Left `
                -Name $field
            $rightValue = Get-RouteTransitionGraceField `
                -Event $Right `
                -Name $field
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return (Get-RouteTransitionGraceDirection -Event $Left) -eq
            (Get-RouteTransitionGraceDirection -Event $Right)
    }

    function Test-RouteTransitionGraceAuthorityMatch {
        param(
            [Parameter(Mandatory = $true)]$Prepared,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-RouteTransitionGraceTransferMatch `
                -Left $Prepared `
                -Right $Candidate)) {
            return $false
        }
        foreach ($field in @(
                'authority_id',
                'operation_generation',
                'transition_kind',
                'source_route',
                'source_protocol_version',
                'source_transport',
                'source_live_route_epoch',
                'source_runtime_generation',
                'source_route_publication_generation',
                'source_route_commit_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_data_session_generation',
                'target_route',
                'target_protocol_version',
                'target_transport')) {
            $leftValue = Get-RouteTransitionGraceField `
                -Event $Prepared `
                -Name $field
            $rightValue = Get-RouteTransitionGraceField `
                -Event $Candidate `
                -Name $field
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Get-RouteTransitionGraceKey {
        param([Parameter(Mandatory = $true)]$Prepared)

        return (@(
            Get-RouteTransitionGraceField -Event $Prepared -Name 'log_writer_id'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'session_id'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'transfer_id'
            Get-RouteTransitionGraceDirection -Event $Prepared
            Get-RouteTransitionGraceField -Event $Prepared -Name 'authority_id'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'operation_generation'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_route'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_protocol_version'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_live_route_epoch'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_runtime_generation'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_route_publication_generation'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_terminal_generation'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_leg_generation'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_transport_epoch'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_bridge_recovery_generation'
            Get-RouteTransitionGraceField -Event $Prepared -Name 'source_data_session_generation'
        ) | ForEach-Object { ([string]$_).ToLowerInvariant() }) -join '|'
    }

    [object[]]$preparedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_route_transition_prepared' -and
        (Get-RouteTransitionGraceField -Event $_ -Name 'status') -in @(
            'Prepared',
            'Idempotent')
    })
    [object[]]$graceEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_transport_grace_exhausted' -and
        (Get-RouteTransitionGraceField -Event $_ -Name 'reason') -eq
            'filetransfer_route_transition_draining'
    })
    [object[]]$terminalEvents = @($events | Where-Object {
        $_.EventName -in @(
            'file_transfer_outbound_terminal',
            'file_transfer_inbound_terminal',
            'transfer_terminal',
            'filetransfer_runtime_terminalized')
    })

    $rawRecords = New-Object System.Collections.Generic.List[object]
    $distinctRecords = New-Object System.Collections.Generic.List[object]
    $distinctKeys =
        New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($grace in $graceEvents) {
        [object[]]$matchingPrepared = @($preparedEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$grace.Sequence -and
            (Test-RouteTransitionGraceTransferMatch `
                -Left $_ `
                -Right $grace)
        } | Where-Object {
            $prepared = $_
            $pause = @($events | Where-Object {
                $_.EventName -eq 'filetransfer_route_transition_pause_bound' -and
                [int64]$_.Sequence -gt [int64]$prepared.Sequence -and
                [int64]$_.Sequence -lt [int64]$grace.Sequence -and
                (Test-RouteTransitionGraceAuthorityMatch `
                    -Prepared $prepared `
                    -Candidate $_) -and
                (Get-RouteTransitionGraceField -Event $_ -Name 'status') -in @(
                    'Installed',
                    'Applied',
                    'Idempotent')
            })
            $draining = @($events | Where-Object {
                $_.EventName -eq 'filetransfer_route_transition_draining' -and
                [int64]$_.Sequence -gt [int64]$prepared.Sequence -and
                [int64]$_.Sequence -lt [int64]$grace.Sequence -and
                (Test-RouteTransitionGraceAuthorityMatch `
                    -Prepared $prepared `
                    -Candidate $_) -and
                (Get-RouteTransitionGraceField -Event $_ -Name 'status') -eq
                    'Draining'
            })
            $terminalBeforeGrace = @($events | Where-Object {
                $_.EventName -in @(
                    'filetransfer_route_transition_committed',
                    'filetransfer_route_transition_invalidated') -and
                [int64]$_.Sequence -gt [int64]$prepared.Sequence -and
                [int64]$_.Sequence -lt [int64]$grace.Sequence -and
                (Test-RouteTransitionGraceAuthorityMatch `
                    -Prepared $prepared `
                    -Candidate $_)
            })
            return $pause.Count -gt 0 -and
                $draining.Count -gt 0 -and
                $terminalBeforeGrace.Count -eq 0
        } | Sort-Object Sequence, LineNumber)
        if ($matchingPrepared.Count -ne 1) {
            continue
        }

        $prepared = $matchingPrepared[0]
        [object[]]$failedTerminals = @($terminalEvents | Where-Object {
            if ([int64]$_.Sequence -le [int64]$grace.Sequence -or
                -not (Test-RouteTransitionGraceTransferMatch `
                    -Left $grace `
                    -Right $_)) {
                return $false
            }
            $state = Get-RouteTransitionGraceField -Event $_ -Name 'state'
            $errorCode =
                Get-RouteTransitionGraceField -Event $_ -Name 'error_code'
            return $state -eq 'Failed' -or
                $errorCode -notin @('', '(none)', 'none')
        } | Sort-Object Sequence, LineNumber)
        if ($failedTerminals.Count -eq 0) {
            continue
        }

        [object[]]$invalidations = @($events | Where-Object {
            $_.EventName -eq 'filetransfer_route_transition_invalidated' -and
            [int64]$_.Sequence -gt [int64]$grace.Sequence -and
            (Test-RouteTransitionGraceAuthorityMatch `
                -Prepared $prepared `
                -Candidate $_) -and
            (Get-RouteTransitionGraceField -Event $_ -Name 'status') -eq
                'Invalidated' -and
            (Get-RouteTransitionGraceField `
                -Event $_ `
                -Name 'decision_reason') -in @(
                    'outbound_transfer_terminal',
                    'inbound_transfer_terminal',
                    'terminal_state')
        } | Sort-Object Sequence, LineNumber)
        if ($invalidations.Count -ne 1) {
            continue
        }
        $invalidation = $invalidations[0]

        [object[]]$dispositions = @($events | Where-Object {
            $_.EventName -eq
                'filetransfer_route_transition_disposition_applied' -and
            [int64]$_.Sequence -gt [int64]$invalidation.Sequence -and
            (Test-RouteTransitionGraceAuthorityMatch `
                -Prepared $prepared `
                -Candidate $_) -and
            (Get-RouteTransitionGraceField -Event $_ -Name 'status') -in @(
                'Applied',
                'Idempotent') -and
            (Get-RouteTransitionGraceField `
                -Event $_ `
                -Name 'disposition').Replace('_', '').ToLowerInvariant() -eq
                'terminalinvalidated'
        } | Sort-Object Sequence, LineNumber)
        if ($dispositions.Count -eq 0) {
            continue
        }

        $key = Get-RouteTransitionGraceKey -Prepared $prepared
        if ([string]::IsNullOrWhiteSpace($key)) {
            continue
        }
        $record = [pscustomobject]@{
            Event = $grace
            Prepared = $prepared
            Terminal = $failedTerminals[0]
            Invalidation = $invalidation
            Disposition = $dispositions[0]
            Reason =
                'coordinator_route_transition_draining_treated_as_transport_disconnect'
            DistinctKey = $key
        }
        $rawRecords.Add($record) | Out-Null
        if ($distinctKeys.Add($key)) {
            $distinctRecords.Add($record) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawRecords.Count
        DistinctCount = $distinctRecords.Count
        RecoveredCount = 0
        UnresolvedCount = $distinctRecords.Count
        Verdict = if ($distinctRecords.Count -gt 0) { 'fail' } else { 'none' }
        RecoveredCandidateEvents = @()
        UnresolvedCandidateEvents = @(
            $distinctRecords.ToArray() |
                ForEach-Object { $_.Event })
        UnresolvedCandidateRecords = @($distinctRecords.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockRegularV4RouteCommitSendDrainCorrelation {
    param(
        [object[]]$Events = @(),
        $DataPathIndex = $null
    )

    [object[]]$orderedEvents = @($Events | Sort-Object Sequence, LineNumber)
    if ($null -eq $DataPathIndex) {
        $DataPathIndex =
            New-FileTransferFileTunaV4DataPathCorrelationIndex `
                -Events $orderedEvents
    }
    $coordinatorTransitionProof =
        Get-FileTransferRegularV4ToTunaRouteTransitionCorrelation -Events $orderedEvents
    [object[]]$ownerRetirements = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_runtime_owner_workers_retired' -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
            (Get-FileTransferEventField -Event $_ -Name 'retired_route' -Default '') -eq 'regular_nkn_v4_fast' -and
            (Get-FileTransferEventField -Event $_ -Name 'current_route' -Default '') -eq 'file_tuna_v4'
        })
    [object[]]$routePublications = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_route_transitioned' -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
            (Get-FileTransferEventField -Event $_ -Name 'previous_route' -Default '') -eq 'regular_nkn_v4_fast' -and
            (Get-FileTransferEventField -Event $_ -Name 'previous_protocol_version' -Default '') -eq '4' -and
            (Get-FileTransferEventField -Event $_ -Name 'new_route' -Default '') -eq 'file_tuna_v4' -and
            (Get-FileTransferEventField -Event $_ -Name 'new_protocol_version' -Default '') -eq '4'
        })
    [object[]]$tunaLegStarts = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_leg_started' -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
            (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'file_tuna_v4' -and
            (Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '4' -and
            (Get-FileTransferEventField -Event $_ -Name 'state' -Default '') -eq 'active'
        })
    [object[]]$sendDrainEvents = @($orderedEvents | Where-Object {
            $_.EventName -in @(
                'runtime_unlock_regular_v4_route_commit_send_drain_staged',
                'runtime_unlock_regular_v4_route_commit_send_drain_deferred',
                'runtime_unlock_regular_v4_route_commit_send_drain_completed',
                'runtime_unlock_regular_v4_route_commit_send_drain_invalidated')
        })
    [object[]]$terminalEvents = @($orderedEvents | Where-Object {
            $_.EventName -in @(
                'file_transfer_outbound_terminal',
                'file_transfer_inbound_terminal',
                'transfer_terminal',
                'filetransfer_runtime_terminalized')
        })
    [object[]]$oldRouteSendResults = @($orderedEvents | Where-Object {
            $_.EventName -eq 'filetransfer_data_path_send_result' -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
            (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'regular_nkn_v4_fast' -and
            (Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '4' -and
            (Get-FileTransferEventField -Event $_ -Name 'actual_transport' -Default '') -eq 'regular_nkn' -and
            (Get-FileTransferEventField -Event $_ -Name 'delivery_transport' -Default '') -eq 'regular_nkn' -and
            (Get-FileTransferEventField -Event $_ -Name 'target_transport' -Default '') -eq 'regular_nkn' -and
            (Test-FileTransferFileTunaV4PayloadDataPathEvent -Event $_)
        })

    function Test-OldRouteWriteIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($fieldName in @('session_id', 'transfer_id')) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $fieldName -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-CompleteOwnerRetirement {
        param([Parameter(Mandatory = $true)]$Retirement)

        foreach ($fieldName in @('session_id', 'transfer_id', 'log_writer_id')) {
            if ([string]::IsNullOrWhiteSpace(
                    (Get-FileTransferEventField -Event $Retirement -Name $fieldName -Default ''))) {
                return $false
            }
        }

        $retiredRuntimeGeneration = Get-FileTransferEventInt64Field `
            -Event $Retirement `
            -Name 'retired_runtime_generation' `
            -Default 0
        $currentRuntimeGeneration = Get-FileTransferEventInt64Field `
            -Event $Retirement `
            -Name 'current_runtime_generation' `
            -Default 0
        if ($retiredRuntimeGeneration -le 0 -or
            $currentRuntimeGeneration -le $retiredRuntimeGeneration -or
            (Get-FileTransferEventInt64Field -Event $Retirement -Name 'log_writer_sequence' -Default 0) -le 0) {
            return $false
        }

        return $true
    }

    function Get-MatchingTunaOwnerInstall {
        param(
            [Parameter(Mandatory = $true)]$Retirement
        )

        $writerId = Get-FileTransferEventField -Event $Retirement -Name 'log_writer_id' -Default ''
        $writerSequence = Get-FileTransferEventInt64Field `
            -Event $Retirement `
            -Name 'log_writer_sequence' `
            -Default 0
        $reason = Get-FileTransferEventField -Event $Retirement -Name 'reason' -Default ''
        [object[]]$matchingStarts = @($tunaLegStarts | Where-Object {
                (Test-OldRouteWriteIdentityMatch -Left $Retirement -Right $_) -and
                [string]::Equals(
                    (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                    $writerId,
                    [System.StringComparison]::OrdinalIgnoreCase) -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -gt 0 -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -lt $writerSequence -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'live_route_epoch' -Default 0) -gt 0 -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -gt 0 -and
                -not [string]::IsNullOrWhiteSpace($reason) -and
                [string]::Equals(
                    (Get-FileTransferEventField -Event $_ -Name 'reason' -Default ''),
                    $reason,
                    [System.StringComparison]::OrdinalIgnoreCase)
            } | Sort-Object {
                Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0
            } -Descending)
        if ($matchingStarts.Count -eq 0) {
            return $null
        }

        return $matchingStarts[0]
    }

    function Test-CompleteTunaOwnerInstallBoundary {
        param([Parameter(Mandatory = $true)]$Boundary)

        foreach ($fieldName in @('session_id', 'transfer_id', 'log_writer_id')) {
            if ([string]::IsNullOrWhiteSpace(
                    (Get-FileTransferEventField -Event $Boundary -Name $fieldName -Default ''))) {
                return $false
            }
        }

        if ((Get-FileTransferEventInt64Field -Event $Boundary -Name 'log_writer_sequence' -Default 0) -le 0 -or
            (Get-FileTransferEventInt64Field -Event $Boundary -Name 'live_route_epoch' -Default 0) -le 0 -or
            (Get-FileTransferEventInt64Field -Event $Boundary -Name 'leg_generation' -Default 0) -le 0) {
            return $false
        }

        if ($Boundary.EventName -eq 'filetransfer_leg_started') {
            return $true
        }

        return $Boundary.EventName -eq 'filetransfer_route_transitioned' -and
            (Get-FileTransferEventInt64Field -Event $Boundary -Name 'runtime_generation' -Default 0) -gt 0
    }

    function Get-PriorTunaOwnerInstallBoundaryForSend {
        param([Parameter(Mandatory = $true)]$Send)

        $writerId = Get-FileTransferEventField -Event $Send -Name 'log_writer_id' -Default ''
        $writerSequence = Get-FileTransferEventInt64Field `
            -Event $Send `
            -Name 'log_writer_sequence' `
            -Default 0
        $sendLiveRouteEpoch = Get-FileTransferEventInt64Field `
            -Event $Send `
            -Name 'live_route_epoch' `
            -Default 0
        $sendRuntimeGeneration = Get-FileTransferEventInt64Field `
            -Event $Send `
            -Name 'runtime_generation' `
            -Default 0
        $sendLegGeneration = Get-FileTransferEventInt64Field `
            -Event $Send `
            -Name 'leg_generation' `
            -Default 0
        if ([string]::IsNullOrWhiteSpace($writerId) -or
            $writerSequence -le 0 -or
            $sendRuntimeGeneration -le 0 -or
            $sendLegGeneration -le 0) {
            return $null
        }

        [object[]]$matchingLegStarts = @($tunaLegStarts | Where-Object {
                (Test-OldRouteWriteIdentityMatch -Left $Send -Right $_) -and
                [string]::Equals(
                    (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                    $writerId,
                    [System.StringComparison]::OrdinalIgnoreCase) -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -lt
                    $writerSequence -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'live_route_epoch' -Default 0) -gt
                    $sendLiveRouteEpoch -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -gt
                    $sendLegGeneration -and
                (Test-CompleteTunaOwnerInstallBoundary -Boundary $_)
            } | Sort-Object {
                Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0
            } -Descending)
        if ($matchingLegStarts.Count -gt 0) {
            # Leg installation is the earliest authoritative owner boundary. Prefer it
            # over later worker-retirement or publication telemetry for the same route.
            return $matchingLegStarts[0]
        }

        [object[]]$matchingRoutePublications = @($routePublications | Where-Object {
                (Test-OldRouteWriteIdentityMatch -Left $Send -Right $_) -and
                [string]::Equals(
                    (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                    $writerId,
                    [System.StringComparison]::OrdinalIgnoreCase) -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -lt
                    $writerSequence -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'live_route_epoch' -Default 0) -gt
                    $sendLiveRouteEpoch -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'runtime_generation' -Default 0) -gt
                    $sendRuntimeGeneration -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'leg_generation' -Default 0) -gt
                    $sendLegGeneration -and
                (Test-CompleteTunaOwnerInstallBoundary -Boundary $_)
            } | Sort-Object {
                Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0
            } -Descending)
        if ($matchingRoutePublications.Count -gt 0) {
            return $matchingRoutePublications[0]
        }

        return $null
    }

    function Test-ExactOldRouteWritePayloadMatch {
        param(
            [Parameter(Mandatory = $true)]$Send,
            [Parameter(Mandatory = $true)]$Receive
        )

        if (-not (Test-OldRouteWriteIdentityMatch -Left $Send -Right $Receive) -or
            -not [string]::Equals(
                (Get-FileTransferEventField -Event $Send -Name 'frame_type' -Default ''),
                (Get-FileTransferEventField -Event $Receive -Name 'frame_type' -Default ''),
                [System.StringComparison]::OrdinalIgnoreCase) -or
            (Get-FileTransferEventInt64Field -Event $Send -Name 'raw_payload_bytes' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $Receive -Name 'raw_payload_bytes' -Default 0) -or
            (Get-FileTransferEventInt64Field -Event $Send -Name 'batch_chunk_count' -Default 0) -ne
                (Get-FileTransferEventInt64Field -Event $Receive -Name 'batch_chunk_count' -Default 0) -or
            -not (Test-FileTransferFileTunaV4DataPathHasRange -Event $Send) -or
            -not (Test-FileTransferFileTunaV4DataPathHasRange -Event $Receive)) {
            return $false
        }

        return (Get-FileTransferFileTunaV4DataPathRangeStart -Event $Send) -eq
                (Get-FileTransferFileTunaV4DataPathRangeStart -Event $Receive) -and
            (Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $Send) -eq
                (Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $Receive)
    }

    function Get-RouteCommitSendDrainIdentityKey {
        param([Parameter(Mandatory = $true)]$Event)

        $parts = New-Object System.Collections.Generic.List[string]
        foreach ($fieldName in @('session_id', 'transfer_id', 'direction')) {
            $value = Get-FileTransferEventField -Event $Event -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none')) {
                return ''
            }

            $parts.Add($value.ToLowerInvariant()) | Out-Null
        }

        return [string]::Join('|', $parts)
    }

    function Get-RouteCommitSendDrainTupleKey {
        param([Parameter(Mandatory = $true)]$Event)

        if ((Get-FileTransferEventField -Event $Event -Name 'direction' -Default '') -ne 'outbound' -or
            (Get-FileTransferEventField -Event $Event -Name 'source_route' -Default '') -ne 'regular_nkn_v4_fast' -or
            (Get-FileTransferEventField -Event $Event -Name 'source_protocol_version' -Default '') -ne '4' -or
            (Get-FileTransferEventField -Event $Event -Name 'target_route' -Default '') -ne 'file_tuna_v4' -or
            (Get-FileTransferEventField -Event $Event -Name 'target_protocol_version' -Default '') -ne '4' -or
            (Get-FileTransferEventField -Event $Event -Name 'target_transport' -Default '') -ne 'tuna' -or
            (Get-FileTransferEventInt64Field -Event $Event -Name 'drain_generation' -Default 0) -le 0) {
            return ''
        }

        $parts = New-Object System.Collections.Generic.List[string]
        foreach ($fieldName in @(
                'session_id',
                'transfer_id',
                'direction',
                'drain_generation',
                'source_route',
                'source_protocol_version',
                'source_live_route_epoch',
                'source_runtime_generation',
                'source_terminal_generation',
                'source_leg_generation',
                'source_transport_epoch',
                'source_bridge_recovery_generation',
                'source_route_publication_generation',
                'source_route_commit_generation',
                'source_data_session_generation',
                'transaction_generation',
                'offer_generation',
                'tuna_path_lease_generation',
                'tuna_path_lease_listener_run_id',
                'target_route',
                'target_protocol_version',
                'target_transport',
                'handoff_kind')) {
            $value = Get-FileTransferEventField -Event $Event -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none')) {
                return ''
            }

            $parts.Add($value.ToLowerInvariant()) | Out-Null
        }

        return [string]::Join('|', $parts)
    }

    function Test-RouteCommitSendDrainProbeProgression {
        param(
            [Parameter(Mandatory = $true)]$Stage,
            [Parameter(Mandatory = $true)]$Disposition
        )

        $stageProbeId = Get-FileTransferEventField -Event $Stage -Name 'probe_id' -Default '(none)'
        $dispositionProbeId = Get-FileTransferEventField -Event $Disposition -Name 'probe_id' -Default '(none)'
        $stageHasProbe = $stageProbeId -notin @('', '(none)', 'none')
        $dispositionHasProbe = $dispositionProbeId -notin @('', '(none)', 'none')
        if ($stageHasProbe -and
            (-not $dispositionHasProbe -or
                -not [string]::Equals(
                    $stageProbeId,
                    $dispositionProbeId,
                    [System.StringComparison]::OrdinalIgnoreCase))) {
            return $false
        }

        $stageState = Get-FileTransferEventField -Event $Stage -Name 'probe_state' -Default '(none)'
        $dispositionState = Get-FileTransferEventField -Event $Disposition -Name 'probe_state' -Default '(none)'
        $stateRanks = @{
            none = 0
            '(none)' = 0
            started = 1
            pending = 1
            acked = 2
            acknowledged = 2
            completed = 3
        }
        $normalizedStageState = $stageState.ToLowerInvariant()
        $normalizedDispositionState = $dispositionState.ToLowerInvariant()
        if ($stateRanks.ContainsKey($normalizedStageState) -and
            $stateRanks.ContainsKey($normalizedDispositionState)) {
            return [int]$stateRanks[$normalizedDispositionState] -ge
                [int]$stateRanks[$normalizedStageState]
        }

        return [string]::Equals(
            $stageState,
            $dispositionState,
            [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Test-RouteCommitSendDrainInvalidationRetiredCapturedWrites {
        param([Parameter(Mandatory = $true)]$Invalidation)

        $capturedText = Get-FileTransferEventField `
            -Event $Invalidation `
            -Name 'captured_send_count' `
            -Default ''
        if ([string]::IsNullOrWhiteSpace($capturedText)) {
            # Pre-drain-accounting artifacts used invalidation as the only terminal
            # disposition. Keep that legacy meaning; new evidence is loss-detecting.
            return $true
        }

        $matchingRetiredText = Get-FileTransferEventField `
            -Event $Invalidation `
            -Name 'matching_retired_send_count' `
            -Default ''
        $activeText = Get-FileTransferEventField `
            -Event $Invalidation `
            -Name 'active_send_count' `
            -Default ''
        [int64]$captured = 0
        [int64]$matchingRetired = 0
        [int64]$active = 0
        if (-not [int64]::TryParse($capturedText, [ref]$captured) -or
            -not [int64]::TryParse($matchingRetiredText, [ref]$matchingRetired) -or
            -not [int64]::TryParse($activeText, [ref]$active) -or
            $captured -lt 0 -or
            $matchingRetired -lt 0 -or
            $active -lt 0) {
            return $false
        }

        return $active -eq 0 -and $matchingRetired -ge $captured
    }

    $rawCandidateRecords = New-Object System.Collections.Generic.List[object]
    $distinctCandidateRecords = New-Object System.Collections.Generic.List[object]
    $corroboratingEvents = New-Object System.Collections.Generic.List[object]
    $corroboratingSequences = New-Object 'System.Collections.Generic.HashSet[int64]'
    $distinctKeys = New-Object 'System.Collections.Generic.HashSet[string]'
    $ownerInstallCandidateKeys = @{}
    $routePublicationCandidateTuples = New-Object 'System.Collections.Generic.HashSet[string]'

    function Add-RouteCommitSendDrainCandidate {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$DistinctKey,
            [Parameter(Mandatory = $true)][string]$Reason
        )

        $record = [pscustomobject]@{
            Event = $Event
            Reason = $Reason
        }
        $rawCandidateRecords.Add($record) | Out-Null
        if ($distinctKeys.Add($DistinctKey)) {
            $distinctCandidateRecords.Add($record) | Out-Null
        }
    }

    foreach ($candidateRecord in @($coordinatorTransitionProof.RawCandidateRecords)) {
        Add-RouteCommitSendDrainCandidate `
            -Event $candidateRecord.Event `
            -DistinctKey $candidateRecord.DistinctKey `
            -Reason $candidateRecord.Reason
    }

    function Add-RouteCommitSendDrainCorroboratingMismatch {
        param(
            [Parameter(Mandatory = $true)]$Send,
            [Parameter(Mandatory = $true)]$OwnerBoundary
        )

        $writerId = Get-FileTransferEventField -Event $Send -Name 'log_writer_id' -Default ''
        $minimumSequence = [Math]::Max([int64]$Send.Sequence, [int64]$OwnerBoundary.Sequence)
        [object[]]$receives = @(
            Get-FileTransferFileTunaV4DataPathIndexedPayloadEvents `
                -Index $DataPathIndex `
                -Event $Send |
            Where-Object {
                $_.EventName -eq 'filetransfer_data_path_receive_result' -and
                [int64]$_.Sequence -gt $minimumSequence -and
                (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'inbound' -and
                (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'file_tuna_v4' -and
                (Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '4' -and
                (Get-FileTransferEventField -Event $_ -Name 'actual_transport' -Default '') -eq 'regular_nkn' -and
                (Get-FileTransferEventField -Event $_ -Name 'delivery_transport' -Default '') -eq 'regular_nkn' -and
                (Get-FileTransferEventField -Event $_ -Name 'target_transport' -Default '') -eq 'tuna' -and
                (Test-ExactOldRouteWritePayloadMatch -Send $Send -Receive $_)
            })
        foreach ($receive in @($receives)) {
            $receiveWriterId = Get-FileTransferEventField -Event $receive -Name 'log_writer_id' -Default ''
            $receiveWriterSequence = Get-FileTransferEventInt64Field -Event $receive -Name 'log_writer_sequence' -Default 0
            if ([string]::IsNullOrWhiteSpace($receiveWriterId) -or
                $receiveWriterSequence -le 0 -or
                [string]::Equals($receiveWriterId, $writerId, [System.StringComparison]::OrdinalIgnoreCase)) {
                continue
            }

            [object[]]$mismatches = @(
                Get-FileTransferFileTunaV4DataPathIndexedWriterWindow `
                    -Index $DataPathIndex `
                    -WriterId $receiveWriterId `
                    -AfterSequence $receiveWriterSequence |
                Where-Object {
                    $_.EventName -eq 'filetransfer_tuna_data_path_mismatch' -and
                    (Get-FileTransferEventField -Event $_ -Name 'proof_direction' -Default '') -eq 'receive' -and
                    (Get-FileTransferEventField -Event $_ -Name 'mismatch_reason' -Default '') -eq 'file_tuna_v4_resolved_to_regular_nkn' -and
                    [string]::Equals(
                        (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                        $receiveWriterId,
                        [System.StringComparison]::OrdinalIgnoreCase) -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -gt $receiveWriterSequence -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -le ($receiveWriterSequence + 8) -and
                    (Test-ExactOldRouteWritePayloadMatch -Send $Send -Receive $_)
                })
            if ($mismatches.Count -ne 1) {
                continue
            }

            $mismatch = $mismatches[0]
            $mismatchWriterSequence = Get-FileTransferEventInt64Field `
                -Event $mismatch `
                -Name 'log_writer_sequence' `
                -Default 0
            [object[]]$ignoredEvents = @(
                Get-FileTransferFileTunaV4DataPathIndexedWriterWindow `
                    -Index $DataPathIndex `
                    -WriterId $receiveWriterId `
                    -AfterSequence $mismatchWriterSequence |
                Where-Object {
                    $_.EventName -eq 'filetransfer_data_frame_ignored' -and
                    (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'file_tuna_v4_payload_requires_tuna' -and
                    [string]::Equals(
                        (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                        $receiveWriterId,
                        [System.StringComparison]::OrdinalIgnoreCase) -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -gt $mismatchWriterSequence -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -le ($mismatchWriterSequence + 8) -and
                    (Test-OldRouteWriteIdentityMatch -Left $Send -Right $_) -and
                    (Test-FileTransferFileTunaV4DataPathRangeMatches -Intent $Send -Actual $_)
                })
            if ($ignoredEvents.Count -ne 1) {
                continue
            }

            foreach ($corroborating in @($receive, $mismatch)) {
                if ($corroboratingSequences.Add([int64]$corroborating.Sequence)) {
                    $corroboratingEvents.Add($corroborating) | Out-Null
                }
            }
        }
    }

    [object[]]$stagedOrDeferredDrains = @($sendDrainEvents | Where-Object {
            $_.EventName -in @(
                'runtime_unlock_regular_v4_route_commit_send_drain_staged',
                'runtime_unlock_regular_v4_route_commit_send_drain_deferred') -and
            -not [string]::IsNullOrWhiteSpace((Get-RouteCommitSendDrainTupleKey -Event $_))
        })
    [object[]]$completedDrains = @($sendDrainEvents | Where-Object {
            $_.EventName -eq 'runtime_unlock_regular_v4_route_commit_send_drain_completed' -and
            -not [string]::IsNullOrWhiteSpace((Get-RouteCommitSendDrainTupleKey -Event $_))
        })
    [object[]]$invalidatedDrains = @($sendDrainEvents | Where-Object {
            $_.EventName -eq 'runtime_unlock_regular_v4_route_commit_send_drain_invalidated' -and
            -not [string]::IsNullOrWhiteSpace((Get-RouteCommitSendDrainTupleKey -Event $_))
        })
    $newDrainIdentityKeys = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($drainEvent in @($sendDrainEvents)) {
        $identityKey = Get-RouteCommitSendDrainIdentityKey -Event $drainEvent
        if (-not [string]::IsNullOrWhiteSpace($identityKey)) {
            [void]$newDrainIdentityKeys.Add($identityKey)
        }
    }

    $firstDrainByTuple = @{}
    foreach ($drain in @($stagedOrDeferredDrains | Sort-Object Sequence, LineNumber)) {
        $tupleKey = Get-RouteCommitSendDrainTupleKey -Event $drain
        if (-not $firstDrainByTuple.ContainsKey($tupleKey)) {
            $firstDrainByTuple[$tupleKey] = $drain
        }
    }

    foreach ($routePublication in @($routePublications | Sort-Object Sequence, LineNumber)) {
        $identityKey = Get-RouteCommitSendDrainIdentityKey -Event $routePublication
        [object[]]$matchingStagedDrains = @($stagedOrDeferredDrains | Where-Object {
                [int64]$_.Sequence -lt [int64]$routePublication.Sequence -and
                (Get-RouteCommitSendDrainIdentityKey -Event $_) -eq $identityKey
            } | Sort-Object Sequence, LineNumber -Descending)
        if ($matchingStagedDrains.Count -eq 0) {
            continue
        }

        $stagedDrain = $matchingStagedDrains[0]
        $tupleKey = Get-RouteCommitSendDrainTupleKey -Event $stagedDrain
        $drainGeneration = Get-FileTransferEventInt64Field `
            -Event $stagedDrain `
            -Name 'drain_generation' `
            -Default 0
        $publishedDrainGeneration = Get-FileTransferEventInt64Field `
            -Event $routePublication `
            -Name 'completed_send_drain_generation' `
            -Default 0
        [object[]]$matchingCompleted = @($completedDrains | Where-Object {
                [int64]$_.Sequence -gt [int64]$stagedDrain.Sequence -and
                [int64]$_.Sequence -lt [int64]$routePublication.Sequence -and
                (Get-RouteCommitSendDrainTupleKey -Event $_) -eq $tupleKey -and
                (Test-RouteCommitSendDrainProbeProgression -Stage $stagedDrain -Disposition $_)
            })
        if ($matchingCompleted.Count -gt 0 -and
            $publishedDrainGeneration -eq $drainGeneration) {
            continue
        }

        [object[]]$priorOwnerInstalls = @($ownerRetirements | Where-Object {
                [int64]$_.Sequence -gt [int64]$stagedDrain.Sequence -and
                [int64]$_.Sequence -lt [int64]$routePublication.Sequence -and
                (Get-RouteCommitSendDrainIdentityKey -Event $_) -eq $identityKey -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'retired_runtime_generation' -Default 0) -eq
                    (Get-FileTransferEventInt64Field -Event $stagedDrain -Name 'source_runtime_generation' -Default 0)
            })
        if ($priorOwnerInstalls.Count -gt 0) {
            # The earlier owner-install boundary already proves the missing drain.
            continue
        }

        [void]$routePublicationCandidateTuples.Add($tupleKey)
        Add-RouteCommitSendDrainCandidate `
            -Event $routePublication `
            -DistinctKey ("new-route-without-drain|{0}" -f $tupleKey) `
            -Reason 'tuna_route_published_without_current_send_drain_completion'
    }

    foreach ($ownerInstall in @($ownerRetirements | Sort-Object Sequence, LineNumber)) {
        $identityKey = Get-RouteCommitSendDrainIdentityKey -Event $ownerInstall
        if (-not $newDrainIdentityKeys.Contains($identityKey)) {
            continue
        }

        $retiredRuntimeGeneration = Get-FileTransferEventInt64Field `
            -Event $ownerInstall `
            -Name 'retired_runtime_generation' `
            -Default 0
        [object[]]$matchingStagedDrains = @($stagedOrDeferredDrains | Where-Object {
                [int64]$_.Sequence -lt [int64]$ownerInstall.Sequence -and
                (Get-RouteCommitSendDrainIdentityKey -Event $_) -eq $identityKey -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'source_runtime_generation' -Default 0) -eq
                    $retiredRuntimeGeneration
            } | Sort-Object Sequence, LineNumber -Descending)
        if ($matchingStagedDrains.Count -eq 0) {
            continue
        }

        $stagedDrain = $matchingStagedDrains[0]
        $tupleKey = Get-RouteCommitSendDrainTupleKey -Event $stagedDrain
        if ($routePublicationCandidateTuples.Contains($tupleKey)) {
            # A publication-before-install boundary for this exact drain is earlier.
            continue
        }
        [object[]]$matchingCompleted = @($completedDrains | Where-Object {
                [int64]$_.Sequence -gt [int64]$stagedDrain.Sequence -and
                [int64]$_.Sequence -lt [int64]$ownerInstall.Sequence -and
                (Get-RouteCommitSendDrainTupleKey -Event $_) -eq $tupleKey -and
                (Test-RouteCommitSendDrainProbeProgression -Stage $stagedDrain -Disposition $_)
            })
        if ($matchingCompleted.Count -eq 0) {
            $ownerInstallLookupKey = @(
                $identityKey,
                (Get-FileTransferEventField -Event $ownerInstall -Name 'retired_runtime_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $ownerInstall -Name 'current_runtime_generation' -Default '(missing)')) -join '|'
            $ownerInstallKey = @(
                'new-owner-without-drain',
                $ownerInstallLookupKey,
                (Get-FileTransferEventField -Event $stagedDrain -Name 'drain_generation' -Default '(missing)')) -join '|'
            $ownerInstallCandidateKeys[$ownerInstallLookupKey] = $ownerInstallKey
            Add-RouteCommitSendDrainCandidate `
                -Event $ownerInstall `
                -DistinctKey $ownerInstallKey `
                -Reason 'tuna_owner_installed_without_current_send_drain_completion'
        }
    }

    foreach ($tupleKey in @($firstDrainByTuple.Keys)) {
        $drain = $firstDrainByTuple[$tupleKey]
        [object[]]$exactCompletions = @($completedDrains | Where-Object {
                [int64]$_.Sequence -gt [int64]$drain.Sequence -and
                (Get-RouteCommitSendDrainTupleKey -Event $_) -eq $tupleKey -and
                (Test-RouteCommitSendDrainProbeProgression -Stage $drain -Disposition $_)
            })
        if ($exactCompletions.Count -gt 0) {
            continue
        }

        [object[]]$exactInvalidations = @($invalidatedDrains | Where-Object {
                [int64]$_.Sequence -gt [int64]$drain.Sequence -and
                (Get-RouteCommitSendDrainTupleKey -Event $_) -eq $tupleKey
            } | Sort-Object Sequence, LineNumber)
        if ($exactInvalidations.Count -gt 0) {
            [object[]]$unsafeInvalidations = @($exactInvalidations | Where-Object {
                -not (Test-RouteCommitSendDrainInvalidationRetiredCapturedWrites -Invalidation $_)
            })
            if ($unsafeInvalidations.Count -gt 0) {
                Add-RouteCommitSendDrainCandidate `
                    -Event $unsafeInvalidations[0] `
                    -DistinctKey ("new-drain-invalidated-active|{0}" -f $tupleKey) `
                    -Reason 'captured_physical_sends_not_retired_before_scope_invalidation'
            }
            continue
        }

        $identityKey = Get-RouteCommitSendDrainIdentityKey -Event $drain
        [object[]]$laterOwnerInstalls = @($ownerRetirements | Where-Object {
                [int64]$_.Sequence -gt [int64]$drain.Sequence -and
                (Get-RouteCommitSendDrainIdentityKey -Event $_) -eq $identityKey -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'retired_runtime_generation' -Default 0) -eq
                    (Get-FileTransferEventInt64Field -Event $drain -Name 'source_runtime_generation' -Default 0)
            })
        if ($laterOwnerInstalls.Count -gt 0) {
            continue
        }

        [object[]]$conclusiveBoundaries = @(
            @($terminalEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$drain.Sequence -and
                    (Get-RouteCommitSendDrainIdentityKey -Event $_) -eq $identityKey
                }) |
                Sort-Object Sequence, LineNumber
        )
        if ($conclusiveBoundaries.Count -eq 0) {
            $conclusiveBoundaries = @($orderedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$drain.Sequence -and
                    (Get-RouteCommitSendDrainIdentityKey -Event $_) -eq $identityKey
                } | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)
        }
        if ($conclusiveBoundaries.Count -eq 0) {
            continue
        }

        Add-RouteCommitSendDrainCandidate `
            -Event $conclusiveBoundaries[0] `
            -DistinctKey ("new-drain-missing|{0}" -f $tupleKey) `
            -Reason 'regular_v4_route_commit_send_drain_completion_missing'
    }

    foreach ($send in @($oldRouteSendResults)) {
        $writerId = Get-FileTransferEventField -Event $send -Name 'log_writer_id' -Default ''
        $writerSequence = Get-FileTransferEventInt64Field -Event $send -Name 'log_writer_sequence' -Default 0
        if ([string]::IsNullOrWhiteSpace($writerId) -or $writerSequence -le 0) {
            continue
        }

        $sendRuntimeGeneration = Get-FileTransferEventInt64Field `
            -Event $send `
            -Name 'runtime_generation' `
            -Default 0
        $ownerInstall = Get-PriorTunaOwnerInstallBoundaryForSend -Send $send
        [object[]]$priorOwnerRetirements = @($ownerRetirements | Where-Object {
                (Test-OldRouteWriteIdentityMatch -Left $send -Right $_) -and
                [string]::Equals(
                    (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                    $writerId,
                    [System.StringComparison]::OrdinalIgnoreCase) -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -gt 0 -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -lt $writerSequence
            } | Sort-Object {
                Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0
            } -Descending)
        $retirement = $null
        if ($priorOwnerRetirements.Count -gt 0) {
            $candidateRetirement = $priorOwnerRetirements[0]
            if ((Test-CompleteOwnerRetirement -Retirement $candidateRetirement) -and
                $sendRuntimeGeneration -eq (Get-FileTransferEventInt64Field `
                    -Event $candidateRetirement `
                    -Name 'retired_runtime_generation' `
                    -Default 0)) {
                $retirement = $candidateRetirement
                if ($null -eq $ownerInstall) {
                    $ownerInstall = Get-MatchingTunaOwnerInstall -Retirement $candidateRetirement
                }
            }
        }

        if ($null -eq $ownerInstall) {
            [object[]]$laterOwnerRetirements = @($ownerRetirements | Where-Object {
                    (Test-OldRouteWriteIdentityMatch -Left $send -Right $_) -and
                    [string]::Equals(
                        (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                        $writerId,
                        [System.StringComparison]::OrdinalIgnoreCase) -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -gt $writerSequence -and
                    (Test-CompleteOwnerRetirement -Retirement $_)
                } | Sort-Object {
                    Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0
                })
            if ($laterOwnerRetirements.Count -gt 0) {
                $laterRetirement = $laterOwnerRetirements[0]
                $laterRetiredRuntimeGeneration = Get-FileTransferEventInt64Field `
                    -Event $laterRetirement `
                    -Name 'retired_runtime_generation' `
                    -Default 0
                if ($sendRuntimeGeneration -eq $laterRetiredRuntimeGeneration -and
                    $null -ne (Get-MatchingTunaOwnerInstall -Retirement $laterRetirement)) {
                    Add-RouteCommitSendDrainCorroboratingMismatch `
                        -Send $send `
                        -OwnerBoundary $laterRetirement
                }
            }
            continue
        }

        $ownerBoundaryWriterSequence = Get-FileTransferEventInt64Field `
            -Event $ownerInstall `
            -Name 'log_writer_sequence' `
            -Default 0
        if ($null -eq $retirement) {
            $ownerBoundaryReason = Get-FileTransferEventField -Event $ownerInstall -Name 'reason' -Default ''
            [object[]]$lineageRetirements = @($ownerRetirements | Where-Object {
                    (Test-OldRouteWriteIdentityMatch -Left $send -Right $_) -and
                    [string]::Equals(
                        (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                        $writerId,
                        [System.StringComparison]::OrdinalIgnoreCase) -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -gt
                        $ownerBoundaryWriterSequence -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'retired_runtime_generation' -Default 0) -eq
                        $sendRuntimeGeneration -and
                    -not [string]::IsNullOrWhiteSpace($ownerBoundaryReason) -and
                    [string]::Equals(
                        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default ''),
                        $ownerBoundaryReason,
                        [System.StringComparison]::OrdinalIgnoreCase) -and
                    (Test-CompleteOwnerRetirement -Retirement $_)
                } | Sort-Object {
                    Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0
                })
            if ($lineageRetirements.Count -gt 0) {
                $retirement = $lineageRetirements[0]
            }
        }

        [object[]]$interveningTerminals = @($terminalEvents | Where-Object {
                (Test-OldRouteWriteIdentityMatch -Left $send -Right $_) -and
                [string]::Equals(
                    (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default ''),
                    $writerId,
                    [System.StringComparison]::OrdinalIgnoreCase) -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -gt $ownerBoundaryWriterSequence -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'log_writer_sequence' -Default 0) -lt $writerSequence
            })
        if ($interveningTerminals.Count -gt 0) {
            continue
        }

        $distinctKey = @(
            (Get-FileTransferEventField -Event $send -Name 'session_id' -Default '(missing)'),
            (Get-FileTransferEventField -Event $send -Name 'transfer_id' -Default '(missing)'),
            $writerId,
            $ownerBoundaryWriterSequence,
            $sendRuntimeGeneration,
            (Get-FileTransferEventField -Event $ownerInstall -Name 'live_route_epoch' -Default '(missing)'),
            (Get-FileTransferEventField -Event $ownerInstall -Name 'leg_generation' -Default '(missing)')) -join '|'
        if ($null -ne $retirement) {
            $retirementIdentityKey = Get-RouteCommitSendDrainIdentityKey -Event $retirement
            $ownerInstallLookupKey = @(
                $retirementIdentityKey,
                (Get-FileTransferEventField -Event $retirement -Name 'retired_runtime_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $retirement -Name 'current_runtime_generation' -Default '(missing)')) -join '|'
            if ($ownerInstallCandidateKeys.ContainsKey($ownerInstallLookupKey)) {
                $distinctKey = [string]$ownerInstallCandidateKeys[$ownerInstallLookupKey]
            }
        }
        Add-RouteCommitSendDrainCandidate `
            -Event $send `
            -DistinctKey $distinctKey `
            -Reason 'retired_regular_v4_send_completed_after_tuna_owner_install'
        Add-RouteCommitSendDrainCorroboratingMismatch `
            -Send $send `
            -OwnerBoundary $ownerInstall
    }

    $distinctCount = $distinctCandidateRecords.Count
    return [pscustomobject]@{
        RawCount = $rawCandidateRecords.Count
        DistinctCount = $distinctCount
        RecoveredCount = 0
        UnresolvedCount = $distinctCount
        Verdict = if ($distinctCount -gt 0) { 'fail' } else { 'pass' }
        CandidateEvents = @($distinctCandidateRecords | ForEach-Object { $_.Event })
        CandidateRecords = @($distinctCandidateRecords.ToArray())
        UnresolvedCandidateEvents = @($distinctCandidateRecords | ForEach-Object { $_.Event })
        UnresolvedCandidateRecords = @($distinctCandidateRecords.ToArray())
        RawCandidateEvents = @($rawCandidateRecords | ForEach-Object { $_.Event })
        CorroboratingMismatchEvents = @($corroboratingEvents.ToArray())
        CorroboratingMismatchSequences = @($corroboratingSequences)
        DataPathIndexBuildVisitCount =
            [int64]$DataPathIndex.Statistics.build_visit_count
        DataPathIndexLookupVisitCount =
            [int64]$DataPathIndex.Statistics.bounded_lookup_visit_count
    }
}

function Get-FileTransferFileTunaV4DataPathMismatchProof {
    param(
        [object[]]$Events = @(),
        $RouteCommitSendDrainProof = $null,
        $DataPathIndex = $null
    )

    [object[]]$orderedEvents = @($Events | Sort-Object Sequence, LineNumber)
    if ($null -eq $DataPathIndex) {
        $DataPathIndex =
            New-FileTransferFileTunaV4DataPathCorrelationIndex `
                -Events $orderedEvents
    }
    if ($null -eq $RouteCommitSendDrainProof) {
        $RouteCommitSendDrainProof =
            Get-FileTransferRuntimeUnlockRegularV4RouteCommitSendDrainCorrelation `
                -Events $orderedEvents `
                -DataPathIndex $DataPathIndex
    }
    $corroboratingMismatchSequences =
        New-Object 'System.Collections.Generic.HashSet[int64]'
    foreach ($sequence in @($RouteCommitSendDrainProof.CorroboratingMismatchSequences)) {
        [void]$corroboratingMismatchSequences.Add([int64]$sequence)
    }
    [object[]]$actualEvents = @($orderedEvents | Where-Object {
            Test-FileTransferFileTunaV4DataPathActualEvent -Event $_
        })
    [object[]]$rawMismatchEvents = @($actualEvents | Where-Object {
            $_.EventName -eq 'filetransfer_tuna_data_path_mismatch' -or
            (Get-FileTransferEventField -Event $_ -Name 'actual_transport' -Default '') -eq 'regular_nkn' -or
            (Get-FileTransferEventField -Event $_ -Name 'delivery_transport' -Default '') -eq 'regular_nkn'
        })
    [object[]]$effectiveMismatchEvents = @($rawMismatchEvents | Where-Object {
            -not $corroboratingMismatchSequences.Contains([int64]$_.Sequence) -and
            -not (Test-FileTransferFileTunaV4DataPathMismatchRejectedFailClosed `
                -Mismatch $_ `
                -Events $orderedEvents `
                -DataPathIndex $DataPathIndex)
        })

    return [pscustomobject]@{
        RawCount = [int]$rawMismatchEvents.Count
        EffectiveCount = [int]$effectiveMismatchEvents.Count
        EffectiveEvents = $effectiveMismatchEvents
        DataPathIndexBuildVisitCount =
            [int64]$DataPathIndex.Statistics.build_visit_count
        DataPathIndexLookupVisitCount =
            [int64]$DataPathIndex.Statistics.bounded_lookup_visit_count
    }
}

function Get-FileTransferFileTunaV4DataPathProof {
    param([Parameter(Mandatory = $true)]$Summary)

    $cachePropertyName = '__FileTransferFileTunaV4DataPathProof'
    if ($null -ne $Summary.PSObject.Properties[$cachePropertyName]) {
        return $Summary.PSObject.Properties[$cachePropertyName].Value
    }

    [object[]]$events = @()
    if ($null -ne $Summary.PSObject.Properties['AllEvents']) {
        $events = @($Summary.AllEvents)
    }
    if ($events.Count -eq 0) {
        $events = @($Summary.GlobalEvents + $Summary.TransferEvents)
    }

    $allowedEventNames = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($eventName in @(Get-FileTransferFileTunaV4DataPathEventNames)) {
        [void]$allowedEventNames.Add($eventName)
    }
    [void]$allowedEventNames.Add('filetransfer_v4_chunk_batch_sent')
    [void]$allowedEventNames.Add('filetransfer_v4_repair_sent')
    $events = @($events | Where-Object {
            $null -ne $_ -and $allowedEventNames.Contains($_.EventName)
        } | Sort-Object Sequence, LineNumber)
    [object[]]$intentEvents = @($events | Where-Object { Test-FileTransferFileTunaV4DataPathIntentEvent -Event $_ })
    [object[]]$actualEvents = @($events | Where-Object { Test-FileTransferFileTunaV4DataPathActualEvent -Event $_ })
    $routeTransitionProof = Get-FileTransferRouteTransitionCorrelation `
        -Events $events `
        -AlreadyChronologicallyOrdered
    [object[]]$downstreamEvents = @($events | Where-Object {
            $_.EventName -notin @(
                'filetransfer_route_transition_physical_send_lease_registered',
                'filetransfer_route_transition_physical_send_lease_retired',
                'filetransfer_route_transition_physical_send_lease_rejected')
        })
    $routeTransitionLiveEpochProjectionProof =
        Get-FileTransferRouteTransitionLiveEpochProjectionCorrelation `
            -Events $downstreamEvents
    $routeTransitionTransportGraceProof =
        Get-FileTransferRouteTransitionDrainingTransportGraceCorrelation `
            -Events $downstreamEvents
    $dataPathIndex =
        New-FileTransferFileTunaV4DataPathCorrelationIndex `
            -Events $downstreamEvents
    $routeCommitSendDrainProof =
        Get-FileTransferRuntimeUnlockRegularV4RouteCommitSendDrainCorrelation `
            -Events $downstreamEvents `
            -DataPathIndex $dataPathIndex
    $mismatchProof = Get-FileTransferFileTunaV4DataPathMismatchProof `
        -Events $downstreamEvents `
        -RouteCommitSendDrainProof $routeCommitSendDrainProof `
        -DataPathIndex $dataPathIndex
    [object[]]$mismatchEvents = @($mismatchProof.EffectiveEvents)
    [object[]]$tunaActualEvents = @($actualEvents | Where-Object {
            (Get-FileTransferEventField -Event $_ -Name 'actual_transport' -Default '') -eq 'tuna' -or
            (Get-FileTransferEventField -Event $_ -Name 'delivery_transport' -Default '') -eq 'tuna'
        })
    [object[]]$peerVisibleEvents = @($actualEvents | Where-Object { $_.EventName -eq 'filetransfer_tuna_data_path_peer_visible' })

    $findings = New-Object System.Collections.Generic.List[string]
    $evidence = New-Object System.Collections.Generic.List[object]
    $missingActualProofCount = 0
    $usedPeerVisibleEventIndexes = New-Object 'System.Collections.Generic.HashSet[int]'
    $usedRepairPeerVisibleEventIndexes = New-Object 'System.Collections.Generic.HashSet[int]'
    $peerVisibleAvailableChunkCountsByScopeKey = @{}
    $peerVisibleRangeCountsByRangeKey = @{}
    foreach ($peerVisible in @($peerVisibleEvents)) {
        if (-not (Test-FileTransferFileTunaV4DataPathHasRange -Event $peerVisible)) {
            continue
        }

        $rangeKey = Get-FileTransferFileTunaV4DataPathRangeKey -Event $peerVisible
        if (-not [string]::IsNullOrWhiteSpace($rangeKey)) {
            if (-not $peerVisibleRangeCountsByRangeKey.ContainsKey($rangeKey)) {
                $peerVisibleRangeCountsByRangeKey[$rangeKey] = 0
            }

            $peerVisibleRangeCountsByRangeKey[$rangeKey] = [int]$peerVisibleRangeCountsByRangeKey[$rangeKey] + 1
        }

        $scopeKey = Get-FileTransferFileTunaV4DataPathScopeKey -Event $peerVisible
        if ([string]::IsNullOrWhiteSpace($scopeKey)) {
            continue
        }

        if (-not $peerVisibleAvailableChunkCountsByScopeKey.ContainsKey($scopeKey)) {
            $peerVisibleAvailableChunkCountsByScopeKey[$scopeKey] = New-Object 'System.Collections.Generic.Dictionary[int64,int]'
        }

        $availableChunkCounts = $peerVisibleAvailableChunkCountsByScopeKey[$scopeKey]
        $actualStart = Get-FileTransferFileTunaV4DataPathRangeStart -Event $peerVisible
        $actualEndExclusive = Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $peerVisible
        for ($chunkIndex = $actualStart; $chunkIndex -lt $actualEndExclusive; $chunkIndex++) {
            $chunkKey = [int64]$chunkIndex
            if (-not $availableChunkCounts.ContainsKey($chunkKey)) {
                $availableChunkCounts[$chunkKey] = 0
            }

            $availableChunkCounts[$chunkKey] = [int]$availableChunkCounts[$chunkKey] + 1
        }
    }

    foreach ($intent in @($intentEvents)) {
        if ($intent.EventName -eq 'filetransfer_v4_repair_sent') {
            $requiredRepairChunkCount = Get-FileTransferEventInt64Field -Event $intent -Name 'sent_chunk_count' -Default 0
            if ($requiredRepairChunkCount -le 0) {
                $requiredRepairChunkCount = Get-FileTransferEventInt64Field -Event $intent -Name 'batch_chunk_count' -Default 0
            }

            $intentScopeKey = Get-FileTransferFileTunaV4DataPathScopeKey -Event $intent
            if ($requiredRepairChunkCount -gt 0 -and
                (Test-FileTransferFileTunaV4DataPathHasRange -Event $intent) -and
                -not [string]::IsNullOrWhiteSpace($intentScopeKey) -and
                $peerVisibleAvailableChunkCountsByScopeKey.ContainsKey($intentScopeKey)) {
                $intentStart = Get-FileTransferFileTunaV4DataPathRangeStart -Event $intent
                $intentEndExclusive = Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $intent
                $availableChunkCounts = $peerVisibleAvailableChunkCountsByScopeKey[$intentScopeKey]
                $matchedRepairChunks = New-Object 'System.Collections.Generic.List[int64]'
                $matchedRepairCoverageCount = 0L
                for ($chunkIndex = $intentStart; $chunkIndex -lt $intentEndExclusive; $chunkIndex++) {
                    $chunkKey = [int64]$chunkIndex
                    if ($availableChunkCounts.ContainsKey($chunkKey) -and [int]$availableChunkCounts[$chunkKey] -gt 0) {
                        [void]$matchedRepairChunks.Add($chunkKey)
                        $matchedRepairCoverageCount++
                    }
                }

                if ($matchedRepairCoverageCount -lt $requiredRepairChunkCount) {
                    $missingActualProofCount++
                    $findings.Add(("file_tuna_v4 V4 repair intent had insufficient peer-visible Tuna data-path proof: required_chunks={0}; matched_chunks={1}; intent={2}" -f $requiredRepairChunkCount, $matchedRepairCoverageCount, (Format-FileTransferEvidenceLine -Event $intent))) | Out-Null
                    $evidence.Add($intent) | Out-Null
                }
                else {
                    foreach ($chunkKey in @($matchedRepairChunks)) {
                        $availableChunkCounts[$chunkKey] = [int]$availableChunkCounts[$chunkKey] - 1
                    }
                }

                continue
            }

            $matchedRepairChunkCount = 0L
            $matchedRepairCoveredChunks = New-Object 'System.Collections.Generic.HashSet[int64]'
            $matchedRepairHasRangeProof = $false
            $matchedRepairPeerVisibleIndexes = New-Object 'System.Collections.Generic.List[int]'
            for ($peerVisibleIndex = 0; $peerVisibleIndex -lt $peerVisibleEvents.Count; $peerVisibleIndex++) {
                if ($usedRepairPeerVisibleEventIndexes.Contains([int]$peerVisibleIndex)) {
                    continue
                }

                $peerVisible = $peerVisibleEvents[$peerVisibleIndex]
                if (-not (Test-FileTransferFileTunaV4DataPathSequenceAllowsMatch -Intent $intent -Actual $peerVisible)) {
                    continue
                }

                if ((Test-FileTransferFileTunaV4DataPathScopeMatches -Intent $intent -Actual $peerVisible) -and
                    (Test-FileTransferFileTunaV4DataPathSendShapeMatches -Intent $intent -Actual $peerVisible)) {
                    $actualBatchChunkCount = Get-FileTransferEventInt64Field -Event $peerVisible -Name 'batch_chunk_count' -Default 0
                    if ($actualBatchChunkCount -le 0) {
                        continue
                    }

                    [void]$matchedRepairPeerVisibleIndexes.Add([int]$peerVisibleIndex)
                    $matchedRepairChunkCount += $actualBatchChunkCount
                    if ((Test-FileTransferFileTunaV4DataPathHasRange -Event $intent) -and
                        (Test-FileTransferFileTunaV4DataPathHasRange -Event $peerVisible)) {
                        $matchedRepairHasRangeProof = $true
                        $actualStart = Get-FileTransferFileTunaV4DataPathRangeStart -Event $peerVisible
                        $actualEndExclusive = Get-FileTransferFileTunaV4DataPathRangeEndExclusive -Event $peerVisible
                        for ($chunkIndex = $actualStart; $chunkIndex -lt $actualEndExclusive; $chunkIndex++) {
                            [void]$matchedRepairCoveredChunks.Add([int64]$chunkIndex)
                        }
                    }

                    $matchedRepairEffectiveChunkCount = if ($matchedRepairHasRangeProof) { [int64]$matchedRepairCoveredChunks.Count } else { $matchedRepairChunkCount }
                    if ($requiredRepairChunkCount -gt 0 -and $matchedRepairEffectiveChunkCount -ge $requiredRepairChunkCount) {
                        break
                    }
                }
            }

            $matchedRepairEffectiveChunkCount = if ($matchedRepairHasRangeProof) { [int64]$matchedRepairCoveredChunks.Count } else { $matchedRepairChunkCount }
            if ($requiredRepairChunkCount -gt 0 -and $matchedRepairEffectiveChunkCount -ge $requiredRepairChunkCount) {
                foreach ($peerVisibleIndex in @($matchedRepairPeerVisibleIndexes)) {
                    [void]$usedRepairPeerVisibleEventIndexes.Add([int]$peerVisibleIndex)
                }
            }
            else {
                $missingActualProofCount++
                $findings.Add(("file_tuna_v4 V4 repair intent had insufficient peer-visible Tuna data-path proof: required_chunks={0}; matched_chunks={1}; intent={2}" -f $requiredRepairChunkCount, $matchedRepairEffectiveChunkCount, (Format-FileTransferEvidenceLine -Event $intent))) | Out-Null
                $evidence.Add($intent) | Out-Null
            }

            continue
        }

        $intentRangeKey = Get-FileTransferFileTunaV4DataPathRangeKey -Event $intent
        if (-not [string]::IsNullOrWhiteSpace($intentRangeKey)) {
            if ($peerVisibleRangeCountsByRangeKey.ContainsKey($intentRangeKey) -and
                [int]$peerVisibleRangeCountsByRangeKey[$intentRangeKey] -gt 0) {
                $peerVisibleRangeCountsByRangeKey[$intentRangeKey] = [int]$peerVisibleRangeCountsByRangeKey[$intentRangeKey] - 1
                continue
            }

            $missingActualProofCount++
            $findings.Add(("file_tuna_v4 V4 send intent had no matching peer-visible Tuna data-path proof: intent={0}" -f (Format-FileTransferEvidenceLine -Event $intent))) | Out-Null
            $evidence.Add($intent) | Out-Null
            continue
        }

        $matchedPeerVisibleIndex = -1
        for ($peerVisibleIndex = 0; $peerVisibleIndex -lt $peerVisibleEvents.Count; $peerVisibleIndex++) {
            if ($usedPeerVisibleEventIndexes.Contains([int]$peerVisibleIndex)) {
                continue
            }

            $peerVisible = $peerVisibleEvents[$peerVisibleIndex]
            if (-not (Test-FileTransferFileTunaV4DataPathSequenceAllowsMatch -Intent $intent -Actual $peerVisible)) {
                continue
            }

            if ((Test-FileTransferFileTunaV4DataPathScopeMatches -Intent $intent -Actual $peerVisible) -and
                (Test-FileTransferFileTunaV4DataPathSendShapeMatches -Intent $intent -Actual $peerVisible)) {
                $matchedPeerVisibleIndex = $peerVisibleIndex
                break
            }
        }

        if ($matchedPeerVisibleIndex -ge 0) {
            [void]$usedPeerVisibleEventIndexes.Add([int]$matchedPeerVisibleIndex)
        }
        else {
            $missingActualProofCount++
            $findings.Add(("file_tuna_v4 V4 send intent had no matching peer-visible Tuna data-path proof: intent={0}" -f (Format-FileTransferEvidenceLine -Event $intent))) | Out-Null
            $evidence.Add($intent) | Out-Null
        }
    }

    foreach ($mismatch in @($mismatchEvents)) {
        $findings.Add(("file_tuna_v4 V4 data path resolved to regular NKN: effect={0}" -f (Format-FileTransferEvidenceLine -Event $mismatch))) | Out-Null
        $evidence.Add($mismatch) | Out-Null
    }

    $peerVisiblePayloadBytes = 0L
    foreach ($event in @($peerVisibleEvents)) {
        $peerVisiblePayloadBytes += Get-FileTransferEventInt64Field -Event $event -Name 'payload_bytes' -Default 0
    }

    $verdict = if ($intentEvents.Count -eq 0 -and $actualEvents.Count -eq 0) { 'none' } elseif ($findings.Count -eq 0) { 'pass' } else { 'fail' }
    $proof = [pscustomobject]@{
        Verdict = $verdict
        FailureClass = if ($verdict -eq 'fail') { 'file_tuna_data_path_mismatch' } else { 'none' }
        IntendedSendCount = [int]$intentEvents.Count
        ActualTunaSendCount = [int]$tunaActualEvents.Count
        ActualRegularNknSendCount = [int]$mismatchEvents.Count
        MismatchCount = [int]$mismatchEvents.Count
        MissingActualProofCount = [int]$missingActualProofCount
        PeerVisiblePayloadBytes = [long]$peerVisiblePayloadBytes
        Findings = $findings
        EvidenceEvents = @($evidence.ToArray() | Select-Object -First 20)
        RouteTransitionProof = $routeTransitionProof
        RouteTransitionLiveEpochProjectionProof =
            $routeTransitionLiveEpochProjectionProof
        RouteTransitionTransportGraceProof =
            $routeTransitionTransportGraceProof
        RouteCommitSendDrainProof = $routeCommitSendDrainProof
    }
    $Summary | Add-Member -NotePropertyName $cachePropertyName -NotePropertyValue $proof -Force
    return $proof
}

function Get-FileTransferPublicationAuthorityFieldCoverageProof {
    param([Parameter(Mandatory = $true)]$Summary)

    [object[]]$events = @()
    if ($null -ne $Summary.PSObject.Properties['AllEvents']) {
        $events = @($Summary.AllEvents)
    }
    if ($events.Count -eq 0) {
        $events = @($Summary.GlobalEvents + $Summary.TransferEvents)
    }

    $events = @($events | Sort-Object Sequence)
    [object[]]$publicationEvents = @($events | Where-Object { Test-FileTransferPublicationAuthorityFieldEvent -Event $_ })
    $findings = New-Object System.Collections.Generic.List[string]
    $evidence = New-Object System.Collections.Generic.List[object]
    $missingFieldCount = 0

    foreach ($event in @($publicationEvents)) {
        foreach ($fieldName in @(Get-FileTransferPublicationAuthorityRequiredFields -Event $event)) {
            if (Test-FileTransferPublicationAuthorityFieldValue -Event $event -FieldName $fieldName) {
                continue
            }

            $missingFieldCount++
            $findings.Add(("publication authority field missing or invalid field={0}: {1}" -f $fieldName, (Format-FileTransferEvidenceLine -Event $event))) | Out-Null
            $evidence.Add($event) | Out-Null
        }
    }

    $verdict = if ($publicationEvents.Count -eq 0) { 'none' } elseif ($findings.Count -eq 0) { 'pass' } else { 'fail' }
    return [pscustomobject]@{
        Verdict = $verdict
        FailureClass = if ($verdict -eq 'fail') { 'publication_authority_missing' } else { 'none' }
        CheckedEventCount = [int]$publicationEvents.Count
        MissingFieldCount = [int]$missingFieldCount
        Findings = $findings
        EvidenceEvents = @($evidence.ToArray() | Select-Object -First 20)
    }
}

function Test-FileTransferFallbackLocalDeliveryWithoutPeerVisibleProof {
    param([Parameter(Mandatory = $true)]$Event)

    if ($Event.EventName -ne 'filetransfer_control_plane_delivery_result' -and
        $Event.EventName -ne 'filetransfer_control_plane_delivery_observed') {
        return $false
    }

    $acceptedAny = Get-FileTransferEventField -Event $Event -Name 'accepted_any' -Default '0'
    $peerVisibleAny = Get-FileTransferEventField -Event $Event -Name 'peer_visible_any' -Default '0'
    $controlQueue = Get-FileTransferEventField -Event $Event -Name 'control_queue' -Default '0'
    $localOnlyRejected = Get-FileTransferEventField -Event $Event -Name 'local_only_rejected' -Default '0'
    if ($peerVisibleAny -eq '1') {
        return $false
    }

    if ($acceptedAny -ne '1' -and $controlQueue -ne '1' -and $localOnlyRejected -ne '1') {
        return $false
    }

    $route = Get-FileTransferEventField -Event $Event -Name 'route' -Default ''
    $kind = (Get-FileTransferEventField -Event $Event -Name 'kind' -Default '').ToLowerInvariant()
    $reason = (Get-FileTransferEventField -Event $Event -Name 'reason' -Default '').ToLowerInvariant()
    return ($route -eq 'post_tuna_fallback_v6' -or
        $kind -match 'fallback|receiver_state|frontier_request' -or
        $reason -match 'fallback|checkpoint|receiver_state|frontier')
}

function Test-FileTransferFallbackPeerVisibleCompletion {
    param([Parameter(Mandatory = $true)]$Event)

    if ($Event.EventName -ne 'filetransfer_control_plane_delivery_result' -and
        $Event.EventName -ne 'filetransfer_control_plane_delivery_observed') {
        return $false
    }

    $peerVisibleAny = Get-FileTransferEventField -Event $Event -Name 'peer_visible_any' -Default '0'
    if ($peerVisibleAny -ne '1') {
        return $false
    }

    $route = Get-FileTransferEventField -Event $Event -Name 'route' -Default ''
    $kind = (Get-FileTransferEventField -Event $Event -Name 'kind' -Default '').ToLowerInvariant()
    $reason = (Get-FileTransferEventField -Event $Event -Name 'reason' -Default '').ToLowerInvariant()
    return ($route -eq 'post_tuna_fallback_v6' -or
        $kind -match 'fallback|receiver_state|frontier_request' -or
        $reason -match 'fallback|checkpoint|receiver_state|frontier')
}

function Get-FileTransferStaleRejectedActionEffectProof {
    param([Parameter(Mandatory = $true)]$Summary)

    [object[]]$events = @()
    if ($null -ne $Summary.PSObject.Properties['AllEvents']) {
        $events = @($Summary.AllEvents)
    }
    if ($events.Count -eq 0) {
        $events = @($Summary.GlobalEvents + $Summary.TransferEvents)
    }

    $events = @($events | Sort-Object Sequence)
    $rejections = @($events | Where-Object {
            $_.EventName -eq 'filetransfer_runtime_owner_stale_update_rejected' -or
            $_.EventName -eq 'filetransfer_coordinator_leg_mutation_rejected' -or
            $_.EventName -eq 'filetransfer_runtime_unlock_callback_rejected' -or
            $_.EventName -eq 'filetransfer_runtime_unlock_precommit_probe_pending_rejected' -or
            $_.EventName -eq 'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery' -or
            $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_rejected' -or
            $_.EventName -eq 'filetransfer_recovery_authority_rejected' -or
            $_.EventName -eq 'filetransfer_route_publication_rejected' -or
            $_.EventName -eq 'filetransfer_route_hint_ignored_missing_publication_authority' -or
            $_.EventName -eq 'filetransfer_route_hint_ignored_stale_publication_authority' -or
            $_.EventName -eq 'filetransfer_route_hint_ignored_invalid_publication_authority'
        })
    $families = @('liveness', 'repair', 'progress', 'checkpoint', 'bridge_recovery', 'control_plane', 'route_publication')
    $familyCounts = @{}
    foreach ($family in @($families)) {
        $familyCounts[$family] = 0
    }
    $fallbackSubfamilies = @('fallback_send', 'fallback_checkpoint', 'fallback_reissue', 'fallback_tail_yield', 'fallback_pressure')
    $fallbackSubfamilyCounts = @{}
    foreach ($subfamily in @($fallbackSubfamilies)) {
        $fallbackSubfamilyCounts[$subfamily] = 0
    }

    $unknownActionCount = 0
    $forbiddenEffectCount = 0
    $findings = New-Object System.Collections.Generic.List[string]
    $evidence = New-Object System.Collections.Generic.List[object]
    $failureEvents = New-Object System.Collections.Generic.List[object]

    foreach ($rejection in @($rejections | Sort-Object Sequence)) {
        $family = Get-FileTransferStaleRejectedProofActionFamily -Event $rejection
        $fallbackSubfamily = Get-FileTransferStaleRejectedProofFallbackSubfamily -Event $rejection
        if ($family -eq 'unknown') {
            $unknownActionCount++
            $actionKind = Get-FileTransferEventField -Event $rejection -Name 'action_kind' -Default '(none)'
            $attemptedAction = Get-FileTransferEventField -Event $rejection -Name 'attempted_action' -Default '(none)'
            $findings.Add(("unknown stale rejected authority action action_kind={0} attempted_action={1}: {2}" -f $actionKind, $attemptedAction, (Format-FileTransferEvidenceLine -Event $rejection))) | Out-Null
            $evidence.Add($rejection) | Out-Null
            $failureEvents.Add($rejection) | Out-Null
            continue
        }

        foreach ($effect in @($events | Where-Object { $_.Sequence -gt $rejection.Sequence })) {
            if (-not (Test-FileTransferStaleRejectedProofForbiddenEffect -Family $family -Event $effect -FallbackSubfamily $fallbackSubfamily)) {
                continue
            }

            if (-not (Test-FileTransferStaleRejectedProofScopeMatches -Rejection $rejection -Effect $effect)) {
                continue
            }

            $missingPublicationAuthority = Test-FileTransferPublicationMissingAuthorityRejection -Event $rejection
            if ($missingPublicationAuthority) {
                if (Test-FileTransferPublicationAuthorityAcceptanceEvent -Event $effect) {
                    continue
                }

                if (Test-FileTransferPublicationEffectHasPriorAuthorizedAcceptance -Rejection $rejection -Effect $effect -Events $events) {
                    continue
                }
            }
            elseif (-not (Test-FileTransferStaleRejectedProofAuthorityMatches -Rejection $rejection -Effect $effect)) {
                continue
            }

            $forbiddenEffectCount++
            $familyCounts[$family] = [int]$familyCounts[$family] + 1
            if (Test-FileTransferStaleRejectedProofMeaningfulValue -Value $fallbackSubfamily) {
                $fallbackSubfamilyCounts[$fallbackSubfamily] = [int]$fallbackSubfamilyCounts[$fallbackSubfamily] + 1
            }
            $displayFamily = if (Test-FileTransferStaleRejectedProofMeaningfulValue -Value $fallbackSubfamily) { $fallbackSubfamily } else { $family }
            $findings.Add(("stale rejected {0} action was followed by matching effect: rejection={1}; effect={2}" -f $displayFamily, (Format-FileTransferEvidenceLine -Event $rejection), (Format-FileTransferEvidenceLine -Event $effect))) | Out-Null
            $evidence.Add($rejection) | Out-Null
            $evidence.Add($effect) | Out-Null
            $failureEvents.Add($effect) | Out-Null
        }
    }

    [object[]]$localDeliveries = @($events | Where-Object { Test-FileTransferFallbackLocalDeliveryWithoutPeerVisibleProof -Event $_ } | Sort-Object Sequence)
    foreach ($localDelivery in @($localDeliveries)) {
        [object[]]$laterAdmissionGrants = @($events | Where-Object {
                $_.Sequence -gt $localDelivery.Sequence -and
                $_.EventName -eq 'filetransfer_runtime_unlock_admission_granted' -and
                (Test-FileTransferStaleRejectedProofScopeMatches -Rejection $localDelivery -Effect $_)
            } | Sort-Object Sequence)

        foreach ($admissionGrant in @($laterAdmissionGrants)) {
            [object[]]$peerVisibleCompletions = @($events | Where-Object {
                    $_.Sequence -gt $localDelivery.Sequence -and
                    $_.Sequence -lt $admissionGrant.Sequence -and
                    (Test-FileTransferFallbackPeerVisibleCompletion -Event $_) -and
                    (Test-FileTransferStaleRejectedProofScopeMatches -Rejection $localDelivery -Effect $_)
                })
            if ($peerVisibleCompletions.Count -gt 0) {
                continue
            }

            $forbiddenEffectCount++
            $familyCounts['control_plane'] = [int]$familyCounts['control_plane'] + 1
            $fallbackSubfamilyCounts['fallback_send'] = [int]$fallbackSubfamilyCounts['fallback_send'] + 1
            $findings.Add(("local fallback control-plane acceptance was followed by runtime unlock admission without matching peer-visible completion: delivery={0}; admission={1}" -f (Format-FileTransferEvidenceLine -Event $localDelivery), (Format-FileTransferEvidenceLine -Event $admissionGrant))) | Out-Null
            $evidence.Add($localDelivery) | Out-Null
            $evidence.Add($admissionGrant) | Out-Null
            $failureEvents.Add($admissionGrant) | Out-Null
        }
    }

    $verdict = if ($rejections.Count -eq 0 -and $localDeliveries.Count -eq 0) { 'none' } elseif ($findings.Count -eq 0) { 'pass' } else { 'fail' }

    return [pscustomobject]@{
        Verdict = $verdict
        FailureClass = if ($verdict -eq 'fail') { 'stale_rejected_action_effect' } else { 'none' }
        RejectedActionCount = [int]$rejections.Count
        ForbiddenEffectCount = [int]$forbiddenEffectCount
        UnknownActionCount = [int]$unknownActionCount
        LivenessForbiddenEffectCount = [int]$familyCounts['liveness']
        RepairForbiddenEffectCount = [int]$familyCounts['repair']
        ProgressForbiddenEffectCount = [int]$familyCounts['progress']
        CheckpointForbiddenEffectCount = [int]$familyCounts['checkpoint']
        BridgeRecoveryForbiddenEffectCount = [int]$familyCounts['bridge_recovery']
        ControlPlaneForbiddenEffectCount = [int]$familyCounts['control_plane']
        RoutePublicationForbiddenEffectCount = [int]$familyCounts['route_publication']
        FallbackSendForbiddenEffectCount = [int]$fallbackSubfamilyCounts['fallback_send']
        FallbackCheckpointForbiddenEffectCount = [int]$fallbackSubfamilyCounts['fallback_checkpoint']
        FallbackReissueForbiddenEffectCount = [int]$fallbackSubfamilyCounts['fallback_reissue']
        FallbackTailYieldForbiddenEffectCount = [int]$fallbackSubfamilyCounts['fallback_tail_yield']
        FallbackPressureForbiddenEffectCount = [int]$fallbackSubfamilyCounts['fallback_pressure']
        Findings = $findings
        EvidenceEvents = @($evidence.ToArray() | Select-Object -First 20)
        FailureEvents = @($failureEvents.ToArray() | Sort-Object Sequence, LineNumber | Select-Object -First 20)
    }
}

function Test-FileTransferRuntimeUnlockFallbackUnavailableDenialScopeMatches {
    param(
        [Parameter(Mandatory = $true)]$Denial,
        [Parameter(Mandatory = $true)]$FallbackUnavailable
    )

    $denialSessionId = Get-FileTransferEventField -Event $Denial -Name 'session_id' -Default ''
    $fallbackSessionId = Get-FileTransferEventField -Event $FallbackUnavailable -Name 'session_id' -Default ''
    if (-not (Test-FileTransferStaleRejectedProofMeaningfulValue -Value $denialSessionId) -or
        -not (Test-FileTransferStaleRejectedProofMeaningfulValue -Value $fallbackSessionId) -or
        -not [string]::Equals($denialSessionId, $fallbackSessionId, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    $denialTransferId = Get-FileTransferStaleRejectedProofTransferId -Event $Denial
    $fallbackTransferId = Get-FileTransferStaleRejectedProofTransferId -Event $FallbackUnavailable
    if ((Test-FileTransferStaleRejectedProofMeaningfulValue -Value $denialTransferId) -and
        (Test-FileTransferStaleRejectedProofMeaningfulValue -Value $fallbackTransferId) -and
        -not [string]::Equals($denialTransferId, $fallbackTransferId, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    return $true
}

function Test-FileTransferRuntimeUnlockCoordinatorDenialEvent {
    param([Parameter(Mandatory = $true)]$Event)

    if ($Event.EventName -in @(
            'filetransfer_runtime_unlock_admission_denied',
            'filetransfer_runtime_unlock_callback_rejected',
            'filetransfer_runtime_unlock_precommit_probe_pending_rejected',
            'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery',
            'runtime_unlock_retry_dispatch_authority_rejected',
            'filetransfer_runtime_unlock_route_commit_rejected')) {
        return $true
    }

    if ($Event.EventName -eq 'filetransfer_runtime_owner_stale_update_rejected') {
        $text = @(
            (Get-FileTransferEventField -Event $Event -Name 'attempted_action' -Default ''),
            (Get-FileTransferEventField -Event $Event -Name 'source' -Default ''),
            (Get-FileTransferEventField -Event $Event -Name 'reason' -Default '')
        ) -join ' '
        return $text.ToLowerInvariant() -match 'runtime_unlock|precommit_probe|route_commit'
    }

    return $false
}

function Test-FileTransferRuntimeUnlockResumeSettlementMatches {
    param(
        [Parameter(Mandatory = $true)]$Blocked,
        [Parameter(Mandatory = $true)]$Settlement
    )

    if ([int64]$Settlement.Sequence -le [int64]$Blocked.Sequence) {
        return $false
    }

    if (-not (Test-FileTransferStaleRejectedProofScopeMatches -Rejection $Blocked -Effect $Settlement)) {
        return $false
    }

    foreach ($fieldName in @(
            'admission_generation',
            'transaction_generation',
            'offer_generation',
            'tuna_path_lease_generation',
            'pending_probe_generation')) {
        $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $fieldName -Default ''
        if (-not (Test-FileTransferStaleRejectedProofMeaningfulValue -Value $blockedValue)) {
            continue
        }

        $settlementValue = Get-FileTransferEventField -Event $Settlement -Name $fieldName -Default ''
        if (-not (Test-FileTransferStaleRejectedProofMeaningfulValue -Value $settlementValue)) {
            continue
        }

        if (-not [string]::Equals($blockedValue, $settlementValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRuntimeUnlockFallbackUnavailableHasCoordinatorDenial {
    param(
        [Parameter(Mandatory = $true)]$FallbackUnavailable,
        [Parameter(Mandatory = $true)][object[]]$Events
    )

    foreach ($event in @($Events | Where-Object { $_.Sequence -lt $FallbackUnavailable.Sequence } | Sort-Object Sequence -Descending)) {
        if (-not (Test-FileTransferRuntimeUnlockCoordinatorDenialEvent -Event $event)) {
            continue
        }

        if (Test-FileTransferRuntimeUnlockFallbackUnavailableDenialScopeMatches -Denial $event -FallbackUnavailable $FallbackUnavailable) {
            return $true
        }
    }

    return $false
}

function Get-FileTransferFallbackRuntimeUnlockSeparationProof {
    param(
        [Parameter(Mandatory = $true)]$Summary
    )

    [object[]]$events = @()
    if ($null -ne $Summary.PSObject.Properties['AllEvents']) {
        $events = @($Summary.AllEvents)
    }

    if ($events.Count -eq 0) {
        $events = @($Summary.GlobalEvents + $Summary.TransferEvents)
    }

    $fallbackAuthorityProof = Get-FileTransferFallbackLegAuthorityProof -TransferEvents $Summary.TransferEvents
    $waitingEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_runtime_unlock_waiting_for_fallback_survival' })
    $activationWindowGrantedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_runtime_unlock_activation_window_granted' })
    $fallbackResumedEvents = @($events | Where-Object { $_.EventName -eq 'filetransfer_runtime_unlock_probe_failed_fallback_resumed' })
    $preCommitProbeStartedEvents = @($events | Where-Object { $_.EventName -eq 'runtime_unlock_precommit_probe_started' })
    $preCommitProbeFailedEvents = @($events | Where-Object { $_.EventName -eq 'runtime_unlock_precommit_probe_failed' })
    $regularNknProbeRejectedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_precommit_probe_ignored' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'not_tuna_transport'
    })
    $fallbackUnavailableMarkEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_runtime_unlock_marked_fallback_unavailable' -or
        (
            $_.EventName -ne 'runtime_unlock_fallback_unavailable_suppressed' -and
            (
                (Get-FileTransferEventField -Event $_ -Name 'trigger' -Default '') -eq 'post_tuna_fallback_offer_send_prepare' -or
                (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'post_tuna_fallback_offer_send_prepare'
            )
        )
    })
    $fallbackUnavailableSuppressedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_fallback_unavailable_suppressed'
    })
    $fallbackUnavailableEvents = @($fallbackUnavailableMarkEvents + $fallbackUnavailableSuppressedEvents)
    $fallbackUnavailableWithoutCoordinatorDenialEvents = @($fallbackUnavailableEvents | Where-Object {
        -not (Test-FileTransferRuntimeUnlockFallbackUnavailableHasCoordinatorDenial -FallbackUnavailable $_ -Events $events)
    })

    $postTunaRouteSelected = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_route_selected' -and
        (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6'
    })

    $probeStartedWithoutActivationWindowEvents = New-Object System.Collections.Generic.List[object]
    $inFallback = $false
    $activationWindowOpen = $false
    foreach ($event in @($events | Sort-Object Sequence)) {
        if ($event.EventName -eq 'filetransfer_route_selected') {
            $route = Get-FileTransferEventField -Event $event -Name 'route' -Default ''
            if ($route -eq 'post_tuna_fallback_v6') {
                $inFallback = $true
                $activationWindowOpen = $false
            }
            elseif ($route -eq 'file_tuna_v4' -or $route -eq 'regular_nkn_v4_fast') {
                $inFallback = $false
                $activationWindowOpen = $false
            }
        }
        elseif ($event.EventName -eq 'filetransfer_runtime_unlock_activation_window_granted' -and $inFallback) {
            $activationWindowOpen = $true
        }
        elseif ($event.EventName -eq 'runtime_unlock_precommit_probe_started' -and $inFallback -and -not $activationWindowOpen) {
            $probeStartedWithoutActivationWindowEvents.Add($event) | Out-Null
        }
    }
    $probeStartedWithoutActivationWindowCount = $probeStartedWithoutActivationWindowEvents.Count

    $findings = New-Object System.Collections.Generic.List[string]
    $evidence = New-Object System.Collections.Generic.List[object]
    $failureEvents = New-Object System.Collections.Generic.List[object]
    if ($fallbackUnavailableWithoutCoordinatorDenialEvents.Count -gt 0) {
        $findings.Add(("runtime unlock fallback-unavailable outcome without coordinator denial count={0}" -f $fallbackUnavailableWithoutCoordinatorDenialEvents.Count)) | Out-Null
        foreach ($event in @($fallbackUnavailableWithoutCoordinatorDenialEvents | Select-Object -First 5)) {
            $evidence.Add($event) | Out-Null
            $failureEvents.Add($event) | Out-Null
        }
    }

    if ($probeStartedWithoutActivationWindowCount -gt 0) {
        $findings.Add(("runtime unlock precommit probe started while fallback owned recovery without activation window count={0}" -f $probeStartedWithoutActivationWindowCount)) | Out-Null
        foreach ($event in @($probeStartedWithoutActivationWindowEvents.ToArray() | Select-Object -First 5)) {
            $evidence.Add($event) | Out-Null
            $failureEvents.Add($event) | Out-Null
        }
    }

    if ($postTunaRouteSelected.Count -gt 0 -and
        ($preCommitProbeFailedEvents.Count -gt 0 -or $regularNknProbeRejectedEvents.Count -gt 0) -and
        $fallbackAuthorityProof.Verdict -eq 'fail') {
        $findings.Add('runtime unlock probe failed while fallback leg authority proof was missing or failed') | Out-Null
        foreach ($event in @($postTunaRouteSelected + $preCommitProbeFailedEvents + $regularNknProbeRejectedEvents | Select-Object -First 8)) {
            $evidence.Add($event) | Out-Null
        }
        foreach ($event in @($preCommitProbeFailedEvents + $regularNknProbeRejectedEvents | Select-Object -First 8)) {
            $failureEvents.Add($event) | Out-Null
        }
    }

    $verdict = if ($findings.Count -eq 0) { 'pass' } else { 'fail' }
    if ($postTunaRouteSelected.Count -eq 0 -and
        $waitingEvents.Count -eq 0 -and
        $activationWindowGrantedEvents.Count -eq 0 -and
        $fallbackResumedEvents.Count -eq 0 -and
        $preCommitProbeStartedEvents.Count -eq 0 -and
        $preCommitProbeFailedEvents.Count -eq 0 -and
        $fallbackUnavailableEvents.Count -eq 0) {
        $verdict = 'none'
    }

    [pscustomobject]@{
        Verdict = $verdict
        FailureClass = if ($verdict -eq 'fail' -and $fallbackUnavailableWithoutCoordinatorDenialEvents.Count -gt 0) {
            'stale_rejected_action_effect'
        }
        elseif ($verdict -eq 'fail') {
            'runtime_fallback_separation_violation'
        }
        else {
            'none'
        }
        WaitingForFallbackSurvivalCount = $waitingEvents.Count
        ActivationWindowGrantedCount = $activationWindowGrantedEvents.Count
        ProbeFailedFallbackResumedCount = $fallbackResumedEvents.Count
        ProbeStartedWithoutActivationWindowCount = $probeStartedWithoutActivationWindowCount
        RegularNknProbeRejectedCount = $regularNknProbeRejectedEvents.Count
        FallbackUnavailableMarkCount = $fallbackUnavailableMarkEvents.Count
        FallbackUnavailableSuppressedCount = $fallbackUnavailableSuppressedEvents.Count
        FallbackUnavailableWithoutCoordinatorDenialCount = $fallbackUnavailableWithoutCoordinatorDenialEvents.Count
        Findings = $findings
        EvidenceEvents = @($evidence.ToArray())
        FailureEvents = @($failureEvents.ToArray() | Sort-Object Sequence, LineNumber | Select-Object -First 20)
    }
}

function New-FileTransferRouteConsistencySummaryLines {
    param(
        [Parameter(Mandatory = $true)]$Summary,
        [ValidateSet('None', 'SwitchOff', 'MultiToggle', 'RegularActivationCycle')]
        [string]$LiveRouteProofMode = 'None',
        $RecoveryClassification = $null
    )

    $routeConsistency = $Summary.RouteConsistency
    [object[]]$routeSelectedEvents = @()
    [object[]]$routeAwareEvents = @()
    [object[]]$findings = @()
    [object[]]$evidenceEvents = @()
    if ($null -ne $routeConsistency) {
        $routeSelectedEvents = @($routeConsistency.RouteSelectedEvents)
        $routeAwareEvents = @($routeConsistency.RouteAwareEvents)
        $findings = @($routeConsistency.Findings)
        $evidenceEvents = @($routeConsistency.EvidenceEvents)
    }
    [object[]]$selectedRoutes = @(
        $routeSelectedEvents |
            ForEach-Object { Get-FileTransferEventField -Event $_ -Name 'route' -Default '' } |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) } |
            Select-Object -Unique
    )
    [object[]]$selectedRouteSequence = @(
        $routeSelectedEvents |
            Sort-Object Sequence |
            ForEach-Object { Get-FileTransferEventField -Event $_ -Name 'route' -Default '' } |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
    )
    $selectedRouteChanges = New-Object System.Collections.Generic.List[string]
    foreach ($route in @($selectedRouteSequence)) {
        if ($selectedRouteChanges.Count -eq 0 -or
            -not [string]::Equals($selectedRouteChanges[$selectedRouteChanges.Count - 1], [string]$route, [System.StringComparison]::OrdinalIgnoreCase)) {
            $selectedRouteChanges.Add([string]$route) | Out-Null
        }
    }

    $liveRouteProof = Get-FileTransferLiveRouteEpochProof -TransferEvents $Summary.TransferEvents -Mode $LiveRouteProofMode
    [object[]]$liveRouteEpochSequence = @($liveRouteProof.Sequence)
    [object[]]$liveRouteEpochRouteChanges = @($liveRouteProof.RouteChanges)
    $fallbackAuthorityProof = Get-FileTransferFallbackLegAuthorityProof -TransferEvents $Summary.TransferEvents
    $fallbackTailProof = Get-FileTransferFallbackTailReconciliationProof -Summary $Summary
    $bridgeLivenessProof = Get-FileTransferBridgeLivenessIntegrationProof -Summary $Summary
    $controlPlaneProof = Get-FileTransferControlPlaneIsolationProof -Summary $Summary
    $staleRejectedActionEffectProof = Get-FileTransferStaleRejectedActionEffectProof -Summary $Summary
    $fallbackRuntimeUnlockSeparationProof = Get-FileTransferFallbackRuntimeUnlockSeparationProof -Summary $Summary
    $publicationAuthorityFieldCoverageProof = Get-FileTransferPublicationAuthorityFieldCoverageProof -Summary $Summary
    $fileTunaV4DataPathProof = Get-FileTransferFileTunaV4DataPathProof -Summary $Summary
    $fileTransferRouteTransitionProof = $fileTunaV4DataPathProof.RouteTransitionProof
    $fileTransferRouteTransitionLiveEpochProjectionProof =
        $fileTunaV4DataPathProof.RouteTransitionLiveEpochProjectionProof
    $fileTransferRouteTransitionDrainingTransportGraceProof =
        $fileTunaV4DataPathProof.RouteTransitionTransportGraceProof
    $runtimeUnlockRegularV4RouteCommitSendDrainProof = $fileTunaV4DataPathProof.RouteCommitSendDrainProof
    if ($null -eq $RecoveryClassification) {
        $RecoveryClassification = Get-FileTransferRecoveryFailureClassification `
            -Summary $Summary `
            -LiveRouteProofMode $LiveRouteProofMode
    }
    [object[]]$fallbackAuthoritySequence = @($fallbackAuthorityProof.Sequence)

    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add(("transfer_id={0}" -f $Summary.TransferId)) | Out-Null
    $lines.Add(("first_proof_chain_failure_class={0}" -f $RecoveryClassification.FirstProofChainFailureClass)) | Out-Null
    $lines.Add(("first_proof_chain_failure_event={0}" -f $RecoveryClassification.FirstProofChainFailureEvent)) | Out-Null
    $lines.Add(("first_proof_chain_failure_reason={0}" -f $RecoveryClassification.FirstProofChainFailureReason)) | Out-Null
    $lines.Add(("first_proof_chain_failure_sequence={0}" -f $RecoveryClassification.FirstProofChainFailureSequence)) | Out-Null
    $lines.Add(("first_proof_chain_failure_source_path={0}" -f $RecoveryClassification.FirstProofChainFailureSourcePath)) | Out-Null
    $lines.Add(("first_proof_chain_failure_line_number={0}" -f $RecoveryClassification.FirstProofChainFailureLineNumber)) | Out-Null
    $lines.Add(("first_proof_chain_failure_writer_sequence={0}" -f $RecoveryClassification.FirstProofChainFailureWriterSequence)) | Out-Null
    $lines.Add(("semantic_failure_domain={0}" -f $RecoveryClassification.SemanticFailureDomain)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_soft_to_hard_handoff_missing_raw_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionSoftToHardHandoffMissingRawCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_soft_to_hard_handoff_missing_distinct_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionSoftToHardHandoffMissingDistinctCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_soft_to_hard_handoff_missing_recovered_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionSoftToHardHandoffMissingRecoveredCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_soft_to_hard_handoff_missing_unresolved_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionSoftToHardHandoffMissingUnresolvedCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_soft_to_hard_handoff_verdict={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionSoftToHardHandoffVerdict)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_startup_payload_isolation_missing_raw_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionStartupPayloadIsolationMissingRawCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_startup_payload_isolation_missing_distinct_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionStartupPayloadIsolationMissingDistinctCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_startup_payload_isolation_missing_recovered_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionStartupPayloadIsolationMissingRecoveredCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_startup_payload_isolation_missing_unresolved_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionStartupPayloadIsolationMissingUnresolvedCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_startup_payload_isolation_verdict={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionStartupPayloadIsolationVerdict)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_payload_hold_missing_raw_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionPayloadHoldMissingRawCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_payload_hold_missing_distinct_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionPayloadHoldMissingDistinctCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_payload_hold_missing_recovered_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionPayloadHoldMissingRecoveredCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_payload_hold_missing_unresolved_count={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionPayloadHoldMissingUnresolvedCount)) | Out-Null
    $lines.Add(("filetransfer_bridge_recovery_execution_payload_hold_verdict={0}" -f $RecoveryClassification.FileTransferBridgeRecoveryExecutionPayloadHoldVerdict)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_unproven_payload_hold_not_preserved_raw_count={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedUnprovenPayloadHoldNotPreservedRawCount)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_unproven_payload_hold_not_preserved_distinct_count={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedUnprovenPayloadHoldNotPreservedDistinctCount)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_unproven_payload_hold_not_preserved_recovered_count={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedUnprovenPayloadHoldNotPreservedRecoveredCount)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_unproven_payload_hold_not_preserved_unresolved_count={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedUnprovenPayloadHoldNotPreservedUnresolvedCount)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_unproven_payload_hold_verdict={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedUnprovenPayloadHoldPreservationVerdict)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_retained_proof_state_publication_missing_raw_count={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedRetainedProofStatePublicationMissingRawCount)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_retained_proof_state_publication_missing_distinct_count={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedRetainedProofStatePublicationMissingDistinctCount)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_retained_proof_state_publication_missing_recovered_count={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedRetainedProofStatePublicationMissingRecoveredCount)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_retained_proof_state_publication_missing_unresolved_count={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedRetainedProofStatePublicationMissingUnresolvedCount)) | Out-Null
    $lines.Add(("filetransfer_receive_recovery_completed_retained_proof_state_publication_verdict={0}" -f $RecoveryClassification.FileTransferReceiveRecoveryCompletedRetainedProofStatePublicationVerdict)) | Out-Null
