}

function New-FileTransferStabilityGateSummaryLines {
    param(
        [Parameter(Mandatory = $true)]$Summary,
        [Parameter(Mandatory = $true)]$GateResult,
        [ValidateSet('None', 'SwitchOff', 'MultiToggle', 'RegularActivationCycle')]
        [string]$LiveRouteProofMode = 'None'
    )

    $gapStallEvents = @(Get-FileTransferEventsForSummary -Summary $Summary -Names @('filetransfer_v4_gap_stall_summary'))
    $progressTimeoutWithReceiverGapStall = if ($Summary.LiveProgressTimeoutCount -gt 0 -and $gapStallEvents.Count -gt 0) { 1 } else { 0 }
    $warningCap = Get-FileTransferGateWarningCap -GateResult $GateResult
    $fallbackDiagnostics = Get-FileTransferGateFallbackDiagnostics -GateResult $GateResult
    $recoveryClassification = Get-FileTransferRecoveryFailureClassification `
        -Summary $Summary `
        -LiveRouteProofMode $LiveRouteProofMode
    $fallbackAuthorityProof = Get-FileTransferFallbackLegAuthorityProof -TransferEvents $Summary.TransferEvents
    $fallbackTailProof = Get-FileTransferFallbackTailReconciliationProof -Summary $Summary
    $bridgeLivenessProof = Get-FileTransferBridgeLivenessIntegrationProof -Summary $Summary
    $controlPlaneProof = Get-FileTransferControlPlaneIsolationProof -Summary $Summary

    return @(
        ("verdict={0}" -f $GateResult.Verdict),
        ("gate_status={0}" -f $GateResult.GateStatus),
        ("transfer_id={0}" -f ($(if ([string]::IsNullOrWhiteSpace($Summary.TransferId)) { '(none)' } else { $Summary.TransferId }))),
        ("recovery_failure_class={0}" -f $recoveryClassification.Class),
        ("first_proof_chain_failure_class={0}" -f $recoveryClassification.FirstProofChainFailureClass),
        ("first_proof_chain_failure_event={0}" -f $recoveryClassification.FirstProofChainFailureEvent),
        ("first_proof_chain_failure_reason={0}" -f $recoveryClassification.FirstProofChainFailureReason),
        ("first_proof_chain_failure_sequence={0}" -f $recoveryClassification.FirstProofChainFailureSequence),
        ("first_proof_chain_failure_source_path={0}" -f $recoveryClassification.FirstProofChainFailureSourcePath),
        ("first_proof_chain_failure_line_number={0}" -f $recoveryClassification.FirstProofChainFailureLineNumber),
        ("first_proof_chain_failure_writer_sequence={0}" -f $recoveryClassification.FirstProofChainFailureWriterSequence),
        ("semantic_failure_domain={0}" -f $recoveryClassification.SemanticFailureDomain),
        ("regular_v4_frontier_repair_settlement_disposition_unverifiable_raw_count={0}" -f $recoveryClassification.RegularV4FrontierRepairSettlementDispositionUnverifiableRawCount),
        ("regular_v4_frontier_repair_settlement_disposition_unverifiable_distinct_count={0}" -f $recoveryClassification.RegularV4FrontierRepairSettlementDispositionUnverifiableDistinctCount),
        ("regular_v4_frontier_repair_settlement_disposition_unverifiable_recovered_count={0}" -f $recoveryClassification.RegularV4FrontierRepairSettlementDispositionUnverifiableRecoveredCount),
        ("regular_v4_frontier_repair_settlement_disposition_unverifiable_unresolved_count={0}" -f $recoveryClassification.RegularV4FrontierRepairSettlementDispositionUnverifiableUnresolvedCount),
        ("regular_v4_frontier_repair_settlement_disposition_verdict={0}" -f $recoveryClassification.RegularV4FrontierRepairSettlementDispositionVerdict),
        ("regular_v4_frontier_repair_pressure_authority_lifecycle_split_raw_count={0}" -f $recoveryClassification.RegularV4FrontierRepairPressureAuthorityLifecycleSplitRawCount),
        ("regular_v4_frontier_repair_pressure_authority_lifecycle_split_distinct_count={0}" -f $recoveryClassification.RegularV4FrontierRepairPressureAuthorityLifecycleSplitDistinctCount),
        ("regular_v4_frontier_repair_pressure_authority_lifecycle_split_recovered_count={0}" -f $recoveryClassification.RegularV4FrontierRepairPressureAuthorityLifecycleSplitRecoveredCount),
        ("regular_v4_frontier_repair_pressure_authority_lifecycle_split_unresolved_count={0}" -f $recoveryClassification.RegularV4FrontierRepairPressureAuthorityLifecycleSplitUnresolvedCount),
