function Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate
    )

    $candidateSchema = Get-FileTransferEventField -Event $Candidate -Name 'closure_proof_schema' -Default ''
    $currentFormat = $candidateSchema -eq '1'
    if (-not [string]::IsNullOrWhiteSpace($candidateSchema) -and -not $currentFormat) {
        return $false
    }

    $strictCurrentRejection = $currentFormat -and
        $Candidate.EventName -eq 'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery'
    $currentProofEvent = $currentFormat -and $Candidate.EventName -in @(
        'runtime_unlock_retry_regular_v4_recovery_lease_closure_hold_preserved',
        'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery')

    foreach ($field in @('session_id', 'transfer_id')) {
        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names @($field, ('closure_' + $field))
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            $receiptValue -in @('(none)', 'none') -or
            [string]::IsNullOrWhiteSpace($candidateValue) -or
            $candidateValue -in @('(none)', 'none') -or
            -not [string]::Equals($receiptValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
        if ($currentProofEvent) {
            $proofValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name ('closure_' + $field) `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($proofValue) -or
                $proofValue -in @('(none)', 'none') -or
                -not [string]::Equals($receiptValue, $proofValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
    }

    $candidateDirection = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('direction', 'closure_direction')
    if ($currentFormat -and
        ([string]::IsNullOrWhiteSpace($candidateDirection) -or $candidateDirection -in @('(none)', 'none'))) {
        return $false
    }
    if (-not [string]::IsNullOrWhiteSpace($candidateDirection) -and
        $candidateDirection -notin @('(none)', 'none')) {
        $receiptDirection = Get-FileTransferEventField -Event $Receipt -Name 'direction' -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptDirection) -or
            $receiptDirection -in @('(none)', 'none') -or
            -not [string]::Equals(
                $receiptDirection,
                $candidateDirection,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
        if ($currentProofEvent) {
            $proofDirection = Get-FileTransferEventField `
                -Event $Candidate `
                -Name 'closure_direction' `
                -Default ''
            if (-not [string]::Equals(
                    $receiptDirection,
                    $proofDirection,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        if ($strictCurrentRejection) {
            $currentDirection = Get-FileTransferEventField `
                -Event $Candidate `
                -Name 'current_direction' `
                -Default ''
            if (-not [string]::Equals(
                    $receiptDirection,
                    $currentDirection,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
    }

    $fieldAliases = [ordered]@{
        route = @('route', 'closure_route', 'current_route')
        protocol_version = @('protocol_version', 'closure_protocol_version', 'current_protocol_version')
        live_route_epoch = @('live_route_epoch', 'closure_live_route_epoch', 'current_live_route_epoch')
        runtime_generation = @('runtime_generation', 'closure_runtime_generation', 'current_runtime_generation')
        terminal_generation = @('terminal_generation', 'closure_terminal_generation', 'current_terminal_generation')
        leg_generation = @('leg_generation', 'closure_leg_generation', 'current_leg_generation')
        transport_epoch = @('transport_epoch', 'closure_transport_epoch', 'current_transport_epoch')
        bridge_recovery_generation = @('bridge_recovery_generation', 'closure_bridge_recovery_generation', 'current_bridge_recovery_generation')
    }
    foreach ($field in $fieldAliases.Keys) {
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names $fieldAliases[$field]
        if ([string]::IsNullOrWhiteSpace($candidateValue) -or $candidateValue -in @('(none)', 'none')) {
            if ($currentFormat) {
                return $false
            }
            continue
        }

        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            $receiptValue -in @('(none)', 'none') -or
            -not [string]::Equals($receiptValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        if ($strictCurrentRejection) {
            $attemptedValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name $field `
                -Default ''
            $currentValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name ('current_' + $field) `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($attemptedValue) -or
                $attemptedValue -in @('(none)', 'none') -or
                -not [string]::Equals($receiptValue, $attemptedValue, [System.StringComparison]::OrdinalIgnoreCase) -or
                [string]::IsNullOrWhiteSpace($currentValue) -or
                $currentValue -in @('(none)', 'none') -or
                -not [string]::Equals($receiptValue, $currentValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        if ($currentProofEvent) {
            $proofValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name ('closure_' + $field) `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($proofValue) -or
                $proofValue -in @('(none)', 'none') -or
                -not [string]::Equals($receiptValue, $proofValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
    }

    $receiptLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Receipt `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
    $candidateLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @(
            'regular_v4_liveness_generation',
            'closure_liveness_generation',
            'current_regular_v4_liveness_generation',
            'adopted_recovery_liveness_generation',
            'recovery_liveness_lease_generation',
            'lease_generation')
    if ([string]::IsNullOrWhiteSpace($receiptLivenessGeneration) -or
        [string]::IsNullOrWhiteSpace($candidateLivenessGeneration) -or
        $receiptLivenessGeneration -ne $candidateLivenessGeneration) {
        return $false
    }

    $receiptBridgeDecisionGeneration = Get-FileTransferEventField `
        -Event $Receipt `
        -Name 'bridge_decision_generation' `
        -Default ''
    $candidateBridgeDecisionGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @(
            'bridge_decision_generation',
            'closure_bridge_decision_generation',
            'current_bridge_decision_generation',
            'adopted_bridge_decision_generation')
    if ($strictCurrentRejection) {
        $attemptedLivenessGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'regular_v4_liveness_generation' `
            -Default ''
        $currentLivenessGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'current_regular_v4_liveness_generation' `
            -Default ''
        $currentBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'current_bridge_decision_generation' `
            -Default ''
        $attemptedBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'bridge_decision_generation' `
            -Default ''
        if ($attemptedLivenessGeneration -ne $receiptLivenessGeneration -or
            $currentLivenessGeneration -ne $receiptLivenessGeneration -or
            $attemptedBridgeDecisionGeneration -ne $receiptBridgeDecisionGeneration -or
            $currentBridgeDecisionGeneration -ne $receiptBridgeDecisionGeneration) {
            return $false
        }
    }
    if ($currentProofEvent) {
        $proofLivenessGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'closure_liveness_generation' `
            -Default ''
        $proofBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $Candidate `
            -Name 'closure_bridge_decision_generation' `
            -Default ''
        if ($proofLivenessGeneration -ne $receiptLivenessGeneration -or
            $proofBridgeDecisionGeneration -ne $receiptBridgeDecisionGeneration) {
            return $false
        }
    }

    return -not [string]::IsNullOrWhiteSpace($receiptBridgeDecisionGeneration) -and
        -not [string]::IsNullOrWhiteSpace($candidateBridgeDecisionGeneration) -and
        $receiptBridgeDecisionGeneration -eq $candidateBridgeDecisionGeneration
}

function Test-FileTransferRegularV4RecoveryClosureHoldLegacyBindingUnique {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate,
        [Parameter(Mandatory = $true)][object[]]$Receipts
    )

    $receiptSchema = Get-FileTransferEventField -Event $Receipt -Name 'closure_proof_schema' -Default ''
    $candidateSchema = Get-FileTransferEventField -Event $Candidate -Name 'closure_proof_schema' -Default ''
    if ($receiptSchema -eq '1' -and $candidateSchema -eq '1') {
        return $true
    }
    if (-not [string]::IsNullOrWhiteSpace($receiptSchema) -or
        -not [string]::IsNullOrWhiteSpace($candidateSchema)) {
        return $false
    }

    $matches = @($Receipts | Where-Object {
        [int64]$_.Sequence -le [int64]$Candidate.Sequence -and
        [string]::IsNullOrWhiteSpace(
            (Get-FileTransferEventField -Event $_ -Name 'closure_proof_schema' -Default '')) -and
        (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch `
            -Receipt $_ `
            -Candidate $Candidate)
    })
    return $matches.Count -eq 1 -and [int64]$matches[0].Sequence -eq [int64]$Receipt.Sequence
}

function Test-FileTransferRegularV4RepairSettlementAdoptionMatch {
    param(
        [Parameter(Mandatory = $true)]$Settlement,
        [Parameter(Mandatory = $true)]$Adoption
    )

    foreach ($field in @(
            'session_id',
            'transfer_id',
            'direction',
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'bridge_decision_generation',
            'route_publication_generation',
            'route_commit_generation',
            'target_transport',
            'repair_request_key')) {
        $settlementValue = Get-FileTransferEventField -Event $Settlement -Name $field -Default ''
        $adoptionValue = Get-FileTransferEventField -Event $Adoption -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($settlementValue) -or
            $settlementValue -in @('(none)', 'none') -or
            [string]::IsNullOrWhiteSpace($adoptionValue) -or
            $adoptionValue -in @('(none)', 'none') -or
            -not [string]::Equals($settlementValue, $adoptionValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $settlementGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Settlement `
        -Names @('decision_generation', 'settlement_decision_generation')
    $adoptionGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Adoption `
        -Names @('settlement_decision_generation', 'decision_generation')
    if ([string]::IsNullOrWhiteSpace($settlementGeneration) -or
        [string]::IsNullOrWhiteSpace($adoptionGeneration) -or
        $settlementGeneration -ne $adoptionGeneration) {
        return $false
    }

    $settlementOutcome = (Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Settlement `
        -Names @('outcome', 'settlement_outcome')).ToLowerInvariant()
    $adoptionOutcome = (Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Adoption `
        -Names @('settlement_outcome', 'outcome')).ToLowerInvariant()
    return $settlementOutcome -in @('missing_dispatch', 'settled_stalled') -and
        $settlementOutcome -eq $adoptionOutcome
}

function Test-FileTransferRuntimeUnlockRetryCurrentBinding {
    param([Parameter(Mandatory = $true)]$Event)

    $proofSchema = Get-FileTransferEventField -Event $Event -Name 'closure_proof_schema' -Default ''
    $currentFormat = $proofSchema -eq '1'
    if (-not [string]::IsNullOrWhiteSpace($proofSchema) -and -not $currentFormat) {
        return $false
    }

    $generationFields = @(
        'contract_generation',
        'retired_generation',
        'offer_generation',
        'dispatch_attempt_generation',
        'missing_dispatch_successor_generation')
    foreach ($field in $generationFields) {
        $value = Get-FileTransferEventField -Event $Event -Name $field -Default ''
        $currentValue = Get-FileTransferEventField -Event $Event -Name ('current_' + $field) -Default ''
        if ($currentFormat -and
            ([string]::IsNullOrWhiteSpace($value) -or
             $value -in @('(none)', 'none') -or
             [string]::IsNullOrWhiteSpace($currentValue) -or
             $currentValue -in @('(none)', 'none'))) {
            return $false
        }
        if (-not [string]::IsNullOrWhiteSpace($value) -and
            -not [string]::IsNullOrWhiteSpace($currentValue) -and
            -not [string]::Equals($value, $currentValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    if ($currentFormat) {
        $predecessorAuthorityId = Get-FileTransferEventField `
            -Event $Event `
            -Name 'predecessor_authority_id' `
            -Default '__missing__'
        $currentPredecessorAuthorityId = Get-FileTransferEventField `
            -Event $Event `
            -Name 'current_predecessor_authority_id' `
            -Default '__missing__'
        if ($predecessorAuthorityId -eq '__missing__' -or
            $currentPredecessorAuthorityId -eq '__missing__' -or
            -not [string]::Equals(
                $predecessorAuthorityId,
                $currentPredecessorAuthorityId,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureHoldDeadlineCurrent {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate
    )

    $deadlineText = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Receipt `
        -Names @(
            'maximum_liveness_deferral_deadline_utc_ms',
            'maximum_local_proof_liveness_deadline_utc_ms',
            'maximum_liveness_deadline_utc_ms',
            'continuation_deadline_utc_ms',
            'local_proof_liveness_deadline_utc_ms')
    $proofSchema = Get-FileTransferEventField -Event $Receipt -Name 'closure_proof_schema' -Default ''
    if ([string]::IsNullOrWhiteSpace($proofSchema)) {
        # Legacy artifacts before closure-proof schema 1 did not retain the
        # immutable deadline. They remain classifiable only through the
        # separately enforced exact, unique settlement/adoption lineage.
        return $true
    }
    if ($proofSchema -ne '1') {
        return $false
    }

    $candidateSchema = Get-FileTransferEventField -Event $Candidate -Name 'closure_proof_schema' -Default ''
    if ($candidateSchema -ne '1') {
        return $false
    }

    [int64]$deadlineUtcMs = 0
    if ([string]::IsNullOrWhiteSpace($deadlineText) -or
        -not [int64]::TryParse($deadlineText, [ref]$deadlineUtcMs) -or
        $deadlineUtcMs -le 0 -or
        $null -eq $Candidate.TimestampUtc) {
        return $false
    }

    $candidateDeadlineText = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @(
            'maximum_liveness_deferral_deadline_utc_ms',
            'maximum_local_proof_liveness_deadline_utc_ms',
            'maximum_liveness_deadline_utc_ms',
            'continuation_deadline_utc_ms',
            'local_proof_liveness_deadline_utc_ms')
    [int64]$candidateDeadlineUtcMs = 0
    if ([string]::IsNullOrWhiteSpace($candidateDeadlineText) -or
        -not [int64]::TryParse($candidateDeadlineText, [ref]$candidateDeadlineUtcMs) -or
        $candidateDeadlineUtcMs -ne $deadlineUtcMs) {
        return $false
    }

    $candidateUtcMs = [DateTimeOffset]$Candidate.TimestampUtc
    return $candidateUtcMs.ToUnixTimeMilliseconds() -le $deadlineUtcMs
}

function Test-FileTransferRecoveryAuthorityEvidenceCompatible {
    param([AllowEmptyCollection()][object[]]$Values = @())

    $concrete = New-Object 'System.Collections.Generic.HashSet[string]' `
        ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($valueObject in @($Values)) {
        $value = [string]$valueObject
        if ([string]::IsNullOrWhiteSpace($value) -or
            $value -in @('(none)', 'none', '(missing)', '__missing__')) {
            return $false
        }
        if ($value -notin @('[redacted]', 'redacted', '(redacted)')) {
            $concrete.Add($value) | Out-Null
        }
    }

    # Redacted copied identities are absent evidence, not mismatches.  The
    # caller must corroborate an all-redacted boundary through its unique
    # complete recovery tuple and one concrete authority-bearing Phase-2 chain.
    return $concrete.Count -le 1
}

function Test-FileTransferRegularV4RecoveryClosureGrantMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Grant
    )

    foreach ($field in @(
            'session_id', 'transfer_id', 'direction', 'route', 'protocol_version',
            'live_route_epoch', 'runtime_generation', 'terminal_generation',
            'leg_generation', 'transport_epoch', 'bridge_recovery_generation')) {
        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        $grantValue = Get-FileTransferEventField -Event $Grant -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            [string]::IsNullOrWhiteSpace($grantValue) -or
            -not [string]::Equals($receiptValue, $grantValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    if ((Get-FileTransferEventField -Event $Grant -Name 'release_kind' -Default '') -ne 'ReceiveRecoveryLeaseClosure') {
        return $false
    }

    $receiptLivenessGeneration = Get-FileTransferEventField `
        -Event $Receipt `
        -Name 'regular_v4_liveness_generation' `
        -Default ''
    $grantLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Grant `
        -Names @('request_regular_v4_liveness_generation', 'regular_v4_liveness_generation')
    $receiptBridgeGeneration = Get-FileTransferEventField `
        -Event $Receipt `
        -Name 'bridge_decision_generation' `
        -Default ''
    $grantBridgeGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Grant `
        -Names @('request_bridge_decision_generation', 'bridge_decision_generation')
    if ($receiptLivenessGeneration -ne $grantLivenessGeneration -or
        $receiptBridgeGeneration -ne $grantBridgeGeneration) {
        return $false
    }

    $receiptAuthorityId = Get-FileTransferEventField -Event $Receipt -Name 'lease_authority_id' -Default ''
    $grantAuthorityId = Get-FileTransferEventField -Event $Grant -Name 'release_authority_id' -Default ''
    $receiptLeaseGeneration = Get-FileTransferEventField -Event $Receipt -Name 'lease_generation' -Default ''
    $grantReleaseGeneration = Get-FileTransferEventField -Event $Grant -Name 'release_generation' -Default ''
    return (Test-FileTransferRecoveryAuthorityEvidenceCompatible -Values @(
            $receiptAuthorityId,
            $grantAuthorityId)) -and
        -not [string]::IsNullOrWhiteSpace($receiptLeaseGeneration) -and
        $receiptLeaseGeneration -eq $grantReleaseGeneration
}

function Test-FileTransferRegularV4RecoveryTerminalMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Terminal
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch -Left $Receipt -Right $Terminal)) {
        return $false
    }

    $receiptDirection = Get-FileTransferEventField -Event $Receipt -Name 'direction' -Default ''
    $terminalDirection = Get-FileTransferEventField -Event $Terminal -Name 'direction' -Default ''
    if ([string]::IsNullOrWhiteSpace($terminalDirection)) {
        if ($Terminal.EventName -eq 'file_transfer_inbound_terminal') {
            $terminalDirection = 'inbound'
        }
        elseif ($Terminal.EventName -eq 'file_transfer_outbound_terminal') {
            $terminalDirection = 'outbound'
        }
    }

    return [string]::IsNullOrWhiteSpace($terminalDirection) -or
        [string]::Equals($receiptDirection, $terminalDirection, [System.StringComparison]::OrdinalIgnoreCase)
}

function Test-FileTransferRegularV4RecoveryLeaseClosureRejectionMatch {
    param(
        [Parameter(Mandatory = $true)]$LifecycleDecision,
        [Parameter(Mandatory = $true)]$ClosureRejection
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $LifecycleDecision `
            -Right $ClosureRejection)) {
        return $false
    }

    $lifecycleGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $LifecycleDecision `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
    $rejectionGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $ClosureRejection `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
    if (-not [string]::IsNullOrWhiteSpace($lifecycleGeneration) -and
        -not [string]::IsNullOrWhiteSpace($rejectionGeneration) -and
        $lifecycleGeneration -ne $rejectionGeneration) {
        return $false
    }

    $rejectionDirection = Get-FileTransferEventField -Event $ClosureRejection -Name 'direction' -Default ''
    if (-not [string]::IsNullOrWhiteSpace($rejectionDirection) -and
        $rejectionDirection -notin @('(none)', 'none') -and
        -not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $LifecycleDecision `
            -Right $ClosureRejection `
            -IncludeDirection)) {
        return $false
    }

    $mismatchKind = Get-FileTransferEventField -Event $ClosureRejection -Name 'mismatch_kind' -Default ''
    $decisionReason = Get-FileTransferEventField -Event $ClosureRejection -Name 'decision_reason' -Default ''
    if ($mismatchKind -in @(
            'coordinator_recovery_liveness_lease_mismatch',
            'coordinator_recovery_liveness_lease_stale') -or
        $decisionReason -in @(
            'coordinator_recovery_liveness_lease_mismatch',
            'coordinator_recovery_liveness_lease_stale')) {
        return $false
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureLivenessTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $Receipt `
            -Right $Candidate `
            -IncludeDirection)) {
        return $false
    }

    # Legacy recovery-authority telemetry prefixes the attempted/current tuple,
    # while the dedicated closure-window events emit the tuple directly. Match
    # every field the candidate carries and require the immutable receipt to
    # provide the corresponding value.
    $fieldAliases = [ordered]@{
        route = @('route', 'attempted_route', 'current_route')
        protocol_version = @('protocol_version', 'attempted_protocol_version', 'current_protocol_version')
        live_route_epoch = @('live_route_epoch', 'attempted_live_route_epoch', 'current_live_route_epoch')
        runtime_generation = @('runtime_generation', 'attempted_runtime_generation', 'current_runtime_generation')
        terminal_generation = @('terminal_generation', 'attempted_terminal_generation', 'current_terminal_generation')
        leg_generation = @('leg_generation', 'attempted_leg_generation')
        transport_epoch = @('transport_epoch', 'attempted_transport_epoch')
        bridge_recovery_generation = @('bridge_recovery_generation', 'attempted_bridge_recovery_generation')
        bridge_decision_generation = @('bridge_decision_generation', 'recovery_decision_generation')
    }
    foreach ($field in $fieldAliases.Keys) {
        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names $fieldAliases[$field]
        if ([string]::IsNullOrWhiteSpace($candidateValue) -or $candidateValue -in @('(none)', 'none')) {
            continue
        }

        # The legacy generic rejection loses the retired bridge/lease generations
        # and records them as zero. Preserve classification of those historical
        # artifacts, but require the complete tuple from the dedicated events.
        if ($Candidate.EventName -eq 'filetransfer_recovery_authority_rejected' -and
            $field -eq 'bridge_decision_generation' -and
            $candidateValue -eq '0') {
            continue
        }

        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            $receiptValue -in @('(none)', 'none') -or
            -not [string]::Equals($receiptValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $candidateLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
    if (-not [string]::IsNullOrWhiteSpace($candidateLivenessGeneration) -and
        $candidateLivenessGeneration -ne '0') {
        $receiptLivenessGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Receipt `
            -Names @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
        if ($candidateLivenessGeneration -ne $receiptLivenessGeneration) {
            return $false
        }
    }

    $exactFieldAliases = @(
        [pscustomobject]@{
            Receipt = @('lease_authority_id', 'recovery_liveness_lease_authority_id')
            Candidate = @('recovery_liveness_lease_authority_id', 'lease_authority_id')
        },
        [pscustomobject]@{
            Receipt = @('lease_state', 'recovery_liveness_lease_state')
            Candidate = @('recovery_liveness_lease_state', 'lease_state')
        },
        [pscustomobject]@{
            Receipt = @('lifecycle_outcome')
            Candidate = @('lifecycle_outcome')
        },
        [pscustomobject]@{
            Receipt = @('lifecycle_decision_status')
            Candidate = @('lifecycle_decision_status')
        },
        [pscustomobject]@{
            Receipt = @('lifecycle_decision_reason')
            Candidate = @('lifecycle_decision_reason')
        }
    )
    foreach ($aliases in $exactFieldAliases) {
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names $aliases.Candidate
        if ([string]::IsNullOrWhiteSpace($candidateValue)) {
            continue
        }

        $receiptValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Receipt `
            -Names $aliases.Receipt
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            -not [string]::Equals($receiptValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureLivenessProofMatch {
    param(
        [Parameter(Mandatory = $true)]$Rejection,
        [Parameter(Mandatory = $true)]$Grant
    )

    # Historical generic rejection telemetry predates the immutable proof and
    # cannot bind its maximum deadline. Its grant is still checked against the
    # retained receipt by the caller. Dedicated telemetry must match wholesale.
    if ($Rejection.EventName -ne
        'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_rejected') {
        return $true
    }

    $fieldAliases = @(
        [pscustomobject]@{ Left = @('session_id'); Right = @('session_id') },
        [pscustomobject]@{ Left = @('transfer_id'); Right = @('transfer_id') },
        [pscustomobject]@{ Left = @('direction'); Right = @('direction') },
        [pscustomobject]@{ Left = @('route'); Right = @('route') },
        [pscustomobject]@{ Left = @('protocol_version'); Right = @('protocol_version') },
        [pscustomobject]@{ Left = @('live_route_epoch'); Right = @('live_route_epoch') },
        [pscustomobject]@{ Left = @('runtime_generation'); Right = @('runtime_generation') },
        [pscustomobject]@{ Left = @('terminal_generation'); Right = @('terminal_generation') },
        [pscustomobject]@{ Left = @('leg_generation'); Right = @('leg_generation') },
        [pscustomobject]@{ Left = @('transport_epoch'); Right = @('transport_epoch') },
        [pscustomobject]@{ Left = @('bridge_recovery_generation'); Right = @('bridge_recovery_generation') },
        [pscustomobject]@{ Left = @('bridge_decision_generation'); Right = @('bridge_decision_generation') },
        [pscustomobject]@{
            Left = @('recovery_liveness_lease_authority_id', 'lease_authority_id')
            Right = @('recovery_liveness_lease_authority_id', 'lease_authority_id')
        },
        [pscustomobject]@{
            Left = @('recovery_liveness_lease_generation', 'lease_generation', 'regular_v4_liveness_generation')
            Right = @('recovery_liveness_lease_generation', 'lease_generation', 'regular_v4_liveness_generation')
        },
        [pscustomobject]@{
            Left = @('recovery_liveness_lease_state', 'lease_state')
            Right = @('recovery_liveness_lease_state', 'lease_state')
        },
        [pscustomobject]@{ Left = @('lifecycle_outcome'); Right = @('lifecycle_outcome') },
        [pscustomobject]@{ Left = @('lifecycle_decision_status'); Right = @('lifecycle_decision_status') },
        [pscustomobject]@{ Left = @('lifecycle_decision_reason'); Right = @('lifecycle_decision_reason') },
        [pscustomobject]@{
            Left = @('maximum_liveness_deferral_deadline_utc_ms')
            Right = @('maximum_liveness_deferral_deadline_utc_ms')
        }
    )
    foreach ($aliases in $fieldAliases) {
        $leftValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Rejection `
            -Names $aliases.Left
        $rightValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Grant `
            -Names $aliases.Right
        if ([string]::IsNullOrWhiteSpace($leftValue) -or
            [string]::IsNullOrWhiteSpace($rightValue) -or
            -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryAuthorityReplacesClosure {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Authority
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $Receipt `
            -Right $Authority `
            -IncludeDirection)) {
        return $false
    }

    $recoveryTupleAliases = @(
        [pscustomobject]@{
            Receipt = @('lease_authority_id', 'recovery_liveness_lease_authority_id')
            Authority = @('recovery_liveness_lease_authority_id', 'lease_authority_id')
        },
        [pscustomobject]@{
            Receipt = @('regular_v4_liveness_generation', 'recovery_liveness_lease_generation', 'lease_generation')
            Authority = @('recovery_liveness_lease_generation', 'lease_generation', 'regular_v4_liveness_generation')
        },
        [pscustomobject]@{
            Receipt = @('bridge_decision_generation')
            Authority = @('bridge_decision_generation')
        },
        [pscustomobject]@{
            Receipt = @('bridge_recovery_generation')
            Authority = @('bridge_recovery_generation')
        }
    )
    foreach ($aliases in $recoveryTupleAliases) {
        $receiptValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Receipt `
            -Names $aliases.Receipt
        $authorityValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Authority `
            -Names $aliases.Authority
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            [string]::IsNullOrWhiteSpace($authorityValue)) {
            continue
        }

        if (-not [string]::Equals($receiptValue, $authorityValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }

    return $false
}

function Get-FileTransferUncoveredRuntimeUnlockRegularV4RecoverySettlementMissingEvents {
    param(
        [AllowEmptyCollection()][object[]]$SettlementMissingEvents = @(),
        [AllowEmptyCollection()][object[]]$ClosureLivenessFailureEvents = @()
    )

    $uncovered = New-Object System.Collections.Generic.List[object]
    foreach ($missingCandidate in @($SettlementMissingEvents)) {
        $coveredByClosureLivenessFailure = @(
            $ClosureLivenessFailureEvents |
                Where-Object {
                    [int64]$_.Sequence -lt [int64]$missingCandidate.Sequence -and
                    (Test-FileTransferRegularV4RecoveryTerminalMatch `
                        -Receipt $_ `
                        -Terminal $missingCandidate)
                } |
                Select-Object -First 1
        ).Count -gt 0
        if (-not $coveredByClosureLivenessFailure) {
            $uncovered.Add($missingCandidate) | Out-Null
        }
    }

    return @($uncovered.ToArray())
}

function Test-FileTransferBridgeRecoveryExecutionWriterMatch {
    param(
        [Parameter(Mandatory = $true)]$Left,
        [Parameter(Mandatory = $true)]$Right,
        [switch]$RequirePresent
    )

    $leftWriter = Get-FileTransferEventField -Event $Left -Name 'log_writer_id' -Default ''
    $rightWriter = Get-FileTransferEventField -Event $Right -Name 'log_writer_id' -Default ''
    if ($RequirePresent) {
        return -not [string]::IsNullOrWhiteSpace($leftWriter) -and
            -not [string]::IsNullOrWhiteSpace($rightWriter) -and
            [string]::Equals($leftWriter, $rightWriter, [System.StringComparison]::Ordinal)
    }

    return [string]::IsNullOrWhiteSpace($leftWriter) -or
        [string]::IsNullOrWhiteSpace($rightWriter) -or
        [string]::Equals($leftWriter, $rightWriter, [System.StringComparison]::Ordinal)
}

function Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Command,
        [Parameter(Mandatory = $true)]$Candidate
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $Command `
            -Right $Candidate `
            -IncludeDirection) -or
        -not (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
            -Left $Command `
            -Right $Candidate)) {
        return $false
    }

    foreach ($field in @(
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'bridge_decision_generation')) {
        $commandValue = Get-FileTransferEventField -Event $Command -Name $field -Default ''
        $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($commandValue) -or
            [string]::IsNullOrWhiteSpace($candidateValue) -or
            -not [string]::Equals(
                $commandValue,
                $candidateValue,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $commandRoute = (
        Get-FileTransferEventField -Event $Command -Name 'route' -Default ''
    ).ToLowerInvariant() -replace '[^a-z0-9]', ''
    $candidateRoute = (
        Get-FileTransferEventField -Event $Candidate -Name 'route' -Default ''
    ).ToLowerInvariant() -replace '[^a-z0-9]', ''
    if ([string]::IsNullOrWhiteSpace($commandRoute) -or
        [string]::IsNullOrWhiteSpace($candidateRoute) -or
        $commandRoute -ne $candidateRoute) {
        return $false
    }

    $commandLeaseGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Command `
        -Names @(
            'recovery_liveness_lease_generation',
            'lease_generation',
            'regular_v4_liveness_generation')
    $candidateLeaseGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @(
            'recovery_liveness_lease_generation',
            'lease_generation',
            'regular_v4_liveness_generation')
    if ([string]::IsNullOrWhiteSpace($commandLeaseGeneration) -or
        [string]::IsNullOrWhiteSpace($candidateLeaseGeneration) -or
        $commandLeaseGeneration -ne $candidateLeaseGeneration) {
        return $false
    }

    $commandLeaseAuthority = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Command `
        -Names @('recovery_liveness_lease_authority_id', 'lease_authority_id')
    $candidateLeaseAuthority = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('recovery_liveness_lease_authority_id', 'lease_authority_id')
    return [string]::IsNullOrWhiteSpace($candidateLeaseAuthority) -or
        (Test-FileTransferRecoveryAuthorityEvidenceCompatible -Values @(
            $commandLeaseAuthority,
            $candidateLeaseAuthority))
}

function Test-FileTransferBridgeRecoveryExecutionStartMatch {
    param(
        [Parameter(Mandatory = $true)]$Command,
        [Parameter(Mandatory = $true)]$Start
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $Command `
            -Right $Start `
            -IncludeDirection) -or
        -not (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
            -Left $Command `
            -Right $Start)) {
        return $false
    }

    foreach ($field in @('bridge_recovery_generation', 'bridge_decision_generation')) {
        $commandValue = Get-FileTransferEventField -Event $Command -Name $field -Default ''
        $startValue = Get-FileTransferEventField -Event $Start -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($commandValue) -or
            [string]::IsNullOrWhiteSpace($startValue) -or
            $commandValue -ne $startValue) {
            return $false
        }
    }

    return (Get-FileTransferEventField -Event $Start -Name 'status' -Default '').ToLowerInvariant() -in
        @('started', 'idempotent')
}

function Get-FileTransferBridgeRecoveryExecutionSoftToHardHandoffCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$commands = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_execution_command_issued'
    })
    [object[]]$starts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_execution_start_decided'
    })
    [object[]]$completions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_recovery_execution_completed' -and
        (Get-FileTransferEventField -Event $_ -Name 'outcome' -Default '').ToLowerInvariant() -eq 'exhausted' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
            'bridge_recovery_execution_timeout' -and
        -not (
            (Get-FileTransferEventField -Event $_ -Name 'physical_execution_terminated' -Default '0') -eq '1' -and
            (Get-FileTransferEventField -Event $_ -Name 'total_deadline_expired' -Default '0') -eq '1'
        )
    })
    [object[]]$receiptDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_execution_receipt_decision_observed' -and
        (Get-FileTransferEventField -Event $_ -Name 'execution_outcome' -Default '').ToLowerInvariant() -eq 'exhausted' -and
        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'disposition' -Default '').ToLowerInvariant() -eq 'accepted' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -in @(
            'bridge_recovery_execution_receipt_accepted',
            'filetransfer_receive_recovery_execution_receipt_applied')
    })
    [object[]]$softToHardEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_receive_stall_recovery_soft_failed_hard_restart'
    })
    [object[]]$hardRestartEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_receive_stall_recovery_hard_restart'
    })
    [object[]]$staleRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_restart_rejected_stale_execution_command' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
            'bridge_recovery_execution_command_not_current'
    })
    [object[]]$terminalEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'transfer_terminal',
            'file_transfer_inbound_terminal',
            'file_transfer_outbound_terminal',
            'filetransfer_runtime_terminalized')
    })

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($completion in $completions) {
        $command = @($commands | Where-Object {
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $_ `
                -Candidate $completion)
        } | Select-Object -Last 1)
        if ($command.Count -eq 0) {
            continue
        }

        $nextCommand = @($commands | Where-Object {
            [int64]$_.Sequence -gt [int64]$command[0].Sequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $command[0] `
                -Right $_ `
                -IncludeDirection) -and
            -not (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_)
        } | Select-Object -First 1)
        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$command[0].Sequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch `
                -Receipt $command[0] `
                -Terminal $_)
        } | Select-Object -First 1)
        $boundarySequence = [int64]::MaxValue
        foreach ($boundary in @($nextCommand + $terminal)) {
            if ($null -ne $boundary -and [int64]$boundary.Sequence -lt $boundarySequence) {
                $boundarySequence = [int64]$boundary.Sequence
            }
        }

        $start = @($starts | Where-Object {
            [int64]$_.Sequence -gt [int64]$command[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionStartMatch `
                -Command $command[0] `
                -Start $_)
        } | Select-Object -First 1)
        $receipt = @($receiptDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$completion.Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_)
        } | Select-Object -First 1)
        if ($start.Count -eq 0 -or $receipt.Count -eq 0) {
            continue
        }

        $stale = @($staleRejections | Where-Object {
            [int64]$_.Sequence -gt [int64]$receipt[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
                -Left $command[0] `
                -Right $_ `
                -RequirePresent) -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_)
        } | Select-Object -First 1)
        if ($stale.Count -eq 0) {
            continue
        }

        # The legacy soft/hard phase events do not carry command fields. Bind
        # them only inside the exact command-to-stale interval and to the same
        # process writer; ambiguous intervals are not proof.
        $softCandidates = @($softToHardEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$receipt[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$stale[0].Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
                -Left $command[0] `
                -Right $_ `
                -RequirePresent)
        })
        $hardCandidates = @($hardRestartEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$receipt[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$stale[0].Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
                -Left $command[0] `
                -Right $_ `
                -RequirePresent)
        })
        if ($softCandidates.Count -ne 1 -or $hardCandidates.Count -ne 1 -or
            [int64]$softCandidates[0].Sequence -gt [int64]$hardCandidates[0].Sequence) {
            continue
        }

        $rawCandidates.Add($completion) | Out-Null
        $tupleKey = [string]::Join('|', @(
                (Get-FileTransferEventField -Event $command[0] -Name 'session_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'transfer_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'direction' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'route' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'protocol_version' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'live_route_epoch' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'runtime_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'terminal_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'leg_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'transport_epoch' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'bridge_recovery_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'bridge_decision_generation' -Default '(missing)'),
                (Get-FileTransferRegularV4RecoveryLeaseField `
                    -Event $command[0] `
                    -Names @('recovery_liveness_lease_generation', 'lease_generation'))))
        if ($seen.ContainsKey($tupleKey)) {
            continue
        }

        $seen[$tupleKey] = $true
        $distinctCandidates.Add($completion) | Out-Null
        $unresolvedCandidates.Add($completion) | Out-Null
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = 0
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) {
            'fail'
        }
        elseif ($distinctCandidates.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @()
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferBridgeRecoveryStartupRawEvidence {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    $rawEvidence = New-Object System.Collections.Generic.List[object]
    foreach ($fileGroup in @($Events | Where-Object {
            $null -ne $_ -and
            -not [string]::IsNullOrWhiteSpace([string]$_.FilePath) -and
            (Test-Path -LiteralPath ([string]$_.FilePath) -PathType Leaf)
        } | Group-Object FilePath)) {
        $fileEvents = @($fileGroup.Group | Sort-Object Sequence, LineNumber)
        if ($fileEvents.Count -eq 0) {
            continue
        }

        $sequenceOffset = [int64]$fileEvents[0].Sequence - [int64]$fileEvents[0].LineNumber
        $lineNumber = 0
        foreach ($line in [System.IO.File]::ReadLines([string]$fileGroup.Name)) {
            $lineNumber++
            $kind = ''
            $processId = ''
            if ($line -match 'Bridge process started \(pid=(?<pid>[0-9]+)') {
                $kind = 'process_started'
                $processId = [string]$Matches['pid']
            }
            elseif ($line -match '\[nkn-bridge\]\s+Bridge started(?:;|$)') {
                $kind = 'node_started'
            }
            elseif ($line -match 'Bulk queue transient not-ready.*reason=Not connected') {
                $kind = 'bulk_not_connected'
            }
            elseif ($line -match 'Control queue send failed:\s*Not connected') {
                $kind = 'control_not_connected'
            }
            elseif ($line -match 'Bridge hello_ok \+ pong') {
                $kind = 'hello_pong'
            }
            elseif ($line -match 'Connected bridge \(') {
                $kind = 'connected'
            }
            else {
                continue
            }

            $writerId = ''
            $writerSequence = ''
            if ($line -match '(?:^|;\s*)log_writer_id=(?<writer>[^;\s]+)') {
                $writerId = [string]$Matches['writer']
            }
            if ($line -match '(?:^|;\s*)log_writer_sequence=(?<sequence>[0-9]+)') {
                $writerSequence = [string]$Matches['sequence']
            }

            $fields = @{
                evidence_kind = $kind
                log_writer_id = $writerId
                log_writer_sequence = $writerSequence
            }
            if (-not [string]::IsNullOrWhiteSpace($processId)) {
                $fields['pid'] = $processId
            }
            $rawEvidence.Add([pscustomobject]@{
                    EventName = 'filetransfer_bridge_recovery_startup_raw_evidence'
                    Fields = $fields
                    FilePath = [string]$fileGroup.Name
                    FileName = [System.IO.Path]::GetFileName([string]$fileGroup.Name)
                    LineNumber = $lineNumber
                    Sequence = $sequenceOffset + $lineNumber
                    RawLine = [string]$line
                    Message = [string]$line
                }) | Out-Null
        }
    }

    return @($rawEvidence.ToArray() | Sort-Object Sequence, LineNumber)
}

function Get-FileTransferBridgeRecoveryExecutionStartupPayloadIsolationCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$rawEvidence = @(Get-FileTransferBridgeRecoveryStartupRawEvidence -Events $orderedEvents)
    [object[]]$commands = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_execution_command_issued'
    })
    [object[]]$starts = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'nkn_bridge_recovery_execution_started',
            'filetransfer_bridge_recovery_execution_start_decided')
    })
    [object[]]$hardDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_recovery_execution_hard_restart_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '').ToLowerInvariant() -eq 'started'
    })
    [object[]]$spawns = @($orderedEvents | Where-Object {
        $_.EventName -eq 'bridge_spawned'
    })
    [object[]]$readyEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'bridge_ready'
    })
    [object[]]$completions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_recovery_execution_completed' -and
        (Get-FileTransferEventField -Event $_ -Name 'outcome' -Default '').ToLowerInvariant() -eq 'exhausted' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
            'bridge_recovery_execution_timeout' -and
        (Get-FileTransferEventField -Event $_ -Name 'physical_execution_terminated' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'total_deadline_expired' -Default '0') -eq '1'
    })
    [object[]]$receiptDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_execution_receipt_decision_observed' -and
        (Get-FileTransferEventField -Event $_ -Name 'execution_outcome' -Default '').ToLowerInvariant() -eq 'exhausted' -and
        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'disposition' -Default '').ToLowerInvariant() -eq 'accepted' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -in @(
            'bridge_recovery_execution_receipt_accepted',
            'filetransfer_receive_recovery_execution_receipt_applied')
    })
    [object[]]$terminalEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'transfer_terminal',
            'file_transfer_inbound_terminal',
            'file_transfer_outbound_terminal',
            'filetransfer_runtime_terminalized')
    })

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($completion in $completions) {
        $command = @($commands | Where-Object {
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $_ -Candidate $completion)
        } | Select-Object -Last 1)
        if ($command.Count -eq 0) {
            continue
        }

        $nextCommand = @($commands | Where-Object {
            [int64]$_.Sequence -gt [int64]$command[0].Sequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $command[0] `
                -Right $_ `
                -IncludeDirection) -and
            -not (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_)
        } | Select-Object -First 1)
        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$command[0].Sequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch `
                -Receipt $command[0] `
                -Terminal $_)
        } | Select-Object -First 1)
        $boundarySequence = [int64]::MaxValue
        foreach ($boundary in @($nextCommand + $terminal)) {
            if ($null -ne $boundary -and [int64]$boundary.Sequence -lt $boundarySequence) {
                $boundarySequence = [int64]$boundary.Sequence
            }
        }

        $start = @($starts | Where-Object {
            [int64]$_.Sequence -gt [int64]$command[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_) -and
            (
                $_.EventName -eq 'nkn_bridge_recovery_execution_started' -or
                (Get-FileTransferEventField -Event $_ -Name 'status' -Default '').ToLowerInvariant() -in
                    @('started', 'idempotent') -or
                (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '').ToLowerInvariant() -in
                    @('started', 'idempotent')
            )
        } | Select-Object -First 1)
        if ($start.Count -eq 0) {
            continue
        }
        $hardDecision = @($hardDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$start[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_)
        } | Select-Object -First 1)
        if ($hardDecision.Count -eq 0) {
            continue
        }

        $writerId = Get-FileTransferEventField -Event $command[0] -Name 'log_writer_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($writerId)) {
            continue
        }
        $spawnCandidates = @($spawns | Where-Object {
            [int64]$_.Sequence -gt [int64]$hardDecision[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId
        })
        if ($spawnCandidates.Count -ne 1) {
            # Raw payload lines have no transfer tuple. They are admissible
            # only inside one unique same-writer process interval.
            continue
        }
        $spawn = $spawnCandidates[0]
        $spawnPid = Get-FileTransferEventField -Event $spawn -Name 'pid' -Default ''
        $processStarted = @($rawEvidence | Where-Object {
            [int64]$_.Sequence -gt [int64]$spawn.Sequence -and
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'evidence_kind' -Default '') -eq 'process_started' -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId -and
            (Get-FileTransferEventField -Event $_ -Name 'pid' -Default '') -eq $spawnPid
        } | Select-Object -First 1)
        $nodeStarted = @($rawEvidence | Where-Object {
            [int64]$_.Sequence -gt [int64]$processStarted[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'evidence_kind' -Default '') -eq 'node_started' -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId
        } | Select-Object -First 1)
        if ($processStarted.Count -eq 0 -or $nodeStarted.Count -eq 0) {
            continue
        }

        $payloadEvidence = @($rawEvidence | Where-Object {
            [int64]$_.Sequence -gt [int64]$nodeStarted[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'evidence_kind' -Default '') -in
                @('bulk_not_connected', 'control_not_connected') -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId
        })
        if ($payloadEvidence.Count -eq 0) {
            # A genuine total deadline without pre-ready payload submission is
            # not this startup-isolation failure.
            continue
        }

        $structuredReady = @($readyEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$spawn.Sequence -and
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId -and
            (
                [string]::IsNullOrWhiteSpace($spawnPid) -or
                (Get-FileTransferEventField -Event $_ -Name 'pid' -Default '') -eq $spawnPid
            )
        })
        $rawReady = @($rawEvidence | Where-Object {
            [int64]$_.Sequence -gt [int64]$spawn.Sequence -and
            [int64]$_.Sequence -lt [int64]$completion.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'evidence_kind' -Default '') -in
                @('hello_pong', 'connected') -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId
        })
        if ($structuredReady.Count -gt 0 -or $rawReady.Count -gt 0) {
            continue
        }

        $receipt = @($receiptDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$completion.Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_)
        } | Select-Object -First 1)
        if ($receipt.Count -eq 0) {
            continue
        }

        $rawCandidates.Add($completion) | Out-Null
        $tupleKey = [string]::Join('|', @(
                (Get-FileTransferEventField -Event $command[0] -Name 'session_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'transfer_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'direction' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'route' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'runtime_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'terminal_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'leg_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'transport_epoch' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'bridge_recovery_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command[0] -Name 'bridge_decision_generation' -Default '(missing)'),
                (Get-FileTransferRegularV4RecoveryLeaseField `
                    -Event $command[0] `
                    -Names @('recovery_liveness_lease_generation', 'lease_generation'))))
        if ($seen.ContainsKey($tupleKey)) {
            continue
        }
        $seen[$tupleKey] = $true
        $distinctCandidates.Add($completion) | Out-Null
        $unresolvedCandidates.Add($completion) | Out-Null
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = 0
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) { 'fail' } elseif ($distinctCandidates.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @()
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferBridgeRecoveryExecutionPayloadHoldCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$commands = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_execution_command_issued'
    })
    [object[]]$starts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_recovery_execution_started'
    })
    [object[]]$barrierClosedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_recovery_submission_barrier_closed' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'submission_epoch' -Default 0) -gt 0
    })
    [object[]]$hardDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_recovery_execution_hard_restart_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '').ToLowerInvariant() -eq
            'started' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'remaining_total_ms' -Default 0) -gt 0
    })
    [object[]]$bindingEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_binding_committed' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -gt 0
    })
    [object[]]$grantEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_authority_granted' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -gt 0
    })
    [object[]]$retirementEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_binding_retired'
    })
    [object[]]$leaseEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_physical_send_lease_registered' -and
        (Get-FileTransferEventField -Event $_ -Name 'send_kind' -Default '') -eq
            'RegularV4Repair' -and
        (Get-FileTransferEventField -Event $_ -Name 'repair_send' -Default '0') -eq '1'
    })
    [object[]]$submissionRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_submission_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'stage' -Default '') -eq 'pre_wait' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
            'bridge_submission_epoch_not_ready' -and
        (Get-FileTransferEventField -Event $_ -Name 'recovery_barrier_active' -Default '0') -eq '1'
    })
    [object[]]$deliveryFailures = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_v4_repair_delivery_both_failed'
    })
    [object[]]$senderFailures = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_v4_sender_failed'
    })
    [object[]]$executionBoundaries = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'nkn_bridge_recovery_submission_barrier_released',
            'nkn_bridge_recovery_submission_barrier_invalidated',
            'nkn_bridge_recovery_execution_completed',
            'nkn_bridge_recovery_execution_completion_late')
    })
    [object[]]$terminalEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'transfer_terminal',
            'file_transfer_inbound_terminal',
            'file_transfer_outbound_terminal',
            'filetransfer_runtime_terminalized')
    })

    function Get-BridgeRecoveryPayloadHoldNormalizedRoute {
        param([string]$Value)
        return $Value.ToLowerInvariant() -replace '[^a-z0-9]', ''
    }

    function Test-BridgeRecoveryPayloadHoldIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Source,
            [Parameter(Mandatory = $true)]$Candidate,
            [switch]$RequireDirection,
            [switch]$RequireWriter
        )

        foreach ($field in @('session_id', 'transfer_id')) {
            $sourceValue = Get-FileTransferEventField -Event $Source -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($sourceValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals(
                    $sourceValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        if ($RequireDirection) {
            $sourceDirection = Get-FileTransferEventField -Event $Source -Name 'direction' -Default ''
            $candidateDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
            if ([string]::IsNullOrWhiteSpace($sourceDirection) -or
                [string]::IsNullOrWhiteSpace($candidateDirection) -or
                -not [string]::Equals(
                    $sourceDirection,
                    $candidateDirection,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        if ($RequireWriter -and
            -not (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
                -Left $Source `
                -Right $Candidate `
                -RequirePresent)) {
            return $false
        }

        return $true
    }

    function Test-BridgeRecoveryPayloadHoldRuntimeScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Command,
            [Parameter(Mandatory = $true)]$Candidate,
            [switch]$SourcePrefixed
        )

        if (-not (Test-BridgeRecoveryPayloadHoldIdentityMatch `
                -Source $Command `
                -Candidate $Candidate `
                -RequireDirection)) {
            return $false
        }

        $routeField = if ($SourcePrefixed) { 'source_route' } else { 'route' }
        $commandRoute = Get-BridgeRecoveryPayloadHoldNormalizedRoute (
            Get-FileTransferEventField -Event $Command -Name 'route' -Default '')
        $candidateRoute = Get-BridgeRecoveryPayloadHoldNormalizedRoute (
            Get-FileTransferEventField -Event $Candidate -Name $routeField -Default '')
        if ([string]::IsNullOrWhiteSpace($commandRoute) -or $commandRoute -ne $candidateRoute) {
            return $false
        }

        foreach ($field in @(
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation')) {
            $candidateField = if ($SourcePrefixed) { "source_$field" } else { $field }
            $commandValue = Get-FileTransferEventField -Event $Command -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $candidateField -Default ''
            if ([string]::IsNullOrWhiteSpace($commandValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                $commandValue -ne $candidateValue) {
                return $false
            }
        }

        if (-not $SourcePrefixed) {
            $commandBridgeDecision = Get-FileTransferEventField `
                -Event $Command `
                -Name 'bridge_decision_generation' `
                -Default ''
            $candidateBridgeDecision = Get-FileTransferEventField `
                -Event $Candidate `
                -Name 'bridge_decision_generation' `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($commandBridgeDecision) -or
                [string]::IsNullOrWhiteSpace($candidateBridgeDecision) -or
                $commandBridgeDecision -ne $candidateBridgeDecision) {
                return $false
            }
        }

        return $true
    }

    function Test-BridgeRecoveryPayloadHoldBindingGrantMatch {
        param(
            [Parameter(Mandatory = $true)]$Binding,
            [Parameter(Mandatory = $true)]$Grant
        )

        if (-not (Test-BridgeRecoveryPayloadHoldIdentityMatch `
                -Source $Binding `
                -Candidate $Grant `
                -RequireDirection) -or
            (Get-FileTransferEventField -Event $Binding -Name 'authority_id' -Default '') -ne
                (Get-FileTransferEventField -Event $Grant -Name 'authority_id' -Default '') -or
            (Get-FileTransferEventField -Event $Binding -Name 'install_generation' -Default '') -ne
                (Get-FileTransferEventField -Event $Grant -Name 'install_generation' -Default '') -or
            (Get-FileTransferEventField -Event $Binding -Name 'repair_request_key' -Default '') -ne
                (Get-FileTransferEventField -Event $Grant -Name 'repair_request_key' -Default '')) {
            return $false
        }

        foreach ($field in @(
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'bridge_decision_generation',
                'route_publication_generation')) {
            if ((Get-FileTransferEventField -Event $Binding -Name $field -Default '') -ne
                (Get-FileTransferEventField -Event $Grant -Name $field -Default '')) {
                return $false
            }
        }

        return $true
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($senderFailure in $senderFailures) {
        $commandCandidates = @($commands | Where-Object {
            [int64]$_.Sequence -lt [int64]$senderFailure.Sequence -and
            (Test-BridgeRecoveryPayloadHoldIdentityMatch `
                -Source $_ `
                -Candidate $senderFailure `
                -RequireWriter)
        } | Sort-Object Sequence, LineNumber)
        foreach ($command in @($commandCandidates | Select-Object -Last 1)) {
            $start = @($starts | Where-Object {
                [int64]$_.Sequence -gt [int64]$command.Sequence -and
                [int64]$_.Sequence -lt [int64]$senderFailure.Sequence -and
                (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                    -Command $command `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($start.Count -eq 0) {
                continue
            }

            $barrier = @($barrierClosedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$start[0].Sequence -and
                [int64]$_.Sequence -lt [int64]$senderFailure.Sequence -and
                (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                    -Command $command `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($barrier.Count -eq 0) {
                continue
            }
            $submissionEpoch = Get-FileTransferEventField `
                -Event $barrier[0] `
                -Name 'submission_epoch' `
                -Default ''

            $hardDecision = @($hardDecisions | Where-Object {
                [int64]$_.Sequence -gt [int64]$barrier[0].Sequence -and
                [int64]$_.Sequence -lt [int64]$senderFailure.Sequence -and
                (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                    -Command $command `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($hardDecision.Count -eq 0) {
                continue
            }

            $boundarySequence = [int64]::MaxValue
            foreach ($boundary in @(
                    $executionBoundaries |
                        Where-Object {
                            [int64]$_.Sequence -gt [int64]$barrier[0].Sequence -and
                            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                                -Command $command `
                                -Candidate $_)
                        } |
                        Select-Object -First 1)) {
                if ($null -ne $boundary) {
                    $boundarySequence = [Math]::Min($boundarySequence, [int64]$boundary.Sequence)
                }
            }
            foreach ($nextCommand in @(
                    $commands |
                        Where-Object {
                            [int64]$_.Sequence -gt [int64]$command.Sequence -and
                            (Test-BridgeRecoveryPayloadHoldIdentityMatch `
                                -Source $command `
                                -Candidate $_ `
                                -RequireDirection) -and
                            -not (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                                -Command $command `
                                -Candidate $_)
                        } |
                        Select-Object -First 1)) {
                if ($null -ne $nextCommand) {
                    $boundarySequence = [Math]::Min(
                        $boundarySequence,
                        [int64]$nextCommand.Sequence)
                }
            }
            foreach ($terminal in @(
                    $terminalEvents |
                        Where-Object {
                            [int64]$_.Sequence -gt [int64]$command.Sequence -and
                            (Test-BridgeRecoveryPayloadHoldIdentityMatch `
                                -Source $command `
                                -Candidate $_)
                        } |
                        Select-Object -First 1)) {
                if ($null -ne $terminal) {
                    $boundarySequence = [Math]::Min($boundarySequence, [int64]$terminal.Sequence)
                }
            }
            if ([int64]$senderFailure.Sequence -ge $boundarySequence) {
                continue
            }

            $qualifyingBindings = New-Object System.Collections.Generic.List[object]
            foreach ($binding in @($bindingEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$barrier[0].Sequence -and
                    [int64]$_.Sequence -lt [int64]$senderFailure.Sequence -and
                    (Test-BridgeRecoveryPayloadHoldRuntimeScopeMatch `
                        -Command $command `
                        -Candidate $_)
                })) {
                $authorityId = Get-FileTransferEventField `
                    -Event $binding `
                    -Name 'authority_id' `
                    -Default ''
                $installGeneration = Get-FileTransferEventField `
                    -Event $binding `
                    -Name 'install_generation' `
                    -Default ''
                $repairKey = Get-FileTransferEventField `
                    -Event $binding `
                    -Name 'repair_request_key' `
                    -Default ''
                if ([string]::IsNullOrWhiteSpace($authorityId) -or
                    [string]::IsNullOrWhiteSpace($installGeneration) -or
                    [string]::IsNullOrWhiteSpace($repairKey)) {
                    continue
                }

                $grant = @($grantEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$binding.Sequence -and
                    [int64]$_.Sequence -lt [int64]$senderFailure.Sequence -and
                    (Test-BridgeRecoveryPayloadHoldBindingGrantMatch `
                        -Binding $binding `
                        -Grant $_)
                } | Select-Object -First 1)
                if ($grant.Count -eq 0) {
                    continue
                }

                $retiredBeforeFailure = @($retirementEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$binding.Sequence -and
                    [int64]$_.Sequence -lt [int64]$senderFailure.Sequence -and
                    (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq
                        $authorityId -and
                    (Get-FileTransferEventField -Event $_ -Name 'install_generation' -Default '') -eq
                        $installGeneration
                }).Count -gt 0
                if ($retiredBeforeFailure) {
                    continue
                }

                $linkedFailure = $false
                foreach ($lease in @($leaseEvents | Where-Object {
                        [int64]$_.Sequence -gt [int64]$hardDecision[0].Sequence -and
                        [int64]$_.Sequence -lt [int64]$senderFailure.Sequence -and
                        (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq
                            $repairKey -and
                        (Test-BridgeRecoveryPayloadHoldRuntimeScopeMatch `
                            -Command $command `
                            -Candidate $_ `
                            -SourcePrefixed) -and
                        (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
                            -Left $command `
                            -Right $_ `
                            -RequirePresent)
                    })) {
                    $deliveryFailure = @($deliveryFailures | Where-Object {
                        [int64]$_.Sequence -gt [int64]$lease.Sequence -and
                        [int64]$_.Sequence -lt [int64]$senderFailure.Sequence -and
                        (Test-BridgeRecoveryPayloadHoldIdentityMatch `
                            -Source $command `
                            -Candidate $_ `
                            -RequireWriter)
                    } | Select-Object -First 1)
                    if ($deliveryFailure.Count -eq 0) {
                        continue
                    }

                    [object[]]$rejects = @($submissionRejections | Where-Object {
                        [int64]$_.Sequence -gt [int64]$lease.Sequence -and
                        [int64]$_.Sequence -lt [int64]$deliveryFailure[0].Sequence -and
                        (Get-FileTransferEventField -Event $_ -Name 'submission_epoch' -Default '') -eq
                            $submissionEpoch -and
                        (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
                            -Left $command `
                            -Right $_ `
                            -RequirePresent)
                    })
                    $channels = @($rejects | ForEach-Object {
                        (Get-FileTransferEventField -Event $_ -Name 'channel' -Default '').ToLowerInvariant()
                    } | Select-Object -Unique)
                    if ($channels -contains 'control' -and $channels -contains 'bulk') {
                        $linkedFailure = $true
                        break
                    }
                }

                if ($linkedFailure) {
                    $qualifyingBindings.Add($binding) | Out-Null
                }
            }

            $bindingKeys = @($qualifyingBindings | ForEach-Object {
                [string]::Join('|', @(
                    (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default ''),
                    (Get-FileTransferEventField -Event $_ -Name 'install_generation' -Default ''),
                    (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '')))
            } | Select-Object -Unique)
            if ($bindingKeys.Count -ne 1) {
                continue
            }

            $binding = @($qualifyingBindings | Sort-Object Sequence, LineNumber | Select-Object -First 1)[0]
            $rawCandidates.Add($senderFailure) | Out-Null
            $tupleKey = [string]::Join('|', @(
                (Get-FileTransferEventField -Event $command -Name 'session_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'transfer_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'direction' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'route' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'runtime_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'terminal_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'leg_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'transport_epoch' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'bridge_recovery_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'bridge_decision_generation' -Default '(missing)'),
                (Get-FileTransferRegularV4RecoveryLeaseField `
                    -Event $command `
                    -Names @('recovery_liveness_lease_generation', 'lease_generation')),
                $submissionEpoch,
                (Get-FileTransferEventField -Event $binding -Name 'authority_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $binding -Name 'install_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $binding -Name 'repair_request_key' -Default '(missing)')))
            if (-not $seen.ContainsKey($tupleKey)) {
                $seen[$tupleKey] = $true
                $distinctCandidates.Add($senderFailure) | Out-Null
                $unresolvedCandidates.Add($senderFailure) | Out-Null
            }
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = 0
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) {
            'fail'
        }
        elseif ($distinctCandidates.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @()
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainSourceScopeKey {
    param(
        [Parameter(Mandatory = $true)]$Event,
        [switch]$SourcePrefixed
    )

    $fields = $Event.Fields
    if ($null -eq $fields) {
        return ''
    }
    $prefix = if ($SourcePrefixed) { 'source_' } else { '' }
    [string[]]$fieldNames = @(
        'session_id',
        'transfer_id',
        'direction',
        'log_writer_id',
        "${prefix}route",
        "${prefix}protocol_version",
        "${prefix}live_route_epoch",
        "${prefix}runtime_generation",
        "${prefix}terminal_generation",
        "${prefix}leg_generation",
        "${prefix}transport_epoch",
        "${prefix}bridge_recovery_generation")
    [string[]]$values = [string[]]::new($fieldNames.Count)
    for ($fieldIndex = 0; $fieldIndex -lt $fieldNames.Count; $fieldIndex++) {
        $fieldName = $fieldNames[$fieldIndex]
        if (-not $fields.ContainsKey($fieldName)) {
            return ''
        }
        $value = [string]$fields[$fieldName]
        if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none')) {
            return ''
        }
        $values[$fieldIndex] = if ($fieldName -eq "${prefix}route") {
            $value.ToLowerInvariant() -replace '[^a-z0-9]', ''
        }
        else {
            $value.ToLowerInvariant()
        }
    }
    return [string]::Join('|', $values)
}

function New-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndex {
    param(
        [AllowEmptyCollection()][object[]]$SemanticEvents = @(),
        [AllowEmptyCollection()][object[]]$RetirementEvents = @()
    )

    $eventsByName = @{}
    $retirementsBySourceScope = @{}
    $retirementLastSequenceBySourceScope = @{}
    $unorderedRetirementSourceScopes = @{}
    $buildVisitCount = 0L
    $semanticVisitCount = 0L
    $retirementVisitCount = 0L

    foreach ($event in @($SemanticEvents)) {
        $buildVisitCount++
        $semanticVisitCount++
        if ($null -eq $event -or [string]::IsNullOrWhiteSpace([string]$event.EventName)) {
            continue
        }
        if ($event.EventName -in @(
                'filetransfer_outbound_physical_send_lease_retired',
                'filetransfer_route_transition_physical_send_lease_retired')) {
            continue
        }
        if (-not $eventsByName.ContainsKey($event.EventName)) {
            $eventsByName[$event.EventName] =
                New-Object System.Collections.Generic.List[object]
        }
        $eventsByName[$event.EventName].Add($event) | Out-Null
    }

    foreach ($event in @($RetirementEvents)) {
        $buildVisitCount++
        $retirementVisitCount++
        if ($null -eq $event -or
            $event.EventName -notin @(
                'filetransfer_outbound_physical_send_lease_retired',
                'filetransfer_route_transition_physical_send_lease_retired')) {
            continue
        }
        $sourceScopeKey =
            Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainSourceScopeKey `
                -Event $event `
                -SourcePrefixed
        if ([string]::IsNullOrWhiteSpace($sourceScopeKey)) {
            continue
        }
        if (-not $retirementsBySourceScope.ContainsKey($sourceScopeKey)) {
            $retirementsBySourceScope[$sourceScopeKey] =
                New-Object System.Collections.Generic.List[object]
        }
        $sequence = [int64]$event.Sequence
        if ($retirementLastSequenceBySourceScope.ContainsKey($sourceScopeKey) -and
            $sequence -lt [int64]$retirementLastSequenceBySourceScope[$sourceScopeKey]) {
            $unorderedRetirementSourceScopes[$sourceScopeKey] = $true
        }
        $retirementLastSequenceBySourceScope[$sourceScopeKey] = $sequence
        $retirementsBySourceScope[$sourceScopeKey].Add($event) | Out-Null
    }

    foreach ($eventName in @($eventsByName.Keys)) {
        $eventsByName[$eventName] = @(
            $eventsByName[$eventName] | Sort-Object Sequence, LineNumber
        )
    }
    foreach ($sourceScopeKey in @($unorderedRetirementSourceScopes.Keys)) {
        $retirementsBySourceScope[$sourceScopeKey] = @(
            $retirementsBySourceScope[$sourceScopeKey] |
                Sort-Object Sequence, LineNumber
        )
    }

    return [pscustomobject]@{
        EventsByName = $eventsByName
        RetirementsBySourceScope = $retirementsBySourceScope
        IndexBuildVisitCount = $buildVisitCount
        SemanticIndexBuildVisitCount = $semanticVisitCount
        RetirementIndexBuildVisitCount = $retirementVisitCount
        BoundedLookupVisitCount = 0L
    }
}

function Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents {
    param(
        [Parameter(Mandatory = $true)]$Index,
        [Parameter(Mandatory = $true)][string]$EventName
    )

    if ($Index.EventsByName.ContainsKey($EventName)) {
        return @($Index.EventsByName[$EventName])
    }
    return @()
}

function Find-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainRetirement {
    param(
        [Parameter(Mandatory = $true)]$Index,
        [Parameter(Mandatory = $true)]$Command,
        [Parameter(Mandatory = $true)][int64]$AfterSequence,
        [Parameter(Mandatory = $true)][int64]$BeforeSequence
    )

    $scopeKey = Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainSourceScopeKey `
        -Event $Command
    if ([string]::IsNullOrWhiteSpace($scopeKey)) {
        $Index.BoundedLookupVisitCount = [int64]$Index.BoundedLookupVisitCount + 1L
        return @()
    }

    if (-not $Index.RetirementsBySourceScope.ContainsKey($scopeKey)) {
        $Index.BoundedLookupVisitCount = [int64]$Index.BoundedLookupVisitCount + 1L
        return @()
    }

    $events = $Index.RetirementsBySourceScope[$scopeKey]
    $low = 0
    $high = $events.Count
    while ($low -lt $high) {
        $Index.BoundedLookupVisitCount = [int64]$Index.BoundedLookupVisitCount + 1L
        $middle = $low + [int](($high - $low) / 2)
        if ([int64]$events[$middle].Sequence -le $AfterSequence) {
            $low = $middle + 1
        }
        else {
            $high = $middle
        }
    }

    for ($eventIndex = $low; $eventIndex -lt $events.Count; $eventIndex++) {
        $Index.BoundedLookupVisitCount = [int64]$Index.BoundedLookupVisitCount + 1L
        $candidate = $events[$eventIndex]
        if ([int64]$candidate.Sequence -ge $BeforeSequence) {
            break
        }
        $registeredCount = Get-FileTransferEventInt64Field `
            -Event $candidate `
            -Name 'registered_send_count' `
            -Default 0
        if ($registeredCount -le 0 -or
            $registeredCount -ne (Get-FileTransferEventInt64Field `
                -Event $candidate `
                -Name 'retired_send_count' `
                -Default -1)) {
            continue
        }
        return @($candidate)
    }

    return @()
}

function Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowNull()]$Index = $null
    )

    if ($null -eq $Index) {
        [object[]]$semanticEvents = @($Events | Where-Object {
                $null -ne $_ -and $_.EventName -notin @(
                    'filetransfer_outbound_physical_send_lease_retired',
                    'filetransfer_route_transition_physical_send_lease_retired')
            })
        [object[]]$retirementEvents = @($Events | Where-Object {
                $null -ne $_ -and $_.EventName -in @(
                    'filetransfer_outbound_physical_send_lease_retired',
                    'filetransfer_route_transition_physical_send_lease_retired')
            })
        $Index = New-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndex `
            -SemanticEvents $semanticEvents `
            -RetirementEvents $retirementEvents
    }

    [object[]]$commands = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'filetransfer_bridge_recovery_execution_command_issued')
    [object[]]$starts = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'nkn_bridge_recovery_execution_started')
    [object[]]$barriers = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'nkn_bridge_recovery_submission_barrier_closed' | Where-Object {
        (Get-FileTransferEventInt64Field -Event $_ -Name 'submission_epoch' -Default 0) -gt 0
    })
    [object[]]$heldEvents = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'filetransfer_bridge_recovery_payload_submission_held' | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'recovery_execution_state' -Default '').ToLowerInvariant() -in
            @('issued', 'running')
    })
    [object[]]$drainStarts = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'nkn_bridge_recovery_submission_barrier_drain_started')
    [object[]]$drainCompletions = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'nkn_bridge_recovery_submission_barrier_drain_completed' | Where-Object {
        (
            (Get-FileTransferEventField -Event $_ -Name 'gate_acquired' -Default '0') -eq '1' -or
            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '').ToLowerInvariant() -eq
                'completed'
        )
    })
    [object[]]$barrierInvalidations = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'nkn_bridge_recovery_submission_barrier_invalidated' | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
            'bridge_recovery_execution_restart_not_ready'
    })
    [object[]]$hardDecisions = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'nkn_bridge_recovery_execution_hard_restart_decided' | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '').ToLowerInvariant() -eq 'started'
    })
    [object[]]$spawns = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'bridge_spawned')
    [object[]]$readyEvents = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'bridge_ready')
    [object[]]$completions = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'nkn_bridge_recovery_execution_completed' | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'physical_execution_terminated' -Default '0') -eq '1'
    })
    [object[]]$receiptDecisions = @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'filetransfer_bridge_recovery_execution_receipt_decision_observed' | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'disposition' -Default '').ToLowerInvariant() -eq 'accepted'
    })
    [object[]]$terminalEvents = @(
        @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'transfer_terminal') +
        @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'file_transfer_inbound_terminal') +
        @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'file_transfer_outbound_terminal') +
        @(Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndexedEvents -Index $Index -EventName 'filetransfer_runtime_terminalized') |
            Sort-Object Sequence, LineNumber
    )

    function Test-BridgeRecoveryDrainProcessMatch {
        param(
            [Parameter(Mandatory = $true)]$Barrier,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in @('submission_epoch', 'source_process_epoch', 'source_process_id')) {
            $expected = Get-FileTransferEventField -Event $Barrier -Name $field -Default ''
            $actual = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($expected) -or
                [string]::IsNullOrWhiteSpace($actual) -or
                $expected -ne $actual) {
                return $false
            }
        }
        return $true
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($barrier in $barriers) {
        $command = @($commands | Where-Object {
            [int64]$_.Sequence -lt [int64]$barrier.Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $_ -Candidate $barrier)
        } | Select-Object -Last 1)
        if ($command.Count -eq 0) {
            continue
        }
        $command = $command[0]
        $start = @($starts | Where-Object {
            [int64]$_.Sequence -gt [int64]$command.Sequence -and
            [int64]$_.Sequence -lt [int64]$barrier.Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_)
        } | Select-Object -First 1)
        if ($start.Count -eq 0) {
            continue
        }

        $nextCommand = @($commands | Where-Object {
            [int64]$_.Sequence -gt [int64]$command.Sequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $command -Right $_ -IncludeDirection) -and
            -not (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_)
        } | Select-Object -First 1)
        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$barrier.Sequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch -Receipt $command -Terminal $_)
        } | Select-Object -First 1)
        $boundarySequence = [int64]::MaxValue
        foreach ($boundary in @($nextCommand + $terminal)) {
            if ($null -ne $boundary -and [int64]$boundary.Sequence -lt $boundarySequence) {
                $boundarySequence = [int64]$boundary.Sequence
            }
        }

        $held = @($heldEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$barrier.Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_)
        } | Select-Object -First 1)
        $fullyRetired = @(
            Find-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainRetirement `
                -Index $Index `
                -Command $command `
                -AfterSequence ([int64]$barrier.Sequence) `
                -BeforeSequence $boundarySequence
        )
        if ($held.Count -eq 0 -or $fullyRetired.Count -eq 0) {
            continue
        }

        $hardDecision = @($hardDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$barrier.Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_)
        } | Select-Object -First 1)
        $drainStart = @($drainStarts | Where-Object {
            $hardDecision.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$hardDecision[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_) -and
            (Test-BridgeRecoveryDrainProcessMatch -Barrier $barrier -Candidate $_)
        } | Select-Object -First 1)
        $drainCompleted = @($drainCompletions | Where-Object {
            $hardDecision.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$hardDecision[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_) -and
            (Test-BridgeRecoveryDrainProcessMatch -Barrier $barrier -Candidate $_)
        } | Select-Object -First 1)
        $writerId = Get-FileTransferEventField -Event $command -Name 'log_writer_id' -Default ''
        $spawn = @($spawns | Where-Object {
            $drainCompleted.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$drainCompleted[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId
        } | Select-Object -First 1)
        $ready = @($readyEvents | Where-Object {
            $spawn.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$spawn[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId -and
            (
                [string]::IsNullOrWhiteSpace(
                    (Get-FileTransferEventField -Event $spawn[0] -Name 'pid' -Default '')) -or
                (Get-FileTransferEventField -Event $_ -Name 'pid' -Default '') -eq
                    (Get-FileTransferEventField -Event $spawn[0] -Name 'pid' -Default '')
            )
        } | Select-Object -First 1)
        $completed = @($completions | Where-Object {
            $ready.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$ready[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Get-FileTransferEventField -Event $_ -Name 'outcome' -Default '').ToLowerInvariant() -eq
                'completed' -and
            (Get-FileTransferEventField -Event $_ -Name 'total_deadline_expired' -Default '0') -eq '0' -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_)
        } | Select-Object -First 1)
        $completedReceipt = @($receiptDecisions | Where-Object {
            $completed.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$completed[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Get-FileTransferEventField -Event $_ -Name 'execution_outcome' -Default '').ToLowerInvariant() -eq
                'completed' -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_)
        } | Select-Object -First 1)

        $failureInvalidation = @($barrierInvalidations | Where-Object {
            [int64]$_.Sequence -gt [int64]$fullyRetired[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_) -and
            (Test-BridgeRecoveryDrainProcessMatch -Barrier $barrier -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'process_epoch' -Default '') -eq
                (Get-FileTransferEventField -Event $_ -Name 'source_process_epoch' -Default '') -and
            (Get-FileTransferEventField -Event $_ -Name 'process_id' -Default '') -eq
                (Get-FileTransferEventField -Event $_ -Name 'source_process_id' -Default '')
        } | Select-Object -First 1)
        $failureCompletion = @($completions | Where-Object {
            $failureInvalidation.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$failureInvalidation[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Get-FileTransferEventField -Event $_ -Name 'outcome' -Default '').ToLowerInvariant() -eq
                'exhausted' -and
            (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
                'bridge_recovery_execution_timeout' -and
            (Get-FileTransferEventField -Event $_ -Name 'total_deadline_expired' -Default '0') -eq '1' -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_)
        } | Select-Object -First 1)
        $failureReceipt = @($receiptDecisions | Where-Object {
            $failureCompletion.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$failureCompletion[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Get-FileTransferEventField -Event $_ -Name 'execution_outcome' -Default '').ToLowerInvariant() -eq
                'exhausted' -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_)
        } | Select-Object -First 1)
        $hardBeforeInvalidation = @($hardDecisions | Where-Object {
            $failureInvalidation.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$barrier.Sequence -and
            [int64]$_.Sequence -lt [int64]$failureInvalidation[0].Sequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch -Command $command -Candidate $_)
        }).Count -gt 0
        $spawnBeforeInvalidation = @($spawns | Where-Object {
            $failureInvalidation.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$barrier.Sequence -and
            [int64]$_.Sequence -lt [int64]$failureInvalidation[0].Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId
        }).Count -gt 0
        $readyBeforeInvalidation = @($readyEvents | Where-Object {
            $failureInvalidation.Count -gt 0 -and
            [int64]$_.Sequence -gt [int64]$barrier.Sequence -and
            [int64]$_.Sequence -lt [int64]$failureInvalidation[0].Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writerId
        }).Count -gt 0

        $isRecovered = $drainStart.Count -gt 0 -and
            $drainCompleted.Count -gt 0 -and
            $hardDecision.Count -gt 0 -and
            $spawn.Count -gt 0 -and
            $ready.Count -gt 0 -and
            $completed.Count -gt 0 -and
            $completedReceipt.Count -gt 0
        $isUnresolved = $failureInvalidation.Count -gt 0 -and
            $failureCompletion.Count -gt 0 -and
            $failureReceipt.Count -gt 0 -and
            -not $hardBeforeInvalidation -and
            -not $spawnBeforeInvalidation -and
            -not $readyBeforeInvalidation
        if (-not $isRecovered -and -not $isUnresolved) {
            continue
        }

        $candidateEvent = if ($isUnresolved) { $failureInvalidation[0] } else { $drainStart[0] }
        $rawCandidates.Add($candidateEvent) | Out-Null
        $tupleKey = [string]::Join('|', @(
                (Get-FileTransferEventField -Event $command -Name 'session_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'transfer_id' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'direction' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'route' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'runtime_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'terminal_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'leg_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'transport_epoch' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'bridge_recovery_generation' -Default '(missing)'),
                (Get-FileTransferEventField -Event $command -Name 'bridge_decision_generation' -Default '(missing)'),
                (Get-FileTransferRegularV4RecoveryLeaseField `
                    -Event $command `
                    -Names @('recovery_liveness_lease_generation', 'lease_generation')),
                (Get-FileTransferEventField -Event $barrier -Name 'submission_epoch' -Default '(missing)'),
                (Get-FileTransferEventField -Event $barrier -Name 'source_process_epoch' -Default '(missing)'),
                (Get-FileTransferEventField -Event $barrier -Name 'source_process_id' -Default '(missing)')))
        if ($seen.ContainsKey($tupleKey)) {
            continue
        }
        $seen[$tupleKey] = $true
        $distinctCandidates.Add($candidateEvent) | Out-Null
        if ($isRecovered) {
            $recoveredCandidates.Add($candidateEvent) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($candidateEvent) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) {
            'fail'
        }
        elseif ($distinctCandidates.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        IndexBuildVisitCount = [int64]$Index.IndexBuildVisitCount
        SemanticIndexBuildVisitCount = [int64]$Index.SemanticIndexBuildVisitCount
        RetirementIndexBuildVisitCount = [int64]$Index.RetirementIndexBuildVisitCount
        BoundedLookupVisitCount = [int64]$Index.BoundedLookupVisitCount
    }
}

function Get-FileTransferRuntimeUnlockRegularV4RecoveryLeaseCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$lifecycleDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved')
    })
    [object[]]$leaseGrants = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_recovery_liveness_lease_granted' -or
        (
            $_.EventName -eq 'filetransfer_bridge_recovery_authority_granted' -and
            [int](Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_generation' -Default '0') -gt 0 -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_liveness_lease_state' -Default '') -eq 'Active'
        )
    })
    [object[]]$bridgeRecoveryAuthorities = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'bridge_recovery_kind' -Default 'BridgeReceiveStallRecovery') -eq
            'BridgeReceiveStallRecovery'
    })
    [object[]]$closureRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_rejected'
    })
    [object[]]$bridgeRecoveryExecutionCommands = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_execution_command_issued'
    })
    [object[]]$bridgeRecoveryExecutionStarts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_execution_start_decided'
    })
    [object[]]$bridgeRecoveryExecutionCompletions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'nkn_bridge_recovery_execution_completed' -and
        (Get-FileTransferEventField -Event $_ -Name 'outcome' -Default '').ToLowerInvariant() -eq
            'completed'
    })
    [object[]]$bridgeRecoveryExecutionCompletionDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_execution_completion_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'execution_outcome' -Default '').ToLowerInvariant() -eq
            'completed' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in
            @('Accepted', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_status' -Default '') -in
            @('Accepted', 'Idempotent')
    })
    [object[]]$closureRetainedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_retained'
    })
    [object[]]$closureAdoptedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_adopted'
    })
    [object[]]$closureConsumedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_consumed'
    })
    [object[]]$retryHeldEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_retry_blocked_by_regular_v4_receive_recovery',
            'runtime_unlock_retry_dispatch_held_by_regular_v4_receive_recovery')
    })
    [object[]]$retryAuthorityGrantedEvents = @($EffectiveGrantEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted'
    })
    [object[]]$terminalEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'transfer_terminal',
            'file_transfer_inbound_terminal',
            'file_transfer_outbound_terminal')
    })
    [object[]]$closureLivenessDeferralRejectedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_rejected'
    })
    [object[]]$closureLivenessRejectedEvents = @($orderedEvents | Where-Object {
        if ($_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_rejected') {
            return (Get-FileTransferRegularV4RecoveryLeaseField `
                -Event $_ `
                -Names @('rejection_reason', 'decision_reason', 'reason')) -eq
                    'recovery_liveness_lease_missing'
        }

        return $_.EventName -eq 'filetransfer_recovery_authority_rejected' -and
            (Get-FileTransferEventField -Event $_ -Name 'action_kind' -Default '') -eq 'LivenessDeferral' -and
             (Get-FileTransferRegularV4RecoveryLeaseField `
                 -Event $_ `
                 -Names @('rejection_reason', 'decision_reason', 'reason')) -eq 'recovery_liveness_lease_missing'
    })
    [object[]]$closureLivenessDeferralGrantedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_granted'
    })
    [object[]]$closureLivenessGrantedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_deferral_granted' -or
        ($_.EventName -eq 'filetransfer_recovery_liveness_lease_granted' -and
            (Get-FileTransferEventField -Event $_ -Name 'action_kind' -Default '') -eq
                'RecoveryLeaseClosureLivenessDeferral')
    })
    [object[]]$frontierRepairSettlementAcceptedEvents = @($orderedEvents | Where-Object {
        if ($_.EventName -ne 'filetransfer_regular_v4_frontier_repair_settlement_accepted') {
            return $false
        }

        $outcome = (Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $_ `
            -Names @('outcome', 'settlement_outcome')).ToLowerInvariant()
        return $outcome -in @('missing_dispatch', 'settled_stalled')
    })
    [object[]]$frontierRepairSettlementAdoptedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_frontier_repair_settlement_handoff_adopted' -and
        (Get-FileTransferEventField -Event $_ -Name 'handoff_disposition' -Default 'Adopted') -eq 'Adopted'
    })
    [object[]]$closureHoldPreservedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_regular_v4_recovery_lease_closure_hold_preserved'
    })
    [object[]]$closureHoldRejectedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'v4_recovery_terminal_no_proof'
    })

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenLifecycleTuples = @{}

    for ($index = 0; $index -lt $lifecycleDecisions.Count; $index++) {
        $lifecycle = $lifecycleDecisions[$index]
        $lifecycleSequence = [int64]$lifecycle.Sequence

        $nextLifecycleSequence = [int64]::MaxValue
        for ($nextIndex = $index + 1; $nextIndex -lt $lifecycleDecisions.Count; $nextIndex++) {
            $nextLifecycle = $lifecycleDecisions[$nextIndex]
            if (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                    -Left $lifecycle `
                    -Right $nextLifecycle `
                    -IncludeDirection) {
                $nextLifecycleSequence = [int64]$nextLifecycle.Sequence
                break
            }
        }

        $matchingAuthority = @($bridgeRecoveryAuthorities | Where-Object {
            [int64]$_.Sequence -lt $lifecycleSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $_ `
                -Right $lifecycle `
                -IncludeDirection)
        } | Select-Object -Last 1)
        $recoveryWindowStart = if ($matchingAuthority.Count -gt 0) {
            [int64]$matchingAuthority[0].Sequence
        }
        else {
            $previousLifecycle = @($lifecycleDecisions | Where-Object {
                [int64]$_.Sequence -lt $lifecycleSequence -and
                (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                    -Left $_ `
                    -Right $lifecycle `
                    -IncludeDirection)
            } | Select-Object -Last 1)
            if ($previousLifecycle.Count -gt 0) { [int64]$previousLifecycle[0].Sequence } else { -1L }
        }

        # Any lease grant in the exact recovery window means the defect is a
        # stale/mismatched lease, not a lease that was never issued. Keep those
        # domains disjoint even when the old telemetry lacks mismatch_kind.
        $windowLeaseGrants = @($leaseGrants | Where-Object {
            [int64]$_.Sequence -ge $recoveryWindowStart -and
            [int64]$_.Sequence -lt $lifecycleSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $_ `
                -Right $lifecycle `
                -IncludeDirection)
        })
        $matchingLeaseGrant = @($windowLeaseGrants | Where-Object {
            Test-FileTransferRegularV4RecoveryLeaseGrantMatch `
                -LeaseGrant $_ `
                -LifecycleDecision $lifecycle
        } | Select-Object -Last 1)
        if ($matchingLeaseGrant.Count -gt 0 -or $windowLeaseGrants.Count -gt 0) {
            continue
        }

        $matchingRejection = @($closureRejections | Where-Object {
            [int64]$_.Sequence -gt $lifecycleSequence -and
            [int64]$_.Sequence -lt $nextLifecycleSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseClosureRejectionMatch `
                -LifecycleDecision $lifecycle `
                -ClosureRejection $_)
        } | Select-Object -First 1)
        if ($matchingRejection.Count -eq 0) {
            continue
        }

        $candidate = $matchingRejection[0]
        $rawCandidates.Add($candidate) | Out-Null
        $tupleKey = Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $lifecycle
        if ($seenLifecycleTuples.ContainsKey($tupleKey)) {
            continue
        }

        $seenLifecycleTuples[$tupleKey] = $true
        $distinctCandidates.Add($candidate) | Out-Null
        $unresolvedCandidates.Add($candidate) | Out-Null
    }

    $issuanceVerdict = if ($unresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    # A completed bridge lifecycle retires the coordinator lease, but the exact
    # retained closure keeps the existing retry Held until local receive proof.
    # An accepted/adopted repair settlement transfers ownership into this
    # closure window; a terminal-no-proof disposition before that window closes
    # is therefore the conclusive failure, not the earlier repair deferral.
    $closureHoldRawCandidates = New-Object System.Collections.Generic.List[object]
    $closureHoldDistinctCandidates = New-Object System.Collections.Generic.List[object]
    $closureHoldRecoveredCandidates = New-Object System.Collections.Generic.List[object]
    $closureHoldUnresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $closureWindowOwnedReceiptKeys = @{}
    $seenClosureHoldTuples = @{}
    foreach ($receipt in @($closureRetainedEvents | Sort-Object Sequence, LineNumber)) {
        $receiptSequence = [int64]$receipt.Sequence
        $receiptTupleKey = Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $receipt
        $lifecycle = @($lifecycleDecisions | Where-Object {
            [int64]$_.Sequence -le $receiptSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -eq 'Completed' -and
            (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($lifecycle.Count -eq 0) {
            continue
        }

        $nextReceipt = @($closureRetainedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $receipt `
                -Right $_ `
                -IncludeDirection)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $nextRecoveryAuthority = @($bridgeRecoveryAuthorities | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryAuthorityReplacesClosure `
                -Receipt $receipt `
                -Authority $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch -Receipt $receipt -Terminal $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $adoptionOrConsumption = @(@($closureAdoptedEvents + $closureConsumedEvents) | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $boundarySequence = [int64]::MaxValue
        foreach ($boundary in @($nextReceipt + $nextRecoveryAuthority + $terminal + $adoptionOrConsumption)) {
            if ($null -ne $boundary -and [int64]$boundary.Sequence -lt $boundarySequence) {
                $boundarySequence = [int64]$boundary.Sequence
            }
        }

        $matchingAdoptions = @($frontierRepairSettlementAdoptedEvents | Where-Object {
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        $matchingAdoption = @()
        $matchingSettlement = @()
        foreach ($adoption in $matchingAdoptions) {
            $settlement = @($frontierRepairSettlementAcceptedEvents | Where-Object {
                [int64]$_.Sequence -lt [int64]$adoption.Sequence -and
                (Test-FileTransferRegularV4RepairSettlementAdoptionMatch `
                    -Settlement $_ `
                    -Adoption $adoption)
            } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
            if ($settlement.Count -gt 0) {
                $matchingAdoption = @($adoption)
                $matchingSettlement = $settlement
                break
            }
        }
        $hasAcceptedAdoptedRepairSettlement =
            $matchingAdoption.Count -gt 0 -and $matchingSettlement.Count -gt 0
        if (-not $hasAcceptedAdoptedRepairSettlement) {
            continue
        }
        $adoptionSequence = [int64]$matchingAdoption[0].Sequence
        $rejections = @($closureHoldRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -ge $adoptionSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch -Receipt $receipt -Candidate $_) -and
            (Test-FileTransferRegularV4RecoveryClosureHoldLegacyBindingUnique `
                -Receipt $receipt `
                -Candidate $_ `
                -Receipts $closureRetainedEvents) -and
            (Test-FileTransferRegularV4RecoveryClosureHoldDeadlineCurrent -Receipt $receipt -Candidate $_) -and
            (Test-FileTransferRuntimeUnlockRetryCurrentBinding -Event $_)
        } | Sort-Object Sequence, LineNumber)
        $matchingPreservedHold = @($closureHoldPreservedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureHoldTupleMatch -Receipt $receipt -Candidate $_) -and
            (Test-FileTransferRegularV4RecoveryClosureHoldLegacyBindingUnique `
                -Receipt $receipt `
                -Candidate $_ `
                -Receipts $closureRetainedEvents) -and
            (Test-FileTransferRegularV4RecoveryClosureHoldDeadlineCurrent -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($rejections.Count -gt 0 -or $matchingPreservedHold.Count -gt 0) {
            $closureWindowOwnedReceiptKeys[$receiptTupleKey] = $true
        }

        foreach ($rejection in $rejections) {
            $closureHoldRawCandidates.Add($rejection) | Out-Null
            $repairRequestKey = Get-FileTransferEventField `
                -Event $matchingSettlement[0] `
                -Name 'repair_request_key' `
                -Default '(missing)'
            $settlementGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
                -Event $matchingSettlement[0] `
                -Names @('decision_generation', 'settlement_decision_generation') `
                -Default '(missing)'
            $retryTuple = (@('contract_generation', 'retired_generation', 'offer_generation') |
                    ForEach-Object { Get-FileTransferEventField -Event $rejection -Name $_ -Default '(missing)' }) -join '|'
            $candidateKey = $receiptTupleKey + '|' + $repairRequestKey + '|' + $settlementGeneration + '|' + $retryTuple
            if ($seenClosureHoldTuples.ContainsKey($candidateKey)) {
                continue
            }

            $seenClosureHoldTuples[$candidateKey] = $true
            $closureHoldDistinctCandidates.Add($rejection) | Out-Null
            $closureHoldUnresolvedCandidates.Add($rejection) | Out-Null
        }
    }

    $closureHoldVerdict = if ($closureHoldUnresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($closureHoldDistinctCandidates.Count -gt 0 -or $closureHoldPreservedEvents.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    # Closure adoption is a separate proof boundary. It starts only when Infra
    # retained the coordinator-issued receipt, then becomes conclusive at the
    # first exact same-tuple retry hold. Lifecycle completion by itself is not a
    # non-adoption failure.
    $closureNotAdoptedRawCandidates = New-Object System.Collections.Generic.List[object]
    $closureNotAdoptedDistinctCandidates = New-Object System.Collections.Generic.List[object]
    $closureNotAdoptedRecoveredCandidates = New-Object System.Collections.Generic.List[object]
    $closureNotAdoptedUnresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenClosureReceiptTuples = @{}
    foreach ($receipt in @($closureRetainedEvents | Sort-Object Sequence, LineNumber)) {
        $receiptSequence = [int64]$receipt.Sequence
        $receiptTupleKey = Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $receipt
        if ($closureWindowOwnedReceiptKeys.ContainsKey($receiptTupleKey)) {
            continue
        }

        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch -Receipt $receipt -Terminal $_)
        } | Select-Object -First 1)
        $terminalSequence = if ($terminal.Count -gt 0) {
            [int64]$terminal[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        $hold = @($retryHeldEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -lt $terminalSequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch `
                -Receipt $receipt `
                -Candidate $_)
        } | Select-Object -First 1)
        if ($hold.Count -eq 0) {
            continue
        }

        $holdEvent = $hold[0]
        $closureNotAdoptedRawCandidates.Add($holdEvent) | Out-Null
        $tupleKey = Get-FileTransferRegularV4RecoveryBoundaryTupleKey -Event $receipt
        if ($seenClosureReceiptTuples.ContainsKey($tupleKey)) {
            continue
        }

        $seenClosureReceiptTuples[$tupleKey] = $true
        $closureNotAdoptedDistinctCandidates.Add($holdEvent) | Out-Null
        $holdSequence = [int64]$holdEvent.Sequence
        $adoption = @($closureAdoptedEvents | Where-Object {
            [int64]$_.Sequence -gt $holdSequence -and
            [int64]$_.Sequence -lt $terminalSequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch `
                -Receipt $receipt `
                -Candidate $_)
        } | Select-Object -First 1)
        $consumption = @($closureConsumedEvents | Where-Object {
            [int64]$_.Sequence -gt $holdSequence -and
            [int64]$_.Sequence -lt $terminalSequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch `
                -Receipt $receipt `
                -Candidate $_)
        } | Select-Object -First 1)
        $grant = @($retryAuthorityGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt $holdSequence -and
            [int64]$_.Sequence -lt $terminalSequence -and
            (Test-FileTransferRegularV4RecoveryClosureGrantMatch `
                -Receipt $receipt `
                -Grant $_)
        } | Select-Object -First 1)
        if ($adoption.Count -gt 0 -and
            $consumption.Count -gt 0 -and
            $grant.Count -gt 0 -and
            [int64]$adoption[0].Sequence -lt [int64]$consumption[0].Sequence -and
            [int64]$consumption[0].Sequence -le [int64]$grant[0].Sequence) {
            $closureNotAdoptedRecoveredCandidates.Add($holdEvent) | Out-Null
        }
        else {
            $closureNotAdoptedUnresolvedCandidates.Add($holdEvent) | Out-Null
        }
    }

    $closureAdoptionVerdict = if ($closureNotAdoptedUnresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($closureNotAdoptedDistinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    # Lifecycle completion legitimately retires the active recovery lease while
    # Infra keeps waiting for local receive proof. A same-tuple LivenessDeferral
    # rejection in that interval is the first conclusive proof that the bounded
    # closure window lost its coordinator authority.
    $closureLivenessRawCandidates = New-Object System.Collections.Generic.List[object]
    $closureLivenessDistinctCandidates = New-Object System.Collections.Generic.List[object]
    $closureLivenessRecoveredCandidates = New-Object System.Collections.Generic.List[object]
    $closureLivenessUnresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenClosureLivenessTuples = @{}

    # Slice 1 makes the exact one-shot execution receipt the authoritative
    # bridge-recovery completion edge. A Completed command whose accepted
    # lifecycle cannot retain its same-generation closure is a liveness
    # preservation failure even though no closure receipt exists yet.
    foreach ($lifecycle in @($lifecycleDecisions | Where-Object {
            (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -eq
                'Completed'
        } | Sort-Object Sequence, LineNumber)) {
        $lifecycleSequence = [int64]$lifecycle.Sequence
        $command = @($bridgeRecoveryExecutionCommands | Where-Object {
            [int64]$_.Sequence -lt $lifecycleSequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $_ `
                -Candidate $lifecycle)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($command.Count -eq 0) {
            continue
        }

        $start = @($bridgeRecoveryExecutionStarts | Where-Object {
            [int64]$_.Sequence -gt [int64]$command[0].Sequence -and
            [int64]$_.Sequence -lt $lifecycleSequence -and
            (Test-FileTransferBridgeRecoveryExecutionStartMatch `
                -Command $command[0] `
                -Start $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $completion = @($bridgeRecoveryExecutionCompletions | Where-Object {
            [int64]$_.Sequence -gt [int64]$command[0].Sequence -and
            [int64]$_.Sequence -lt $lifecycleSequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($start.Count -eq 0 -or $completion.Count -eq 0) {
            continue
        }

        $nextCommand = @($bridgeRecoveryExecutionCommands | Where-Object {
            [int64]$_.Sequence -gt $lifecycleSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $command[0] `
                -Right $_ `
                -IncludeDirection)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $lifecycleSequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch `
                -Receipt $command[0] `
                -Terminal $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $boundarySequence = [int64]::MaxValue
        foreach ($boundary in @($nextCommand + $terminal)) {
            if ($null -ne $boundary -and [int64]$boundary.Sequence -lt $boundarySequence) {
                $boundarySequence = [int64]$boundary.Sequence
            }
        }

        $rejections = @($closureRejections | Where-Object {
            [int64]$_.Sequence -gt $lifecycleSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -eq
                'Completed' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in
                @('Accepted', 'Idempotent') -and
            (Get-FileTransferRegularV4RecoveryLeaseField `
                -Event $_ `
                -Names @(
                    'regular_v4_liveness_generation',
                    'recovery_liveness_lease_generation',
                    'lease_generation')) -eq
                (Get-FileTransferRegularV4RecoveryLeaseField `
                    -Event $command[0] `
                    -Names @(
                        'recovery_liveness_lease_generation',
                        'lease_generation',
                        'regular_v4_liveness_generation')) -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $command[0] `
                -Right $_) -and
            (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
                -Left $command[0] `
                -Right $_) -and
            (
                (Get-FileTransferEventField -Event $_ -Name 'mismatch_kind' -Default '') -in @(
                    'coordinator_recovery_liveness_lease_mismatch',
                    'coordinator_recovery_liveness_lease_stale') -or
                (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -in @(
                    'coordinator_recovery_liveness_lease_mismatch',
                    'coordinator_recovery_liveness_lease_stale')
            )
        } | Sort-Object Sequence, LineNumber)
        if ($rejections.Count -eq 0) {
            continue
        }

        $legacyRejection = [string]::IsNullOrWhiteSpace(
            (Get-FileTransferEventField -Event $rejections[0] -Name 'direction' -Default '')) -or
            [string]::IsNullOrWhiteSpace(
                (Get-FileTransferEventField `
                    -Event $rejections[0] `
                    -Name 'bridge_decision_generation' `
                    -Default ''))
        if ($legacyRejection) {
            $matchingLifecycleTupleKeys = @($lifecycleDecisions | Where-Object {
                [int64]$_.Sequence -lt [int64]$rejections[0].Sequence -and
                (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -eq
                    'Completed' -and
                (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in
                    @('Accepted', 'Idempotent') -and
                (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                    -Left $_ `
                    -Right $rejections[0]) -and
                (Test-FileTransferBridgeRecoveryExecutionWriterMatch `
                    -Left $_ `
                    -Right $rejections[0]) -and
                (Get-FileTransferRegularV4RecoveryLeaseField `
                    -Event $_ `
                    -Names @(
                        'regular_v4_liveness_generation',
                        'recovery_liveness_lease_generation',
                        'lease_generation')) -eq
                    (Get-FileTransferRegularV4RecoveryLeaseField `
                        -Event $rejections[0] `
                        -Names @(
                            'regular_v4_liveness_generation',
                            'recovery_liveness_lease_generation',
                            'lease_generation'))
            } | ForEach-Object {
                Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $_
            } | Select-Object -Unique)
            if ($matchingLifecycleTupleKeys.Count -ne 1) {
                continue
            }
        }

        $completionDecision = @($bridgeRecoveryExecutionCompletionDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$completion[0].Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($completionDecision.Count -eq 0) {
            continue
        }

        foreach ($rejection in $rejections) {
            $closureLivenessRawCandidates.Add($rejection) | Out-Null
        }
        $tupleKey = Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $command[0]
        if ($seenClosureLivenessTuples.ContainsKey($tupleKey)) {
            continue
        }

        $seenClosureLivenessTuples[$tupleKey] = $true
        $candidate = $rejections[0]
        $closureLivenessDistinctCandidates.Add($candidate) | Out-Null
        $retainedClosure = @($closureRetainedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$candidate.Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferBridgeRecoveryExecutionCommandTupleMatch `
                -Command $command[0] `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($retainedClosure.Count -gt 0) {
            $closureLivenessRecoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $closureLivenessUnresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    foreach ($receipt in @($closureRetainedEvents | Sort-Object Sequence, LineNumber)) {
        $receiptSequence = [int64]$receipt.Sequence
        $nextReceipt = @($closureRetainedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
                -Left $receipt `
                -Right $_ `
                -IncludeDirection)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $nextRecoveryAuthority = @($bridgeRecoveryAuthorities | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryAuthorityReplacesClosure `
                -Receipt $receipt `
                -Authority $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch -Receipt $receipt -Terminal $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $boundarySequence = [int64]::MaxValue
        if ($nextReceipt.Count -gt 0) {
            $boundarySequence = [int64]$nextReceipt[0].Sequence
        }
        if ($nextRecoveryAuthority.Count -gt 0 -and
            [int64]$nextRecoveryAuthority[0].Sequence -lt $boundarySequence) {
            $boundarySequence = [int64]$nextRecoveryAuthority[0].Sequence
        }
        if ($terminal.Count -gt 0 -and [int64]$terminal[0].Sequence -lt $boundarySequence) {
            $boundarySequence = [int64]$terminal[0].Sequence
        }

        $adoptionOrConsumption = @(@($closureAdoptedEvents + $closureConsumedEvents) | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $proofBoundarySequence = if ($adoptionOrConsumption.Count -gt 0) {
            [int64]$adoptionOrConsumption[0].Sequence
        }
        else {
            $boundarySequence
        }
        $rejections = @($closureLivenessRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            [int64]$_.Sequence -lt $proofBoundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureLivenessTupleMatch `
                -Receipt $receipt `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        foreach ($rejection in $rejections) {
            $closureLivenessRawCandidates.Add($rejection) | Out-Null
        }
        if ($rejections.Count -eq 0) {
            continue
        }

        $tupleKey = Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $receipt
        if ($seenClosureLivenessTuples.ContainsKey($tupleKey)) {
            continue
        }

        $seenClosureLivenessTuples[$tupleKey] = $true
        $candidate = $rejections[0]
        $closureLivenessDistinctCandidates.Add($candidate) | Out-Null
        $matchingGrant = @($closureLivenessGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$candidate.Sequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RecoveryClosureLivenessTupleMatch `
                -Receipt $receipt `
                -Candidate $_) -and
            (Test-FileTransferRegularV4RecoveryClosureLivenessProofMatch `
                -Rejection $candidate `
                -Grant $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($matchingGrant.Count -gt 0) {
            $closureLivenessRecoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $closureLivenessUnresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    $closureLivenessVerdict = if ($closureLivenessUnresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($closureLivenessDistinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        ClosureRejectedCount = $closureRejections.Count
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = 0
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $issuanceVerdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        ClosureNotAdoptedRawCount = $closureNotAdoptedRawCandidates.Count
        ClosureNotAdoptedDistinctCount = $closureNotAdoptedDistinctCandidates.Count
        ClosureNotAdoptedRecoveredCount = $closureNotAdoptedRecoveredCandidates.Count
        ClosureNotAdoptedUnresolvedCount = $closureNotAdoptedUnresolvedCandidates.Count
        ClosureAdoptionVerdict = $closureAdoptionVerdict
        ClosureNotAdoptedRawCandidateEvents = @($closureNotAdoptedRawCandidates.ToArray())
        ClosureNotAdoptedDistinctCandidateEvents = @($closureNotAdoptedDistinctCandidates.ToArray())
        ClosureNotAdoptedRecoveredCandidateEvents = @($closureNotAdoptedRecoveredCandidates.ToArray())
        ClosureNotAdoptedUnresolvedCandidateEvents = @($closureNotAdoptedUnresolvedCandidates.ToArray())
        ClosureLivenessRejectedCount = $closureLivenessDeferralRejectedEvents.Count
        ClosureLivenessGrantedCount = $closureLivenessDeferralGrantedEvents.Count
        ClosureLivenessRawCount = $closureLivenessRawCandidates.Count
        ClosureLivenessDistinctCount = $closureLivenessDistinctCandidates.Count
        ClosureLivenessRecoveredCount = $closureLivenessRecoveredCandidates.Count
        ClosureLivenessUnresolvedCount = $closureLivenessUnresolvedCandidates.Count
        ClosureLivenessVerdict = $closureLivenessVerdict
        ClosureLivenessRawCandidateEvents = @($closureLivenessRawCandidates.ToArray())
        ClosureLivenessDistinctCandidateEvents = @($closureLivenessDistinctCandidates.ToArray())
        ClosureLivenessRecoveredCandidateEvents = @($closureLivenessRecoveredCandidates.ToArray())
        ClosureLivenessUnresolvedCandidateEvents = @($closureLivenessUnresolvedCandidates.ToArray())
        ClosureHoldNotPreservedRawCount = $closureHoldRawCandidates.Count
        ClosureHoldNotPreservedDistinctCount = $closureHoldDistinctCandidates.Count
        ClosureHoldNotPreservedRecoveredCount = $closureHoldRecoveredCandidates.Count
        ClosureHoldNotPreservedUnresolvedCount = $closureHoldUnresolvedCandidates.Count
        ClosureHoldPreservationVerdict = $closureHoldVerdict
        ClosureHoldNotPreservedRawCandidateEvents = @($closureHoldRawCandidates.ToArray())
        ClosureHoldNotPreservedDistinctCandidateEvents = @($closureHoldDistinctCandidates.ToArray())
        ClosureHoldNotPreservedRecoveredCandidateEvents = @($closureHoldRecoveredCandidates.ToArray())
        ClosureHoldNotPreservedUnresolvedCandidateEvents = @($closureHoldUnresolvedCandidates.ToArray())
    }
}

function Test-FileTransferRuntimeUnlockRetryDispatchStateTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Authority,
        [Parameter(Mandatory = $true)]$Candidate
    )

    foreach ($field in @(
            'session_id',
            'transfer_id',
            'contract_generation',
            'dispatch_attempt_generation',
            'missing_dispatch_successor_generation')) {
        $authorityValue = Get-FileTransferEventField -Event $Authority -Name $field -Default ''
        $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($authorityValue) -or
            [string]::IsNullOrWhiteSpace($candidateValue) -or
            -not [string]::Equals($authorityValue, $candidateValue, [System.StringComparison]::Ordinal)) {
            return $false
        }
    }

    return $true
}

function Get-FileTransferRuntimeUnlockRetryLifecycleCorrelation {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [object[]]$orderedEvents = @(
        $Events |
            Where-Object { $null -ne $_ } |
            Sort-Object Sequence, LineNumber
    )

    function Test-LifecycleAuthorityMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [switch]$SuccessorEvaluation
        )

        foreach ($field in @(Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields | Where-Object {
                    -not $SuccessorEvaluation -or $_ -ne 'retired_generation'
                })) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    function Test-LifecycleFieldMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)][string]$LeftName,
            [Parameter(Mandatory = $true)]$Right,
            [Parameter(Mandatory = $true)][string]$RightName
        )

        $leftValue = Get-FileTransferEventField -Event $Left -Name $LeftName -Default ''
        $rightValue = Get-FileTransferEventField -Event $Right -Name $RightName -Default ''
        return -not [string]::IsNullOrWhiteSpace($leftValue) -and
            -not [string]::IsNullOrWhiteSpace($rightValue) -and
            [string]::Equals(
                $leftValue,
                $rightValue,
                [System.StringComparison]::OrdinalIgnoreCase)
    }

    [object[]]$executionObservations = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_execution_observed' -and
        (Get-FileTransferEventField -Event $_ -Name 'subscriber_present' -Default '1') -eq '1'
    })
    [object[]]$executionDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_lifecycle_execution_decided'
    })
    [object[]]$successorEvaluations = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_successor_evaluation_requested' -and
        (Get-FileTransferEventField -Event $_ -Name 'subscriber_present' -Default '1') -eq '1'
    })
    [object[]]$successorDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_lifecycle_successor_decided'
    })
    [object[]]$deadlineEvaluations = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_deadline_evaluation_requested' -and
        (Get-FileTransferEventField -Event $_ -Name 'subscriber_present' -Default '1') -eq '1'
    })
    [object[]]$deadlineDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_lifecycle_deadline_decided'
    })

    $effectiveExecutionDecisions = New-Object System.Collections.Generic.List[object]
    $unresolvedExecutionObservations = New-Object System.Collections.Generic.List[object]
    foreach ($observation in $executionObservations) {
        [object[]]$matches = @($executionDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$observation.Sequence -and
            (Test-LifecycleAuthorityMatch -Left $observation -Right $_) -and
            (Test-LifecycleFieldMatch -Left $observation -LeftName 'install_generation' -Right $_ -RightName 'install_generation') -and
            (Test-LifecycleFieldMatch -Left $observation -LeftName 'attempt_phase' -Right $_ -RightName 'attempt_phase') -and
            (Test-LifecycleFieldMatch -Left $observation -LeftName 'offer_generation' -Right $_ -RightName 'offer_generation') -and
            (Test-LifecycleFieldMatch -Left $observation -LeftName 'offer_nonce' -Right $_ -RightName 'offer_nonce') -and
            (Test-LifecycleFieldMatch -Left $observation -LeftName 'dispatch_observed' -Right $_ -RightName 'dispatch_observed')
        } | Sort-Object Sequence, LineNumber)
        if ($matches.Count -eq 0) {
            $unresolvedExecutionObservations.Add($observation) | Out-Null
        }
        else {
            $effectiveExecutionDecisions.Add($matches[0]) | Out-Null
        }
    }

    $effectiveSuccessorCorrelations = New-Object System.Collections.Generic.List[object]
    $unresolvedSuccessorEvaluations = New-Object System.Collections.Generic.List[object]
    foreach ($evaluation in $successorEvaluations) {
        [object[]]$matches = @($successorDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$evaluation.Sequence -and
            (Test-LifecycleAuthorityMatch -Left $evaluation -Right $_ -SuccessorEvaluation) -and
            (Test-LifecycleFieldMatch -Left $evaluation -LeftName 'retired_generation' -Right $_ -RightName 'retired_offer_generation') -and
            (Test-LifecycleFieldMatch -Left $evaluation -LeftName 'requires_listener_retry' -Right $_ -RightName 'requires_listener_retry') -and
            (Test-LifecycleFieldMatch -Left $evaluation -LeftName 'request_active_predecessor_supersession' -Right $_ -RightName 'active_predecessor_supersession')
        } | Sort-Object Sequence, LineNumber)
        if ($matches.Count -eq 0) {
            $unresolvedSuccessorEvaluations.Add($evaluation) | Out-Null
        }
        else {
            $effectiveSuccessorCorrelations.Add([pscustomobject]@{
                Evaluation = $evaluation
                Decision = $matches[0]
            }) | Out-Null
        }
    }

    $effectiveDeadlineCorrelations = New-Object System.Collections.Generic.List[object]
    $unresolvedDeadlineEvaluations = New-Object System.Collections.Generic.List[object]
    foreach ($evaluation in $deadlineEvaluations) {
        [object[]]$matches = @($deadlineDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$evaluation.Sequence -and
            (Test-LifecycleAuthorityMatch -Left $evaluation -Right $_) -and
            (Test-LifecycleFieldMatch -Left $evaluation -LeftName 'install_generation' -Right $_ -RightName 'install_generation') -and
            (Test-LifecycleFieldMatch -Left $evaluation -LeftName 'observed_utc_ms' -Right $_ -RightName 'observed_utc_ms')
        } | Sort-Object Sequence, LineNumber)
        if ($matches.Count -eq 0) {
            $unresolvedDeadlineEvaluations.Add($evaluation) | Out-Null
        }
        else {
            $effectiveDeadlineCorrelations.Add([pscustomobject]@{
                Evaluation = $evaluation
                Decision = $matches[0]
            }) | Out-Null
        }
    }

    $verdict = if (
        $unresolvedExecutionObservations.Count -gt 0 -or
        $unresolvedSuccessorEvaluations.Count -gt 0 -or
        $unresolvedDeadlineEvaluations.Count -gt 0) {
        'fail'
    }
    elseif (
        $executionObservations.Count -gt 0 -or
        $successorEvaluations.Count -gt 0 -or
        $deadlineEvaluations.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        ExecutionObservationCount = $executionObservations.Count
        ExecutionDecisionCount = $effectiveExecutionDecisions.Count
        UnresolvedExecutionObservationEvents = @($unresolvedExecutionObservations.ToArray())
        EffectiveExecutionDecisionEvents = @($effectiveExecutionDecisions.ToArray())
        SuccessorEvaluationCount = $successorEvaluations.Count
        SuccessorDecisionCount = $effectiveSuccessorCorrelations.Count
        SuccessorProtocolObserved = $successorEvaluations.Count -gt 0 -or
            $successorDecisions.Count -gt 0
        UnresolvedSuccessorEvaluationEvents = @($unresolvedSuccessorEvaluations.ToArray())
        EffectiveSuccessorCorrelations = @($effectiveSuccessorCorrelations.ToArray())
        EffectiveSuccessorDecisionEvents = @(
            $effectiveSuccessorCorrelations.ToArray() |
                ForEach-Object { $_.Decision }
        )
        DeadlineEvaluationCount = $deadlineEvaluations.Count
        DeadlineDecisionCount = $effectiveDeadlineCorrelations.Count
        DeadlineProtocolObserved = $deadlineEvaluations.Count -gt 0 -or
            $deadlineDecisions.Count -gt 0
        UnresolvedDeadlineEvaluationEvents = @($unresolvedDeadlineEvaluations.ToArray())
        EffectiveDeadlineCorrelations = @($effectiveDeadlineCorrelations.ToArray())
        EffectiveDeadlineDecisionEvents = @(
            $effectiveDeadlineCorrelations.ToArray() |
                ForEach-Object { $_.Decision }
        )
        Verdict = $verdict
    }
}

function Get-FileTransferRuntimeUnlockRetryDispatchBoundedMissingDispatchClosure {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [Parameter(Mandatory = $true)]$Grant,
        [int64]$AfterSequence = 0
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    $authorityId = Get-FileTransferEventField -Event $Grant -Name 'authority_id' -Default ''
    $attempt = Get-FileTransferEventInt64Field -Event $Grant -Name 'dispatch_attempt_generation' -Default -1
    $missingGeneration = Get-FileTransferEventInt64Field `
        -Event $Grant -Name 'missing_dispatch_successor_generation' -Default -1
    $missingLimit = Get-FileTransferEventInt64Field `
        -Event $Grant -Name 'missing_dispatch_successor_limit' -Default -1
    if ([string]::IsNullOrWhiteSpace($authorityId) -or
        $authorityId -in @('(none)', 'none') -or
        $attempt -lt 1 -or
        $missingGeneration -lt 0 -or
        $missingLimit -lt 0) {
        return $null
    }

    $lifecycleCorrelation =
        Get-FileTransferRuntimeUnlockRetryLifecycleCorrelation -Events $orderedEvents
    [object[]]$effectiveSuccessorDecisions = @(
        $lifecycleCorrelation.EffectiveSuccessorDecisionEvents
    )

    [object[]]$settlements = @($orderedEvents | Where-Object {
        [int64]$_.Sequence -gt $AfterSequence -and
        $_.EventName -eq 'runtime_unlock_retry_dispatch_contract_settled' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
        (Get-FileTransferEventField -Event $_ -Name 'dispatch_observed' -Default '0') -eq '0' -and
        (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $Grant -Right $_)
    } | Sort-Object Sequence, LineNumber)
    foreach ($settlement in $settlements) {
        $settlementReason = Get-FileTransferEventField -Event $settlement -Name 'decision_reason' -Default ''
        [object[]]$reports = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
            $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_reported' -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq $settlementReason -and
            (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $Grant -Right $_)
        } | Sort-Object Sequence, LineNumber)
        if ($reports.Count -eq 0) {
            continue
        }

        [object[]]$decisions = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$reports[0].Sequence -and
            $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_decided' -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq $settlementReason -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
            (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $Grant -Right $_)
        } | Sort-Object Sequence, LineNumber)
        if ($decisions.Count -eq 0) {
            continue
        }

        $requestedAttempt = $attempt + 1
        $requestedMissingGeneration = $missingGeneration + 1
        [object[]]$legacyRejections = if ($lifecycleCorrelation.SuccessorProtocolObserved) {
            @()
        }
        else {
            @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$decisions[0].Sequence -and
            $_.EventName -in @(
                'runtime_unlock_retry_successor_intent_rejected',
                'runtime_unlock_retry_missing_dispatch_successor_limit_rejected') -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
                'retry_dispatch_missing_successor_limit_exhausted' -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq $authorityId -and
            (Get-FileTransferEventField -Event $_ -Name 'requested_predecessor_authority_id' -Default '') -eq
                $authorityId -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'requested_dispatch_attempt_generation' -Default -1) -eq
                $requestedAttempt -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'requested_missing_dispatch_successor_generation' -Default -1) -eq
                $requestedMissingGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'request_active_predecessor_supersession' -Default '') -in
                @('0', 'false', 'False') -and
            (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $Grant -Right $_)
            } | Sort-Object Sequence, LineNumber)
        }
        [object[]]$coordinatorRejections = @($effectiveSuccessorDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$decisions[0].Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @(
                'ChainClosed',
                'Rejected') -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
                'retry_dispatch_missing_successor_limit_exhausted' -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'requested_attempt_generation' -Default -1) -eq
                $requestedAttempt -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'requested_missing_dispatch_generation' -Default -1) -eq
                $requestedMissingGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'active_predecessor_supersession' -Default '') -in
                @('0', 'false', 'False') -and
            (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $Grant -Right $_)
        } | Sort-Object Sequence, LineNumber)
        [object[]]$rejections = @(
            @($legacyRejections + $coordinatorRejections) |
                Sort-Object Sequence, LineNumber
        )
        if ($rejections.Count -eq 0 -or $requestedMissingGeneration -le $missingLimit) {
            continue
        }

        [object[]]$chainClosed = @($orderedEvents | Where-Object {
            $candidate = $_
            if ([int64]$candidate.Sequence -le [int64]$rejections[0].Sequence) {
                return $false
            }

            if ($candidate.EventName -eq 'runtime_unlock_retry_dispatch_chain_closed') {
                return (Get-FileTransferEventField -Event $candidate -Name 'settlement_outcome' -Default '') -eq
                        'MissingDispatch' -and
                    (Get-FileTransferEventField -Event $candidate -Name 'successor_decision_status' -Default '') -eq
                        'Rejected' -and
                    (Get-FileTransferEventField -Event $candidate -Name 'decision_reason' -Default '') -eq
                        'retry_dispatch_missing_successor_limit_exhausted' -and
                    (Get-FileTransferEventInt64Field -Event $candidate -Name 'requested_dispatch_attempt_generation' -Default -1) -eq
                        $requestedAttempt -and
                    (Get-FileTransferEventInt64Field -Event $candidate -Name 'requested_missing_dispatch_successor_generation' -Default -1) -eq
                        $requestedMissingGeneration -and
                    (Get-FileTransferEventField -Event $candidate -Name 'current_authority_cleared' -Default '0') -eq
                        '1' -and
                    (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $Grant -Right $candidate)
            }

            if ($candidate.EventName -ne 'runtime_unlock_retry_lifecycle_chain_closed' -or
                (Get-FileTransferEventField -Event $candidate -Name 'decision_status' -Default '') -notin @(
                    'Accepted',
                    'Idempotent',
                    'ChainClosed') -or
                (Get-FileTransferEventField -Event $candidate -Name 'lifecycle_state' -Default '') -ne
                    'Closed' -or
                (Get-FileTransferEventField -Event $candidate -Name 'decision_reason' -Default '') -ne
                    'retry_dispatch_missing_successor_limit_exhausted' -or
                (Get-FileTransferEventInt64Field -Event $candidate -Name 'rejected_attempt_generation' -Default -1) -ne
                    $requestedAttempt -or
                (Get-FileTransferEventInt64Field -Event $candidate -Name 'rejected_missing_dispatch_generation' -Default -1) -ne
                    $requestedMissingGeneration -or
                (Get-FileTransferEventInt64Field -Event $candidate -Name 'attempt_generation' -Default -1) -ne
                    (Get-FileTransferEventInt64Field -Event $Grant -Name 'dispatch_attempt_generation' -Default -2) -or
                (Get-FileTransferEventInt64Field -Event $candidate -Name 'missing_dispatch_generation' -Default -1) -ne
                    (Get-FileTransferEventInt64Field -Event $Grant -Name 'missing_dispatch_successor_generation' -Default -2) -or
                (Get-FileTransferEventField -Event $candidate -Name 'authority_id' -Default '') -ne
                    $authorityId) {
                return $false
            }

            foreach ($field in @('session_id', 'transfer_id', 'direction')) {
                if ((Get-FileTransferEventField -Event $candidate -Name $field -Default '') -ne
                    (Get-FileTransferEventField -Event $Grant -Name $field -Default '')) {
                    return $false
                }
            }

            return $true
        } | Sort-Object Sequence, LineNumber)
        if ($chainClosed.Count -eq 0) {
            continue
        }

        return [pscustomobject]@{
            Grant = $Grant
            Settlement = $settlement
            Report = $reports[0]
            Decision = $decisions[0]
            Rejection = $rejections[0]
            ChainClosed = $chainClosed[0]
        }
    }

    return $null
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$Candidate,
        [switch]$RequireCompleteRecoveryTuple
    )

    $receiptSession = Get-FileTransferEventField -Event $Receipt -Name 'session_id' -Default ''
    $candidateSession = Get-FileTransferEventField -Event $Candidate -Name 'session_id' -Default ''
    if ([string]::IsNullOrWhiteSpace($receiptSession) -or
        [string]::IsNullOrWhiteSpace($candidateSession) -or
        -not [string]::Equals($receiptSession, $candidateSession, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    $candidateTransfer = Get-FileTransferEventField -Event $Candidate -Name 'transfer_id' -Default ''
    if (-not [string]::IsNullOrWhiteSpace($candidateTransfer) -and
        $candidateTransfer -notin @('(none)', 'none', 'runtime_unlock')) {
        $receiptTransfer = Get-FileTransferEventField -Event $Receipt -Name 'transfer_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptTransfer) -or
            -not [string]::Equals($receiptTransfer, $candidateTransfer, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $candidateDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
    if (-not [string]::IsNullOrWhiteSpace($candidateDirection) -and
        $candidateDirection -notin @('(none)', 'none')) {
        $receiptDirection = Get-FileTransferEventField -Event $Receipt -Name 'direction' -Default ''
        if (-not [string]::Equals($receiptDirection, $candidateDirection, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $fieldAliases = [ordered]@{
        route = @('route')
        protocol_version = @('protocol_version')
        live_route_epoch = @('live_route_epoch')
        runtime_generation = @('runtime_generation')
        terminal_generation = @('terminal_generation')
        leg_generation = @('leg_generation')
        transport_epoch = @('transport_epoch')
        bridge_recovery_generation = @('bridge_recovery_generation')
        bridge_decision_generation = @('bridge_decision_generation')
        regular_v4_liveness_generation = @(
            'regular_v4_liveness_generation',
            'recovery_liveness_lease_generation',
            'lease_generation')
        lease_authority_id = @(
            'lease_authority_id',
            'recovery_liveness_lease_authority_id')
    }
    foreach ($receiptField in $fieldAliases.Keys) {
        $receiptValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Receipt `
            -Names @($receiptField)
        $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField `
            -Event $Candidate `
            -Names $fieldAliases[$receiptField]
        if ([string]::IsNullOrWhiteSpace($candidateValue)) {
            if ($RequireCompleteRecoveryTuple) {
                return $false
            }

            continue
        }

        $valuesMatch = if ($receiptField -eq 'lease_authority_id') {
            Test-FileTransferRecoveryAuthorityEvidenceCompatible -Values @(
                $receiptValue,
                $candidateValue)
        }
        else {
            -not [string]::IsNullOrWhiteSpace($receiptValue) -and
                [string]::Equals(
                    $receiptValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)
        }
        if (-not $valuesMatch) {
            return $false
        }
    }

    if ($RequireCompleteRecoveryTuple) {
        $publicationFieldAliases = [ordered]@{
            session_id = 'source_publication_session_id'
            transfer_id = 'source_publication_transfer_id'
            direction = 'source_publication_direction'
            route = 'source_publication_route'
            protocol_version = 'source_publication_protocol_version'
            live_route_epoch = 'source_publication_live_route_epoch'
            runtime_generation = 'source_publication_runtime_generation'
            terminal_generation = 'source_publication_terminal_generation'
            leg_generation = 'source_publication_leg_generation'
        }
        foreach ($receiptField in $publicationFieldAliases.Keys) {
            $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $receiptField -Default ''
            $publicationValue = Get-FileTransferEventField `
                -Event $Candidate `
                -Name $publicationFieldAliases[$receiptField] `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($receiptValue) -or
                [string]::IsNullOrWhiteSpace($publicationValue) -or
                -not [string]::Equals($receiptValue, $publicationValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        if ([int64](Get-FileTransferEventField `
                -Event $Candidate `
                -Name 'source_publication_route_publication_generation' `
                -Default '0') -le 0) {
            return $false
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutStalePredecessorMatch {
    param(
        [Parameter(Mandatory = $true)]$Receipt,
        [Parameter(Mandatory = $true)]$RejectedAuthority
    )

    if (-not (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch `
            -Left $Receipt `
            -Right $RejectedAuthority `
            -IncludeDirection)) {
        return $false
    }

    if ((Get-FileTransferEventField -Event $RejectedAuthority -Name 'mismatch_field' -Default '') -ne
            'infra_current_binding' -or
        (Get-FileTransferEventField -Event $RejectedAuthority -Name 'decision_reason' -Default '') -ne
            'runtime_unlock_retry_dispatch_authority_tuple_mismatch') {
        return $false
    }

    foreach ($field in @(
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation')) {
        $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
        $authorityValue = Get-FileTransferEventField -Event $RejectedAuthority -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($receiptValue) -or
            [string]::IsNullOrWhiteSpace($authorityValue) -or
            -not [string]::Equals($receiptValue, $authorityValue, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }

    $receiptBridgeDecisionGeneration = [int64](Get-FileTransferEventField `
        -Event $Receipt `
        -Name 'bridge_decision_generation' `
        -Default '0')
    $authorityBridgeDecisionGeneration = [int64](Get-FileTransferEventField `
        -Event $RejectedAuthority `
        -Name 'bridge_decision_generation' `
        -Default '0')
    $receiptLeaseGeneration = [int64](Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Receipt `
        -Names @('lease_generation', 'regular_v4_liveness_generation') `
        -Default '0')
    $authorityReleaseGeneration = [int64](Get-FileTransferEventField `
        -Event $RejectedAuthority `
        -Name 'release_generation' `
        -Default '0')
    if ($receiptBridgeDecisionGeneration -le 0 -or
        $receiptLeaseGeneration -le 0 -or
        $authorityBridgeDecisionGeneration -le 0 -or
        $authorityReleaseGeneration -le 0 -or
        $authorityBridgeDecisionGeneration -ge $receiptBridgeDecisionGeneration -or
        $authorityReleaseGeneration -ge $receiptLeaseGeneration) {
        return $false
    }

    return (Get-FileTransferEventField -Event $RejectedAuthority -Name 'release_kind' -Default '') -eq
            'ReceiveRecoveryLeaseClosure' -and
        (Get-FileTransferEventField -Event $RejectedAuthority -Name 'release_outcome' -Default '') -eq 'Retired'
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutOfferIdentityMatch {
    param(
        [Parameter(Mandatory = $true)]$Timeout,
        [Parameter(Mandatory = $true)]$Candidate,
        $Join = $null
    )

    $timeoutSession = Get-FileTransferEventField -Event $Timeout -Name 'session_id' -Default ''
    $candidateSession = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('offer_session_id', 'session_id')
    if ([string]::IsNullOrWhiteSpace($timeoutSession) -or
        [string]::IsNullOrWhiteSpace($candidateSession) -or
        -not [string]::Equals($timeoutSession, $candidateSession, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    $timeoutInterruptionReason = Get-FileTransferEventField `
        -Event $Timeout `
        -Name 'interruption_reason' `
        -Default ''
    $expectedTimeoutPurpose = switch ($timeoutInterruptionReason) {
        'offer_answer_timeout' { 'offer_answer'; break }
        'offer_peer_response_timeout' { 'offer_peer_response'; break }
        'runtime_unlock_offer_peer_response_timeout' { 'offer_peer_response'; break }
        default {
            if ((Get-FileTransferEventField -Event $Timeout -Name 'trigger' -Default '') -eq
                    'runtime_unlock_offer_send_not_observed' -and
                (Get-FileTransferEventField -Event $Timeout -Name 'recovery_reason' -Default '') -eq
                    'tuna_activation_offer_send_timeout') {
                'offer'
            }
            else {
                ''
            }
            break
        }
    }
    $candidateTimeoutPurpose = Get-FileTransferEventField `
        -Event $Candidate `
        -Name 'timeout_purpose' `
        -Default ''
    if ([string]::IsNullOrWhiteSpace($expectedTimeoutPurpose) -or
        [string]::IsNullOrWhiteSpace($candidateTimeoutPurpose) -or
        -not [string]::Equals(
            $expectedTimeoutPurpose,
            $candidateTimeoutPurpose,
            [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }

    $timeoutPayerDecisionId = Get-FileTransferEventField -Event $Timeout -Name 'payer_decision_id' -Default ''
    $candidatePayerDecisionId = Get-FileTransferEventField -Event $Candidate -Name 'payer_decision_id' -Default ''
    $timeoutOfferGeneration = Get-FileTransferEventField -Event $Timeout -Name 'generation' -Default ''
    $candidateOfferGeneration = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('offer_generation', 'generation')
    if ([string]::IsNullOrWhiteSpace($timeoutPayerDecisionId) -or
        [string]::IsNullOrWhiteSpace($candidatePayerDecisionId) -or
        $timeoutPayerDecisionId -ne $candidatePayerDecisionId -or
        [string]::IsNullOrWhiteSpace($timeoutOfferGeneration) -or
        [string]::IsNullOrWhiteSpace($candidateOfferGeneration) -or
        $timeoutOfferGeneration -ne $candidateOfferGeneration) {
        return $false
    }

    $timeoutNonce = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Timeout `
        -Names @('offer_nonce', 'nonce')
    $candidateNonce = Get-FileTransferRegularV4RecoveryLeaseField `
        -Event $Candidate `
        -Names @('offer_nonce', 'nonce')
    if (-not [string]::IsNullOrWhiteSpace($timeoutNonce) -and
        ([string]::IsNullOrWhiteSpace($candidateNonce) -or
            -not [string]::Equals($timeoutNonce, $candidateNonce, [System.StringComparison]::Ordinal))) {
        return $false
    }

    if ($null -ne $Join) {
        $joinGeneration = Get-FileTransferEventField -Event $Join -Name 'join_generation' -Default ''
        $candidateJoinGeneration = Get-FileTransferEventField -Event $Candidate -Name 'join_generation' -Default ''
        if ([string]::IsNullOrWhiteSpace($joinGeneration) -or
            [string]::IsNullOrWhiteSpace($candidateJoinGeneration) -or
            $joinGeneration -ne $candidateJoinGeneration) {
            return $false
        }

        foreach ($aliases in @(
                [pscustomobject]@{ Join = @('offer_session_id', 'session_id'); Candidate = @('offer_session_id', 'session_id') },
                [pscustomobject]@{ Join = @('offer_nonce', 'nonce'); Candidate = @('offer_nonce', 'nonce') },
                [pscustomobject]@{ Join = @('payer_decision_id'); Candidate = @('payer_decision_id') },
                [pscustomobject]@{ Join = @('offer_generation', 'generation'); Candidate = @('offer_generation', 'generation') })) {
            $joinValue = Get-FileTransferRegularV4RecoveryLeaseField -Event $Join -Names $aliases.Join
            $candidateValue = Get-FileTransferRegularV4RecoveryLeaseField -Event $Candidate -Names $aliases.Candidate
            if ([string]::IsNullOrWhiteSpace($joinValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals($joinValue, $candidateValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }
    }

    return $true
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutFreshArm {
    param(
        [Parameter(Mandatory = $true)]$Arm
    )

    $contractGeneration = [int64](Get-FileTransferEventField `
        -Event $Arm `
        -Name 'contract_generation' `
        -Default '0')
    $predecessorAuthorityId = Get-FileTransferEventField `
        -Event $Arm `
        -Name 'predecessor_authority_id' `
        -Default '(none)'
    return $contractGeneration -gt 0 -and
        (Get-FileTransferEventField -Event $Arm -Name 'dispatch_attempt_generation' -Default '') -eq '1' -and
        (Get-FileTransferEventField -Event $Arm -Name 'missing_dispatch_successor_generation' -Default '') -eq '0' -and
        $predecessorAuthorityId -in @('', '(none)', 'none')
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutGrantBinding {
    param(
        [Parameter(Mandatory = $true)]$Arm,
        [Parameter(Mandatory = $true)]$Consumption,
        [Parameter(Mandatory = $true)]$Grant
    )

    if (-not (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutFreshArm -Arm $Arm)) {
        return $false
    }

    $armContractGeneration = Get-FileTransferEventField -Event $Arm -Name 'contract_generation' -Default ''
    $grantContractGeneration = Get-FileTransferEventField -Event $Grant -Name 'contract_generation' -Default ''
    $grantPredecessorAuthorityId = Get-FileTransferEventField `
        -Event $Grant `
        -Name 'predecessor_authority_id' `
        -Default '(none)'
    if ([string]::IsNullOrWhiteSpace($armContractGeneration) -or
        [string]::IsNullOrWhiteSpace($grantContractGeneration) -or
        $armContractGeneration -ne $grantContractGeneration -or
        (Get-FileTransferEventField -Event $Grant -Name 'dispatch_attempt_generation' -Default '') -ne '1' -or
        (Get-FileTransferEventField -Event $Grant -Name 'missing_dispatch_successor_generation' -Default '') -ne '0' -or
        $grantPredecessorAuthorityId -notin @('', '(none)', 'none')) {
        return $false
    }

    $grantAuthorityId = Get-FileTransferEventField -Event $Grant -Name 'authority_id' -Default ''
    $consumedAuthorityId = Get-FileTransferEventField `
        -Event $Consumption `
        -Name 'retry_authority_id' `
        -Default ''
    return (Test-FileTransferRecoveryAuthorityEvidenceCompatible -Values @(
            $grantAuthorityId,
            $consumedAuthorityId)) -and
        (Get-FileTransferEventField -Event $Consumption -Name 'dispatch_attempt_generation' -Default '') -eq '1' -and
        (Get-FileTransferEventField -Event $Consumption -Name 'missing_dispatch_successor_generation' -Default '') -eq '0'
}

function Test-FileTransferRegularV4RecoveryClosureOfferTimeoutInvalidationDiscard {
    param(
        [Parameter(Mandatory = $true)]$Discard
    )

    $decisionReason = Get-FileTransferEventField -Event $Discard -Name 'decision_reason' -Default ''
    return $decisionReason -in @(
        'retry_join_intent_replaced',
        'regular_v4_recovery_retry_join_intent_replaced',
        'regular_v4_recovery_state_missing',
        'regular_v4_recovery_lease_closure_already_consumed',
        'regular_v4_recovery_lease_closure_stale',
        'regular_v4_recovery_lease_closure_deadline_expired',
        'regular_v4_recovery_route_replaced',
        'regular_v4_recovery_route_publication_replaced',
        'current_filetransfer_owner_authority_mismatch',
        'missing_current_filetransfer_route_publication_authority',
        'ambiguous_current_filetransfer_owner_authority',
        'missing_session_id',
        'phase1_dispatch_contract_owns_successor',
        'dispatch_observed_settlement_not_applied',
        'dispatch_observed_settlement_replaced_before_retry_install',
        'regular_v4_peer_visible_window_failed',
        'existing_regular_v4_receive_recovery_deferral_owned_timeout')
}

function Get-FileTransferRuntimeUnlockRegularV4RecoveryClosureOfferTimeoutCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$receipts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_retained' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'regular_nkn_v4_fast' -and
        (Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '4' -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_decision_status' -Default '') -in @('Accepted', 'Idempotent')
    })
    [object[]]$timeouts = @($orderedEvents | Where-Object {
        if ($_.EventName -ne 'tuna_acceleration_activation_offer_not_observed') {
            return $false
        }

        $interruption = Get-FileTransferEventField -Event $_ -Name 'interruption_reason' -Default ''
        $recoveryReason = Get-FileTransferEventField -Event $_ -Name 'recovery_reason' -Default ''
        $retryReason = Get-FileTransferEventField -Event $_ -Name 'retry_reason' -Default ''
        $legacyTimeout = $interruption -in @(
                'offer_answer_timeout',
                'offer_peer_response_timeout',
                'runtime_unlock_offer_peer_response_timeout') -and
            (Get-FileTransferEventField -Event $_ -Name 'peer_received' -Default '') -eq '0' -and
            ($recoveryReason -like '*runtime_unlock*' -or
                $retryReason -like '*runtime_unlock*' -or
                $recoveryReason -in @(
                    'tuna_activation_offer_peer_response_timeout',
                    'tuna_activation_offer_answer_timeout'))
        $directOfferTimeout =
            (Get-FileTransferEventField -Event $_ -Name 'trigger' -Default '') -eq
                'runtime_unlock_offer_send_not_observed' -and
            $recoveryReason -eq 'tuna_activation_offer_send_timeout' -and
            (Get-FileTransferEventField -Event $_ -Name 'retry_after_recovery_armed' -Default '') -in @('0', '1') -and
            (Get-FileTransferEventField -Event $_ -Name 'dispatch_successor_requested' -Default '0') -eq '0' -and
            (Get-FileTransferEventField -Event $_ -Name 'recovery_requested' -Default '0') -eq '0'
        return $legacyTimeout -or $directOfferTimeout
    })
    [object[]]$joinedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_joined'
    })
    [object[]]$armedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_retry_armed'
    })
    [object[]]$discardedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_join_discarded'
    })
    [object[]]$adoptedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_adopted'
    })
    [object[]]$consumedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_consumed'
    })
    [object[]]$grantEvents = @($EffectiveGrantEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'release_kind' -Default '') -eq 'ReceiveRecoveryLeaseClosure' -and
        (Get-FileTransferEventField -Event $_ -Name 'dispatch_attempt_generation' -Default '') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'missing_dispatch_successor_generation' -Default '') -eq '0' -and
        (Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '(none)') -in @('', '(none)', 'none')
    })
    [object[]]$staleAuthorityEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_current_authority_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'mismatch_field' -Default '') -eq 'infra_current_binding' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'runtime_unlock_retry_dispatch_authority_tuple_mismatch'
    })
    [object[]]$installRejectedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_install_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'retry_dispatch_install_authority_no_longer_current_retry_schedule'
    })
    [object[]]$retryNotScheduledEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_activation_offer_retry_not_scheduled' -and
        (Get-FileTransferEventField -Event $_ -Name 'trigger' -Default '') -eq
            'runtime_unlock_offer_send_not_observed'
    })
    [object[]]$terminalEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'transfer_terminal',
            'file_transfer_inbound_terminal',
            'file_transfer_outbound_terminal',
            'filetransfer_runtime_terminalized')
    })
    [object[]]$replacementAuthorities = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_authority_granted'
    })

    function Test-BoundedClosureReceiptScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Closure,
            [Parameter(Mandatory = $true)]$Receipt
        )

        $grant = $Closure.Grant
        if ((Get-FileTransferEventField -Event $grant -Name 'release_kind' -Default '') -ne
                'ReceiveRecoveryLeaseClosure' -or
            (Get-FileTransferEventField -Event $grant -Name 'release_outcome' -Default '') -ne
                'Retired') {
            return $false
        }

        foreach ($field in @(
                'session_id', 'transfer_id', 'direction', 'route', 'protocol_version',
                'live_route_epoch', 'runtime_generation', 'terminal_generation',
                'leg_generation', 'transport_epoch')) {
            $grantValue = Get-FileTransferEventField -Event $grant -Name $field -Default ''
            $receiptValue = Get-FileTransferEventField -Event $Receipt -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($grantValue) -or
                [string]::IsNullOrWhiteSpace($receiptValue) -or
                -not [string]::Equals($grantValue, $receiptValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $sourceFieldMap = [ordered]@{
            source_publication_session_id = 'session_id'
            source_publication_transfer_id = 'transfer_id'
            source_publication_direction = 'direction'
            source_publication_route = 'route'
            source_publication_protocol_version = 'protocol_version'
            source_publication_live_route_epoch = 'live_route_epoch'
            source_publication_runtime_generation = 'runtime_generation'
            source_publication_terminal_generation = 'terminal_generation'
            source_publication_leg_generation = 'leg_generation'
            runtime_owner_session_id = 'session_id'
            runtime_owner_transfer_id = 'transfer_id'
            runtime_owner_direction = 'direction'
            runtime_owner_route = 'route'
            runtime_owner_protocol_version = 'protocol_version'
            runtime_owner_live_route_epoch = 'live_route_epoch'
            runtime_owner_runtime_generation = 'runtime_generation'
            runtime_owner_terminal_generation = 'terminal_generation'
        }
        foreach ($grantField in $sourceFieldMap.Keys) {
            $grantValue = Get-FileTransferEventField -Event $grant -Name $grantField -Default ''
            $receiptValue = Get-FileTransferEventField `
                -Event $Receipt `
                -Name $sourceFieldMap[$grantField] `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($grantValue) -or
                [string]::IsNullOrWhiteSpace($receiptValue) -or
                -not [string]::Equals($grantValue, $receiptValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $grantBridgeDecision = Get-FileTransferEventInt64Field `
            -Event $grant -Name 'bridge_decision_generation' -Default -1
        $receiptBridgeDecision = Get-FileTransferEventInt64Field `
            -Event $Receipt -Name 'bridge_decision_generation' -Default -1
        $grantReleaseGeneration = Get-FileTransferEventInt64Field `
            -Event $grant -Name 'release_generation' -Default -1
        $receiptLivenessGeneration = Get-FileTransferEventInt64Field `
            -Event $Receipt -Name 'regular_v4_liveness_generation' -Default -1
        $grantBridgeRecoveryGeneration = Get-FileTransferEventInt64Field `
            -Event $grant -Name 'bridge_recovery_generation' -Default -1
        $receiptBridgeRecoveryGeneration = Get-FileTransferEventInt64Field `
            -Event $Receipt -Name 'bridge_recovery_generation' -Default -1
        return $receiptBridgeDecision -gt $grantBridgeDecision -and
            $receiptLivenessGeneration -gt $grantReleaseGeneration -and
            $receiptBridgeRecoveryGeneration -ge $grantBridgeRecoveryGeneration
    }

    function Test-DirectOfferTimeoutIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Timeout,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in @('session_id', 'payer_decision_id', 'generation')) {
            $timeoutValue = Get-FileTransferEventField -Event $Timeout -Name $field -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($timeoutValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals($timeoutValue, $candidateValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    $boundedClosures = New-Object System.Collections.Generic.List[object]
    foreach ($grant in @($EffectiveGrantEvents | Sort-Object Sequence, LineNumber)) {
        $closure = Get-FileTransferRuntimeUnlockRetryDispatchBoundedMissingDispatchClosure `
            -Events $orderedEvents `
            -Grant $grant `
            -AfterSequence ([int64]$grant.Sequence)
        if ($null -ne $closure) {
            $boundedClosures.Add($closure) | Out-Null
        }
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $correlatedStaleAuthorityEvents = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($receipt in @($receipts | Sort-Object Sequence, LineNumber)) {
        $receiptSequence = [int64]$receipt.Sequence
        $boundarySequence = [int64]::MaxValue

        $terminal = @($terminalEvents | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryTerminalMatch -Receipt $receipt -Terminal $_)
        } | Select-Object -First 1)
        if ($terminal.Count -gt 0) {
            $boundarySequence = [int64]$terminal[0].Sequence
        }

        $replacement = @($replacementAuthorities | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryAuthorityReplacesClosure -Receipt $receipt -Authority $_)
        } | Select-Object -First 1)
        if ($replacement.Count -gt 0 -and [int64]$replacement[0].Sequence -lt $boundarySequence) {
            $boundarySequence = [int64]$replacement[0].Sequence
        }

        $nextReceipt = @($receipts | Where-Object {
            [int64]$_.Sequence -gt $receiptSequence -and
            (Test-FileTransferRegularV4RecoveryLeaseIdentityMatch -Left $receipt -Right $_ -IncludeDirection)
        } | Select-Object -First 1)
        if ($nextReceipt.Count -gt 0 -and [int64]$nextReceipt[0].Sequence -lt $boundarySequence) {
            $boundarySequence = [int64]$nextReceipt[0].Sequence
        }

        foreach ($timeout in @($timeouts | Where-Object {
                    [int64]$_.Sequence -gt $receiptSequence -and
                    [int64]$_.Sequence -lt $boundarySequence -and
                    (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch `
                        -Receipt $receipt `
                        -Candidate $_)
                } | Sort-Object Sequence, LineNumber)) {
            $timeoutSequence = [int64]$timeout.Sequence
            $adoptionBeforeTimeout = @($adoptedEvents | Where-Object {
                [int64]$_.Sequence -gt $receiptSequence -and
                [int64]$_.Sequence -lt $timeoutSequence -and
                (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
            } | Select-Object -First 1)
            if ($adoptionBeforeTimeout.Count -gt 0) {
                continue
            }

            $matchingJoin = @($joinedEvents | Where-Object {
                [int64]$_.Sequence -gt $receiptSequence -and
                [int64]$_.Sequence -le $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch `
                    -Receipt $receipt `
                    -Candidate $_ `
                    -RequireCompleteRecoveryTuple) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutOfferIdentityMatch `
                    -Timeout $timeout `
                    -Candidate $_)
            } | Select-Object -First 1)
            $matchingArm = @($armedEvents | Where-Object {
                [int64]$_.Sequence -ge $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch `
                    -Receipt $receipt `
                    -Candidate $_ `
                    -RequireCompleteRecoveryTuple) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutOfferIdentityMatch `
                    -Timeout $timeout `
                    -Candidate $_ `
                    -Join $(if ($matchingJoin.Count -gt 0) { $matchingJoin[0] } else { $null })) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutFreshArm -Arm $_)
            } | Select-Object -First 1)
            $matchingInvalidationDiscard = @($discardedEvents | Where-Object {
                [int64]$_.Sequence -ge $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutTupleMatch `
                    -Receipt $receipt `
                    -Candidate $_) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutOfferIdentityMatch `
                    -Timeout $timeout `
                    -Candidate $_ `
                    -Join $(if ($matchingJoin.Count -gt 0) { $matchingJoin[0] } else { $null })) -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutInvalidationDiscard -Discard $_)
            } | Select-Object -First 1)
            $matchingStaleAuthority = @($staleAuthorityEvents | Where-Object {
                [int64]$_.Sequence -gt $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutStalePredecessorMatch `
                    -Receipt $receipt `
                    -RejectedAuthority $_)
            } | Select-Object -First 1)

            $isDirectOfferTimeout =
                (Get-FileTransferEventField -Event $timeout -Name 'trigger' -Default '') -eq
                    'runtime_unlock_offer_send_not_observed' -and
                (Get-FileTransferEventField -Event $timeout -Name 'recovery_reason' -Default '') -eq
                    'tuna_activation_offer_send_timeout'
            $matchingBoundedClosure = @($boundedClosures.ToArray() | Where-Object {
                [int64]$_.ChainClosed.Sequence -lt $receiptSequence -and
                (Test-BoundedClosureReceiptScopeMatch -Closure $_ -Receipt $receipt) -and
                (Get-FileTransferEventField -Event $_.Settlement -Name 'offer_generation' -Default '') -eq
                    (Get-FileTransferEventField -Event $timeout -Name 'generation' -Default '')
            } | Sort-Object { [int64]$_.ChainClosed.Sequence } -Descending | Select-Object -First 1)
            $matchingObsoleteInstallRejection = @()
            $matchingRetryNotScheduled = @()
            if ($isDirectOfferTimeout -and $matchingBoundedClosure.Count -gt 0) {
                $boundedGrant = $matchingBoundedClosure[0].Grant
                $boundedInstallGeneration = Get-FileTransferEventField `
                    -Event $boundedGrant -Name 'install_generation' -Default ''
                $matchingObsoleteInstallRejection = @($installRejectedEvents | Where-Object {
                    [int64]$_.Sequence -gt $timeoutSequence -and
                    [int64]$_.Sequence -lt $boundarySequence -and
                    (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch `
                        -Left $boundedGrant `
                        -Right $_) -and
                    -not [string]::IsNullOrWhiteSpace($boundedInstallGeneration) -and
                    (Get-FileTransferEventField -Event $_ -Name 'install_generation' -Default '') -eq
                        $boundedInstallGeneration
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                $retryFailureAfter = if ($matchingObsoleteInstallRejection.Count -gt 0) {
                    [int64]$matchingObsoleteInstallRejection[0].Sequence
                }
                else {
                    $timeoutSequence
                }
                $matchingRetryNotScheduled = @($retryNotScheduledEvents | Where-Object {
                    [int64]$_.Sequence -gt $retryFailureAfter -and
                    [int64]$_.Sequence -lt $boundarySequence -and
                    (Test-DirectOfferTimeoutIdentityMatch -Timeout $timeout -Candidate $_)
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            }

            $hasLegacyFailureShape =
                (Get-FileTransferEventField -Event $timeout -Name 'recovery_requested' -Default '') -eq '0' -and
                (Get-FileTransferEventField -Event $timeout -Name 'retry_after_recovery_armed' -Default '') -eq '0' -and
                $matchingJoin.Count -eq 0 -and
                $matchingStaleAuthority.Count -gt 0
            $hasBoundedFailureShape =
                $isDirectOfferTimeout -and
                $matchingBoundedClosure.Count -gt 0 -and
                $matchingJoin.Count -eq 0 -and
                $matchingObsoleteInstallRejection.Count -gt 0 -and
                $matchingRetryNotScheduled.Count -gt 0 -and
                (Get-FileTransferEventField -Event $timeout -Name 'retry_scheduled' -Default '') -eq '1' -and
                (Get-FileTransferEventField -Event $timeout -Name 'retry_after_recovery_armed' -Default '') -eq '0'
            $hasExplicitJoinShape = ($matchingJoin.Count -gt 0 -or $matchingArm.Count -gt 0) -and
                (-not $isDirectOfferTimeout -or $matchingBoundedClosure.Count -gt 0)
            if (-not $hasLegacyFailureShape -and
                -not $hasBoundedFailureShape -and
                -not $hasExplicitJoinShape) {
                continue
            }
            if ($matchingInvalidationDiscard.Count -gt 0) {
                continue
            }

            $candidateEvent = if ($hasBoundedFailureShape) {
                $matchingRetryNotScheduled[0]
            }
            else {
                $timeout
            }
            $rawCandidates.Add($candidateEvent) | Out-Null
            $key = (Get-FileTransferRegularV4RecoveryLeaseTupleKey -Event $receipt) + '|' +
                (Get-FileTransferEventField -Event $timeout -Name 'payer_decision_id' -Default '(missing)') + '|' +
                (Get-FileTransferEventField -Event $timeout -Name 'generation' -Default '(missing)') + '|' +
                $(if ($isDirectOfferTimeout) {
                    'offer'
                }
                else {
                    Get-FileTransferEventField -Event $timeout -Name 'interruption_reason' -Default '(missing)'
                }) + '|' +
                $(if ($matchingBoundedClosure.Count -gt 0) {
                    (Get-FileTransferEventField `
                        -Event $matchingBoundedClosure[0].Grant `
                        -Name 'authority_id' `
                        -Default '(missing)') + '|' +
                    (Get-FileTransferEventField `
                        -Event $matchingBoundedClosure[0].Grant `
                        -Name 'install_generation' `
                        -Default '(missing)')
                }
                else {
                    '(legacy)|(legacy)'
                })
            if ($seen.ContainsKey($key)) {
                continue
            }

            $seen[$key] = $true
            $distinctCandidates.Add($candidateEvent) | Out-Null
            if ($matchingStaleAuthority.Count -gt 0) {
                $correlatedStaleAuthorityEvents.Add($matchingStaleAuthority[0]) | Out-Null
            }

            $matchingAdoption = @($adoptedEvents | Where-Object {
                [int64]$_.Sequence -gt $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
            } | Select-Object -First 1)
            $matchingConsumption = @($consumedEvents | Where-Object {
                [int64]$_.Sequence -gt $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RecoveryBoundaryTupleMatch -Receipt $receipt -Candidate $_)
            } | Select-Object -First 1)
            $matchingGrant = @($grantEvents | Where-Object {
                [int64]$_.Sequence -gt $timeoutSequence -and
                [int64]$_.Sequence -lt $boundarySequence -and
                $matchingConsumption.Count -gt 0 -and
                [int64]$_.Sequence -ge [int64]$matchingConsumption[0].Sequence -and
                (Test-FileTransferRegularV4RecoveryClosureGrantMatch -Receipt $receipt -Grant $_) -and
                $matchingArm.Count -gt 0 -and
                (Test-FileTransferRegularV4RecoveryClosureOfferTimeoutGrantBinding `
                    -Arm $matchingArm[0] `
                    -Consumption $matchingConsumption[0] `
                    -Grant $_)
            })

            if ($matchingJoin.Count -gt 0 -and
                $matchingArm.Count -gt 0 -and
                $matchingAdoption.Count -gt 0 -and
                $matchingConsumption.Count -gt 0 -and
                $matchingGrant.Count -eq 1 -and
                [int64]$matchingJoin[0].Sequence -le [int64]$matchingArm[0].Sequence -and
                [int64]$matchingJoin[0].Sequence -lt [int64]$matchingAdoption[0].Sequence -and
                [int64]$matchingArm[0].Sequence -lt [int64]$matchingConsumption[0].Sequence -and
                [int64]$matchingAdoption[0].Sequence -lt [int64]$matchingConsumption[0].Sequence -and
                [int64]$matchingConsumption[0].Sequence -le [int64]$matchingGrant[0].Sequence) {
                $recoveredCandidates.Add($candidateEvent) | Out-Null
            }
            else {
                $unresolvedCandidates.Add($candidateEvent) | Out-Null
            }
        }
    }

    $verdict = if ($unresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        CorrelatedStaleAuthorityEvents = @($correlatedStaleAuthorityEvents.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockInitialOfferRetryLifecycleHandoffCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$offerFailures = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_activation_offer_not_observed' -and
        (Get-FileTransferEventField -Event $_ -Name 'trigger' -Default '') -eq 'runtime_unlock' -and
        (Get-FileTransferEventField -Event $_ -Name 'retry_scheduled' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'retry_after_recovery_armed' -Default '0') -eq '0' -and
        (Get-FileTransferEventField -Event $_ -Name 'dispatch_successor_requested' -Default '0') -eq '0' -and
        (Get-FileTransferEventField -Event $_ -Name 'recovery_requested' -Default '0') -eq '0' -and
        (Get-FileTransferEventField -Event $_ -Name 'recovery_reason' -Default '') -eq
            'tuna_activation_offer_send_timeout'
    })
    [object[]]$installRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_install_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'retry_dispatch_install_state_missing_retry_schedule'
    })
    [object[]]$notScheduledEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_activation_offer_retry_not_scheduled' -and
        (Get-FileTransferEventField -Event $_ -Name 'trigger' -Default '') -eq 'runtime_unlock' -and
        (Get-FileTransferEventField -Event $_ -Name 'retry_reason' -Default '') -eq
            'runtime_unlock_offer_send_not_observed'
    })
    [object[]]$armedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_runtime_unlock_retry_after_recovery_armed'
    })
    [object[]]$initialOffers = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_offer_queued' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'runtime_unlock' -and
        -not [string]::IsNullOrWhiteSpace(
            (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '')) -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'payer_decision_id' -Default '0') -gt 0 -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'generation' -Default '0') -gt 0
    })
    [object[]]$acceptedAnswers = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_sent' -and
        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '0') -eq '1'
    })
    [object[]]$rawAnswers = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_received_raw'
    })
    [object[]]$answerLifecycleAcks = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_lifecycle_ack_sent' -and
        (Get-FileTransferEventField -Event $_ -Name 'message_type' -Default '') -eq
            'transport_acceleration_answer'
    })
    [object[]]$answerInstallRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_install_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'retry_dispatch_install_state_missing_answer_received' -and
        (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '(none)') -in
            @('', '(none)', 'none') -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'install_generation' -Default '0') -eq 0
    })
    [object[]]$offerBoundaryDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_offer_authority_boundary_decided'
    })
    [object[]]$transactionAnswerEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_transaction_answer_received' -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'transaction_generation' -Default '0') -gt 0 -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'offer_generation' -Default '0') -gt 0 -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'tuna_path_lease_generation' -Default '0') -gt 0
    })
    [object[]]$answerAckSentEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_ack_sent'
    })
    [object[]]$preCommitHandoffEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_precommit_probe_launch_requested',
            'filetransfer_runtime_unlock_precommit_probe_launch_handoff_decided',
            'runtime_unlock_precommit_probe_launch_started',
            'runtime_unlock_precommit_probe_started')
    })
    [object[]]$retiredOfferEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_outbound_offer_retired' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
            'runtime_unlock_offer_peer_response_timeout_pending_runtime_unlock_answer'
    })
    [object[]]$pendingAnswerPreservedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_pending_runtime_unlock_answer_preserved' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
            'runtime_unlock_offer_peer_response_timeout_pending_runtime_unlock_answer'
    })
    [object[]]$retiredAnswerAcceptedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_retired_offer_answer_accepted'
    })
    [object[]]$answerAckBarrierEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_answer_ack_probe_barrier_released'
    })
    [object[]]$pendingRouteCommitEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_runtime_unlock_handoff_pending_route_commit' -and
        (Get-FileTransferEventField -Event $_ -Name 'state' -Default '').Equals(
            'offersentobserved',
            [System.StringComparison]::OrdinalIgnoreCase) -and
        (Get-FileTransferEventField -Event $_ -Name 'path_probe_state' -Default '').Equals(
            'none',
            [System.StringComparison]::OrdinalIgnoreCase)
    })

    function Test-InitialOfferIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @('session_id', 'payer_decision_id', 'generation')) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::Ordinal)) {
                return $false
            }
        }
        return (Get-FileTransferEventField -Event $Left -Name 'log_writer_id' -Default '') -eq
            (Get-FileTransferEventField -Event $Right -Name 'log_writer_id' -Default '')
    }

    function Test-InitialOfferWriterMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        $leftWriter = Get-FileTransferEventField -Event $Left -Name 'log_writer_id' -Default ''
        $rightWriter = Get-FileTransferEventField -Event $Right -Name 'log_writer_id' -Default ''
        return -not [string]::IsNullOrWhiteSpace($leftWriter) -and
            -not [string]::IsNullOrWhiteSpace($rightWriter) -and
            [string]::Equals(
                $leftWriter,
                $rightWriter,
                [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Get-InitialOfferBoundaryField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                return $value
            }
        }
        return ''
    }

    function Test-InitialOfferBoundaryIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Offer,
            [Parameter(Mandatory = $true)]$Candidate,
            [switch]$RequireCompleteCandidate
        )

        if (-not (Test-InitialOfferWriterMatch -Left $Offer -Right $Candidate)) {
            return $false
        }

        foreach ($mapping in @(
                [pscustomobject]@{ Offer = @('session_id'); Candidate = @('session_id') },
                [pscustomobject]@{ Offer = @('payer_decision_id'); Candidate = @('payer_decision_id') },
                [pscustomobject]@{ Offer = @('generation'); Candidate = @('offer_generation', 'generation') })) {
            $offerValue = Get-InitialOfferBoundaryField -Event $Offer -Names $mapping.Offer
            $candidateValue = Get-InitialOfferBoundaryField -Event $Candidate -Names $mapping.Candidate
            if ([string]::IsNullOrWhiteSpace($offerValue) -or
                ($RequireCompleteCandidate -and [string]::IsNullOrWhiteSpace($candidateValue)) -or
                (-not [string]::IsNullOrWhiteSpace($candidateValue) -and
                    -not [string]::Equals(
                        $offerValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase))) {
                return $false
            }
        }
        return $true
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($notScheduled in $notScheduledEvents) {
        $offerFailure = @($offerFailures | Where-Object {
            [int64]$_.Sequence -lt [int64]$notScheduled.Sequence -and
            (Test-InitialOfferIdentityMatch -Left $_ -Right $notScheduled)
        } | Select-Object -Last 1)
        if ($offerFailure.Count -ne 1) {
            continue
        }

        $rejection = @($installRejections | Where-Object {
            [int64]$_.Sequence -gt [int64]$offerFailure[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$notScheduled.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq
                (Get-FileTransferEventField -Event $notScheduled -Name 'log_writer_id' -Default '')
        })
        if ($rejection.Count -ne 1) {
            continue
        }

        $rawCandidates.Add($notScheduled) | Out-Null
        $key = [string]::Join('|', @(
                (Get-FileTransferEventField -Event $notScheduled -Name 'log_writer_id' -Default ''),
                (Get-FileTransferEventField -Event $notScheduled -Name 'session_id' -Default ''),
                (Get-FileTransferEventField -Event $notScheduled -Name 'payer_decision_id' -Default ''),
                (Get-FileTransferEventField -Event $notScheduled -Name 'generation' -Default ''))).
            ToLowerInvariant()
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true
        $distinctCandidates.Add($notScheduled) | Out-Null

        $sessionId = Get-FileTransferEventField -Event $notScheduled -Name 'session_id' -Default ''
        $retiredGeneration = Get-FileTransferEventField -Event $notScheduled -Name 'generation' -Default ''
        $arm = @($armedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$notScheduled.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $sessionId -and
            (Get-FileTransferEventField -Event $_ -Name 'retired_generation' -Default '') -eq
                $retiredGeneration
        } | Select-Object -First 1)
        $grant = @()
        if ($arm.Count -eq 1) {
            $grant = @($EffectiveGrantEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$arm[0].Sequence -and
                $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted' -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $sessionId -and
                (Get-FileTransferEventField -Event $_ -Name 'retired_generation' -Default '') -eq
                    $retiredGeneration -and
                (Get-FileTransferEventField -Event $_ -Name 'dispatch_attempt_generation' -Default '') -eq '1' -and
                (Get-FileTransferEventField -Event $_ -Name 'missing_dispatch_successor_generation' -Default '') -eq '0' -and
                (Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '(none)') -in
                    @('', '(none)', 'none')
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        }

        if ($grant.Count -eq 1) {
            $recoveredCandidates.Add($notScheduled) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($notScheduled) | Out-Null
        }
    }

    # Legacy initial activations do not carry a Phase-2 install receipt.  An
    # accepted answer followed by an empty retry-install rejection is therefore
    # a distinct handoff failure, not retry-install evidence.  The legacy
    # rejection is intentionally correlated only inside one complete
    # same-writer offer interval.
    [object[]]$answerBoundaryRejections = @(
        $answerInstallRejections +
        @($offerBoundaryDecisions | Where-Object {
            (Get-InitialOfferBoundaryField -Event $_ -Names @('offer_authority_mode', 'authority_mode')) -eq
                'InitialActivation' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '').Equals(
                'Rejected',
                [System.StringComparison]::OrdinalIgnoreCase) -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -in @(
                'initial_offer_answer_misclassified_as_retry_install',
                'retry_dispatch_install_state_missing_answer_received')
        })
    )
    foreach ($rejection in @($answerBoundaryRejections | Sort-Object Sequence, LineNumber)) {
        [object[]]$matchingOfferRecords = @(
            foreach ($offer in $initialOffers) {
                if ([int64]$offer.Sequence -ge [int64]$rejection.Sequence -or
                    -not (Test-InitialOfferBoundaryIdentityMatch -Offer $offer -Candidate $rejection)) {
                    continue
                }

                $payerDecisionId = Get-FileTransferEventField -Event $offer -Name 'payer_decision_id' -Default ''
                $acceptedAnswer = @($acceptedAnswers | Where-Object {
                    [int64]$_.Sequence -gt [int64]$offer.Sequence -and
                    [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                    (Get-FileTransferEventField -Event $_ -Name 'payer_decision_id' -Default '') -eq
                        $payerDecisionId
                } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
                if ($acceptedAnswer.Count -ne 1) {
                    continue
                }

                $rawAnswer = @($rawAnswers | Where-Object {
                    [int64]$_.Sequence -gt [int64]$acceptedAnswer[0].Sequence -and
                    [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                    (Test-InitialOfferWriterMatch -Left $offer -Right $_)
                } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
                if ($rawAnswer.Count -ne 1) {
                    continue
                }

                $lifecycleAck = @($answerLifecycleAcks | Where-Object {
                    [int64]$_.Sequence -gt [int64]$rawAnswer[0].Sequence -and
                    [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                    (Test-InitialOfferWriterMatch -Left $offer -Right $_)
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                if ($lifecycleAck.Count -ne 1) {
                    continue
                }

                [pscustomobject]@{
                    Offer = $offer
                    AcceptedAnswer = $acceptedAnswer[0]
                    RawAnswer = $rawAnswer[0]
                    LifecycleAck = $lifecycleAck[0]
                    Rejection = $rejection
                }
            }
        )
        if ($matchingOfferRecords.Count -ne 1) {
            continue
        }

        $record = $matchingOfferRecords[0]
        $offer = $record.Offer
        $rawCandidates.Add($rejection) | Out-Null
        $key = [string]::Join('|', @(
                (Get-FileTransferEventField -Event $offer -Name 'log_writer_id' -Default ''),
                (Get-FileTransferEventField -Event $offer -Name 'session_id' -Default ''),
                (Get-FileTransferEventField -Event $offer -Name 'payer_decision_id' -Default ''),
                (Get-FileTransferEventField -Event $offer -Name 'generation' -Default ''))).
            ToLowerInvariant()
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true
        $distinctCandidates.Add($rejection) | Out-Null

        $transaction = @($transactionAnswerEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$rejection.Sequence -and
            (Test-InitialOfferBoundaryIdentityMatch -Offer $offer -Candidate $_ -RequireCompleteCandidate)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $answerAck = @()
        $preCommit = @()
        if ($transaction.Count -eq 1) {
            $answerAck = @($answerAckSentEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$transaction[0].Sequence -and
                (Test-InitialOfferBoundaryIdentityMatch -Offer $offer -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        }
        if ($answerAck.Count -eq 1) {
            $transactionGeneration =
                Get-FileTransferEventField -Event $transaction[0] -Name 'transaction_generation' -Default ''
            $offerGeneration =
                Get-FileTransferEventField -Event $transaction[0] -Name 'offer_generation' -Default ''
            $leaseGeneration =
                Get-FileTransferEventField -Event $transaction[0] -Name 'tuna_path_lease_generation' -Default ''
            $preCommit = @($preCommitHandoffEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$answerAck[0].Sequence -and
                (Test-InitialOfferWriterMatch -Left $offer -Right $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $offer -Name 'session_id' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'transaction_generation' -Default '') -eq
                    $transactionGeneration -and
                (Get-FileTransferEventField -Event $_ -Name 'offer_generation' -Default '') -eq
                    $offerGeneration -and
                (Get-FileTransferEventField -Event $_ -Name 'tuna_path_lease_generation' -Default '') -eq
                    $leaseGeneration
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        }

        if ($transaction.Count -eq 1 -and
            $answerAck.Count -eq 1 -and
            $preCommit.Count -eq 1) {
            $recoveredCandidates.Add($rejection) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($rejection) | Out-Null
        }
    }

    # A peer-response timeout retires the wire offer while deliberately keeping
    # the InitialActivation transaction and answer window alive.  If the late
    # answer is accepted but that retained transaction remains OfferSentObserved,
    # the initiator never owns a precommit launch.  Anchor the boundary at the
    # exact pending-route-commit observation, not at the responder's intentional
    # waiting launch.
    foreach ($pendingRouteCommit in $pendingRouteCommitEvents) {
        $writer = Get-InitialOfferBoundaryField -Event $pendingRouteCommit -Names @('log_writer_id')
        $sessionId = Get-InitialOfferBoundaryField -Event $pendingRouteCommit -Names @('session_id')
        $offerGeneration = Get-InitialOfferBoundaryField -Event $pendingRouteCommit -Names @('offer_generation')
        $transactionGeneration = Get-InitialOfferBoundaryField -Event $pendingRouteCommit -Names @('transaction_generation')
        if ([string]::IsNullOrWhiteSpace($writer) -or
            [string]::IsNullOrWhiteSpace($sessionId) -or
            [string]::IsNullOrWhiteSpace($offerGeneration) -or
            [string]::IsNullOrWhiteSpace($transactionGeneration)) {
            continue
        }

        [object[]]$matchingOffers = @($initialOffers | Where-Object {
            [int64]$_.Sequence -lt [int64]$pendingRouteCommit.Sequence -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('log_writer_id')) -eq $writer -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('generation')) -eq $offerGeneration
        })
        if ($matchingOffers.Count -ne 1) {
            continue
        }
        $offer = $matchingOffers[0]
        $payerDecisionId = Get-InitialOfferBoundaryField -Event $offer -Names @('payer_decision_id')

        $retirement = @($retiredOfferEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$offer.Sequence -and
            [int64]$_.Sequence -lt [int64]$pendingRouteCommit.Sequence -and
            (Test-InitialOfferWriterMatch -Left $offer -Right $_) -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('payer_decision_id')) -eq $payerDecisionId
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        $preserved = @($pendingAnswerPreservedEvents | Where-Object {
            $retirement.Count -eq 1 -and
            [int64]$_.Sequence -gt [int64]$retirement[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$pendingRouteCommit.Sequence -and
            (Test-InitialOfferWriterMatch -Left $offer -Right $_) -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('payer_decision_id')) -eq $payerDecisionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('generation')) -eq $offerGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $rawAnswer = @($rawAnswers | Where-Object {
            $preserved.Count -eq 1 -and
            [int64]$_.Sequence -gt [int64]$preserved[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$pendingRouteCommit.Sequence -and
            (Test-InitialOfferWriterMatch -Left $offer -Right $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $acceptedBoundary = @($offerBoundaryDecisions | Where-Object {
            $rawAnswer.Count -eq 1 -and
            [int64]$_.Sequence -gt [int64]$rawAnswer[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$pendingRouteCommit.Sequence -and
            (Test-InitialOfferWriterMatch -Left $offer -Right $_) -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('boundary')) -eq 'answer_received' -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('authority_mode', 'offer_authority_mode')) -eq 'InitialActivation' -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('decision_status')).Equals(
                'accepted',
                [System.StringComparison]::OrdinalIgnoreCase) -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('payer_decision_id')) -eq $payerDecisionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('offer_generation')) -eq $offerGeneration -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('transaction_generation')) -eq $transactionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $retiredAccepted = @($retiredAnswerAcceptedEvents | Where-Object {
            $acceptedBoundary.Count -eq 1 -and
            [int64]$_.Sequence -gt [int64]$acceptedBoundary[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$pendingRouteCommit.Sequence -and
            (Test-InitialOfferWriterMatch -Left $offer -Right $_) -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('payer_decision_id')) -eq $payerDecisionId
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $answerAck = @($answerAckSentEvents | Where-Object {
            $retiredAccepted.Count -eq 1 -and
            [int64]$_.Sequence -gt [int64]$retiredAccepted[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$pendingRouteCommit.Sequence -and
            (Test-InitialOfferWriterMatch -Left $offer -Right $_) -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('payer_decision_id')) -eq $payerDecisionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('generation')) -eq $offerGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $barrier = @($answerAckBarrierEvents | Where-Object {
            $answerAck.Count -eq 1 -and
            [int64]$_.Sequence -gt [int64]$answerAck[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$pendingRouteCommit.Sequence -and
            (Test-InitialOfferWriterMatch -Left $offer -Right $_) -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('payer_decision_id')) -eq $payerDecisionId
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($retirement.Count -ne 1 -or $preserved.Count -ne 1 -or
            $rawAnswer.Count -ne 1 -or $acceptedBoundary.Count -ne 1 -or
            $retiredAccepted.Count -ne 1 -or $answerAck.Count -ne 1 -or
            $barrier.Count -ne 1) {
            continue
        }

        $rawCandidates.Add($pendingRouteCommit) | Out-Null
        $key = [string]::Join('|', @($writer, $sessionId, $payerDecisionId, $offerGeneration, $transactionGeneration)).ToLowerInvariant()
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true
        $distinctCandidates.Add($pendingRouteCommit) | Out-Null

        $transaction = @($transactionAnswerEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$pendingRouteCommit.Sequence -and
            (Test-InitialOfferWriterMatch -Left $offer -Right $_) -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('offer_generation')) -eq $offerGeneration -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('transaction_generation')) -eq $transactionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $initiatorLaunch = @($preCommitHandoffEvents | Where-Object {
            $transaction.Count -eq 1 -and
            [int64]$_.Sequence -gt [int64]$transaction[0].Sequence -and
            (Test-InitialOfferWriterMatch -Left $offer -Right $_) -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('offer_generation')) -eq $offerGeneration -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('transaction_generation')) -eq $transactionGeneration -and
            (Get-InitialOfferBoundaryField -Event $_ -Names @('responder_waiting_for_peer_probe')) -ne '1'
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($transaction.Count -eq 1 -and $initiatorLaunch.Count -eq 1) {
            $recoveredCandidates.Add($pendingRouteCommit) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($pendingRouteCommit) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) {
            'fail'
        }
        elseif ($distinctCandidates.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockInitialActivationAnswerPeerDeliveryCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$timeouts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_ack_timeout' -and
        (Get-FileTransferEventField -Event $_ -Name 'trigger' -Default '') -eq 'runtime_unlock' -and
        (Get-FileTransferEventField -Event $_ -Name 'retry_reason' -Default '') -eq
            'runtime_unlock_answer_ack_timeout'
    })
    [object[]]$pendingEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_ack_pending'
    })
    [object[]]$answerSends = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'tuna_acceleration_answer_sent',
            'tuna_acceleration_answer_replay_sent') -and
        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '1') -ne '0'
    })
    [object[]]$rawAnswerReceipts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_received_raw'
    })
    [object[]]$answerAcks = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'tuna_acceleration_answer_ack_sent',
            'tuna_acceleration_answer_ack_received_raw',
            'tuna_acceleration_answer_ack_received')
    })
    [object[]]$preCommitEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_precommit_probe_launch_requested',
            'filetransfer_runtime_unlock_precommit_probe_launch_handoff_decided',
            'runtime_unlock_precommit_probe_launch_started',
            'runtime_unlock_precommit_probe_started',
            'filetransfer_route_transition_prepared')
    })
    [object[]]$bridgeReadyEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'bridge_ready'
    })
    [object[]]$replyTargetEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_acceleration_reply_target_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'purpose' -Default '') -in @(
            'answer',
            'answer_replay') -and
        (Get-FileTransferEventField -Event $_ -Name 'status' -Default '') -eq
            'accepted'
    })

    function Get-AnswerDeliveryIdentityValue {
        param($Event, [string[]]$Names)
        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                return $value
            }
        }
        return ''
    }

    $raw = New-Object System.Collections.Generic.List[object]
    $distinct = New-Object System.Collections.Generic.List[object]
    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    $peerRecoveryReplayWindowUnresolved =
        New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($timeout in $timeouts) {
        $sessionId = Get-AnswerDeliveryIdentityValue $timeout @('session_id')
        $payerDecisionId = Get-AnswerDeliveryIdentityValue $timeout @('payer_decision_id')
        $generation = Get-AnswerDeliveryIdentityValue $timeout @('generation')
        $writer = Get-AnswerDeliveryIdentityValue $timeout @('log_writer_id')
        if ([string]::IsNullOrWhiteSpace($sessionId) -or
            [string]::IsNullOrWhiteSpace($payerDecisionId) -or
            [string]::IsNullOrWhiteSpace($generation) -or
            [string]::IsNullOrWhiteSpace($writer)) {
            continue
        }

        $pending = @($pendingEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$timeout.Sequence -and
            (Get-AnswerDeliveryIdentityValue $_ @('session_id')) -eq $sessionId -and
            (Get-AnswerDeliveryIdentityValue $_ @('payer_decision_id')) -eq $payerDecisionId -and
            (Get-AnswerDeliveryIdentityValue $_ @('generation')) -eq $generation -and
            (Get-AnswerDeliveryIdentityValue $_ @('log_writer_id')) -eq $writer
        } | Select-Object -Last 1)
        if ($pending.Count -ne 1) {
            continue
        }

        $sends = @($answerSends | Where-Object {
            [int64]$_.Sequence -gt [int64]$pending[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$timeout.Sequence -and
            (Get-AnswerDeliveryIdentityValue $_ @('payer_decision_id')) -eq $payerDecisionId -and
            (Get-AnswerDeliveryIdentityValue $_ @('log_writer_id')) -eq $writer
        })
        if ($sends.Count -eq 0) {
            continue
        }

        $raw.Add($timeout) | Out-Null
        $key = [string]::Join('|', @($writer, $sessionId, $payerDecisionId, $generation)).ToLowerInvariant()
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true
        $distinct.Add($timeout) | Out-Null

        $peerRaw = @($rawAnswerReceipts | Where-Object {
            [int64]$_.Sequence -gt [int64]$sends[0].Sequence -and
            (Get-AnswerDeliveryIdentityValue $_ @('log_writer_id')) -ne $writer
        } | Select-Object -First 1)
        $ack = @()
        $preCommit = @()
        if ($peerRaw.Count -eq 1) {
            $ack = @($answerAcks | Where-Object {
                [int64]$_.Sequence -gt [int64]$peerRaw[0].Sequence -and
                (Get-AnswerDeliveryIdentityValue $_ @('session_id')) -in @('', $sessionId)
            } | Select-Object -First 1)
        }
        if ($ack.Count -eq 1) {
            $preCommit = @($preCommitEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$ack[0].Sequence -and
                (Get-AnswerDeliveryIdentityValue $_ @('session_id')) -in @('', $sessionId)
            } | Select-Object -First 1)
        }

        if ($peerRaw.Count -eq 1 -and $ack.Count -eq 1 -and $preCommit.Count -eq 1) {
            $recovered.Add($timeout) | Out-Null
        }
        else {
            $unresolved.Add($timeout) | Out-Null
            $lastSend = @($sends | Sort-Object Sequence, LineNumber |
                Select-Object -Last 1)
            $replyTarget = @($replyTargetEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$pending[0].Sequence -and
                [int64]$_.Sequence -le [int64]$lastSend[0].Sequence -and
                (Get-AnswerDeliveryIdentityValue $_ @('log_writer_id')) -eq $writer -and
                (Get-AnswerDeliveryIdentityValue $_ @('payer_decision_id')) -eq $payerDecisionId -and
                (Get-AnswerDeliveryIdentityValue $_ @('generation')) -eq $generation
            } | Select-Object -Last 1)
            $peerReady = @($bridgeReadyEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$lastSend[0].Sequence -and
                [int64]$_.Sequence -lt [int64]$timeout.Sequence -and
                (Get-AnswerDeliveryIdentityValue $_ @('log_writer_id')) -ne $writer
            } | Select-Object -First 1)
            $postReadyReplay = @($sends | Where-Object {
                $peerReady.Count -eq 1 -and
                [int64]$_.Sequence -gt [int64]$peerReady[0].Sequence
            }).Count -gt 0
            if ($replyTarget.Count -eq 1 -and
                $peerReady.Count -eq 1 -and
                -not $postReadyReplay) {
                $peerRecoveryReplayWindowUnresolved.Add($timeout) | Out-Null
            }
        }
    }

    return [pscustomobject]@{
        RawCount = $raw.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($raw.ToArray())
        DistinctCandidateEvents = @($distinct.ToArray())
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
        PeerRecoveryReplayWindowUnresolvedCandidateEvents =
            @($peerRecoveryReplayWindowUnresolved.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockInitialOfferReceiveRecoveryHoldCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }

    function Get-InitialActivationHoldField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                return $value
            }
        }
        return ''
    }

    function Test-InitialActivationHoldWriterAndSession {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @('log_writer_id', 'session_id')) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-InitialActivationHoldWriter {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        $leftWriter =
            Get-FileTransferEventField -Event $Left -Name 'log_writer_id' -Default ''
        $rightWriter =
            Get-FileTransferEventField -Event $Right -Name 'log_writer_id' -Default ''
        return -not [string]::IsNullOrWhiteSpace($leftWriter) -and
            -not [string]::IsNullOrWhiteSpace($rightWriter) -and
            [string]::Equals(
                $leftWriter,
                $rightWriter,
                [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Test-InitialActivationOfferTuple {
        param(
            [Parameter(Mandatory = $true)]$Boundary,
            [Parameter(Mandatory = $true)]$Candidate,
            [switch]$RequireTransaction
        )

        if (-not (Test-InitialActivationHoldWriterAndSession -Left $Boundary -Right $Candidate)) {
            return $false
        }

        foreach ($mapping in @(
                [pscustomobject]@{
                    Boundary = @('payer_decision_id')
                    Candidate = @('payer_decision_id')
                    Required = $true
                },
                [pscustomobject]@{
                    Boundary = @('offer_generation', 'generation')
                    Candidate = @('offer_generation', 'generation')
                    Required = $true
                },
                [pscustomobject]@{
                    Boundary = @('transaction_generation')
                    Candidate = @('transaction_generation')
                    Required = $RequireTransaction.IsPresent
                },
                [pscustomobject]@{
                    Boundary = @('tuna_path_lease_generation')
                    Candidate = @('tuna_path_lease_generation')
                    Required = $RequireTransaction.IsPresent
                })) {
            $boundaryValue =
                Get-InitialActivationHoldField -Event $Boundary -Names $mapping.Boundary
            $candidateValue =
                Get-InitialActivationHoldField -Event $Candidate -Names $mapping.Candidate
            if (($mapping.Required -and
                    ([string]::IsNullOrWhiteSpace($boundaryValue) -or
                        [string]::IsNullOrWhiteSpace($candidateValue))) -or
                (-not [string]::IsNullOrWhiteSpace($candidateValue) -and
                    -not [string]::Equals(
                        $boundaryValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase))) {
                return $false
            }
        }

        return $true
    }

    function Test-InitialActivationRecoveryOperationMatch {
        param(
            [Parameter(Mandatory = $true)]$Operation,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($mapping in @(
                [pscustomobject]@{
                    Operation = @('receive_recovery_operation_authority_id')
                    Candidate = @(
                        'receive_recovery_operation_authority_id',
                        'recovery_operation_authority_id')
                },
                [pscustomobject]@{
                    Operation = @('receive_recovery_operation_generation')
                    Candidate = @(
                        'receive_recovery_operation_generation',
                        'recovery_operation_generation')
                },
                [pscustomobject]@{
                    Operation = @('recovery_liveness_lease_generation')
                    Candidate = @('recovery_liveness_lease_generation')
                },
                [pscustomobject]@{
                    Operation = @('closure_generation')
                    Candidate = @(
                        'closure_generation',
                        'receive_recovery_closure_generation')
                })) {
            $operationValue =
                Get-InitialActivationHoldField -Event $Operation -Names $mapping.Operation
            $candidateValue =
                Get-InitialActivationHoldField -Event $Candidate -Names $mapping.Candidate
            if ([string]::IsNullOrWhiteSpace($operationValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals(
                    $operationValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-InitialActivationRecoveryOperationIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Operation,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in @(
                'receive_recovery_operation_authority_id',
                'receive_recovery_operation_generation',
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'route_publication_generation',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'bridge_decision_generation',
                'checkpoint_request_id',
                'data_session_identity',
                'data_session_generation',
                'recovery_liveness_lease_authority_id',
                'recovery_liveness_lease_generation')) {
            $operationValue =
                Get-FileTransferEventField -Event $Operation -Name $field -Default ''
            $candidateValue =
                Get-FileTransferEventField -Event $Candidate -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($operationValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals(
                    $operationValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-InitialActivationHoldRequestMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'offer_nonce',
                'payer_decision_id',
                'offer_generation',
                'transaction_generation',
                'tuna_path_lease_generation',
                'tuna_path_lease_listener_run_id',
                'control_envelope_fingerprint')) {
            $leftValue =
                Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue =
                Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-InitialActivationRecoveryReboundMatch {
        param(
            [Parameter(Mandatory = $true)]$Boundary,
            [Parameter(Mandatory = $true)]$Rebound,
            [Parameter(Mandatory = $true)]$Proof,
            [Parameter(Mandatory = $true)]$Predecessor
        )

        if (-not (Test-InitialActivationOfferTuple `
                -Boundary $Boundary `
                -Candidate $Rebound `
                -RequireTransaction) -or
            -not (Test-InitialActivationHoldWriterAndSession -Left $Rebound -Right $Proof) -or
            -not (Test-InitialActivationRecoveryOperationMatch `
                -Operation $Proof `
                -Candidate $Rebound)) {
            return $false
        }

        foreach ($mapping in @(
                [pscustomobject]@{
                    Predecessor = @('receive_recovery_operation_authority_id')
                    Rebound = @('previous_receive_recovery_operation_authority_id')
                },
                [pscustomobject]@{
                    Predecessor = @('receive_recovery_operation_generation')
                    Rebound = @('previous_receive_recovery_operation_generation')
                })) {
            $predecessorValue =
                Get-InitialActivationHoldField -Event $Predecessor -Names $mapping.Predecessor
            $reboundValue =
                Get-InitialActivationHoldField -Event $Rebound -Names $mapping.Rebound
            if ([string]::IsNullOrWhiteSpace($predecessorValue) -or
                [string]::IsNullOrWhiteSpace($reboundValue) -or
                -not [string]::Equals(
                    $predecessorValue,
                    $reboundValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    [object[]]$terminalFailures = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_activation_offer_not_observed' -and
        (Get-FileTransferEventField -Event $_ -Name 'authority_mode' -Default '') -eq
            'InitialActivation' -and
        (Get-FileTransferEventField -Event $_ -Name 'retry_scheduled' -Default '0') -eq '0' -and
        (Get-FileTransferEventField -Event $_ -Name 'retry_after_recovery_armed' -Default '0') -eq '0' -and
        (Get-FileTransferEventField -Event $_ -Name 'pause_deferred' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'trigger' -Default '') -in @(
            'runtime_unlock_offer_send_not_observed',
            'runtime_unlock_payer_intent_send_rejected')
    })
    [object[]]$retryExhaustedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_retry_exhausted' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq
            'runtime_unlock_offer_send_not_observed'
    })
    [object[]]$offerBoundaries = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_offer_authority_boundary_decided' -and
        (Get-InitialActivationHoldField -Event $_ -Names @(
                'authority_mode',
                'offer_authority_mode')) -eq 'InitialActivation' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '').Equals(
            'accepted',
            [System.StringComparison]::OrdinalIgnoreCase) -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'transaction_generation' -Default '0') -gt 0 -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'tuna_path_lease_generation' -Default '0') -gt 0
    })
    [object[]]$recoveryDeferrals = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_activation_control_send_deferred_for_regular_v4_recovery' -and
        (Get-FileTransferEventField -Event $_ -Name 'purpose' -Default '') -eq 'offer' -and
        (Get-FileTransferEventField -Event $_ -Name 'blocker_reason' -Default '') -eq
            'receive_stall_recovery_awaiting_receive_proof'
    })
    [object[]]$retainedClosures = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_receive_recovery_operation_closure_retained' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'execution_state' -Default '') -eq
            'Completed' -and
        (Get-FileTransferEventField -Event $_ -Name 'execution_outcome' -Default '') -eq
            'Completed' -and
        (Get-FileTransferEventField -Event $_ -Name 'closure_state' -Default '') -eq 'Retained' -and
        (Get-InitialActivationHoldField -Event $_ -Names @('proof_identity')) -eq ''
    })
    [object[]]$recoveryOperationsIssued = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_receive_recovery_operation_issued' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'execution_state' -Default '') -eq 'Issued'
    })
    [object[]]$recoveryExecutionReceipts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_receive_recovery_operation_execution_receipt_applied' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'execution_state' -Default '') -eq
            'Completed' -and
        (Get-FileTransferEventField -Event $_ -Name 'execution_outcome' -Default '') -eq
            'Completed' -and
        (Get-InitialActivationHoldField -Event $_ -Names @('proof_identity')) -eq ''
    })
    [object[]]$holdDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_initial_activation_receive_recovery_hold_decided'
    })
    [object[]]$holdRebounds = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_initial_activation_receive_recovery_hold_rebound'
    })
    [object[]]$holdResumed = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_initial_activation_receive_recovery_hold_resumed'
    })
    [object[]]$proofAdoptions = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'filetransfer_receive_recovery_operation_proof_observed',
            'filetransfer_receive_recovery_operation_closure_adopted') -and
        (Get-FileTransferEventField -Event $_ -Name 'closure_state' -Default '') -eq 'Adopted'
    })
    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $correlatedDiagnosticSequences = New-Object System.Collections.Generic.List[int64]
    $seen = @{}

    foreach ($terminalFailure in $terminalFailures) {
        $boundary = @($offerBoundaries | Where-Object {
            [int64]$_.Sequence -lt [int64]$terminalFailure.Sequence -and
            (Test-InitialActivationOfferTuple -Boundary $_ -Candidate $terminalFailure)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($boundary.Count -ne 1) {
            continue
        }

        $competingBoundaries = @($offerBoundaries | Where-Object {
            [int64]$_.Sequence -gt [int64]$boundary[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$terminalFailure.Sequence -and
            (Test-InitialActivationHoldWriter -Left $boundary[0] -Right $_) -and
            -not (
                (Test-InitialActivationHoldWriterAndSession -Left $boundary[0] -Right $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $boundary[0] -Name 'transfer_id' -Default '') -and
                (Get-FileTransferEventField -Event $_ -Name 'transaction_generation' -Default '') -eq
                    (Get-FileTransferEventField -Event $boundary[0] -Name 'transaction_generation' -Default '')
            )
        })
        if ($competingBoundaries.Count -gt 0) {
            continue
        }

        $retryExhausted = @($retryExhaustedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$boundary[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$terminalFailure.Sequence -and
            (Test-InitialActivationHoldWriter -Left $boundary[0] -Right $_)
        } | Sort-Object Sequence, LineNumber)
        if ($retryExhausted.Count -ne 1) {
            continue
        }

        [object[]]$candidateClosures = @($retainedClosures | Where-Object {
            [int64]$_.Sequence -lt [int64]$terminalFailure.Sequence -and
            (Test-InitialActivationHoldWriterAndSession -Left $boundary[0] -Right $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq
                (Get-FileTransferEventField -Event $boundary[0] -Name 'transfer_id' -Default '')
        } | Sort-Object Sequence, LineNumber -Descending)
        $retainedClosure = @()
        [object[]]$matchingDeferrals = @()
        foreach ($candidateClosure in $candidateClosures) {
            [object[]]$candidateDeferrals = @($recoveryDeferrals | Where-Object {
                $deferral = $_
                if ([int64]$deferral.Sequence -le [int64]$candidateClosure.Sequence -or
                    [int64]$deferral.Sequence -ge [int64]$terminalFailure.Sequence -or
                    -not (Test-InitialActivationHoldWriterAndSession `
                        -Left $boundary[0] `
                        -Right $deferral)) {
                    return $false
                }

                $latestClosure = @($retainedClosures | Where-Object {
                    [int64]$_.Sequence -lt [int64]$deferral.Sequence -and
                    (Test-InitialActivationHoldWriterAndSession `
                        -Left $boundary[0] `
                        -Right $_)
                } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
                return $latestClosure.Count -eq 1 -and
                    (Test-InitialActivationRecoveryOperationIdentityMatch `
                        -Operation $candidateClosure `
                        -Candidate $latestClosure[0])
            } | Sort-Object Sequence, LineNumber)
            if ($candidateDeferrals.Count -ge 2) {
                $retainedClosure = @($candidateClosure)
                $matchingDeferrals = $candidateDeferrals
                break
            }
        }
        if ($retainedClosure.Count -ne 1 -or $matchingDeferrals.Count -lt 2) {
            continue
        }

        $operationIssued = @($recoveryOperationsIssued | Where-Object {
            [int64]$_.Sequence -lt [int64]$retainedClosure[0].Sequence -and
            (Test-InitialActivationRecoveryOperationIdentityMatch `
                -Operation $retainedClosure[0] `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($operationIssued.Count -ne 1) {
            continue
        }
        $executionReceipt = @($recoveryExecutionReceipts | Where-Object {
            [int64]$_.Sequence -gt [int64]$operationIssued[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$retainedClosure[0].Sequence -and
            (Test-InitialActivationRecoveryOperationIdentityMatch `
                -Operation $retainedClosure[0] `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($executionReceipt.Count -ne 1) {
            continue
        }

        $transactionGeneration =
            Get-FileTransferEventField `
                -Event $boundary[0] `
                -Name 'transaction_generation' `
                -Default ''
        $sameLineageBoundaries = @($offerBoundaries | Where-Object {
            [int64]$_.Sequence -gt [int64]$retainedClosure[0].Sequence -and
            [int64]$_.Sequence -le [int64]$terminalFailure.Sequence -and
            (Test-InitialActivationHoldWriterAndSession -Left $boundary[0] -Right $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq
                (Get-FileTransferEventField -Event $boundary[0] -Name 'transfer_id' -Default '') -and
            (Get-FileTransferEventField -Event $_ -Name 'transaction_generation' -Default '') -eq
                $transactionGeneration
        })
        if ($sameLineageBoundaries.Count -lt 2) {
            continue
        }

        $rawCandidates.Add($terminalFailure) | Out-Null
        foreach ($diagnostic in @($matchingDeferrals + $retryExhausted)) {
            $correlatedDiagnosticSequences.Add([int64]$diagnostic.Sequence) | Out-Null
        }

        $key = [string]::Join('|', @(
                (Get-FileTransferEventField -Event $boundary[0] -Name 'log_writer_id' -Default ''),
                (Get-FileTransferEventField -Event $boundary[0] -Name 'session_id' -Default ''),
                (Get-FileTransferEventField -Event $boundary[0] -Name 'transfer_id' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'direction' -Default ''),
                (Get-FileTransferEventField -Event $boundary[0] -Name 'transaction_generation' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'route' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'protocol_version' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'live_route_epoch' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'route_publication_generation' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'runtime_generation' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'terminal_generation' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'leg_generation' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'transport_epoch' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'bridge_recovery_generation' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'bridge_decision_generation' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'receive_recovery_operation_authority_id' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'receive_recovery_operation_generation' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'recovery_liveness_lease_authority_id' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'recovery_liveness_lease_generation' -Default ''),
                (Get-FileTransferEventField -Event $retainedClosure[0] -Name 'closure_generation' -Default ''))).
            ToLowerInvariant()
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true
        $distinctCandidates.Add($terminalFailure) | Out-Null

        [object[]]$heldCandidates = @($holdDecisions | Where-Object {
            [int64]$_.Sequence -gt [int64]$retainedClosure[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$terminalFailure.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '').Equals(
                'Held',
                [System.StringComparison]::OrdinalIgnoreCase) -and
            (Test-InitialActivationOfferTuple `
                -Boundary $boundary[0] `
                -Candidate $_ `
                -RequireTransaction) -and
            (Test-InitialActivationRecoveryOperationMatch `
                -Operation $retainedClosure[0] `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber)

        $recovered = $false
        foreach ($held in $heldCandidates) {
            [object[]]$adoptionCandidates = @($proofAdoptions | Where-Object {
                $proofEvent = $_
                [int64]$_.Sequence -gt [int64]$held.Sequence -and
                [int64]$_.Sequence -lt [int64]$terminalFailure.Sequence -and
                (Test-InitialActivationHoldWriterAndSession -Left $boundary[0] -Right $_) -and
                (
                    (Test-InitialActivationRecoveryOperationMatch `
                        -Operation $retainedClosure[0] `
                        -Candidate $_) -or
                    @($holdRebounds | Where-Object {
                        [int64]$_.Sequence -gt [int64]$held.Sequence -and
                        [int64]$_.Sequence -lt [int64]$proofEvent.Sequence -and
                        (Test-InitialActivationRecoveryReboundMatch `
                            -Boundary $boundary[0] `
                            -Rebound $_ `
                            -Proof $proofEvent `
                            -Predecessor $retainedClosure[0])
                    }).Count -gt 0
                )
            } | Sort-Object Sequence, LineNumber)
            foreach ($adopted in $adoptionCandidates) {
                $released = @(
                    @($holdDecisions + $holdResumed) | Where-Object {
                        [int64]$_.Sequence -gt [int64]$adopted.Sequence -and
                        [int64]$_.Sequence -lt [int64]$terminalFailure.Sequence -and
                        (
                            $_.EventName -eq
                                'runtime_unlock_initial_activation_receive_recovery_hold_resumed' -or
                            (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '').
                                Equals(
                                    'Released',
                                    [System.StringComparison]::OrdinalIgnoreCase)
                        ) -and
                        (Test-InitialActivationHoldRequestMatch `
                            -Left $held `
                            -Right $_) -and
                        (Test-InitialActivationRecoveryOperationMatch `
                            -Operation $adopted `
                            -Candidate $_)
                    } | Sort-Object Sequence, LineNumber | Select-Object -First 1
                )
                if ($released.Count -eq 1) {
                    $recovered = $true
                    break
                }
            }
            if ($recovered) {
                break
            }
        }

        if ($recovered) {
            $recoveredCandidates.Add($terminalFailure) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($terminalFailure) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) {
            'fail'
        }
        elseif ($distinctCandidates.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        CorrelatedDiagnosticSequences = @($correlatedDiagnosticSequences.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockInitialActivationReceiveRecoveryHoldReleaseDeliveryCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$events = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }

    function Get-HoldReleaseField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = ''
        )

        foreach ($name in $Names) {
            $value =
                Get-FileTransferEventField `
                    -Event $Event `
                    -Name $name `
                    -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                return $value
            }
        }
        return $Default
    }

    function Test-HoldReleaseTuple {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [switch]$RequireOperation,
            [switch]$AllowMissingRightFields
        )

        [object[]]$mappings = @(
            [pscustomobject]@{ Left = @('log_writer_id'); Right = @('log_writer_id') },
            [pscustomobject]@{ Left = @('session_id'); Right = @('session_id') },
            [pscustomobject]@{ Left = @('transfer_id'); Right = @('transfer_id') },
            [pscustomobject]@{ Left = @('direction'); Right = @('direction') },
            [pscustomobject]@{ Left = @('offer_nonce'); Right = @('offer_nonce') },
            [pscustomobject]@{ Left = @('payer_decision_id'); Right = @('payer_decision_id') },
            [pscustomobject]@{ Left = @('offer_generation', 'generation'); Right = @('offer_generation', 'generation') },
            [pscustomobject]@{ Left = @('transaction_generation'); Right = @('transaction_generation') },
            [pscustomobject]@{ Left = @('tuna_path_lease_generation'); Right = @('tuna_path_lease_generation') },
            [pscustomobject]@{ Left = @('tuna_path_lease_listener_run_id'); Right = @('tuna_path_lease_listener_run_id') },
            [pscustomobject]@{ Left = @('control_envelope_fingerprint'); Right = @('control_envelope_fingerprint') },
            [pscustomobject]@{ Left = @('hold_generation'); Right = @('hold_generation') }
        )
        if ($RequireOperation) {
            $mappings += @(
                [pscustomobject]@{
                    Left = @(
                        'receive_recovery_operation_generation',
                        'recovery_operation_generation')
                    Right = @(
                        'receive_recovery_operation_generation',
                        'recovery_operation_generation')
                },
                [pscustomobject]@{
                    Left = @(
                        'receive_recovery_closure_generation',
                        'closure_generation')
                    Right = @(
                        'receive_recovery_closure_generation',
                        'closure_generation')
                })
        }

        foreach ($mapping in $mappings) {
            $leftValue =
                Get-HoldReleaseField -Event $Left -Names $mapping.Left
            $rightValue =
                Get-HoldReleaseField -Event $Right -Names $mapping.Right
            if ($AllowMissingRightFields -and
                [string]::IsNullOrWhiteSpace($rightValue)) {
                continue
            }
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-HoldReleaseOperationMatch {
        param(
            [Parameter(Mandatory = $true)]$Operation,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($mapping in @(
                [pscustomobject]@{
                    Operation = @(
                        'receive_recovery_operation_generation',
                        'recovery_operation_generation')
                    Candidate = @(
                        'receive_recovery_operation_generation',
                        'recovery_operation_generation')
                },
                [pscustomobject]@{
                    Operation = @('closure_generation')
                    Candidate = @(
                        'receive_recovery_closure_generation',
                        'closure_generation')
                },
                [pscustomobject]@{
                    Operation = @('recovery_liveness_lease_generation')
                    Candidate = @('recovery_liveness_lease_generation')
                })) {
            $operationValue =
                Get-HoldReleaseField `
                    -Event $Operation `
                    -Names $mapping.Operation
            $candidateValue =
                Get-HoldReleaseField `
                    -Event $Candidate `
                    -Names $mapping.Candidate
            if ([string]::IsNullOrWhiteSpace($operationValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                $operationValue -ne $candidateValue) {
                return $false
            }
        }

        $operationAuthority =
            Get-HoldReleaseField `
                -Event $Operation `
                -Names @(
                    'receive_recovery_operation_authority_id',
                    'recovery_operation_authority_id')
        $candidateAuthority =
            Get-HoldReleaseField `
                -Event $Candidate `
                -Names @(
                    'receive_recovery_operation_authority_id',
                    'recovery_operation_authority_id')
        $operationAuthorityVisible =
            -not [string]::IsNullOrWhiteSpace($operationAuthority) -and
            $operationAuthority -notmatch 'redacted|missing|none'
        $candidateAuthorityVisible =
            -not [string]::IsNullOrWhiteSpace($candidateAuthority) -and
            $candidateAuthority -notmatch 'redacted|missing|none'
        return -not ($operationAuthorityVisible -and
                $candidateAuthorityVisible) -or
            [string]::Equals(
                $operationAuthority,
                $candidateAuthority,
            [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Test-HoldReleaseSemanticTuple {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($mapping in @(
                [pscustomobject]@{ Left = @('log_writer_id'); Right = @('log_writer_id') },
                [pscustomobject]@{ Left = @('session_id'); Right = @('session_id') },
                [pscustomobject]@{ Left = @('transfer_id'); Right = @('transfer_id') },
                [pscustomobject]@{ Left = @('direction'); Right = @('direction') },
                [pscustomobject]@{ Left = @('offer_nonce'); Right = @('offer_nonce') },
                [pscustomobject]@{ Left = @('payer_decision_id'); Right = @('payer_decision_id') },
                [pscustomobject]@{ Left = @('offer_generation'); Right = @('offer_generation') },
                [pscustomobject]@{ Left = @('transaction_generation'); Right = @('transaction_generation') },
                [pscustomobject]@{ Left = @('tuna_path_lease_generation'); Right = @('tuna_path_lease_generation') },
                [pscustomobject]@{ Left = @('tuna_path_lease_listener_run_id'); Right = @('tuna_path_lease_listener_run_id') },
                [pscustomobject]@{ Left = @('semantic_offer_fingerprint'); Right = @('semantic_offer_fingerprint') },
                [pscustomobject]@{ Left = @('source_route', 'expected_route', 'route'); Right = @('source_route', 'expected_route', 'route') },
                [pscustomobject]@{ Left = @('source_runtime_generation', 'expected_runtime_generation', 'runtime_generation'); Right = @('source_runtime_generation', 'expected_runtime_generation', 'runtime_generation') },
                [pscustomobject]@{ Left = @('source_terminal_generation', 'expected_terminal_generation', 'terminal_generation'); Right = @('source_terminal_generation', 'expected_terminal_generation', 'terminal_generation') },
                [pscustomobject]@{ Left = @('source_leg_generation', 'expected_leg_generation', 'leg_generation'); Right = @('source_leg_generation', 'expected_leg_generation', 'leg_generation') },
                [pscustomobject]@{ Left = @('source_route_publication_generation', 'expected_route_publication_generation', 'route_publication_generation'); Right = @('source_route_publication_generation', 'expected_route_publication_generation', 'route_publication_generation') },
                [pscustomobject]@{ Left = @('source_transport_epoch', 'expected_transport_epoch', 'transport_epoch'); Right = @('source_transport_epoch', 'expected_transport_epoch', 'transport_epoch') },
                [pscustomobject]@{ Left = @('source_bridge_recovery_generation', 'expected_bridge_recovery_generation', 'bridge_recovery_generation'); Right = @('source_bridge_recovery_generation', 'expected_bridge_recovery_generation', 'bridge_recovery_generation') },
                [pscustomobject]@{ Left = @('data_session_identity', 'expected_data_session_identity'); Right = @('data_session_identity', 'expected_data_session_identity') },
                [pscustomobject]@{ Left = @('data_session_generation', 'expected_data_session_generation'); Right = @('data_session_generation', 'expected_data_session_generation') })) {
            $leftValue = Get-HoldReleaseField -Event $Left -Names $mapping.Left
            $rightValue = Get-HoldReleaseField -Event $Right -Names $mapping.Right
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue)) {
                continue
            }
            if (-not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    [object[]]$rejections = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_invalidation_rejected' -and
        (Get-HoldReleaseField -Event $_ -Names @('decision_status')) -eq
            'Released' -and
        (Get-HoldReleaseField -Event $_ -Names @('decision_reason')) -eq
            'exact_coordinator_invalidation_required'
    })
    [object[]]$misroutedReleases = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_invalidated' -and
        (Get-HoldReleaseField -Event $_ -Names @('decision_status')) -eq
            'Released'
    })
    [object[]]$heldDecisions = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_decided' -and
        (Get-HoldReleaseField -Event $_ -Names @('decision_status')) -eq
            'Held'
    })
    [object[]]$adoptions = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_operation_closure_adopted' -and
        (Get-HoldReleaseField -Event $_ -Names @('closure_state')) -eq
            'Adopted'
    })
    [object[]]$normalReleaseEvents = @($events | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_initial_activation_receive_recovery_hold_decided',
            'runtime_unlock_initial_activation_receive_recovery_hold_directive_delivery_decided') -and
        (Get-HoldReleaseField -Event $_ -Names @('decision_status')) -eq
            'Released'
    })
    [object[]]$resumeEvents = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_resumed'
    })
    [object[]]$refreshIssued = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_offer_envelope_refresh_issued'
    })
    [object[]]$refreshPrepared = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_offer_envelope_refresh_prepared'
    })
    [object[]]$refreshCommitted = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_offer_envelope_refresh_committed' -and
        (Get-HoldReleaseField -Event $_ -Names @('decision_status')) -in
            @('Accepted', 'Idempotent', 'accepted', 'idempotent') -and
        -not [string]::IsNullOrWhiteSpace(
            (Get-HoldReleaseField -Event $_ -Names @('offer_nonce')))
    })
    [object[]]$rejectedRefreshPrevalidations = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_send_prevalidated' -and
        (Get-HoldReleaseField -Event $_ -Names @('prevalidation_status')) -eq
            'rejected' -and
        (Get-HoldReleaseField -Event $_ -Names @('decision_status')) -eq
            'Released' -and
        (Get-HoldReleaseField -Event $_ -Names @('same_generation_resume')) -eq
            '1'
    })
    [object[]]$acceptedControlEntries = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_offer_authority_boundary_decided' -and
        (Get-HoldReleaseField -Event $_ -Names @('boundary')) -eq
            'control_send_entry' -and
        (Get-HoldReleaseField -Event $_ -Names @('decision_status')) -eq
            'accepted'
    })
    [object[]]$postPrevalidationSubmissions = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_post_prevalidation_submission'
    })
    [object[]]$rawPeerOffers = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_offer_received_raw'
    })
    [object[]]$transactionAnswers = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_transaction_answer_received'
    })
    [object[]]$answerAcks = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_ack_sent'
    })
    [object[]]$precommitOrPrepared = @($events | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_precommit_admission_granted',
            'runtime_unlock_route_commit_precommit_admission_granted',
            'filetransfer_route_transition_prepared')
    })

    $raw = New-Object System.Collections.Generic.List[object]
    $distinct = [ordered]@{}
    foreach ($rejection in $rejections) {
        [object[]]$misrouted = @($misroutedReleases | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Test-HoldReleaseTuple `
                -Left $_ `
                -Right $rejection `
                -AllowMissingRightFields)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($misrouted.Count -ne 1) {
            continue
        }

        [object[]]$matchingAdoptions = @($adoptions | Where-Object {
            [int64]$_.Sequence -lt [int64]$misrouted[0].Sequence -and
            (Get-HoldReleaseField -Event $_ -Names @('log_writer_id')) -eq
                (Get-HoldReleaseField -Event $rejection -Names @('log_writer_id')) -and
            (Get-HoldReleaseField -Event $_ -Names @('session_id')) -eq
                (Get-HoldReleaseField -Event $rejection -Names @('session_id')) -and
            (Get-HoldReleaseField -Event $_ -Names @('transfer_id')) -eq
                (Get-HoldReleaseField -Event $rejection -Names @('transfer_id')) -and
            (Get-HoldReleaseField -Event $_ -Names @('direction')) -eq
                (Get-HoldReleaseField -Event $rejection -Names @('direction')) -and
            (Test-HoldReleaseOperationMatch `
                -Operation $_ `
                -Candidate $misrouted[0])
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($matchingAdoptions.Count -ne 1) {
            continue
        }

        [object[]]$matchingHolds = @($heldDecisions | Where-Object {
            [int64]$_.Sequence -lt [int64]$matchingAdoptions[0].Sequence -and
            (Test-HoldReleaseTuple `
                -Left $_ `
                -Right $rejection `
                -AllowMissingRightFields)
        } | Sort-Object Sequence, LineNumber)
        if ($matchingHolds.Count -eq 0) {
            continue
        }

        $raw.Add($rejection) | Out-Null
        $key = (@(
            Get-HoldReleaseField -Event $rejection -Names @('log_writer_id')
            Get-HoldReleaseField -Event $rejection -Names @('session_id')
            Get-HoldReleaseField -Event $rejection -Names @('transfer_id')
            Get-HoldReleaseField -Event $rejection -Names @('direction')
            Get-HoldReleaseField -Event $rejection -Names @('offer_nonce')
            Get-HoldReleaseField -Event $rejection -Names @('payer_decision_id')
            Get-HoldReleaseField -Event $rejection -Names @('offer_generation')
            Get-HoldReleaseField -Event $rejection -Names @('transaction_generation')
            Get-HoldReleaseField -Event $rejection -Names @('tuna_path_lease_generation')
            Get-HoldReleaseField -Event $misrouted[0] -Names @('hold_generation')
            Get-HoldReleaseField -Event $misrouted[0] -Names @('receive_recovery_operation_generation')
            Get-HoldReleaseField -Event $misrouted[0] -Names @('closure_generation')
        ) | ForEach-Object { ([string]$_).ToLowerInvariant() }) -join '|'
        if (-not $distinct.Contains($key)) {
            $distinct[$key] = [pscustomobject]@{
                Event = $rejection
                Misrouted = $misrouted[0]
                Adoption = $matchingAdoptions[0]
                Variant = 'invalidation'
                Refresh = $null
            }
        }
    }

    foreach ($prevalidation in $rejectedRefreshPrevalidations) {
        $candidateSequence = [int64]$prevalidation.Sequence
        [object[]]$commits = @($refreshCommitted | Where-Object {
            [int64]$_.Sequence -lt $candidateSequence -and
            (Test-HoldReleaseSemanticTuple -Left $_ -Right $prevalidation)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($commits.Count -ne 1) {
            continue
        }
        $commit = $commits[0]
        $refreshGeneration =
            Get-HoldReleaseField -Event $commit -Names @('refresh_generation')
        $successorEnvelopeGeneration =
            Get-HoldReleaseField `
                -Event $commit `
                -Names @('successor_envelope_generation')
        $successorFingerprint =
            Get-HoldReleaseField `
                -Event $commit `
                -Names @('successor_envelope_fingerprint')
        $successorMessageId =
            Get-HoldReleaseField -Event $commit -Names @('message_id')
        if ([string]::IsNullOrWhiteSpace($refreshGeneration) -or
            [string]::IsNullOrWhiteSpace($successorEnvelopeGeneration) -or
            [string]::IsNullOrWhiteSpace($successorFingerprint) -or
            [string]::IsNullOrWhiteSpace($successorMessageId)) {
            continue
        }

        [object[]]$prepared = @($refreshPrepared | Where-Object {
            [int64]$_.Sequence -lt [int64]$commit.Sequence -and
            (Test-HoldReleaseSemanticTuple -Left $_ -Right $commit) -and
            (Get-HoldReleaseField -Event $_ -Names @('refresh_generation')) -eq
                $refreshGeneration -and
            (Get-HoldReleaseField -Event $_ -Names @('successor_envelope_generation')) -eq
                $successorEnvelopeGeneration -and
            (Get-HoldReleaseField -Event $_ -Names @('successor_envelope_fingerprint')) -eq
                $successorFingerprint -and
            (Get-HoldReleaseField -Event $_ -Names @('message_id')) -eq
                $successorMessageId
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        [object[]]$issued = @($refreshIssued | Where-Object {
            $prepared.Count -eq 1 -and
            [int64]$_.Sequence -lt [int64]$prepared[0].Sequence -and
            (Test-HoldReleaseSemanticTuple -Left $_ -Right $commit) -and
            (Get-HoldReleaseField -Event $_ -Names @('refresh_generation')) -eq
                $refreshGeneration -and
            (Get-HoldReleaseField -Event $_ -Names @('successor_envelope_generation')) -eq
                $successorEnvelopeGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($prepared.Count -ne 1 -or $issued.Count -ne 1) {
            continue
        }

        [object[]]$releases = @($normalReleaseEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$commit.Sequence -and
            [int64]$_.Sequence -lt $candidateSequence -and
            (Test-HoldReleaseSemanticTuple -Left $_ -Right $prevalidation) -and
            (Get-HoldReleaseField -Event $_ -Names @('refresh_generation')) -eq
                $refreshGeneration -and
            (Get-HoldReleaseField -Event $_ -Names @('successor_envelope_generation')) -eq
                $successorEnvelopeGeneration
        } | Sort-Object Sequence, LineNumber)
        if ($releases.Count -eq 0) {
            continue
        }
        $release = $releases[-1]
        [object[]]$matchingHolds = @($heldDecisions | Where-Object {
            [int64]$_.Sequence -lt [int64]$issued[0].Sequence -and
            (Test-HoldReleaseSemanticTuple -Left $_ -Right $prevalidation)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        [object[]]$matchingAdoptions = @($adoptions | Where-Object {
            [int64]$_.Sequence -lt [int64]$issued[0].Sequence -and
            (Get-HoldReleaseField -Event $_ -Names @('log_writer_id')) -eq
                (Get-HoldReleaseField -Event $prevalidation -Names @('log_writer_id')) -and
            (Get-HoldReleaseField -Event $_ -Names @('session_id')) -eq
                (Get-HoldReleaseField -Event $prevalidation -Names @('session_id')) -and
            (Get-HoldReleaseField -Event $_ -Names @('transfer_id')) -eq
                (Get-HoldReleaseField -Event $prevalidation -Names @('transfer_id')) -and
            (Get-HoldReleaseField -Event $_ -Names @('direction')) -eq
                (Get-HoldReleaseField -Event $prevalidation -Names @('direction')) -and
            (Test-HoldReleaseOperationMatch -Operation $_ -Candidate $release)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        [object[]]$controlEntries = @($acceptedControlEntries | Where-Object {
            [int64]$_.Sequence -gt [int64]$release.Sequence -and
            [int64]$_.Sequence -lt $candidateSequence -and
            (Get-HoldReleaseField -Event $_ -Names @('log_writer_id')) -eq
                (Get-HoldReleaseField -Event $prevalidation -Names @('log_writer_id')) -and
            (Get-HoldReleaseField -Event $_ -Names @('session_id')) -eq
                (Get-HoldReleaseField -Event $prevalidation -Names @('session_id')) -and
            (Get-HoldReleaseField -Event $_ -Names @('transfer_id')) -eq
                (Get-HoldReleaseField -Event $prevalidation -Names @('transfer_id')) -and
            (Get-HoldReleaseField -Event $_ -Names @('offer_generation')) -eq
                (Get-HoldReleaseField -Event $prevalidation -Names @('offer_generation'))
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($matchingHolds.Count -ne 1 -or
            $matchingAdoptions.Count -ne 1 -or
            $controlEntries.Count -ne 1) {
            continue
        }

        $raw.Add($prevalidation) | Out-Null
        $key = (@(
            Get-HoldReleaseField -Event $prevalidation -Names @('log_writer_id')
            Get-HoldReleaseField -Event $prevalidation -Names @('session_id')
            Get-HoldReleaseField -Event $prevalidation -Names @('transfer_id')
            Get-HoldReleaseField -Event $prevalidation -Names @('direction')
            Get-HoldReleaseField -Event $prevalidation -Names @('offer_nonce')
            Get-HoldReleaseField -Event $prevalidation -Names @('payer_decision_id')
            Get-HoldReleaseField -Event $prevalidation -Names @('offer_generation')
            Get-HoldReleaseField -Event $prevalidation -Names @('transaction_generation')
            Get-HoldReleaseField -Event $prevalidation -Names @('tuna_path_lease_generation')
            Get-HoldReleaseField -Event $prevalidation -Names @('semantic_offer_fingerprint')
            $refreshGeneration
        ) | ForEach-Object { ([string]$_).ToLowerInvariant() }) -join '|'
        if (-not $distinct.Contains($key)) {
            $distinct[$key] = [pscustomobject]@{
                Event = $prevalidation
                Misrouted = $release
                Adoption = $matchingAdoptions[0]
                Variant = 'committed_refresh'
                Refresh = $commit
            }
        }
    }

    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    foreach ($record in @($distinct.Values)) {
        if ($record.Variant -eq 'committed_refresh') {
            $eventSequence = [int64]$record.Event.Sequence
            $refreshGeneration =
                Get-HoldReleaseField `
                    -Event $record.Refresh `
                    -Names @('refresh_generation')
            $successorGeneration =
                Get-HoldReleaseField `
                    -Event $record.Refresh `
                    -Names @('successor_envelope_generation')
            $successorFingerprint =
                Get-HoldReleaseField `
                    -Event $record.Refresh `
                    -Names @('successor_envelope_fingerprint')
            $messageId =
                Get-HoldReleaseField `
                    -Event $record.Refresh `
                    -Names @('message_id')
            [object[]]$acceptedPrevalidation = @($events | Where-Object {
                [int64]$_.Sequence -gt $eventSequence -and
                $_.EventName -eq
                    'runtime_unlock_initial_activation_receive_recovery_hold_send_prevalidated' -and
                (Get-HoldReleaseField -Event $_ -Names @('prevalidation_status')) -eq
                    'accepted' -and
                (Get-HoldReleaseField -Event $_ -Names @('boundary_match_mode')) -eq
                    'committed_refresh_successor' -and
                (Get-HoldReleaseField -Event $_ -Names @('refresh_generation')) -eq
                    $refreshGeneration -and
                (Get-HoldReleaseField -Event $_ -Names @('effective_envelope_generation')) -eq
                    $successorGeneration -and
                (Get-HoldReleaseField -Event $_ -Names @('effective_envelope_fingerprint')) -eq
                    $successorFingerprint -and
                (Test-HoldReleaseSemanticTuple -Left $_ -Right $record.Event)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            [object[]]$submission = @($postPrevalidationSubmissions | Where-Object {
                $acceptedPrevalidation.Count -eq 1 -and
                [int64]$_.Sequence -gt [int64]$acceptedPrevalidation[0].Sequence -and
                (Get-HoldReleaseField -Event $_ -Names @('refresh_generation')) -eq
                    $refreshGeneration -and
                (Get-HoldReleaseField -Event $_ -Names @('envelope_generation')) -eq
                    $successorGeneration -and
                (Get-HoldReleaseField -Event $_ -Names @('control_envelope_fingerprint')) -eq
                    $successorFingerprint -and
                (Get-HoldReleaseField -Event $_ -Names @('message_id')) -eq
                    $messageId -and
                (Test-HoldReleaseSemanticTuple -Left $_ -Right $record.Event)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            [object[]]$peerReceipt = @($rawPeerOffers | Where-Object {
                $submission.Count -eq 1 -and
                [int64]$_.Sequence -gt [int64]$submission[0].Sequence -and
                (Get-HoldReleaseField -Event $_ -Names @('message_id', 'msg_id')) -eq
                    $messageId
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            [object[]]$answer = @($transactionAnswers | Where-Object {
                $peerReceipt.Count -eq 1 -and
                [int64]$_.Sequence -gt [int64]$peerReceipt[0].Sequence -and
                (Get-HoldReleaseField -Event $_ -Names @('session_id')) -eq
                    (Get-HoldReleaseField -Event $record.Event -Names @('session_id')) -and
                (Get-HoldReleaseField -Event $_ -Names @('transfer_id')) -eq
                    (Get-HoldReleaseField -Event $record.Event -Names @('transfer_id')) -and
                (Get-HoldReleaseField -Event $_ -Names @('offer_generation')) -eq
                    (Get-HoldReleaseField -Event $record.Event -Names @('offer_generation'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            [object[]]$ack = @($answerAcks | Where-Object {
                $answer.Count -eq 1 -and
                [int64]$_.Sequence -gt [int64]$answer[0].Sequence -and
                (Get-HoldReleaseField -Event $_ -Names @('log_writer_id')) -eq
                    (Get-HoldReleaseField -Event $record.Event -Names @('log_writer_id'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            [object[]]$precommit = @($precommitOrPrepared | Where-Object {
                $ack.Count -eq 1 -and
                [int64]$_.Sequence -gt [int64]$ack[0].Sequence -and
                (Get-HoldReleaseField -Event $_ -Names @('session_id')) -eq
                    (Get-HoldReleaseField -Event $record.Event -Names @('session_id')) -and
                (Get-HoldReleaseField -Event $_ -Names @('transfer_id')) -eq
                    (Get-HoldReleaseField -Event $record.Event -Names @('transfer_id')) -and
                (Get-HoldReleaseField -Event $_ -Names @('direction')) -eq
                    (Get-HoldReleaseField -Event $record.Event -Names @('direction'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($acceptedPrevalidation.Count -eq 1 -and
                $submission.Count -eq 1 -and
                $peerReceipt.Count -eq 1 -and
                $answer.Count -eq 1 -and
                $ack.Count -eq 1 -and
                $precommit.Count -eq 1) {
                $recovered.Add($record.Event) | Out-Null
            }
            else {
                $unresolved.Add($record.Event) | Out-Null
            }
            continue
        }

        [object[]]$normalRelease = @($normalReleaseEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$record.Event.Sequence -and
            (Test-HoldReleaseTuple `
                -Left $record.Misrouted `
                -Right $_ `
                -RequireOperation)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $resumed = $false
        if ($normalRelease.Count -eq 1) {
            $resumed = @($resumeEvents | Where-Object {
                [int64]$_.Sequence -ge [int64]$normalRelease[0].Sequence -and
                (Test-HoldReleaseTuple `
                    -Left $record.Misrouted `
                    -Right $_ `
                    -RequireOperation)
            }).Count -gt 0
        }

        if ($resumed) {
            $recovered.Add($record.Event) | Out-Null
        }
        else {
            $unresolved.Add($record.Event) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $raw.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) {
            'fail'
        }
        elseif ($distinct.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($raw.ToArray())
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockInitialActivationReceiveRecoveryHoldReleasedPathLeaseExpiredCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$events = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }

    function Get-PathLeaseExpiryField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = ''
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                return $value
            }
        }
        return $Default
    }

    function Test-PathLeaseExpiryTuple {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [switch]$AllowMissingRight
        )

        foreach ($mapping in @(
                [pscustomobject]@{ Left = @('log_writer_id'); Right = @('log_writer_id') },
                [pscustomobject]@{ Left = @('session_id'); Right = @('session_id') },
                [pscustomobject]@{ Left = @('transfer_id'); Right = @('transfer_id') },
                [pscustomobject]@{ Left = @('direction'); Right = @('direction') },
                [pscustomobject]@{ Left = @('offer_nonce'); Right = @('offer_nonce') },
                [pscustomobject]@{ Left = @('payer_decision_id'); Right = @('payer_decision_id') },
                [pscustomobject]@{ Left = @('offer_generation'); Right = @('offer_generation') },
                [pscustomobject]@{ Left = @('transaction_generation'); Right = @('transaction_generation') },
                [pscustomobject]@{ Left = @('tuna_path_lease_generation'); Right = @('tuna_path_lease_generation', 'lease_generation') },
                [pscustomobject]@{ Left = @('tuna_path_lease_listener_run_id'); Right = @('tuna_path_lease_listener_run_id', 'listener_run_id') })) {
            $leftValue = Get-PathLeaseExpiryField -Event $Left -Names $mapping.Left
            $rightValue = Get-PathLeaseExpiryField -Event $Right -Names $mapping.Right
            if ($AllowMissingRight -and [string]::IsNullOrWhiteSpace($rightValue)) {
                continue
            }
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    [object[]]$physicalResumes = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_offer_envelope_refresh_physical_resume' -and
        (Get-PathLeaseExpiryField -Event $_ -Names @('boundary')) -in
            @('PeerResponseTimeout', 'AnswerTimeout') -and
        [int64](Get-PathLeaseExpiryField -Event $_ -Names @('refresh_generation') -Default '0') -gt 0
    })
    [object[]]$refreshCommitted = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_offer_envelope_refresh_committed' -and
        (Get-PathLeaseExpiryField -Event $_ -Names @('decision_status')) -in
            @('Accepted', 'Idempotent', 'accepted', 'idempotent')
    })
    [object[]]$held = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_decided' -and
        (Get-PathLeaseExpiryField -Event $_ -Names @('decision_status')) -eq 'Held'
    })
    [object[]]$adopted = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_operation_closure_adopted' -and
        (Get-PathLeaseExpiryField -Event $_ -Names @('execution_state')) -eq 'Completed' -and
        (Get-PathLeaseExpiryField -Event $_ -Names @('closure_state')) -eq 'Adopted'
    })
    [object[]]$resumed = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_resumed' -and
        (Get-PathLeaseExpiryField -Event $_ -Names @('decision_status')) -eq 'Released'
    })
    [object[]]$sidecarTimeouts = @($events | Where-Object {
        $_.EventName -eq 'tuna_listener_sidecar_event' -and
        (Get-PathLeaseExpiryField -Event $_ -Names @('sidecar_event')) -eq 'error' -and
        (Get-PathLeaseExpiryField -Event $_ -Names @('sidecar_reason')) -match
            'Tuna accept failed: accept timed out'
    })
    [object[]]$leaseFailures = @($events | Where-Object {
        $_.EventName -in @('tuna_path_lease_failed', 'tuna_path_lease_sidecar_unavailable') -and
        [int64](Get-PathLeaseExpiryField -Event $_ -Names @('offer_generation') -Default '0') -gt 0 -and
        [int64](Get-PathLeaseExpiryField -Event $_ -Names @('transaction_generation') -Default '0') -gt 0 -and
        [int64](Get-PathLeaseExpiryField -Event $_ -Names @('lease_generation') -Default '0') -gt 0
    })
    [object[]]$prevalidations = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_send_prevalidated' -and
        (Get-PathLeaseExpiryField -Event $_ -Names @('prevalidation_status')) -eq 'accepted'
    })
    [object[]]$submissions = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_post_prevalidation_submission'
    })
    [object[]]$answers = @($events | Where-Object {
        $_.EventName -in @(
            'tuna_acceleration_offer_received_raw',
            'runtime_unlock_transaction_answer_received',
            'tuna_acceleration_answer_ack_sent',
            'runtime_unlock_precommit_admission_granted',
            'runtime_unlock_route_commit_precommit_admission_granted',
            'filetransfer_route_transition_prepared')
    })

    $raw = New-Object System.Collections.Generic.List[object]
    $distinct = [ordered]@{}
    foreach ($timeout in $sidecarTimeouts) {
        $writerId = Get-PathLeaseExpiryField -Event $timeout -Names @('log_writer_id')
        [object[]]$matchingFailures = @($leaseFailures | Where-Object {
            [int64]$_.Sequence -gt [int64]$timeout.Sequence -and
            (Get-PathLeaseExpiryField -Event $_ -Names @('log_writer_id')) -eq
                $writerId
        } | Select-Object -First 1)
        if ($matchingFailures.Count -eq 0) {
            continue
        }
        $failure = $matchingFailures[0]

        [object[]]$matchingResumes = @($physicalResumes | Where-Object {
            [int64]$_.Sequence -lt [int64]$timeout.Sequence -and
            (Test-PathLeaseExpiryTuple -Left $_ -Right $failure -AllowMissingRight)
        } | Select-Object -Last 2)
        if ($matchingResumes.Count -ne 1) {
            continue
        }
        $resume = $matchingResumes[0]

        $refreshGeneration = Get-PathLeaseExpiryField -Event $resume -Names @('refresh_generation')
        [object[]]$refreshes = @($refreshCommitted | Where-Object {
            [int64]$_.Sequence -lt [int64]$resume.Sequence -and
            (Get-PathLeaseExpiryField -Event $_ -Names @('refresh_generation')) -eq
                $refreshGeneration -and
            (Test-PathLeaseExpiryTuple -Left $resume -Right $_)
        } | Select-Object -Last 1)
        [object[]]$matchingHolds = @($held | Where-Object {
            [int64]$_.Sequence -lt [int64]$resume.Sequence -and
            (Test-PathLeaseExpiryTuple -Left $resume -Right $_ -AllowMissingRight)
        } | Select-Object -Last 1)
        [object[]]$matchingAdoptions = @($adopted | Where-Object {
            [int64]$_.Sequence -lt [int64]$resume.Sequence -and
            (Get-PathLeaseExpiryField -Event $_ -Names @('log_writer_id')) -eq $writerId -and
            (Get-PathLeaseExpiryField -Event $_ -Names @('session_id')) -eq
                (Get-PathLeaseExpiryField -Event $resume -Names @('session_id')) -and
            (Get-PathLeaseExpiryField -Event $_ -Names @('transfer_id')) -eq
                (Get-PathLeaseExpiryField -Event $resume -Names @('transfer_id'))
        } | Select-Object -Last 1)
        [object[]]$matchingRelease = @($resumed | Where-Object {
            [int64]$_.Sequence -le [int64]$resume.Sequence -and
            (Test-PathLeaseExpiryTuple -Left $resume -Right $_)
        } | Select-Object -Last 1)
        if ($refreshes.Count -ne 1 -or
            $matchingHolds.Count -ne 1 -or
            $matchingAdoptions.Count -ne 1 -or
            $matchingRelease.Count -ne 1) {
            continue
        }

        $sendObserved = @(@($prevalidations) + @($submissions) | Where-Object {
            [int64]$_.Sequence -gt [int64]$resume.Sequence -and
            [int64]$_.Sequence -lt [int64]$timeout.Sequence -and
            (Test-PathLeaseExpiryTuple -Left $resume -Right $_ -AllowMissingRight)
        }).Count -gt 0
        $progressObserved = @($answers | Where-Object {
            [int64]$_.Sequence -gt [int64]$resume.Sequence -and
            [int64]$_.Sequence -lt [int64]$timeout.Sequence
        }).Count -gt 0
        if ($sendObserved -or $progressObserved) {
            continue
        }

        $raw.Add($timeout) | Out-Null
        $key = [string]::Join('|', @(
            $writerId,
            (Get-PathLeaseExpiryField -Event $resume -Names @('session_id')),
            (Get-PathLeaseExpiryField -Event $resume -Names @('transfer_id')),
            (Get-PathLeaseExpiryField -Event $resume -Names @('direction')),
            (Get-PathLeaseExpiryField -Event $resume -Names @('payer_decision_id')),
            (Get-PathLeaseExpiryField -Event $resume -Names @('offer_generation')),
            (Get-PathLeaseExpiryField -Event $resume -Names @('transaction_generation')),
            (Get-PathLeaseExpiryField -Event $resume -Names @('tuna_path_lease_generation')),
            (Get-PathLeaseExpiryField -Event $resume -Names @('tuna_path_lease_listener_run_id')),
            $refreshGeneration))
        if (-not $distinct.Contains($key)) {
            $distinct[$key] = $timeout
        }
    }

    $unresolved = @($distinct.Values)
    return [pscustomobject]@{
        RawCount = $raw.Count
        DistinctCount = $distinct.Count
        RecoveredCount = 0
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($raw.ToArray())
        RecoveredCandidateEvents = @()
        UnresolvedCandidateEvents = @($unresolved)
    }
}

function Get-FileTransferRuntimeUnlockInitialActivationReceiveRecoveryHoldReleasedOfferExpiredCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$events = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }

    function Get-ExpiredOfferField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = ''
        )

        foreach ($name in $Names) {
            $value =
                Get-FileTransferEventField `
                    -Event $Event `
                    -Name $name `
                    -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                return $value
            }
        }
        return $Default
    }

    function Test-ExpiredOfferSourceTuple {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [switch]$AllowMissingRight
        )

        foreach ($mapping in @(
                [pscustomobject]@{ Left = @('log_writer_id'); Right = @('log_writer_id') },
                [pscustomobject]@{ Left = @('session_id'); Right = @('session_id') },
                [pscustomobject]@{ Left = @('payer_decision_id'); Right = @('payer_decision_id') },
                [pscustomobject]@{ Left = @('offer_generation', 'generation'); Right = @('offer_generation', 'generation') })) {
            $leftValue = Get-ExpiredOfferField -Event $Left -Names $mapping.Left
            $rightValue = Get-ExpiredOfferField -Event $Right -Names $mapping.Right
            if ($AllowMissingRight -and [string]::IsNullOrWhiteSpace($rightValue)) {
                continue
            }
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    [object[]]$held = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_decided' -and
        (Get-ExpiredOfferField -Event $_ -Names @('decision_status')) -eq 'Held'
    })
    [object[]]$adopted = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_operation_closure_adopted' -and
        (Get-ExpiredOfferField -Event $_ -Names @('execution_state')) -eq
            'Completed' -and
        (Get-ExpiredOfferField -Event $_ -Names @('closure_state')) -eq
            'Adopted'
    })
    [object[]]$resumed = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_resumed' -and
        (Get-ExpiredOfferField -Event $_ -Names @('decision_status')) -eq
            'Released'
    })
    [object[]]$prevalidated = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_receive_recovery_hold_send_prevalidated' -and
        (Get-ExpiredOfferField -Event $_ -Names @('decision_status')) -eq
            'Released' -and
        (Get-ExpiredOfferField -Event $_ -Names @('same_generation_resume')) -eq '1'
    })
    [object[]]$queued = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_offer_queued' -and
        (Get-ExpiredOfferField -Event $_ -Names @('reason')) -eq
            'runtime_unlock'
    })
    [object[]]$rawPeerOffers = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_offer_received_raw'
    })
    [object[]]$expiredRejections = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_message_rejected' -and
        (Get-ExpiredOfferField -Event $_ -Names @('message_type')) -eq
            'transport_acceleration_offer' -and
        (Get-ExpiredOfferField -Event $_ -Names @('reason')) -eq 'expired'
    })
    [object[]]$refreshCommitted = @($events | Where-Object {
        $_.EventName -eq
            'runtime_unlock_initial_activation_offer_envelope_refresh_committed' -and
        (Get-ExpiredOfferField -Event $_ -Names @('decision_status')) -in
            @('Accepted', 'Idempotent', 'accepted', 'idempotent')
    })
    [object[]]$transactionAnswers = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_transaction_answer_received'
    })
    [object[]]$answerAcks = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_ack_sent'
    })
    [object[]]$preparedTransitions = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_route_transition_prepared'
    })

    $raw = New-Object System.Collections.Generic.List[object]
    $distinct = [ordered]@{}
    foreach ($rejection in $expiredRejections) {
        $rejectionSequence = [int64]$rejection.Sequence
        $peerWriter =
            Get-ExpiredOfferField -Event $rejection -Names @('log_writer_id')
        [object[]]$peerRaw = @($rawPeerOffers | Where-Object {
            [int64]$_.Sequence -lt $rejectionSequence -and
            (Get-ExpiredOfferField -Event $_ -Names @('log_writer_id')) -eq
                $peerWriter
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($peerRaw.Count -ne 1) {
            continue
        }

        [object[]]$sourceQueues = @($queued | Where-Object {
            [int64]$_.Sequence -lt [int64]$peerRaw[0].Sequence -and
            (Get-ExpiredOfferField -Event $_ -Names @('log_writer_id')) -ne
                $peerWriter
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($sourceQueues.Count -ne 1) {
            continue
        }
        $sourceQueue = $sourceQueues[0]

        [object[]]$matchingPrevalidation = @($prevalidated | Where-Object {
            [int64]$_.Sequence -lt [int64]$sourceQueue.Sequence -and
            (Test-ExpiredOfferSourceTuple -Left $_ -Right $sourceQueue)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($matchingPrevalidation.Count -ne 1) {
            continue
        }
        $prevalidation = $matchingPrevalidation[0]

        [object[]]$matchingResume = @($resumed | Where-Object {
            [int64]$_.Sequence -le [int64]$prevalidation.Sequence -and
            (Test-ExpiredOfferSourceTuple `
                -Left $_ `
                -Right $prevalidation `
                -AllowMissingRight)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($matchingResume.Count -ne 1) {
            continue
        }
        $resume = $matchingResume[0]

        [object[]]$matchingHold = @($held | Where-Object {
            [int64]$_.Sequence -lt [int64]$resume.Sequence -and
            (Test-ExpiredOfferSourceTuple `
                -Left $_ `
                -Right $resume `
                -AllowMissingRight) -and
            (Get-ExpiredOfferField -Event $_ -Names @('transfer_id')) -eq
                (Get-ExpiredOfferField -Event $resume -Names @('transfer_id')) -and
            (Get-ExpiredOfferField -Event $_ -Names @('direction')) -eq
                (Get-ExpiredOfferField -Event $resume -Names @('direction')) -and
            (Get-ExpiredOfferField -Event $_ -Names @('control_envelope_fingerprint')) -eq
                (Get-ExpiredOfferField -Event $resume -Names @('control_envelope_fingerprint'))
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($matchingHold.Count -ne 1) {
            continue
        }

        $operationGeneration =
            Get-ExpiredOfferField `
                -Event $resume `
                -Names @('receive_recovery_operation_generation')
        $closureGeneration =
            Get-ExpiredOfferField `
                -Event $resume `
                -Names @('receive_recovery_closure_generation', 'closure_generation')
        [object[]]$matchingAdoption = @($adopted | Where-Object {
            [int64]$_.Sequence -lt [int64]$resume.Sequence -and
            (Get-ExpiredOfferField -Event $_ -Names @('log_writer_id')) -eq
                (Get-ExpiredOfferField -Event $resume -Names @('log_writer_id')) -and
            (Get-ExpiredOfferField -Event $_ -Names @('session_id')) -eq
                (Get-ExpiredOfferField -Event $resume -Names @('session_id')) -and
            (Get-ExpiredOfferField -Event $_ -Names @('transfer_id')) -eq
                (Get-ExpiredOfferField -Event $resume -Names @('transfer_id')) -and
            (Get-ExpiredOfferField -Event $_ -Names @('direction')) -eq
                (Get-ExpiredOfferField -Event $resume -Names @('direction')) -and
            (Get-ExpiredOfferField -Event $_ -Names @('receive_recovery_operation_generation')) -eq
                $operationGeneration -and
            (Get-ExpiredOfferField -Event $_ -Names @('closure_generation')) -eq
                $closureGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($matchingAdoption.Count -ne 1) {
            continue
        }

        $raw.Add($rejection) | Out-Null
        $key = (@(
            Get-ExpiredOfferField -Event $resume -Names @('log_writer_id')
            Get-ExpiredOfferField -Event $resume -Names @('session_id')
            Get-ExpiredOfferField -Event $resume -Names @('transfer_id')
            Get-ExpiredOfferField -Event $resume -Names @('direction')
            Get-ExpiredOfferField -Event $resume -Names @('payer_decision_id')
            Get-ExpiredOfferField -Event $resume -Names @('offer_generation')
            Get-ExpiredOfferField -Event $resume -Names @('transaction_generation')
            Get-ExpiredOfferField -Event $resume -Names @('tuna_path_lease_generation')
            Get-ExpiredOfferField -Event $resume -Names @('control_envelope_fingerprint')
            $operationGeneration
            $closureGeneration
            $peerWriter
        ) | ForEach-Object { ([string]$_).ToLowerInvariant() }) -join '|'
        if (-not $distinct.Contains($key)) {
            $distinct[$key] = [pscustomobject]@{
                Event = $rejection
                Resume = $resume
            }
        }
    }

    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    foreach ($record in @($distinct.Values)) {
        $eventSequence = [int64]$record.Event.Sequence
        [object[]]$refresh = @($refreshCommitted | Where-Object {
            [int64]$_.Sequence -gt $eventSequence -and
            (Test-ExpiredOfferSourceTuple `
                -Left $record.Resume `
                -Right $_ `
                -AllowMissingRight)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $resolved = $false
        if ($refresh.Count -eq 1) {
            [object[]]$answers = @($transactionAnswers | Where-Object {
                [int64]$_.Sequence -gt [int64]$refresh[0].Sequence -and
                (Test-ExpiredOfferSourceTuple `
                    -Left $record.Resume `
                    -Right $_ `
                    -AllowMissingRight)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            [object[]]$acks = @($answerAcks | Where-Object {
                $answers.Count -eq 1 -and
                [int64]$_.Sequence -gt [int64]$answers[0].Sequence -and
                (Get-ExpiredOfferField -Event $_ -Names @('log_writer_id')) -eq
                    (Get-ExpiredOfferField -Event $record.Resume -Names @('log_writer_id'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            [object[]]$prepared = @($preparedTransitions | Where-Object {
                $acks.Count -eq 1 -and
                [int64]$_.Sequence -gt [int64]$acks[0].Sequence -and
                (Get-ExpiredOfferField -Event $_ -Names @('session_id')) -eq
                    (Get-ExpiredOfferField -Event $record.Resume -Names @('session_id')) -and
                (Get-ExpiredOfferField -Event $_ -Names @('transfer_id')) -eq
                    (Get-ExpiredOfferField -Event $record.Resume -Names @('transfer_id')) -and
                (Get-ExpiredOfferField -Event $_ -Names @('direction')) -eq
                    (Get-ExpiredOfferField -Event $record.Resume -Names @('direction'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            $resolved =
                $answers.Count -eq 1 -and
                $acks.Count -eq 1 -and
                $prepared.Count -eq 1
        }

        if ($resolved) {
            $recovered.Add($record.Event) | Out-Null
        }
        else {
            $unresolved.Add($record.Event) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $raw.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) {
            'fail'
        }
        elseif ($distinct.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($raw.ToArray())
        DistinctCandidateEvents = @($distinct.Values | ForEach-Object { $_.Event })
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockRetryZeroOfferSuccessorCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @()
    )

    function Test-ZeroOfferRetryScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [switch]$IncludeAuthority
        )

        $fields = @(
            'session_id',
            'transfer_id',
            'direction',
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'bridge_decision_generation',
            'route_publication_generation',
            'route_commit_generation',
            'contract_generation',
            'retry_reason',
            'recovery_reason')
        if ($IncludeAuthority) {
            $fields += @(
                'authority_id',
                'retired_generation',
                'dispatch_attempt_generation',
                'missing_dispatch_successor_generation')
        }

        foreach ($field in $fields) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    [object[]]$settlementEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_contract_settled' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'retired_generation' -Default '-1') -eq 0 -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'offer_generation' -Default '-1') -eq 0
    } | Sort-Object Sequence)
    [object[]]$settlementDecisionEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent')
    } | Sort-Object Sequence)
    $lifecycleCorrelation =
        Get-FileTransferRuntimeUnlockRetryLifecycleCorrelation -Events $Events
    [object[]]$coordinatorRejectionCorrelations = @(
        $lifecycleCorrelation.EffectiveSuccessorCorrelations |
            Where-Object {
                (Get-FileTransferEventField -Event $_.Decision -Name 'decision_status' -Default '') -eq
                    'Rejected' -and
                (Get-FileTransferEventField -Event $_.Decision -Name 'decision_reason' -Default '') -eq
                    'retry_dispatch_successor_retired_offer_mismatch'
            }
    )
    [object[]]$legacyRejectionEvents = if ($lifecycleCorrelation.SuccessorProtocolObserved) {
        @()
    }
    else {
        @($Events | Where-Object {
            $_.EventName -eq 'runtime_unlock_retry_successor_intent_rejected' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
                'retry_dispatch_successor_retired_offer_mismatch'
        } | Sort-Object Sequence)
    }
    [object[]]$rejectionEvents = @(
        @($legacyRejectionEvents + @(
            $coordinatorRejectionCorrelations |
                ForEach-Object { $_.Decision }
        )) |
            Sort-Object Sequence, LineNumber
    )
    $coordinatorEvaluationByDecisionSequence = @{}
    foreach ($correlation in $coordinatorRejectionCorrelations) {
        $coordinatorEvaluationByDecisionSequence[[string]$correlation.Decision.Sequence] =
            $correlation.Evaluation
    }
    [object[]]$grantEvents = @($EffectiveGrantEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted'
    } | Sort-Object Sequence)

    $acceptedSettlements = New-Object System.Collections.Generic.List[object]
    foreach ($settlement in $settlementEvents) {
        $authorityId = Get-FileTransferEventField -Event $settlement -Name 'authority_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($authorityId) -or $authorityId -in @('(none)', 'none')) {
            continue
        }

        $matchingDecision = @($settlementDecisionEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq $authorityId -and
            (Test-ZeroOfferRetryScopeMatch -Left $settlement -Right $_ -IncludeAuthority)
        } | Sort-Object Sequence | Select-Object -First 1)
        if ($matchingDecision.Count -gt 0) {
            $acceptedSettlements.Add($settlement) | Out-Null
        }
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($rejection in $rejectionEvents) {
        $coordinatorEvaluation =
            $coordinatorEvaluationByDecisionSequence[[string]$rejection.Sequence]
        $isCoordinatorDecision = $null -ne $coordinatorEvaluation
        $authorityId = Get-FileTransferEventField -Event $rejection -Name 'authority_id' -Default ''
        $requestedPredecessor = if ($isCoordinatorDecision) {
            $authorityId
        }
        else {
            Get-FileTransferEventField `
                -Event $rejection `
                -Name 'requested_predecessor_authority_id' `
                -Default ''
        }
        $predecessorAttempt = [int](Get-FileTransferEventField `
            -Event $rejection `
            -Name 'dispatch_attempt_generation' `
            -Default '0')
        $predecessorMissingGeneration = [int](Get-FileTransferEventField `
            -Event $rejection `
            -Name 'missing_dispatch_successor_generation' `
            -Default '-1')
        $requestedAttempt = if ($isCoordinatorDecision) {
            $predecessorAttempt + 1
        }
        else {
            [int](Get-FileTransferEventField `
                -Event $rejection `
                -Name 'requested_dispatch_attempt_generation' `
                -Default '0')
        }
        $requestedMissingGeneration = if ($isCoordinatorDecision) {
            $predecessorMissingGeneration + 1
        }
        else {
            [int](Get-FileTransferEventField `
                -Event $rejection `
                -Name 'requested_missing_dispatch_successor_generation' `
                -Default '-1')
        }
        $requestedRetiredGeneration = if ($isCoordinatorDecision) {
            Get-FileTransferEventInt64Field `
                -Event $coordinatorEvaluation `
                -Name 'retired_generation' `
                -Default -1
        }
        else {
            [int64](Get-FileTransferEventField `
                -Event $rejection `
                -Name 'requested_retired_generation' `
                -Default '-1')
        }
        $predecessorRetiredGeneration = [int64](Get-FileTransferEventField `
            -Event $rejection `
            -Name 'retired_generation' `
            -Default '-1')
        $supersession = if ($isCoordinatorDecision) {
            Get-FileTransferEventField `
                -Event $coordinatorEvaluation `
                -Name 'request_active_predecessor_supersession' `
                -Default '0'
        }
        else {
            Get-FileTransferEventField `
                -Event $rejection `
                -Name 'request_active_predecessor_supersession' `
                -Default '0'
        }

        if ([string]::IsNullOrWhiteSpace($authorityId) -or
            $authorityId -in @('(none)', 'none') -or
            $requestedPredecessor -ne $authorityId -or
            $requestedRetiredGeneration -ne 0 -or
            $predecessorRetiredGeneration -ne 0 -or
            $requestedAttempt -ne ($predecessorAttempt + 1) -or
            $requestedMissingGeneration -ne ($predecessorMissingGeneration + 1) -or
            $supersession -notin @('0', 'false', 'False')) {
            continue
        }

        $matchingSettlement = @($acceptedSettlements.ToArray() | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq $authorityId -and
            [int](Get-FileTransferEventField -Event $_ -Name 'dispatch_attempt_generation' -Default '0') -eq
                $predecessorAttempt -and
            [int](Get-FileTransferEventField -Event $_ -Name 'missing_dispatch_successor_generation' -Default '-1') -eq
                $predecessorMissingGeneration -and
            (Test-ZeroOfferRetryScopeMatch -Left $_ -Right $rejection -IncludeAuthority)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($matchingSettlement.Count -eq 0) {
            continue
        }

        $rawCandidates.Add($rejection) | Out-Null
        $key = '{0}|{1}|{2}|{3}|{4}|{5}' -f `
            (Get-FileTransferEventField -Event $rejection -Name 'session_id' -Default ''), `
            (Get-FileTransferEventField -Event $rejection -Name 'transfer_id' -Default ''), `
            (Get-FileTransferEventField -Event $rejection -Name 'direction' -Default ''), `
            $authorityId, `
            $requestedAttempt, `
            $requestedMissingGeneration
        if ($seen.ContainsKey($key)) {
            continue
        }

        $seen[$key] = 1
        $distinctCandidates.Add($rejection) | Out-Null
        $matchingGrant = @($grantEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$rejection.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '') -eq $authorityId -and
            [int64](Get-FileTransferEventField -Event $_ -Name 'retired_generation' -Default '-1') -eq 0 -and
            [int](Get-FileTransferEventField -Event $_ -Name 'dispatch_attempt_generation' -Default '0') -eq
                $requestedAttempt -and
            [int](Get-FileTransferEventField -Event $_ -Name 'missing_dispatch_successor_generation' -Default '-1') -eq
                $requestedMissingGeneration -and
            (Test-ZeroOfferRetryScopeMatch -Left $matchingSettlement[0] -Right $_)
        } | Sort-Object Sequence | Select-Object -First 1)
        if ($matchingGrant.Count -gt 0) {
            $recoveredCandidates.Add($rejection) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($rejection) | Out-Null
        }
    }

    $verdict = if ($unresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        AcceptedMissingDispatchSettlementEvents = @($acceptedSettlements.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockRetryFallbackPairedYieldSuccessorReleaseCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @()
    )

    function Test-FallbackPairedYieldReleaseTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @(
                'release_kind',
                'release_authority_id',
                'release_generation',
                'release_outcome')) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                $leftValue -in @('(none)', 'none') -or
                $rightValue -in @('(none)', 'none') -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackPairedYieldSuccessorRequestMatch {
        param(
            [Parameter(Mandatory = $true)]$Request,
            [Parameter(Mandatory = $true)]$Rejection,
            [Parameter(Mandatory = $true)]$Settlement
        )

        foreach ($field in @('session_id', 'transfer_id', 'direction', 'contract_generation')) {
            $requestValue = Get-FileTransferEventField -Event $Request -Name $field -Default ''
            $rejectionValue = Get-FileTransferEventField -Event $Rejection -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($requestValue) -or
                [string]::IsNullOrWhiteSpace($rejectionValue) -or
                -not [string]::Equals($requestValue, $rejectionValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $authorityId = Get-FileTransferEventField -Event $Settlement -Name 'authority_id' -Default ''
        $requestPredecessor = Get-FileTransferEventField -Event $Request -Name 'predecessor_authority_id' -Default ''
        $rejectedPredecessor = Get-FileTransferEventField -Event $Rejection -Name 'requested_predecessor_authority_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($authorityId) -or
            $authorityId -in @('(none)', 'none') -or
            $requestPredecessor -ne $authorityId -or
            $rejectedPredecessor -ne $authorityId) {
            return $false
        }

        [int64]$offerGeneration = Get-FileTransferEventInt64Field -Event $Settlement -Name 'offer_generation' -Default -1
        [int64]$requestRetiredGeneration = Get-FileTransferEventInt64Field -Event $Request -Name 'retired_generation' -Default -1
        [int64]$rejectedRetiredGeneration = Get-FileTransferEventInt64Field -Event $Rejection -Name 'requested_retired_generation' -Default -1
        [int64]$predecessorAttempt = Get-FileTransferEventInt64Field -Event $Settlement -Name 'dispatch_attempt_generation' -Default -1
        [int64]$predecessorMissingGeneration = Get-FileTransferEventInt64Field -Event $Settlement -Name 'missing_dispatch_successor_generation' -Default -1
        [int64]$requestAttempt = Get-FileTransferEventInt64Field -Event $Request -Name 'dispatch_attempt_generation' -Default -1
        [int64]$rejectedAttempt = Get-FileTransferEventInt64Field -Event $Rejection -Name 'requested_dispatch_attempt_generation' -Default -1
        [int64]$requestMissingGeneration = Get-FileTransferEventInt64Field -Event $Request -Name 'missing_dispatch_successor_generation' -Default -1
        [int64]$rejectedMissingGeneration = Get-FileTransferEventInt64Field -Event $Rejection -Name 'requested_missing_dispatch_successor_generation' -Default -1
        $requestSupersession = Get-FileTransferEventField -Event $Request -Name 'request_active_predecessor_supersession' -Default ''
        $rejectedSupersession = Get-FileTransferEventField -Event $Rejection -Name 'request_active_predecessor_supersession' -Default ''

        return $offerGeneration -gt 0 -and
            $requestRetiredGeneration -eq $offerGeneration -and
            $rejectedRetiredGeneration -eq $offerGeneration -and
            $requestAttempt -eq ($predecessorAttempt + 1) -and
            $rejectedAttempt -eq $requestAttempt -and
            $requestMissingGeneration -eq ($predecessorMissingGeneration + 1) -and
            $rejectedMissingGeneration -eq $requestMissingGeneration -and
            $requestSupersession -in @('0', 'false', 'False') -and
            $rejectedSupersession -in @('0', 'false', 'False')
    }

    function Test-FallbackPairedYieldSuccessorGrantMatch {
        param(
            [Parameter(Mandatory = $true)]$PredecessorGrant,
            [Parameter(Mandatory = $true)]$Request,
            [Parameter(Mandatory = $true)]$SuccessorGrant
        )

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'route_kind',
                'protocol_version',
                'live_route_epoch',
                'terminal_generation',
                'leg_generation',
                'contract_generation',
                'retry_reason',
                'recovery_reason',
                'target_route',
                'target_route_kind',
                'target_protocol_version',
                'target_transport',
                'runtime_owner_session_id',
                'runtime_owner_transfer_id',
                'runtime_owner_direction',
                'runtime_owner_route',
                'runtime_owner_route_kind',
                'runtime_owner_protocol_version',
                'runtime_owner_live_route_epoch',
                'runtime_owner_terminal_generation',
                'runtime_owner_family',
                'source_publication_session_id',
                'source_publication_transfer_id',
                'source_publication_direction',
                'source_publication_route',
                'source_publication_route_kind',
                'source_publication_protocol_version',
                'source_publication_live_route_epoch',
                'source_publication_terminal_generation',
                'source_publication_leg_generation',
                'source_publication_route_commit_generation',
                'source_publication_target_route',
                'source_publication_target_route_kind',
                'source_publication_target_protocol_version',
                'source_publication_target_transport',
                'source_publication_action_kind')) {
            $predecessorValue = Get-FileTransferEventField -Event $PredecessorGrant -Name $field -Default ''
            $successorValue = Get-FileTransferEventField -Event $SuccessorGrant -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($predecessorValue) -or
                [string]::IsNullOrWhiteSpace($successorValue) -or
                -not [string]::Equals($predecessorValue, $successorValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $predecessorAuthorityId = Get-FileTransferEventField -Event $PredecessorGrant -Name 'authority_id' -Default ''
        if ((Get-FileTransferEventField -Event $SuccessorGrant -Name 'predecessor_authority_id' -Default '') -ne
                $predecessorAuthorityId -or
            -not (Test-FallbackPairedYieldReleaseTupleMatch -Left $PredecessorGrant -Right $SuccessorGrant)) {
            return $false
        }

        return (Get-FileTransferEventInt64Field -Event $SuccessorGrant -Name 'retired_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $Request -Name 'retired_generation' -Default -2) -and
            (Get-FileTransferEventInt64Field -Event $SuccessorGrant -Name 'dispatch_attempt_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $Request -Name 'dispatch_attempt_generation' -Default -2) -and
            (Get-FileTransferEventInt64Field -Event $SuccessorGrant -Name 'missing_dispatch_successor_generation' -Default -1) -eq
                (Get-FileTransferEventInt64Field -Event $Request -Name 'missing_dispatch_successor_generation' -Default -2) -and
            (Get-FileTransferEventField -Event $SuccessorGrant -Name 'request_active_predecessor_supersession' -Default '') -in
                @('0', 'false', 'False')
    }

    function Test-FallbackPairedYieldCoordinatorSuccessorGrantMatch {
        param(
            [Parameter(Mandatory = $true)]$PredecessorGrant,
            [Parameter(Mandatory = $true)]$Settlement,
            [Parameter(Mandatory = $true)]$Evaluation,
            [Parameter(Mandatory = $true)]$SuccessorGrant
        )

        $predecessorAuthorityId =
            Get-FileTransferEventField -Event $PredecessorGrant -Name 'authority_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($predecessorAuthorityId) -or
            (Get-FileTransferEventField -Event $SuccessorGrant -Name 'predecessor_authority_id' -Default '') -ne
                $predecessorAuthorityId -or
            -not (Test-FallbackPairedYieldReleaseTupleMatch -Left $PredecessorGrant -Right $SuccessorGrant)) {
            return $false
        }

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'route_kind',
                'protocol_version',
                'live_route_epoch',
                'terminal_generation',
                'leg_generation',
                'contract_generation',
                'target_route',
                'target_route_kind',
                'target_protocol_version',
                'target_transport',
                'runtime_owner_session_id',
                'runtime_owner_transfer_id',
                'runtime_owner_direction',
                'runtime_owner_route',
                'runtime_owner_route_kind',
                'runtime_owner_protocol_version',
                'runtime_owner_live_route_epoch',
                'runtime_owner_terminal_generation',
                'runtime_owner_family',
                'source_publication_session_id',
                'source_publication_transfer_id',
                'source_publication_direction',
                'source_publication_route',
                'source_publication_route_kind',
                'source_publication_protocol_version',
                'source_publication_live_route_epoch',
                'source_publication_terminal_generation',
                'source_publication_leg_generation',
                'source_publication_route_commit_generation',
                'source_publication_target_route',
                'source_publication_target_route_kind',
                'source_publication_target_protocol_version',
                'source_publication_target_transport',
                'source_publication_action_kind')) {
            $predecessorValue =
                Get-FileTransferEventField -Event $PredecessorGrant -Name $field -Default ''
            $successorValue =
                Get-FileTransferEventField -Event $SuccessorGrant -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($predecessorValue) -or
                [string]::IsNullOrWhiteSpace($successorValue) -or
                -not [string]::Equals(
                    $predecessorValue,
                    $successorValue,
                    [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $offerGeneration =
            Get-FileTransferEventInt64Field -Event $Settlement -Name 'offer_generation' -Default -1
        return $offerGeneration -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $Evaluation -Name 'retired_generation' -Default -2) -eq
                $offerGeneration -and
            (Get-FileTransferEventField -Event $Evaluation -Name 'request_active_predecessor_supersession' -Default '') -in
                @('0', 'false', 'False') -and
            (Get-FileTransferEventInt64Field -Event $SuccessorGrant -Name 'retired_generation' -Default -1) -eq
                $offerGeneration -and
            (Get-FileTransferEventInt64Field -Event $SuccessorGrant -Name 'dispatch_attempt_generation' -Default -1) -eq
                ((Get-FileTransferEventInt64Field -Event $PredecessorGrant -Name 'dispatch_attempt_generation' -Default -2) + 1) -and
            (Get-FileTransferEventInt64Field -Event $SuccessorGrant -Name 'missing_dispatch_successor_generation' -Default -1) -eq
                ((Get-FileTransferEventInt64Field -Event $PredecessorGrant -Name 'missing_dispatch_successor_generation' -Default -2) + 1) -and
            (Get-FileTransferEventField -Event $SuccessorGrant -Name 'request_active_predecessor_supersession' -Default '') -in
                @('0', 'false', 'False')
    }

    [object[]]$predecessorGrantEvents = @($EffectiveGrantEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'release_kind' -Default '') -eq 'FallbackPairedTailYield' -and
        (Get-FileTransferEventField -Event $_ -Name 'release_outcome' -Default '') -eq 'Quiescent'
    } | Sort-Object Sequence, LineNumber)
    [object[]]$settlementEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_contract_settled' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
        (Get-FileTransferEventField -Event $_ -Name 'dispatch_observed' -Default '') -eq '0'
    } | Sort-Object Sequence, LineNumber)
    [object[]]$reportedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_reported' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch'
    } | Sort-Object Sequence, LineNumber)
    [object[]]$decidedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent')
    } | Sort-Object Sequence, LineNumber)
    [object[]]$requestEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_successor_intent_requested'
    } | Sort-Object Sequence, LineNumber)
    $lifecycleCorrelation =
        Get-FileTransferRuntimeUnlockRetryLifecycleCorrelation -Events $Events
    [object[]]$legacyRejectionEvents = if ($lifecycleCorrelation.SuccessorProtocolObserved) {
        @()
    } else {
        @($Events | Where-Object {
            $_.EventName -eq 'runtime_unlock_retry_successor_intent_rejected' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
                'retry_dispatch_predecessor_release_invalid'
        } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$coordinatorRejectionCorrelations = @(
        $lifecycleCorrelation.EffectiveSuccessorCorrelations |
            Where-Object {
                (Get-FileTransferEventField -Event $_.Decision -Name 'decision_status' -Default '') -eq
                    'Rejected' -and
                (Get-FileTransferEventField -Event $_.Decision -Name 'decision_reason' -Default '') -eq
                    'retry_dispatch_predecessor_release_invalid'
            }
    )
    [object[]]$rejectionEvents = @(
        @($legacyRejectionEvents + @(
            $coordinatorRejectionCorrelations |
                ForEach-Object { $_.Decision }
        )) |
            Sort-Object Sequence, LineNumber
    )
    $coordinatorEvaluationByDecisionSequence = @{}
    foreach ($correlation in $coordinatorRejectionCorrelations) {
        $coordinatorEvaluationByDecisionSequence[[string]$correlation.Decision.Sequence] =
            $correlation.Evaluation
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $acceptedSettlements = New-Object System.Collections.Generic.List[object]
    $seen = @{}

    foreach ($rejection in $rejectionEvents) {
        $coordinatorEvaluation =
            $coordinatorEvaluationByDecisionSequence[[string]$rejection.Sequence]
        $isCoordinatorDecision = $null -ne $coordinatorEvaluation
        [object[]]$matchingSettlements = @($settlementEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
        } | Sort-Object Sequence, LineNumber -Descending)
        $matched = $null
        foreach ($settlement in $matchingSettlements) {
            [object[]]$matchingGrants = @($predecessorGrantEvents | Where-Object {
                [int64]$_.Sequence -lt [int64]$settlement.Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $settlement)
            } | Sort-Object Sequence, LineNumber -Descending)
            if ($matchingGrants.Count -eq 0) {
                continue
            }

            [object[]]$matchingReports = @($reportedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
                [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $settlement -Right $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq
                    (Get-FileTransferEventField -Event $settlement -Name 'decision_reason' -Default '')
            } | Sort-Object Sequence, LineNumber)
            if ($matchingReports.Count -eq 0) {
                continue
            }

            [object[]]$matchingDecisions = @($decidedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$matchingReports[0].Sequence -and
                [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $settlement -Right $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq
                    (Get-FileTransferEventField -Event $matchingReports[0] -Name 'settlement_reason' -Default '')
            } | Sort-Object Sequence, LineNumber)
            if ($matchingDecisions.Count -eq 0) {
                continue
            }

            [object[]]$matchingRequests = if ($isCoordinatorDecision) {
                if ([int64]$coordinatorEvaluation.Sequence -gt [int64]$matchingDecisions[0].Sequence -and
                    [int64]$coordinatorEvaluation.Sequence -lt [int64]$rejection.Sequence -and
                    (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch `
                        -Left $settlement `
                        -Right $coordinatorEvaluation) -and
                    (Get-FileTransferEventInt64Field -Event $coordinatorEvaluation -Name 'retired_generation' -Default -1) -eq
                        (Get-FileTransferEventInt64Field -Event $settlement -Name 'offer_generation' -Default -2) -and
                    (Get-FileTransferEventField -Event $coordinatorEvaluation -Name 'request_active_predecessor_supersession' -Default '') -in
                        @('0', 'false', 'False')) {
                    @($coordinatorEvaluation)
                }
                else {
                    @()
                }
            }
            else {
                @($requestEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$matchingDecisions[0].Sequence -and
                    [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                    (Test-FallbackPairedYieldSuccessorRequestMatch `
                        -Request $_ `
                        -Rejection $rejection `
                        -Settlement $settlement)
                } | Sort-Object Sequence, LineNumber)
            }
            if ($matchingRequests.Count -eq 0) {
                continue
            }

            $matched = [pscustomobject]@{
                Grant = $matchingGrants[0]
                Settlement = $settlement
                Request = $matchingRequests[0]
                CoordinatorOwned = $isCoordinatorDecision
            }
            break
        }

        if ($null -eq $matched) {
            continue
        }

        $rawCandidates.Add($rejection) | Out-Null
        $acceptedSettlements.Add($matched.Settlement) | Out-Null
        $keyFields = @(Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields)
        $key = (@($keyFields | ForEach-Object {
            Get-FileTransferEventField -Event $rejection -Name $_ -Default '(missing)'
        }) + @(
            (Get-FileTransferEventField -Event $rejection -Name 'requested_retired_generation' -Default '(missing)'),
            (Get-FileTransferEventField -Event $rejection -Name 'requested_dispatch_attempt_generation' -Default '(missing)'),
            (Get-FileTransferEventField -Event $rejection -Name 'requested_missing_dispatch_successor_generation' -Default '(missing)'))) -join '|'
        if ($seen.ContainsKey($key)) {
            continue
        }

        $seen[$key] = $true
        $distinctCandidates.Add($rejection) | Out-Null
        [object[]]$matchingSuccessorGrants = @($EffectiveGrantEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$rejection.Sequence -and
            (
                (
                    $matched.CoordinatorOwned -and
                    (Test-FallbackPairedYieldCoordinatorSuccessorGrantMatch `
                        -PredecessorGrant $matched.Grant `
                        -Settlement $matched.Settlement `
                        -Evaluation $matched.Request `
                        -SuccessorGrant $_)
                ) -or
                (
                    -not $matched.CoordinatorOwned -and
                    (Test-FallbackPairedYieldSuccessorGrantMatch `
                        -PredecessorGrant $matched.Grant `
                        -Request $matched.Request `
                        -SuccessorGrant $_)
                )
            )
        } | Sort-Object Sequence, LineNumber)
        if ($matchingSuccessorGrants.Count -gt 0) {
            $recoveredCandidates.Add($rejection) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($rejection) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) {
            'fail'
        }
        elseif ($distinctCandidates.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
        AcceptedMissingDispatchSettlementEvents = @($acceptedSettlements.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockRetryFallbackTailUnblockRecheckCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @(),
        [bool]$Phase2ProtocolObserved = $false
    )

    # Raw Phase-2 grant telemetry is not authority until the exact staged
    # decision has a committed install receipt. Keep non-grant evidence intact,
    # but expose only install-proven grants to this correlation.
    [object[]]$nonGrantEvents = @($Events | Where-Object {
        $_.EventName -ne 'runtime_unlock_retry_dispatch_authority_granted'
    })
    $Events = @($nonGrantEvents + @($EffectiveGrantEvents) | Sort-Object Sequence, LineNumber)

    [object[]]$heldEvents = @($Events | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_retry_dispatch_authority_held',
            'runtime_unlock_retry_dispatch_authority_hold_preserved') -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'fallback_paired_tail_yield_pending'
    } | Sort-Object Sequence)
    [object[]]$pairedYieldEvents = @($Events | Where-Object {
        $_.EventName -eq 'filetransfer_fallback_tail_paired_yield_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
        (Get-FileTransferEventField -Event $_ -Name 'protocol_version' -Default '') -eq '6'
    } | Sort-Object Sequence)
    [object[]]$tailUnblockedEvents = @($Events | Where-Object {
        $_.EventName -eq 'filetransfer_v6_epoch_tail_unblocked' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'target_transport' -Default '') -eq 'regular_nkn' -and
        (Get-FileTransferEventField -Event $_ -Name 'handoff_kind' -Default '') -in @(
            'tuna_to_normal_fallback',
            'regular_nkn_recovery')
    } | Sort-Object Sequence)
    [object[]]$recheckRequestedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_requested'
    } | Sort-Object Sequence)
    [object[]]$recheckDecidedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_decided'
    } | Sort-Object Sequence)
    [object[]]$recheckDiscardedEvents = @($Events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_discarded'
    } | Sort-Object Sequence)

    function Get-FallbackTailRecheckField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = ''
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
                return $value
            }
        }

        return $Default
    }

    function Get-FallbackTailRecheckExactField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value)) {
                return $value
            }
        }

        return ''
    }

    function Test-FallbackTailRecheckEventComplete {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][ValidateSet('Hold', 'Requested', 'Decided', 'Boundary')][string]$Kind
        )

        if ($Kind -eq 'Boundary') {
            $required = @(
                'session_id',
                'transfer_id',
                'direction',
                'transport_epoch',
                'handoff_kind',
                'source_transport',
                'target_transport')

            $recoveryBoundaryGeneration = Get-FallbackTailRecheckExactField `
                -Event $Event `
                -Names @('recovery_boundary_generation')
            $observationReason = Get-FallbackTailRecheckExactField `
                -Event $Event `
                -Names @('observation_reason')
            if (-not [string]::IsNullOrWhiteSpace($recoveryBoundaryGeneration) -or
                -not [string]::IsNullOrWhiteSpace($observationReason)) {
                $required += @('recovery_boundary_generation', 'observation_reason')
            }
        }
        else {
            $required = @(
                'session_id',
                'transfer_id',
                'direction|attempted_source_publication_direction',
                'contract_generation',
                'retired_generation|retired_offer_generation',
                'dispatch_attempt_generation',
                'missing_dispatch_successor_generation',
                'predecessor_authority_id',
                'request_active_predecessor_supersession',
                'retry_reason',
                'recovery_reason',
                'regular_v4_liveness_generation',
                'bridge_decision_generation',
                'source_session_id|source_publication_session_id|attempted_source_publication_session_id',
                'source_transfer_id|source_publication_transfer_id|attempted_source_publication_transfer_id',
                'source_direction|source_publication_direction|attempted_source_publication_direction',
                'source_route|source_publication_route|attempted_source_publication_route',
                'source_protocol_version|source_publication_protocol_version|attempted_source_publication_protocol_version',
                'source_live_route_epoch|source_publication_live_route_epoch|attempted_source_publication_live_route_epoch',
                'source_runtime_generation|source_publication_runtime_generation|attempted_source_publication_runtime_generation',
                'source_terminal_generation|source_publication_terminal_generation|attempted_source_publication_terminal_generation',
                'source_leg_generation|source_publication_leg_generation|attempted_source_publication_leg_generation',
                'source_route_publication_generation|source_publication_generation|attempted_source_publication_route_publication_generation',
                'source_route_commit_generation|source_publication_route_commit_generation|attempted_source_publication_route_commit_generation',
                'source_route_commit_generation_present|source_publication_route_commit_generation_present|attempted_source_publication_route_commit_generation_present',
                'source_target_route|source_publication_target_route|attempted_source_publication_target_route',
                'source_target_protocol_version|source_publication_target_protocol_version|attempted_source_publication_target_protocol_version',
                'source_target_transport|source_publication_target_transport|attempted_source_publication_target_transport',
                'source_route_publication_action_kind|source_publication_action_kind|attempted_source_publication_route_publication_action_kind',
                'source_coordinator_decision_reason|source_publication_reason|attempted_source_publication_coordinator_decision_reason')

            if ($Kind -in @('Requested', 'Decided')) {
                $required += @(
                    'recovered_transport_epoch',
                    'handoff_kind',
                    'boundary_source_transport',
                    'boundary_target_transport',
                    'fallback_epoch',
                    'boundary_reason',
                    'boundary_identity',
                    'original_hold_reason',
                    'recheck_generation')
            }
            if ($Kind -eq 'Decided') {
                $required += @(
                    'decision_status',
                    'decision_valid',
                    'decision_reason')
            }
        }

        foreach ($aliasSpec in $required) {
            [string[]]$aliases = $aliasSpec -split '\|'
            if ([string]::IsNullOrWhiteSpace(
                    (Get-FallbackTailRecheckExactField -Event $Event -Names $aliases))) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckHoldEligible {
        param(
            [Parameter(Mandatory = $true)]$Event
        )

        if (Test-FallbackTailRecheckEventComplete -Event $Event -Kind Hold) {
            return $true
        }

        # Artifacts captured before the recheck protocol logged the complete request tuple.
        # Retain those holds only as evidence that the historical boundary was abandoned;
        # they can never satisfy the strict requested/decided recovery proof below.
        foreach ($aliasSpec in @(
                'session_id',
                'transfer_id',
                'contract_generation',
                'retired_generation|retired_offer_generation',
                'regular_v4_liveness_generation',
                'bridge_decision_generation',
                'attempted_source_publication_session_id',
                'attempted_source_publication_transfer_id',
                'attempted_source_publication_direction',
                'attempted_source_publication_route',
                'attempted_source_publication_protocol_version',
                'attempted_source_publication_live_route_epoch',
                'attempted_source_publication_runtime_generation',
                'attempted_source_publication_terminal_generation',
                'attempted_source_publication_leg_generation',
                'attempted_source_publication_route_publication_generation',
                'attempted_source_publication_route_commit_generation',
                'attempted_source_publication_target_route',
                'attempted_source_publication_target_protocol_version',
                'attempted_source_publication_target_transport',
                'attempted_source_publication_route_publication_action_kind')) {
            [string[]]$aliases = $aliasSpec -split '\|'
            if ([string]::IsNullOrWhiteSpace(
                    (Get-FallbackTailRecheckExactField -Event $Event -Names $aliases))) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @('session_id', 'transfer_id')) {
            $leftValue = Get-FallbackTailRecheckField -Event $Left -Names @($field)
            $rightValue = Get-FallbackTailRecheckField -Event $Right -Names @($field)
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckRequestMatch {
        param(
            [Parameter(Mandatory = $true)]$Hold,
            [Parameter(Mandatory = $true)]$Decision,
            [ValidateSet('Hold', 'Requested', 'Decided')][string]$DecisionKind = 'Requested'
        )

        if (-not (Test-FallbackTailRecheckIdentityMatch -Left $Hold -Right $Decision)) {
            return $false
        }

        if (-not (Test-FallbackTailRecheckEventComplete -Event $Hold -Kind Hold) -or
            -not (Test-FallbackTailRecheckEventComplete -Event $Decision -Kind $DecisionKind)) {
            return $false
        }

        $fieldAliases = @(
            [pscustomobject]@{ Hold = @('direction', 'attempted_source_publication_direction'); Decision = @('direction', 'request_direction') },
            [pscustomobject]@{ Hold = @('source_route', 'source_publication_route', 'attempted_source_publication_route', 'route'); Decision = @('source_route', 'source_publication_route', 'request_source_route') },
            [pscustomobject]@{ Hold = @('source_protocol_version', 'source_publication_protocol_version', 'attempted_source_publication_protocol_version', 'protocol_version'); Decision = @('source_protocol_version', 'source_publication_protocol_version', 'request_source_protocol_version') },
            [pscustomobject]@{ Hold = @('source_live_route_epoch', 'source_publication_live_route_epoch', 'attempted_source_publication_live_route_epoch', 'live_route_epoch'); Decision = @('source_live_route_epoch', 'source_publication_live_route_epoch', 'request_source_live_route_epoch') },
            [pscustomobject]@{ Hold = @('source_runtime_generation', 'source_publication_runtime_generation', 'attempted_source_publication_runtime_generation', 'runtime_generation'); Decision = @('source_runtime_generation', 'source_publication_runtime_generation', 'request_source_runtime_generation') },
            [pscustomobject]@{ Hold = @('source_terminal_generation', 'source_publication_terminal_generation', 'attempted_source_publication_terminal_generation', 'terminal_generation'); Decision = @('source_terminal_generation', 'source_publication_terminal_generation', 'request_source_terminal_generation') },
            [pscustomobject]@{ Hold = @('source_leg_generation', 'source_publication_leg_generation', 'attempted_source_publication_leg_generation', 'leg_generation'); Decision = @('source_leg_generation', 'source_publication_leg_generation', 'request_source_leg_generation') },
            [pscustomobject]@{ Hold = @('source_route_commit_generation', 'source_publication_route_commit_generation', 'attempted_source_publication_route_commit_generation', 'route_commit_generation'); Decision = @('source_route_commit_generation', 'source_publication_route_commit_generation', 'request_source_route_commit_generation') },
            [pscustomobject]@{ Hold = @('contract_generation'); Decision = @('contract_generation', 'request_contract_generation') },
            [pscustomobject]@{ Hold = @('retired_generation'); Decision = @('retired_generation', 'request_retired_generation') },
            [pscustomobject]@{ Hold = @('dispatch_attempt_generation'); Decision = @('dispatch_attempt_generation', 'request_dispatch_attempt_generation') },
            [pscustomobject]@{ Hold = @('missing_dispatch_successor_generation'); Decision = @('missing_dispatch_successor_generation', 'request_missing_dispatch_successor_generation') },
            [pscustomobject]@{ Hold = @('predecessor_authority_id'); Decision = @('predecessor_authority_id', 'request_predecessor_authority_id') },
            [pscustomobject]@{ Hold = @('request_active_predecessor_supersession'); Decision = @('request_active_predecessor_supersession') },
            [pscustomobject]@{ Hold = @('retry_reason'); Decision = @('retry_reason') },
            [pscustomobject]@{ Hold = @('recovery_reason'); Decision = @('recovery_reason') },
            [pscustomobject]@{ Hold = @('regular_v4_liveness_generation'); Decision = @('regular_v4_liveness_generation') },
            [pscustomobject]@{ Hold = @('bridge_decision_generation'); Decision = @('bridge_decision_generation') },
            [pscustomobject]@{ Hold = @('source_session_id', 'source_publication_session_id', 'attempted_source_publication_session_id'); Decision = @('source_session_id') },
            [pscustomobject]@{ Hold = @('source_transfer_id', 'source_publication_transfer_id', 'attempted_source_publication_transfer_id'); Decision = @('source_transfer_id') },
            [pscustomobject]@{ Hold = @('source_direction', 'source_publication_direction', 'attempted_source_publication_direction'); Decision = @('source_direction') },
            [pscustomobject]@{ Hold = @('source_route_publication_generation', 'source_publication_generation', 'attempted_source_publication_route_publication_generation'); Decision = @('source_route_publication_generation') },
            [pscustomobject]@{ Hold = @('source_route_commit_generation_present', 'source_publication_route_commit_generation_present', 'attempted_source_publication_route_commit_generation_present'); Decision = @('source_route_commit_generation_present') },
            [pscustomobject]@{ Hold = @('source_target_route', 'source_publication_target_route', 'attempted_source_publication_target_route'); Decision = @('source_target_route') },
            [pscustomobject]@{ Hold = @('source_target_protocol_version', 'source_publication_target_protocol_version', 'attempted_source_publication_target_protocol_version'); Decision = @('source_target_protocol_version') },
            [pscustomobject]@{ Hold = @('source_target_transport', 'source_publication_target_transport', 'attempted_source_publication_target_transport'); Decision = @('source_target_transport') },
            [pscustomobject]@{ Hold = @('source_route_publication_action_kind', 'source_publication_action_kind', 'attempted_source_publication_route_publication_action_kind'); Decision = @('source_route_publication_action_kind') },
            [pscustomobject]@{ Hold = @('source_coordinator_decision_reason', 'source_publication_reason', 'attempted_source_publication_coordinator_decision_reason'); Decision = @('source_coordinator_decision_reason') }
        )
        foreach ($aliases in $fieldAliases) {
            $holdValue = Get-FallbackTailRecheckExactField -Event $Hold -Names $aliases.Hold
            $decisionValue = Get-FallbackTailRecheckExactField -Event $Decision -Names $aliases.Decision
            if ([string]::IsNullOrWhiteSpace($holdValue) -or
                [string]::IsNullOrWhiteSpace($decisionValue) -or
                -not [string]::Equals($holdValue, $decisionValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckBoundaryMatch {
        param(
            [Parameter(Mandatory = $true)]$Boundary,
            [Parameter(Mandatory = $true)]$Decision
        )

        if (-not (Test-FallbackTailRecheckEventComplete -Event $Boundary -Kind Boundary) -or
            -not (Test-FallbackTailRecheckEventComplete -Event $Decision -Kind Requested) -or
            -not (Test-FallbackTailRecheckIdentityMatch -Left $Boundary -Right $Decision)) {
            return $false
        }

        foreach ($aliases in @(
                [pscustomobject]@{ Boundary = @('transport_epoch'); Decision = @('recovered_transport_epoch', 'transport_epoch') },
                [pscustomobject]@{ Boundary = @('handoff_kind'); Decision = @('handoff_kind', 'recovery_handoff_kind') },
                [pscustomobject]@{ Boundary = @('source_transport'); Decision = @('boundary_source_transport') },
                [pscustomobject]@{ Boundary = @('target_transport'); Decision = @('boundary_target_transport') })) {
            $boundaryValue = Get-FallbackTailRecheckExactField -Event $Boundary -Names $aliases.Boundary
            $decisionValue = Get-FallbackTailRecheckExactField -Event $Decision -Names $aliases.Decision
            if ([string]::IsNullOrWhiteSpace($boundaryValue) -or
                [string]::IsNullOrWhiteSpace($decisionValue) -or
                -not [string]::Equals($boundaryValue, $decisionValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $boundaryGeneration = Get-FallbackTailRecheckExactField `
            -Event $Boundary `
            -Names @('recovery_boundary_generation')
        $observationReason = Get-FallbackTailRecheckExactField `
            -Event $Boundary `
            -Names @('observation_reason')
        if (-not [string]::IsNullOrWhiteSpace($boundaryGeneration) -or
            -not [string]::IsNullOrWhiteSpace($observationReason)) {
            $decisionGeneration = Get-FallbackTailRecheckExactField `
                -Event $Decision `
                -Names @('recovery_boundary_generation')
            $decisionObservationReason = Get-FallbackTailRecheckExactField `
                -Event $Decision `
                -Names @('boundary_reason', 'recovery_boundary_reason')
            if ([string]::IsNullOrWhiteSpace($boundaryGeneration) -or
                [string]::IsNullOrWhiteSpace($observationReason) -or
                -not [string]::Equals(
                    $boundaryGeneration,
                    $decisionGeneration,
                    [System.StringComparison]::OrdinalIgnoreCase) -or
                -not [string]::Equals(
                    $observationReason,
                    $decisionObservationReason,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-FallbackTailRecheckPublishedDecisionMatch {
        param(
            [Parameter(Mandatory = $true)]$Requested,
            [Parameter(Mandatory = $true)]$Decided
        )

        if (-not (Test-FallbackTailRecheckEventComplete -Event $Requested -Kind Requested) -or
            -not (Test-FallbackTailRecheckEventComplete -Event $Decided -Kind Decided) -or
            -not (Test-FallbackTailRecheckRequestMatch `
                -Hold $Requested `
                -Decision $Decided `
                -DecisionKind Decided)) {
            return $false
        }

        foreach ($field in @(
                'recovered_transport_epoch',
                'handoff_kind',
                'boundary_source_transport',
                'boundary_target_transport',
                'fallback_epoch',
                'recovery_boundary_generation',
                'boundary_reason',
                'boundary_identity',
                'original_hold_reason',
                'recheck_generation')) {
            $requestedValue = Get-FallbackTailRecheckExactField -Event $Requested -Names @($field)
            $decidedValue = Get-FallbackTailRecheckExactField -Event $Decided -Names @($field)
            if ([string]::IsNullOrWhiteSpace($requestedValue) -or
                [string]::IsNullOrWhiteSpace($decidedValue) -or
                -not [string]::Equals(
                    $requestedValue,
                    $decidedValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return (Get-FileTransferEventField -Event $Decided -Name 'decision_valid' -Default '') -eq '1' -and
               (Get-FileTransferEventField -Event $Decided -Name 'decision_status' -Default '') -in @(
                   'Held',
                   'Granted',
                   'Rejected')
    }

    function Test-FallbackTailRecheckInvalidationEvent {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Requested,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-FallbackTailRecheckIdentityMatch -Left $Anchor -Right $Candidate)) {
            return $false
        }

        $direction = Get-FallbackTailRecheckExactField -Event $Candidate -Names @('direction')
        if (-not [string]::IsNullOrWhiteSpace($direction) -and $direction -ne 'outbound') {
            return $false
        }

        if ($Candidate.EventName -in @(
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'transfer_terminal',
                'filetransfer_runtime_terminalized',
                'runtime_unlock_retry_dispatch_chain_closed')) {
            return $true
        }

        if ($Candidate.EventName -in @(
                'runtime_unlock_retry_dispatch_authority_granted',
                'runtime_unlock_retry_dispatch_authority_rejected')) {
            return $true
        }

        if ($Candidate.EventName -in @(
                'runtime_unlock_retry_dispatch_authority_held',
                'runtime_unlock_retry_dispatch_authority_hold_preserved')) {
            $requestOrdinalAliases = @(
                [pscustomobject]@{ Requested = @('contract_generation'); Candidate = @('contract_generation') },
                [pscustomobject]@{ Requested = @('retired_generation', 'retired_offer_generation'); Candidate = @('retired_generation', 'retired_offer_generation') },
                [pscustomobject]@{ Requested = @('dispatch_attempt_generation'); Candidate = @('dispatch_attempt_generation') },
                [pscustomobject]@{ Requested = @('missing_dispatch_successor_generation'); Candidate = @('missing_dispatch_successor_generation') })
            $completeOrdinalTuple = $true
            $ordinalMismatch = $false
            foreach ($aliases in $requestOrdinalAliases) {
                $requestedValue = Get-FallbackTailRecheckExactField -Event $Requested -Names $aliases.Requested
                $candidateValue = Get-FallbackTailRecheckExactField -Event $Candidate -Names $aliases.Candidate
                if ([string]::IsNullOrWhiteSpace($requestedValue) -or
                    [string]::IsNullOrWhiteSpace($candidateValue)) {
                    $completeOrdinalTuple = $false
                    break
                }
                if (-not [string]::Equals(
                        $requestedValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    $ordinalMismatch = $true
                }
            }
            if ($completeOrdinalTuple -and $ordinalMismatch) {
                return $true
            }

            if (Test-FallbackTailRecheckEventComplete -Event $Candidate -Kind Hold) {
                return -not (Test-FallbackTailRecheckRequestMatch `
                    -Hold $Requested `
                    -Decision $Candidate `
                    -DecisionKind Hold)
            }

            return $false
        }

        $requestedContract = Get-FallbackTailRecheckExactField -Event $Requested -Names @('contract_generation')
        $candidateContract = Get-FallbackTailRecheckExactField -Event $Candidate -Names @('contract_generation')
        if ($Candidate.EventName -like 'session_recovery_contract_*') {
            if ($Candidate.EventName -in @(
                    'session_recovery_contract_completed',
                    'session_recovery_contract_failed')) {
                return $true
            }

            if (-not [string]::IsNullOrWhiteSpace($candidateContract) -and
                $candidateContract -ne $requestedContract) {
                return $true
            }
        }

        if ($Candidate.EventName -notin @(
                'filetransfer_route_transitioned',
                'filetransfer_route_selected',
                'filetransfer_live_route_epoch_started',
                'filetransfer_live_route_epoch_recovered',
                'filetransfer_runtime_started',
                'filetransfer_runtime_owner_changed',
                'filetransfer_bridge_recovery_authority_granted')) {
            return $false
        }

        $tupleAliases = @(
            [pscustomobject]@{ Requested = @('source_route'); Candidate = @('route', 'current_route') },
            [pscustomobject]@{ Requested = @('source_protocol_version'); Candidate = @('protocol_version', 'current_protocol_version') },
            [pscustomobject]@{ Requested = @('source_live_route_epoch'); Candidate = @('live_route_epoch', 'current_live_route_epoch') },
            [pscustomobject]@{ Requested = @('source_runtime_generation'); Candidate = @('runtime_generation', 'current_runtime_generation') },
            [pscustomobject]@{ Requested = @('source_terminal_generation'); Candidate = @('terminal_generation', 'current_terminal_generation') },
            [pscustomobject]@{ Requested = @('source_leg_generation'); Candidate = @('leg_generation', 'current_leg_generation') },
            [pscustomobject]@{ Requested = @('source_route_publication_generation'); Candidate = @('route_publication_generation', 'source_publication_generation') },
            [pscustomobject]@{ Requested = @('bridge_decision_generation'); Candidate = @('bridge_decision_generation') })
        foreach ($aliases in $tupleAliases) {
            $requestedValue = Get-FallbackTailRecheckExactField -Event $Requested -Names $aliases.Requested
            $candidateValue = Get-FallbackTailRecheckExactField -Event $Candidate -Names $aliases.Candidate
            if ([string]::IsNullOrWhiteSpace($candidateValue)) {
                continue
            }

            if ([string]::IsNullOrWhiteSpace($requestedValue) -or
                -not [string]::Equals(
                    $requestedValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $true
            }
        }

        return $false
    }

    function Test-FallbackTailRecheckAuthorityResultMatchesPublishedDecision {
        param(
            [Parameter(Mandatory = $true)]$Hold,
            [Parameter(Mandatory = $true)]$Boundary,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $expectedStatus = if ($Candidate.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted') {
            'Granted'
        }
        elseif ($Candidate.EventName -eq 'runtime_unlock_retry_dispatch_authority_rejected') {
            'Rejected'
        }
        else {
            return $false
        }

        $candidateSequence = [int64]$Candidate.Sequence
        foreach ($requested in @($recheckRequestedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$Hold.Sequence -and
                    [int64]$_.Sequence -lt $candidateSequence -and
                    (Test-FallbackTailRecheckRequestMatch -Hold $Hold -Decision $_) -and
                    (Test-FallbackTailRecheckBoundaryMatch -Boundary $Boundary -Decision $_)
                })) {
            $decided = @($recheckDecidedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$requested.Sequence -and
                    [int64]$_.Sequence -lt $candidateSequence -and
                    (Test-FallbackTailRecheckPublishedDecisionMatch -Requested $requested -Decided $_) -and
                    [string]::Equals(
                        (Get-FallbackTailRecheckExactField -Event $_ -Names @('decision_status')),
                        $expectedStatus,
                        [System.StringComparison]::OrdinalIgnoreCase)
                } | Sort-Object Sequence | Select-Object -First 1)
            if ($decided.Count -eq 0) {
                continue
            }

            $tupleMatches = $true
            foreach ($aliases in @(
                    [pscustomobject]@{ Requested = @('direction'); Candidate = @('direction') },
                    [pscustomobject]@{ Requested = @('contract_generation'); Candidate = @('contract_generation') },
                    [pscustomobject]@{ Requested = @('retired_generation', 'retired_offer_generation'); Candidate = @('retired_generation', 'retired_offer_generation') },
                    [pscustomobject]@{ Requested = @('dispatch_attempt_generation'); Candidate = @('dispatch_attempt_generation') },
                    [pscustomobject]@{ Requested = @('missing_dispatch_successor_generation'); Candidate = @('missing_dispatch_successor_generation') })) {
                $requestedValue = Get-FallbackTailRecheckExactField -Event $requested -Names $aliases.Requested
                $candidateValue = Get-FallbackTailRecheckExactField -Event $Candidate -Names $aliases.Candidate
                if ([string]::IsNullOrWhiteSpace($requestedValue) -or
                    [string]::IsNullOrWhiteSpace($candidateValue) -or
                    -not [string]::Equals(
                        $requestedValue,
                        $candidateValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    $tupleMatches = $false
                    break
                }
            }
            if ($tupleMatches) {
                return $true
            }
        }

        return $false
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenCandidateKeys = @{}

    foreach ($boundary in $tailUnblockedEvents) {
        $boundarySequence = [int64]$boundary.Sequence
        $matchingHolds = @($heldEvents | Where-Object {
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FallbackTailRecheckIdentityMatch -Left $_ -Right $boundary) -and
            (Test-FallbackTailRecheckHoldEligible -Event $_) -and
            (Get-FallbackTailRecheckExactField -Event $_ -Names @('direction', 'attempted_source_publication_direction')) -eq 'outbound' -and
            (Get-FallbackTailRecheckExactField -Event $_ -Names @('source_route', 'source_publication_route', 'attempted_source_publication_route', 'route')) -eq 'post_tuna_fallback_v6' -and
            (Get-FallbackTailRecheckExactField -Event $_ -Names @('source_protocol_version', 'source_publication_protocol_version', 'attempted_source_publication_protocol_version', 'protocol_version')) -eq '6'
        } | Sort-Object Sequence -Descending)
        if ($matchingHolds.Count -eq 0) {
            continue
        }

        $hold = $matchingHolds[0]
        $holdSequence = [int64]$hold.Sequence
        $pairedYield = @($pairedYieldEvents | Where-Object {
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FallbackTailRecheckIdentityMatch -Left $_ -Right $boundary)
        } | Sort-Object Sequence -Descending | Select-Object -First 1)
        if ($pairedYield.Count -eq 0) {
            continue
        }

        $holdRoute = Get-FallbackTailRecheckField `
            -Event $hold `
            -Names @('source_route', 'source_publication_route', 'attempted_source_publication_route', 'route')
        $holdProtocol = Get-FallbackTailRecheckField `
            -Event $hold `
            -Names @('source_protocol_version', 'source_publication_protocol_version', 'attempted_source_publication_protocol_version', 'protocol_version')
        $holdDirection = Get-FallbackTailRecheckField `
            -Event $hold `
            -Names @('direction', 'attempted_source_publication_direction')
        if ($holdRoute -ne 'post_tuna_fallback_v6' -or
            $holdProtocol -ne '6' -or
            $holdDirection -ne 'outbound') {
            continue
        }

        $ownerTupleMatches = $true
        foreach ($aliases in @(
                [pscustomobject]@{ Hold = @('source_live_route_epoch', 'source_publication_live_route_epoch', 'attempted_source_publication_live_route_epoch', 'live_route_epoch'); Paired = @('live_route_epoch') },
                [pscustomobject]@{ Hold = @('source_runtime_generation', 'source_publication_runtime_generation', 'attempted_source_publication_runtime_generation', 'runtime_generation'); Paired = @('runtime_generation') },
                [pscustomobject]@{ Hold = @('source_terminal_generation', 'source_publication_terminal_generation', 'attempted_source_publication_terminal_generation', 'terminal_generation'); Paired = @('terminal_generation') },
                [pscustomobject]@{ Hold = @('source_leg_generation', 'source_publication_leg_generation', 'attempted_source_publication_leg_generation', 'leg_generation'); Paired = @('leg_generation') })) {
            $holdValue = Get-FallbackTailRecheckField -Event $hold -Names $aliases.Hold
            $pairedValue = Get-FallbackTailRecheckField -Event $pairedYield[0] -Names $aliases.Paired
            if ([string]::IsNullOrWhiteSpace($holdValue) -or
                [string]::IsNullOrWhiteSpace($pairedValue) -or
                $holdValue -ne $pairedValue) {
                $ownerTupleMatches = $false
                break
            }
        }
        if (-not $ownerTupleMatches) {
            continue
        }

        $invalidatedBeforeBoundary = @($Events | Where-Object {
            if ([int64]$_.Sequence -le $holdSequence -or
                [int64]$_.Sequence -ge $boundarySequence -or
                -not (Test-FallbackTailRecheckInvalidationEvent `
                    -Anchor $hold `
                    -Requested $hold `
                    -Candidate $_)) {
                return $false
            }

            return -not (Test-FallbackTailRecheckAuthorityResultMatchesPublishedDecision `
                -Hold $hold `
                -Boundary $boundary `
                -Candidate $_)
        } | Select-Object -First 1).Count -gt 0
        if ($invalidatedBeforeBoundary) {
            continue
        }

        $rawCandidates.Add($boundary) | Out-Null
        $requestKeyParts = @(
            Get-FallbackTailRecheckField -Event $hold -Names @('session_id') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('transfer_id') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('direction', 'attempted_source_publication_direction') -Default 'outbound'
            Get-FallbackTailRecheckField -Event $hold -Names @('contract_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('retired_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('dispatch_attempt_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('missing_dispatch_successor_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $hold -Names @('predecessor_authority_id') -Default '(none)'
            Get-FallbackTailRecheckField -Event $hold -Names @('source_route_publication_generation', 'source_publication_generation', 'attempted_source_publication_route_publication_generation') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('transport_epoch') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('handoff_kind') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('source_transport') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('target_transport') -Default '(missing)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('recovery_boundary_generation') -Default '(legacy)'
            Get-FallbackTailRecheckField -Event $boundary -Names @('observation_reason') -Default '(legacy)'
        )
        $candidateKey = $requestKeyParts -join '|'
        if ($seenCandidateKeys.ContainsKey($candidateKey)) {
            continue
        }

        $seenCandidateKeys[$candidateKey] = $true
        $distinctCandidates.Add($boundary) | Out-Null
        $firstBoundaryInvalidation = @($Events | Where-Object {
            [int64]$_.Sequence -gt $boundarySequence -and
            (Test-FallbackTailRecheckInvalidationEvent `
                -Anchor $hold `
                -Requested $hold `
                -Candidate $_)
        } | Sort-Object Sequence | Select-Object -First 1)
        $boundaryInvalidationSequence = if ($firstBoundaryInvalidation.Count -gt 0) {
            [int64]$firstBoundaryInvalidation[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        $matchingRequested = @($recheckRequestedEvents | Where-Object {
            [int64]$_.Sequence -gt $holdSequence -and
            [int64]$_.Sequence -lt $boundaryInvalidationSequence -and
            (Test-FallbackTailRecheckRequestMatch -Hold $hold -Decision $_) -and
            (Test-FallbackTailRecheckBoundaryMatch -Boundary $boundary -Decision $_)
        } | Sort-Object Sequence | Select-Object -First 1)
        $matchingDecision = @()
        if ($matchingRequested.Count -gt 0) {
            $requested = $matchingRequested[0]
            $requestedSequence = [int64]$requested.Sequence
            $firstInvalidation = @($Events | Where-Object {
                [int64]$_.Sequence -gt $requestedSequence -and
                (Test-FallbackTailRecheckInvalidationEvent `
                    -Anchor $hold `
                    -Requested $requested `
                    -Candidate $_)
            } | Sort-Object Sequence | Select-Object -First 1)
            $invalidationSequence = if ($firstInvalidation.Count -gt 0) {
                [int64]$firstInvalidation[0].Sequence
            }
            else {
                [int64]::MaxValue
            }
            $matchingDecision = @($recheckDecidedEvents | Where-Object {
                [int64]$_.Sequence -gt $requestedSequence -and
                [int64]$_.Sequence -lt $invalidationSequence -and
                (Test-FallbackTailRecheckPublishedDecisionMatch `
                    -Requested $requested `
                    -Decided $_)
            } | Sort-Object Sequence | Select-Object -First 1)
            if ($Phase2ProtocolObserved -and
                $matchingDecision.Count -gt 0 -and
                (Get-FallbackTailRecheckExactField `
                    -Event $matchingDecision[0] `
                    -Names @('decision_status')) -eq 'Granted') {
                $matchingCommittedGrant = @($EffectiveGrantEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$matchingDecision[0].Sequence -and
                    (Test-FallbackTailRecheckAuthorityResultMatchesPublishedDecision `
                        -Hold $hold `
                        -Boundary $boundary `
                        -Candidate $_)
                } | Sort-Object Sequence | Select-Object -First 1)
                if ($matchingCommittedGrant.Count -eq 0) {
                    $matchingDecision = @()
                }
            }
        }
        if ($matchingDecision.Count -gt 0) {
            $recoveredCandidates.Add($boundary) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($boundary) | Out-Null
        }
    }

    $verdict = if ($distinctCandidates.Count -eq 0) {
        'none'
    }
    elseif ($unresolvedCandidates.Count -eq 0) {
        'pass'
    }
    else {
        'fail'
    }

    return [pscustomobject]@{
        RequestedCount = $recheckRequestedEvents.Count
        DecidedCount = $recheckDecidedEvents.Count
        DiscardedCount = $recheckDiscardedEvents.Count
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRegularV4RepairProjectionRange {
    param([Parameter(Mandatory = $true)]$Event)

    $startText = ''
    foreach ($name in @(
            'projected_first_start_chunk_index',
            'projected_start_chunk_index',
            'first_start_chunk_index',
            'start_chunk_index',
            'frontier_chunk_index',
            'contiguous_committed_chunk_index')) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if ($value -match '^\d+$') {
            $startText = $value
            break
        }
    }

    $endText = ''
    foreach ($name in @(
            'projected_last_end_chunk_exclusive',
            'projected_end_chunk_exclusive',
            'last_end_chunk_exclusive',
            'end_chunk_exclusive')) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if ($value -match '^\d+$') {
            $endText = $value
            break
        }
    }

    $rangesText = ''
    foreach ($name in @(
            'repair_attempt_ranges',
            'projected_ranges',
            'repair_projection_projected_ranges',
            'source_ranges',
            'repair_projection_source_ranges')) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
            $rangesText = $value
            break
        }
    }
    $parsedRanges = New-Object System.Collections.Generic.List[object]
    if (-not [string]::IsNullOrWhiteSpace($rangesText)) {
        $rangeStart = [int64]::MaxValue
        $rangeEnd = -1L
        foreach ($rangeToken in @($rangesText -split ',')) {
            if ($rangeToken.Trim() -notmatch '^(?<start>\d+):(?<count>\d+)$') {
                continue
            }
            $tokenStart = [int64]$Matches['start']
            $tokenCount = [int64]$Matches['count']
            if ($tokenCount -le 0) {
                continue
            }
            $parsedRanges.Add([pscustomobject]@{
                    Valid = $true
                    Start = $tokenStart
                    End = $tokenStart + $tokenCount
                }) | Out-Null
            if ($tokenStart -lt $rangeStart) {
                $rangeStart = $tokenStart
            }
            if (($tokenStart + $tokenCount) -gt $rangeEnd) {
                $rangeEnd = $tokenStart + $tokenCount
            }
        }
        if ($rangeStart -ne [int64]::MaxValue -and $rangeEnd -gt $rangeStart) {
            $startText = [string]$rangeStart
            $endText = [string]$rangeEnd
        }
    }

    $repairKey = ''
    foreach ($name in @(
            'repair_attempt_request_key',
            'projected_repair_request_key',
            'repair_projection_projected_key',
            'source_repair_request_key',
            'repair_projection_source_key',
            'repair_request_key')) {
        $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
        if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
            $repairKey = $value
            break
        }
    }
    if ($startText -notmatch '^\d+$' -or $endText -notmatch '^\d+$') {
        [object[]]$keyParts = @($repairKey -split ':')
        if ($keyParts.Count -ge 4) {
            $keyStartText = [string]$keyParts[$keyParts.Count - 4]
            $keyCountText = [string]$keyParts[$keyParts.Count - 3]
            $keyFrontierText = [string]$keyParts[$keyParts.Count - 2]
            $keyHighestText = [string]$keyParts[$keyParts.Count - 1]
            if ($keyStartText -match '^\d+$' -and
                $keyCountText -match '^\d+$' -and
                $keyFrontierText -match '^\d+$' -and
                $keyHighestText -match '^-?\d+$') {
                $keyStart = [int64]$keyStartText
                $keyCount = [int64]$keyCountText
                if ($startText -notmatch '^\d+$') {
                    $startText = [string]$keyStart
                }
                if ($endText -notmatch '^\d+$') {
                    $endText = [string]($keyStart + $keyCount)
                }
            }
        }
    }

    if ($startText -match '^\d+$' -and $endText -notmatch '^\d+$') {
        foreach ($name in @('projected_chunk_count', 'projected_requested_chunk_count', 'requested_chunk_count', 'pending_repair_count')) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if ($value -match '^\d+$' -and [int64]$value -gt 0) {
                $endText = [string]([int64]$startText + [int64]$value)
                break
            }
        }
    }

    $valid = $startText -match '^\d+$' -and
        $endText -match '^\d+$' -and
        [int64]$endText -gt [int64]$startText
    [object[]]$exactRanges = if ($parsedRanges.Count -gt 0) {
        @($parsedRanges.ToArray() | ForEach-Object {
                [pscustomobject]@{
                    Valid = $true
                    Start = [int64]$_.Start
                    End = [int64]$_.End
                    RepairKey = if ([string]::IsNullOrWhiteSpace($repairKey)) { '(none)' } else { $repairKey }
                }
            })
    }
    elseif ($valid) {
        @([pscustomobject]@{
                Valid = $true
                Start = [int64]$startText
                End = [int64]$endText
                RepairKey = if ([string]::IsNullOrWhiteSpace($repairKey)) { '(none)' } else { $repairKey }
            })
    }
    else {
        @()
    }
    return [pscustomobject]@{
        Valid = $valid
        Start = if ($startText -match '^\d+$') { [int64]$startText } else { -1L }
        End = if ($endText -match '^\d+$') { [int64]$endText } else { -1L }
        RepairKey = if ([string]::IsNullOrWhiteSpace($repairKey)) { '(none)' } else { $repairKey }
        Ranges = $exactRanges
    }
}

function Get-FileTransferRegularV4RepairProjectionScopeField {
    param(
        [Parameter(Mandatory = $true)]$Event,
        [Parameter(Mandatory = $true)][string]$Name,
        [string]$Default = ''
    )

    [string[]]$names = switch ($Name) {
        'data_session_generation' { @('data_session_generation', 'repair_projection_data_session_generation') }
        'authority_id' { @('authority_id', 'repair_projection_authority_id') }
        'predecessor_authority_id' { @('predecessor_authority_id', 'repair_projection_predecessor_authority_id') }
        default { @($Name) }
    }
    foreach ($candidateName in $names) {
        $value = Get-FileTransferEventField -Event $Event -Name $candidateName -Default ''
        if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
            return $value
        }
    }
    return $Default
}

function Test-FileTransferRegularV4RepairProjectionScopeMatch {
    param(
        [Parameter(Mandatory = $true)]$Anchor,
        [Parameter(Mandatory = $true)]$Candidate
    )

    if (-not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $Anchor -Candidate $Candidate)) {
        return $false
    }
    foreach ($name in @(
            'route',
            'protocol_version',
            'live_route_epoch',
            'runtime_generation',
            'terminal_generation',
            'leg_generation',
            'transport_epoch',
            'bridge_recovery_generation',
            'bridge_decision_generation',
            'route_publication_generation',
            'route_commit_generation',
            'data_session_generation')) {
        $left = Get-FileTransferRegularV4RepairProjectionScopeField -Event $Anchor -Name $name
        $right = Get-FileTransferRegularV4RepairProjectionScopeField -Event $Candidate -Name $name
        if (-not [string]::IsNullOrWhiteSpace($left) -and
            -not [string]::IsNullOrWhiteSpace($right) -and
            -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }
    }
    return $true
}

function Get-FileTransferRegularV4RepairProjectionScopeKey {
    param(
        [Parameter(Mandatory = $true)]$Event,
        [int64]$Frontier = -1L
    )

    $direction = Get-FileTransferEventField -Event $Event -Name 'direction' -Default 'inbound'
    if ($direction -in @('', 'receiver')) {
        $direction = 'inbound'
    }
    $parts = @(
        (Get-FileTransferEventField -Event $Event -Name 'session_id' -Default '(none)'),
        (Get-FileTransferEventField -Event $Event -Name 'transfer_id' -Default '(none)'),
        $direction,
        [string]$Frontier,
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'route' -Default 'regular_nkn_v4_fast'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'protocol_version' -Default '4'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'live_route_epoch' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'runtime_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'terminal_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'leg_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'transport_epoch' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'bridge_recovery_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'bridge_decision_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'route_publication_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'route_commit_generation' -Default '0'),
        (Get-FileTransferRegularV4RepairProjectionScopeField -Event $Event -Name 'data_session_generation' -Default '0')
    )
    return ($parts -join '|').ToLowerInvariant()
}

