function Get-FileTransferRegularV4FrontierTailRepairRange {
    param([Parameter(Mandatory = $true)]$Event)

    $range = Get-FileTransferRegularV4RepairProjectionRange -Event $Event
    if ($range.Valid) {
        return $range
    }

    if ($Event.EventName -notin @(
            'filetransfer_regular_v4_frontier_tail_repair_state_authorized',
            'filetransfer_regular_v4_frontier_tail_repair_state_rejected')) {
        return $range
    }

    $rangesText = Get-FileTransferEventField -Event $Event -Name 'ranges' -Default ''
    if ($rangesText -notmatch '^(?<start>\d+):(?<count>\d+)$' -or [int64]$Matches['count'] -le 0) {
        return $range
    }

    $start = [int64]$Matches['start']
    $end = $start + [int64]$Matches['count']
    return [pscustomobject]@{
        Valid = $true
        Start = $start
        End = $end
        RepairKey = Get-FileTransferEventField -Event $Event -Name 'repair_request_key' -Default '(none)'
        Ranges = @([pscustomobject]@{
                Valid = $true
                Start = $start
                End = $end
                RepairKey = Get-FileTransferEventField -Event $Event -Name 'repair_request_key' -Default '(none)'
            })
    }
}

function Get-FileTransferRegularV4FrontierTailRepairStatePublicationProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$bindingEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_binding_committed' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'inbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'binding_state' -Default '') -eq 'Installed' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -gt 0 -and
        -not [string]::IsNullOrWhiteSpace(
            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id'))
    })
    [object[]]$rejectionEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'inbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'coordinator_projection_authority_missing'
    })
    [object[]]$authorizedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_tail_repair_state_authorized' -and
        (Get-FileTransferEventField -Event $_ -Name 'repair_publication_kind' -Default '') -eq
            'attempt_scoped_frontier_tail'
    })
    [object[]]$stateSentEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_v4_state_sent' -and
        (Get-FileTransferEventField -Event $_ -Name 'repair_publication_kind' -Default '') -eq
            'attempt_scoped_frontier_tail'
    })
    [object[]]$stateReceivedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_v4_state_received' -and
        (Get-FileTransferEventField -Event $_ -Name 'applied' -Default '0') -eq '1' -and
        (Get-FileTransferEventInt64Field -Event $_ -Name 'missing_range_count' -Default 0) -gt 0
    })
    [object[]]$peerAuthorityEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound'
    })
    [object[]]$dispatchEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_dispatched' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound'
    })
    [object[]]$pressureRecoveryHandoffEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_committed' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'inbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'StaleRejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq
            'bridge_receive_stall_recovery_pressure_handoff' -and
        (Get-FileTransferEventField -Event $_ -Name 'apply_status' -Default '') -in @('Applied', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'current_authority_cleared' -Default '0') -eq '1'
    })

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $metadataBySequence = @{}
    $seenTuples = @{}

    foreach ($rejection in $rejectionEvents) {
        $rejectionSequence = [int64]$rejection.Sequence
        $rejectionRange = Get-FileTransferRegularV4FrontierTailRepairRange -Event $rejection
        $frontier = Get-FileTransferEventInt64Field -Event $rejection -Name 'frontier_chunk_index' -Default -1
        $durableHighest = Get-FileTransferEventInt64Field `
            -Event $rejection `
            -Name 'durable_received_highest_chunk_index' `
            -Default -1
        $repairKey = Get-FileTransferEventField `
            -Event $rejection `
            -Name 'source_repair_request_key' `
            -Default ''
        if (-not $rejectionRange.Valid -or
            $frontier -lt 0 -or
            $durableHighest -ge $frontier -or
            [string]::IsNullOrWhiteSpace($repairKey)) {
            continue
        }

        [object[]]$matchingBindings = @($bindingEvents | Where-Object {
            $candidateRange = Get-FileTransferRegularV4FrontierTailRepairRange -Event $_
            [int64]$_.Sequence -lt $rejectionSequence -and
            (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $rejection -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq $repairKey -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'frontier_chunk_index' -Default -1) -eq $frontier -and
            $candidateRange.Valid -and
            [int64]$candidateRange.Start -eq [int64]$rejectionRange.Start -and
            [int64]$candidateRange.End -eq [int64]$rejectionRange.End
        } | Sort-Object Sequence, LineNumber)
        $activeBindings = New-Object System.Collections.Generic.List[object]
        foreach ($candidateBinding in $matchingBindings) {
            $candidateAuthorityId = Get-FileTransferRegularV4RepairProjectionScopeField `
                -Event $candidateBinding `
                -Name 'authority_id'
            $candidateInstallGeneration = Get-FileTransferEventInt64Field `
                -Event $candidateBinding `
                -Name 'install_generation' `
                -Default 0
            $retiredBeforeRejection = @($orderedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$candidateBinding.Sequence -and
                [int64]$_.Sequence -lt $rejectionSequence -and
                $_.EventName -in @(
                    'filetransfer_regular_v4_frontier_repair_pressure_binding_retired',
                    'filetransfer_regular_v4_frontier_repair_pressure_binding_invalidated') -and
                (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq
                    $candidateAuthorityId -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -eq
                    $candidateInstallGeneration
            }).Count -gt 0
            if (-not $retiredBeforeRejection) {
                $activeBindings.Add($candidateBinding) | Out-Null
            }
        }
        [object[]]$bindingTuples = @($activeBindings.ToArray() | Group-Object {
            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') + '|' +
                (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0)
        })
        if ($bindingTuples.Count -ne 1) {
            continue
        }
        $binding = @($bindingTuples[0].Group | Sort-Object Sequence, LineNumber -Descending | Select-Object -First 1)[0]
        $authorityId = Get-FileTransferRegularV4RepairProjectionScopeField `
            -Event $binding `
            -Name 'authority_id'
        $installGeneration = Get-FileTransferEventInt64Field `
            -Event $binding `
            -Name 'install_generation' `
            -Default 0
        $rangeFingerprint = Get-FileTransferEventField `
            -Event $rejection `
            -Name 'required_range_fingerprint' `
            -Default '(none)'

        $priorAuthorization = @($authorizedEvents | Where-Object {
            $candidateRange = Get-FileTransferRegularV4FrontierTailRepairRange -Event $_
            [int64]$_.Sequence -gt [int64]$binding.Sequence -and
            [int64]$_.Sequence -lt $rejectionSequence -and
            (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $binding -Candidate $_) -and
            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq $authorityId -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -eq $installGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq $repairKey -and
            $candidateRange.Valid -and
            [int64]$candidateRange.Start -eq [int64]$rejectionRange.Start -and
            [int64]$candidateRange.End -eq [int64]$rejectionRange.End
        } | Select-Object -First 1)
        if ($priorAuthorization.Count -gt 0) {
            continue
        }

        $rawCandidates.Add($rejection) | Out-Null
        $tuple = (@(
                (Get-FileTransferEventField -Event $binding -Name 'session_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $binding -Name 'transfer_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $binding -Name 'direction' -Default '(none)'),
                $authorityId,
                $installGeneration,
                $repairKey,
                [int64]$rejectionRange.Start,
                [int64]$rejectionRange.End,
                $rangeFingerprint,
                (Get-FileTransferRegularV4RepairProjectionScopeKey -Event $rejection -Frontier $frontier)
            ) -join '|').ToLowerInvariant()
        if ($seenTuples.ContainsKey($tuple)) {
            continue
        }
        $seenTuples[$tuple] = $true
        $distinctCandidates.Add($rejection) | Out-Null
        $metadataBySequence[[string]$rejectionSequence] = [pscustomobject]@{
            Binding = $binding
            AuthorityId = $authorityId
            InstallGeneration = $installGeneration
            RepairKey = $repairKey
            Range = $rejectionRange
            RangeFingerprint = $rangeFingerprint
            Frontier = $frontier
        }
    }

    foreach ($candidate in $distinctCandidates.ToArray()) {
        $candidateSequence = [int64]$candidate.Sequence
        $metadata = $metadataBySequence[[string]$candidateSequence]
        $binding = $metadata.Binding
        $range = $metadata.Range
        $frontier = [int64]$metadata.Frontier
        $pressureRecoveryResolution = @($pressureRecoveryHandoffEvents | Where-Object {
            [int64]$_.Sequence -gt $candidateSequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $binding `
                -Candidate $_) -and
            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq
                $metadata.AuthorityId -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -eq
                [int64]$metadata.InstallGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq
                $metadata.RepairKey -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_decision_generation' -Default 0) -gt 0 -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'recovery_liveness_lease_generation' -Default 0) -gt 0
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $scopeBoundary = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt $candidateSequence -and
            (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $binding -Candidate $_) -and
            (
                ($_.EventName -in @(
                    'filetransfer_regular_v4_frontier_repair_pressure_binding_retired',
                    'filetransfer_regular_v4_frontier_repair_pressure_binding_invalidated') -and
                    (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq
                        $metadata.AuthorityId -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -eq
                        [int64]$metadata.InstallGeneration) -or
                $_.EventName -in @(
                    'transfer_terminal', 'file_transfer_inbound_terminal', 'file_transfer_outbound_terminal',
                    'filetransfer_runtime_terminalized') -or
                (
                    (
                        [string]::IsNullOrWhiteSpace(
                            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '')) -or
                        [string]::Equals(
                            (Get-FileTransferEventField -Event $binding -Name 'direction' -Default ''),
                            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default ''),
                            [System.StringComparison]::OrdinalIgnoreCase)
                    ) -and
                    (Test-FileTransferRegularV4RepairProjectionScopeReplacement -Anchor $binding -Candidate $_)
                )
            )
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $boundarySequence = if ($scopeBoundary.Count -gt 0) {
            [int64]$scopeBoundary[0].Sequence
        }
        else {
            [int64]::MaxValue
        }

        $durableResolution = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt $candidateSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $binding -Candidate $_) -and
            (
                ($_.EventName -eq 'filetransfer_v4_state_sent' -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'contiguous_committed_chunk_index' -Default -1) -gt
                        $frontier) -or
                ($_.EventName -eq 'filetransfer_regular_v4_frontier_repair_progress_observed' -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'committed_frontier_after' -Default -1) -gt
                        $frontier) -or
                ($_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_cleared' -and
                    (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -in @(
                        'frontier_advanced', 'frontier_advanced_gap_resolved', 'frontier_complete',
                        'range_filled', 'durable_fill', 'repair_filled'))
            )
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)

        $authorization = @($authorizedEvents | Where-Object {
            $candidateRange = Get-FileTransferRegularV4FrontierTailRepairRange -Event $_
            [int64]$_.Sequence -gt $candidateSequence -and
            [int64]$_.Sequence -lt $boundarySequence -and
            (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $binding -Candidate $_) -and
            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq
                $metadata.AuthorityId -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'install_generation' -Default 0) -eq
                [int64]$metadata.InstallGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq
                $metadata.RepairKey -and
            (
                $metadata.RangeFingerprint -in @('', '(none)', 'none') -or
                (Get-FileTransferEventField -Event $_ -Name 'range_fingerprint' -Default '') -eq
                    $metadata.RangeFingerprint
            ) -and
            $candidateRange.Valid -and
            [int64]$candidateRange.Start -eq [int64]$range.Start -and
            [int64]$candidateRange.End -eq [int64]$range.End
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)

        $dispatchResolution = @()
        if ($authorization.Count -gt 0) {
            $authorization = $authorization[0]
            $stateSent = @($stateSentEvents | Where-Object {
                $candidateState = $_
                $candidateRange = Get-FileTransferRegularV4FrontierTailRepairRange -Event $candidateState
                $credit = Get-FileTransferEventInt64Field `
                    -Event $candidateState `
                    -Name 'credit_until_chunk_index_exclusive' `
                    -Default -1
                $copiedAuthorityId = Get-FileTransferEventField `
                    -Event $candidateState `
                    -Name 'repair_attempt_authority_id' `
                    -Default ''
                $copiedAuthorityAbsent = $copiedAuthorityId -in @(
                    '', '(none)', 'none', '[redacted]', 'redacted', '(redacted)')
                $authorityCorroborated = if (-not $copiedAuthorityAbsent) {
                    $copiedAuthorityId -eq $metadata.AuthorityId
                }
                else {
                    [object[]]$matchingCanonicalAuthorizations = @($authorizedEvents | Where-Object {
                        $candidateAuthorization = $_
                        $authorizationRange = Get-FileTransferRegularV4FrontierTailRepairRange `
                            -Event $candidateAuthorization
                        [int64]$candidateAuthorization.Sequence -gt $candidateSequence -and
                        [int64]$candidateAuthorization.Sequence -lt [int64]$candidateState.Sequence -and
                        (Test-FileTransferRegularV4RepairProjectionScopeMatch `
                            -Anchor $candidateState `
                            -Candidate $candidateAuthorization) -and
                        (Get-FileTransferEventInt64Field `
                            -Event $candidateAuthorization `
                            -Name 'install_generation' `
                            -Default 0) -eq [int64]$metadata.InstallGeneration -and
                        (Get-FileTransferEventField `
                            -Event $candidateAuthorization `
                            -Name 'repair_request_key' `
                            -Default '') -eq $metadata.RepairKey -and
                        (
                            $metadata.RangeFingerprint -in @('', '(none)', 'none') -or
                            (Get-FileTransferEventField `
                                -Event $candidateAuthorization `
                                -Name 'range_fingerprint' `
                                -Default '') -eq $metadata.RangeFingerprint
                        ) -and
                        $authorizationRange.Valid -and
                        [int64]$authorizationRange.Start -eq [int64]$range.Start -and
                        [int64]$authorizationRange.End -eq [int64]$range.End
                    })
                    [object[]]$canonicalAuthorityTuples = @($matchingCanonicalAuthorizations | Group-Object {
                        (@(
                                (Get-FileTransferRegularV4RepairProjectionScopeField `
                                    -Event $_ `
                                    -Name 'authority_id'),
                                (Get-FileTransferEventInt64Field `
                                    -Event $_ `
                                    -Name 'install_generation' `
                                    -Default 0),
                                (Get-FileTransferEventField `
                                    -Event $_ `
                                    -Name 'repair_request_key' `
                                    -Default ''),
                                (Get-FileTransferRegularV4RepairProjectionScopeKey `
                                    -Event $_ `
                                    -Frontier $frontier)
                            ) -join '|').ToLowerInvariant()
                    })
                    $canonicalAuthorityTuples.Count -eq 1 -and
                        (Get-FileTransferRegularV4RepairProjectionScopeField `
                            -Event $canonicalAuthorityTuples[0].Group[0] `
                            -Name 'authority_id') -eq $metadata.AuthorityId
                }
                [int64]$candidateState.Sequence -gt [int64]$authorization.Sequence -and
                [int64]$candidateState.Sequence -lt $boundarySequence -and
                (Test-FileTransferRegularV4RepairProjectionScopeMatch `
                    -Anchor $binding `
                    -Candidate $candidateState) -and
                $authorityCorroborated -and
                (Get-FileTransferEventInt64Field `
                    -Event $candidateState `
                    -Name 'repair_attempt_install_generation' `
                    -Default 0) -eq
                    [int64]$metadata.InstallGeneration -and
                (Get-FileTransferEventField `
                    -Event $candidateState `
                    -Name 'repair_attempt_request_key' `
                    -Default '') -eq
                    $metadata.RepairKey -and
                (
                    $metadata.RangeFingerprint -in @('', '(none)', 'none') -or
                    (Get-FileTransferEventField `
                        -Event $candidateState `
                        -Name 'repair_attempt_range_fingerprint' `
                        -Default '') -eq
                        $metadata.RangeFingerprint
                ) -and
                (Get-FileTransferEventInt64Field `
                    -Event $candidateState `
                    -Name 'missing_range_count' `
                    -Default 0) -gt 0 -and
                $credit -eq [int64]$range.End -and
                $candidateRange.Valid -and
                [int64]$candidateRange.Start -eq [int64]$range.Start -and
                [int64]$candidateRange.End -eq [int64]$range.End
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($stateSent.Count -gt 0) {
                $stateSent = $stateSent[0]
                $stateEpoch = Get-FileTransferEventField -Event $stateSent -Name 'epoch' -Default ''
                $stateReceived = @($stateReceivedEvents | Where-Object {
                    $candidateRange = Get-FileTransferRegularV4FrontierTailRepairRange -Event $_
                    [int64]$_.Sequence -gt [int64]$stateSent.Sequence -and
                    [int64]$_.Sequence -lt $boundarySequence -and
                    (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $stateSent -Candidate $_) -and
                    -not [string]::IsNullOrWhiteSpace($stateEpoch) -and
                    (Get-FileTransferEventField -Event $_ -Name 'epoch' -Default '') -eq $stateEpoch -and
                    $candidateRange.Valid -and
                    [int64]$candidateRange.Start -eq [int64]$range.Start -and
                    [int64]$candidateRange.End -eq [int64]$range.End
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                if ($stateReceived.Count -gt 0) {
                    $stateReceived = $stateReceived[0]
                    $peerAuthority = @($peerAuthorityEvents | Where-Object {
                        $candidateRange = Get-FileTransferRegularV4FrontierTailRepairRange -Event $_
                        [int64]$_.Sequence -gt [int64]$stateReceived.Sequence -and
                        [int64]$_.Sequence -lt $boundarySequence -and
                        (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $stateReceived -Candidate $_) -and
                        (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq
                            $metadata.RepairKey -and
                        $candidateRange.Valid -and
                        [int64]$candidateRange.Start -eq [int64]$range.Start -and
                        [int64]$candidateRange.End -eq [int64]$range.End -and
                        -not [string]::IsNullOrWhiteSpace(
                            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id'))
                    } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                    if ($peerAuthority.Count -gt 0) {
                        $peerAuthority = $peerAuthority[0]
                        $peerAuthorityId = Get-FileTransferRegularV4RepairProjectionScopeField `
                            -Event $peerAuthority `
                            -Name 'authority_id'
                        $dispatchResolution = @($dispatchEvents | Where-Object {
                            $candidateRange = Get-FileTransferRegularV4FrontierTailRepairRange -Event $_
                            [int64]$_.Sequence -gt [int64]$peerAuthority.Sequence -and
                            [int64]$_.Sequence -lt $boundarySequence -and
                            (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $peerAuthority -Candidate $_) -and
                            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq
                                $peerAuthorityId -and
                            (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq
                                $metadata.RepairKey -and
                            $candidateRange.Valid -and
                            [int64]$candidateRange.Start -eq [int64]$range.Start -and
                            [int64]$candidateRange.End -eq [int64]$range.End
                        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                    }
                }
            }
        }

        if ($pressureRecoveryResolution.Count -gt 0 -or
            $durableResolution.Count -gt 0 -or
            $dispatchResolution.Count -gt 0) {
            $recoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) { 'fail' } elseif ($distinctCandidates.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRegularV4RepairProjectionReauthorizationProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [object[]]$invalidationEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'coordinator_action_BridgeReceiveStallRecovery' -and
        -not [string]::IsNullOrWhiteSpace(
            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id'))
    })
    [object[]]$bridgeAuthorityEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_bridge_recovery_authority_granted' -and
        (Get-FileTransferEventField -Event $_ -Name 'action_kind' -Default '') -eq 'BridgeReceiveStallRecovery'
    })
    [object[]]$lifecycleDecisionEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved')
    })
    [object[]]$closureEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_retained' -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'lifecycle_outcome' -Default '') -in @('Completed', 'ReceiveProofObserved')
    })
    [object[]]$resumeEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_transport_resumed'
    })
    [object[]]$rejectionEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'fresh_projection_required_before_unrestricted_state'
    })
    [object[]]$missingAuthorityEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'coordinator_projection_authority_missing'
    })
    [object[]]$pressureRecoveryHandoffEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_pressure_recovery_handoff_committed' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'StaleRejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq
            'bridge_receive_stall_recovery_pressure_handoff' -and
        (Get-FileTransferEventField -Event $_ -Name 'apply_status' -Default '') -in @('Applied', 'Idempotent') -and
        (Get-FileTransferEventField -Event $_ -Name 'current_authority_cleared' -Default '0') -eq '1'
    })
    [object[]]$repairContractSettledEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'StaleRejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'bridge_receive_stall_recovery_pressure_handoff'
    })
    [object[]]$projectionRetainedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_retained'
    })
    [object[]]$projectionPublishedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_published'
    })

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $metadataBySequence = @{}
    $seenTuples = @{}

    foreach ($invalidation in $invalidationEvents) {
        $invalidationSequence = [int64]$invalidation.Sequence
        $range = Get-FileTransferRegularV4RepairProjectionRange -Event $invalidation
        $frontier = Get-FileTransferEventInt64Field -Event $invalidation -Name 'frontier_chunk_index' -Default -1
        $durableHighest = Get-FileTransferEventInt64Field -Event $invalidation -Name 'durable_received_highest_chunk_index' -Default -1
        if (-not $range.Valid -or $frontier -lt 0 -or $durableHighest -le $frontier) {
            continue
        }

        $oldBridgeDecisionGeneration = Get-FileTransferRegularV4RepairProjectionScopeField `
            -Event $invalidation `
            -Name 'bridge_decision_generation' `
            -Default '0'
        $bridgeAuthority = @($bridgeAuthorityEvents | Where-Object {
            [int64]$_.Sequence -gt $invalidationSequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $invalidation `
                -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'bridge_decision_generation' -Default '0') -ne
                $oldBridgeDecisionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($bridgeAuthority.Count -eq 0) {
            continue
        }
        $bridgeAuthority = $bridgeAuthority[0]
        $currentBridgeDecisionGeneration = Get-FileTransferEventField `
            -Event $bridgeAuthority `
            -Name 'bridge_decision_generation' `
            -Default '0'

        $lifecycleDecision = @($lifecycleDecisionEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$bridgeAuthority.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $bridgeAuthority `
                -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'bridge_decision_generation' -Default '0') -eq
                $currentBridgeDecisionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($lifecycleDecision.Count -eq 0) {
            continue
        }
        $lifecycleDecision = $lifecycleDecision[0]

        $closure = @($closureEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$lifecycleDecision.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $bridgeAuthority `
                -Candidate $_) -and
            (Get-FileTransferEventField -Event $_ -Name 'bridge_decision_generation' -Default '0') -eq
                $currentBridgeDecisionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($closure.Count -eq 0) {
            continue
        }
        $closure = $closure[0]

        $resume = @($resumeEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$closure.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $invalidation `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($resume.Count -eq 0) {
            continue
        }
        $resume = $resume[0]

        [object[]]$matchingRejections = @($rejectionEvents | Where-Object {
            $candidateBridgeDecisionGeneration =
                Get-FileTransferRegularV4RepairProjectionScopeField `
                    -Event $_ `
                    -Name 'bridge_decision_generation'
            [int64]$_.Sequence -gt [int64]$resume.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $invalidation `
                -Candidate $_) -and
            ([string]::IsNullOrWhiteSpace($candidateBridgeDecisionGeneration) -or
                $candidateBridgeDecisionGeneration -eq $currentBridgeDecisionGeneration) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'frontier_chunk_index' -Default -1) -eq $frontier -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'durable_received_highest_chunk_index' -Default -1) -gt $frontier
        } | Sort-Object Sequence, LineNumber)
        if ($matchingRejections.Count -eq 0) {
            continue
        }

        foreach ($candidate in $matchingRejections) {
            $rawCandidates.Add($candidate) | Out-Null
        }

        $authorityId = Get-FileTransferRegularV4RepairProjectionScopeField `
            -Event $invalidation `
            -Name 'authority_id' `
            -Default '(none)'
        $rangeText = Get-FileTransferEventField -Event $invalidation -Name 'projected_ranges' -Default '(none)'
        $tuple = (@(
                (Get-FileTransferEventField -Event $invalidation -Name 'session_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $invalidation -Name 'transfer_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $invalidation -Name 'direction' -Default '(none)'),
                $frontier,
                $authorityId,
                $rangeText,
                $currentBridgeDecisionGeneration,
                (Get-FileTransferEventField -Event $closure -Name 'regular_v4_liveness_generation' -Default '0'),
                (Get-FileTransferRegularV4RepairProjectionScopeKey -Event $invalidation -Frontier $frontier)
            ) -join '|').ToLowerInvariant()
        if ($seenTuples.ContainsKey($tuple)) {
            continue
        }
        $seenTuples[$tuple] = $true
        $firstCandidate = $matchingRejections[0]
        $distinctCandidates.Add($firstCandidate) | Out-Null
        $metadataBySequence[[string][int64]$firstCandidate.Sequence] = [pscustomobject]@{
            Invalidation = $invalidation
            ScopeAnchor = $invalidation
            BridgeAuthority = $bridgeAuthority
            Closure = $closure
            Frontier = $frontier
            Range = $range
            CurrentBridgeDecisionGeneration = $currentBridgeDecisionGeneration
            MinimumBridgeDecisionGeneration = [int64]$currentBridgeDecisionGeneration
            AllowLaterBridgeDecision = $false
            AcceptedProjectionReasons = @('coordinator_recovery_projection_reauthorized')
        }
    }

    foreach ($handoff in $pressureRecoveryHandoffEvents) {
        $handoffSequence = [int64]$handoff.Sequence
        $authorityId = Get-FileTransferRegularV4RepairProjectionScopeField -Event $handoff -Name 'authority_id'
        $repairKey = Get-FileTransferEventField -Event $handoff -Name 'repair_request_key' -Default ''
        $installGeneration = Get-FileTransferEventField -Event $handoff -Name 'install_generation' -Default '0'
        $targetBridgeDecisionGeneration = Get-FileTransferEventInt64Field `
            -Event $handoff `
            -Name 'bridge_decision_generation' `
            -Default 0
        $range = Get-FileTransferRegularV4RepairProjectionRange -Event $handoff
        $frontier = Get-FileTransferEventInt64Field -Event $handoff -Name 'frontier_chunk_index' -Default -1
        if ($frontier -lt 0 -and $range.Valid) {
            $frontier = [int64]$range.Start
        }
        if ([string]::IsNullOrWhiteSpace($authorityId) -or
            [string]::IsNullOrWhiteSpace($repairKey) -or
            $installGeneration -notmatch '^\d+$' -or
            [int64]$installGeneration -le 0 -or
            $targetBridgeDecisionGeneration -le 0 -or
            -not $range.Valid -or
            $frontier -lt 0) {
            continue
        }

        $contractSettled = @($repairContractSettledEvents | Where-Object {
            [int64]$_.Sequence -gt $handoffSequence -and
            (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq $authorityId -and
            (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq $repairKey
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($contractSettled.Count -eq 0) {
            continue
        }

        $bridgeAuthority = @($bridgeAuthorityEvents | Where-Object {
            [int64]$_.Sequence -gt $handoffSequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch -Anchor $handoff -Candidate $_) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_decision_generation' -Default 0) -eq
                $targetBridgeDecisionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($bridgeAuthority.Count -eq 0) {
            continue
        }
        $bridgeAuthority = $bridgeAuthority[0]

        $lifecycleDecision = @($lifecycleDecisionEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$bridgeAuthority.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch -Anchor $handoff -Candidate $_) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_decision_generation' -Default 0) -eq
                $targetBridgeDecisionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($lifecycleDecision.Count -eq 0) {
            continue
        }

        $closure = @($closureEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$lifecycleDecision[0].Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch -Anchor $handoff -Candidate $_) -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_decision_generation' -Default 0) -eq
                $targetBridgeDecisionGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($closure.Count -eq 0) {
            continue
        }
        $closure = $closure[0]

        [object[]]$matchingMissingAuthorities = @($missingAuthorityEvents | Where-Object {
            $candidateRange = Get-FileTransferRegularV4RepairProjectionRange -Event $_
            $candidateBridgeDecisionGeneration = Get-FileTransferEventInt64Field `
                -Event $_ `
                -Name 'bridge_decision_generation' `
                -Default 0
            [int64]$_.Sequence -gt [int64]$closure.Sequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch -Anchor $handoff -Candidate $_) -and
            $candidateBridgeDecisionGeneration -ge $targetBridgeDecisionGeneration -and
            $candidateRange.Valid -and
            [int64]$candidateRange.Start -eq [int64]$range.Start -and
            [int64]$candidateRange.End -eq [int64]$range.End -and
            (Get-FileTransferEventField -Event $_ -Name 'source_repair_request_key' -Default '') -eq $repairKey -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'frontier_chunk_index' -Default -1) -eq $frontier -and
            (Get-FileTransferEventInt64Field -Event $_ -Name 'durable_received_highest_chunk_index' -Default -1) -gt $frontier
        } | Sort-Object Sequence, LineNumber)
        if ($matchingMissingAuthorities.Count -eq 0) {
            continue
        }

        foreach ($candidate in $matchingMissingAuthorities) {
            $rawCandidates.Add($candidate) | Out-Null
        }

        $rangeFingerprint = Get-FileTransferEventField `
            -Event $matchingMissingAuthorities[0] `
            -Name 'required_range_fingerprint' `
            -Default '(none)'
        $tuple = (@(
                (Get-FileTransferEventField -Event $handoff -Name 'session_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $handoff -Name 'transfer_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $handoff -Name 'direction' -Default '(none)'),
                $authorityId,
                $installGeneration,
                $repairKey,
                $frontier,
                [int64]$range.Start,
                [int64]$range.End,
                $rangeFingerprint,
                (Get-FileTransferRegularV4RepairProjectionScopeKey -Event $handoff -Frontier $frontier)
            ) -join '|').ToLowerInvariant()
        if ($seenTuples.ContainsKey($tuple)) {
            continue
        }
        $seenTuples[$tuple] = $true
        $firstCandidate = $matchingMissingAuthorities[0]
        $distinctCandidates.Add($firstCandidate) | Out-Null
        $metadataBySequence[[string][int64]$firstCandidate.Sequence] = [pscustomobject]@{
            Invalidation = $handoff
            ScopeAnchor = $handoff
            BridgeAuthority = $bridgeAuthority
            Closure = $closure
            Frontier = $frontier
            Range = $range
            CurrentBridgeDecisionGeneration = [string]$targetBridgeDecisionGeneration
            MinimumBridgeDecisionGeneration = $targetBridgeDecisionGeneration
            AllowLaterBridgeDecision = $true
            AcceptedProjectionReasons = @('coordinator_authority_projection_staged')
        }
    }

    foreach ($candidate in $distinctCandidates.ToArray()) {
        $metadata = $metadataBySequence[[string][int64]$candidate.Sequence]
        $candidateSequence = [int64]$candidate.Sequence
        $frontier = [int64]$metadata.Frontier
        $scopeAnchor = $metadata.ScopeAnchor

        $durableResolution = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt $candidateSequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $scopeAnchor `
                -Candidate $_) -and
            (
                ($_.EventName -eq 'filetransfer_v4_state_sent' -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'contiguous_committed_chunk_index' -Default -1) -gt $frontier) -or
                ($_.EventName -eq 'filetransfer_regular_v4_frontier_repair_progress_observed' -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'committed_frontier_after' -Default -1) -gt $frontier) -or
                ($_.EventName -eq 'filetransfer_regular_v4_frontier_repair_projection_cleared' -and
                    (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -in @(
                        'frontier_advanced', 'frontier_advanced_gap_resolved', 'frontier_complete',
                        'range_filled', 'durable_fill', 'repair_filled'))
            )
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)

        $freshProjection = @($projectionRetainedEvents | Where-Object {
            [int64]$_.Sequence -gt $candidateSequence -and
            (Test-FileTransferRegularV4RepairProjectionReauthorizationBaseScopeMatch `
                -Anchor $scopeAnchor `
                -Candidate $_) -and
            (
                (-not [bool]$metadata.AllowLaterBridgeDecision -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_decision_generation' -Default 0) -eq
                        [int64]$metadata.CurrentBridgeDecisionGeneration) -or
                ([bool]$metadata.AllowLaterBridgeDecision -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'bridge_decision_generation' -Default 0) -ge
                        [int64]$metadata.MinimumBridgeDecisionGeneration)
            ) -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -in
                @($metadata.AcceptedProjectionReasons) -and
            @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
            }).Count -gt 0
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)

        $dispatchResolution = @()
        if ($freshProjection.Count -gt 0) {
            $freshProjection = $freshProjection[0]
            $freshAuthorityId = Get-FileTransferRegularV4RepairProjectionScopeField `
                -Event $freshProjection `
                -Name 'authority_id'
            $published = @($projectionPublishedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$freshProjection.Sequence -and
                (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq $freshAuthorityId -and
                @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                    $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
                }).Count -gt 0
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($published.Count -gt 0) {
                $stateSent = @($orderedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$published[0].Sequence -and
                    $_.EventName -eq 'filetransfer_v4_state_sent' -and
                    (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq $freshAuthorityId -and
                    (Get-FileTransferEventInt64Field -Event $_ -Name 'missing_range_count' -Default 0) -gt 0
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                if ($stateSent.Count -gt 0) {
                    $stateEpoch = Get-FileTransferEventField -Event $stateSent[0] -Name 'epoch' -Default ''
                        $stateReceived = @($orderedEvents | Where-Object {
                            [int64]$_.Sequence -gt [int64]$stateSent[0].Sequence -and
                            $_.EventName -eq 'filetransfer_v4_state_received' -and
                        (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq
                            (Get-FileTransferEventField -Event $stateSent[0] -Name 'session_id' -Default '') -and
                        (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq
                            (Get-FileTransferEventField -Event $stateSent[0] -Name 'transfer_id' -Default '') -and
                            (Get-FileTransferEventField -Event $_ -Name 'epoch' -Default '') -eq $stateEpoch -and
                            (Get-FileTransferEventField -Event $_ -Name 'applied' -Default '0') -eq '1' -and
                            (Get-FileTransferEventInt64Field -Event $_ -Name 'missing_range_count' -Default 0) -gt 0 -and
                            @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                                $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
                            }).Count -gt 0
                    } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                    if ($stateReceived.Count -gt 0) {
                        $freshRepairKey = Get-FileTransferEventField `
                            -Event $freshProjection `
                            -Name 'projected_repair_request_key' `
                            -Default ''
                        $peerAuthority = @($orderedEvents | Where-Object {
                            [int64]$_.Sequence -gt [int64]$stateReceived[0].Sequence -and
                            $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_authority_granted' -and
                            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
                            (Test-FileTransferRegularV4RepairProjectionScopeMatch `
                                -Anchor $stateReceived[0] `
                                -Candidate $_) -and
                            -not [string]::IsNullOrWhiteSpace($freshRepairKey) -and
                            (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq
                                $freshRepairKey -and
                            @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                                $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
                            }).Count -gt 0
                        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                        if ($peerAuthority.Count -gt 0) {
                            $peerAuthorityId = Get-FileTransferRegularV4RepairProjectionScopeField `
                                -Event $peerAuthority[0] `
                                -Name 'authority_id'
                            $dispatchResolution = @($orderedEvents | Where-Object {
                                [int64]$_.Sequence -gt [int64]$peerAuthority[0].Sequence -and
                                $_.EventName -eq 'filetransfer_regular_v4_frontier_repair_dispatched' -and
                                (Get-FileTransferRegularV4RepairProjectionScopeField -Event $_ -Name 'authority_id') -eq $peerAuthorityId -and
                                (Test-FileTransferRegularV4RepairProjectionScopeMatch `
                                    -Anchor $peerAuthority[0] `
                                    -Candidate $_) -and
                                (Get-FileTransferEventField -Event $_ -Name 'repair_request_key' -Default '') -eq
                                    $freshRepairKey -and
                                @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                                    $_.Start -eq [int64]$metadata.Range.Start -and $_.End -eq [int64]$metadata.Range.End
                                }).Count -gt 0
                            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                        }
                    }
                }
            }
        }

        if ($durableResolution.Count -gt 0 -or $dispatchResolution.Count -gt 0) {
            $recoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = if ($unresolvedCandidates.Count -gt 0) { 'fail' } elseif ($distinctCandidates.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRegularV4MissingRangePreservationProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    $authorityByFrontier = @{}
    $activeByScope = @{}
    $projectionEpochToScope = @{}
    $appliedProjectionScopes = @{}
    $peerAuthorityEvents = New-Object System.Collections.Generic.List[object]
    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidates = New-Object System.Collections.Generic.List[object]
    $unresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $recoveredCandidateSequences = @{}
    $seenCandidateLogicalTuples = @{}
    $candidateMetadataBySequence = @{}

    foreach ($event in $orderedEvents) {
        $eventName = [string]$event.EventName
        $sequence = [int64]$event.Sequence

        if ($eventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated',
                'filetransfer_route_selected',
                'filetransfer_route_transitioned',
                'filetransfer_live_route_epoch_started',
                'filetransfer_runtime_started',
                'filetransfer_runtime_owner_changed')) {
            $isUnconditionalBoundary = $eventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated')
            foreach ($scopeKey in @($activeByScope.Keys)) {
                $projection = $activeByScope[$scopeKey]
                if (-not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $projection.Anchor -Candidate $event)) {
                    continue
                }
                if ($isUnconditionalBoundary -or
                    (Test-FileTransferRegularV4RepairProjectionScopeReplacement `
                        -Anchor $projection.ScopeAnchor `
                        -Candidate $event)) {
                    $activeByScope.Remove($scopeKey)
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_authority_granted') {
            $direction = Get-FileTransferEventField -Event $event -Name 'direction' -Default ''
            $route = Get-FileTransferEventField -Event $event -Name 'route' -Default 'regular_nkn_v4_fast'
            $protocol = Get-FileTransferEventField -Event $event -Name 'protocol_version' -Default '4'
            if ($direction -eq 'outbound' -and $route -eq 'regular_nkn_v4_fast' -and $protocol -eq '4') {
                $peerAuthorityEvents.Add($event) | Out-Null
            }
            elseif ($direction -eq 'inbound' -and $route -eq 'regular_nkn_v4_fast' -and $protocol -eq '4') {
                $rangeInfo = Get-FileTransferRegularV4RepairProjectionRange -Event $event
                foreach ($range in @($rangeInfo.Ranges)) {
                    $authorityKey = Get-FileTransferRegularV4RepairProjectionScopeKey -Event $event -Frontier $range.Start
                    $authorityByFrontier[$authorityKey] = $event
                }
            }
            continue
        }

        if ($eventName -in @(
                'filetransfer_v4_repair_requested',
                'filetransfer_v4_repair_suppressed',
                'filetransfer_regular_v4_frontier_repair_projection_retained',
                'filetransfer_regular_v4_frontier_repair_projection_published')) {
            $rangeInfo = Get-FileTransferRegularV4RepairProjectionRange -Event $event
            if (-not $rangeInfo.Valid) {
                continue
            }

            foreach ($range in @($rangeInfo.Ranges)) {
            $scopeKey = Get-FileTransferRegularV4RepairProjectionScopeKey -Event $event -Frontier $range.Start
            $existingScope = @($activeByScope.Values | Where-Object {
                [int64]$_.Start -eq $range.Start -and
                (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $_.ScopeAnchor -Candidate $event)
            } | Sort-Object @{ Expression = { [int64]$_.LastEvidence.Sequence } } | Select-Object -Last 1)
            if ($existingScope.Count -gt 0) {
                $scopeKey = [string]$existingScope[0].ScopeKey
            }
            $matchingAuthority = $null
            if ($authorityByFrontier.ContainsKey($scopeKey)) {
                $matchingAuthority = $authorityByFrontier[$scopeKey]
            }
            else {
                $matchingAuthority = @($authorityByFrontier.Values | Where-Object {
                    [int64]$_.Sequence -lt $sequence -and
                    (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $_ -Candidate $event) -and
                    @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                            $null -ne $_ -and $_.Start -eq $range.Start
                        }).Count -gt 0
                } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
                if ($matchingAuthority.Count -gt 0) {
                    $matchingAuthority = $matchingAuthority[0]
                }
                else {
                    $matchingAuthority = $null
                }
            }

            $sourceAuthorityId = Get-FileTransferEventField -Event $event -Name 'authority_id' -Default ''
            $hasEmbeddedAuthority = -not [string]::IsNullOrWhiteSpace($sourceAuthorityId) -and
                $sourceAuthorityId -notin @('(none)', 'none')
            if ($null -eq $matchingAuthority -and -not $hasEmbeddedAuthority) {
                continue
            }

            if ($activeByScope.ContainsKey($scopeKey)) {
                $projection = $activeByScope[$scopeKey]
                if ($range.Start -eq [int64]$projection.Start -and $range.End -le [int64]$projection.SourceEnd) {
                    $projection.End = $range.End
                    $projection.RepairKey = $range.RepairKey
                    $projection.LastEvidence = $event
                }
            }
            else {
                $matchingAuthorityRange = @(if ($null -ne $matchingAuthority) {
                    (Get-FileTransferRegularV4RepairProjectionRange -Event $matchingAuthority).Ranges | Where-Object {
                            $null -ne $_ -and $_.Start -eq $range.Start
                        } | Select-Object -First 1
                }
                else {
                    # Preserve an empty collection for embedded-authority projection
                    # events that do not need a separate authorization event.
                })
                $sourceEnd = if ($matchingAuthorityRange.Count -gt 0) {
                    [int64]$matchingAuthorityRange[0].End
                }
                else {
                    $range.End
                }
                $activeByScope[$scopeKey] = [pscustomobject]@{
                    ScopeKey = $scopeKey
                    Anchor = $event
                    Authority = $matchingAuthority
                    ScopeAnchor = if ($hasEmbeddedAuthority -or $eventName -like 'filetransfer_regular_v4_frontier_repair_projection_*') {
                        $event
                    }
                    elseif ($null -ne $matchingAuthority) {
                        $matchingAuthority
                    }
                    else {
                        $event
                    }
                    LastEvidence = $event
                    Start = $range.Start
                    End = $range.End
                    SourceEnd = $sourceEnd
                    RepairKey = $range.RepairKey
                    Candidate = $null
                    CandidateLogicalTuple = ''
                    Recovered = $false
                }
            }

            if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_projection_published') {
                $epoch = Get-FileTransferEventField -Event $event -Name 'epoch' -Default ''
                if ($epoch -notmatch '^\d+$') {
                    $epoch = Get-FileTransferEventField -Event $event -Name 'state_epoch' -Default ''
                }
                if ($epoch -match '^\d+$') {
                    $epochKey = ('{0}|{1}|{2}' -f
                            (Get-FileTransferEventField -Event $event -Name 'session_id' -Default '(none)'),
                            (Get-FileTransferEventField -Event $event -Name 'transfer_id' -Default '(none)'),
                            $epoch)
                    if (-not $projectionEpochToScope.ContainsKey($epochKey)) {
                        $projectionEpochToScope[$epochKey] = New-Object System.Collections.Generic.List[string]
                    }
                    if (-not $projectionEpochToScope[$epochKey].Contains($scopeKey)) {
                        $projectionEpochToScope[$epochKey].Add($scopeKey) | Out-Null
                    }
                }
            }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_v4_state_sent') {
            $frontier = Get-FileTransferEventInt64Field -Event $event -Name 'contiguous_committed_chunk_index' -Default -1
            $durableHighest = Get-FileTransferEventInt64Field -Event $event -Name 'durable_received_highest_chunk_index' -Default -1
            $missingCount = Get-FileTransferEventInt64Field -Event $event -Name 'missing_range_count' -Default 0
            $creditExclusive = Get-FileTransferEventInt64Field -Event $event -Name 'credit_until_chunk_index_exclusive' -Default -1
            $terminalReady = Get-FileTransferEventField -Event $event -Name 'terminal_ready' -Default '0'
            $epoch = Get-FileTransferEventField -Event $event -Name 'epoch' -Default ''
            $stateRangeInfo = Get-FileTransferRegularV4RepairProjectionRange -Event $event

            foreach ($scopeKey in @($activeByScope.Keys)) {
                $projection = $activeByScope[$scopeKey]
                if (-not (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $projection.ScopeAnchor -Candidate $event)) {
                    continue
                }

                if ($frontier -gt [int64]$projection.Start) {
                    if ($null -ne $projection.Candidate) {
                        $projection.Recovered = $true
                        $recoveredCandidateSequences[[string][int64]$projection.Candidate.Sequence] = $true
                        if (-not [string]::IsNullOrWhiteSpace([string]$projection.CandidateLogicalTuple) -and
                            $seenCandidateLogicalTuples.ContainsKey([string]$projection.CandidateLogicalTuple)) {
                            $earliestLogicalCandidate = $seenCandidateLogicalTuples[[string]$projection.CandidateLogicalTuple]
                            $recoveredCandidateSequences[[string][int64]$earliestLogicalCandidate.Sequence] = $true
                        }
                    }
                    $activeByScope.Remove($scopeKey)
                    continue
                }

                $stateCarriesExactProjection = $stateRangeInfo.Valid -and @($stateRangeInfo.Ranges | Where-Object {
                        $null -ne $_ -and
                        [int64]$_.Start -eq [int64]$projection.Start -and
                        [int64]$_.End -eq [int64]$projection.End
                    }).Count -gt 0
                if ($missingCount -gt 0 -and $stateCarriesExactProjection -and $epoch -match '^\d+$') {
                    $epochKey = ('{0}|{1}|{2}' -f
                            (Get-FileTransferEventField -Event $event -Name 'session_id' -Default '(none)'),
                            (Get-FileTransferEventField -Event $event -Name 'transfer_id' -Default '(none)'),
                            $epoch)
                    if (-not $projectionEpochToScope.ContainsKey($epochKey)) {
                        $projectionEpochToScope[$epochKey] = New-Object System.Collections.Generic.List[string]
                    }
                    if (-not $projectionEpochToScope[$epochKey].Contains($scopeKey)) {
                        $projectionEpochToScope[$epochKey].Add($scopeKey) | Out-Null
                    }
                }

                if ($null -eq $projection.Candidate -and
                    $frontier -eq [int64]$projection.Start -and
                    $durableHighest -gt $frontier -and
                    $missingCount -eq 0 -and
                    $terminalReady -ne '1' -and
                    $creditExclusive -gt [int64]$projection.End) {
                    $projection.Candidate = $event
                    $rawCandidates.Add($event) | Out-Null
                    $authorityId = Get-FileTransferEventField -Event $projection.ScopeAnchor -Name 'authority_id' -Default '(none)'
                    $decisionGeneration = Get-FileTransferEventField -Event $projection.ScopeAnchor -Name 'decision_generation' -Default '0'
                    $logicalTuple = ('{0}|{1}|{2}|{3}|{4}|{5}|{6}' -f
                        $projection.ScopeKey,
                        $projection.Start,
                        $projection.End,
                        $authorityId,
                        $decisionGeneration,
                        (Get-FileTransferEventField -Event $projection.LastEvidence -Name 'rebind_generation' -Default '0'),
                        $projection.RepairKey)
                    $projection.CandidateLogicalTuple = $logicalTuple
                    if (-not $seenCandidateLogicalTuples.ContainsKey($logicalTuple)) {
                        $seenCandidateLogicalTuples[$logicalTuple] = $event
                        $candidateMetadataBySequence[[string][int64]$event.Sequence] = [pscustomobject]@{
                            ScopeAnchor = $projection.ScopeAnchor
                            Start = [int64]$projection.Start
                            End = [int64]$projection.End
                            LogicalTuple = $logicalTuple
                        }
                        $distinctCandidates.Add($event) | Out-Null
                    }
                }
                elseif ($null -ne $projection.Candidate -and
                    $frontier -eq [int64]$projection.Start -and
                    $durableHighest -gt $frontier -and
                    $missingCount -eq 0 -and
                    $terminalReady -ne '1' -and
                    $creditExclusive -gt [int64]$projection.End -and
                    $epoch -match '^\d+$' -and
                    [string]::Equals(
                        $epoch,
                        (Get-FileTransferEventField -Event $projection.Candidate -Name 'epoch' -Default ''),
                        [System.StringComparison]::Ordinal)) {
                    # Retained-slice merging can preserve the same logical state
                    # more than once. Count the raw copy, but keep one distinct
                    # proof edge at its earliest retained sequence.
                    $rawCandidates.Add($event) | Out-Null
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_v4_state_received' -and
            (Get-FileTransferEventField -Event $event -Name 'applied' -Default '0') -eq '1' -and
            (Get-FileTransferEventInt64Field -Event $event -Name 'missing_range_count' -Default 0) -gt 0) {
            $epoch = Get-FileTransferEventField -Event $event -Name 'epoch' -Default ''
            $epochKey = ('{0}|{1}|{2}' -f
                (Get-FileTransferEventField -Event $event -Name 'session_id' -Default '(none)'),
                (Get-FileTransferEventField -Event $event -Name 'transfer_id' -Default '(none)'),
                $epoch)
            if ($projectionEpochToScope.ContainsKey($epochKey)) {
                foreach ($scopeKey in @($projectionEpochToScope[$epochKey])) {
                    $appliedProjectionScopes[$scopeKey] = $event
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_dispatched') {
            $dispatchRange = Get-FileTransferRegularV4RepairProjectionRange -Event $event
            foreach ($scopeKey in @($activeByScope.Keys)) {
                $projection = $activeByScope[$scopeKey]
                if ($null -eq $projection.Candidate -or
                    -not $appliedProjectionScopes.ContainsKey($scopeKey) -or
                    -not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $projection.Anchor -Candidate $event)) {
                    continue
                }
                $appliedState = $appliedProjectionScopes[$scopeKey]
                $matchingPeerAuthority = @($peerAuthorityEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$appliedState.Sequence -and
                    [int64]$_.Sequence -lt $sequence -and
                    (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $projection.ScopeAnchor -Candidate $_) -and
                    (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $appliedState -Candidate $_) -and
                    @((Get-FileTransferRegularV4RepairProjectionRange -Event $_).Ranges | Where-Object {
                            $null -ne $_ -and
                            [int64]$_.Start -eq [int64]$projection.Start -and
                            [int64]$_.End -eq [int64]$projection.End
                        }).Count -gt 0
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                if ($matchingPeerAuthority.Count -gt 0 -and
                    $dispatchRange.Valid -and
                    @($dispatchRange.Ranges | Where-Object {
                            $null -ne $_ -and
                            [int64]$_.Start -eq [int64]$projection.Start -and
                            [int64]$_.End -eq [int64]$projection.End
                        }).Count -gt 0 -and
                    (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $matchingPeerAuthority[0] -Candidate $event)) {
                    $projection.Recovered = $true
                    $recoveredCandidateSequences[[string][int64]$projection.Candidate.Sequence] = $true
                    if (-not [string]::IsNullOrWhiteSpace([string]$projection.CandidateLogicalTuple) -and
                        $seenCandidateLogicalTuples.ContainsKey([string]$projection.CandidateLogicalTuple)) {
                        $earliestLogicalCandidate = $seenCandidateLogicalTuples[[string]$projection.CandidateLogicalTuple]
                        $recoveredCandidateSequences[[string][int64]$earliestLogicalCandidate.Sequence] = $true
                    }
                }
            }
            continue
        }

        if ($eventName -in @(
                'filetransfer_v4_repair_filled',
                'filetransfer_v4_repair_cleared',
                'filetransfer_regular_v4_frontier_repair_progress_observed',
                'filetransfer_regular_v4_frontier_repair_projection_cleared')) {
            $frontierAfter = Get-FileTransferEventInt64Field -Event $event -Name 'committed_frontier_after' -Default -1
            if ($frontierAfter -lt 0) {
                $frontierAfter = Get-FileTransferEventInt64Field -Event $event -Name 'contiguous_committed_chunk_index' -Default -1
            }
            $range = Get-FileTransferRegularV4RepairProjectionRange -Event $event
            $clearReason = Get-FileTransferEventField -Event $event -Name 'decision_reason' -Default ''
            if ([string]::IsNullOrWhiteSpace($clearReason)) {
                $clearReason = Get-FileTransferEventField -Event $event -Name 'reason' -Default ''
            }
            foreach ($scopeKey in @($activeByScope.Keys)) {
                $projection = $activeByScope[$scopeKey]
                if (-not (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $projection.ScopeAnchor -Candidate $event)) {
                    continue
                }
                $durablyResolved = $frontierAfter -gt [int64]$projection.Start -or
                    ($eventName -eq 'filetransfer_v4_repair_filled' -and
                     $range.Valid -and
                     $range.Start -le [int64]$projection.Start -and
                     $range.End -ge [int64]$projection.End) -or
                    ($eventName -eq 'filetransfer_regular_v4_frontier_repair_projection_cleared' -and
                     $clearReason -in @(
                         'frontier_advanced',
                         'frontier_advanced_gap_resolved',
                         'frontier_complete',
                         'range_filled',
                         'durable_fill',
                         'repair_filled'))
                if ($durablyResolved) {
                    if ($null -ne $projection.Candidate) {
                        $projection.Recovered = $true
                        $recoveredCandidateSequences[[string][int64]$projection.Candidate.Sequence] = $true
                        if (-not [string]::IsNullOrWhiteSpace([string]$projection.CandidateLogicalTuple) -and
                            $seenCandidateLogicalTuples.ContainsKey([string]$projection.CandidateLogicalTuple)) {
                            $earliestLogicalCandidate = $seenCandidateLogicalTuples[[string]$projection.CandidateLogicalTuple]
                            $recoveredCandidateSequences[[string][int64]$earliestLogicalCandidate.Sequence] = $true
                        }
                    }
                }
                if ($durablyResolved -or $eventName -eq 'filetransfer_regular_v4_frontier_repair_projection_cleared') {
                    $activeByScope.Remove($scopeKey)
                }
            }
        }
    }

    foreach ($candidate in $distinctCandidates.ToArray()) {
        $matchingProjection = @($activeByScope.Values | Where-Object {
            $null -ne $_.Candidate -and [int64]$_.Candidate.Sequence -eq [int64]$candidate.Sequence
        } | Select-Object -First 1)
        if (($matchingProjection.Count -gt 0 -and $matchingProjection[0].Recovered) -or
            $recoveredCandidateSequences.ContainsKey([string][int64]$candidate.Sequence)) {
            $recoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $unresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    # A resolved projection may have been removed from the active map. Re-scan
    # durable frontier/fill evidence only for those candidate objects so their
    # recovery status is retained without treating attempt settlement as proof.
    foreach ($candidate in @($unresolvedCandidates.ToArray())) {
        $candidateFrontier = Get-FileTransferEventInt64Field -Event $candidate -Name 'contiguous_committed_chunk_index' -Default -1
        $candidateMetadata = $candidateMetadataBySequence[[string][int64]$candidate.Sequence]
        $candidateScopeAnchor = if ($null -ne $candidateMetadata) { $candidateMetadata.ScopeAnchor } else { $candidate }
        $firstInvalidatingBoundary = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$candidate.Sequence -and
            $_.EventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated',
                'filetransfer_route_selected',
                'filetransfer_route_transitioned',
                'filetransfer_live_route_epoch_started',
                'filetransfer_runtime_started',
                'filetransfer_runtime_owner_changed') -and
            (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $candidate -Candidate $_) -and
            (
                $_.EventName -in @(
                    'transfer_terminal',
                    'file_transfer_inbound_terminal',
                    'file_transfer_outbound_terminal',
                    'filetransfer_runtime_terminalized',
                    'filetransfer_manifest_received',
                    'filetransfer_manifest_replaced',
                    'filetransfer_session_replaced',
                    'filetransfer_data_session_recreated') -or
                (Test-FileTransferRegularV4RepairProjectionScopeReplacement `
                    -Anchor $candidateScopeAnchor `
                    -Candidate $_)
            )
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        $invalidationSequence = if ($firstInvalidatingBoundary.Count -gt 0) {
            [int64]$firstInvalidatingBoundary[0].Sequence
        }
        else {
            [int64]::MaxValue
        }
        $recovery = @($orderedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$candidate.Sequence -and
            [int64]$_.Sequence -lt $invalidationSequence -and
            (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $candidateScopeAnchor -Candidate $_) -and
            (
                ($_.EventName -eq 'filetransfer_v4_state_sent' -and
                 (Get-FileTransferEventInt64Field -Event $_ -Name 'contiguous_committed_chunk_index' -Default -1) -gt $candidateFrontier) -or
                ($_.EventName -eq 'filetransfer_regular_v4_frontier_repair_progress_observed' -and
                 (Get-FileTransferEventInt64Field -Event $_ -Name 'committed_frontier_after' -Default -1) -gt $candidateFrontier)
            )
        } | Select-Object -First 1)
        if ($recovery.Count -gt 0) {
            $unresolvedCandidates.Remove($candidate) | Out-Null
            $recoveredCandidates.Add($candidate) | Out-Null
        }
    }

    $verdict = if ($unresolvedCandidates.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidates.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidates.Count
        RecoveredCount = $recoveredCandidates.Count
        UnresolvedCount = $unresolvedCandidates.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidates.ToArray())
        RecoveredCandidateEvents = @($recoveredCandidates.ToArray())
        UnresolvedCandidateEvents = @($unresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRegularV4PeerSilenceReplayRange {
    param([Parameter(Mandatory = $true)]$Event)

    $repairKey = Get-FileTransferEventField -Event $Event -Name 'repair_request_key' -Default ''
    if ([string]::IsNullOrWhiteSpace($repairKey) -or $repairKey -in @('(none)', 'none')) {
        $repairKey = Get-FileTransferEventField -Event $Event -Name 'successor_repair_request_key' -Default ''
    }

    if ($repairKey -match '^regular_v4_peer_silence_safety_replay:(?<frontier>\d+):(?<start>\d+):(?<count>\d+):(?<ordinal>\d+)$') {
        $start = [int64]$Matches['start']
        $count = [int64]$Matches['count']
        return [pscustomobject]@{
            Valid = $count -gt 0
            RepairKey = $repairKey
            Frontier = [int64]$Matches['frontier']
            Start = $start
            End = $start + $count
            Ordinal = [int64]$Matches['ordinal']
        }
    }

    $frontier = Get-FileTransferEventInt64Field -Event $Event -Name 'remote_next_expected_chunk_index' -Default -1
    if ($frontier -lt 0) {
        $frontier = Get-FileTransferEventInt64Field -Event $Event -Name 'frontier_chunk_index' -Default -1
    }
    $start = Get-FileTransferEventInt64Field -Event $Event -Name 'replay_start_chunk_index' -Default -1
    if ($start -lt 0) {
        $start = Get-FileTransferEventInt64Field -Event $Event -Name 'start_chunk_index' -Default -1
    }
    $end = Get-FileTransferEventInt64Field -Event $Event -Name 'replay_end_chunk_exclusive' -Default -1
    if ($end -lt 0 -and $start -ge 0) {
        $count = Get-FileTransferEventInt64Field -Event $Event -Name 'scheduled_chunk_count' -Default 0
        if ($count -le 0) {
            $count = Get-FileTransferEventInt64Field -Event $Event -Name 'requested_chunk_count' -Default 0
        }
        if ($count -le 0) {
            $count = Get-FileTransferEventInt64Field -Event $Event -Name 'sent_chunk_count' -Default 0
        }
        if ($count -gt 0) {
            $end = $start + $count
        }
    }

    return [pscustomobject]@{
        Valid = $frontier -ge 0 -and $start -ge 0 -and $end -gt $start
        RepairKey = if ([string]::IsNullOrWhiteSpace($repairKey)) { '(none)' } else { $repairKey }
        Frontier = $frontier
        Start = $start
        End = $end
        Ordinal = Get-FileTransferEventInt64Field -Event $Event -Name 'replay_ordinal' -Default 0
    }
}

function Test-FileTransferRegularV4PeerSilenceReplayScopeMatch {
    param(
        [Parameter(Mandatory = $true)]$Anchor,
        [Parameter(Mandatory = $true)]$Candidate
    )

    if (-not (Test-FileTransferRegularV4RepairProjectionScopeMatch -Anchor $Anchor -Candidate $Candidate)) {
        return $false
    }

    $anchorDirection = Get-FileTransferEventField -Event $Anchor -Name 'direction' -Default ''
    $candidateDirection = Get-FileTransferEventField -Event $Candidate -Name 'direction' -Default ''
    return [string]::IsNullOrWhiteSpace($anchorDirection) -or
        [string]::IsNullOrWhiteSpace($candidateDirection) -or
        [string]::Equals($anchorDirection, $candidateDirection, [System.StringComparison]::OrdinalIgnoreCase)
}

function Get-FileTransferRegularV4PeerSilenceReplayMissingDispatchRangeProof {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$orderedEvents = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    $grantRecords = New-Object System.Collections.Generic.List[object]
    $grantByCorrelationKey = @{}
    $missingDispatchByCorrelationKey = @{}
    $activeUnresolvedRanges = New-Object System.Collections.Generic.List[object]
    $activeRangeByLogicalKey = @{}
    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctCandidateRecords = New-Object System.Collections.Generic.List[object]
    $seenCandidateLogicalTuples = @{}

    foreach ($event in $orderedEvents) {
        $eventName = [string]$event.EventName
        $sequence = [int64]$event.Sequence

        if ($eventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated',
                'filetransfer_route_selected',
                'filetransfer_route_transitioned',
                'filetransfer_live_route_epoch_started',
                'filetransfer_runtime_started',
                'filetransfer_runtime_owner_changed')) {
            $isUnconditionalBoundary = $eventName -in @(
                'transfer_terminal',
                'file_transfer_inbound_terminal',
                'file_transfer_outbound_terminal',
                'filetransfer_runtime_terminalized',
                'filetransfer_manifest_received',
                'filetransfer_manifest_replaced',
                'filetransfer_session_replaced',
                'filetransfer_data_session_recreated')
            foreach ($range in @($activeUnresolvedRanges.ToArray())) {
                if (-not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $range.ScopeAnchor -Candidate $event)) {
                    continue
                }
                if ($isUnconditionalBoundary -or
                    (Test-FileTransferRegularV4RepairProjectionScopeReplacement -Anchor $range.ScopeAnchor -Candidate $event)) {
                    $activeUnresolvedRanges.Remove($range) | Out-Null
                    $activeRangeByLogicalKey.Remove([string]$range.LogicalKey)
                }
            }
            foreach ($candidate in $distinctCandidateRecords.ToArray()) {
                if ($sequence -le [int64]$candidate.Event.Sequence -or
                    [int64]$candidate.InvalidationSequence -ne [int64]::MaxValue -or
                    -not (Test-FileTransferRegularV4RepairProjectionTransferMatch -Anchor $candidate.ScopeAnchor -Candidate $event)) {
                    continue
                }
                if ($isUnconditionalBoundary -or
                    (Test-FileTransferRegularV4RepairProjectionScopeReplacement -Anchor $candidate.ScopeAnchor -Candidate $event)) {
                    $candidate.InvalidationSequence = $sequence
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_authority_granted') {
            $source = Get-FileTransferEventField -Event $event -Name 'source' -Default ''
            $direction = Get-FileTransferEventField -Event $event -Name 'direction' -Default ''
            $route = Get-FileTransferEventField -Event $event -Name 'route' -Default 'regular_nkn_v4_fast'
            $protocol = Get-FileTransferEventField -Event $event -Name 'protocol_version' -Default '4'
            $range = Get-FileTransferRegularV4PeerSilenceReplayRange -Event $event
            if ($source -ne 'regular_v4_peer_silence_safety_replay' -or
                $direction -ne 'outbound' -or
                $route -ne 'regular_nkn_v4_fast' -or
                $protocol -ne '4' -or
                -not $range.Valid) {
                continue
            }

            $scopeKey = Get-FileTransferRegularV4RepairProjectionScopeKey -Event $event -Frontier $range.Frontier
            $correlationKey = ('{0}|{1}' -f $scopeKey, $range.RepairKey)
            if (-not $grantByCorrelationKey.ContainsKey($correlationKey)) {
                $grantRecord = [pscustomobject]@{
                    CorrelationKey = $correlationKey
                    ScopeKey = $scopeKey
                    Event = $event
                    Range = $range
                }
                $grantByCorrelationKey[$correlationKey] = $grantRecord
                $grantRecords.Add($grantRecord) | Out-Null
            }

            foreach ($unresolved in @($activeUnresolvedRanges.ToArray())) {
                if ($range.Frontier -ne [int64]$unresolved.Frontier -or
                    $range.Start -le [int64]$unresolved.Start -or
                    -not (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $unresolved.ScopeAnchor -Candidate $event)) {
                    continue
                }

                $rawCandidates.Add($event) | Out-Null
                $decisionGeneration = Get-FileTransferEventField -Event $event -Name 'decision_generation' -Default '0'
                $logicalTuple = ('{0}|{1}|{2}|{3}|{4}|{5}|{6}' -f
                    $unresolved.ScopeKey,
                    $unresolved.Frontier,
                    $unresolved.Start,
                    $unresolved.End,
                    $unresolved.RepairKey,
                    $range.RepairKey,
                    $decisionGeneration)
                if (-not $seenCandidateLogicalTuples.ContainsKey($logicalTuple)) {
                    $candidateRecord = [pscustomobject]@{
                        Event = $event
                        LogicalTuple = $logicalTuple
                        ScopeAnchor = $unresolved.ScopeAnchor
                        Frontier = [int64]$unresolved.Frontier
                        Start = [int64]$unresolved.Start
                        End = [int64]$unresolved.End
                        Recovered = $false
                        InvalidationSequence = [int64]::MaxValue
                    }
                    $seenCandidateLogicalTuples[$logicalTuple] = $candidateRecord
                    $distinctCandidateRecords.Add($candidateRecord) | Out-Null
                }
                break
            }
            continue
        }

        if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_missing_dispatch') {
            $range = Get-FileTransferRegularV4PeerSilenceReplayRange -Event $event
            if ($range.Valid) {
                $matchingGrant = @($grantRecords.ToArray() | Where-Object {
                    $_.Range.RepairKey -eq $range.RepairKey -and
                    [int64]$_.Event.Sequence -lt $sequence -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $_.Event -Candidate $event)
                } | Sort-Object @{ Expression = { [int64]$_.Event.Sequence } } | Select-Object -Last 1)
                if ($matchingGrant.Count -gt 0) {
                    $missingDispatchByCorrelationKey[[string]$matchingGrant[0].CorrelationKey] = $event
                }
            }
            continue
        }

        if ($eventName -in @(
                'filetransfer_regular_v4_frontier_repair_contract_settled',
                'filetransfer_regular_v4_frontier_repair_settled_stalled',
                'filetransfer_regular_v4_frontier_repair_settlement_accepted') -and
            -not ($eventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled' -and
                (Get-FileTransferEventField -Event $event -Name 'dispatch_observed' -Default '0') -eq '1')) {
            $range = Get-FileTransferRegularV4PeerSilenceReplayRange -Event $event
            if (-not $range.Valid) {
                continue
            }

            [object[]]$matchingGrants = @($grantRecords.ToArray() | Where-Object {
                $_.Range.RepairKey -eq $range.RepairKey -and
                [int64]$_.Event.Sequence -lt $sequence -and
                $missingDispatchByCorrelationKey.ContainsKey([string]$_.CorrelationKey) -and
                (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $_.Event -Candidate $event)
            } | Sort-Object @{ Expression = { [int64]$_.Event.Sequence } })
            if ($matchingGrants.Count -eq 0 -or
                ($eventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled' -and
                    $matchingGrants.Count -ne 1)) {
                continue
            }

            $outcome = Get-FileTransferEventField -Event $event -Name 'settlement_outcome' -Default ''
            if ([string]::IsNullOrWhiteSpace($outcome)) {
                $outcome = Get-FileTransferEventField -Event $event -Name 'outcome' -Default ''
            }
            if ([string]::IsNullOrWhiteSpace($outcome) -and
                $eventName -eq 'filetransfer_regular_v4_frontier_repair_settled_stalled') {
                $outcome = 'SettledStalled'
            }
            $dispatchObserved = Get-FileTransferEventField -Event $event -Name 'dispatch_observed' -Default '0'
            if ($outcome.ToLowerInvariant() -notin @('missingdispatch', 'missing_dispatch', 'settledstalled', 'settled_stalled') -or
                $dispatchObserved -eq '1') {
                continue
            }

            $grantRecord = $matchingGrants[-1]
            $scopeAnchor = $grantRecord.Event
            $range = $grantRecord.Range
            $scopeKey = [string]$grantRecord.ScopeKey
            $logicalKey = ('{0}|{1}|{2}|{3}' -f $scopeKey, $range.Frontier, $range.Start, $range.End)
            if (-not $activeRangeByLogicalKey.ContainsKey($logicalKey)) {
                $unresolved = [pscustomobject]@{
                    LogicalKey = $logicalKey
                    ScopeKey = $scopeKey
                    ScopeAnchor = $scopeAnchor
                    Frontier = $range.Frontier
                    Start = $range.Start
                    End = $range.End
                    RepairKey = $range.RepairKey
                    Settlement = $event
                }
                $activeRangeByLogicalKey[$logicalKey] = $unresolved
                $activeUnresolvedRanges.Add($unresolved) | Out-Null
            }
            else {
                $unresolved = $activeRangeByLogicalKey[$logicalKey]
                if ([int64]$event.Sequence -gt [int64]$unresolved.Settlement.Sequence) {
                    $unresolved.ScopeKey = $scopeKey
                    $unresolved.ScopeAnchor = $scopeAnchor
                    $unresolved.RepairKey = $range.RepairKey
                    $unresolved.Settlement = $event
                }
            }
            continue
        }

        if ($eventName -in @(
                'filetransfer_regular_v4_frontier_repair_dispatched',
                'filetransfer_regular_v4_frontier_repair_contract_settled')) {
            if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled' -and
                (Get-FileTransferEventField -Event $event -Name 'dispatch_observed' -Default '0') -ne '1') {
                continue
            }
            $range = Get-FileTransferRegularV4PeerSilenceReplayRange -Event $event
            if (-not $range.Valid) {
                continue
            }
            [object[]]$matchingGrants = @($grantRecords.ToArray() | Where-Object {
                $_.Range.RepairKey -eq $range.RepairKey -and
                [int64]$_.Event.Sequence -lt $sequence -and
                (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $_.Event -Candidate $event)
            } | Sort-Object @{ Expression = { [int64]$_.Event.Sequence } })
            if ($eventName -eq 'filetransfer_regular_v4_frontier_repair_contract_settled' -and
                $matchingGrants.Count -ne 1) {
                continue
            }
            $scopeAnchor = if ($matchingGrants.Count -gt 0) { $matchingGrants[-1].Event } else { $event }
            foreach ($unresolved in @($activeUnresolvedRanges.ToArray())) {
                if ($range.Start -le [int64]$unresolved.Start -and
                    $range.End -ge [int64]$unresolved.End -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $unresolved.ScopeAnchor -Candidate $scopeAnchor)) {
                    $activeUnresolvedRanges.Remove($unresolved) | Out-Null
                    $activeRangeByLogicalKey.Remove([string]$unresolved.LogicalKey)
                }
            }
            foreach ($candidate in $distinctCandidateRecords.ToArray()) {
                if (-not $candidate.Recovered -and
                    $sequence -gt [int64]$candidate.Event.Sequence -and
                    $sequence -lt [int64]$candidate.InvalidationSequence -and
                    $range.Start -le [int64]$candidate.Start -and
                    $range.End -ge [int64]$candidate.End -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $candidate.ScopeAnchor -Candidate $scopeAnchor)) {
                    $candidate.Recovered = $true
                }
            }
            continue
        }

        if ($eventName -eq 'filetransfer_v4_state_received' -and
            (Get-FileTransferEventField -Event $event -Name 'applied' -Default '0') -eq '1') {
            $peerFrontier = Get-FileTransferEventInt64Field -Event $event -Name 'contiguous_committed_chunk_index' -Default -1
            foreach ($unresolved in @($activeUnresolvedRanges.ToArray())) {
                if ($peerFrontier -ge [int64]$unresolved.End -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $unresolved.ScopeAnchor -Candidate $event)) {
                    $activeUnresolvedRanges.Remove($unresolved) | Out-Null
                    $activeRangeByLogicalKey.Remove([string]$unresolved.LogicalKey)
                }
            }
            foreach ($candidate in $distinctCandidateRecords.ToArray()) {
                if (-not $candidate.Recovered -and
                    $sequence -gt [int64]$candidate.Event.Sequence -and
                    $sequence -lt [int64]$candidate.InvalidationSequence -and
                    $peerFrontier -ge [int64]$candidate.End -and
                    (Test-FileTransferRegularV4PeerSilenceReplayScopeMatch -Anchor $candidate.ScopeAnchor -Candidate $event)) {
                    $candidate.Recovered = $true
                }
            }
        }
    }

    [object[]]$recoveredCandidateEvents = @(
        $distinctCandidateRecords.ToArray() |
            Where-Object { $_.Recovered } |
            ForEach-Object { $_.Event }
    )
    [object[]]$unresolvedCandidateEvents = @(
        $distinctCandidateRecords.ToArray() |
            Where-Object { -not $_.Recovered } |
            ForEach-Object { $_.Event }
    )
    $verdict = if ($unresolvedCandidateEvents.Count -gt 0) {
        'fail'
    }
    elseif ($distinctCandidateRecords.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinctCandidateRecords.Count
        RecoveredCount = $recoveredCandidateEvents.Count
        UnresolvedCount = $unresolvedCandidateEvents.Count
        Verdict = $verdict
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = @($distinctCandidateRecords.ToArray() | ForEach-Object { $_.Event })
        RecoveredCandidateEvents = $recoveredCandidateEvents
        UnresolvedCandidateEvents = $unresolvedCandidateEvents
    }
}

function Remove-FileTransferLegacyReceiveRecoveryEventsCoveredByOperations {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$OperationEvents = @()
    )

    [object[]]$issued = @($OperationEvents | Where-Object {
        $_.EventName -eq 'filetransfer_receive_recovery_operation_issued' -and
        -not [string]::IsNullOrWhiteSpace(
            (Get-FileTransferEventField `
                -Event $_ `
                -Name 'receive_recovery_operation_authority_id' `
                -Default '')) -and
        -not [string]::IsNullOrWhiteSpace(
            (Get-FileTransferEventField `
                -Event $_ `
                -Name 'observation_identity' `
                -Default '')) -and
        (Get-FileTransferEventInt64Field `
            -Event $_ `
            -Name 'receive_recovery_operation_generation' `
            -Default 0) -gt 0
    })
    if ($issued.Count -eq 0) {
        return @($Events)
    }

    [object[]]$filtered = @(
        foreach ($candidate in @($Events)) {
            $covered = $false
            foreach ($operation in $issued) {
                $sessionMatches =
                    (Get-FileTransferEventField -Event $candidate -Name 'session_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $operation -Name 'session_id' -Default '')
                $transferMatches =
                    (Get-FileTransferEventField -Event $candidate -Name 'transfer_id' -Default '') -eq
                    (Get-FileTransferEventField -Event $operation -Name 'transfer_id' -Default '')
                if (-not $sessionMatches -or -not $transferMatches) {
                    continue
                }

                $candidateDirection =
                    Get-FileTransferEventField -Event $candidate -Name 'direction' -Default ''
                $operationDirection =
                    Get-FileTransferEventField -Event $operation -Name 'direction' -Default ''
                if (-not [string]::IsNullOrWhiteSpace($candidateDirection) -and
                    $candidateDirection -ne $operationDirection) {
                    continue
                }

                $scopeMismatch = $false
                foreach ($scopeField in @(
                        'route',
                        'protocol_version',
                        'live_route_epoch',
                        'route_publication_generation',
                        'runtime_generation',
                        'terminal_generation',
                        'leg_generation',
                        'transport_epoch',
                        'bridge_recovery_generation',
                        'data_session_generation')) {
                    $candidateScopeValue = Get-FileTransferEventField `
                        -Event $candidate `
                        -Name $scopeField `
                        -Default ''
                    if ([string]::IsNullOrWhiteSpace($candidateScopeValue) -or
                        $candidateScopeValue -in @('(none)', 'none')) {
                        continue
                    }
                    $operationScopeValue = Get-FileTransferEventField `
                        -Event $operation `
                        -Name $scopeField `
                        -Default ''
                    if (-not [string]::Equals(
                            $candidateScopeValue,
                            $operationScopeValue,
                            [System.StringComparison]::OrdinalIgnoreCase)) {
                        $scopeMismatch = $true
                        break
                    }
                }
                if ($scopeMismatch) {
                    continue
                }

                $candidateBridgeDecision = Get-FileTransferEventField `
                    -Event $candidate `
                    -Name 'bridge_decision_generation' `
                    -Default (
                        Get-FileTransferEventField `
                            -Event $candidate `
                            -Name 'execution_command_generation' `
                            -Default '0')
                $operationBridgeDecision = Get-FileTransferEventField `
                    -Event $operation `
                    -Name 'bridge_decision_generation' `
                    -Default '0'
                $candidateLeaseGeneration = Get-FileTransferEventField `
                    -Event $candidate `
                    -Name 'regular_v4_liveness_generation' `
                    -Default (
                        Get-FileTransferEventField `
                            -Event $candidate `
                            -Name 'recovery_liveness_lease_generation' `
                            -Default '0')
                $operationLeaseGeneration = Get-FileTransferEventField `
                    -Event $operation `
                    -Name 'recovery_liveness_lease_generation' `
                    -Default '0'
                $exactDecision =
                    $candidateBridgeDecision -ne '0' -and
                    $candidateBridgeDecision -eq $operationBridgeDecision
                $exactLease =
                    $candidateLeaseGeneration -ne '0' -and
                    $candidateLeaseGeneration -eq $operationLeaseGeneration
                if ($exactDecision -or $exactLease) {
                    $covered = $true
                    break
                }
            }

            if (-not $covered) {
                $candidate
            }
        }
    )
    return $filtered
}

function Get-FileTransferReceiveRecoveryOperationCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @()
    )

    [object[]]$events = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    $eventNames = @{
        Issued = @('filetransfer_receive_recovery_operation_issued')
        Started = @(
            'filetransfer_receive_recovery_operation_execution_start_decided',
            'filetransfer_receive_recovery_operation_execution_started')
        Receipt = @(
            'filetransfer_receive_recovery_operation_execution_receipt_applied',
            'filetransfer_receive_recovery_operation_receipt_applied')
        Proof = @(
            'filetransfer_receive_recovery_operation_proof_observed',
            'filetransfer_receive_recovery_operation_receive_proof_observed')
        Terminal = @(
            'filetransfer_receive_recovery_operation_terminal_decided',
            'filetransfer_receive_recovery_operation_completed')
        Invalidated = @('filetransfer_receive_recovery_operation_invalidated')
        Superseded = @('filetransfer_receive_recovery_operation_superseded')
        ClosureRetained = @('filetransfer_receive_recovery_operation_closure_retained')
        ClosureAdopted = @('filetransfer_receive_recovery_operation_closure_adopted')
        ClosureReserved = @('filetransfer_receive_recovery_operation_closure_reserved')
        ClosureConsumed = @('filetransfer_receive_recovery_operation_closure_consumed')
    }
    $identityFields = @(
        'receive_recovery_operation_authority_id',
        'observation_identity',
        'observation_generation',
        'observation_source',
        'observation_reason',
        'observation_utc_ms',
        'session_id',
        'transfer_id',
        'direction',
        'route',
        'protocol_version',
        'live_route_epoch',
        'route_publication_generation',
        'route_commit_generation',
        'route_commit_transaction_generation',
        'route_commit_offer_generation',
        'route_commit_path_lease_generation',
        'route_commit_probe_ack_id',
        'runtime_generation',
        'terminal_generation',
        'leg_generation',
        'transport_epoch',
        'bridge_recovery_generation',
        'bridge_decision_generation',
        'checkpoint_request_id',
        'data_session_identity',
        'data_session_generation',
        'recovery_liveness_lease_authority_id',
        'recovery_liveness_lease_generation')

    function Get-ReceiveRecoveryOperationField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = '',
            [switch]$AllowNone
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(missing)', '__missing__') -and
                ($AllowNone -or $value -notin @('(none)', 'none'))) {
                return $value
            }
        }
        return $Default
    }

    function Get-ReceiveRecoveryOperationGeneration {
        param([Parameter(Mandatory = $true)]$Event)

        return Get-ReceiveRecoveryOperationField `
            -Event $Event `
            -Names @(
                'receive_recovery_operation_generation',
                'recovery_operation_generation',
                'operation_generation')
    }

    function Get-ReceiveRecoveryIdentityValue {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Name
        )

        [string[]]$aliases = switch ($Name) {
            'receive_recovery_operation_authority_id' {
                @(
                    'receive_recovery_operation_authority_id',
                    'recovery_operation_authority_id')
            }
            'observation_identity' {
                @(
                    'observation_identity',
                    'receive_recovery_observation_identity')
            }
            'observation_generation' {
                @('observation_generation', 'receive_recovery_observation_generation')
            }
            'observation_source' { @('observation_source') }
            'observation_reason' { @('observation_reason') }
            'observation_utc_ms' { @('observation_utc_ms', 'observed_utc_ms') }
            'session_id' { @('session_id', 'observation_session_id') }
            'transfer_id' { @('transfer_id', 'observation_transfer_id') }
            'direction' { @('direction', 'observation_direction') }
            'route' { @('route', 'observation_route', 'source_route') }
            'protocol_version' { @('protocol_version', 'observation_protocol_version', 'source_protocol_version') }
            'live_route_epoch' { @('live_route_epoch', 'observation_live_route_epoch', 'source_live_route_epoch') }
            'route_publication_generation' {
                @(
                    'route_publication_generation',
                    'observation_route_publication_generation',
                    'source_route_publication_generation')
            }
            'route_commit_generation' {
                @(
                    'route_commit_generation',
                    'observation_route_commit_generation',
                    'source_route_commit_generation')
            }
            'route_commit_transaction_generation' {
                @('route_commit_transaction_generation')
            }
            'route_commit_offer_generation' {
                @('route_commit_offer_generation')
            }
            'route_commit_path_lease_generation' {
                @('route_commit_path_lease_generation')
            }
            'route_commit_probe_ack_id' {
                @('route_commit_probe_ack_id')
            }
            'runtime_generation' {
                @(
                    'runtime_generation',
                    'runtime_owner_generation',
                    'observation_runtime_generation',
                    'source_runtime_generation')
            }
            'terminal_generation' { @('terminal_generation', 'observation_terminal_generation', 'source_terminal_generation') }
            'leg_generation' { @('leg_generation', 'observation_leg_generation', 'source_leg_generation') }
            'transport_epoch' { @('transport_epoch', 'observation_transport_epoch', 'source_transport_epoch') }
            'bridge_recovery_generation' {
                @(
                    'bridge_recovery_generation',
                    'observation_bridge_recovery_generation',
                    'source_bridge_recovery_generation')
            }
            'bridge_decision_generation' {
                @('bridge_decision_generation', 'execution_command_generation')
            }
            'checkpoint_request_id' {
                @('checkpoint_request_id', 'observation_checkpoint_request_id')
            }
            'data_session_identity' {
                @('data_session_identity', 'observation_data_session_identity')
            }
            'data_session_generation' {
                @(
                    'data_session_generation',
                    'observation_data_session_generation',
                    'source_data_session_generation')
            }
            'recovery_liveness_lease_authority_id' {
                @(
                    'recovery_liveness_lease_authority_id',
                    'regular_v4_liveness_authority_id')
            }
            'recovery_liveness_lease_generation' {
                @(
                    'recovery_liveness_lease_generation',
                    'regular_v4_liveness_generation')
            }
            default { @($Name) }
        }
        $optional = $Name -in @(
            'route_commit_probe_ack_id',
            'checkpoint_request_id',
            'recovery_liveness_lease_authority_id')
        return Get-ReceiveRecoveryOperationField `
            -Event $Event `
            -Names $aliases `
            -Default $(if ($optional) { '__missing__' } else { '' }) `
            -AllowNone:$optional
    }

    function Get-ReceiveRecoveryOperationKey {
        param([Parameter(Mandatory = $true)]$Event)

        $generation = Get-ReceiveRecoveryOperationGeneration -Event $Event
        if ([string]::IsNullOrWhiteSpace($generation)) {
            return ''
        }

        $parts = New-Object System.Collections.Generic.List[string]
        $parts.Add($generation.ToLowerInvariant()) | Out-Null
        foreach ($field in $identityFields) {
            $value = Get-ReceiveRecoveryIdentityValue -Event $Event -Name $field
            $optional = $field -in @(
                'route_commit_probe_ack_id',
                'checkpoint_request_id',
                'recovery_liveness_lease_authority_id')
            if ([string]::IsNullOrWhiteSpace($value) -or
                $value -in @('(missing)', '__missing__') -or
                (-not $optional -and
                 $value -in @('(none)', 'none'))) {
                return ''
            }
            $parts.Add($value.ToLowerInvariant()) | Out-Null
        }
        return $parts -join '|'
    }

    function Test-ReceiveRecoveryOperationMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $anchorKey = Get-ReceiveRecoveryOperationKey -Event $Anchor
        $candidateKey = Get-ReceiveRecoveryOperationKey -Event $Candidate
        return -not [string]::IsNullOrWhiteSpace($anchorKey) -and
            [string]::Equals(
                $anchorKey,
                $candidateKey,
                [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Get-ReceiveRecoveryOperationOutcome {
        param([Parameter(Mandatory = $true)]$Event)

        return (Get-ReceiveRecoveryOperationField `
            -Event $Event `
            -Names @('execution_outcome', 'operation_outcome', 'outcome', 'operation_state') `
            -Default '').Replace('_', '').ToLowerInvariant()
    }

    function Test-ReceiveRecoveryPhase2TupleMatch {
        param(
            [Parameter(Mandatory = $true)]$ClosureEvent,
            [Parameter(Mandatory = $true)]$Candidate,
            [switch]$IgnoreInstallGeneration
        )

        [object[]]$fieldMappings = @(
            [pscustomobject]@{
                Closure = @('receive_recovery_operation_generation', 'recovery_operation_generation')
                Candidate = @('receive_recovery_operation_generation', 'recovery_operation_generation')
            },
            [pscustomobject]@{
                Closure = @('data_session_generation')
                Candidate = @('receive_recovery_data_session_generation', 'data_session_generation')
            },
            [pscustomobject]@{ Closure = @('session_id'); Candidate = @('session_id') },
            [pscustomobject]@{ Closure = @('transfer_id'); Candidate = @('transfer_id') },
            [pscustomobject]@{ Closure = @('direction'); Candidate = @('direction') },
            [pscustomobject]@{ Closure = @('route'); Candidate = @('route') },
            [pscustomobject]@{ Closure = @('protocol_version'); Candidate = @('protocol_version') },
            [pscustomobject]@{ Closure = @('live_route_epoch'); Candidate = @('live_route_epoch') },
            [pscustomobject]@{
                Closure = @('route_publication_generation')
                Candidate = @('route_publication_generation')
            },
            [pscustomobject]@{ Closure = @('runtime_generation'); Candidate = @('runtime_generation') },
            [pscustomobject]@{ Closure = @('terminal_generation'); Candidate = @('terminal_generation') },
            [pscustomobject]@{ Closure = @('leg_generation'); Candidate = @('leg_generation') },
            [pscustomobject]@{ Closure = @('transport_epoch'); Candidate = @('transport_epoch') },
            [pscustomobject]@{
                Closure = @('bridge_recovery_generation')
                Candidate = @('bridge_recovery_generation')
            },
            [pscustomobject]@{
                Closure = @('bridge_decision_generation')
                Candidate = @('bridge_decision_generation')
            },
            [pscustomobject]@{
                Closure = @('bridge_decision_generation')
                Candidate = @('request_bridge_decision_generation')
            },
            [pscustomobject]@{
                Closure = @('recovery_liveness_lease_generation')
                Candidate = @('request_regular_v4_liveness_generation')
            },
            [pscustomobject]@{
                Closure = @('retry_authority_id')
                Candidate = @('authority_id', 'retry_authority_id')
            },
            [pscustomobject]@{
                Closure = @('retry_dispatch_attempt_generation')
                Candidate = @('dispatch_attempt_generation')
            },
            [pscustomobject]@{
                Closure = @('retry_missing_dispatch_generation')
                Candidate = @('missing_dispatch_successor_generation')
            },
            [pscustomobject]@{
                Closure = @('retry_release_kind')
                Candidate = @('release_kind')
            },
            [pscustomobject]@{
                Closure = @('retry_release_authority_id')
                Candidate = @('release_authority_id')
            },
            [pscustomobject]@{
                Closure = @('retry_release_generation')
                Candidate = @('release_generation')
            },
            [pscustomobject]@{
                Closure = @('retry_release_outcome')
                Candidate = @('release_outcome')
            })
        foreach ($mapping in $fieldMappings) {
            $closureValue = Get-ReceiveRecoveryOperationField `
                -Event $ClosureEvent `
                -Names $mapping.Closure
            $candidateValue = Get-ReceiveRecoveryOperationField `
                -Event $Candidate `
                -Names $mapping.Candidate
            if ([string]::IsNullOrWhiteSpace($closureValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals(
                    $closureValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        if ((Get-ReceiveRecoveryOperationField `
                -Event $ClosureEvent `
                -Names @('retry_release_kind')) -ne
            'ReceiveRecoveryLeaseClosure') {
            return $false
        }
        if ($IgnoreInstallGeneration) {
            return $true
        }
        $closureInstallGeneration = Get-ReceiveRecoveryOperationField `
            -Event $ClosureEvent `
            -Names @('retry_install_generation', 'install_generation')
        $candidateInstallGeneration = Get-ReceiveRecoveryOperationField `
            -Event $Candidate `
            -Names @('install_generation', 'retry_install_generation')
        return $closureInstallGeneration -match '^[1-9][0-9]*$' -and
            $closureInstallGeneration -eq $candidateInstallGeneration
    }

    function Test-ReceiveRecoveryClosureBoundaryMatch {
        param(
            [Parameter(Mandatory = $true)]$ReservedEvent,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-ReceiveRecoveryOperationMatch `
                -Anchor $ReservedEvent `
                -Candidate $Candidate)) {
            return $false
        }
        foreach ($field in @(
                'closure_generation',
                'retry_authority_id',
                'retry_dispatch_attempt_generation',
                'retry_missing_dispatch_generation',
                'retry_release_kind',
                'retry_release_authority_id',
                'retry_release_generation',
                'retry_release_outcome')) {
            $reservedValue = Get-ReceiveRecoveryOperationField `
                -Event $ReservedEvent `
                -Names @($field)
            $candidateValue = Get-ReceiveRecoveryOperationField `
                -Event $Candidate `
                -Names @($field)
            if ([string]::IsNullOrWhiteSpace($reservedValue) -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                -not [string]::Equals(
                    $reservedValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return (Get-ReceiveRecoveryOperationField `
                -Event $ReservedEvent `
                -Names @('closure_generation')) -match '^[1-9][0-9]*$'
    }

    function Test-ReceiveRecoveryPhase2ChainEventMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [switch]$RequireInstallGeneration
        )

        if (-not (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch `
                -Left $Left `
                -Right $Right)) {
            return $false
        }

        foreach ($field in @(
                'request_regular_v4_liveness_generation',
                'request_bridge_decision_generation',
                'request_active_predecessor_supersession',
                'receive_recovery_operation_generation',
                'data_session_generation')) {
            $leftValue = Get-ReceiveRecoveryOperationField `
                -Event $Left `
                -Names @($field)
            $rightValue = Get-ReceiveRecoveryOperationField `
                -Event $Right `
                -Names @($field)
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals(
                    $leftValue,
                    $rightValue,
                    [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        if (-not $RequireInstallGeneration) {
            return $true
        }

        $leftInstallGeneration = Get-ReceiveRecoveryOperationField `
            -Event $Left `
            -Names @('install_generation')
        $rightInstallGeneration = Get-ReceiveRecoveryOperationField `
            -Event $Right `
            -Names @('install_generation')
        return $leftInstallGeneration -match '^[1-9][0-9]*$' -and
            $leftInstallGeneration -eq $rightInstallGeneration
    }

    # Build the correlation indexes once. The compact analyzer deliberately
    # passes a wider receive-recovery semantic stream into this function; only
    # a small subset carries a complete operation identity. Recomputing the
    # full identity tuple while rescanning that wider stream for every issued
    # operation made large retained artifacts quadratic.
    $correlationDiagnostics = [pscustomobject]@{
        IndexBuildVisitCount = 0L
        OperationKeyBuildCount = 0L
        IndexedOperationEventCount = 0L
        BoundedLookupVisitCount = 0L
    }
    $eventsByName = @{}
    $operationEventsByKey = @{}
    $issuedEventsByGeneration = @{}
    $issuedEventList = New-Object System.Collections.Generic.List[object]
    $distinctIssuedByKey = [ordered]@{}
    $operationIdentityCounts = [ordered]@{
        Started = 0L
        Receipt = 0L
        Proof = 0L
        ClosureRetained = 0L
        ClosureAdopted = 0L
        ClosureReserved = 0L
        ClosureConsumed = 0L
    }
    $phase2IndexedEventNames = @{
        runtime_unlock_retry_dispatch_decision_staged = $true
        runtime_unlock_retry_dispatch_install_receipt_issued = $true
        runtime_unlock_retry_dispatch_install_committed = $true
    }
    foreach ($event in $events) {
        $correlationDiagnostics.IndexBuildVisitCount++
        $isReceiveRecoveryOperationEvent =
            $event.EventName.StartsWith(
                'filetransfer_receive_recovery_operation_',
                [System.StringComparison]::Ordinal)
        if (-not $isReceiveRecoveryOperationEvent -and
            -not $phase2IndexedEventNames.ContainsKey($event.EventName)) {
            continue
        }
        if (-not $eventsByName.ContainsKey($event.EventName)) {
            $eventsByName[$event.EventName] =
                New-Object System.Collections.Generic.List[object]
        }
        $eventsByName[$event.EventName].Add($event) | Out-Null

        if (-not $isReceiveRecoveryOperationEvent) {
            continue
        }

        # These three cheap required fields avoid constructing the complete
        # 30-field identity for unrelated health, hold, and proof-state events.
        $operationGeneration = Get-ReceiveRecoveryOperationGeneration -Event $event
        if ([string]::IsNullOrWhiteSpace($operationGeneration)) {
            continue
        }
        $operationAuthority = Get-ReceiveRecoveryOperationField `
            -Event $event `
            -Names @(
                'receive_recovery_operation_authority_id',
                'recovery_operation_authority_id')
        $observationIdentity = Get-ReceiveRecoveryOperationField `
            -Event $event `
            -Names @(
                'observation_identity',
                'receive_recovery_observation_identity')
        if ([string]::IsNullOrWhiteSpace($operationAuthority) -or
            [string]::IsNullOrWhiteSpace($observationIdentity)) {
            continue
        }

        $correlationDiagnostics.OperationKeyBuildCount++
        $operationKey = Get-ReceiveRecoveryOperationKey -Event $event
        if ([string]::IsNullOrWhiteSpace($operationKey)) {
            continue
        }
        $correlationDiagnostics.IndexedOperationEventCount++
        if (-not $operationEventsByKey.ContainsKey($operationKey)) {
            $operationEventsByKey[$operationKey] =
                New-Object System.Collections.Generic.List[object]
        }
        $operationEventsByKey[$operationKey].Add($event) | Out-Null

        if ($event.EventName -in $eventNames.Issued) {
            $issuedEventList.Add($event) | Out-Null
            if (-not $distinctIssuedByKey.Contains($operationKey)) {
                $distinctIssuedByKey[$operationKey] = $event
            }
            if (-not $issuedEventsByGeneration.ContainsKey($operationGeneration)) {
                $issuedEventsByGeneration[$operationGeneration] =
                    New-Object System.Collections.Generic.List[object]
            }
            $issuedEventsByGeneration[$operationGeneration].Add($event) | Out-Null
        }
        if ($event.EventName -in $eventNames.Started) {
            $operationIdentityCounts.Started++
        }
        if ($event.EventName -in $eventNames.Receipt) {
            $operationIdentityCounts.Receipt++
        }
        if ($event.EventName -in $eventNames.Proof) {
            $operationIdentityCounts.Proof++
        }
        if ($event.EventName -in $eventNames.ClosureRetained) {
            $operationIdentityCounts.ClosureRetained++
        }
        if ($event.EventName -in $eventNames.ClosureAdopted) {
            $operationIdentityCounts.ClosureAdopted++
        }
        if ($event.EventName -in $eventNames.ClosureReserved) {
            $operationIdentityCounts.ClosureReserved++
        }
        if ($event.EventName -in $eventNames.ClosureConsumed) {
            $operationIdentityCounts.ClosureConsumed++
        }
    }
    [object[]]$issuedEvents = @($issuedEventList.ToArray())

    function Get-ReceiveRecoveryIndexedEventsByName {
        param([Parameter(Mandatory = $true)][string]$Name)

        $correlationDiagnostics.BoundedLookupVisitCount++
        if (-not $eventsByName.ContainsKey($Name)) {
            return @()
        }
        return @($eventsByName[$Name].ToArray())
    }

    function Get-ReceiveRecoveryIndexedOperationEvents {
        param([Parameter(Mandatory = $true)][string]$Key)

        $correlationDiagnostics.BoundedLookupVisitCount++
        if ([string]::IsNullOrWhiteSpace($Key) -or
            -not $operationEventsByKey.ContainsKey($Key)) {
            return @()
        }
        return @($operationEventsByKey[$Key].ToArray())
    }

    function Get-ReceiveRecoveryIndexedIssuedByGeneration {
        param([Parameter(Mandatory = $true)][string]$Generation)

        $correlationDiagnostics.BoundedLookupVisitCount++
        if ([string]::IsNullOrWhiteSpace($Generation) -or
            -not $issuedEventsByGeneration.ContainsKey($Generation)) {
            return @()
        }
        return @($issuedEventsByGeneration[$Generation].ToArray())
    }

    [object[]]$supersessionEvents = @(
        Get-ReceiveRecoveryIndexedEventsByName `
            -Name $eventNames.Superseded[0])
    [object[]]$phase2StageEvents = @(
        Get-ReceiveRecoveryIndexedEventsByName `
            -Name 'runtime_unlock_retry_dispatch_decision_staged')
    [object[]]$phase2ReceiptIssuedEvents = @(
        Get-ReceiveRecoveryIndexedEventsByName `
            -Name 'runtime_unlock_retry_dispatch_install_receipt_issued')
    [object[]]$phase2CommitEvents = @(
        Get-ReceiveRecoveryIndexedEventsByName `
            -Name 'runtime_unlock_retry_dispatch_install_committed')

    function Get-ReceiveRecoverySupersessionResolution {
        param(
            [Parameter(Mandatory = $true)]$Issued,
            [Parameter(Mandatory = $true)]$Receipt,
            [Parameter(Mandatory = $true)]$Closure,
            $Proof = $null
        )

        $issuedGeneration = Get-ReceiveRecoveryOperationGeneration -Event $Issued
        $issuedAuthority = Get-ReceiveRecoveryOperationField `
            -Event $Issued `
            -Names @(
                'receive_recovery_operation_authority_id',
                'recovery_operation_authority_id')
        $closureGeneration = Get-ReceiveRecoveryOperationField `
            -Event $Closure `
            -Names @('closure_generation')
        $receiptObservedUtcMs = Get-ReceiveRecoveryOperationField `
            -Event $Receipt `
            -Names @(
                'execution_receipt_observed_utc_ms',
                'terminal_receipt_observed_utc_ms')
        if ($closureGeneration -notmatch '^[1-9][0-9]*$' -or
            $receiptObservedUtcMs -notmatch '^[1-9][0-9]*$' -or
            [int64]$Closure.Sequence -le [int64]$Receipt.Sequence -or
            (Get-ReceiveRecoveryOperationField `
                -Event $Closure `
                -Names @(
                    'execution_receipt_observed_utc_ms',
                    'terminal_receipt_observed_utc_ms')) -ne
                $receiptObservedUtcMs) {
            return $null
        }

        $proofIdentity = '(none)'
        $proofObservedUtcMs = '0'
        $supersessionReason =
            'completed_unproven_receive_recovery_superseded_by_newer_health_observation'
        if ($null -ne $Proof) {
            $proofIdentity = Get-ReceiveRecoveryOperationField `
                -Event $Proof `
                -Names @('proof_identity')
            $proofObservedUtcMs = Get-ReceiveRecoveryOperationField `
                -Event $Proof `
                -Names @('proof_observed_utc_ms')
            if ([string]::IsNullOrWhiteSpace($proofIdentity) -or
                $proofIdentity -in @('(none)', 'none') -or
                $proofObservedUtcMs -notmatch '^[1-9][0-9]*$' -or
                [int64]$Closure.Sequence -le [int64]$Proof.Sequence -or
                (Get-ReceiveRecoveryOperationField `
                    -Event $Closure `
                    -Names @('proof_identity')) -ne $proofIdentity -or
                (Get-ReceiveRecoveryOperationField `
                    -Event $Closure `
                    -Names @('proof_observed_utc_ms')) -ne
                    $proofObservedUtcMs) {
                return $null
            }
            $supersessionReason =
                'completed_proven_unreserved_receive_recovery_superseded_by_newer_health_observation'
        }

        [object[]]$supersessions = @($supersessionEvents | Where-Object {
            if ([int64]$_.Sequence -le [int64]$Closure.Sequence) {
                return $false
            }

            if ((Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @(
                        'predecessor_receive_recovery_operation_generation',
                        'predecessor_operation_generation')) -ne
                    $issuedGeneration -or
                (Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @('predecessor_closure_generation')) -ne
                    $closureGeneration -or
                (Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @(
                        'predecessor_execution_receipt_observed_utc_ms',
                        'predecessor_terminal_receipt_observed_utc_ms')) -ne
                    $receiptObservedUtcMs -or
                (Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @('predecessor_receive_proof_identity') `
                    -Default '(none)' `
                    -AllowNone) -ne $proofIdentity -or
                (Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @('predecessor_receive_proof_observed_utc_ms') `
                    -Default '0') -ne $proofObservedUtcMs -or
                (Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @('decision_reason')) -ne $supersessionReason) {
                return $false
            }

            foreach ($field in @(
                    'log_writer_id',
                    'session_id',
                    'transfer_id',
                    'direction',
                    'route',
                    'protocol_version',
                    'live_route_epoch',
                    'route_publication_generation',
                    'runtime_generation',
                    'terminal_generation',
                    'leg_generation',
                    'transport_epoch',
                    'bridge_recovery_generation',
                    'checkpoint_request_id',
                    'data_session_identity',
                    'data_session_generation')) {
                $left = Get-ReceiveRecoveryIdentityValue `
                    -Event $Issued `
                    -Name $field
                $right = Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @($field) `
                    -AllowNone
                if ([string]::IsNullOrWhiteSpace($left) -or
                    [string]::IsNullOrWhiteSpace($right) -or
                    -not [string]::Equals(
                        $left,
                        $right,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }

            foreach ($generationMapping in @(
                    @('bridge_decision_generation', 'predecessor_bridge_decision_generation'),
                    @('recovery_liveness_lease_generation', 'predecessor_recovery_liveness_lease_generation'))) {
                $left = Get-ReceiveRecoveryIdentityValue `
                    -Event $Receipt `
                    -Name $generationMapping[0]
                $right = Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @($generationMapping[1])
                if ([string]::IsNullOrWhiteSpace($left) -or
                    $left -ne $right) {
                    return $false
                }
            }

            $predecessorAuthority = Get-ReceiveRecoveryOperationField `
                -Event $_ `
                -Names @(
                    'predecessor_receive_recovery_operation_authority_id',
                    'predecessor_operation_authority_id')
            $authorityVisible =
                -not [string]::IsNullOrWhiteSpace($predecessorAuthority) -and
                $predecessorAuthority -notmatch 'redacted|missing|none'
            return -not $authorityVisible -or
                [string]::Equals(
                    $issuedAuthority,
                    $predecessorAuthority,
                    [System.StringComparison]::OrdinalIgnoreCase)
        } | Sort-Object Sequence, LineNumber)
        if ($supersessions.Count -ne 1) {
            return $null
        }

        $supersession = $supersessions[0]
        $successorGeneration = Get-ReceiveRecoveryOperationField `
            -Event $supersession `
            -Names @(
                'successor_receive_recovery_operation_generation',
                'successor_operation_generation')
        $successorAuthority = Get-ReceiveRecoveryOperationField `
            -Event $supersession `
            -Names @(
                'successor_receive_recovery_operation_authority_id',
                'successor_operation_authority_id')
        [object[]]$successorIssuedCandidates = @(
            Get-ReceiveRecoveryIndexedIssuedByGeneration `
                -Generation $successorGeneration)
        [object[]]$successorIssued = @($successorIssuedCandidates | Where-Object {
            if ([int64]$_.Sequence -le [int64]$supersession.Sequence -or
                (Get-ReceiveRecoveryOperationGeneration -Event $_) -ne $successorGeneration) {
                return $false
            }
            foreach ($field in @('session_id', 'transfer_id', 'direction')) {
                if ((Get-ReceiveRecoveryIdentityValue -Event $_ -Name $field) -ne
                    (Get-ReceiveRecoveryIdentityValue -Event $Issued -Name $field)) {
                    return $false
                }
            }
            foreach ($field in @(
                    'route',
                    'protocol_version',
                    'live_route_epoch',
                    'route_publication_generation',
                    'runtime_generation',
                    'terminal_generation',
                    'leg_generation',
                    'transport_epoch',
                    'bridge_recovery_generation',
                    'checkpoint_request_id',
                    'data_session_identity',
                    'data_session_generation')) {
                $predecessorValue = Get-ReceiveRecoveryIdentityValue `
                    -Event $Issued `
                    -Name $field
                $successorValue = Get-ReceiveRecoveryIdentityValue `
                    -Event $_ `
                    -Name $field
                if ([string]::IsNullOrWhiteSpace($predecessorValue) -or
                    [string]::IsNullOrWhiteSpace($successorValue) -or
                    -not [string]::Equals(
                        $predecessorValue,
                        $successorValue,
                        [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $false
                }
            }
            $candidateAuthority = Get-ReceiveRecoveryIdentityValue `
                -Event $_ `
                -Name 'receive_recovery_operation_authority_id'
            if ($successorAuthority -notmatch 'redacted|missing|none' -and
                $candidateAuthority -ne $successorAuthority) {
                return $false
            }
            $candidatePredecessorGeneration =
                Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @('predecessor_receive_recovery_operation_generation')
            $candidatePredecessorAuthority =
                Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @(
                        'predecessor_receive_recovery_operation_authority_id',
                        'predecessor_operation_authority_id')
            return $candidatePredecessorGeneration -eq $issuedGeneration -and
                (
                    $candidatePredecessorAuthority -match
                        'redacted|missing|none' -or
                    [string]::Equals(
                        $candidatePredecessorAuthority,
                        $issuedAuthority,
                        [System.StringComparison]::OrdinalIgnoreCase)
                )
        } | Sort-Object Sequence, LineNumber)
        if ($successorIssued.Count -ne 1) {
            return $null
        }

        $successor = $successorIssued[0]
        $successorOperationKey = Get-ReceiveRecoveryOperationKey -Event $successor
        [object[]]$successorEvents = @(
            Get-ReceiveRecoveryIndexedOperationEvents `
                -Key $successorOperationKey | Where-Object {
            [int64]$_.Sequence -gt [int64]$successor.Sequence -and
                (Test-ReceiveRecoveryOperationMatch `
                    -Anchor $successor `
                    -Candidate $_)
            })
        $successorStart = @($successorEvents | Where-Object {
            $_.EventName -in $eventNames.Started -and
            (Get-ReceiveRecoveryOperationField `
                -Event $_ `
                -Names @(
                    'execution_start_status',
                    'decision_status',
                    'start_status',
                    'status')) -in @('Started', 'Idempotent', 'Accepted')
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($successorStart.Count -ne 1) {
            return $null
        }
        $successorReceipt = @($successorEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$successorStart[0].Sequence -and
            $_.EventName -in $eventNames.Receipt -and
            (Get-ReceiveRecoveryOperationOutcome -Event $_) -in @(
                'completed',
                'exhausted',
                'discarded')
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($successorReceipt.Count -eq 1) {
            return $supersession
        }

        $successorInvalidation = @($successorEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$successorStart[0].Sequence -and
            $_.EventName -in $eventNames.Invalidated -and
            (
                (Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @(
                        'decision_reason',
                        'invalidation_reason',
                        'reason') `
                    -Default '').ToLowerInvariant() -notmatch
                        'ttl|missing.callback|observation.expir|bridge.started.timeout'
            )
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($successorInvalidation.Count -ne 1) {
            return $null
        }

        $closureAfterInvalidation = @($successorEvents | Where-Object {
            [int64]$_.Sequence -gt
                [int64]$successorInvalidation[0].Sequence -and
            $_.EventName -in @(
                $eventNames.ClosureRetained +
                $eventNames.ClosureAdopted +
                $eventNames.ClosureReserved +
                $eventNames.ClosureConsumed)
        } | Select-Object -First 1)
        if ($closureAfterInvalidation.Count -gt 0) {
            return $null
        }

        return $supersession
    }

    $recoveredEvents = New-Object System.Collections.Generic.List[object]
    $unresolvedEvents = New-Object System.Collections.Generic.List[object]
    foreach ($issued in @($distinctIssuedByKey.Values)) {
        $issuedOperationKey = Get-ReceiveRecoveryOperationKey -Event $issued
        [object[]]$operationEvents = @(
            Get-ReceiveRecoveryIndexedOperationEvents `
                -Key $issuedOperationKey | Where-Object {
                    [int64]$_.Sequence -ge [int64]$issued.Sequence
                })
        [object[]]$started = @($operationEvents | Where-Object {
            $_.EventName -in $eventNames.Started -and
            (Get-ReceiveRecoveryOperationField `
                -Event $_ `
                -Names @(
                    'execution_start_status',
                    'decision_status',
                    'start_status',
                    'status') `
                -Default '') -in
                @('Started', 'Idempotent', 'Accepted')
        })
        [object[]]$receipts = @($operationEvents | Where-Object {
            $_.EventName -in $eventNames.Receipt
        })
        [object[]]$proofs = @($operationEvents | Where-Object {
            $_.EventName -in $eventNames.Proof -and
            -not [string]::IsNullOrWhiteSpace(
                (Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @('proof_identity'))) -and
            (Get-FileTransferEventInt64Field `
                -Event $_ `
                -Name 'proof_observed_utc_ms' `
                -Default 0) -gt 0
        })
        [object[]]$terminalEvents = @($operationEvents | Where-Object {
            $_.EventName -in $eventNames.Terminal
        })
        [object[]]$invalidations = @($operationEvents | Where-Object {
            $_.EventName -in $eventNames.Invalidated
        })
        [object[]]$retained = @($operationEvents | Where-Object {
            $_.EventName -in $eventNames.ClosureRetained -and
            (Get-ReceiveRecoveryOperationField `
                -Event $_ `
                -Names @('closure_state')) -eq 'Retained'
        })
        [object[]]$adopted = @($operationEvents | Where-Object {
            $_.EventName -in $eventNames.ClosureAdopted -and
            (Get-ReceiveRecoveryOperationField `
                -Event $_ `
                -Names @('closure_state')) -eq 'Adopted'
        })
        [object[]]$reserved = @($operationEvents | Where-Object {
            $_.EventName -in $eventNames.ClosureReserved -and
            (Get-ReceiveRecoveryOperationField `
                -Event $_ `
                -Names @('closure_state')) -eq 'Reserved'
        })
        [object[]]$consumed = @($operationEvents | Where-Object {
            $_.EventName -in $eventNames.ClosureConsumed -and
            (Get-ReceiveRecoveryOperationField `
                -Event $_ `
                -Names @('closure_state')) -eq 'Consumed'
        })

        $resolved = $false
        $unresolvedEvent = $issued
        $startEvent = @($started | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        [object[]]$terminalReceipts = @($receipts | Where-Object {
            $receiptOutcome = Get-ReceiveRecoveryOperationOutcome -Event $_
            $afterIssue = [int64]$_.Sequence -gt [int64]$issued.Sequence
            $afterAcceptedStart =
                $startEvent.Count -gt 0 -and
                [int64]$_.Sequence -gt [int64]$startEvent[0].Sequence
            $afterIssue -and
                $receiptOutcome -in @('completed', 'exhausted', 'discarded') -and
                ($receiptOutcome -eq 'discarded' -or $afterAcceptedStart)
        } | Sort-Object Sequence, LineNumber)
        [object[]]$orderedInvalidations = @($invalidations | Where-Object {
            [int64]$_.Sequence -gt [int64]$issued.Sequence
        } | Sort-Object Sequence, LineNumber)
        $receipt = @($terminalReceipts | Select-Object -First 1)
        [object[]]$observationOnlyInvalidations = @(
            $orderedInvalidations | Where-Object {
                $reason = (Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @(
                        'decision_reason',
                        'invalidation_reason',
                        'reason') `
                    -Default '').ToLowerInvariant()
                $reason -match 'ttl|missing.callback|observation.expir|bridge.started.timeout'
            })
        [object[]]$authoritativeInvalidations = @(
            $orderedInvalidations | Where-Object {
                $reason = (Get-ReceiveRecoveryOperationField `
                    -Event $_ `
                    -Names @(
                        'decision_reason',
                        'invalidation_reason',
                        'reason') `
                    -Default '').ToLowerInvariant()
                $reason -notmatch 'ttl|missing.callback|observation.expir|bridge.started.timeout'
            })
        $authoritativeInvalidation = @(
            $authoritativeInvalidations | Select-Object -First 1)

        if ($authoritativeInvalidation.Count -gt 0) {
            [object[]]$closureEventsAfterInvalidation = @(
                @($retained) +
                @($adopted) +
                @($reserved) +
                @($consumed) |
                    Where-Object {
                        [int64]$_.Sequence -gt
                            [int64]$authoritativeInvalidation[0].Sequence
                    } |
                    Sort-Object Sequence, LineNumber)
            # Exact coordinator scope or terminal invalidation is a terminal
            # operation transition even after Completed/Retained/Adopted/
            # Reserved. Any later closure mutation is a stale-authority effect.
            $resolved = $closureEventsAfterInvalidation.Count -eq 0
            $unresolvedEvent = if ($resolved) {
                $authoritativeInvalidation[0]
            }
            else {
                $closureEventsAfterInvalidation[0]
            }
        }
        elseif ($receipt.Count -gt 0) {
            $receiptEvent = $receipt[0]
            $unresolvedEvent = $receiptEvent
            $outcome = Get-ReceiveRecoveryOperationOutcome -Event $receiptEvent
            $proofSequenceFloor = if ($startEvent.Count -gt 0) {
                [int64]$startEvent[0].Sequence
            }
            else {
                [int64]$issued.Sequence
            }
            [object[]]$orderedProofs = @($proofs | Where-Object {
                [int64]$_.Sequence -gt $proofSequenceFloor
            } | Sort-Object Sequence, LineNumber)
            $proofEvent = @($orderedProofs | Select-Object -First 1)
            $leaseGeneration = Get-ReceiveRecoveryOperationField `
                -Event $receiptEvent `
                -Names @(
                    'recovery_liveness_lease_generation',
                    'regular_v4_liveness_generation') `
                -Default '0'
            $hasRegularV4Closure = $leaseGeneration -match '^[1-9][0-9]*$'

            if ($outcome -in @('exhausted', 'discarded')) {
                $resolved = $retained.Count -eq 0 -and
                    $adopted.Count -eq 0 -and
                    $reserved.Count -eq 0 -and
                    $consumed.Count -eq 0
            }
            elseif ($outcome -eq 'completed' -and -not $hasRegularV4Closure) {
                $resolved = $proofEvent.Count -gt 0 -and
                    $retained.Count -eq 0 -and
                    $adopted.Count -eq 0 -and
                    $reserved.Count -eq 0 -and
                    $consumed.Count -eq 0
            }
            elseif ($outcome -eq 'completed') {
                $resolved = $false
                [object[]]$orderedAdopted = @()
                if ($proofEvent.Count -gt 0) {
                    $adoptionFloor = [Math]::Max(
                        [int64]$receiptEvent.Sequence,
                        [int64]$proofEvent[0].Sequence)
                    [object[]]$orderedAdopted = @($adopted | Where-Object {
                        [int64]$_.Sequence -gt $adoptionFloor
                    } | Sort-Object Sequence, LineNumber)
                    if ($orderedAdopted.Count -gt 0) {
                        $unresolvedEvent = $orderedAdopted[0]
                    }
                    else {
                        $unresolvedEvent = $proofEvent[0]
                    }
                }
                else {
                    [object[]]$orderedRetained = @($retained | Where-Object {
                        [int64]$_.Sequence -gt [int64]$receiptEvent.Sequence
                    } | Sort-Object Sequence, LineNumber)
                    if ($orderedRetained.Count -gt 0) {
                        $unresolvedEvent = $orderedRetained[0]
                    }
                }

                # The reservation must follow an exact adopted boundary.
                [object[]]$orderedReserved = @($reserved | Where-Object {
                    $orderedAdopted.Count -gt 0 -and
                    [int64]$_.Sequence -gt
                        [int64]$orderedAdopted[0].Sequence -and
                    (Get-ReceiveRecoveryOperationField `
                        -Event $_ `
                        -Names @('closure_generation')) -match '^[1-9][0-9]*$' -and
                    (Get-ReceiveRecoveryOperationField `
                        -Event $_ `
                        -Names @('closure_generation')) -eq
                    (Get-ReceiveRecoveryOperationField `
                        -Event $orderedAdopted[0] `
                        -Names @('closure_generation'))
                } | Sort-Object Sequence, LineNumber)

                if ($orderedReserved.Count -gt 0) {
                    $reservedEvent = $orderedReserved[0]
                    [object[]]$matchingConsumed = @($consumed | Where-Object {
                        [int64]$_.Sequence -gt [int64]$reservedEvent.Sequence -and
                        (Test-ReceiveRecoveryClosureBoundaryMatch `
                            -ReservedEvent $reservedEvent `
                            -Candidate $_)
                    } | Sort-Object Sequence, LineNumber)
                    $phase2Resolved = $false
                    foreach ($consumedEvent in $matchingConsumed) {
                        [object[]]$matchingStages = @($phase2StageEvents | Where-Object {
                            [int64]$_.Sequence -gt [int64]$reservedEvent.Sequence -and
                            (Get-ReceiveRecoveryOperationField `
                                -Event $_ `
                                -Names @('stage_status') `
                                -Default '') -in @('Staged', 'Idempotent') -and
                            (Test-ReceiveRecoveryPhase2TupleMatch `
                                -ClosureEvent $reservedEvent `
                                -Candidate $_ `
                                -IgnoreInstallGeneration)
                        } | Sort-Object Sequence, LineNumber)
                        foreach ($stageEvent in $matchingStages) {
                            [object[]]$matchingReceipts = @($phase2ReceiptIssuedEvents | Where-Object {
                                [int64]$_.Sequence -gt [int64]$stageEvent.Sequence -and
                                [int64]$_.Sequence -lt [int64]$consumedEvent.Sequence -and
                                (Get-ReceiveRecoveryOperationField `
                                    -Event $_ `
                                    -Names @('stage_status') `
                                    -Default '') -in @('Staged', 'Idempotent') -and
                                (Test-ReceiveRecoveryPhase2ChainEventMatch `
                                    -Left $stageEvent `
                                    -Right $_) -and
                                (Test-ReceiveRecoveryPhase2TupleMatch `
                                    -ClosureEvent $consumedEvent `
                                    -Candidate $_)
                            } | Sort-Object Sequence, LineNumber)
                            foreach ($receiptIssuedEvent in $matchingReceipts) {
                                $matchingCommit = @($phase2CommitEvents | Where-Object {
                                    [int64]$_.Sequence -gt [int64]$receiptIssuedEvent.Sequence -and
                                    [int64]$_.Sequence -lt [int64]$consumedEvent.Sequence -and
                                    (Get-ReceiveRecoveryOperationField `
                                        -Event $_ `
                                        -Names @('install_status') `
                                        -Default '') -in @('Installed', 'Idempotent') -and
                                    (Test-ReceiveRecoveryPhase2ChainEventMatch `
                                        -Left $receiptIssuedEvent `
                                        -Right $_ `
                                        -RequireInstallGeneration) -and
                                    (Test-ReceiveRecoveryPhase2TupleMatch `
                                        -ClosureEvent $consumedEvent `
                                        -Candidate $_)
                                }).Count -gt 0
                                if ($matchingCommit) {
                                    $phase2Resolved = $true
                                    break
                                }
                            }
                            if ($phase2Resolved) {
                                break
                            }
                        }
                        if ($phase2Resolved) {
                            break
                        }
                    }
                    if (-not $phase2Resolved) {
                        $unresolvedEvent = if ($matchingConsumed.Count -gt 0) {
                            $matchingConsumed[0]
                        }
                        else {
                            $reservedEvent
                        }
                    }
                    $resolved = $phase2Resolved
                }
                elseif ($consumed.Count -gt 0) {
                    # Consumption without an exact reservation is never proof.
                    $resolved = $false
                    $unresolvedEvent = @(
                        $consumed |
                            Sort-Object Sequence, LineNumber |
                            Select-Object -First 1)[0]
                }

                if (-not $resolved -and
                    $reserved.Count -eq 0 -and
                    $consumed.Count -eq 0) {
                    $supersessionClosure = $null
                    $supersessionProof = $null
                    if ($proofEvent.Count -eq 1 -and
                        $orderedAdopted.Count -gt 0) {
                        $supersessionClosure = $orderedAdopted[0]
                        $supersessionProof = $proofEvent[0]
                    }
                    elseif ($proofEvent.Count -eq 0) {
                        $retainedBoundary = @(
                            $retained |
                                Where-Object {
                                    [int64]$_.Sequence -gt
                                        [int64]$receiptEvent.Sequence
                                } |
                                Sort-Object Sequence, LineNumber |
                                Select-Object -First 1)
                        if ($retainedBoundary.Count -eq 1) {
                            $supersessionClosure = $retainedBoundary[0]
                        }
                    }

                    if ($null -ne $supersessionClosure) {
                        $supersessionResolution =
                            Get-ReceiveRecoverySupersessionResolution `
                                -Issued $issued `
                                -Receipt $receiptEvent `
                                -Closure $supersessionClosure `
                                -Proof $supersessionProof
                        if ($null -ne $supersessionResolution) {
                            $resolved = $true
                            $unresolvedEvent = $supersessionResolution
                        }
                    }
                }

            }
        }
        else {
            $observationOnlyInvalidation = @(
                $observationOnlyInvalidations | Select-Object -First 1)
            if ($observationOnlyInvalidation.Count -gt 0) {
                $unresolvedEvent = $observationOnlyInvalidation[0]
            }
            else {
                $lastObservedBoundary = @(
                    $operationEvents |
                        Where-Object {
                            [int64]$_.Sequence -gt [int64]$issued.Sequence
                        } |
                        Sort-Object Sequence, LineNumber |
                        Select-Object -Last 1)
                if ($lastObservedBoundary.Count -gt 0) {
                    $unresolvedEvent = $lastObservedBoundary[0]
                }
            }
        }

        if ($resolved) {
            $recoveredEvents.Add($issued) | Out-Null
        }
        else {
            $unresolvedEvents.Add($unresolvedEvent) | Out-Null
        }
    }

    $verdict = if ($unresolvedEvents.Count -gt 0) {
        'fail'
    }
    elseif ($distinctIssuedByKey.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    return [pscustomobject]@{
        RawCount = $issuedEvents.Count
        DistinctCount = $distinctIssuedByKey.Count
        RecoveredCount = $recoveredEvents.Count
        UnresolvedCount = $unresolvedEvents.Count
        Verdict = $verdict
        IssuedCount = $issuedEvents.Count
        StartedCount = [int64]$operationIdentityCounts.Started
        ExecutionReceiptAppliedCount = [int64]$operationIdentityCounts.Receipt
        ProofObservedCount = [int64]$operationIdentityCounts.Proof
        ClosureRetainedCount = [int64]$operationIdentityCounts.ClosureRetained
        ClosureAdoptedCount = [int64]$operationIdentityCounts.ClosureAdopted
        ClosureReservedCount = [int64]$operationIdentityCounts.ClosureReserved
        ClosureConsumedCount = [int64]$operationIdentityCounts.ClosureConsumed
        IndexBuildVisitCount = [int64]$correlationDiagnostics.IndexBuildVisitCount
        OperationKeyBuildCount = [int64]$correlationDiagnostics.OperationKeyBuildCount
        IndexedOperationEventCount = [int64]$correlationDiagnostics.IndexedOperationEventCount
        BoundedLookupVisitCount = [int64]$correlationDiagnostics.BoundedLookupVisitCount
        RecoveredCandidateEvents = @($recoveredEvents.ToArray())
        UnresolvedCandidateEvents = @($unresolvedEvents.ToArray())
    }
}

function Get-FileTransferReceiveRecoveryCompletedUnprovenSuccessorCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$events = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }

    function Get-CompletedUnprovenField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = ''
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(none)', 'none', '(missing)', '__missing__')) {
                return $value
            }
        }
        return $Default
    }

    function Test-CompletedUnprovenMeaningful {
        param([AllowNull()][AllowEmptyString()][string]$Value)

        return -not [string]::IsNullOrWhiteSpace($Value) -and
            $Value -notin @('(none)', 'none', '(missing)', '__missing__', '0')
    }

    function Test-CompletedUnprovenPresent {
        param([AllowNull()][AllowEmptyString()][string]$Value)

        return -not [string]::IsNullOrWhiteSpace($Value) -and
            $Value -notin @('(none)', 'none', '(missing)', '__missing__')
    }

    function Get-CompletedUnprovenOperationGeneration {
        param([Parameter(Mandatory = $true)]$Event)

        return Get-CompletedUnprovenField -Event $Event -Names @(
            'receive_recovery_operation_generation',
            'recovery_operation_generation',
            'operation_generation')
    }

    function Get-CompletedUnprovenOperationAuthority {
        param([Parameter(Mandatory = $true)]$Event)

        return Get-CompletedUnprovenField -Event $Event -Names @(
            'receive_recovery_operation_authority_id',
            'recovery_operation_authority_id')
    }

    function Test-CompletedUnprovenOperationMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        $anchorGeneration = Get-CompletedUnprovenOperationGeneration -Event $Anchor
        $candidateGeneration = Get-CompletedUnprovenOperationGeneration -Event $Candidate
        $anchorAuthority = Get-CompletedUnprovenOperationAuthority -Event $Anchor
        $candidateAuthority = Get-CompletedUnprovenOperationAuthority -Event $Candidate
        if (-not (Test-CompletedUnprovenMeaningful $anchorGeneration) -or
            -not (Test-CompletedUnprovenMeaningful $candidateGeneration) -or
            -not (Test-CompletedUnprovenMeaningful $anchorAuthority) -or
            -not (Test-CompletedUnprovenMeaningful $candidateAuthority) -or
            $anchorGeneration -ne $candidateGeneration -or
            -not [string]::Equals(
                $anchorAuthority,
                $candidateAuthority,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'route_publication_generation',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'bridge_decision_generation',
                'data_session_generation',
                'recovery_liveness_lease_generation')) {
            $anchorValue = Get-CompletedUnprovenField -Event $Anchor -Names @(
                $field,
                $(if ($field -eq 'recovery_liveness_lease_generation') {
                    'regular_v4_liveness_generation'
                } else {
                    "__unused_$field"
                }))
            $candidateValue = Get-CompletedUnprovenField -Event $Candidate -Names @(
                $field,
                $(if ($field -eq 'recovery_liveness_lease_generation') {
                    'regular_v4_liveness_generation'
                } else {
                    "__unused_$field"
                }))
            if (-not (Test-CompletedUnprovenPresent $anchorValue) -or
                -not (Test-CompletedUnprovenPresent $candidateValue) -or
                -not [string]::Equals(
                    $anchorValue,
                    $candidateValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-CompletedUnprovenRejectionScope {
        param(
            [Parameter(Mandatory = $true)]$Operation,
            [Parameter(Mandatory = $true)]$Rejection
        )

        foreach ($field in @(
                'log_writer_id',
                'session_id',
                'transfer_id',
                'direction')) {
            $operationValue = Get-CompletedUnprovenField -Event $Operation -Names @($field)
            $rejectionValue = Get-CompletedUnprovenField -Event $Rejection -Names @($field)
            if (-not (Test-CompletedUnprovenPresent $operationValue) -or
                -not (Test-CompletedUnprovenPresent $rejectionValue) -or
                -not [string]::Equals(
                    $operationValue,
                    $rejectionValue,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        foreach ($mapping in @(
                [pscustomobject]@{ Operation = 'route'; Rejection = @('current_route', 'attempted_route') },
                [pscustomobject]@{ Operation = 'protocol_version'; Rejection = @('current_protocol_version', 'attempted_protocol_version') },
                [pscustomobject]@{ Operation = 'live_route_epoch'; Rejection = @('current_live_route_epoch', 'attempted_live_route_epoch') },
                [pscustomobject]@{ Operation = 'runtime_generation'; Rejection = @('current_runtime_generation', 'attempted_runtime_generation') },
                [pscustomobject]@{ Operation = 'terminal_generation'; Rejection = @('current_terminal_generation', 'attempted_terminal_generation') },
                [pscustomobject]@{ Operation = 'leg_generation'; Rejection = @('attempted_leg_generation') },
                [pscustomobject]@{ Operation = 'transport_epoch'; Rejection = @('attempted_transport_epoch') },
                [pscustomobject]@{ Operation = 'bridge_recovery_generation'; Rejection = @('attempted_bridge_recovery_generation') })) {
            $operationValue = Get-CompletedUnprovenField -Event $Operation -Names @($mapping.Operation)
            $rejectionValue = Get-CompletedUnprovenField -Event $Rejection -Names $mapping.Rejection
            if ((Test-CompletedUnprovenPresent $rejectionValue) -and
                (-not (Test-CompletedUnprovenPresent $operationValue) -or
                 -not [string]::Equals(
                    $operationValue,
                    $rejectionValue,
                    [System.StringComparison]::OrdinalIgnoreCase))) {
                return $false
            }
        }
        return $true
    }

    function Get-CompletedUnprovenLogicalKey {
        param(
            [Parameter(Mandatory = $true)]$Issued,
            [Parameter(Mandatory = $true)]$Retained
        )

        return (@(
            Get-CompletedUnprovenOperationAuthority -Event $Issued
            Get-CompletedUnprovenOperationGeneration -Event $Issued
            Get-CompletedUnprovenField -Event $Retained -Names @('closure_generation')
            Get-CompletedUnprovenField -Event $Issued -Names @('recovery_liveness_lease_authority_id')
            Get-CompletedUnprovenField -Event $Issued -Names @(
                'recovery_liveness_lease_generation',
                'regular_v4_liveness_generation')
            Get-CompletedUnprovenField -Event $Issued -Names @('session_id')
            Get-CompletedUnprovenField -Event $Issued -Names @('transfer_id')
            Get-CompletedUnprovenField -Event $Issued -Names @('direction')
            Get-CompletedUnprovenField -Event $Issued -Names @('route')
            Get-CompletedUnprovenField -Event $Issued -Names @('protocol_version')
            Get-CompletedUnprovenField -Event $Issued -Names @('live_route_epoch')
            Get-CompletedUnprovenField -Event $Issued -Names @('route_publication_generation')
            Get-CompletedUnprovenField -Event $Issued -Names @('runtime_generation')
            Get-CompletedUnprovenField -Event $Issued -Names @('terminal_generation')
            Get-CompletedUnprovenField -Event $Issued -Names @('leg_generation')
            Get-CompletedUnprovenField -Event $Issued -Names @('transport_epoch')
            Get-CompletedUnprovenField -Event $Issued -Names @('bridge_recovery_generation')
            Get-CompletedUnprovenField -Event $Issued -Names @('data_session_generation')
        ) | ForEach-Object { ([string]$_).ToLowerInvariant() }) -join '|'
    }

    [object[]]$issuedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_receive_recovery_operation_issued' -and
        (Test-CompletedUnprovenMeaningful (
            Get-CompletedUnprovenOperationGeneration -Event $_)) -and
        (Test-CompletedUnprovenMeaningful (
            Get-CompletedUnprovenOperationAuthority -Event $_))
    })
    [object[]]$rejections = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_recovery_authority_rejected' -and
        (Get-CompletedUnprovenField -Event $_ -Names @('action_kind')) -eq
            'ReceiveRecoveryOperation' -and
        (Get-CompletedUnprovenField -Event $_ -Names @('rejection_reason', 'reason')) -eq
            'filetransfer_receive_recovery_operation_conflict' -and
        (Get-CompletedUnprovenField -Event $_ -Names @('attempted_action')) -in @(
            'bridge_ping_timeout',
            'bridge_receive_stall',
            'receive_stall',
            'ping_timeout')
    })

    $rawRecords = New-Object System.Collections.Generic.List[object]
    foreach ($rejection in $rejections) {
        $rejectionWriter = Get-CompletedUnprovenField -Event $rejection -Names @('log_writer_id')
        $rejectionObservation = @($events | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            $_.EventName -eq 'nkn_bridge_recovery_evaluation_requested' -and
            (Get-CompletedUnprovenField -Event $_ -Names @('log_writer_id')) -eq $rejectionWriter -and
            (Get-CompletedUnprovenField -Event $_ -Names @('transfer_id')) -eq
                (Get-CompletedUnprovenField -Event $rejection -Names @('transfer_id')) -and
            (Get-CompletedUnprovenField -Event $_ -Names @('observation_kind')) -in @(
                'ping_timeout',
                'receive_stall') -and
            (Test-CompletedUnprovenMeaningful (
                Get-CompletedUnprovenField -Event $_ -Names @('observation_generation')))
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        if ($rejectionObservation.Count -eq 0) {
            continue
        }
        $observationGeneration = Get-CompletedUnprovenField `
            -Event $rejectionObservation[0] `
            -Names @('observation_generation')
        $evaluationDecision = @($events | Where-Object {
            [int64]$_.Sequence -gt [int64]$rejection.Sequence -and
            $_.EventName -eq 'filetransfer_receive_recovery_evaluation_requested' -and
            (Get-CompletedUnprovenField -Event $_ -Names @('log_writer_id')) -eq $rejectionWriter -and
            (Get-CompletedUnprovenField -Event $_ -Names @('session_id')) -eq
                (Get-CompletedUnprovenField -Event $rejection -Names @('session_id')) -and
            (Get-CompletedUnprovenField -Event $_ -Names @('transfer_id')) -eq
                (Get-CompletedUnprovenField -Event $rejection -Names @('transfer_id')) -and
            (Get-CompletedUnprovenField -Event $_ -Names @('direction')) -eq
                (Get-CompletedUnprovenField -Event $rejection -Names @('direction')) -and
            (Get-CompletedUnprovenField -Event $_ -Names @('observation_generation')) -eq
                $observationGeneration -and
            (Get-FileTransferEventInt64Field `
                -Event $_ `
                -Name 'receive_recovery_operation_issued' `
                -Default -1) -eq 0
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($evaluationDecision.Count -eq 0) {
            continue
        }

        $eligibleOperations = New-Object System.Collections.Generic.List[object]
        foreach ($issued in @($issuedEvents | Where-Object {
                [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                (Get-CompletedUnprovenField -Event $_ -Names @('log_writer_id')) -eq
                    $rejectionWriter -and
                (Test-CompletedUnprovenRejectionScope `
                    -Operation $_ `
                    -Rejection $rejection)
            })) {
            [object[]]$operationEvents = @($events | Where-Object {
                [int64]$_.Sequence -gt [int64]$issued.Sequence -and
                [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                (Test-CompletedUnprovenOperationMatch `
                    -Anchor $issued `
                    -Candidate $_)
            })
            $start = @($operationEvents | Where-Object {
                $_.EventName -in @(
                    'filetransfer_receive_recovery_operation_execution_start_decided',
                    'filetransfer_receive_recovery_operation_execution_started') -and
                (Get-CompletedUnprovenField `
                    -Event $_ `
                    -Names @('execution_start_status', 'decision_status', 'status')) -in @(
                        'Started',
                        'Idempotent',
                        'Accepted')
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($start.Count -eq 0) {
                continue
            }
            $receipt = @($operationEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$start[0].Sequence -and
                $_.EventName -in @(
                    'filetransfer_receive_recovery_operation_execution_receipt_applied',
                    'filetransfer_receive_recovery_operation_receipt_applied') -and
                (Get-CompletedUnprovenField `
                    -Event $_ `
                    -Names @('execution_outcome', 'operation_outcome', 'outcome')) -eq
                    'Completed' -and
                (Get-CompletedUnprovenField `
                    -Event $_ `
                    -Names @('execution_state', 'operation_state') `
                    -Default 'Completed') -eq 'Completed' -and
                -not (Test-CompletedUnprovenMeaningful (
                    Get-CompletedUnprovenField -Event $_ -Names @('proof_identity'))) -and
                (Get-FileTransferEventInt64Field `
                    -Event $_ `
                    -Name 'proof_observed_utc_ms' `
                    -Default 0) -eq 0
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($receipt.Count -eq 0) {
                continue
            }
            $retained = @($operationEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$receipt[0].Sequence -and
                $_.EventName -eq 'filetransfer_receive_recovery_operation_closure_retained' -and
                (Get-CompletedUnprovenField -Event $_ -Names @('closure_state')) -eq
                    'Retained' -and
                (Test-CompletedUnprovenMeaningful (
                    Get-CompletedUnprovenField -Event $_ -Names @('closure_generation')))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($retained.Count -eq 0) {
                continue
            }
            $disqualifying = @($operationEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$retained[0].Sequence -and
                $_.EventName -in @(
                    'filetransfer_receive_recovery_operation_proof_observed',
                    'filetransfer_receive_recovery_operation_receive_proof_observed',
                    'filetransfer_receive_recovery_operation_closure_adopted',
                    'filetransfer_receive_recovery_operation_closure_reserved',
                    'filetransfer_receive_recovery_operation_closure_consumed',
                    'filetransfer_receive_recovery_operation_invalidated')
            })
            if ($disqualifying.Count -gt 0) {
                continue
            }

            $eligibleOperations.Add([pscustomobject]@{
                Issued = $issued
                Receipt = $receipt[0]
                Retained = $retained[0]
            }) | Out-Null
        }
        if ($eligibleOperations.Count -ne 1) {
            continue
        }

        $operation = $eligibleOperations[0]
        $rawRecords.Add([pscustomobject]@{
            Event = $rejection
            Issued = $operation.Issued
            Receipt = $operation.Receipt
            Retained = $operation.Retained
            Key = Get-CompletedUnprovenLogicalKey `
                -Issued $operation.Issued `
                -Retained $operation.Retained
        }) | Out-Null
    }

    $distinctRecords = [ordered]@{}
    foreach ($record in $rawRecords) {
        if (-not $distinctRecords.Contains($record.Key)) {
            $distinctRecords[$record.Key] = $record
        }
    }

    $recoveredEvents = New-Object System.Collections.Generic.List[object]
    $unresolvedEvents = New-Object System.Collections.Generic.List[object]
    foreach ($record in @($distinctRecords.Values)) {
        $issued = $record.Issued
        $rejection = $record.Event
        $recovered = $false

        $proof = @($events | Where-Object {
            [int64]$_.Sequence -gt [int64]$rejection.Sequence -and
            $_.EventName -in @(
                'filetransfer_receive_recovery_operation_proof_observed',
                'filetransfer_receive_recovery_operation_receive_proof_observed') -and
            (Test-CompletedUnprovenOperationMatch -Anchor $issued -Candidate $_) -and
            (Test-CompletedUnprovenMeaningful (
                Get-CompletedUnprovenField -Event $_ -Names @('proof_identity')))
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($proof.Count -gt 0) {
            $adoption = @($events | Where-Object {
                [int64]$_.Sequence -gt [int64]$proof[0].Sequence -and
                $_.EventName -eq 'filetransfer_receive_recovery_operation_closure_adopted' -and
                (Test-CompletedUnprovenOperationMatch -Anchor $issued -Candidate $_) -and
                (Get-CompletedUnprovenField -Event $_ -Names @('closure_state')) -eq
                    'Adopted' -and
                (Get-CompletedUnprovenField -Event $_ -Names @('closure_generation')) -eq
                    (Get-CompletedUnprovenField -Event $record.Retained -Names @('closure_generation'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            $invalidationBeforeAdoption = @($events | Where-Object {
                $_.EventName -eq 'filetransfer_receive_recovery_operation_invalidated' -and
                [int64]$_.Sequence -gt [int64]$rejection.Sequence -and
                ($adoption.Count -eq 0 -or
                 [int64]$_.Sequence -lt [int64]$adoption[0].Sequence) -and
                (Test-CompletedUnprovenOperationMatch -Anchor $issued -Candidate $_)
            }).Count -gt 0
            $recovered = $adoption.Count -gt 0 -and -not $invalidationBeforeAdoption
        }

        if (-not $recovered) {
            $supersession = @($events | Where-Object {
                [int64]$_.Sequence -gt [int64]$rejection.Sequence -and
                $_.EventName -eq 'filetransfer_receive_recovery_operation_superseded' -and
                (Get-CompletedUnprovenField -Event $_ -Names @(
                    'predecessor_receive_recovery_operation_generation',
                    'predecessor_operation_generation')) -eq
                    (Get-CompletedUnprovenOperationGeneration -Event $issued) -and
                (Get-CompletedUnprovenField -Event $_ -Names @(
                    'predecessor_receive_recovery_operation_authority_id',
                    'predecessor_operation_authority_id')) -eq
                    (Get-CompletedUnprovenOperationAuthority -Event $issued) -and
                (Get-CompletedUnprovenField -Event $_ -Names @('session_id')) -eq
                    (Get-CompletedUnprovenField -Event $issued -Names @('session_id')) -and
                (Get-CompletedUnprovenField -Event $_ -Names @('transfer_id')) -eq
                    (Get-CompletedUnprovenField -Event $issued -Names @('transfer_id')) -and
                (Get-CompletedUnprovenField -Event $_ -Names @('direction')) -eq
                    (Get-CompletedUnprovenField -Event $issued -Names @('direction'))
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($supersession.Count -gt 0) {
                $oldGeneration = [int64](
                    Get-CompletedUnprovenOperationGeneration -Event $issued)
                [object[]]$successors = @($issuedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$supersession[0].Sequence -and
                    [int64](Get-CompletedUnprovenOperationGeneration -Event $_) -gt
                        $oldGeneration -and
                    (Get-CompletedUnprovenField -Event $_ -Names @('session_id')) -eq
                        (Get-CompletedUnprovenField -Event $issued -Names @('session_id')) -and
                    (Get-CompletedUnprovenField -Event $_ -Names @('transfer_id')) -eq
                        (Get-CompletedUnprovenField -Event $issued -Names @('transfer_id')) -and
                    (Get-CompletedUnprovenField -Event $_ -Names @('direction')) -eq
                        (Get-CompletedUnprovenField -Event $issued -Names @('direction')) -and
                    (Get-CompletedUnprovenField -Event $_ -Names @('route')) -eq
                        (Get-CompletedUnprovenField -Event $issued -Names @('route')) -and
                    (Get-CompletedUnprovenField -Event $_ -Names @('runtime_generation')) -eq
                        (Get-CompletedUnprovenField -Event $issued -Names @('runtime_generation')) -and
                    (Get-CompletedUnprovenField -Event $_ -Names @('data_session_generation')) -eq
                        (Get-CompletedUnprovenField -Event $issued -Names @('data_session_generation'))
                } | Sort-Object Sequence, LineNumber)
                foreach ($successor in $successors) {
                    $successorStart = @($events | Where-Object {
                        [int64]$_.Sequence -gt [int64]$successor.Sequence -and
                        $_.EventName -in @(
                            'filetransfer_receive_recovery_operation_execution_start_decided',
                            'filetransfer_receive_recovery_operation_execution_started') -and
                        (Test-CompletedUnprovenOperationMatch `
                            -Anchor $successor `
                            -Candidate $_) -and
                        (Get-CompletedUnprovenField `
                            -Event $_ `
                            -Names @('execution_start_status', 'decision_status', 'status')) -in @(
                                'Started',
                                'Idempotent',
                                'Accepted')
                    } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                    if ($successorStart.Count -eq 0) {
                        continue
                    }
                    $successorReceipt = @($events | Where-Object {
                        [int64]$_.Sequence -gt [int64]$successorStart[0].Sequence -and
                        $_.EventName -in @(
                            'filetransfer_receive_recovery_operation_execution_receipt_applied',
                            'filetransfer_receive_recovery_operation_receipt_applied') -and
                        (Test-CompletedUnprovenOperationMatch `
                            -Anchor $successor `
                            -Candidate $_) -and
                        (Get-CompletedUnprovenField `
                            -Event $_ `
                            -Names @('execution_outcome', 'operation_outcome', 'outcome')) -in @(
                                'Completed',
                                'Exhausted',
                                'Discarded')
                    } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                    if ($successorReceipt.Count -gt 0) {
                        $recovered = $true
                        break
                    }
                }
            }
        }

        if ($recovered) {
            $recoveredEvents.Add($rejection) | Out-Null
        }
        else {
            $unresolvedEvents.Add($rejection) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $rawRecords.Count
        DistinctCount = $distinctRecords.Count
        RecoveredCount = $recoveredEvents.Count
        UnresolvedCount = $unresolvedEvents.Count
        Verdict = if ($unresolvedEvents.Count -gt 0) {
            'fail'
        }
        elseif ($distinctRecords.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($rawRecords.ToArray() | ForEach-Object { $_.Event })
        RecoveredCandidateEvents = @($recoveredEvents.ToArray())
        UnresolvedCandidateEvents = @($unresolvedEvents.ToArray())
    }
}

function Get-FileTransferReceiveRecoveryCompletedUnprovenPayloadHoldCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$events = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }
    [string[]]$scopeFields = @(
        'log_writer_id',
        'session_id',
        'transfer_id',
        'direction',
        'route',
        'protocol_version',
        'live_route_epoch',
        'route_publication_generation',
        'runtime_generation',
        'terminal_generation',
        'leg_generation',
        'transport_epoch',
        'bridge_recovery_generation',
        'data_session_generation')

    function Get-CompletedUnprovenPayloadHoldField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = '',
            [switch]$AllowNone
        )

        if ($null -eq $Event.PSObject.Properties['Fields'] -and
            $null -ne $Event.PSObject.Properties['Event']) {
            $Event = $Event.Event
        }
        if ($null -eq $Event -or
            $null -eq $Event.PSObject.Properties['Fields']) {
            return $Default
        }

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField `
                -Event $Event `
                -Name $name `
                -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(missing)', '__missing__') -and
                ($AllowNone -or $value -notin @('(none)', 'none'))) {
                return $value
            }
        }
        return $Default
    }

    function Test-CompletedUnprovenPayloadHoldVisible {
        param([AllowNull()][string]$Value)

        return -not [string]::IsNullOrWhiteSpace($Value) -and
            $Value -notmatch 'redacted|missing|none'
    }

    function Get-CompletedUnprovenPayloadHoldGeneration {
        param([Parameter(Mandatory = $true)]$Event)

        return Get-CompletedUnprovenPayloadHoldField `
            -Event $Event `
            -Names @(
                'receive_recovery_operation_generation',
                'recovery_operation_generation',
                'operation_generation')
    }

    function Get-CompletedUnprovenPayloadHoldAuthority {
        param([Parameter(Mandatory = $true)]$Event)

        return Get-CompletedUnprovenPayloadHoldField `
            -Event $Event `
            -Names @(
                'receive_recovery_operation_authority_id',
                'recovery_operation_authority_id')
    }

    function Test-CompletedUnprovenPayloadHoldScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in $scopeFields) {
            $left = Get-CompletedUnprovenPayloadHoldField `
                -Event $Anchor `
                -Names @($field)
            $right = Get-CompletedUnprovenPayloadHoldField `
                -Event $Candidate `
                -Names @($field)
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals(
                    $left,
                    $right,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        foreach ($optional in @(
                'checkpoint_request_id',
                'data_session_identity')) {
            $left = Get-CompletedUnprovenPayloadHoldField `
                -Event $Anchor `
                -Names @($optional) `
                -Default '(none)' `
                -AllowNone
            $right = Get-CompletedUnprovenPayloadHoldField `
                -Event $Candidate `
                -Names @($optional) `
                -Default '(none)' `
                -AllowNone
            if ($left -ne '(none)' -and
                $right -ne '(none)' -and
                -not [string]::Equals(
                    $left,
                    $right,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-CompletedUnprovenPayloadHoldOperationMatch {
        param(
            [Parameter(Mandatory = $true)]$Issued,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-CompletedUnprovenPayloadHoldScopeMatch `
                -Anchor $Issued `
                -Candidate $Candidate) -or
            (Get-CompletedUnprovenPayloadHoldGeneration -Event $Issued) -ne
                (Get-CompletedUnprovenPayloadHoldGeneration -Event $Candidate)) {
            return $false
        }

        $issuedAuthority =
            Get-CompletedUnprovenPayloadHoldAuthority -Event $Issued
        $candidateAuthority =
            Get-CompletedUnprovenPayloadHoldAuthority -Event $Candidate
        return -not (
            (Test-CompletedUnprovenPayloadHoldVisible $issuedAuthority) -and
            (Test-CompletedUnprovenPayloadHoldVisible $candidateAuthority) -and
            -not [string]::Equals(
                $issuedAuthority,
                $candidateAuthority,
                [System.StringComparison]::OrdinalIgnoreCase))
    }

    function Get-CompletedUnprovenPayloadHoldOperationKey {
        param([Parameter(Mandatory = $true)]$Issued)

        $parts = New-Object System.Collections.Generic.List[string]
        foreach ($field in $scopeFields) {
            $parts.Add((
                Get-CompletedUnprovenPayloadHoldField `
                    -Event $Issued `
                    -Names @($field) `
                    -Default '(missing)').ToLowerInvariant()) | Out-Null
        }
        $parts.Add((
            Get-CompletedUnprovenPayloadHoldGeneration -Event $Issued).
                ToLowerInvariant()) | Out-Null
        $parts.Add((
            Get-CompletedUnprovenPayloadHoldAuthority -Event $Issued).
                ToLowerInvariant()) | Out-Null
        return $parts -join '|'
    }

    function Test-CompletedUnprovenPayloadHoldSuccessorLineage {
        param(
            [Parameter(Mandatory = $true)]$Predecessor,
            [Parameter(Mandatory = $true)]$Supersession,
            [Parameter(Mandatory = $true)]$Successor
        )

        if (-not (Test-CompletedUnprovenPayloadHoldScopeMatch `
                -Anchor $Predecessor `
                -Candidate $Supersession) -or
            -not (Test-CompletedUnprovenPayloadHoldScopeMatch `
                -Anchor $Predecessor `
                -Candidate $Successor)) {
            return $false
        }

        $predecessorGeneration =
            Get-CompletedUnprovenPayloadHoldGeneration -Event $Predecessor
        $predecessorAuthority =
            Get-CompletedUnprovenPayloadHoldAuthority -Event $Predecessor
        $successorGeneration = Get-CompletedUnprovenPayloadHoldField `
            -Event $Supersession `
            -Names @('successor_receive_recovery_operation_generation')
        $successorAuthority = Get-CompletedUnprovenPayloadHoldField `
            -Event $Supersession `
            -Names @('successor_receive_recovery_operation_authority_id')
        $candidatePredecessorGeneration =
            Get-CompletedUnprovenPayloadHoldField `
                -Event $Successor `
                -Names @('predecessor_receive_recovery_operation_generation')
        $candidatePredecessorAuthority =
            Get-CompletedUnprovenPayloadHoldField `
                -Event $Successor `
                -Names @('predecessor_receive_recovery_operation_authority_id')
        if ((Get-CompletedUnprovenPayloadHoldGeneration -Event $Successor) -ne
                $successorGeneration -or
            $candidatePredecessorGeneration -ne $predecessorGeneration) {
            return $false
        }

        foreach ($pair in @(
                @($predecessorAuthority, $candidatePredecessorAuthority),
                @(
                    Get-CompletedUnprovenPayloadHoldAuthority -Event $Successor,
                    $successorAuthority))) {
            if ((Test-CompletedUnprovenPayloadHoldVisible $pair[0]) -and
                (Test-CompletedUnprovenPayloadHoldVisible $pair[1]) -and
                -not [string]::Equals(
                    $pair[0],
                    $pair[1],
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    [object[]]$issuedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_receive_recovery_operation_issued' -and
        (Get-CompletedUnprovenPayloadHoldField `
            -Event $_ `
            -Names @('direction')) -eq 'outbound' -and
        (Get-CompletedUnprovenPayloadHoldGeneration -Event $_) -match
            '^[1-9][0-9]*$'
    })
    $issuedByKey = [ordered]@{}
    foreach ($issued in $issuedEvents) {
        $key = Get-CompletedUnprovenPayloadHoldOperationKey -Issued $issued
        if (-not $issuedByKey.Contains($key)) {
            $issuedByKey[$key] = $issued
        }
    }
    [object[]]$distinctIssued = @($issuedByKey.Values)
    $rootByOperationKey = @{}
    foreach ($issued in @($distinctIssued | Sort-Object Sequence, LineNumber)) {
        $issuedKey = Get-CompletedUnprovenPayloadHoldOperationKey -Issued $issued
        $predecessorGeneration = Get-CompletedUnprovenPayloadHoldField `
            -Event $issued `
            -Names @('predecessor_receive_recovery_operation_generation') `
            -Default '0'
        $predecessorAuthority = Get-CompletedUnprovenPayloadHoldField `
            -Event $issued `
            -Names @('predecessor_receive_recovery_operation_authority_id')
        $predecessors = @($distinctIssued | Where-Object {
            [int64]$_.Sequence -lt [int64]$issued.Sequence -and
            (Get-CompletedUnprovenPayloadHoldGeneration -Event $_) -eq
                $predecessorGeneration -and
            (Test-CompletedUnprovenPayloadHoldScopeMatch `
                -Anchor $_ `
                -Candidate $issued) -and
            (
                -not (Test-CompletedUnprovenPayloadHoldVisible $predecessorAuthority) -or
                [string]::Equals(
                    (Get-CompletedUnprovenPayloadHoldAuthority -Event $_),
                    $predecessorAuthority,
                    [System.StringComparison]::OrdinalIgnoreCase)
            )
        })
        if ($predecessors.Count -eq 1) {
            $predecessorKey =
                Get-CompletedUnprovenPayloadHoldOperationKey `
                    -Issued $predecessors[0]
            if ($rootByOperationKey.ContainsKey($predecessorKey)) {
                $rootByOperationKey[$issuedKey] =
                    $rootByOperationKey[$predecessorKey]
                continue
            }
        }
        $rootByOperationKey[$issuedKey] = $issuedKey
    }

    [object[]]$starts = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_receive_recovery_operation_execution_start_decided',
            'filetransfer_receive_recovery_operation_execution_started') -and
        (Get-CompletedUnprovenPayloadHoldField `
            -Event $_ `
            -Names @(
                'execution_start_status',
                'decision_status',
                'start_status',
                'status')) -in @(
                    'Started',
                    'Idempotent',
                    'Accepted')
    })
    [object[]]$heldEvents = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_bridge_recovery_payload_submission_held'
    })
    [object[]]$receiptEvents = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_receive_recovery_operation_execution_receipt_applied',
            'filetransfer_receive_recovery_operation_receipt_applied') -and
        (Get-CompletedUnprovenPayloadHoldField `
            -Event $_ `
            -Names @('execution_outcome', 'operation_outcome', 'outcome')) -eq
                'Completed'
    })
    [object[]]$retainedEvents = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_operation_closure_retained' -and
        (Get-CompletedUnprovenPayloadHoldField `
            -Event $_ `
            -Names @('closure_state')) -eq 'Retained'
    })
    [object[]]$proofEvents = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_receive_recovery_operation_proof_observed',
            'filetransfer_receive_recovery_operation_receive_proof_observed')
    })
    [object[]]$adoptedEvents = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_operation_closure_adopted' -and
        (Get-CompletedUnprovenPayloadHoldField `
            -Event $_ `
            -Names @('closure_state')) -eq 'Adopted'
    })
    [object[]]$resumedEvents = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_bridge_recovery_payload_submission_resumed'
    })
    [object[]]$supersessions = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_operation_superseded' -and
        (Get-CompletedUnprovenPayloadHoldField `
            -Event $_ `
            -Names @('direction')) -eq 'outbound' -and
        (Get-CompletedUnprovenPayloadHoldField `
            -Event $_ `
            -Names @('decision_reason')) -eq
            'completed_unproven_receive_recovery_superseded_by_newer_health_observation' -and
        (Get-CompletedUnprovenPayloadHoldField `
            -Event $_ `
            -Names @('health_evaluation_kind')) -notin @('', '(none)', 'None') -and
        (Get-CompletedUnprovenPayloadHoldField `
            -Event $_ `
            -Names @('health_evidence_generation')) -match '^[1-9][0-9]*$'
    })

    function Get-CompletedUnprovenPayloadHoldSuccessor {
        param(
            [Parameter(Mandatory = $true)]$Predecessor,
            [Parameter(Mandatory = $true)]$Supersession
        )

        $matches = @($distinctIssued | Where-Object {
            [int64]$_.Sequence -gt [int64]$Supersession.Sequence -and
            (Test-CompletedUnprovenPayloadHoldSuccessorLineage `
                -Predecessor $Predecessor `
                -Supersession $Supersession `
                -Successor $_)
        })
        if ($matches.Count -ne 1) {
            return $null
        }
        return $matches[0]
    }

    function Test-CompletedUnprovenPayloadHoldRecovered {
        param([Parameter(Mandatory = $true)]$InitialSuccessor)

        $current = $InitialSuccessor
        for ($depth = 0; $depth -lt 64; $depth++) {
            $start = @($starts | Where-Object {
                [int64]$_.Sequence -gt [int64]$current.Sequence -and
                (Test-CompletedUnprovenPayloadHoldOperationMatch `
                    -Issued $current `
                    -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($start.Count -ne 1) {
                return $false
            }

            $receipt = @($receiptEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$start[0].Sequence -and
                (Test-CompletedUnprovenPayloadHoldOperationMatch `
                    -Issued $current `
                    -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            $proof = @($proofEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$start[0].Sequence -and
                (Test-CompletedUnprovenPayloadHoldOperationMatch `
                    -Issued $current `
                    -Candidate $_) -and
                (Get-CompletedUnprovenPayloadHoldField `
                    -Event $_ `
                    -Names @('proof_identity')) -notin @(
                        '',
                        '(none)',
                        'none') -and
                (Get-CompletedUnprovenPayloadHoldField `
                    -Event $_ `
                    -Names @('proof_observed_utc_ms')) -match
                        '^[1-9][0-9]*$'
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($receipt.Count -eq 1 -and $proof.Count -eq 1) {
                $adoptionFloor = [Math]::Max(
                    [int64]$receipt[0].Sequence,
                    [int64]$proof[0].Sequence)
                $adopted = @($adoptedEvents | Where-Object {
                    [int64]$_.Sequence -gt $adoptionFloor -and
                    (Test-CompletedUnprovenPayloadHoldOperationMatch `
                        -Issued $current `
                        -Candidate $_)
                } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                if ($adopted.Count -eq 1) {
                    $earlyResume = @($resumedEvents | Where-Object {
                        [int64]$_.Sequence -gt [int64]$receipt[0].Sequence -and
                        [int64]$_.Sequence -lt [int64]$adopted[0].Sequence -and
                        (Test-CompletedUnprovenPayloadHoldOperationMatch `
                            -Issued $current `
                            -Candidate $_)
                    }).Count -gt 0
                    $release = @($resumedEvents | Where-Object {
                        [int64]$_.Sequence -gt [int64]$adopted[0].Sequence -and
                        (Test-CompletedUnprovenPayloadHoldOperationMatch `
                            -Issued $current `
                            -Candidate $_)
                    } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
                    return -not $earlyResume -and $release.Count -eq 1
                }
            }

            if ($receipt.Count -ne 1) {
                return $false
            }
            $earlyResume = @($resumedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$receipt[0].Sequence -and
                (Test-CompletedUnprovenPayloadHoldOperationMatch `
                    -Issued $current `
                    -Candidate $_)
            } | Select-Object -First 1)
            if ($earlyResume.Count -gt 0) {
                return $false
            }

            $nextSupersession = @($supersessions | Where-Object {
                [int64]$_.Sequence -gt [int64]$receipt[0].Sequence -and
                (Get-CompletedUnprovenPayloadHoldField `
                    -Event $_ `
                    -Names @(
                        'predecessor_receive_recovery_operation_generation')) -eq
                    (Get-CompletedUnprovenPayloadHoldGeneration -Event $current) -and
                (Test-CompletedUnprovenPayloadHoldScopeMatch `
                    -Anchor $current `
                    -Candidate $_)
            } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
            if ($nextSupersession.Count -ne 1) {
                return $false
            }
            $next = Get-CompletedUnprovenPayloadHoldSuccessor `
                -Predecessor $current `
                -Supersession $nextSupersession[0]
            if ($null -eq $next) {
                return $false
            }
            $current = $next
        }
        return $false
    }

    $candidateRecords = New-Object System.Collections.Generic.List[object]
    foreach ($supersession in $supersessions) {
        $predecessorGeneration = Get-CompletedUnprovenPayloadHoldField `
            -Event $supersession `
            -Names @('predecessor_receive_recovery_operation_generation')
        $predecessorAuthority = Get-CompletedUnprovenPayloadHoldField `
            -Event $supersession `
            -Names @('predecessor_receive_recovery_operation_authority_id')
        $predecessors = @($distinctIssued | Where-Object {
            [int64]$_.Sequence -lt [int64]$supersession.Sequence -and
            (Get-CompletedUnprovenPayloadHoldGeneration -Event $_) -eq
                $predecessorGeneration -and
            (Test-CompletedUnprovenPayloadHoldScopeMatch `
                -Anchor $_ `
                -Candidate $supersession) -and
            (
                -not (Test-CompletedUnprovenPayloadHoldVisible $predecessorAuthority) -or
                [string]::Equals(
                    (Get-CompletedUnprovenPayloadHoldAuthority -Event $_),
                    $predecessorAuthority,
                    [System.StringComparison]::OrdinalIgnoreCase)
            )
        })
        if ($predecessors.Count -ne 1) {
            continue
        }
        $predecessor = $predecessors[0]
        $start = @($starts | Where-Object {
            [int64]$_.Sequence -gt [int64]$predecessor.Sequence -and
            [int64]$_.Sequence -lt [int64]$supersession.Sequence -and
            (Test-CompletedUnprovenPayloadHoldOperationMatch `
                -Issued $predecessor `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($start.Count -ne 1) {
            continue
        }
        $held = @($heldEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$start[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$supersession.Sequence -and
            (Test-CompletedUnprovenPayloadHoldOperationMatch `
                -Issued $predecessor `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($held.Count -ne 1) {
            continue
        }
        $receipt = @($receiptEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$start[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$supersession.Sequence -and
            (Test-CompletedUnprovenPayloadHoldOperationMatch `
                -Issued $predecessor `
                -Candidate $_) -and
            (Get-CompletedUnprovenPayloadHoldField `
                -Event $_ `
                -Names @('closure_state')) -eq 'Retained' -and
            (Get-CompletedUnprovenPayloadHoldField `
                -Event $_ `
                -Names @('proof_identity') `
                -Default '(none)' `
                -AllowNone) -in @('(none)', 'none')
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($receipt.Count -ne 1) {
            continue
        }
        $closureGeneration = Get-CompletedUnprovenPayloadHoldField `
            -Event $supersession `
            -Names @('predecessor_closure_generation')
        $retained = @($retainedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$receipt[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$supersession.Sequence -and
            (Test-CompletedUnprovenPayloadHoldOperationMatch `
                -Issued $predecessor `
                -Candidate $_) -and
            (Get-CompletedUnprovenPayloadHoldField `
                -Event $_ `
                -Names @('closure_generation')) -eq $closureGeneration
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($retained.Count -ne 1) {
            continue
        }
        $resume = @($resumedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$retained[0].Sequence -and
            [int64]$_.Sequence -lt [int64]$supersession.Sequence -and
            (Test-CompletedUnprovenPayloadHoldOperationMatch `
                -Issued $predecessor `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($resume.Count -ne 1) {
            continue
        }
        $successor = Get-CompletedUnprovenPayloadHoldSuccessor `
            -Predecessor $predecessor `
            -Supersession $supersession
        if ($null -eq $successor) {
            continue
        }
        $successorStart = @($starts | Where-Object {
            [int64]$_.Sequence -gt [int64]$successor.Sequence -and
            (Test-CompletedUnprovenPayloadHoldOperationMatch `
                -Issued $successor `
                -Candidate $_)
        } | Sort-Object Sequence, LineNumber | Select-Object -First 1)
        if ($successorStart.Count -ne 1) {
            continue
        }

        $predecessorKey =
            Get-CompletedUnprovenPayloadHoldOperationKey -Issued $predecessor
        $rootKey = if ($rootByOperationKey.ContainsKey($predecessorKey)) {
            $rootByOperationKey[$predecessorKey]
        }
        else {
            $predecessorKey
        }
        $candidateRecords.Add([pscustomobject]@{
            Event = $supersession
            RootKey = $rootKey
            Successor = $successor
        }) | Out-Null
    }

    $distinctByRoot = [ordered]@{}
    foreach ($record in $candidateRecords) {
        if (-not $distinctByRoot.Contains($record.RootKey)) {
            $distinctByRoot[$record.RootKey] = $record
        }
    }
    $recovered = New-Object System.Collections.Generic.List[object]
    $unresolved = New-Object System.Collections.Generic.List[object]
    foreach ($record in @($distinctByRoot.Values)) {
        if (Test-CompletedUnprovenPayloadHoldRecovered `
                -InitialSuccessor $record.Successor) {
            $recovered.Add($record.Event) | Out-Null
        }
        else {
            $unresolved.Add($record.Event) | Out-Null
        }
    }

    return [pscustomobject]@{
        RawCount = $candidateRecords.Count
        DistinctCount = $distinctByRoot.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) {
            'fail'
        }
        elseif ($distinctByRoot.Count -gt 0) {
            'pass'
        }
        else {
            'none'
        }
        RawCandidateEvents = @($candidateRecords | ForEach-Object { $_.Event })
        DistinctCandidateEvents = @(
            $distinctByRoot.Values | ForEach-Object { $_.Event })
        RecoveredCandidateEvents = @($recovered.ToArray())
        UnresolvedCandidateEvents = @($unresolved.ToArray())
    }
}

function Get-FileTransferReceiveRecoveryCompletedRetainedProofStatePublicationCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [switch]$AlreadyChronologicallyOrdered
    )

    [object[]]$events = if ($null -eq $Events -or $Events.Count -eq 0) {
        ,([object[]]@())
    }
    elseif ($AlreadyChronologicallyOrdered) {
        @($Events)
    }
    else {
        @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    }

    function Get-ProofStateField {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string[]]$Names,
            [string]$Default = ''
        )

        foreach ($name in $Names) {
            $value = Get-FileTransferEventField `
                -Event $Event `
                -Name $name `
                -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and
                $value -notin @('(missing)', '__missing__')) {
                return $value
            }
        }
        return $Default
    }

    function Test-ProofStateVisible {
        param([AllowNull()][string]$Value)

        return -not [string]::IsNullOrWhiteSpace($Value) -and
            $Value -notmatch 'redacted|missing|none'
    }

    function Test-ProofStateOperationMatch {
        param(
            [Parameter(Mandatory = $true)]$Issued,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in @(
                'log_writer_id',
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'route_publication_generation',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'data_session_generation')) {
            $left = Get-ProofStateField -Event $Issued -Names @($field)
            $right = Get-ProofStateField -Event $Candidate -Names @($field)
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals(
                    $left,
                    $right,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $issuedGeneration = Get-ProofStateField `
            -Event $Issued `
            -Names @(
                'receive_recovery_operation_generation',
                'recovery_operation_generation')
        $candidateGeneration = Get-ProofStateField `
            -Event $Candidate `
            -Names @(
                'receive_recovery_operation_generation',
                'recovery_operation_generation')
        if ($issuedGeneration -ne $candidateGeneration) {
            return $false
        }

        $issuedAuthority = Get-ProofStateField `
            -Event $Issued `
            -Names @(
                'receive_recovery_operation_authority_id',
                'recovery_operation_authority_id')
        $candidateAuthority = Get-ProofStateField `
            -Event $Candidate `
            -Names @(
                'receive_recovery_operation_authority_id',
                'recovery_operation_authority_id')
        return -not (
            (Test-ProofStateVisible $issuedAuthority) -and
            (Test-ProofStateVisible $candidateAuthority) -and
            -not [string]::Equals(
                $issuedAuthority,
                $candidateAuthority,
                [System.StringComparison]::OrdinalIgnoreCase))
    }

    function Test-ProofStatePublicationCommandMatch {
        param(
            [Parameter(Mandatory = $true)]$Issued,
            [Parameter(Mandatory = $true)]$Retained,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($field in @('session_id', 'transfer_id', 'direction')) {
            $left = Get-ProofStateField -Event $Issued -Names @($field)
            $right = Get-ProofStateField -Event $Candidate -Names @($field)
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals(
                    $left,
                    $right,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $issuedGeneration = Get-ProofStateField `
            -Event $Issued `
            -Names @(
                'receive_recovery_operation_generation',
                'recovery_operation_generation')
        $candidateGeneration = Get-ProofStateField `
            -Event $Candidate `
            -Names @(
                'receive_recovery_operation_generation',
                'recovery_operation_generation')
        $issuedBridgeDecisionGeneration = Get-ProofStateField `
            -Event $Issued `
            -Names @('bridge_decision_generation')
        $candidateBridgeDecisionGeneration = Get-ProofStateField `
            -Event $Candidate `
            -Names @('bridge_decision_generation')
        if ([string]::IsNullOrWhiteSpace($issuedGeneration) -or
            [string]::IsNullOrWhiteSpace($candidateGeneration) -or
            $issuedGeneration -ne $candidateGeneration) {
            return $false
        }
        if (-not [string]::IsNullOrWhiteSpace(
                $candidateBridgeDecisionGeneration) -and
            ([string]::IsNullOrWhiteSpace(
                    $issuedBridgeDecisionGeneration) -or
                $issuedBridgeDecisionGeneration -ne
                    $candidateBridgeDecisionGeneration)) {
            return $false
        }

        $issuedAuthority = Get-ProofStateField `
            -Event $Issued `
            -Names @(
                'receive_recovery_operation_authority_id',
                'recovery_operation_authority_id')
        $candidateAuthority = Get-ProofStateField `
            -Event $Candidate `
            -Names @(
                'receive_recovery_operation_authority_id',
                'recovery_operation_authority_id')
        if ((Test-ProofStateVisible $issuedAuthority) -and
            (Test-ProofStateVisible $candidateAuthority) -and
            -not [string]::Equals(
                $issuedAuthority,
                $candidateAuthority,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        $retainedClosureGeneration = Get-ProofStateField `
            -Event $Retained `
            -Names @('closure_generation')
        $candidateClosureGeneration = Get-ProofStateField `
            -Event $Candidate `
            -Names @('closure_generation')
        return [string]::IsNullOrWhiteSpace($candidateClosureGeneration) -or
            $candidateClosureGeneration -eq $retainedClosureGeneration
    }

    function Test-ProofStateOppositeOperationScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Publisher,
            [Parameter(Mandatory = $true)]$Target
        )

        if ((Get-ProofStateField -Event $Publisher -Names @('direction')) -ne
                'inbound' -or
            (Get-ProofStateField -Event $Target -Names @('direction')) -ne
                'outbound') {
            return $false
        }

        $publisherWriter =
            Get-ProofStateField -Event $Publisher -Names @('log_writer_id')
        $targetWriter =
            Get-ProofStateField -Event $Target -Names @('log_writer_id')
        if ([string]::IsNullOrWhiteSpace($publisherWriter) -or
            [string]::IsNullOrWhiteSpace($targetWriter) -or
            [string]::Equals(
                $publisherWriter,
                $targetWriter,
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        foreach ($field in @(
                'session_id',
                'transfer_id',
                'route',
                'protocol_version',
                'live_route_epoch',
                'route_publication_generation',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'data_session_generation')) {
            $left = Get-ProofStateField -Event $Publisher -Names @($field)
            $right = Get-ProofStateField -Event $Target -Names @($field)
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals(
                    $left,
                    $right,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-ProofStateHeartbeatPair {
        param(
            [Parameter(Mandatory = $true)]$Heartbeat,
            [Parameter(Mandatory = $true)]$Proof,
            [Parameter(Mandatory = $true)]$Publisher
        )

        if ($Heartbeat.EventName -ne 'session_liveness_heartbeat_received' -or
            $Proof.EventName -ne 'session_liveness_proof_received' -or
            (Get-ProofStateField -Event $Proof -Names @('proof_kind')) -ne
                'heartbeat_received' -or
            [int64]$Proof.Sequence -le [int64]$Heartbeat.Sequence) {
            return $false
        }

        $publisherWriter =
            Get-ProofStateField -Event $Publisher -Names @('log_writer_id')
        foreach ($event in @($Heartbeat, $Proof)) {
            if ((Get-ProofStateField -Event $event -Names @('log_writer_id')) -ne
                    $publisherWriter -or
                (Get-ProofStateField -Event $event -Names @('session_id')) -ne
                    (Get-ProofStateField -Event $Publisher -Names @('session_id'))) {
                return $false
            }
        }

        foreach ($field in @('generation', 'sequence', 'lane')) {
            $left = Get-ProofStateField -Event $Heartbeat -Names @($field)
            $right = Get-ProofStateField -Event $Proof -Names @($field)
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                $left -ne $right) {
                return $false
            }
        }

        return $true
    }

    function Get-ProofStatePublicationGeneration {
        param([Parameter(Mandatory = $true)]$Event)

        return Get-ProofStateField `
            -Event $Event `
            -Names @(
                'publication_generation',
                'receive_recovery_publication_generation')
    }

    function Get-ProofStateFrameFingerprint {
        param([Parameter(Mandatory = $true)]$Event)

        return Get-ProofStateField `
            -Event $Event `
            -Names @(
                'v4_state_wire_fingerprint',
                'wire_state_fingerprint',
                'receive_recovery_wire_state_fingerprint',
                'frame_fingerprint',
                'receive_recovery_frame_fingerprint')
    }

    function Get-ProofStateOperationKey {
        param(
            [Parameter(Mandatory = $true)]$Issued,
            [Parameter(Mandatory = $true)]$Retained
        )

        return [string]::Join('|', @(
            (Get-ProofStateField -Event $Issued -Names @('log_writer_id')),
            (Get-ProofStateField -Event $Issued -Names @('session_id')),
            (Get-ProofStateField -Event $Issued -Names @('transfer_id')),
            (Get-ProofStateField -Event $Issued -Names @('direction')),
            (Get-ProofStateField `
                -Event $Issued `
                -Names @(
                    'receive_recovery_operation_authority_id',
                    'recovery_operation_authority_id')),
            (Get-ProofStateField `
                -Event $Issued `
                -Names @(
                    'receive_recovery_operation_generation',
                    'recovery_operation_generation')),
            (Get-ProofStateField `
                -Event $Retained `
                -Names @('closure_generation')),
            (Get-ProofStateField `
                -Event $Issued `
                -Names @('bridge_decision_generation'))))
    }

    function Test-ProofStatePeerReceiptMatch {
        param(
            [Parameter(Mandatory = $true)]$StateSend,
            [Parameter(Mandatory = $true)]$TargetIssued,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if ($Candidate.EventName -ne 'filetransfer_v4_state_received' -or
            (Get-ProofStateField -Event $Candidate -Names @('direction')) -ne
                'outbound') {
            return $false
        }

        foreach ($field in @(
                'log_writer_id',
                'session_id',
                'transfer_id',
                'route',
                'protocol_version',
                'live_route_epoch',
                'route_publication_generation',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'transport_epoch',
                'bridge_recovery_generation',
                'data_session_generation')) {
            $left = Get-ProofStateField -Event $TargetIssued -Names @($field)
            $right = Get-ProofStateField -Event $Candidate -Names @($field)
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals(
                    $left,
                    $right,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $sentEpoch = Get-ProofStateField -Event $StateSend -Names @('epoch')
        $receivedEpoch =
            Get-ProofStateField -Event $Candidate -Names @('epoch')
        if ([string]::IsNullOrWhiteSpace($sentEpoch) -or
            $sentEpoch -ne $receivedEpoch) {
            return $false
        }

        $sentFingerprint = Get-ProofStateFrameFingerprint -Event $StateSend
        $receivedFingerprint =
            Get-ProofStateFrameFingerprint -Event $Candidate
        if ((Test-ProofStateVisible $sentFingerprint) -or
            (Test-ProofStateVisible $receivedFingerprint)) {
            return (Test-ProofStateVisible $sentFingerprint) -and
                (Test-ProofStateVisible $receivedFingerprint) -and
                [string]::Equals(
                    $sentFingerprint,
                    $receivedFingerprint,
                    [System.StringComparison]::OrdinalIgnoreCase)
        }

        return $true
    }

    function Select-ProofStatePeerReceipt {
        param(
            [Parameter(Mandatory = $true)][AllowEmptyCollection()][object[]]$Candidates
        )

        if ($Candidates.Count -eq 0) {
            return @()
        }

        $identityKeys = @($Candidates | ForEach-Object {
            $fingerprint = Get-ProofStateFrameFingerprint -Event $_
            if (-not (Test-ProofStateVisible $fingerprint)) {
                return ''
            }

            return [string]::Join('|', @(
                (Get-ProofStateField -Event $_ -Names @('log_writer_id')),
                (Get-ProofStateField -Event $_ -Names @('session_id')),
                (Get-ProofStateField -Event $_ -Names @('transfer_id')),
                (Get-ProofStateField -Event $_ -Names @('direction')),
                (Get-ProofStateField -Event $_ -Names @('route')),
                (Get-ProofStateField -Event $_ -Names @('protocol_version')),
                (Get-ProofStateField -Event $_ -Names @('live_route_epoch')),
                (Get-ProofStateField -Event $_ -Names @('route_publication_generation')),
                (Get-ProofStateField -Event $_ -Names @('runtime_generation')),
                (Get-ProofStateField -Event $_ -Names @('terminal_generation')),
                (Get-ProofStateField -Event $_ -Names @('leg_generation')),
                (Get-ProofStateField -Event $_ -Names @('transport_epoch')),
                (Get-ProofStateField -Event $_ -Names @('bridge_recovery_generation')),
                (Get-ProofStateField -Event $_ -Names @('data_session_generation')),
                (Get-ProofStateField -Event $_ -Names @('epoch')),
                $fingerprint)).ToLowerInvariant()
        } | Select-Object -Unique)

        if ($Candidates.Count -gt 1 -and
            ($identityKeys.Count -ne 1 -or
                [string]::IsNullOrWhiteSpace([string]$identityKeys[0]))) {
            return @()
        }

        $applied = @($Candidates | Where-Object {
            (Get-ProofStateField -Event $_ -Names @('applied')) -eq '1'
        } | Sort-Object Sequence | Select-Object -First 1)
        if ($applied.Count -eq 1) {
            return $applied
        }

        return @($Candidates | Sort-Object Sequence | Select-Object -First 1)
    }

    function Test-ProofStatePayloadAdmissionMatch {
        param(
            [Parameter(Mandatory = $true)]$Operation,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($mapping in @(
                @('session_id', 'session_id'),
                @('transfer_id', 'transfer_id'),
                @('direction', 'direction'),
                @('route', 'source_route'),
                @('protocol_version', 'source_protocol_version'),
                @('live_route_epoch', 'source_live_route_epoch'),
                @('route_publication_generation', 'source_route_publication_generation'),
                @('runtime_generation', 'source_runtime_generation'),
                @('terminal_generation', 'source_terminal_generation'),
                @('leg_generation', 'source_leg_generation'),
                @('transport_epoch', 'source_transport_epoch'),
                @('bridge_recovery_generation', 'source_bridge_recovery_generation'),
                @('data_session_generation', 'source_data_session_generation'))) {
            $left = Get-ProofStateField -Event $Operation -Names @($mapping[0])
            $right = Get-ProofStateField -Event $Candidate -Names @($mapping[1])
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals(
                    $left,
                    $right,
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return (Get-ProofStateField -Event $Candidate -Names @('send_kind')) -in @(
            'RegularV4Payload',
            'RegularV4Repair')
    }

    [object[]]$issuedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_receive_recovery_operation_issued' -and
        (Get-ProofStateField -Event $_ -Names @('direction')) -eq 'inbound' -and
        (Get-ProofStateField -Event $_ -Names @('route')) -eq
            'regular_nkn_v4_fast'
    })
    [object[]]$outboundIssuedEvents = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_receive_recovery_operation_issued' -and
        (Get-ProofStateField -Event $_ -Names @('direction')) -eq 'outbound' -and
        (Get-ProofStateField -Event $_ -Names @('route')) -eq
            'regular_nkn_v4_fast'
    })
    [object[]]$receiptEvents = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_receive_recovery_operation_execution_receipt_applied',
            'filetransfer_receive_recovery_operation_receipt_applied') -and
        (Get-ProofStateField `
            -Event $_ `
            -Names @('execution_outcome', 'operation_outcome', 'outcome')) -eq
                'Completed' -and
        (Get-ProofStateField -Event $_ -Names @('closure_state')) -eq
            'Retained'
    })
    [object[]]$retainedEvents = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_operation_closure_retained' -and
        (Get-ProofStateField -Event $_ -Names @('closure_state')) -eq
            'Retained'
    })
    [object[]]$diagnostics = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_bridge_recovery_lifecycle_diagnostic_only' -and
        (Get-ProofStateField -Event $_ -Names @('lifecycle')).ToLowerInvariant() -eq
            'receivestallrecoveryreceiveresumed' -and
        (Get-ProofStateField -Event $_ -Names @('reason')) -eq
            'coordinator_operation_receipt_or_proof_required'
    })
    [object[]]$readyEvents = @($events | Where-Object {
        $_.EventName -eq 'bridge_ready'
    })
    [object[]]$heartbeatEvents = @($events | Where-Object {
        $_.EventName -eq 'session_liveness_proof_received' -and
        (Get-ProofStateField -Event $_ -Names @('proof_kind')) -eq
            'heartbeat_received'
    })
    [object[]]$heartbeatReceivedEvents = @($events | Where-Object {
        $_.EventName -eq 'session_liveness_heartbeat_received'
    })
    [object[]]$decisions = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_receive_recovery_proof_state_publication_decided',
            'filetransfer_receive_recovery_proof_state_publication_resume_decided') -and
        (Get-ProofStateField `
            -Event $_ `
            -Names @('decision_status', 'status')) -in @(
                'Started',
                'Idempotent',
                'Accepted')
    })
    [object[]]$stateSends = @($events | Where-Object {
        $_.EventName -eq 'filetransfer_v4_state_sent' -and
        (Get-ProofStateField `
            -Event $_ `
            -Names @('repair_publication_kind')) -eq
            'receive_recovery_proof_state'
    })
    [object[]]$publicationReceipts = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_proof_state_publication_receipt_applied' -and
        (Get-ProofStateField `
            -Event $_ `
            -Names @('publication_outcome', 'outcome')) -eq 'Delivered' -and
        (Get-ProofStateField `
            -Event $_ `
            -Names @('decision_status', 'status')) -in @(
                'Accepted',
                'Idempotent')
    })
    [object[]]$publicationDispositionReceipts = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_proof_state_publication_receipt_applied' -and
        (Get-ProofStateField `
            -Event $_ `
            -Names @('publication_outcome', 'outcome')) -in @(
                'Held',
                'Rejected') -and
        (Get-ProofStateField `
            -Event $_ `
            -Names @('decision_status', 'status')) -in @(
                'Accepted',
                'Idempotent')
    })
    [object[]]$publicationAttempts = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_proof_state_publication_attempted'
    })
    [object[]]$activationPauseEvents = @($events | Where-Object {
        ($_.EventName -eq
            'filetransfer_tuna_activation_transport_pause_control_suppressed' -and
         (Get-ProofStateField -Event $_ -Names @('paused')) -eq '1' -and
         (Get-ProofStateField -Event $_ -Names @('reason')) -eq
            'tuna_activation_negotiating') -or
        ($_.EventName -eq 'filetransfer_transport_paused' -and
         (Get-ProofStateField -Event $_ -Names @('reason')) -eq
            'tuna_activation_negotiating')
    })
    [object[]]$activationReleaseEvents = @($events | Where-Object {
        ($_.EventName -eq
            'filetransfer_tuna_activation_transport_pause_control_suppressed' -and
         (Get-ProofStateField -Event $_ -Names @('paused')) -eq '0') -or
        $_.EventName -eq 'filetransfer_tuna_activation_local_barrier_released' -or
        $_.EventName -eq 'filetransfer_transport_resumed'
    })
    [object[]]$proofEvents = @($events | Where-Object {
        $_.EventName -in @(
            'filetransfer_receive_recovery_operation_proof_observed',
            'filetransfer_receive_recovery_operation_receive_proof_observed')
    })
    [object[]]$adoptedEvents = @($events | Where-Object {
        $_.EventName -eq
            'filetransfer_receive_recovery_operation_closure_adopted' -and
        (Get-ProofStateField -Event $_ -Names @('closure_state')) -eq
