function Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch {
    param(
        [Parameter(Mandatory = $true)]$Left,
        [Parameter(Mandatory = $true)]$Right
    )

    foreach ($field in @(Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields)) {
        $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
        $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
        if ([string]::IsNullOrWhiteSpace($leftValue) -or
            [string]::IsNullOrWhiteSpace($rightValue) -or
            -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
            return $false
        }
    }

    return $true
}

function Get-FileTransferRuntimeUnlockRetryDispatchInstallProof {
    param([object[]]$Events)

    [string[]]$authorityTupleFields = @(
        Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields
    )
    [string[]]$requestTupleFields = @(
        'request_regular_v4_liveness_generation',
        'request_bridge_decision_generation',
        'request_active_predecessor_supersession'
    )

    $allEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    $stageEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_decision_staged' -and
        (Get-FileTransferEventField -Event $_ -Name 'stage_status' -Default 'Staged') -in @('Staged', 'Idempotent')
    })
    $receiptEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_install_receipt_issued'
    })
    $committedEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_install_committed' -and
        (Get-FileTransferEventField -Event $_ -Name 'install_status' -Default 'Installed') -in @('Installed', 'Idempotent')
    })
    $rejectedEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_install_rejected'
    })
    $grantEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_granted'
    })
    $lifecycleStageDecisionEvents = @($allEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_lifecycle_stage_decided'
    })
    $phase2Events = @($stageEvents + $receiptEvents + $committedEvents + $rejectedEvents)
    [object[]]$phase2DeclaredGrantEvents = @($grantEvents | Where-Object {
        [int64]$installGeneration = 0
        $installGenerationText = Get-FileTransferEventField `
            -Event $_ `
            -Name 'install_generation' `
            -Default ''
        [int64]::TryParse($installGenerationText, [ref]$installGeneration) -and
            $installGeneration -gt 0
    })
    $phase2ProtocolObserved = $phase2Events.Count -gt 0 -or
        $phase2DeclaredGrantEvents.Count -gt 0

    function Get-InstallIdentityKey {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [switch]$IgnoreInstallGeneration
        )

        $parts = @($authorityTupleFields | ForEach-Object {
            Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
        })
        if ($Event.EventName -in @(
                'runtime_unlock_retry_dispatch_decision_staged',
                'runtime_unlock_retry_dispatch_install_receipt_issued',
                'runtime_unlock_retry_dispatch_install_committed',
                'runtime_unlock_retry_dispatch_install_rejected',
                'runtime_unlock_retry_dispatch_authority_granted')) {
            $parts += @($requestTupleFields | ForEach-Object {
                Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
            })
        }
        if (-not $IgnoreInstallGeneration) {
            $parts += Get-FileTransferEventField -Event $Event -Name 'install_generation' -Default '(missing)'
        }
        if ($Event.EventName -eq 'runtime_unlock_retry_dispatch_install_rejected') {
            $parts += Get-FileTransferEventField -Event $Event -Name 'install_status' -Default '(missing)'
            $parts += Get-FileTransferEventField -Event $Event -Name 'stage_cleared' -Default '(missing)'
            $parts += Get-FileTransferEventField -Event $Event -Name 'stage_disposition' -Default '(missing)'
        }
        return $parts -join '|'
    }

    function Get-DistinctInstallEvents {
        param(
            [object[]]$Candidates,
            [switch]$IgnoreInstallGeneration
        )

        $seen = @{}
        $result = New-Object System.Collections.Generic.List[object]
        foreach ($candidate in @($Candidates | Sort-Object Sequence, LineNumber)) {
            $key = Get-InstallIdentityKey -Event $candidate -IgnoreInstallGeneration:$IgnoreInstallGeneration
            if ($seen.ContainsKey($key)) {
                continue
            }
            $seen[$key] = $true
            $result.Add($candidate) | Out-Null
        }
        return @($result.ToArray())
    }

    function Test-InstallPrimaryIdentityMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        foreach ($field in @('session_id', 'transfer_id', 'direction', 'authority_id')) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        return $true
    }

    function Test-InstallEventBefore {
        param(
            [Parameter(Mandatory = $true)]$Earlier,
            [Parameter(Mandatory = $true)]$Later
        )

        $earlierSequence = [int64]$Earlier.Sequence
        $laterSequence = [int64]$Later.Sequence
        if ($earlierSequence -lt $laterSequence) {
            return $true
        }
        if ($earlierSequence -gt $laterSequence) {
            return $false
        }

        return [int64]$Earlier.LineNumber -lt [int64]$Later.LineNumber
    }

    function Test-InstallScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right,
            [switch]$RequireInstallGeneration,
            [switch]$RequireRequestTuple
        )

        foreach ($field in $authorityTupleFields) {
            $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
            $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($leftValue) -or
                [string]::IsNullOrWhiteSpace($rightValue) -or
                -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        if ($RequireRequestTuple) {
            foreach ($field in $requestTupleFields) {
                $leftValue = Get-FileTransferEventField -Event $Left -Name $field -Default ''
                $rightValue = Get-FileTransferEventField -Event $Right -Name $field -Default ''
                if ([string]::IsNullOrWhiteSpace($leftValue) -or
                    [string]::IsNullOrWhiteSpace($rightValue) -or
                    -not [string]::Equals($leftValue, $rightValue, [System.StringComparison]::Ordinal)) {
                    return $false
                }
            }
        }

        if ($RequireInstallGeneration) {
            $leftGeneration = Get-FileTransferEventField -Event $Left -Name 'install_generation' -Default ''
            $rightGeneration = Get-FileTransferEventField -Event $Right -Name 'install_generation' -Default ''
            if ([string]::IsNullOrWhiteSpace($leftGeneration) -or
                [string]::IsNullOrWhiteSpace($rightGeneration) -or
                $leftGeneration -ne $rightGeneration) {
                return $false
            }
        }

        return $true
    }

    function Test-InstallGenerationPositive {
        param([Parameter(Mandatory = $true)]$Event)

        [int64]$generation = 0
        $generationText = Get-FileTransferEventField `
            -Event $Event `
            -Name 'install_generation' `
            -Default ''
        return [int64]::TryParse($generationText, [ref]$generation) -and
            $generation -gt 0
    }

    function Get-InstallGrantBoundaryKey {
        param([Parameter(Mandatory = $true)]$Event)

        return (@(
                'session_id',
                'transfer_id',
                'direction',
                'authority_id',
                'install_generation') | ForEach-Object {
                Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
            }) -join '|'
    }

    function Test-InstallGrantBoundaryMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        return (Get-InstallGrantBoundaryKey -Event $Left) -eq
            (Get-InstallGrantBoundaryKey -Event $Right)
    }

    function Get-InstallGrantEvidenceFailureReason {
        param([Parameter(Mandatory = $true)]$Grant)

        foreach ($field in $requestTupleFields) {
            $value = Get-FileTransferEventField -Event $Grant -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none')) {
                return "retry_dispatch_grant_${field}_missing"
            }
        }

        [object[]]$referenceEvents = @(
            @($distinctCommitted + $distinctReceipts + $distinctStages) | Where-Object {
                (Test-InstallGrantBoundaryMatch -Left $Grant -Right $_) -and
                (Test-InstallEventBefore -Earlier $_ -Later $Grant)
            } | Sort-Object Sequence, LineNumber -Descending
        )
        if ($referenceEvents.Count -eq 0) {
            return 'retry_dispatch_grant_install_chain_missing'
        }

        $reference = $referenceEvents[0]
        foreach ($field in $requestTupleFields) {
            $grantValue = Get-FileTransferEventField -Event $Grant -Name $field -Default ''
            $referenceValue = Get-FileTransferEventField -Event $reference -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($referenceValue) -or
                -not [string]::Equals($grantValue, $referenceValue, [System.StringComparison]::Ordinal)) {
                return "retry_dispatch_grant_${field}_mismatch"
            }
        }

        foreach ($field in $authorityTupleFields) {
            $grantValue = Get-FileTransferEventField -Event $Grant -Name $field -Default ''
            $referenceValue = Get-FileTransferEventField -Event $reference -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($grantValue) -or
                [string]::IsNullOrWhiteSpace($referenceValue) -or
                -not [string]::Equals($grantValue, $referenceValue, [System.StringComparison]::Ordinal)) {
                return 'retry_dispatch_grant_authority_tuple_mismatch'
            }
        }

        return 'retry_dispatch_grant_install_chain_incomplete'
    }

    function New-InstallGrantEvidenceCandidateEvent {
        param(
            [Parameter(Mandatory = $true)]$Event,
            [Parameter(Mandatory = $true)][string]$Reason
        )

        $fields = @{}
        if ($null -ne $Event.Fields) {
            foreach ($key in @($Event.Fields.Keys)) {
                $fields[$key] = $Event.Fields[$key]
            }
        }
        $fields['decision_reason'] = $Reason

        return [pscustomobject]@{
            EventName = [string]$Event.EventName
            Sequence = [int64]$Event.Sequence
            LineNumber = [int]$Event.LineNumber
            FilePath = [string]$Event.FilePath
            FileName = [string]$Event.FileName
            Message = [string]$Event.Message
            RawLine = [string]$Event.RawLine
            TransferId = [string]$Event.TransferId
            Fields = $fields
        }
    }

    function Test-InstallRejectionDisposition {
        param(
            [Parameter(Mandatory = $true)]$Rejection,
            [switch]$RequireStageCleared
        )

        if ($Rejection.EventName -ne 'runtime_unlock_retry_dispatch_install_rejected' -or
            (Get-FileTransferEventField -Event $Rejection -Name 'install_status' -Default '') -ne 'Rejected') {
            return $false
        }

        if (-not $RequireStageCleared) {
            return $true
        }

        if ((Get-FileTransferEventField -Event $Rejection -Name 'stage_cleared' -Default '0') -ne '1') {
            return $false
        }

        $disposition = Get-FileTransferEventField `
            -Event $Rejection `
            -Name 'stage_disposition' `
            -Default ''
        return -not [string]::IsNullOrWhiteSpace($disposition) -and
            $disposition -notin @('(none)', 'none', 'unknown')
    }

    function Test-InstallStageClearedByDirectRejection {
        param(
            [Parameter(Mandatory = $true)]$Stage,
            [Parameter(Mandatory = $true)]$Rejection
        )

        [int64]$rejectionGeneration = -1
        $rejectionGenerationText = Get-FileTransferEventField `
            -Event $Rejection `
            -Name 'install_generation' `
            -Default ''
        return (Test-InstallRejectionDisposition -Rejection $Rejection -RequireStageCleared) -and
            [int64]::TryParse($rejectionGenerationText, [ref]$rejectionGeneration) -and
            $rejectionGeneration -eq 0 -and
            (Test-InstallScopeMatch -Left $Stage -Right $Rejection -RequireRequestTuple)
    }

    function Test-InstallStageClearedByCoordinatorDecision {
        param(
            [Parameter(Mandatory = $true)]$Stage,
            [Parameter(Mandatory = $true)]$Decision
        )

        if ($Decision.EventName -ne 'runtime_unlock_retry_lifecycle_stage_decided' -or
            (Get-FileTransferEventField -Event $Decision -Name 'decision_status' -Default '') -notin @(
                'Accepted',
                'Idempotent',
                'Expired')) {
            return $false
        }

        $lifecycleState = Get-FileTransferEventField `
            -Event $Decision `
            -Name 'lifecycle_state' `
            -Default ''
        if ($lifecycleState -notin @('Expired', 'Invalidated', 'Rejected', 'Closed')) {
            return $false
        }

        foreach ($fieldPair in @(
                @('session_id', 'session_id'),
                @('transfer_id', 'transfer_id'),
                @('direction', 'direction'),
                @('authority_id', 'authority_id'),
                @('predecessor_authority_id', 'predecessor_authority_id'),
                @('dispatch_attempt_generation', 'attempt_generation'),
                @('missing_dispatch_successor_generation', 'missing_dispatch_generation'))) {
            $stageValue = Get-FileTransferEventField `
                -Event $Stage `
                -Name $fieldPair[0] `
                -Default ''
            $decisionValue = Get-FileTransferEventField `
                -Event $Decision `
                -Name $fieldPair[1] `
                -Default ''
            if ([string]::IsNullOrWhiteSpace($decisionValue)) {
                # Preserve parity for transitional artifacts which projected
                # the coordinator field through the old Phase-2 name.
                $decisionValue = Get-FileTransferEventField `
                    -Event $Decision `
                    -Name $fieldPair[0] `
                    -Default ''
            }
            if ([string]::IsNullOrWhiteSpace($stageValue) -or
                [string]::IsNullOrWhiteSpace($decisionValue) -or
                -not [string]::Equals(
                    $stageValue,
                    $decisionValue,
                    [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        # A stage exists before an install generation is issued.  The
        # coordinator's exact terminal decision therefore uses generation
        # zero.  Infra observations cannot substitute for this decision.
        [int64]$installGeneration = -1
        $installGenerationText = Get-FileTransferEventField `
            -Event $Decision `
            -Name 'install_generation' `
            -Default ''
        return [int64]::TryParse($installGenerationText, [ref]$installGeneration) -and
            $installGeneration -eq 0
    }

    function Test-InstallReceiptClearedByExactRejection {
        param(
            [Parameter(Mandatory = $true)]$Receipt,
            [Parameter(Mandatory = $true)]$Rejection
        )

        return (Test-InstallRejectionDisposition -Rejection $Rejection -RequireStageCleared) -and
            (Test-InstallGenerationPositive -Event $Receipt) -and
            (Test-InstallScopeMatch `
                -Left $Receipt `
                -Right $Rejection `
                -RequireInstallGeneration `
                -RequireRequestTuple)
    }

    $distinctStages = @(Get-DistinctInstallEvents -Candidates $stageEvents -IgnoreInstallGeneration)
    $distinctReceipts = @(Get-DistinctInstallEvents -Candidates $receiptEvents)
    $distinctCommitted = @(Get-DistinctInstallEvents -Candidates $committedEvents)
    $distinctRejected = @(Get-DistinctInstallEvents -Candidates $rejectedEvents)
    $distinctGrants = @(Get-DistinctInstallEvents -Candidates $grantEvents)
    $effectiveGrants = New-Object System.Collections.Generic.List[object]
    $uncommittedGrants = New-Object System.Collections.Generic.List[object]

    foreach ($grant in $distinctGrants) {
        $phase2ForGrant = @($phase2Events | Where-Object {
            Test-InstallPrimaryIdentityMatch -Left $grant -Right $_
        })
        if ($phase2ForGrant.Count -eq 0) {
            [int64]$grantInstallGeneration = 0
            $grantInstallGenerationText = Get-FileTransferEventField `
                -Event $grant `
                -Name 'install_generation' `
                -Default ''
            if ([int64]::TryParse($grantInstallGenerationText, [ref]$grantInstallGeneration) -and
                $grantInstallGeneration -gt 0) {
                # A positive install generation declares the Phase-2 protocol.
                # Missing stage/receipt/commit evidence must fail closed rather
                # than being accepted through the legacy artifact path.
                $uncommittedGrants.Add($grant) | Out-Null
            }
            elseif (-not $phase2ProtocolObserved) {
                # Legacy artifacts predate the two-phase protocol. Once any
                # Phase-2 evidence exists in an artifact, a grant without its
                # install generation cannot borrow the legacy path.
                $effectiveGrants.Add($grant) | Out-Null
            }
            else {
                $uncommittedGrants.Add($grant) | Out-Null
            }
            continue
        }

        [object[]]$commit = @($distinctCommitted | Where-Object {
            (Test-InstallEventBefore -Earlier $_ -Later $grant) -and
            (Test-InstallScopeMatch `
                -Left $grant `
                -Right $_ `
                -RequireInstallGeneration `
                -RequireRequestTuple)
        } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        [object[]]$receipt = @()
        if ($commit.Count -gt 0) {
            $receipt = @($distinctReceipts | Where-Object {
                (Test-InstallEventBefore -Earlier $_ -Later $commit[0]) -and
                (Test-InstallScopeMatch `
                    -Left $commit[0] `
                    -Right $_ `
                    -RequireInstallGeneration `
                    -RequireRequestTuple)
            } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        }
        [object[]]$stage = @()
        if ($receipt.Count -gt 0) {
            $stage = @($distinctStages | Where-Object {
                (Test-InstallEventBefore -Earlier $_ -Later $receipt[0]) -and
                (Test-InstallScopeMatch -Left $grant -Right $_ -RequireRequestTuple) -and
                (Test-InstallScopeMatch -Left $receipt[0] -Right $_ -RequireRequestTuple)
            } | Sort-Object Sequence, LineNumber | Select-Object -Last 1)
        }
        $chainInvalidated = $false
        if ($commit.Count -gt 0 -and $receipt.Count -gt 0 -and $stage.Count -gt 0) {
            $stageClearedBeforeReceipt = @($distinctRejected | Where-Object {
                (Test-InstallEventBefore -Earlier $stage[0] -Later $_) -and
                (Test-InstallEventBefore -Earlier $_ -Later $receipt[0]) -and
                (Test-InstallStageClearedByDirectRejection `
                    -Stage $stage[0] `
                    -Rejection $_)
            }).Count -gt 0
            $receiptClearedBeforeCommit = @($distinctRejected | Where-Object {
                (Test-InstallEventBefore -Earlier $receipt[0] -Later $_) -and
                (Test-InstallEventBefore -Earlier $_ -Later $commit[0]) -and
                (Test-InstallReceiptClearedByExactRejection `
                    -Receipt $receipt[0] `
                    -Rejection $_)
            }).Count -gt 0
            $receiptRejectedAfterCommit = @($distinctRejected | Where-Object {
                (Test-InstallEventBefore -Earlier $commit[0] -Later $_) -and
                (Test-InstallEventBefore -Earlier $_ -Later $grant) -and
                (Test-InstallRejectionDisposition -Rejection $_) -and
                (Test-InstallScopeMatch `
                    -Left $commit[0] `
                    -Right $_ `
                    -RequireInstallGeneration `
                    -RequireRequestTuple)
            }).Count -gt 0
            $chainInvalidated = $stageClearedBeforeReceipt -or
                $receiptClearedBeforeCommit -or
                $receiptRejectedAfterCommit
        }
        if ($commit.Count -gt 0 -and
            $receipt.Count -gt 0 -and
            $stage.Count -gt 0 -and
            -not $chainInvalidated) {
            $effectiveGrants.Add($grant) | Out-Null
        }
        else {
            $uncommittedGrants.Add($grant) | Out-Null
        }
    }

    $pendingReceipts = @($distinctReceipts | Where-Object {
        $receipt = $_
        $resolvedByCommit = @($distinctCommitted | Where-Object {
            (Test-InstallEventBefore -Earlier $receipt -Later $_) -and
            (Test-InstallScopeMatch `
                -Left $receipt `
                -Right $_ `
                -RequireInstallGeneration `
                -RequireRequestTuple)
        })
        $resolvedByRejection = @($distinctRejected | Where-Object {
            (Test-InstallEventBefore -Earlier $receipt -Later $_) -and
            (Test-InstallReceiptClearedByExactRejection `
                -Receipt $receipt `
                -Rejection $_)
        })
        $resolvedByCommit.Count -eq 0 -and $resolvedByRejection.Count -eq 0
    })
    $pendingStages = @($distinctStages | Where-Object {
        $stage = $_
        $resolvedByReceipt = @($distinctReceipts | Where-Object {
            (Test-InstallEventBefore -Earlier $stage -Later $_) -and
            (Test-InstallGenerationPositive -Event $_) -and
            (Test-InstallScopeMatch -Left $stage -Right $_ -RequireRequestTuple)
        })
        $resolvedByRejection = @($distinctRejected | Where-Object {
            (Test-InstallEventBefore -Earlier $stage -Later $_) -and
            (Test-InstallStageClearedByDirectRejection `
                -Stage $stage `
                -Rejection $_)
        })
        $resolvedByCoordinatorDecision = @($lifecycleStageDecisionEvents | Where-Object {
            (Test-InstallEventBefore -Earlier $stage -Later $_) -and
            (Test-InstallStageClearedByCoordinatorDecision `
                -Stage $stage `
                -Decision $_)
        })
        $resolvedByReceipt.Count -eq 0 -and
            $resolvedByRejection.Count -eq 0 -and
            $resolvedByCoordinatorDecision.Count -eq 0
    })

    # A commit is proof only when the exact complete authority tuple first
    # passed through stage and receipt issuance in chronological order.  Do
    # this independently from authority_granted correlation so a commit-only
    # artifact cannot be accepted merely because no grant line survived.
    $orphanCommitted = @($distinctCommitted | Where-Object {
        $commit = $_
        $validChain = $false
        [object[]]$matchingReceipts = @($distinctReceipts | Where-Object {
            (Test-InstallEventBefore -Earlier $_ -Later $commit) -and
            (Test-InstallScopeMatch `
                -Left $commit `
                -Right $_ `
                -RequireInstallGeneration `
                -RequireRequestTuple)
        } | Sort-Object Sequence, LineNumber -Descending)
        foreach ($receipt in $matchingReceipts) {
            [object[]]$matchingStages = @($distinctStages | Where-Object {
                (Test-InstallEventBefore -Earlier $_ -Later $receipt) -and
                (Test-InstallScopeMatch -Left $receipt -Right $_ -RequireRequestTuple)
            } | Sort-Object Sequence, LineNumber -Descending)
            foreach ($stage in $matchingStages) {
                $interveningStageRejection = @($distinctRejected | Where-Object {
                    (Test-InstallEventBefore -Earlier $stage -Later $_) -and
                    (Test-InstallEventBefore -Earlier $_ -Later $receipt) -and
                    (Test-InstallStageClearedByDirectRejection `
                        -Stage $stage `
                        -Rejection $_)
                }).Count -gt 0
                $interveningReceiptRejection = @($distinctRejected | Where-Object {
                    (Test-InstallEventBefore -Earlier $receipt -Later $_) -and
                    (Test-InstallEventBefore -Earlier $_ -Later $commit) -and
                    (Test-InstallReceiptClearedByExactRejection `
                        -Receipt $receipt `
                        -Rejection $_)
                }).Count -gt 0
                if (-not $interveningStageRejection -and
                    -not $interveningReceiptRejection) {
                    $validChain = $true
                    break
                }
            }
            if ($validChain) {
                break
            }
        }
        -not $validChain
    })

    # A coordinator attempt has one install identity.  Exact duplicate commit
    # evidence is already deduplicated above; a second authority or install
    # generation for the same attempt is a conflicting installation and must
    # remain incomplete even if both individual stage chains are well formed.
    $attemptInstallConflicts = New-Object System.Collections.Generic.List[object]
    $committedByAttempt = @{}
    [string[]]$attemptScopeFields = @(
        'session_id',
        'transfer_id',
        'direction',
        'route',
        'route_kind',
        'protocol_version',
        'live_route_epoch',
        'runtime_generation',
        'terminal_generation',
        'leg_generation',
        'transport_epoch',
        'bridge_recovery_generation',
        'bridge_decision_generation',
        'route_publication_generation',
        'route_commit_generation',
        'contract_generation',
        'retired_generation',
        'dispatch_attempt_generation',
        'missing_dispatch_successor_generation',
        'predecessor_authority_id',
        'source_publication_generation',
        'source_publication_runtime_generation',
        'source_publication_terminal_generation',
        'source_publication_leg_generation',
        'source_publication_route_commit_generation',
        'runtime_owner_runtime_generation',
        'runtime_owner_terminal_generation',
        'request_regular_v4_liveness_generation',
        'request_bridge_decision_generation',
        'request_active_predecessor_supersession'
    )
    foreach ($commit in @($distinctCommitted | Sort-Object Sequence, LineNumber)) {
        $attemptKey = (@($attemptScopeFields | ForEach-Object {
                Get-FileTransferEventField -Event $commit -Name $_ -Default '(missing)'
            })) -join '|'
        $installIdentity = (@(
                'authority_id',
                'install_generation') | ForEach-Object {
                Get-FileTransferEventField -Event $commit -Name $_ -Default '(missing)'
            }) -join '|'

        if (-not $committedByAttempt.ContainsKey($attemptKey)) {
            $committedByAttempt[$attemptKey] = $installIdentity
            continue
        }

        if (-not [string]::Equals(
                [string]$committedByAttempt[$attemptKey],
                $installIdentity,
                [System.StringComparison]::Ordinal)) {
            $attemptInstallConflicts.Add($commit) | Out-Null
        }
    }
    $orphanCommitted = @(
        @($orphanCommitted + $attemptInstallConflicts.ToArray()) |
            Sort-Object Sequence, LineNumber -Unique
    )

    # A Phase-2 authority grant is effective only when its own complete tuple
    # correlates to stage, receipt, and commit.  Keep malformed retained copies
    # as evidence, but group them by the stable install boundary so a later
    # exact duplicate can recover the boundary without inflating grant count.
    $incompleteGrantRawCandidates = New-Object System.Collections.Generic.List[object]
    foreach ($grant in $grantEvents) {
        if (-not (Test-InstallGenerationPositive -Event $grant)) {
            continue
        }

        [int64]$receiveRecoveryOperationGeneration = 0
        $receiveRecoveryOperationGenerationText =
            Get-FileTransferEventField `
                -Event $grant `
                -Name 'receive_recovery_operation_generation' `
                -Default '0'
        if ([int64]::TryParse(
                $receiveRecoveryOperationGenerationText,
                [ref]$receiveRecoveryOperationGeneration) -and
            $receiveRecoveryOperationGeneration -gt 0) {
            # A closure-backed Phase-2 grant is part of the persistent receive-
            # recovery operation. Its exact stage/install validity is classified
            # by that operation's shared correlator, so the legacy grant proof
            # must not create a second failure for the same boundary.
            continue
        }

        $exactEffectiveGrant = @($effectiveGrants.ToArray() | Where-Object {
            Test-InstallScopeMatch `
                -Left $grant `
                -Right $_ `
                -RequireInstallGeneration `
                -RequireRequestTuple
        }).Count -gt 0
        if ($exactEffectiveGrant) {
            continue
        }

        $reason = Get-InstallGrantEvidenceFailureReason -Grant $grant
        $incompleteGrantRawCandidates.Add(
            (New-InstallGrantEvidenceCandidateEvent -Event $grant -Reason $reason)) | Out-Null
    }

    $incompleteGrantDistinctCandidates = New-Object System.Collections.Generic.List[object]
    $incompleteGrantRecoveredCandidates = New-Object System.Collections.Generic.List[object]
    $incompleteGrantUnresolvedCandidates = New-Object System.Collections.Generic.List[object]
    $seenIncompleteGrantBoundaries = @{}
    foreach ($candidate in @($incompleteGrantRawCandidates.ToArray() | Sort-Object Sequence, LineNumber)) {
        $boundaryKey = Get-InstallGrantBoundaryKey -Event $candidate
        if ($seenIncompleteGrantBoundaries.ContainsKey($boundaryKey)) {
            continue
        }
        $seenIncompleteGrantBoundaries[$boundaryKey] = $true
        $incompleteGrantDistinctCandidates.Add($candidate) | Out-Null

        $recovered = @($effectiveGrants.ToArray() | Where-Object {
            Test-InstallGrantBoundaryMatch -Left $candidate -Right $_
        }).Count -gt 0
        if ($recovered) {
            $incompleteGrantRecoveredCandidates.Add($candidate) | Out-Null
        }
        else {
            $incompleteGrantUnresolvedCandidates.Add($candidate) | Out-Null
        }
    }

    $grantEvidenceVerdict = if ($phase2DeclaredGrantEvents.Count -eq 0) {
        'none'
    }
    elseif ($incompleteGrantUnresolvedCandidates.Count -gt 0) {
        'fail'
    }
    else {
        'pass'
    }

    [object[]]$otherUncommittedGrantEvents = @($uncommittedGrants.ToArray() | Where-Object {
        -not (Test-InstallGenerationPositive -Event $_)
    })

    $verdict = if ($pendingStages.Count -gt 0 -or
        $pendingReceipts.Count -gt 0 -or
        $orphanCommitted.Count -gt 0 -or
        $otherUncommittedGrantEvents.Count -gt 0 -or
        $incompleteGrantUnresolvedCandidates.Count -gt 0) {
        'incomplete'
    }
    elseif ($phase2Events.Count -eq 0) {
        'none'
    }
    else {
        'pass'
    }

    return [pscustomobject]@{
        DecisionStagedCount = $distinctStages.Count
        ReceiptIssuedCount = $distinctReceipts.Count
        CommittedCount = $distinctCommitted.Count
        RejectedCount = $distinctRejected.Count
        Verdict = $verdict
        ProtocolObserved = $phase2ProtocolObserved
        AuthorityGrantedRawCount = $grantEvents.Count
        EffectiveGrantEvents = @($effectiveGrants.ToArray())
        UncommittedGrantEvents = @($otherUncommittedGrantEvents + $incompleteGrantUnresolvedCandidates.ToArray())
        OrphanCommittedEvents = @($orphanCommitted)
        GrantEvidenceIncompleteRawCount = $incompleteGrantRawCandidates.Count
        GrantEvidenceIncompleteDistinctCount = $incompleteGrantDistinctCandidates.Count
        GrantEvidenceIncompleteRecoveredCount = $incompleteGrantRecoveredCandidates.Count
        GrantEvidenceIncompleteUnresolvedCount = $incompleteGrantUnresolvedCandidates.Count
        GrantEvidenceVerdict = $grantEvidenceVerdict
        GrantEvidenceRawCandidateEvents = @($incompleteGrantRawCandidates.ToArray())
        GrantEvidenceDistinctCandidateEvents = @($incompleteGrantDistinctCandidates.ToArray())
        GrantEvidenceRecoveredCandidateEvents = @($incompleteGrantRecoveredCandidates.ToArray())
        GrantEvidenceUnresolvedCandidateEvents = @($incompleteGrantUnresolvedCandidates.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockRetryDispatchPostGrantHoldCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$heldEvents = @($orderedEvents | Where-Object {
        $_.EventName -like 'runtime_unlock_retry_dispatch_held_*'
    })
    [object[]]$dispatchObservedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_observed'
    })
    [object[]]$settledEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_contract_settled'
    })
    [object[]]$settlementReports = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_reported'
    })
    [object[]]$settlementDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_decided'
    })
    [object[]]$listenerRearmCompletedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'session_recovery_contract_listener_rearm_completed' -and
        (Get-FileTransferEventField -Event $_ -Name 'listener_rearm_completed' -Default '1') -eq '1'
    })
    [object[]]$retryDispatchedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'session_recovery_contract_retry_dispatched' -and
        (Get-FileTransferEventField -Event $_ -Name 'retry_dispatched' -Default '1') -eq '1'
    })
    [object[]]$offerWindowRefreshedEvents = @($orderedEvents | Where-Object {
        $_.EventName -eq 'session_recovery_contract_retry_authority_offer_window_refreshed'
    })

    function Test-PostGrantExactMatch {
        param(
            [Parameter(Mandatory = $true)]$Left,
            [Parameter(Mandatory = $true)]$Right
        )

        if (-not (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch `
                -Left $Left `
                -Right $Right)) {
            return $false
        }

        $leftInstallGeneration = Get-FileTransferEventField -Event $Left -Name 'install_generation' -Default ''
        $rightInstallGeneration = Get-FileTransferEventField -Event $Right -Name 'install_generation' -Default ''
        [int64]$rightPositiveGeneration = 0
        if ([int64]::TryParse($rightInstallGeneration, [ref]$rightPositiveGeneration) -and
            $rightPositiveGeneration -gt 0) {
            return -not [string]::IsNullOrWhiteSpace($leftInstallGeneration) -and
                [string]::Equals($leftInstallGeneration, $rightInstallGeneration, [System.StringComparison]::Ordinal)
        }

        return $true
    }

    function Get-PostGrantAcceptedSettlement {
        param(
            [Parameter(Mandatory = $true)]$Grant,
            [Parameter(Mandatory = $true)][int64]$AfterSequence,
            [string]$Outcome = ''
        )

        [object[]]$matchingSettlements = @($settledEvents | Where-Object {
            [int64]$_.Sequence -gt $AfterSequence -and
            ([string]::IsNullOrWhiteSpace($Outcome) -or
                (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq $Outcome) -and
            (Test-PostGrantExactMatch -Left $Grant -Right $_)
        } | Sort-Object Sequence, LineNumber)
        foreach ($settlement in $matchingSettlements) {
            $settlementOutcome = Get-FileTransferEventField -Event $settlement -Name 'settlement_outcome' -Default ''
            $settlementReason = Get-FileTransferEventField -Event $settlement -Name 'decision_reason' -Default ''
            [object[]]$matchingReports = @($settlementReports | Where-Object {
                [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq $settlementOutcome -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq $settlementReason -and
                (Test-PostGrantExactMatch -Left $Grant -Right $_)
            } | Sort-Object Sequence, LineNumber)
            if ($matchingReports.Count -eq 0) {
                continue
            }

            $report = $matchingReports[0]
            [object[]]$matchingDecisions = @($settlementDecisions | Where-Object {
                [int64]$_.Sequence -gt [int64]$report.Sequence -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq $settlementOutcome -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq $settlementReason -and
                (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent') -and
                (Test-PostGrantExactMatch -Left $Grant -Right $_)
            } | Sort-Object Sequence, LineNumber)
            if ($matchingDecisions.Count -gt 0) {
                return [pscustomobject]@{
                    Settlement = $settlement
                    Report = $report
                    Decision = $matchingDecisions[0]
                }
            }
        }

        return $null
    }

    function Test-PostGrantActiveSuccessorLineage {
        param(
            [Parameter(Mandatory = $true)]$PredecessorGrant,
            [Parameter(Mandatory = $true)]$SuccessorGrant
        )

        $predecessorAuthorityId = Get-FileTransferEventField -Event $PredecessorGrant -Name 'authority_id' -Default ''
        $successorAuthorityId = Get-FileTransferEventField -Event $SuccessorGrant -Name 'authority_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($predecessorAuthorityId) -or
            [string]::IsNullOrWhiteSpace($successorAuthorityId) -or
            $predecessorAuthorityId -in @('(none)', 'none') -or
            $successorAuthorityId -in @('(none)', 'none') -or
            (Get-FileTransferEventField -Event $SuccessorGrant -Name 'predecessor_authority_id' -Default '') -ne
                $predecessorAuthorityId -or
            (Get-FileTransferEventField -Event $SuccessorGrant -Name 'request_active_predecessor_supersession' -Default '') -notin
                @('1', 'true', 'True')) {
            return $false
        }

        [string[]]$mutableSuccessorFields = @(
            'authority_id',
            'authority_generation',
            'predecessor_authority_id',
            'bridge_decision_generation',
            'dispatch_attempt_generation',
            'recovery_reason')
        foreach ($field in @(Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields | Where-Object {
                    $_ -notin $mutableSuccessorFields
                })) {
            $predecessorValue = Get-FileTransferEventField -Event $PredecessorGrant -Name $field -Default ''
            $successorValue = Get-FileTransferEventField -Event $SuccessorGrant -Name $field -Default ''
            if ([string]::IsNullOrWhiteSpace($predecessorValue) -or
                [string]::IsNullOrWhiteSpace($successorValue) -or
                -not [string]::Equals($predecessorValue, $successorValue, [System.StringComparison]::Ordinal)) {
                return $false
            }
        }

        $predecessorAuthorityGeneration = Get-FileTransferEventInt64Field `
            -Event $PredecessorGrant -Name 'authority_generation' -Default -1
        $successorAuthorityGeneration = Get-FileTransferEventInt64Field `
            -Event $SuccessorGrant -Name 'authority_generation' -Default -1
        $predecessorAttempt = Get-FileTransferEventInt64Field `
            -Event $PredecessorGrant -Name 'dispatch_attempt_generation' -Default -1
        $successorAttempt = Get-FileTransferEventInt64Field `
            -Event $SuccessorGrant -Name 'dispatch_attempt_generation' -Default -1
        if ($successorAuthorityGeneration -ne ($predecessorAuthorityGeneration + 1) -or
            $successorAttempt -ne ($predecessorAttempt + 1)) {
            return $false
        }

        $requestBridgeDecisionGeneration = Get-FileTransferEventInt64Field `
            -Event $SuccessorGrant -Name 'request_bridge_decision_generation' -Default -1
        $predecessorBridgeDecisionGeneration = Get-FileTransferEventInt64Field `
            -Event $PredecessorGrant -Name 'bridge_decision_generation' -Default -2
        return $requestBridgeDecisionGeneration -eq $predecessorBridgeDecisionGeneration
    }

    function Get-PostGrantAcceptedActiveSuccessor {
        param(
            [Parameter(Mandatory = $true)]$Grant,
            [Parameter(Mandatory = $true)][int64]$AfterSequence
        )

        $acceptedSupersession = Get-PostGrantAcceptedSettlement `
            -Grant $Grant `
            -AfterSequence $AfterSequence `
            -Outcome 'Superseded'
        if ($null -eq $acceptedSupersession) {
            return $null
        }

        $successorAuthorityId = Get-FileTransferEventField `
            -Event $acceptedSupersession.Settlement `
            -Name 'successor_authority_id' `
            -Default ''
        if ([string]::IsNullOrWhiteSpace($successorAuthorityId) -or
            $successorAuthorityId -in @('(none)', 'none')) {
            return $null
        }

        [object[]]$matchingSuccessors = @($EffectiveGrantEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$acceptedSupersession.Decision.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '') -eq $successorAuthorityId -and
            (Test-PostGrantActiveSuccessorLineage -PredecessorGrant $Grant -SuccessorGrant $_)
        } | Sort-Object Sequence, LineNumber)
        if ($matchingSuccessors.Count -ne 1) {
            return $null
        }

        return [pscustomobject]@{
            Grant = $matchingSuccessors[0]
            Settlement = $acceptedSupersession.Settlement
            Decision = $acceptedSupersession.Decision
        }
    }

    function Test-PostGrantDispatchObserved {
        param(
            [Parameter(Mandatory = $true)]$Grant,
            [Parameter(Mandatory = $true)][int64]$AfterSequence
        )

        [object[]]$observed = @($dispatchObservedEvents | Where-Object {
            [int64]$_.Sequence -gt $AfterSequence -and
            (Test-PostGrantExactMatch -Left $Grant -Right $_)
        } | Sort-Object Sequence, LineNumber)
        if ($observed.Count -eq 0) {
            return $false
        }

        $acceptedDispatch = Get-PostGrantAcceptedSettlement `
            -Grant $Grant `
            -AfterSequence $AfterSequence `
            -Outcome 'DispatchObserved'
        return $null -ne $acceptedDispatch -and
            (Get-FileTransferEventField -Event $acceptedDispatch.Settlement -Name 'dispatch_observed' -Default '0') -eq '1'
    }

    function Test-PostGrantBoundedMissingDispatchClosure {
        param(
            [Parameter(Mandatory = $true)]$Grant,
            [Parameter(Mandatory = $true)][int64]$AfterSequence
        )

        [object[]]$matchingGrantState = @($EffectiveGrantEvents | Where-Object {
            [int64]$_.Sequence -le $AfterSequence -and
            (Test-FileTransferRuntimeUnlockRetryDispatchStateTupleMatch -Authority $Grant -Candidate $_)
        })
        if ($matchingGrantState.Count -ne 1 -or
            (Get-FileTransferEventField -Event $matchingGrantState[0] -Name 'authority_id' -Default '') -ne
                (Get-FileTransferEventField -Event $Grant -Name 'authority_id' -Default '')) {
            return $false
        }

        [object[]]$matchingRearms = @($listenerRearmCompletedEvents | Where-Object {
            [int64]$_.Sequence -gt $AfterSequence -and
            (Test-FileTransferRuntimeUnlockRetryDispatchStateTupleMatch -Authority $Grant -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        foreach ($rearm in $matchingRearms) {
            [object[]]$matchingDispatches = @($retryDispatchedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$rearm.Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchStateTupleMatch -Authority $Grant -Candidate $_)
            } | Sort-Object Sequence, LineNumber)
            if ($matchingDispatches.Count -eq 0) {
                continue
            }

            [object[]]$matchingWindows = @($offerWindowRefreshedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$matchingDispatches[0].Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchStateTupleMatch -Authority $Grant -Candidate $_) -and
                (Get-FileTransferEventInt64Field -Event $_ -Name 'offer_generation' -Default 0) -gt 0
            } | Sort-Object Sequence, LineNumber)
            if ($matchingWindows.Count -eq 0) {
                continue
            }

            $closure = Get-FileTransferRuntimeUnlockRetryDispatchBoundedMissingDispatchClosure `
                -Events $orderedEvents `
                -Grant $Grant `
                -AfterSequence ([int64]$matchingWindows[0].Sequence)
            if ($null -eq $closure) {
                continue
            }

            $windowOfferGeneration = Get-FileTransferEventField `
                -Event $matchingWindows[0] -Name 'offer_generation' -Default ''
            $settlementOfferGeneration = Get-FileTransferEventField `
                -Event $closure.Settlement -Name 'offer_generation' -Default ''
            if (-not [string]::IsNullOrWhiteSpace($windowOfferGeneration) -and
                [string]::Equals(
                    $windowOfferGeneration,
                    $settlementOfferGeneration,
                    [System.StringComparison]::Ordinal)) {
                return $true
            }
        }

        return $false
    }

    function Test-PostGrantHoldRecovered {
        param(
            [Parameter(Mandatory = $true)]$Grant,
            [Parameter(Mandatory = $true)][int64]$AfterSequence
        )

        $currentGrant = $Grant
        $currentBoundary = $AfterSequence
        $visitedAuthorities = New-Object 'System.Collections.Generic.HashSet[string]'
        for ($depth = 0; $depth -lt 16; $depth++) {
            $currentAuthorityId = Get-FileTransferEventField -Event $currentGrant -Name 'authority_id' -Default ''
            if ([string]::IsNullOrWhiteSpace($currentAuthorityId) -or
                -not $visitedAuthorities.Add($currentAuthorityId)) {
                return $false
            }

            if (Test-PostGrantDispatchObserved -Grant $currentGrant -AfterSequence $currentBoundary) {
                return $true
            }

            if (Test-PostGrantBoundedMissingDispatchClosure `
                    -Grant $currentGrant `
                    -AfterSequence $currentBoundary) {
                return $true
            }

            $successor = Get-PostGrantAcceptedActiveSuccessor `
                -Grant $currentGrant `
                -AfterSequence $currentBoundary
            if ($null -eq $successor) {
                return $false
            }

            $currentGrant = $successor.Grant
            $currentBoundary = [int64]$currentGrant.Sequence
        }

        return $false
    }

    function Get-PostGrantHoldKey {
        param([Parameter(Mandatory = $true)]$Event)

        $parts = @(Get-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleFields | ForEach-Object {
            Get-FileTransferEventField -Event $Event -Name $_ -Default '(missing)'
        })
        $parts += Get-FileTransferEventField -Event $Event -Name 'install_generation' -Default '(legacy)'
        return $parts -join '|'
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctRecords = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($grant in @($EffectiveGrantEvents | Sort-Object Sequence, LineNumber)) {
        if ((Get-FileTransferAuthoritySchema -Line ([string]$grant.RawLine)) -lt 2) {
            continue
        }

        [object[]]$matchingSettlements = @($settledEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$grant.Sequence -and
            (Test-PostGrantExactMatch -Left $grant -Right $_)
        } | Sort-Object Sequence, LineNumber)
        $settlementBoundary = if ($matchingSettlements.Count -gt 0) {
            [int64]$matchingSettlements[0].Sequence
        }
        else {
            [int64]::MaxValue
        }

        foreach ($held in @($heldEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$grant.Sequence -and
            [int64]$_.Sequence -lt $settlementBoundary -and
            (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 -and
            (Test-PostGrantExactMatch -Left $grant -Right $_)
        } | Sort-Object Sequence, LineNumber)) {
            $rawCandidates.Add($held) | Out-Null
            $key = Get-PostGrantHoldKey -Event $grant
            if ($seen.ContainsKey($key)) {
                continue
            }
            $seen[$key] = $true

            $recovered = $false
            if ($held.EventName -eq 'runtime_unlock_retry_dispatch_held_by_active_negotiation') {
                $recovered = Test-PostGrantHoldRecovered `
                    -Grant $grant `
                    -AfterSequence ([int64]$held.Sequence)
            }

            $distinctRecords.Add([pscustomobject]@{
                Event = $held
                Recovered = $recovered
            }) | Out-Null
        }
    }

    [object[]]$distinct = @($distinctRecords.ToArray() | ForEach-Object { $_.Event })
    [object[]]$recovered = @($distinctRecords.ToArray() | Where-Object { $_.Recovered } | ForEach-Object { $_.Event })
    [object[]]$unresolved = @($distinctRecords.ToArray() | Where-Object { -not $_.Recovered } | ForEach-Object { $_.Event })
    $unresolvedGrantList = New-Object System.Collections.Generic.List[object]
    $acceptedDispositionSettlementList = New-Object System.Collections.Generic.List[object]
    foreach ($grant in @($EffectiveGrantEvents | Sort-Object Sequence, LineNumber)) {
        [object[]]$observed = @($dispatchObservedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$grant.Sequence -and
            (Test-PostGrantExactMatch -Left $grant -Right $_)
        })
        if ($observed.Count -gt 0) {
            continue
        }

        $disposed = $false
        foreach ($outcome in @(
                'DispatchObserved',
                'MissingDispatch',
                'AuthorityRejected',
                'StaleRejected',
                'TerminalRejected',
                'TransferTerminal')) {
            $acceptedDisposition = Get-PostGrantAcceptedSettlement `
                    -Grant $grant `
                    -AfterSequence ([int64]$grant.Sequence) `
                    -Outcome $outcome
            if ($null -ne $acceptedDisposition) {
                $acceptedDispositionSettlementList.Add($acceptedDisposition.Settlement) | Out-Null
                $disposed = $true
                break
            }
        }
        if ($disposed) {
            continue
        }

        $acceptedSuccessor = Get-PostGrantAcceptedActiveSuccessor `
            -Grant $grant `
            -AfterSequence ([int64]$grant.Sequence)
        if ($null -ne $acceptedSuccessor) {
            $acceptedDispositionSettlementList.Add($acceptedSuccessor.Settlement) | Out-Null
            continue
        }

        $unresolvedGrantList.Add($grant) | Out-Null
    }
    [object[]]$unresolvedGrants = @($unresolvedGrantList.ToArray())
    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = $distinct
        RecoveredCandidateEvents = $recovered
        UnresolvedCandidateEvents = $unresolved
        UnresolvedGrantEvents = $unresolvedGrants
        AcceptedDispositionSettlementEvents = @($acceptedDispositionSettlementList.ToArray())
    }
}

function Get-FileTransferRuntimeUnlockPreCommitProbeStartHandoffCorrelation {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$launchRequests = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_precommit_probe_launch_requested' -and
        (Get-FileTransferEventField -Event $_ -Name 'duplicate' -Default '0') -eq '0' -and
        (Get-FileTransferEventField -Event $_ -Name 'responder_waiting_for_peer_probe' -Default '0') -eq '0'
    })
    [object[]]$timeouts = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_precommit_probe_start_timeout' -and
        (Get-FileTransferEventField -Event $_ -Name 'reason' -Default (
            Get-FileTransferEventField -Event $_ -Name 'failure_reason' -Default '')) -eq
            'runtime_unlock_probe_start_timeout'
    })
    [object[]]$startedEvents = @($orderedEvents | Where-Object {
        $_.EventName -in @(
            'runtime_unlock_precommit_probe_started',
            'runtime_unlock_precommit_probe_launch_started')
    })
    [object[]]$dispositionEvents = @($orderedEvents | Where-Object {
        ($_.EventName -eq 'filetransfer_runtime_unlock_precommit_probe_launch_handoff_decided' -and
            (Get-FileTransferEventField -Event $_ -Name 'status' -Default (
                Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '')) -in
                @('Accepted', 'Idempotent', 'Held', 'Rejected', 'Invalidated')) -or
        $_.EventName -in @(
            'runtime_unlock_precommit_probe_launch_held_by_coordinator_denial',
            'runtime_unlock_precommit_probe_start_timeout_suppressed_by_coordinator_denial',
            'filetransfer_runtime_unlock_precommit_probe_pending_held',
            'filetransfer_runtime_unlock_precommit_probe_pending_rejected')
    })

    function Get-ProbeField {
        param($Event, [string[]]$Names)
        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
                return $value
            }
        }
        return ''
    }

    function Test-ProbeCoreMatch {
        param($Launch, $Candidate)
        foreach ($aliases in @(
                @('session_id'),
                @('transaction_generation'),
                @('offer_generation'))) {
            $left = Get-ProbeField -Event $Launch -Names $aliases
            $right = Get-ProbeField -Event $Candidate -Names $aliases
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        foreach ($aliases in @(
                @('direction'),
                @('transfer_id'),
                @('tuna_path_lease_generation', 'path_lease_generation'),
                @('launch_generation'))) {
            $left = Get-ProbeField -Event $Launch -Names $aliases
            $right = Get-ProbeField -Event $Candidate -Names $aliases
            if (-not [string]::IsNullOrWhiteSpace($right) -and
                ([string]::IsNullOrWhiteSpace($left) -or
                    -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase))) {
                return $false
            }
        }
        return $true
    }

    function Test-ProbeExactMatch {
        param($Launch, $Candidate)
        if (-not (Test-ProbeCoreMatch -Launch $Launch -Candidate $Candidate)) {
            return $false
        }
        foreach ($aliases in @(
                @('transfer_id'),
                @('tuna_path_lease_generation', 'path_lease_generation'),
                @('launch_generation'))) {
            $left = Get-ProbeField -Event $Launch -Names $aliases
            $right = Get-ProbeField -Event $Candidate -Names $aliases
            if ([string]::IsNullOrWhiteSpace($left) -or
                [string]::IsNullOrWhiteSpace($right) -or
                -not [string]::Equals($left, $right, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }
        return $true
    }

    function Test-ProbeCandidateHasExactTuple {
        param($Event)
        return -not [string]::IsNullOrWhiteSpace((Get-ProbeField -Event $Event -Names @('transfer_id'))) -and
            -not [string]::IsNullOrWhiteSpace((Get-ProbeField -Event $Event -Names @('tuna_path_lease_generation', 'path_lease_generation'))) -and
            -not [string]::IsNullOrWhiteSpace((Get-ProbeField -Event $Event -Names @('launch_generation')))
    }

    function Get-ProbeKey {
        param($Launch)
        return (@(
            (Get-ProbeField -Event $Launch -Names @('session_id')),
            (Get-ProbeField -Event $Launch -Names @('direction')),
            (Get-ProbeField -Event $Launch -Names @('transfer_id')),
            (Get-ProbeField -Event $Launch -Names @('transaction_generation')),
            (Get-ProbeField -Event $Launch -Names @('offer_generation')),
            (Get-ProbeField -Event $Launch -Names @('tuna_path_lease_generation', 'path_lease_generation')),
            (Get-ProbeField -Event $Launch -Names @('launch_generation'))
        )) -join '|'
    }

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $distinctRecords = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $matchedLaunchSequences = New-Object System.Collections.Generic.HashSet[long]
    foreach ($timeout in $timeouts) {
        [object[]]$possible = @($launchRequests | Where-Object {
            [int64]$_.Sequence -lt [int64]$timeout.Sequence -and
            (Test-ProbeCoreMatch -Launch $_ -Candidate $timeout)
        } | Sort-Object Sequence, LineNumber -Descending)
        if (Test-ProbeCandidateHasExactTuple -Event $timeout) {
            $possible = @($possible | Where-Object {
                Test-ProbeExactMatch -Launch $_ -Candidate $timeout
            })
        }
        else {
            $possible = @($possible | Where-Object {
                -not $matchedLaunchSequences.Contains([int64]$_.Sequence)
            })
            if ($possible.Count -ne 1) {
                continue
            }
        }
        if ($possible.Count -ne 1) {
            continue
        }

        $launch = $possible[0]
        $matchedLaunchSequences.Add([int64]$launch.Sequence) | Out-Null
        $rawCandidates.Add($timeout) | Out-Null
        $key = Get-ProbeKey -Launch $launch
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true

        [object[]]$resolutions = @($startedEvents + $dispositionEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$launch.Sequence -and
            [int64]$_.Sequence -lt [int64]$timeout.Sequence -and
            $(if (Test-ProbeCandidateHasExactTuple -Event $_) {
                Test-ProbeExactMatch -Launch $launch -Candidate $_
            }
            else {
                Test-ProbeCoreMatch -Launch $launch -Candidate $_
            })
        })
        $distinctRecords.Add([pscustomobject]@{
            Event = $timeout
            Recovered = $resolutions.Count -gt 0
        }) | Out-Null
    }

    [object[]]$distinct = @($distinctRecords.ToArray() | ForEach-Object { $_.Event })
    [object[]]$recovered = @($distinctRecords.ToArray() | Where-Object { $_.Recovered } | ForEach-Object { $_.Event })
    [object[]]$unresolved = @($distinctRecords.ToArray() | Where-Object { -not $_.Recovered } | ForEach-Object { $_.Event })
    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recovered.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = $distinct
        RecoveredCandidateEvents = $recovered
        UnresolvedCandidateEvents = $unresolved
    }
}

function Get-FileTransferRuntimeUnlockResponderPeerProbeHandoffCorrelation {
    param([AllowEmptyCollection()][object[]]$Events = @())

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)

    function Get-ResponderProbeField {
        param($Event, [string[]]$Names)
        foreach ($name in $Names) {
            $value = Get-FileTransferEventField -Event $Event -Name $name -Default ''
            if (-not [string]::IsNullOrWhiteSpace($value) -and $value -notin @('(none)', 'none')) {
                return $value
            }
        }
        return ''
    }

    function Test-ResponderProbeFieldEqual {
        param($Left, $Right, [string[]]$Names, [switch]$OptionalRight)
        $leftValue = Get-ResponderProbeField -Event $Left -Names $Names
        $rightValue = Get-ResponderProbeField -Event $Right -Names $Names
        if ($OptionalRight -and
            ([string]::IsNullOrWhiteSpace($leftValue) -or [string]::IsNullOrWhiteSpace($rightValue))) {
            return $true
        }
        return -not [string]::IsNullOrWhiteSpace($leftValue) -and
            -not [string]::IsNullOrWhiteSpace($rightValue) -and
            [string]::Equals($leftValue, $rightValue, [System.StringComparison]::OrdinalIgnoreCase)
    }

    function Test-ResponderLocalTupleMatch {
        param($Boundary, $Candidate)
        foreach ($names in @(
                @('log_writer_id'),
                @('session_id'),
                @('transaction_generation'),
                @('offer_generation'))) {
            if (-not (Test-ResponderProbeFieldEqual -Left $Boundary -Right $Candidate -Names $names)) {
                return $false
            }
        }
        foreach ($names in @(
                @('transfer_id'),
                @('tuna_path_lease_generation', 'path_lease_generation'),
                @('tuna_path_lease_listener_run_id', 'path_lease_listener_run_id'))) {
            if (-not (Test-ResponderProbeFieldEqual -Left $Boundary -Right $Candidate -Names $names -OptionalRight)) {
                return $false
            }
        }
        return $true
    }

    function Test-ResponderProbeIdentityMatch {
        param($PathProbe, $Candidate)
        foreach ($names in @(
                @('log_writer_id'),
                @('session_id'),
                @('probe_id', 'path_probe_id'),
                @('tuna_path_lease_generation', 'path_lease_generation'))) {
            if (-not (Test-ResponderProbeFieldEqual -Left $PathProbe -Right $Candidate -Names $names)) {
                return $false
            }
        }
        foreach ($names in @(@('transfer_id'), @('direction'))) {
            if (-not (Test-ResponderProbeFieldEqual -Left $PathProbe -Right $Candidate -Names $names -OptionalRight)) {
                return $false
            }
        }
        return $true
    }

    [object[]]$pendingBoundaries = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_runtime_unlock_handoff_pending_route_commit' -and
        (Get-FileTransferEventField -Event $_ -Name 'state' -Default '') -ieq 'routecommitpending' -and
        (Get-FileTransferEventField -Event $_ -Name 'path_probe_state' -Default '') -ieq 'acked' -and
        (Get-FileTransferEventField -Event $_ -Name 'route_commit_pending' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'route_committed' -Default '0') -eq '0'
    })
    [object[]]$transactionAnswers = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_transaction_answer_received' -and
        (Get-FileTransferEventField -Event $_ -Name 'answer_received' -Default '0') -eq '1' -and
        (Get-FileTransferEventField -Event $_ -Name 'tuna_path_lease_current' -Default '0') -eq '1'
    })
    [object[]]$pathProbeAcks = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_transaction_path_probe_acked' -and
        (Get-FileTransferEventField -Event $_ -Name 'path_probe_state' -Default '') -ieq 'acked' -and
        (Get-FileTransferEventField -Event $_ -Name 'path_probe_transport' -Default '') -ieq 'tuna' -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'path_probe_acked_utc_ms' -Default '0') -gt 0
    })
    [object[]]$coreProbeAcks = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_precommit_probe_acked' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -ieq 'inbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'probe_state' -Default '') -ieq 'acked' -and
        (Get-FileTransferEventField -Event $_ -Name 'received_transport' -Default '') -ieq 'tuna' -and
        (Get-FileTransferEventField -Event $_ -Name 'launch_generation' -Default '0') -eq '0'
    })
    [object[]]$pendingAnswerAcks = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_ack_pending'
    })
    [object[]]$acceptedAnswerAcks = @($orderedEvents | Where-Object {
        $_.EventName -eq 'tuna_acceleration_answer_ack_received'
    })
    [object[]]$answerAckBarriers = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_answer_ack_probe_barrier_received'
    })
    [object[]]$launches = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_precommit_probe_launch_requested' -and
        [int64](Get-FileTransferEventField -Event $_ -Name 'launch_generation' -Default '0') -gt 0 -and
        (Get-FileTransferEventField -Event $_ -Name 'tuple_mutation' -Default '0') -eq '0' -and
        ((Get-FileTransferEventField -Event $_ -Name 'launch_role' -Default '') -like 'Responder*' -or
            (Get-FileTransferEventField -Event $_ -Name 'peer_probe_adoption' -Default '0') -eq '1')
    })
    [object[]]$boundLaunches = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_precommit_responder_peer_probe_handoff_bound' -and
        (Get-FileTransferEventField -Event $_ -Name 'status' -Default '') -in @('Accepted', 'Idempotent')
    })
    [object[]]$prepared = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_route_transition_prepared' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -ieq 'inbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'transition_kind' -Default '') -eq 'RegularV4ToTunaV4'
    })
    [object[]]$draining = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_route_transition_draining' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -ieq 'inbound'
    })
    [object[]]$committed = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_route_transition_committed' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -ieq 'inbound'
    })
    [object[]]$dispositions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'filetransfer_route_transition_disposition_applied' -and
        (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -ieq 'inbound' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default (
            Get-FileTransferEventField -Event $_ -Name 'apply_status' -Default '')) -in @('Applied', 'applied', 'Idempotent', 'idempotent')
    })

    $rawCandidates = New-Object System.Collections.Generic.List[object]
    $records = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($boundary in $pendingBoundaries) {
        [object[]]$localAnswers = @($transactionAnswers | Where-Object {
            [int64]$_.Sequence -lt [int64]$boundary.Sequence -and
            (Test-ResponderLocalTupleMatch -Boundary $boundary -Candidate $_)
        } | Sort-Object Sequence, LineNumber -Descending)
        [object[]]$localAcks = @($pathProbeAcks | Where-Object {
            [int64]$_.Sequence -lt [int64]$boundary.Sequence -and
            (Test-ResponderLocalTupleMatch -Boundary $boundary -Candidate $_)
        } | Sort-Object Sequence, LineNumber -Descending)
        if ($localAnswers.Count -eq 0 -or $localAcks.Count -eq 0) {
            continue
        }
        $pathProbeAck = $localAcks[0]
        [object[]]$matchingCoreAcks = @($coreProbeAcks | Where-Object {
            [int64]$_.Sequence -le [int64]$boundary.Sequence -and
            (Test-ResponderProbeIdentityMatch -PathProbe $pathProbeAck -Candidate $_)
        })
        if ($matchingCoreAcks.Count -eq 0) {
            continue
        }

        $writer = Get-ResponderProbeField -Event $boundary -Names @('log_writer_id')
        $sessionId = Get-ResponderProbeField -Event $boundary -Names @('session_id')
        $offerGeneration = Get-ResponderProbeField -Event $boundary -Names @('offer_generation')
        [object[]]$pending = @($pendingAnswerAcks | Where-Object {
            [int64]$_.Sequence -lt [int64]$boundary.Sequence -and
            (Get-ResponderProbeField -Event $_ -Names @('log_writer_id')) -eq $writer -and
            (Get-ResponderProbeField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-ResponderProbeField -Event $_ -Names @('generation', 'offer_generation')) -eq $offerGeneration
        } | Sort-Object Sequence, LineNumber -Descending)
        if ($pending.Count -eq 0) {
            continue
        }
        $payer = Get-ResponderProbeField -Event $pending[0] -Names @('payer_decision_id')
        [object[]]$accepted = @($acceptedAnswerAcks | Where-Object {
            [int64]$_.Sequence -gt [int64]$pathProbeAck.Sequence -and
            [int64]$_.Sequence -lt [int64]$boundary.Sequence -and
            (Get-ResponderProbeField -Event $_ -Names @('log_writer_id')) -eq $writer -and
            (Get-ResponderProbeField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-ResponderProbeField -Event $_ -Names @('payer_decision_id')) -eq $payer
        })
        [object[]]$barriers = @($answerAckBarriers | Where-Object {
            [int64]$_.Sequence -gt [int64]$pathProbeAck.Sequence -and
            [int64]$_.Sequence -lt [int64]$boundary.Sequence -and
            (Get-ResponderProbeField -Event $_ -Names @('log_writer_id')) -eq $writer -and
            (Get-ResponderProbeField -Event $_ -Names @('session_id')) -eq $sessionId -and
            (Get-ResponderProbeField -Event $_ -Names @('payer_decision_id')) -eq $payer
        })
        if ($accepted.Count -eq 0 -or $barriers.Count -eq 0) {
            continue
        }

        $rawCandidates.Add($boundary) | Out-Null
        $key = (@(
            $writer,
            $sessionId,
            (Get-ResponderProbeField -Event $boundary -Names @('transaction_generation')),
            $offerGeneration,
            (Get-ResponderProbeField -Event $pathProbeAck -Names @('tuna_path_lease_generation', 'path_lease_generation')),
            (Get-ResponderProbeField -Event $pathProbeAck -Names @('probe_id', 'path_probe_id'))
        )) -join '|'
        if ($seen.ContainsKey($key)) {
            continue
        }
        $seen[$key] = $true

        [object[]]$matchingLaunches = @($launches + $boundLaunches | Where-Object {
            [int64]$_.Sequence -gt [int64]$boundary.Sequence -and
            (Test-ResponderLocalTupleMatch -Boundary $boundary -Candidate $_) -and
            (Test-ResponderProbeIdentityMatch -PathProbe $pathProbeAck -Candidate $_)
        } | Sort-Object Sequence, LineNumber)
        $recovered = $false
        foreach ($launch in $matchingLaunches) {
            $launchGeneration = Get-ResponderProbeField -Event $launch -Names @('launch_generation')
            [object[]]$matchingPrepared = @($prepared | Where-Object {
                [int64]$_.Sequence -gt [int64]$launch.Sequence -and
                (Get-ResponderProbeField -Event $_ -Names @('log_writer_id')) -eq $writer -and
                (Get-ResponderProbeField -Event $_ -Names @('session_id')) -eq $sessionId -and
                (Get-ResponderProbeField -Event $_ -Names @('transaction_generation')) -eq
                    (Get-ResponderProbeField -Event $boundary -Names @('transaction_generation')) -and
                (Get-ResponderProbeField -Event $_ -Names @('offer_generation')) -eq $offerGeneration -and
                (Get-ResponderProbeField -Event $_ -Names @('launch_generation')) -eq $launchGeneration
            } | Sort-Object Sequence, LineNumber)
            foreach ($prepare in $matchingPrepared) {
                $authority = Get-ResponderProbeField -Event $prepare -Names @('authority_id')
                $transitionGeneration = Get-ResponderProbeField -Event $prepare -Names @('transition_generation')
                $hasDrain = @($draining | Where-Object {
                    [int64]$_.Sequence -gt [int64]$prepare.Sequence -and
                    (Get-ResponderProbeField -Event $_ -Names @('authority_id')) -eq $authority -and
                    (Get-ResponderProbeField -Event $_ -Names @('transition_generation')) -eq $transitionGeneration
                }).Count -gt 0
                $matchingCommit = @($committed | Where-Object {
                    [int64]$_.Sequence -gt [int64]$prepare.Sequence -and
                    (Get-ResponderProbeField -Event $_ -Names @('authority_id')) -eq $authority -and
                    (Get-ResponderProbeField -Event $_ -Names @('transition_generation')) -eq $transitionGeneration
                } | Select-Object -First 1)
                $hasDisposition = $matchingCommit.Count -gt 0 -and @($dispositions | Where-Object {
                    [int64]$_.Sequence -gt [int64]$matchingCommit[0].Sequence -and
                    (Get-ResponderProbeField -Event $_ -Names @('authority_id')) -eq $authority -and
                    (Get-ResponderProbeField -Event $_ -Names @('transition_generation')) -eq $transitionGeneration
                }).Count -gt 0
                if ($hasDrain -and $matchingCommit.Count -gt 0 -and $hasDisposition) {
                    $recovered = $true
                    break
                }
            }
            if ($recovered) { break }
        }
        $records.Add([pscustomobject]@{ Event = $boundary; Recovered = $recovered }) | Out-Null
    }

    [object[]]$distinct = @($records.ToArray() | ForEach-Object { $_.Event })
    [object[]]$recoveredEvents = @($records.ToArray() | Where-Object { $_.Recovered } | ForEach-Object { $_.Event })
    [object[]]$unresolved = @($records.ToArray() | Where-Object { -not $_.Recovered } | ForEach-Object { $_.Event })
    return [pscustomobject]@{
        RawCount = $rawCandidates.Count
        DistinctCount = $distinct.Count
        RecoveredCount = $recoveredEvents.Count
        UnresolvedCount = $unresolved.Count
        Verdict = if ($unresolved.Count -gt 0) { 'fail' } elseif ($distinct.Count -gt 0) { 'pass' } else { 'none' }
        RawCandidateEvents = @($rawCandidates.ToArray())
        DistinctCandidateEvents = $distinct
        RecoveredCandidateEvents = $recoveredEvents
        UnresolvedCandidateEvents = $unresolved
    }
}

function Get-FileTransferRuntimeUnlockRetryDispatchAuthorityTupleMismatchCorrelation {
    param(
        [AllowEmptyCollection()][object[]]$Events = @(),
        [AllowEmptyCollection()][object[]]$EffectiveGrantEvents = @(),
        [AllowEmptyCollection()][object[]]$AdditionalDiagnosticEvents = @()
    )

    [object[]]$orderedEvents = @($Events | Where-Object { $null -ne $_ } | Sort-Object Sequence, LineNumber)
    [object[]]$decisionTupleRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_decision_tuple_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'runtime_unlock_retry_dispatch_authority_tuple_mismatch'
    })
    [object[]]$currentAuthorityRejections = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_current_authority_rejected' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
            'runtime_unlock_retry_dispatch_authority_tuple_mismatch'
    })
    [object[]]$dispatchObservedSettlements = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_contract_settled' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'DispatchObserved' -and
        (Get-FileTransferEventField -Event $_ -Name 'dispatch_observed' -Default '') -eq '1'
    })
    [object[]]$dispatchObservedReports = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_reported' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'DispatchObserved' -and
        -not [string]::IsNullOrWhiteSpace(
            (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default ''))
    })
    [object[]]$acceptedSettlementDecisions = @($orderedEvents | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_settlement_decided' -and
        (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'DispatchObserved' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent')
    })
    [int64[]]$additionalDiagnosticSequences = @(
        $AdditionalDiagnosticEvents |
            Where-Object { $null -ne $_ } |
            ForEach-Object { [int64]$_.Sequence }
    )

    $recoveredCurrentAuthorityRejections = New-Object System.Collections.Generic.List[object]
    $unresolvedCurrentAuthorityRejections = New-Object System.Collections.Generic.List[object]
    foreach ($rejection in $currentAuthorityRejections) {
        if ([int64]$rejection.Sequence -in $additionalDiagnosticSequences) {
            $recoveredCurrentAuthorityRejections.Add($rejection) | Out-Null
            continue
        }

        [object[]]$matchingGrants = @($EffectiveGrantEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
            (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
        } | Sort-Object Sequence, LineNumber -Descending)
        $finalSettlementAccepted = $false
        foreach ($grant in $matchingGrants) {
            [object[]]$matchingSettlements = @($dispatchObservedSettlements | Where-Object {
                [int64]$_.Sequence -gt [int64]$grant.Sequence -and
                [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
            } | Sort-Object Sequence, LineNumber)
            foreach ($settlement in $matchingSettlements) {
                $settlementReason = Get-FileTransferEventField -Event $settlement -Name 'decision_reason' -Default ''
                [object[]]$matchingReports = @($dispatchObservedReports | Where-Object {
                    [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
                    [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                    (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq $settlementReason -and
                    (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
                } | Sort-Object Sequence, LineNumber)
                foreach ($report in $matchingReports) {
                    $reportReason = Get-FileTransferEventField -Event $report -Name 'settlement_reason' -Default ''
                    $matchingDecision = @($acceptedSettlementDecisions | Where-Object {
                        [int64]$_.Sequence -gt [int64]$report.Sequence -and
                        [int64]$_.Sequence -lt [int64]$rejection.Sequence -and
                        (Get-FileTransferEventField -Event $_ -Name 'settlement_reason' -Default '') -eq $reportReason -and
                        (Test-FileTransferRuntimeUnlockRetryDispatchCompleteAuthorityTupleMatch -Left $_ -Right $rejection)
                    } | Select-Object -First 1)
                    if ($matchingDecision.Count -gt 0) {
                        $finalSettlementAccepted = $true
                        break
                    }
                }
                if ($finalSettlementAccepted) {
                    break
                }
            }
            if ($finalSettlementAccepted) {
                break
            }
        }

        if ($finalSettlementAccepted) {
            # The authority was installed, dispatched, and terminally accepted.
            # A later current-binding check is stale diagnostic evidence, not a
            # failure of the already completed authority tuple.
            $recoveredCurrentAuthorityRejections.Add($rejection) | Out-Null
        }
        else {
            $unresolvedCurrentAuthorityRejections.Add($rejection) | Out-Null
        }
    }

    [object[]]$unresolved = @($decisionTupleRejections + $unresolvedCurrentAuthorityRejections.ToArray())
    return [pscustomobject]@{
        RawCount = $decisionTupleRejections.Count + $currentAuthorityRejections.Count
        RecoveredCount = $recoveredCurrentAuthorityRejections.Count
        UnresolvedCount = $unresolved.Count
        RecoveredCandidateEvents = @($recoveredCurrentAuthorityRejections.ToArray())
        UnresolvedCandidateEvents = $unresolved
    }
}

function Get-FileTransferReceiveRecoveryFallbackCheckpointScopeHandoffCorrelation {
    param([object[]]$Events = @())

    [object[]]$ordered = @($Events | Where-Object { $null -ne $_ } |
            Sort-Object Sequence, LineNumber)
    [object[]]$invalidations = @($ordered | Where-Object {
            $_.EventName -eq 'filetransfer_receive_recovery_operation_invalidated' -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
            (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq 'runtime_scope_replaced' -and
            (Get-FileTransferEventField -Event $_ -Name 'checkpoint_request_id' -Default '(none)') -in @('', '(none)', 'none')
        })
    $records = New-Object System.Collections.Generic.List[object]
    $heldDeliveryRetiredRecords = New-Object System.Collections.Generic.List[object]
    $keys = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($invalidation in $invalidations) {
        $sequence = [int64]$invalidation.Sequence
        $writer = Get-FileTransferEventField -Event $invalidation -Name 'log_writer_id' -Default ''
        $session = Get-FileTransferEventField -Event $invalidation -Name 'session_id' -Default ''
        $transfer = Get-FileTransferEventField -Event $invalidation -Name 'transfer_id' -Default ''
        $authority = Get-FileTransferEventField -Event $invalidation -Name 'receive_recovery_operation_authority_id' -Default ''
        $generation = Get-FileTransferEventField -Event $invalidation -Name 'receive_recovery_operation_generation' -Default '0'
        if ([string]::IsNullOrWhiteSpace($writer) -or
            [string]::IsNullOrWhiteSpace($session) -or
            [string]::IsNullOrWhiteSpace($transfer) -or
            [string]::IsNullOrWhiteSpace($authority) -or
            [int64]$generation -le 0) {
            continue
        }
        $scopeMatch = {
            param($event)
            (Get-FileTransferEventField -Event $event -Name 'log_writer_id' -Default '') -eq $writer -and
            (Get-FileTransferEventField -Event $event -Name 'session_id' -Default '') -eq $session -and
            (Get-FileTransferEventField -Event $event -Name 'transfer_id' -Default '') -eq $transfer
        }
        [object[]]$started = @($ordered | Where-Object {
                [int64]$_.Sequence -lt $sequence -and
                $_.EventName -in @(
                    'filetransfer_receive_recovery_operation_issued',
                    'filetransfer_receive_recovery_execution_started',
                    'filetransfer_receive_recovery_operation_execution_start_decided') -and
                (& $scopeMatch $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'receive_recovery_operation_authority_id' -Default '') -eq $authority -and
                (Get-FileTransferEventField -Event $_ -Name 'receive_recovery_operation_generation' -Default '0') -eq $generation
            })
        [object[]]$holds = @($ordered | Where-Object {
                [int64]$_.Sequence -lt $sequence -and
                $_.EventName -eq 'runtime_unlock_initial_activation_receive_recovery_hold_decided' -and
                (& $scopeMatch $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'receive_recovery_operation_authority_id' -Default '') -eq $authority -and
                (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Held'
            })
        [object[]]$requests = @($ordered | Where-Object {
                [int64]$_.Sequence -lt $sequence -and
                $_.EventName -eq 'filetransfer_v6_regular_nkn_state_refresh_requested' -and
                (& $scopeMatch $_) -and
                -not [string]::IsNullOrWhiteSpace(
                    (Get-FileTransferEventField -Event $_ -Name 'request_id' -Default ''))
            } | Select-Object -Last 1)
        if ($started.Count -eq 0 -or $holds.Count -eq 0 -or $requests.Count -ne 1) {
            continue
        }
        $requestId = Get-FileTransferEventField -Event $requests[0] -Name 'request_id' -Default ''
        [object[]]$checkpoint = @($ordered | Where-Object {
                [int64]$_.Sequence -gt $sequence -and
                $_.EventName -in @(
                    'filetransfer_fallback_checkpoint_requested',
                    'filetransfer_clean_fallback_checkpoint_requested') -and
                (& $scopeMatch $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'checkpoint_request_id' -Default '') -eq $requestId
            } | Select-Object -First 1)
        [object[]]$lateWorker = @($ordered | Where-Object {
                [int64]$_.Sequence -gt $sequence -and
                $_.EventName -eq 'nkn_bridge_recovery_execution_completion_late' -and
                (& $scopeMatch $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'total_deadline_expired' -Default '1') -eq '0'
            } | Select-Object -First 1)
        [object[]]$lostTransaction = @($ordered | Where-Object {
                [int64]$_.Sequence -gt $sequence -and
                $_.EventName -eq 'runtime_unlock_transaction_failed' -and
                (Get-FileTransferEventField -Event $_ -Name 'log_writer_id' -Default '') -eq $writer -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $session -and
                (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'runtime_scope_replaced'
            } | Select-Object -First 1)
        if ($checkpoint.Count -eq 0 -or $lateWorker.Count -eq 0 -or
            $lostTransaction.Count -eq 0) {
            continue
        }

        $key = "$session|$transfer|outbound|$authority|$generation|$requestId".ToLowerInvariant()
        if ($keys.Add($key)) {
            $records.Add([pscustomobject]@{
                    Event = $invalidation
                    Reason = 'post_tuna_fallback_checkpoint_descendant_treated_as_runtime_scope_replacement'
                    DistinctKey = $key
                }) | Out-Null
        }
    }

    [object[]]$heldDeliveryRetirements = @($ordered | Where-Object {
            $_.EventName -eq 'filetransfer_receive_recovery_fallback_checkpoint_lifecycle_advanced' -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq 'outbound' -and
            (Get-FileTransferEventField -Event $_ -Name 'checkpoint_binding_state' -Default '') -eq 'retired' -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq 'tail_reconciliation_forced'
        })
    foreach ($retirement in $heldDeliveryRetirements) {
        $sequence = [int64]$retirement.Sequence
        $writer = Get-FileTransferEventField -Event $retirement -Name 'log_writer_id' -Default ''
        $session = Get-FileTransferEventField -Event $retirement -Name 'session_id' -Default ''
        $transfer = Get-FileTransferEventField -Event $retirement -Name 'transfer_id' -Default ''
        $generation = Get-FileTransferEventField -Event $retirement -Name 'recovery_operation_generation' -Default '0'
        $checkpointId = Get-FileTransferEventField -Event $retirement -Name 'effective_checkpoint_request_id' -Default ''
        $bindingGeneration = Get-FileTransferEventField -Event $retirement -Name 'checkpoint_binding_generation' -Default '0'
        $frameFingerprint = Get-FileTransferEventField -Event $retirement -Name 'frame_fingerprint' -Default ''
        $transportEpoch = Get-FileTransferEventField -Event $retirement -Name 'transport_epoch' -Default '0'
        if ([string]::IsNullOrWhiteSpace($writer) -or
            [string]::IsNullOrWhiteSpace($session) -or
            [string]::IsNullOrWhiteSpace($transfer) -or
            [int64]$generation -le 0 -or
            [string]::IsNullOrWhiteSpace($checkpointId) -or
            [int64]$bindingGeneration -le 0 -or
            [string]::IsNullOrWhiteSpace($frameFingerprint) -or
            [int64]$transportEpoch -le 0) {
            continue
        }

        $sameScope = {
            param($event)
            (Get-FileTransferEventField -Event $event -Name 'log_writer_id' -Default '') -eq $writer -and
            (Get-FileTransferEventField -Event $event -Name 'session_id' -Default '') -eq $session -and
            (Get-FileTransferEventField -Event $event -Name 'transfer_id' -Default '') -eq $transfer
        }
        $sameCheckpoint = {
            param($event)
            (& $sameScope $event) -and
            (Get-FileTransferEventField -Event $event -Name 'recovery_operation_generation' -Default '0') -eq $generation -and
            (Get-FileTransferEventField -Event $event -Name 'effective_checkpoint_request_id' -Default '') -eq $checkpointId -and
            (Get-FileTransferEventField -Event $event -Name 'checkpoint_binding_generation' -Default '0') -eq $bindingGeneration -and
            (Get-FileTransferEventField -Event $event -Name 'frame_fingerprint' -Default '') -eq $frameFingerprint
        }
        [object[]]$binding = @($ordered | Where-Object {
                [int64]$_.Sequence -lt $sequence -and
                $_.EventName -eq 'filetransfer_receive_recovery_fallback_checkpoint_bound' -and
                (& $sameCheckpoint $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'checkpoint_binding_state' -Default '') -eq 'pending' -and
                (Get-FileTransferEventField -Event $_ -Name 'transport_epoch' -Default '0') -eq $transportEpoch
            } | Select-Object -Last 1)
        [object[]]$held = @($ordered | Where-Object {
                [int64]$_.Sequence -lt $sequence -and
                $_.EventName -eq 'filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied' -and
                (& $sameCheckpoint $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'delivery_state' -Default '') -eq 'held' -and
                (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('accepted', 'idempotent')
            } | Select-Object -Last 1)
        if ($binding.Count -ne 1 -or $held.Count -ne 1) {
            continue
        }
        $deliveryGeneration = Get-FileTransferEventField -Event $held[0] -Name 'checkpoint_delivery_generation' -Default '0'
        if ([int64]$deliveryGeneration -le 0) {
            continue
        }

        $started = @($ordered | Where-Object {
                [int64]$_.Sequence -lt [int64]$binding[0].Sequence -and
                $_.EventName -in @(
                    'filetransfer_receive_recovery_operation_issued',
                    'filetransfer_receive_recovery_execution_started',
                    'filetransfer_receive_recovery_operation_execution_start_decided') -and
                (& $sameScope $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'receive_recovery_operation_generation' -Default '0') -eq $generation -and
                (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6'
            })
        if ($started.Count -eq 0) {
            continue
        }

        [object[]]$resumeOrDelivery = @($ordered | Where-Object {
                [int64]$_.Sequence -gt [int64]$held[0].Sequence -and
                [int64]$_.Sequence -lt $sequence -and
                $_.EventName -in @(
                    'filetransfer_receive_recovery_fallback_checkpoint_delivery_resumed',
                    'filetransfer_receive_recovery_fallback_checkpoint_delivery_receipt_applied') -and
                (& $sameCheckpoint $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'checkpoint_delivery_generation' -Default '0') -eq $deliveryGeneration -and
                ($_.EventName -eq 'filetransfer_receive_recovery_fallback_checkpoint_delivery_resumed' -or
                    (Get-FileTransferEventField -Event $_ -Name 'delivery_state' -Default '') -eq 'delivered')
            })
        if ($resumeOrDelivery.Count -gt 0) {
            continue
        }

        [object[]]$bindingInvalidation = @($ordered | Where-Object {
                [int64]$_.Sequence -gt $sequence -and
                $_.EventName -eq 'filetransfer_receive_recovery_fallback_checkpoint_invalidated' -and
                (& $sameCheckpoint $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq 'runtime_scope_replaced'
            } | Select-Object -First 1)
        [object[]]$operationInvalidation = @($ordered | Where-Object {
                [int64]$_.Sequence -gt $sequence -and
                $_.EventName -eq 'filetransfer_receive_recovery_operation_invalidated' -and
                (& $sameScope $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'receive_recovery_operation_generation' -Default '0') -eq $generation -and
                (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6' -and
                (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq 'runtime_scope_replaced'
            } | Select-Object -First 1)
        if ($bindingInvalidation.Count -ne 1 -or $operationInvalidation.Count -ne 1) {
            continue
        }

        $key = "$session|$transfer|outbound|$generation|$checkpointId|$bindingGeneration|$deliveryGeneration|$frameFingerprint|$transportEpoch".ToLowerInvariant()
        if ($keys.Add($key)) {
            $record = [pscustomobject]@{
                Event = $retirement
                Reason = 'held_receive_recovery_fallback_checkpoint_retired_before_exact_resume_boundary'
                Variant = 'held_delivery_retired_before_resume'
                DistinctKey = $key
            }
            $records.Add($record) | Out-Null
            $heldDeliveryRetiredRecords.Add($record) | Out-Null
        }
    }
    return [pscustomobject]@{
        RawCount = $records.Count
        DistinctCount = $records.Count
        RecoveredCount = 0
        UnresolvedCount = $records.Count
        HeldDeliveryRetiredRawCount = $heldDeliveryRetiredRecords.Count
        HeldDeliveryRetiredDistinctCount = $heldDeliveryRetiredRecords.Count
        HeldDeliveryRetiredRecoveredCount = 0
        HeldDeliveryRetiredUnresolvedCount = $heldDeliveryRetiredRecords.Count
        Verdict = if ($records.Count -gt 0) { 'fail' } else { 'pass' }
        CandidateRecords = @($records.ToArray())
        UnresolvedCandidateRecords = @($records.ToArray())
    }
}

function Get-FileTransferRecoveryFailureClassification {
    param(
        [Parameter(Mandatory = $true)]$Summary,
        [ValidateSet('None', 'SwitchOff', 'MultiToggle', 'RegularActivationCycle')]
        [string]$LiveRouteProofMode = 'None'
    )

    $cachePropertyName = '__FileTransferRecoveryFailureClassification_{0}' -f $LiveRouteProofMode
    if ($null -ne $Summary.PSObject.Properties[$cachePropertyName]) {
        return $Summary.PSObject.Properties[$cachePropertyName].Value
    }

    [object[]]$events = @()
    if ($null -ne $Summary.PSObject.Properties['AllEvents']) {
        $events = @($Summary.AllEvents)
    }

    if ($events.Count -eq 0) {
        $events = @($Summary.GlobalEvents + $Summary.TransferEvents)
    }

    [object[]]$allEvents = @($events)
    [object[]]$submissionBarrierRetirementEvents = @($allEvents | Where-Object {
        $_.EventName -in @(
            'filetransfer_outbound_physical_send_lease_retired',
            'filetransfer_route_transition_physical_send_lease_retired')
    })
    [object[]]$events = @($allEvents | Where-Object {
        $_.EventName -notin @(
            'filetransfer_tuna_data_path_peer_visible',
            'filetransfer_data_path_send_result',
            'filetransfer_route_transition_physical_send_lease_registered',
            'filetransfer_route_transition_physical_send_lease_retired',
            'tuna_accelerated_envelope_sent',
            'tuna_accelerated_file_frame_sent',
            'filetransfer_outbound_physical_send_lease_registered',
            'filetransfer_outbound_physical_send_lease_retired'
        )
    })

    $runtimeUnlockOfferNotObservedEvents = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_activation_offer_not_observed' -and
        (
            (Get-FileTransferEventField -Event $_ -Name 'trigger' -Default '') -eq 'runtime_unlock' -or
            (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -like '*runtime_unlock*' -or
            (Get-FileTransferEventField -Event $_ -Name 'retry_reason' -Default '') -like '*runtime_unlock*'
        )
    })
    $runtimeUnlockRetryScheduledEvents = @($events | Where-Object {
        $_.EventName -eq 'tuna_acceleration_runtime_unlock_retry_after_recovery_scheduled'
    })
    $runtimeUnlockRetryReleasedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_released_after_regular_v4_receive_recovery'
    })
    $runtimeUnlockRetryBlockedByRegularV4RecoveryEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_blocked_by_regular_v4_receive_recovery'
    })
    $runtimeUnlockRetryHeldByRegularV4RecoveryEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_dispatch_held_by_regular_v4_receive_recovery'
    })
    $runtimeUnlockRetryRejectedAfterRegularV4RecoveryEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_rejected_after_regular_v4_receive_recovery'
    })
    $runtimeUnlockRetryRegularV4RecoverySettlementMissingEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_retry_regular_v4_recovery_settlement_missing'
    })
    $runtimeUnlockRegularV4RecoverySettlementReportedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_settlement_reported'
    })
    $runtimeUnlockRegularV4RecoverySettlementDecidedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_settlement_decided'
    })
    $runtimeUnlockRegularV4RecoverySettlementAcceptedEvents = @($runtimeUnlockRegularV4RecoverySettlementDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'disposition' -Default '') -eq 'Consumed' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Accepted'
    })
    $runtimeUnlockRegularV4RecoverySettlementIdempotentEvents = @($runtimeUnlockRegularV4RecoverySettlementDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'disposition' -Default '') -eq 'Consumed' -and
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Idempotent'
    })
    $runtimeUnlockRegularV4RecoverySettlementRejectedEvents = @($runtimeUnlockRegularV4RecoverySettlementDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Rejected'
    })
    $runtimeUnlockRegularV4RecoveryLifecycleReportedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_reported'
    })
    $runtimeUnlockRegularV4RecoveryLifecycleDecidedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lifecycle_decided'
    })
    $runtimeUnlockRegularV4RecoveryLifecycleAcceptedEvents = @($runtimeUnlockRegularV4RecoveryLifecycleDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -in @('Accepted', 'Idempotent')
    })
    $runtimeUnlockRegularV4RecoveryLeaseClosureRetainedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_retained'
    })
    $runtimeUnlockRegularV4RecoveryLeaseClosureAdoptedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_adopted'
    })
    $runtimeUnlockRegularV4RecoveryLeaseClosureRejectedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_rejected'
    })
    $runtimeUnlockRegularV4RecoveryLeaseClosureConsumedEvents = @($events | Where-Object {
        $_.EventName -eq 'runtime_unlock_regular_v4_recovery_lease_closure_consumed'
    })
    $fileTransferReceiveRecoveryOperationProof =
        Get-FileTransferReceiveRecoveryOperationCorrelation -Events $events
    $fileTransferReceiveRecoveryCompletedUnprovenPayloadHoldProof =
        Get-FileTransferReceiveRecoveryCompletedUnprovenPayloadHoldCorrelation `
            -Events $events
    $fileTransferReceiveRecoveryCompletedRetainedProofStatePublicationProof =
        Get-FileTransferReceiveRecoveryCompletedRetainedProofStatePublicationCorrelation `
            -Events $events
    $fileTransferReceiveRecoveryCompletedRetainedProofStateRecheckHeartbeatSuppressionProof =
        Get-FileTransferReceiveRecoveryCompletedRetainedProofStateRecheckHeartbeatSuppressionCorrelation `
            -Events $events
    $fileTransferReceiveRecoveryCompletedUnprovenSuccessorProof =
        Get-FileTransferReceiveRecoveryCompletedUnprovenSuccessorCorrelation `
            -Events $events
    $fileTransferReceiveRecoveryCompletedProvenSuccessorProof =
        Get-FileTransferReceiveRecoveryCompletedProvenSuccessorCorrelation `
            -Events $events
    $fileTransferReceiveRecoveryFallbackCheckpointScopeHandoffProof =
        Get-FileTransferReceiveRecoveryFallbackCheckpointScopeHandoffCorrelation `
            -Events $events
    $fileTransferReceiveRecoveryOperationPhase2EventNames = @(
        'runtime_unlock_retry_dispatch_decision_staged',
        'runtime_unlock_retry_dispatch_install_receipt_issued',
        'runtime_unlock_retry_dispatch_install_committed',
        'runtime_unlock_retry_dispatch_install_rejected',
        'runtime_unlock_retry_dispatch_authority_granted'
    )
    $fileTransferReceiveRecoveryOperationRetryAuthorityIds = @(
        $events |
            Where-Object {
                $_.EventName -in @(
                    'filetransfer_receive_recovery_operation_closure_reserved',
                    'filetransfer_receive_recovery_operation_closure_consumed') -and
                [int64](Get-FileTransferEventField `
                    -Event $_ `
                    -Name 'receive_recovery_operation_generation' `
                    -Default '0') -gt 0
            } |
            ForEach-Object {
                Get-FileTransferEventField `
                    -Event $_ `
                    -Name 'retry_authority_id' `
                    -Default '(none)'
            } |
            Where-Object { $_ -notin @('', '(none)', 'none') } |
            Select-Object -Unique
    )
    $fileTransferReceiveRecoveryOperationPhase2EvidenceSequences = @(
        $events |
            Where-Object {
                $_.EventName -in $fileTransferReceiveRecoveryOperationPhase2EventNames -and
                (
                    [int64](Get-FileTransferEventField `
                        -Event $_ `
                        -Name 'receive_recovery_operation_generation' `
                        -Default '0') -gt 0 -or
                    (Get-FileTransferEventField `
                        -Event $_ `
                        -Name 'authority_id' `
                        -Default '(none)') -in $fileTransferReceiveRecoveryOperationRetryAuthorityIds
                )
            } |
            ForEach-Object { [int64]$_.Sequence }
    )
    [object[]]$legacyRuntimeUnlockRegularV4RecoveryLeaseEvents =
        Remove-FileTransferLegacyReceiveRecoveryEventsCoveredByOperations `
            -Events $events `
            -OperationEvents $events
    $runtimeUnlockRetryDispatchInstallProof =
        Get-FileTransferRuntimeUnlockRetryDispatchInstallProof -Events $events
    $runtimeUnlockRetryLifecycleProof =
        Get-FileTransferRuntimeUnlockRetryLifecycleCorrelation -Events $events
    [object[]]$runtimeUnlockRetryDispatchEffectiveGrantEvents = @(
        $runtimeUnlockRetryDispatchInstallProof.EffectiveGrantEvents
    )
    $runtimeUnlockRetryDispatchPostGrantHoldProof =
        Get-FileTransferRuntimeUnlockRetryDispatchPostGrantHoldCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $runtimeUnlockPreCommitProbeStartHandoffProof =
        Get-FileTransferRuntimeUnlockPreCommitProbeStartHandoffCorrelation -Events $events
    $runtimeUnlockResponderPeerProbeHandoffProof =
        Get-FileTransferRuntimeUnlockResponderPeerProbeHandoffCorrelation -Events $events
    $runtimeUnlockRegularV4RecoveryLeaseIssuanceProof =
        Get-FileTransferRuntimeUnlockRegularV4RecoveryLeaseCorrelation `
            -Events $legacyRuntimeUnlockRegularV4RecoveryLeaseEvents `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $bridgeRecoveryExecutionSoftToHardHandoffProof =
        Get-FileTransferBridgeRecoveryExecutionSoftToHardHandoffCorrelation -Events $events
    $bridgeRecoveryExecutionStartupPayloadIsolationProof =
        Get-FileTransferBridgeRecoveryExecutionStartupPayloadIsolationCorrelation -Events $events
    $bridgeRecoveryExecutionPayloadHoldProof =
        Get-FileTransferBridgeRecoveryExecutionPayloadHoldCorrelation -Events $events
    $bridgeRecoveryExecutionSubmissionBarrierDrainIndex =
        New-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainIndex `
            -SemanticEvents $events `
            -RetirementEvents $submissionBarrierRetirementEvents
    $bridgeRecoveryExecutionSubmissionBarrierDrainProof =
        Get-FileTransferBridgeRecoveryExecutionSubmissionBarrierDrainCorrelation `
            -Index $bridgeRecoveryExecutionSubmissionBarrierDrainIndex
    $runtimeUnlockRegularV4RecoveryClosureOfferTimeoutHandoffProof =
        Get-FileTransferRuntimeUnlockRegularV4RecoveryClosureOfferTimeoutCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $runtimeUnlockInitialOfferRetryLifecycleHandoffProof =
        Get-FileTransferRuntimeUnlockInitialOfferRetryLifecycleHandoffCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $runtimeUnlockInitialActivationAnswerPeerDeliveryProof =
        Get-FileTransferRuntimeUnlockInitialActivationAnswerPeerDeliveryCorrelation `
            -Events $events
    $runtimeUnlockInitialOfferReceiveRecoveryHoldProof =
        Get-FileTransferRuntimeUnlockInitialOfferReceiveRecoveryHoldCorrelation `
            -Events $events
    $runtimeUnlockInitialActivationReceiveRecoveryHoldReleaseDeliveryProof =
        Get-FileTransferRuntimeUnlockInitialActivationReceiveRecoveryHoldReleaseDeliveryCorrelation `
            -Events $events
    $runtimeUnlockInitialActivationReceiveRecoveryHoldReleasedPathLeaseExpiredProof =
        Get-FileTransferRuntimeUnlockInitialActivationReceiveRecoveryHoldReleasedPathLeaseExpiredCorrelation `
            -Events $events
    $runtimeUnlockInitialActivationReceiveRecoveryHoldReleasedOfferExpiredProof =
        Get-FileTransferRuntimeUnlockInitialActivationReceiveRecoveryHoldReleasedOfferExpiredCorrelation `
            -Events $events
    $runtimeUnlockRetryDispatchAuthorityTupleMismatchProof =
        Get-FileTransferRuntimeUnlockRetryDispatchAuthorityTupleMismatchCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents `
            -AdditionalDiagnosticEvents $runtimeUnlockRegularV4RecoveryClosureOfferTimeoutHandoffProof.CorrelatedStaleAuthorityEvents
    $regularV4FrontierRepairSettlementDispositionProof =
        Get-FileTransferRegularV4FrontierRepairSettlementDispositionProof -Events $events
    $runtimeUnlockRegularV4RecoverySettlementProof =
        Get-FileTransferRuntimeUnlockRegularV4RecoverySettlementCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents `
            -ResolvedRepairSettlementEvents $regularV4FrontierRepairSettlementDispositionProof.ResolvedAcceptedEvents
    $runtimeUnlockPostTunaFallbackTransportProofHandoffProof =
        Get-FileTransferRuntimeUnlockPostTunaFallbackTransportProofHandoffCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $runtimeUnlockUncommittedTunaFallbackProofAuthorityProof =
        Get-FileTransferRuntimeUnlockUncommittedTunaFallbackProofAuthorityCorrelation `
            -Events $events
    $runtimeUnlockUncommittedTunaFallbackHandoffSuppressionProof =
        Get-FileTransferRuntimeUnlockUncommittedTunaFallbackHandoffSuppressionCorrelation `
            -Events $events
    $runtimeUnlockUncommittedTunaFallbackPrecommitAuthorityProof =
        Get-FileTransferRuntimeUnlockUncommittedTunaFallbackPrecommitAuthorityCorrelation `
            -Events $events
    $runtimeUnlockRetryFallbackTailUnblockRecheckProof =
        Get-FileTransferRuntimeUnlockRetryFallbackTailUnblockRecheckCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents `
            -Phase2ProtocolObserved $runtimeUnlockRetryDispatchInstallProof.ProtocolObserved
    $runtimeUnlockRetryZeroOfferSuccessorProof =
        Get-FileTransferRuntimeUnlockRetryZeroOfferSuccessorCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $runtimeUnlockRetryFallbackPairedYieldSuccessorReleaseProof =
        Get-FileTransferRuntimeUnlockRetryFallbackPairedYieldSuccessorReleaseCorrelation `
            -Events $events `
            -EffectiveGrantEvents $runtimeUnlockRetryDispatchEffectiveGrantEvents
    $regularV4FrontierRepairMissingRangePreservationProof =
        Get-FileTransferRegularV4MissingRangePreservationProof -Events $events
    $regularV4FrontierTailRepairStatePublicationProof =
        Get-FileTransferRegularV4FrontierTailRepairStatePublicationProof -Events $events
    $regularV4FrontierRepairProjectionReauthorizationProof =
        Get-FileTransferRegularV4RepairProjectionReauthorizationProof -Events $events
    $regularV4PeerSilenceReplayMissingDispatchRangeProof =
        Get-FileTransferRegularV4PeerSilenceReplayMissingDispatchRangeProof -Events $events
    $regularV4PeerSilenceReplayInstalledAuthorityDispatchProof =
        Get-FileTransferRegularV4PeerSilenceReplayInstalledAuthorityDispatchProof -Events $events
    $regularV4FrontierRepairLifecycleProof =
        Get-FileTransferRegularV4FrontierRepairLifecycleProof `
            -Events $events `
            -SettlementDispositionProof $regularV4FrontierRepairSettlementDispositionProof
    $regularV4FrontierRepairPressureAuthorityLifecycleSplitProof =
