            (Get-FileTransferEventField -Event $_ -Name 'receive_proof_observed' -Default '0') -eq '0') -or
        $_.EventName -in @('file_transfer_outbound_terminal', 'file_transfer_inbound_terminal', 'transfer_terminal')
    })
