    function Test-RuntimeUnlockRegularV4RecoveryLifecycleMatchesBlocked {
        param(
            [Parameter(Mandatory = $true)]$Blocked,
            [Parameter(Mandatory = $true)]$Lifecycle
        )

        foreach ($fieldName in @(
                'session_id',
                'transfer_id',
                'direction',
                'route',
                'protocol_version',
                'live_route_epoch',
                'regular_v4_liveness_generation',
                'bridge_decision_generation')) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $fieldName -Default ''
            $lifecycleValue = Get-FileTransferEventField -Event $Lifecycle -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($blockedValue) -or
                [string]::IsNullOrWhiteSpace($lifecycleValue) -or
                -not [string]::Equals($blockedValue, $lifecycleValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-RuntimeUnlockRegularV4RecoveryBoundaryMatch {
        param(
            [Parameter(Mandatory = $true)]$Blocked,
            [Parameter(Mandatory = $true)]$Boundary
        )

        $blockedSession = Get-FileTransferEventField -Event $Blocked -Name 'session_id' -Default ''
        $boundarySession = Get-FileTransferEventField -Event $Boundary -Name 'session_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($blockedSession) -or
            [string]::IsNullOrWhiteSpace($boundarySession) -or
            -not [string]::Equals($blockedSession, $boundarySession, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        foreach ($identityField in @('transfer_id', 'route', 'protocol_version', 'live_route_epoch')) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $identityField -Default ''
            $boundaryValue = Get-FileTransferEventField -Event $Boundary -Name $identityField -Default ''
            if (-not [string]::IsNullOrWhiteSpace($blockedValue) -and
                $blockedValue -notin @('(none)', 'none') -and
                -not [string]::IsNullOrWhiteSpace($boundaryValue) -and
                $boundaryValue -notin @('(none)', 'none') -and
                -not [string]::Equals($blockedValue, $boundaryValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        $blockedDirection = Get-FileTransferEventField -Event $Blocked -Name 'direction' -Default ''
        $boundaryDirection = Get-FileTransferEventField -Event $Boundary -Name 'direction' -Default ''
        if ([string]::IsNullOrWhiteSpace($boundaryDirection)) {
            if ($Boundary.EventName -eq 'file_transfer_outbound_terminal') {
                $boundaryDirection = 'outbound'
            }
            elseif ($Boundary.EventName -eq 'file_transfer_inbound_terminal') {
                $boundaryDirection = 'inbound'
            }
        }
        if (-not [string]::IsNullOrWhiteSpace($blockedDirection) -and
            -not [string]::IsNullOrWhiteSpace($boundaryDirection) -and
            -not [string]::Equals($blockedDirection, $boundaryDirection, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        return $true
    }

    function Test-RuntimeUnlockRegularV4RecoveryGrantMatch {
        param(
            [Parameter(Mandatory = $true)]$Blocked,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($requiredBlockedField in @(
                'session_id',
                'transfer_id',
                'route',
                'protocol_version',
                'live_route_epoch',
                'regular_v4_liveness_generation',
                'bridge_decision_generation')) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $requiredBlockedField -Default ''
            if ([string]::IsNullOrWhiteSpace($blockedValue) -or $blockedValue -in @('(none)', 'none')) {
                return $false
            }
        }

        foreach ($requiredCandidateField in @(
                'session_id',
                'transfer_id',
                'direction',
                'request_regular_v4_liveness_generation',
                'request_bridge_decision_generation',
                'decision_reason')) {
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $requiredCandidateField -Default ''
            if ([string]::IsNullOrWhiteSpace($candidateValue) -or $candidateValue -in @('(none)', 'none')) {
                return $false
            }
        }

        foreach ($identityField in @('session_id', 'transfer_id')) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $identityField -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $identityField -Default ''
            if (-not [string]::Equals($blockedValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        foreach ($generationPair in @(
                @('regular_v4_liveness_generation', 'request_regular_v4_liveness_generation'),
                @('bridge_decision_generation', 'request_bridge_decision_generation'))) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $generationPair[0] -Default ''
            $requestValue = Get-FileTransferEventField -Event $Candidate -Name $generationPair[1] -Default ''
            if ($requestValue -ne '0' -and $requestValue -ne $blockedValue) {
                return $false
            }
        }

        if ($Candidate.EventName -eq 'runtime_unlock_retry_dispatch_pending_request_rechecked') {
            foreach ($requiredRecheckField in @(
                    'release_authority_id',
                    'release_generation',
                    'release_outcome',
                    'granted_authority_id',
                    'granted_bridge_decision_generation',
                    'decision_status',
                    'trigger')) {
                $requiredValue = Get-FileTransferEventField -Event $Candidate -Name $requiredRecheckField -Default ''
                if ([string]::IsNullOrWhiteSpace($requiredValue) -or $requiredValue -in @('(none)', 'none')) {
                    return $false
                }
            }

            if ((Get-FileTransferEventField -Event $Candidate -Name 'decision_status' -Default '') -notin @('Granted', 'Accepted')) {
                return $false
            }

            return $true
        }

        if ($Candidate.EventName -ne 'runtime_unlock_retry_dispatch_authority_granted' -or
            (Get-FileTransferAuthoritySchema -Line ([string]$Candidate.RawLine)) -lt 2) {
            return $false
        }

        foreach ($requiredGrantField in @(
                'authority_id',
                'route',
                'protocol_version',
                'live_route_epoch',
                'contract_generation',
                'retired_generation',
                'release_kind',
                'release_authority_id',
                'release_generation',
                'release_outcome')) {
            $requiredValue = Get-FileTransferEventField -Event $Candidate -Name $requiredGrantField -Default ''
            if ([string]::IsNullOrWhiteSpace($requiredValue) -or $requiredValue -in @('(none)', 'none')) {
                return $false
            }
        }

        foreach ($tupleField in @('route', 'protocol_version', 'live_route_epoch')) {
            if (-not [string]::Equals(
                    (Get-FileTransferEventField -Event $Blocked -Name $tupleField -Default ''),
                    (Get-FileTransferEventField -Event $Candidate -Name $tupleField -Default ''),
                    [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        foreach ($optionalRetryField in @('contract_generation', 'retired_generation')) {
            $blockedValue = Get-FileTransferEventField -Event $Blocked -Name $optionalRetryField -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $optionalRetryField -Default ''
            if (-not [string]::IsNullOrWhiteSpace($blockedValue) -and $blockedValue -ne $candidateValue) {
                return $false
            }
        }

        return $true
    }

    # Use the shared full/compact correlation result as the semantic source of truth.
    $runtimeUnlockRetryRegularV4RecoverySettlementMissingCandidateEvents =
        New-Object System.Collections.Generic.List[object]
    foreach ($candidate in @($runtimeUnlockRegularV4RecoverySettlementProof.UnresolvedCandidateEvents)) {
        $runtimeUnlockRetryRegularV4RecoverySettlementMissingCandidateEvents.Add($candidate) | Out-Null
    }
    $runtimeUnlockRetryRegularV4SettlementHandoffBypassedCandidateEvents =
        New-Object System.Collections.Generic.List[object]
    foreach ($candidate in @($runtimeUnlockRegularV4RecoverySettlementProof.HandoffBypassCandidateEvents)) {
        $runtimeUnlockRetryRegularV4SettlementHandoffBypassedCandidateEvents.Add($candidate) | Out-Null
    }
    $runtimeUnlockRetryRegularV4RecoverySettlementMissingCount =
        $runtimeUnlockRegularV4RecoverySettlementProof.UnresolvedCount
    $runtimeUnlockRetryRegularV4SettlementHandoffBypassedCount =
        $runtimeUnlockRegularV4RecoverySettlementProof.HandoffBypassCount

    # The shared correlation helper anchors non-adoption on an immutable
    # retained receipt and is also used by the compact analyzer.
    $runtimeUnlockRecoveryLeaseClosureNotAdoptedRawEvents =
        @($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureNotAdoptedRawCandidateEvents)
    $runtimeUnlockRecoveryLeaseClosureNotAdoptedDistinctEvents =
        @($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureNotAdoptedDistinctCandidateEvents)
    $runtimeUnlockRecoveryLeaseClosureAdoptedRecoveryEvents =
        @($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureNotAdoptedRecoveredCandidateEvents)
    $runtimeUnlockRecoveryLeaseClosureNotAdoptedUnresolvedEvents =
        @($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureNotAdoptedUnresolvedCandidateEvents)
    $runtimeUnlockRecoveryLeaseClosureNotAdoptedRawCount =
        $runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureNotAdoptedRawCount
    $runtimeUnlockRecoveryLeaseClosureNotAdoptedDistinctCount =
        $runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureNotAdoptedDistinctCount
    $runtimeUnlockRecoveryLeaseClosureNotAdoptedRecoveredCount =
        $runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureNotAdoptedRecoveredCount
    $runtimeUnlockRecoveryLeaseClosureNotAdoptedUnresolvedCount =
        $runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureNotAdoptedUnresolvedCount
    $runtimeUnlockRecoveryLeaseClosureAdoptionVerdict =
        $runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureAdoptionVerdict

    # A failed Tuna path probe is a recoverable trigger. The proof-chain failure
    # begins only when Core has explicitly held the matching retry authority and
    # Infra later discards that exact hold as if no authority decision existed.
    $runtimeUnlockProbeRecoveryAuthorityLostRawEvents = New-Object System.Collections.Generic.List[object]
    foreach ($rejection in @($runtimeUnlockRetryDispatchAuthorityRejectedEvents | Where-Object {
                (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
                    'missing_runtime_unlock_retry_authority'
            } | Sort-Object Sequence)) {
        $rejectionSequence = [int64]$rejection.Sequence
        $sessionId = Get-FileTransferEventField -Event $rejection -Name 'session_id' -Default ''
        $transferId = Get-FileTransferEventField -Event $rejection -Name 'transfer_id' -Default ''
        $contractGeneration = Get-FileTransferEventField -Event $rejection -Name 'contract_generation' -Default ''
        $held = @($runtimeUnlockRetryDispatchAuthorityHeldEvents | Where-Object {
            [int64]$_.Sequence -lt $rejectionSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq
                'regular_v4_repair_settlement_pending' -and
            (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $sessionId -and
            (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq $transferId -and
            (Get-FileTransferEventField -Event $_ -Name 'contract_generation' -Default '') -eq $contractGeneration -and
            (Get-FileTransferEventField -Event $_ -Name 'retry_reason' -Default '') -eq
                'runtime_unlock_tuna_probe_sidecar_closed'
        } | Sort-Object Sequence | Select-Object -Last 1)
        if ($held.Count -eq 0) {
            continue
        }

        $heldSequence = [int64]$held[0].Sequence
        $trigger = @($runtimeUnlockTransactionPathProbeSidecarClosedEvents | Where-Object {
            [int64]$_.Sequence -lt $heldSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $sessionId
        } | Sort-Object Sequence | Select-Object -Last 1)
        if ($trigger.Count -eq 0) {
            continue
        }

        $runtimeUnlockProbeRecoveryAuthorityLostRawEvents.Add($rejection) | Out-Null
    }

    $runtimeUnlockProbeRecoveryAuthorityLostDistinctEvents = New-Object System.Collections.Generic.List[object]
    $runtimeUnlockProbeRecoveryAuthorityLostRecoveredEvents = New-Object System.Collections.Generic.List[object]
    $runtimeUnlockProbeRecoveryAuthorityLostUnresolvedEvents = New-Object System.Collections.Generic.List[object]
    $probeRecoveryAuthorityLostKeys = @{}
    foreach ($rejection in @($runtimeUnlockProbeRecoveryAuthorityLostRawEvents.ToArray() | Sort-Object Sequence)) {
        $key = (@(
                'session_id',
                'transfer_id',
                'contract_generation',
                'dispatch_attempt_generation',
                'missing_dispatch_successor_generation') |
                ForEach-Object { Get-FileTransferEventField -Event $rejection -Name $_ -Default '(missing)' }) -join '|'
        if ($probeRecoveryAuthorityLostKeys.ContainsKey($key)) {
            continue
        }

        $probeRecoveryAuthorityLostKeys[$key] = $true
        $runtimeUnlockProbeRecoveryAuthorityLostDistinctEvents.Add($rejection) | Out-Null
        $rejectionSequence = [int64]$rejection.Sequence
        $sessionId = Get-FileTransferEventField -Event $rejection -Name 'session_id' -Default ''
        $transferId = Get-FileTransferEventField -Event $rejection -Name 'transfer_id' -Default ''
        $acceptedHandoff = @(
            @($runtimeUnlockRegularV4RecoverySettlementAcceptedEvents +
                $runtimeUnlockRegularV4RecoverySettlementIdempotentEvents) | Where-Object {
                [int64]$_.Sequence -gt $rejectionSequence -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $sessionId -and
                (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq $transferId
            } | Sort-Object Sequence | Select-Object -First 1
        )
        $grant = @()
        $freshProof = @()
        if ($acceptedHandoff.Count -gt 0) {
            $acceptedSequence = [int64]$acceptedHandoff[0].Sequence
            $grant = @($runtimeUnlockRetryDispatchAuthorityGrantedEvents | Where-Object {
                [int64]$_.Sequence -gt $acceptedSequence -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $sessionId -and
                (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq $transferId
            } | Sort-Object Sequence | Select-Object -First 1)
            if ($grant.Count -gt 0) {
                $grantSequence = [int64]$grant[0].Sequence
                $freshProof = @(@(
                        $runtimeUnlockTransactionStartedEvents +
                        $runtimeUnlockProbeAckedEvents +
                        $runtimeUnlockPreCommitProbeAckedEvents +
                        $runtimeUnlockTunaProbeAckReceivedEvents +
                        $runtimeUnlockTransactionCommittedEvents) | Where-Object {
                        [int64]$_.Sequence -gt $grantSequence -and
                        (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $sessionId
                    } | Sort-Object Sequence | Select-Object -First 1)
            }
        }

        if ($acceptedHandoff.Count -gt 0 -and $grant.Count -gt 0 -and $freshProof.Count -gt 0) {
            $runtimeUnlockProbeRecoveryAuthorityLostRecoveredEvents.Add($rejection) | Out-Null
        }
        else {
            $runtimeUnlockProbeRecoveryAuthorityLostUnresolvedEvents.Add($rejection) | Out-Null
        }
    }
    $runtimeUnlockProbeRecoveryAuthorityVerdict = if (
        $runtimeUnlockProbeRecoveryAuthorityLostUnresolvedEvents.Count -gt 0) {
        'fail'
    }
    elseif ($runtimeUnlockProbeRecoveryAuthorityLostDistinctEvents.Count -gt 0) {
        'recovered'
    }
    elseif ($runtimeUnlockTransactionPathProbeSidecarClosedEvents.Count -gt 0) {
        'pass'
    }
    else {
        'none'
    }

    $runtimeUnlockRetryDispatchMissingAfterAuthorityGrantedCount = $runtimeUnlockRetryDispatchUnsettledMissingAfterAuthorityGrantedEvents.Count
    $runtimeUnlockRetryDispatchMissingCount = $runtimeUnlockRetryDispatchMissingAfterAuthorityGrantedCount
    $runtimeUnlockRetryDispatchReleaseCount = $runtimeUnlockRetryReleasedEvents.Count
    $runtimeUnlockRetryDispatchDuplicateObservedCount = (@(
        $runtimeUnlockRetryDispatchObservedEvents |
            Where-Object { (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 } |
            Group-Object { Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '(none)' } |
            Where-Object { $_.Name -ne '(none)' -and $_.Count -gt 1 } |
            ForEach-Object { $_.Count - 1 }
    ) | Measure-Object -Sum).Sum
    $runtimeUnlockRetryDispatchDuplicateSettlementCount = (@(
        $runtimeUnlockRetryDispatchContractSettledEvents |
            Where-Object { (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 } |
            Group-Object { Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '(none)' } |
            Where-Object { $_.Name -ne '(none)' -and $_.Count -gt 1 } |
            ForEach-Object { $_.Count - 1 }
    ) | Measure-Object -Sum).Sum
    if ($null -eq $runtimeUnlockRetryDispatchDuplicateObservedCount) {
        $runtimeUnlockRetryDispatchDuplicateObservedCount = 0
    }
    if ($null -eq $runtimeUnlockRetryDispatchDuplicateSettlementCount) {
        $runtimeUnlockRetryDispatchDuplicateSettlementCount = 0
    }
    $runtimeUnlockRetryDispatchDuplicateObservedCount = [int]$runtimeUnlockRetryDispatchDuplicateObservedCount
    $runtimeUnlockRetryDispatchDuplicateSettlementCount = [int]$runtimeUnlockRetryDispatchDuplicateSettlementCount
    $runtimeUnlockRetryDispatchSettlementAcceptedEvents = @($runtimeUnlockRetryDispatchSettlementDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Accepted'
    })
    $runtimeUnlockRetryDispatchSettlementIdempotentEvents = @($runtimeUnlockRetryDispatchSettlementDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Idempotent'
    })
    $runtimeUnlockRetryDispatchSettlementRejectedEvents = @($runtimeUnlockRetryDispatchSettlementDecidedEvents | Where-Object {
        (Get-FileTransferEventField -Event $_ -Name 'decision_status' -Default '') -eq 'Rejected'
    })
    $runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved =
        $runtimeUnlockRetryDispatchSettlementReportedEvents.Count -gt 0 -or
        $runtimeUnlockRetryDispatchSettlementDecidedEvents.Count -gt 0 -or
        $runtimeUnlockRetryDispatchChainClosedEvents.Count -gt 0
    $runtimeUnlockRetryDispatchSettlementAcceptanceMissingEvents = New-Object System.Collections.Generic.List[object]
    $runtimeUnlockRetryDispatchSettlementAcceptanceMissingSettlementSequences = New-Object System.Collections.Generic.List[int64]
    $runtimeUnlockRetryDispatchSettlementDisposedSequences = New-Object System.Collections.Generic.HashSet[int64]
    foreach ($settlement in $runtimeUnlockRetryDispatchContractSettledEvents) {
        if (-not $runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved -or
            (Get-FileTransferAuthoritySchema -Line ([string]$settlement.RawLine)) -lt 2) {
            continue
        }

        $matchingReports = @($runtimeUnlockRetryDispatchSettlementReportedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'subscriber_present' -Default '0') -eq '1' -and
            (Test-RuntimeUnlockRetryDispatchSettlementMatch -Settlement $settlement -Candidate $_)
        } | Sort-Object Sequence)
        $disposed = $false
        foreach ($report in $matchingReports) {
            $firstDecision = @($runtimeUnlockRetryDispatchSettlementDecidedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$report.Sequence -and
                (Test-RuntimeUnlockRetryDispatchSettlementMatch -Settlement $report -Candidate $_)
            } | Sort-Object Sequence | Select-Object -First 1)
            if ($firstDecision.Count -eq 0) {
                continue
            }

            $decisionStatus = Get-FileTransferEventField -Event $firstDecision[0] -Name 'decision_status' -Default ''
            if ($decisionStatus -eq 'Accepted') {
                $disposed = $true
                break
            }

            if ($decisionStatus -eq 'Idempotent') {
                $settlementOutcome = Get-FileTransferEventField -Event $settlement -Name 'settlement_outcome' -Default ''
                if ($settlementOutcome -ne 'Superseded') {
                    $disposed = $true
                    break
                }

                $predecessorAuthorityId = Get-FileTransferEventField -Event $settlement -Name 'authority_id' -Default '(none)'
                $successorAuthorityId = Get-FileTransferEventField -Event $settlement -Name 'successor_authority_id' -Default '(none)'
                $matchingSuccessor = @($runtimeUnlockRetryDispatchAuthorityGrantedEvents | Where-Object {
                    [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
                    (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 -and
                    (Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '(none)') -eq $predecessorAuthorityId -and
                    ($successorAuthorityId -in @('', '(none)', 'none') -or
                        (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '(none)') -eq $successorAuthorityId) -and
                    (Test-RuntimeUnlockRetryDispatchSuccessorHandoffMatch -Predecessor $settlement -Successor $_)
                })
                if ($matchingSuccessor.Count -eq 1) {
                    $disposed = $true
                    break
                }
            }
        }
        if ($disposed) {
            [void]$runtimeUnlockRetryDispatchSettlementDisposedSequences.Add([int64]$settlement.Sequence)
        }
        else {
            $runtimeUnlockRetryDispatchSettlementAcceptanceMissingSettlementSequences.Add([int64]$settlement.Sequence) | Out-Null
            $runtimeUnlockRetryDispatchSettlementAcceptanceMissingEvents.Add(
                $(if ($matchingReports.Count -gt 0) { $matchingReports[0] } else { $settlement })) | Out-Null
        }
    }
    $runtimeUnlockRetryDispatchUnsettledAuthorityEvents = @(
        $runtimeUnlockRetryDispatchAuthorityGrantedEvents | Where-Object {
            $grant = $_
            $matchingSettlements = @($runtimeUnlockRetryDispatchContractSettledEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$grant.Sequence -and
                (Test-RuntimeUnlockRetryDispatchMatch -Release $grant -Candidate $_)
            })
            (Get-FileTransferAuthoritySchema -Line ([string]$grant.RawLine)) -ge 2 -and
            $matchingSettlements.Count -eq 0
        }
    )
    $runtimeUnlockRetryDispatchUnsettledAuthorityNonReceiveRecoveryOperationEvents = @(
        $runtimeUnlockRetryDispatchUnsettledAuthorityEvents |
            Where-Object {
                [int64]$_.Sequence -notin $fileTransferReceiveRecoveryOperationPhase2EvidenceSequences
            }
    )
    $runtimeUnlockRetryDispatchGrantBypassedByRetryBudgetEvents = @(
        $runtimeUnlockRetryDispatchUnsettledAuthorityEvents | Where-Object {
            $grant = $_
            $grantSession = Get-FileTransferEventField -Event $grant -Name 'session_id' -Default ''
            $grantTransfer = Get-FileTransferEventField -Event $grant -Name 'transfer_id' -Default ''
            $grantContract = Get-FileTransferEventField -Event $grant -Name 'contract_generation' -Default ''
            @($runtimeUnlockBrokenStateRetrySuppressedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$grant.Sequence -and
                (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $grantSession -and
                (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq $grantTransfer -and
                (Get-FileTransferEventField -Event $_ -Name 'contract_generation' -Default '') -eq $grantContract
            }).Count -gt 0
        }
    )
    $runtimeUnlockRetryDispatchOrphanedSupersessionCount = 0
    foreach ($settlement in $runtimeUnlockRetryDispatchContractSettledEvents) {
        if ((Get-FileTransferAuthoritySchema -Line ([string]$settlement.RawLine)) -lt 2 -or
            (Get-FileTransferEventField -Event $settlement -Name 'settlement_outcome' -Default '') -ne 'Superseded') {
            continue
        }

        $predecessorAuthorityId = Get-FileTransferEventField -Event $settlement -Name 'authority_id' -Default '(none)'
        $successorAuthorityId = Get-FileTransferEventField -Event $settlement -Name 'successor_authority_id' -Default '(none)'
        $predecessorMissingDispatchGeneration = [int](Get-FileTransferEventField -Event $settlement -Name 'missing_dispatch_successor_generation' -Default '0')
        $matchingPredecessorGrant = @($runtimeUnlockRetryDispatchAuthorityGrantedEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$settlement.Sequence -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $_ -Candidate $settlement)
        })
        $matchingSuccessor = @($runtimeUnlockRetryDispatchAuthorityGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
            (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '(none)') -eq $successorAuthorityId -and
            (Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '(none)') -eq $predecessorAuthorityId -and
            [int](Get-FileTransferEventField -Event $_ -Name 'missing_dispatch_successor_generation' -Default '0') -eq $predecessorMissingDispatchGeneration -and
            (Test-RuntimeUnlockRetryDispatchSuccessorHandoffMatch -Predecessor $settlement -Successor $_)
        })
        if ($predecessorAuthorityId -eq '(none)' -or
            $successorAuthorityId -eq '(none)' -or
            $matchingPredecessorGrant.Count -ne 1 -or
            $matchingSuccessor.Count -ne 1) {
            $runtimeUnlockRetryDispatchOrphanedSupersessionCount++
        }
    }
    $runtimeUnlockRetryDispatchCompleteBoundedClosureEvents = New-Object System.Collections.Generic.List[object]
    $runtimeUnlockRetryDispatchCompleteBoundedClosureSettlementSequences = New-Object System.Collections.Generic.HashSet[int64]
    $runtimeUnlockRetryDispatchIncompleteBoundedClosureEvents = New-Object System.Collections.Generic.List[object]
    foreach ($limitRejection in $runtimeUnlockRetryMissingDispatchSuccessorLimitRejectedEvents) {
        if (-not $runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved) {
            continue
        }

        $matchingSettlements = @($runtimeUnlockRetryDispatchContractSettledEvents | Where-Object {
            [int64]$_.Sequence -lt [int64]$limitRejection.Sequence -and
            -not $runtimeUnlockRetryDispatchSettlementAcceptanceMissingSettlementSequences.Contains([int64]$_.Sequence) -and
            (Test-RuntimeUnlockRetryDispatchBoundedClosureMatch -Settlement $_ -Candidate $limitRejection)
        } | Sort-Object Sequence -Descending)
        $completeClosure = $null
        if ($matchingSettlements.Count -gt 0) {
            $settlement = $matchingSettlements[0]
            $completeClosure = @($runtimeUnlockRetryDispatchChainClosedEvents | Where-Object {
                [int64]$_.Sequence -gt [int64]$limitRejection.Sequence -and
                (Test-RuntimeUnlockRetryDispatchBoundedClosureMatch -Settlement $settlement -Candidate $_) -and
                (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
                (Get-FileTransferEventField -Event $_ -Name 'successor_decision_status' -Default '') -eq 'Rejected' -and
                (Get-FileTransferEventField -Event $_ -Name 'current_authority_cleared' -Default '0') -eq '1' -and
                (Get-FileTransferEventField -Event $_ -Name 'retry_deadline_cleared' -Default '0') -eq '1' -and
                (Get-FileTransferEventField -Event $_ -Name 'liveness_deferral_cleared' -Default '0') -eq '1'
            } | Sort-Object Sequence | Select-Object -First 1)
            if ($completeClosure.Count -gt 0) {
                $runtimeUnlockRetryDispatchCompleteBoundedClosureEvents.Add($completeClosure[0]) | Out-Null
                [void]$runtimeUnlockRetryDispatchCompleteBoundedClosureSettlementSequences.Add([int64]$settlement.Sequence)
            }
        }

        if ($null -eq $completeClosure -or $completeClosure.Count -eq 0) {
            $runtimeUnlockRetryDispatchIncompleteBoundedClosureEvents.Add($limitRejection) | Out-Null
        }
    }
    foreach ($grant in $runtimeUnlockRetryDispatchAuthorityGrantedEvents) {
        $coordinatorClosure =
            Get-FileTransferRuntimeUnlockRetryDispatchBoundedMissingDispatchClosure `
                -Events $events `
                -Grant $grant
        if ($null -eq $coordinatorClosure) {
            continue
        }

        $settlementSequence = [int64]$coordinatorClosure.Settlement.Sequence
        if ($runtimeUnlockRetryDispatchCompleteBoundedClosureSettlementSequences.Add(
                $settlementSequence)) {
            $runtimeUnlockRetryDispatchCompleteBoundedClosureEvents.Add(
                $coordinatorClosure.ChainClosed) | Out-Null
        }
    }

    $runtimeUnlockRetryDispatchFreshIndependentGrantEvents = New-Object System.Collections.Generic.List[object]
    $runtimeUnlockRetryDispatchInvalidFreshGrantEvents = New-Object System.Collections.Generic.List[object]
    foreach ($closure in $runtimeUnlockRetryDispatchCompleteBoundedClosureEvents) {
        $closureSession = Get-FileTransferEventField -Event $closure -Name 'session_id' -Default ''
        $closureTransfer = Get-FileTransferEventField -Event $closure -Name 'transfer_id' -Default ''
        $closureDirection = Get-FileTransferEventField -Event $closure -Name 'direction' -Default ''
        $laterGrant = @($runtimeUnlockRetryDispatchAuthorityGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$closure.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'session_id' -Default '') -eq $closureSession -and
            (Get-FileTransferEventField -Event $_ -Name 'transfer_id' -Default '') -eq $closureTransfer -and
            (Get-FileTransferEventField -Event $_ -Name 'direction' -Default '') -eq $closureDirection
        } | Sort-Object Sequence | Select-Object -First 1)
        if ($laterGrant.Count -eq 0) {
            continue
        }

        $predecessor = Get-FileTransferEventField -Event $laterGrant[0] -Name 'predecessor_authority_id' -Default '(none)'
        if ([int](Get-FileTransferEventField -Event $laterGrant[0] -Name 'dispatch_attempt_generation' -Default '0') -eq 1 -and
            [int](Get-FileTransferEventField -Event $laterGrant[0] -Name 'missing_dispatch_successor_generation' -Default '-1') -eq 0 -and
            $predecessor -in @('', '(none)', 'none', 'null')) {
            $runtimeUnlockRetryDispatchFreshIndependentGrantEvents.Add($laterGrant[0]) | Out-Null
        }
        else {
            $runtimeUnlockRetryDispatchInvalidFreshGrantEvents.Add($laterGrant[0]) | Out-Null
        }
    }
    $runtimeUnlockRetryDispatchSuccessorMissingAfterMissingDispatchEvents = New-Object System.Collections.Generic.List[object]
    foreach ($settlement in $runtimeUnlockRetryDispatchContractSettledEvents) {
        if ((Get-FileTransferAuthoritySchema -Line ([string]$settlement.RawLine)) -lt 2 -or
            (Get-FileTransferEventField -Event $settlement -Name 'settlement_outcome' -Default '') -ne 'MissingDispatch') {
            continue
        }

        $predecessorAuthorityId = Get-FileTransferEventField -Event $settlement -Name 'authority_id' -Default '(none)'
        $predecessorAttempt = [int](Get-FileTransferEventField -Event $settlement -Name 'dispatch_attempt_generation' -Default '0')
        $predecessorMissingDispatchGeneration = [int](Get-FileTransferEventField -Event $settlement -Name 'missing_dispatch_successor_generation' -Default '0')
        $failedOfferGeneration = [int64](Get-FileTransferEventField -Event $settlement -Name 'offer_generation' -Default '0')
        $matchingSuccessor = @($runtimeUnlockRetryDispatchAuthorityGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
            (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 -and
            (Get-FileTransferEventField -Event $_ -Name 'predecessor_authority_id' -Default '(none)') -eq $predecessorAuthorityId -and
            [int](Get-FileTransferEventField -Event $_ -Name 'dispatch_attempt_generation' -Default '0') -eq ($predecessorAttempt + 1) -and
            [int](Get-FileTransferEventField -Event $_ -Name 'missing_dispatch_successor_generation' -Default '0') -eq ($predecessorMissingDispatchGeneration + 1) -and
            ($failedOfferGeneration -le 0 -or
                [int64](Get-FileTransferEventField -Event $_ -Name 'retired_generation' -Default '0') -eq $failedOfferGeneration) -and
            (Test-RuntimeUnlockRetryDispatchSuccessorHandoffMatch -Predecessor $settlement -Successor $_)
        })
        if ($matchingSuccessor.Count -eq 1) {
            continue
        }
        if ($runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved -and
            $runtimeUnlockRetryDispatchCompleteBoundedClosureSettlementSequences.Contains([int64]$settlement.Sequence)) {
            continue
        }

        $matchingSuccessorRejection = @($runtimeUnlockRetrySuccessorIntentRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
            (Get-FileTransferAuthoritySchema -Line ([string]$_.RawLine)) -ge 2 -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '(none)') -eq $predecessorAuthorityId -and
            (Get-FileTransferEventField -Event $_ -Name 'requested_predecessor_authority_id' -Default '(none)') -eq $predecessorAuthorityId -and
            [int](Get-FileTransferEventField -Event $_ -Name 'requested_dispatch_attempt_generation' -Default '0') -eq ($predecessorAttempt + 1) -and
            [int](Get-FileTransferEventField -Event $_ -Name 'requested_missing_dispatch_successor_generation' -Default '0') -eq ($predecessorMissingDispatchGeneration + 1) -and
            ($failedOfferGeneration -le 0 -or
                [int64](Get-FileTransferEventField -Event $_ -Name 'requested_retired_generation' -Default '0') -eq $failedOfferGeneration) -and
            (Test-RuntimeUnlockRetryDispatchSuccessorHandoffMatch -Predecessor $settlement -Successor $_)
        })
        $matchingZeroOfferSuccessorRejection = @($matchingSuccessorRejection | Where-Object {
            [int64]$_.Sequence -in $runtimeUnlockRetryZeroOfferSuccessorCandidateSequences
        })
        $matchingFallbackPairedYieldSuccessorReleaseRejection = @($matchingSuccessorRejection | Where-Object {
            [int64]$_.Sequence -in $runtimeUnlockRetryFallbackPairedYieldSuccessorReleaseCandidateSequences
        })
        if ($matchingZeroOfferSuccessorRejection.Count -gt 0 -or
            $matchingFallbackPairedYieldSuccessorReleaseRejection.Count -gt 0) {
            continue
        }
        if ($matchingSuccessorRejection.Count -gt 0 -and
            -not $runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved) {
            continue
        }

        $settledPredecessorReuse = @($runtimeUnlockRetryDispatchAuthorityRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt [int64]$settlement.Sequence -and
            (Get-FileTransferEventField -Event $_ -Name 'authority_id' -Default '(none)') -eq $predecessorAuthorityId -and
            (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq 'runtime_unlock_retry_authority_settled'
        })
        $matchingTerminal = @($events | Where-Object {
            $terminalEvent = $_
            $terminalDirection = switch ($terminalEvent.EventName) {
                'file_transfer_outbound_terminal' { 'outbound'; break }
                'file_transfer_inbound_terminal' { 'inbound'; break }
                'transfer_terminal' { Get-FileTransferEventField -Event $terminalEvent -Name 'direction' -Default ''; break }
                default { '' }
            }
            [int64]$terminalEvent.Sequence -gt [int64]$settlement.Sequence -and
            $terminalEvent.EventName -in @('file_transfer_outbound_terminal', 'file_transfer_inbound_terminal', 'transfer_terminal') -and
            (Get-FileTransferEventField -Event $terminalEvent -Name 'session_id' -Default '') -eq
                (Get-FileTransferEventField -Event $settlement -Name 'session_id' -Default '') -and
            (Get-FileTransferEventField -Event $terminalEvent -Name 'transfer_id' -Default '') -eq
                (Get-FileTransferEventField -Event $settlement -Name 'transfer_id' -Default '') -and
            $terminalDirection -eq
                (Get-FileTransferEventField -Event $settlement -Name 'direction' -Default '')
        })
        if (($runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved -and $matchingTerminal.Count -eq 0) -or
            (-not $runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved -and
                ($settledPredecessorReuse.Count -gt 0 -or $matchingTerminal.Count -eq 0))) {
            $runtimeUnlockRetryDispatchSuccessorMissingAfterMissingDispatchEvents.Add($settlement) | Out-Null
        }
    }
    $runtimeUnlockRetryDispatchSuccessorMissingAfterMissingDispatchCount = $runtimeUnlockRetryDispatchSuccessorMissingAfterMissingDispatchEvents.Count
    [object[]]$runtimeUnlockRetryDispatchPostGrantHoldEvents = @(
        $runtimeUnlockRetryDispatchPostGrantHoldProof.UnresolvedCandidateEvents
    )
    $runtimeUnlockRetryDispatchPostGrantHoldCount =
        $runtimeUnlockRetryDispatchPostGrantHoldProof.RawCount
    foreach ($release in $runtimeUnlockRetryReleasedEvents) {
        $releaseSequence = [int64]$release.Sequence
        $matchingGrant = @($runtimeUnlockRetryDispatchAuthorityGrantedEvents | Where-Object {
            (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_)
        })
        $matchingObserved = @($runtimeUnlockRetryDispatchObservedEvents | Where-Object {
            [int64]$_.Sequence -gt $releaseSequence -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_)
        })
        $matchingRejected = @($runtimeUnlockRetryDispatchAuthorityRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $releaseSequence -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_)
        })
        $matchingDispatchMissingAfterGrant = @($runtimeUnlockRetryDispatchMissingAfterAuthorityGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt $releaseSequence -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_)
        })
        $matchingFailed = @($events | Where-Object {
            [int64]$_.Sequence -gt $releaseSequence -and
            $_.EventName -eq 'session_recovery_contract_failed' -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_)
        })
        $matchingSuperseded = @($runtimeUnlockRetryDispatchContractSettledEvents | Where-Object {
            [int64]$_.Sequence -gt $releaseSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'Superseded' -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_)
        })
        $matchingAcceptedMissingDispatch = @($runtimeUnlockRetryDispatchContractSettledEvents | Where-Object {
            $runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved -and
            [int64]$_.Sequence -gt $releaseSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
            -not $runtimeUnlockRetryDispatchSettlementAcceptanceMissingSettlementSequences.Contains([int64]$_.Sequence) -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_)
        })
        $matchingDisposedTerminalSettlement = @($runtimeUnlockRetryDispatchContractSettledEvents | Where-Object {
            $runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved -and
            [int64]$_.Sequence -gt $releaseSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -in @(
                'AuthorityRejected',
                'StaleRejected',
                'TerminalRejected',
                'TransferTerminal') -and
            $runtimeUnlockRetryDispatchSettlementDisposedSequences.Contains([int64]$_.Sequence) -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_)
        })

        if ($matchingDispatchMissingAfterGrant.Count -gt 0 -or
            ($matchingGrant.Count -gt 0 -and $matchingObserved.Count -gt 0) -or
            $matchingRejected.Count -gt 0 -or
            $matchingFailed.Count -gt 0 -or
            $matchingSuperseded.Count -gt 0 -or
            $matchingAcceptedMissingDispatch.Count -gt 0 -or
            $matchingDisposedTerminalSettlement.Count -gt 0) {
            continue
        }

        $runtimeUnlockRetryDispatchMissingCount++
    }

    foreach ($grant in @($runtimeUnlockRetryDispatchAuthorityGrantedEvents)) {
        $grantSequence = [int64]$grant.Sequence
        $matchingRelease = @($runtimeUnlockRetryReleasedEvents | Where-Object {
            (Test-RuntimeUnlockRetryDispatchMatch -Release $grant -Candidate $_)
        })
        if ($matchingRelease.Count -gt 0) {
            continue
        }

        $matchingObserved = @($runtimeUnlockRetryDispatchObservedEvents | Where-Object {
            [int64]$_.Sequence -gt $grantSequence -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $grant -Candidate $_)
        })
        $matchingRejected = @($runtimeUnlockRetryDispatchAuthorityRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $grantSequence -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $grant -Candidate $_)
        })
        $matchingDispatchMissingAfterGrant = @($runtimeUnlockRetryDispatchMissingAfterAuthorityGrantedEvents | Where-Object {
            [int64]$_.Sequence -gt $grantSequence -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $grant -Candidate $_)
        })
        $matchingFailed = @($events | Where-Object {
            [int64]$_.Sequence -gt $grantSequence -and
            $_.EventName -eq 'session_recovery_contract_failed' -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $grant -Candidate $_)
        })
        $matchingSuperseded = @($runtimeUnlockRetryDispatchContractSettledEvents | Where-Object {
            [int64]$_.Sequence -gt $grantSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'Superseded' -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $grant -Candidate $_)
        })
        $matchingAcceptedMissingDispatch = @($runtimeUnlockRetryDispatchContractSettledEvents | Where-Object {
            $runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved -and
            [int64]$_.Sequence -gt $grantSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -eq 'MissingDispatch' -and
            -not $runtimeUnlockRetryDispatchSettlementAcceptanceMissingSettlementSequences.Contains([int64]$_.Sequence) -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $grant -Candidate $_)
        })
        $matchingDisposedTerminalSettlement = @($runtimeUnlockRetryDispatchContractSettledEvents | Where-Object {
            $runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved -and
            [int64]$_.Sequence -gt $grantSequence -and
            (Get-FileTransferEventField -Event $_ -Name 'settlement_outcome' -Default '') -in @(
                'AuthorityRejected',
                'StaleRejected',
                'TerminalRejected',
                'TransferTerminal') -and
            $runtimeUnlockRetryDispatchSettlementDisposedSequences.Contains([int64]$_.Sequence) -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $grant -Candidate $_)
        })

        if ($matchingObserved.Count -eq 0 -and
            $matchingRejected.Count -eq 0 -and
            $matchingDispatchMissingAfterGrant.Count -eq 0 -and
            $matchingFailed.Count -eq 0 -and
            $matchingSuperseded.Count -eq 0 -and
            $matchingAcceptedMissingDispatch.Count -eq 0 -and
            $matchingDisposedTerminalSettlement.Count -eq 0) {
            $runtimeUnlockRetryDispatchMissingCount++
        }
    }

    $runtimeUnlockRetryMissingAuthorityAfterReleaseCount = 0
    foreach ($release in $runtimeUnlockRetryReleasedEvents) {
        $releaseSequence = [int64]$release.Sequence
        $matchingMissingAuthority = @($events | Where-Object {
            [int64]$_.Sequence -gt $releaseSequence -and
            (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_) -and
            $_.EventName -notin @(
                'runtime_unlock_retry_dispatch_authority_rejected',
                'session_recovery_contract_failed') -and
            (
                (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -eq 'missing_runtime_unlock_retry_authority' -or
                (Get-FileTransferEventField -Event $_ -Name 'blocker_reason' -Default '') -eq 'missing_runtime_unlock_retry_authority' -or
                (Get-FileTransferEventField -Event $_ -Name 'authority_failure_reason' -Default '') -eq 'missing_runtime_unlock_retry_authority' -or
                (Get-FileTransferEventField -Event $_ -Name 'decision_reason' -Default '') -eq 'missing_runtime_unlock_retry_authority'
            )
        })

        foreach ($missingAuthority in $matchingMissingAuthority) {
            $missingSequence = [int64]$missingAuthority.Sequence
            $matchingRejectedOrFailed = @($events | Where-Object {
                [int64]$_.Sequence -gt $missingSequence -and
                (Test-RuntimeUnlockRetryDispatchMatch -Release $release -Candidate $_) -and
                (
                    $_.EventName -eq 'runtime_unlock_retry_dispatch_authority_rejected' -or
                    $_.EventName -eq 'session_recovery_contract_failed'
                )
            })

            if ($matchingRejectedOrFailed.Count -eq 0) {
                $runtimeUnlockRetryMissingAuthorityAfterReleaseCount++
            }
        }
    }

    $runtimeUnlockRetryDispatchChainClosureProofVerdict = if (
        $runtimeUnlockRetryDispatchSettlementAcceptanceMissingEvents.Count -gt 0 -or
        $runtimeUnlockRetryDispatchIncompleteBoundedClosureEvents.Count -gt 0 -or
        $runtimeUnlockRetryDispatchInvalidFreshGrantEvents.Count -gt 0) {
        'fail'
    } elseif ($runtimeUnlockRetryDispatchPhase1SettlementProtocolObserved) {
        'pass'
    } else {
        'none'
    }

    $runtimeUnlockRetryDispatchProofVerdict = if ($runtimeUnlockRetryDispatchMissingCount -gt 0 -or
        $runtimeUnlockRetryDispatchUnsettledAuthorityEvents.Count -gt 0 -or
        $runtimeUnlockRetryMissingAuthorityAfterReleaseCount -gt 0 -or
        $runtimeUnlockRetryDispatchDuplicateObservedCount -gt 0 -or
        $runtimeUnlockRetryDispatchDuplicateSettlementCount -gt 0 -or
        $runtimeUnlockRetryDispatchOrphanedSupersessionCount -gt 0 -or
        $runtimeUnlockRetryDispatchPostGrantHoldProof.UnresolvedCount -gt 0 -or
        $runtimeUnlockRetryDispatchChainClosureProofVerdict -eq 'fail') {
        'fail'
    } elseif ($runtimeUnlockRetryDispatchReleaseCount -gt 0 -or
        $runtimeUnlockRetryDispatchPostGrantHoldProof.RecoveredCount -gt 0) {
        'pass'
    } else {
        'none'
    }

    $runtimeUnlockPreCommitProbeAckMissingCount = 0
    foreach ($sent in $runtimeUnlockPreCommitProbeSentEvents) {
        $sentSequence = [int64]$sent.Sequence
        $matchingProbeDelivery = @(
            $runtimeUnlockPreCommitProbeDeliveryResultEvents |
                Where-Object {
                    (Get-FileTransferEventField -Event $_ -Name 'delivery_result' -Default '') -eq 'sent' -and
                    (Get-FileTransferEventField -Event $_ -Name 'actual_transport' -Default '') -eq 'tuna' -and
                    (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $sent -Candidate $_)
                }
        )
        $matchingProbeReceiveOrAck = @(
            @($runtimeUnlockTunaProbeReceivedEvents + $runtimeUnlockTunaProbeAckSentEvents + $runtimeUnlockTunaProbeAckReceivedEvents + $runtimeUnlockPreCommitProbeAckedEvents + $runtimeUnlockTransactionCommittedEvents) |
                Where-Object {
                    [int64]$_.Sequence -gt $sentSequence -and
                    (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $sent -Candidate $_)
                }
        )
        $matchingProbeFailure = @($runtimeUnlockPreCommitProbeFailedEvents | Where-Object {
            [int64]$_.Sequence -gt $sentSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $sent -Candidate $_)
        })

        if ($matchingProbeDelivery.Count -eq 0 -and
            $matchingProbeReceiveOrAck.Count -eq 0 -and
            $matchingProbeFailure.Count -eq 0) {
            $runtimeUnlockPreCommitProbeAckMissingCount++
        }
    }

    foreach ($sent in $runtimeUnlockPreCommitProbeSentEvents) {
        $sentSequence = [int64]$sent.Sequence
        $matchingAckOrCommit = @(
            @($runtimeUnlockPreCommitProbeAckedEvents + $runtimeUnlockTunaProbeAckReceivedEvents + $runtimeUnlockTransactionCommittedEvents) |
                Where-Object {
                    [int64]$_.Sequence -gt $sentSequence -and
                    (($_.EventName -ne 'runtime_unlock_tuna_probe_ack_received') -or
                        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '1') -ne '0') -and
                    (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $sent -Candidate $_)
                }
        )
        $matchingFailure = @($runtimeUnlockPreCommitProbeFailedEvents | Where-Object {
            [int64]$_.Sequence -gt $sentSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $sent -Candidate $_)
        })
        $matchingAckAuthorityRejected = @($runtimeUnlockPreCommitProbeAckAuthorityRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $sentSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $sent -Candidate $_)
        })

        if ($matchingFailure.Count -eq 0 -or $matchingAckAuthorityRejected.Count -gt 0) {
            continue
        }

        $firstFailureSequence = (@($matchingFailure | Sort-Object Sequence | Select-Object -First 1))[0].Sequence
        $firstAckOrCommitSequence = if ($matchingAckOrCommit.Count -gt 0) {
            (@($matchingAckOrCommit | Sort-Object Sequence | Select-Object -First 1))[0].Sequence
        } else {
            $null
        }

        if ($null -eq $firstAckOrCommitSequence -or [int64]$firstFailureSequence -lt [int64]$firstAckOrCommitSequence) {
            $runtimeUnlockPreCommitProbeAckMissingCount++
        }
    }

    foreach ($received in $runtimeUnlockTunaProbeReceivedEvents) {
        $receivedSequence = [int64]$received.Sequence
        $matchingAckAuthorityRejected = @($runtimeUnlockPreCommitProbeAckAuthorityRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $receivedSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $received -Candidate $_)
        })

        if ($matchingAckAuthorityRejected.Count -eq 0) {
            continue
        }

        $matchingAckOrCommit = @(
            @($runtimeUnlockTunaProbeAckSentEvents + $runtimeUnlockPreCommitProbeAckDeliveryResultEvents + $runtimeUnlockTunaProbeAckReceivedEvents + $runtimeUnlockPreCommitProbeAckedEvents + $runtimeUnlockTransactionCommittedEvents) |
                Where-Object {
                    [int64]$_.Sequence -gt $receivedSequence -and
                    (($_.EventName -ne 'runtime_unlock_tuna_probe_ack_received') -or
                        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '1') -ne '0') -and
                    (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $received -Candidate $_)
                }
        )
        $firstRejectionSequence = (@($matchingAckAuthorityRejected | Sort-Object Sequence | Select-Object -First 1))[0].Sequence
        $firstAckOrCommitSequence = if ($matchingAckOrCommit.Count -gt 0) {
            (@($matchingAckOrCommit | Sort-Object Sequence | Select-Object -First 1))[0].Sequence
        } else {
            $null
        }

        if ($null -eq $firstAckOrCommitSequence -or [int64]$firstRejectionSequence -lt [int64]$firstAckOrCommitSequence) {
            $runtimeUnlockPreCommitProbeAckMissingCount++
        }
    }

    foreach ($ackSent in $runtimeUnlockTunaProbeAckSentEvents) {
        $ackSentSequence = [int64]$ackSent.Sequence
        $matchingAckDelivery = @(
            $runtimeUnlockPreCommitProbeAckDeliveryResultEvents |
                Where-Object {
                    (Get-FileTransferEventField -Event $_ -Name 'delivery_result' -Default '') -eq 'sent' -and
                    (Get-FileTransferEventField -Event $_ -Name 'actual_transport' -Default '') -eq 'tuna' -and
                    (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackSent -Candidate $_)
                }
        )
        $matchingAckReceive = @(
            @($runtimeUnlockTunaProbeAckReceivedEvents + $runtimeUnlockPreCommitProbeAckedEvents + $runtimeUnlockTransactionCommittedEvents) |
                Where-Object {
                    [int64]$_.Sequence -gt $ackSentSequence -and
                    (($_.EventName -ne 'runtime_unlock_tuna_probe_ack_received') -or
                        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '1') -ne '0') -and
                    (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackSent -Candidate $_)
                }
        )
        $matchingAckAuthorityRejected = @($runtimeUnlockPreCommitProbeAckAuthorityRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackSentSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackSent -Candidate $_)
        })
        $matchingAckFailure = @($runtimeUnlockPreCommitProbeFailedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackSentSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackSent -Candidate $_)
        })
        $matchingTransactionFailure = @($runtimeUnlockTransactionFailedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackSentSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackSent -Candidate $_)
        })

        if ($matchingAckDelivery.Count -eq 0 -and $matchingAckReceive.Count -eq 0) {
            $runtimeUnlockPreCommitProbeAckMissingCount++
        } elseif ($matchingAckDelivery.Count -gt 0 -and
            $matchingAckReceive.Count -eq 0 -and
            $matchingAckAuthorityRejected.Count -eq 0 -and
            $matchingAckFailure.Count -eq 0 -and
            $matchingTransactionFailure.Count -eq 0) {
            $runtimeUnlockPreCommitProbeAckMissingCount++
        }
    }

    foreach ($ackDelivery in $runtimeUnlockPreCommitProbeAckDeliveryResultEvents) {
        $ackDeliverySequence = [int64]$ackDelivery.Sequence
        if ((Get-FileTransferEventField -Event $ackDelivery -Name 'delivery_result' -Default '') -ne 'sent' -or
            (Get-FileTransferEventField -Event $ackDelivery -Name 'actual_transport' -Default '') -ne 'tuna') {
            continue
        }

        $matchingAckSent = @($runtimeUnlockTunaProbeAckSentEvents | Where-Object {
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackDelivery -Candidate $_)
        })
        if ($matchingAckSent.Count -gt 0) {
            continue
        }

        $matchingAckReceive = @(
            @($runtimeUnlockTunaProbeAckReceivedEvents + $runtimeUnlockPreCommitProbeAckedEvents + $runtimeUnlockTransactionCommittedEvents) |
                Where-Object {
                    [int64]$_.Sequence -gt $ackDeliverySequence -and
                    (($_.EventName -ne 'runtime_unlock_tuna_probe_ack_received') -or
                        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '1') -ne '0') -and
                    (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackDelivery -Candidate $_)
                }
        )
        $matchingAckAuthorityRejected = @($runtimeUnlockPreCommitProbeAckAuthorityRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackDeliverySequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackDelivery -Candidate $_)
        })
        $matchingAckFailure = @($runtimeUnlockPreCommitProbeFailedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackDeliverySequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackDelivery -Candidate $_)
        })
        $matchingTransactionFailure = @($runtimeUnlockTransactionFailedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackDeliverySequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackDelivery -Candidate $_)
        })

        if ($matchingAckReceive.Count -eq 0 -and
            $matchingAckAuthorityRejected.Count -eq 0 -and
            $matchingAckFailure.Count -eq 0 -and
            $matchingTransactionFailure.Count -eq 0) {
            $runtimeUnlockPreCommitProbeAckMissingCount++
        }
    }

    foreach ($ackReceive in $runtimeUnlockPreCommitProbeAckReceiveResultEvents) {
        $ackReceiveSequence = [int64]$ackReceive.Sequence
        if ((Get-FileTransferEventField -Event $ackReceive -Name 'delivery_result' -Default '') -ne 'received' -or
            (Get-FileTransferEventField -Event $ackReceive -Name 'actual_transport' -Default '') -ne 'tuna') {
            continue
        }

        $matchingAckObserved = @(
            @($runtimeUnlockTunaProbeAckReceivedEvents + $runtimeUnlockPreCommitProbeAckedEvents + $runtimeUnlockTransactionCommittedEvents) |
                Where-Object {
                    [int64]$_.Sequence -gt $ackReceiveSequence -and
                    (($_.EventName -ne 'runtime_unlock_tuna_probe_ack_received') -or
                        (Get-FileTransferEventField -Event $_ -Name 'accepted' -Default '1') -ne '0') -and
                    (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackReceive -Candidate $_)
                }
        )
        $matchingAckDispatchRejected = @($runtimeUnlockPreCommitProbeAckReceiveDispatchRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackReceiveSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackReceive -Candidate $_)
        })
        $matchingAckAuthorityRejected = @($runtimeUnlockPreCommitProbeAckAuthorityRejectedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackReceiveSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackReceive -Candidate $_)
        })
        $matchingAckFailure = @($runtimeUnlockPreCommitProbeFailedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackReceiveSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackReceive -Candidate $_)
        })
        $matchingTransactionFailure = @($runtimeUnlockTransactionFailedEvents | Where-Object {
            [int64]$_.Sequence -gt $ackReceiveSequence -and
            (Test-RuntimeUnlockPreCommitProbeTupleMatch -Sent $ackReceive -Candidate $_)
        })

        if ($matchingAckObserved.Count -eq 0 -and
            $matchingAckDispatchRejected.Count -eq 0 -and
            $matchingAckAuthorityRejected.Count -eq 0 -and
            $matchingAckFailure.Count -eq 0 -and
            $matchingTransactionFailure.Count -eq 0) {
            $runtimeUnlockPreCommitProbeAckMissingCount++
        }
    }

    $routeChanges = New-Object System.Collections.Generic.List[string]
    $lastRoute = ''
    foreach ($event in @($events | Sort-Object Sequence)) {
        if ($event.EventName -ne 'filetransfer_route_selected') {
            continue
        }

        $route = Get-FileTransferEventField -Event $event -Name 'route' -Default ''
        if ([string]::IsNullOrWhiteSpace($route) -or $route -eq $lastRoute) {
            continue
        }

        $routeChanges.Add($route) | Out-Null
        $lastRoute = $route
    }
    $hasPostTunaFallbackEvidence = $routeChanges -contains 'post_tuna_fallback_v6'
    if (-not $hasPostTunaFallbackEvidence) {
        $hasPostTunaFallbackEvidence = @($events | Where-Object {
            (Get-FileTransferEventField -Event $_ -Name 'route' -Default '') -eq 'post_tuna_fallback_v6'
        }).Count -gt 0
    }
    $hasRegularOnlyRouteEvidence =
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        -not $hasPostTunaFallbackEvidence

    function Test-PostTunaFallbackOutboundWorkerScopeMatch {
        param(
            [Parameter(Mandatory = $true)]$Anchor,
            [Parameter(Mandatory = $true)]$Candidate
        )

        foreach ($fieldName in @('session_id', 'transfer_id')) {
            $anchorValue = Get-FileTransferEventField -Event $Anchor -Name $fieldName -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($anchorValue) -or
                $anchorValue -in @('(none)', 'none') -or
                [string]::IsNullOrWhiteSpace($candidateValue) -or
                $candidateValue -in @('(none)', 'none') -or
                -not [string]::Equals($anchorValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-PostTunaFallbackOutboundWorkerPublicationTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Publication,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-PostTunaFallbackOutboundWorkerPublicationTupleComplete -Event $Publication) -or
            -not (Test-PostTunaFallbackOutboundWorkerPublicationTupleComplete -Event $Candidate) -or
            -not (Test-PostTunaFallbackOutboundWorkerScopeMatch -Anchor $Publication -Candidate $Candidate)) {
            return $false
        }

        foreach ($fieldName in @(
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'route_publication_generation',
                'route_commit_generation',
                'target_route',
                'target_protocol_version',
                'target_transport')) {
            $publicationValue = Get-FileTransferEventField -Event $Publication -Name $fieldName -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $fieldName -Default ''
            if (-not [string]::Equals($publicationValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Test-PostTunaFallbackOutboundWorkerPublicationTupleComplete {
        param([Parameter(Mandatory = $true)]$Event)

        foreach ($fieldName in @('session_id', 'transfer_id')) {
            $value = Get-FileTransferEventField -Event $Event -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none')) {
                return $false
            }
        }

        if (-not [string]::Equals(
                (Get-FileTransferEventField -Event $Event -Name 'direction' -Default ''),
                'outbound',
                [System.StringComparison]::OrdinalIgnoreCase)) {
            return $false
        }

        foreach ($fieldName in @(
                'route',
                'protocol_version',
                'live_route_epoch',
                'runtime_generation',
                'terminal_generation',
                'leg_generation',
                'route_publication_generation',
                'route_commit_generation',
                'target_route',
                'target_protocol_version',
                'target_transport')) {
            $value = Get-FileTransferEventField -Event $Event -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($value) -or $value -in @('(none)', 'none')) {
                return $false
            }
        }

        return $true
    }

    function Test-PostTunaFallbackOutboundWorkerFrontierTupleMatch {
        param(
            [Parameter(Mandatory = $true)]$Publication,
            [Parameter(Mandatory = $true)]$Candidate
        )

        if (-not (Test-PostTunaFallbackOutboundWorkerPublicationTupleComplete -Event $Publication) -or
            -not (Test-PostTunaFallbackOutboundWorkerScopeMatch -Anchor $Publication -Candidate $Candidate)) {
            return $false
        }

        foreach ($fieldName in @('route', 'protocol_version', 'live_route_epoch', 'leg_generation')) {
            $publicationValue = Get-FileTransferEventField -Event $Publication -Name $fieldName -Default ''
            $candidateValue = Get-FileTransferEventField -Event $Candidate -Name $fieldName -Default ''
            if ([string]::IsNullOrWhiteSpace($candidateValue) -or
                $candidateValue -in @('(none)', 'none') -or
                -not [string]::Equals($publicationValue, $candidateValue, [System.StringComparison]::OrdinalIgnoreCase)) {
                return $false
            }
        }

        return $true
    }

    function Get-PostTunaFallbackOutboundWorkerFrontierCorrelationKey {
        param([Parameter(Mandatory = $true)]$Event)

        $repairRequestId = Get-FileTransferEventField -Event $Event -Name 'repair_request_id' -Default ''
        $requestCorrelationId = Get-FileTransferEventField -Event $Event -Name 'request_correlation_id' -Default ''
        if ([string]::IsNullOrWhiteSpace($repairRequestId) -or
            $repairRequestId -in @('(none)', 'none') -or
            [string]::IsNullOrWhiteSpace($requestCorrelationId) -or
            $requestCorrelationId -in @('(none)', 'none')) {
            return ''
        }

        return ('{0}|{1}' -f $repairRequestId, $requestCorrelationId).ToLowerInvariant()
    }

