            -Events @($candidateRecord.Event) `
            -DefaultReason ([string]$candidateRecord.Reason) `
            -UseDefaultReason
    }
    foreach ($candidateRecord in @($fileTransferRouteTransitionProof.UnresolvedCandidateRecords)) {
        $candidateClass = if (-not [string]::IsNullOrWhiteSpace([string]$candidateRecord.Class)) {
            [string]$candidateRecord.Class
        }
        else {
            'filetransfer_route_transition_incomplete'
        }
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $candidateClass `
            -Events @($candidateRecord.Event) `
            -DefaultReason ([string]$candidateRecord.Reason) `
            -UseDefaultReason
    }
    foreach ($candidateRecord in @(
            $fileTransferGuiLiveFallbackFaultWindowProof.UnresolvedCandidateRecords)) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'filetransfer_gui_live_fallback_fault_window_missed' `
            -Events @($candidateRecord.Event) `
            -DefaultReason ([string]$candidateRecord.Reason) `
            -UseDefaultReason
    }
    foreach ($candidateRecord in @(
            $fileTransferRouteTransitionLiveEpochProjectionProof.UnresolvedCandidateRecords)) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'filetransfer_live_route_epoch_projection_missing' `
            -Events @($candidateRecord.Event) `
            -DefaultReason ([string]$candidateRecord.Reason) `
            -UseDefaultReason
    }
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'filetransfer_route_transition_draining_transport_grace_terminalization' `
        -Events @(
            $fileTransferRouteTransitionDrainingTransportGraceProof.UnresolvedCandidateEvents) `
        -DefaultReason 'coordinator_route_transition_draining_treated_as_transport_disconnect' `
        -UseDefaultReason
    foreach ($candidateRecord in @($runtimeUnlockRegularV4RouteCommitSendDrainProof.UnresolvedCandidateRecords)) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'runtime_unlock_regular_v4_route_commit_send_drain_missing' `
            -Events @($candidateRecord.Event) `
            -DefaultReason ([string]$candidateRecord.Reason) `
            -UseDefaultReason
    }
    if ($fileTunaV4DataPathProof.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class 'file_tuna_data_path_mismatch' `
            -Events $fileTunaV4DataPathProof.EvidenceEvents `
            -DefaultReason 'file_tuna_data_path_mismatch' `
            -UseDefaultReason
    }
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'active_file_tuna_v6_evidence' `
        -Events $fileTunaV6Events `
        -DefaultReason 'active_file_tuna_v6_evidence' `
        -UseDefaultReason
    Add-FileTransferProofChainFailureCandidates `
        -Candidates $proofChainFailureCandidates `
        -Class 'tuna_path_lease_unavailable_at_answer' `
        -Events @($runtimeUnlockAnswerRejectedTunaPathLeaseUnavailableEvents + $runtimeUnlockTunaPathLeaseRouteCommitRejectedEvents)

    $runtimeOwnerInvariant = Get-FileTransferInvariantRuntimeOwnerResult -Summary $Summary
    if ($runtimeOwnerInvariant.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $runtimeOwnerInvariant.FailureClass `
            -Events $runtimeOwnerInvariant.EvidenceEvents `
            -DefaultReason $runtimeOwnerInvariant.FailureClass `
            -UseDefaultReason
    }
    $routeLawInvariant = Get-FileTransferInvariantRouteLawResult -Summary $Summary
    if ($routeLawInvariant.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $routeLawInvariant.FailureClass `
            -Events $routeLawInvariant.EvidenceEvents `
            -DefaultReason $routeLawInvariant.FailureClass `
            -UseDefaultReason
    }
    $controlPriorityInvariant = Get-FileTransferInvariantControlPriorityResult -Summary $Summary
    if ($controlPriorityInvariant.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $controlPriorityInvariant.FailureClass `
            -Events $controlPriorityInvariant.EvidenceEvents `
            -DefaultReason $controlPriorityInvariant.FailureClass `
            -UseDefaultReason
    }
    if ($terminalLifecycleInvariant.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $terminalLifecycleInvariant.FailureClass `
            -Events $terminalLifecycleInvariant.EvidenceEvents `
            -DefaultReason $terminalLifecycleInvariant.FailureClass `
            -UseDefaultReason
    }
    if ($staleRejectedActionEffectProof.Verdict -eq 'fail') {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $staleRejectedActionEffectProof.FailureClass `
            -Events $staleRejectedActionEffectProof.FailureEvents `
            -DefaultReason $staleRejectedActionEffectProof.FailureClass `
            -UseDefaultReason
    }
    if ($fallbackRuntimeUnlockSeparationProof.Verdict -eq 'fail' -and $hasFallbackRouteOrOwnerEvidence) {
        Add-FileTransferProofChainFailureCandidates `
            -Candidates $proofChainFailureCandidates `
            -Class $fallbackRuntimeUnlockSeparationProof.FailureClass `
            -Events $fallbackRuntimeUnlockSeparationProof.FailureEvents `
            -DefaultReason $fallbackRuntimeUnlockSeparationProof.FailureClass `
            -UseDefaultReason
    }

    # Fallback symptoms are proof-chain candidates only after the retained slice
    # contains an actual fallback route or fallback-owner tuple. This prevents a
    # route-less downstream diagnostic from manufacturing fallback authority.
    if ($hasFallbackRouteOrOwnerEvidence) {
        $fallbackFailureClass = if ($fallbackTailProof.TransportEpochReauthorizationUnresolvedCount -gt 0) {
            # The cross-epoch suppression is the precise authority edge. One-sided
            # yield/quiescence symptoms in the retired scope are downstream.
            ''
        }
        elseif ($fallbackTailProof.YieldAuthorityRejectedCount -gt 0) {
            'fallback_tail_yield_authority_invalid'
        }
        elseif ($fallbackTailProof.OtherOwnerGenerationMismatchCount -gt 0) {
            'fallback_tail_owner_generation_mismatch'
        }
        elseif ($fallbackTailProof.FrontierRequestDispatchVerdict -eq 'fail') {
            'fallback_frontier_request_dispatch_missing'
        }
        elseif ($fallbackTailProof.FrontierRepairVerdict -eq 'fail') {
            'fallback_frontier_repair_stalled'
        }
        elseif ($fallbackTailProof.ProofReplayLocalYieldBlockedCount -gt 0 -and $fallbackTailProof.PairedYieldVerdict -eq 'fail') {
            'post_fallback_frontier_replay_unsettled'
        }
        elseif ($fallbackTailProof.LocalYieldBlockedCount -gt 0 -and $fallbackTailProof.PairedYieldVerdict -eq 'fail') {
            'fallback_tail_local_yield_missing'
        }
        elseif ($fallbackTailProof.QuiescenceVerdict -eq 'fail' -and
            $fallbackTailProof.BridgeRecoveryGenerationMismatchUnresolvedCount -eq 0) {
            'fallback_tail_quiescence_missing'
        }
        elseif ($fallbackTailProof.Verdict -eq 'fail') {
            'fallback_tail_reconciliation'
        }
        else {
            ''
        }
        if (-not [string]::IsNullOrWhiteSpace($fallbackFailureClass)) {
            [object[]]$fallbackFailureEvents = @(
                switch ($fallbackFailureClass) {
                    'fallback_tail_yield_authority_invalid' {
                        @($fallbackTailProof.YieldAuthorityRejectedEvents)
                        break
                    }
                    'fallback_tail_owner_generation_mismatch' {
                        @($fallbackTailProof.OtherOwnerGenerationMismatchEvents)
                        break
                    }
                    'fallback_frontier_request_dispatch_missing' {
                        @($fallbackTailProof.FrontierRequestDispatchMissingEvents)
                        break
                    }
                    'fallback_frontier_repair_stalled' {
                        @($fallbackTailProof.FrontierRepairUnresolvedStalledEvents)
                        break
                    }
                    default {
                        @(
                            $fallbackTailProof.QuiescenceEvidenceEvents |
                                Where-Object {
                                    $_.EventName -ne 'filetransfer_route_selected' -and
                                    $_.EventName -notlike 'filetransfer_fallback_leg_authority_started'
                                }
                        )
                    }
                }
            )
            if ($fallbackFailureEvents.Count -eq 0) {
                $fallbackFailureEvents = @($fallbackTailProof.EvidenceEvents | Where-Object { $_.EventName -ne 'filetransfer_route_selected' })
            }
            Add-FileTransferProofChainFailureCandidates `
                -Candidates $proofChainFailureCandidates `
                -Class $fallbackFailureClass `
                -Events $fallbackFailureEvents `
                -DefaultReason $fallbackFailureClass `
                -UseDefaultReason
        }
    }

    [object[]]$firstProofChainFailureCandidates =
        @($proofChainFailureCandidates.ToArray())
    if ($fileTransferRouteTransitionDrainingTransportGraceProof.UnresolvedCount -gt 0) {
        # A transition-grace terminalization is the exact authority edge.  Raw
        # repair deferral/stall candidates can begin earlier while the same
        # logical repair remains unresolved only because this transition later
        # terminalizes the transfer.  Keep precise earlier semantic failures,
        # but do not let those aggregate repair symptoms mask the causal edge.
        $firstProofChainFailureCandidates = @(
            $firstProofChainFailureCandidates |
                Where-Object {
                    $_.Class -notin @(
                        'regular_v4_frontier_repair_send_deferred_or_stalled',
                        'regular_v4_frontier_repair_stalled')
                })
    }

    $firstProofChainFailure = @(
        $firstProofChainFailureCandidates |
            Sort-Object Sequence, LineNumber, Class, Event |
            Select-Object -First 1
    )
    if ($firstProofChainFailure.Count -eq 0) {
        $firstProofChainFailure = $null
    }
    else {
        $firstProofChainFailure = $firstProofChainFailure[0]
    }

    $class = '(none)'
    if ($null -ne $firstProofChainFailure) {
        # A retained, explicit proof-chain rejection owns classification before
        # aggregate symptoms (for example, later fallback or liveness failures).
        $class = $firstProofChainFailure.Class
    }
    elseif ($runtimeUnlockFileTransferOwnerMissingBeforePathLeaseUnresolvedEvents.Count -gt 0) {
        $class = 'runtime_unlock_filetransfer_owner_missing_before_path_lease'
    }
    elseif ($runtimeUnlockFileTransferOwnerStaleBeforeOfferDispatchUnresolvedEvents.Count -gt 0) {
        $class = 'runtime_unlock_filetransfer_owner_stale_before_offer_dispatch'
    }
    elseif ($runtimeUnlockRetrySourcePublicationMismatchEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_source_publication_mismatch'
    }
    elseif ($runtimeUnlockRetryDispatchSettlementAcceptanceMissingEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_settlement_unaccepted'
    }
    elseif ($runtimeUnlockRetryDispatchIncompleteBoundedClosureEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_chain_closure_incomplete'
    }
    elseif ($runtimeUnlockRetryDispatchInvalidFreshGrantEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_fresh_chain_invalid_after_closure'
    }
    elseif ($runtimeUnlockRetryDispatchGrantBypassedByRetryBudgetEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_grant_bypassed_by_retry_budget'
    }
    elseif ($runtimeUnlockRetryDispatchUnsettledAuthorityNonReceiveRecoveryOperationEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_contract_unsettled'
    }
    elseif ($runtimeUnlockRetryDispatchSuccessorMissingAfterMissingDispatchCount -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_successor_missing_after_missing_dispatch'
    }
    elseif ($runtimeUnlockRegularV4RecoveryClosureOfferTimeoutHandoffProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_handoff_missing'
    }
    elseif ($runtimeUnlockInitialOfferRetryLifecycleHandoffProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_initial_offer_retry_lifecycle_handoff_missing'
    }
    elseif ($runtimeUnlockInitialActivationAnswerPeerDeliveryProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_initial_activation_answer_peer_delivery_missing'
    }
    elseif ($runtimeUnlockInitialOfferReceiveRecoveryHoldProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_initial_offer_receive_recovery_hold_not_preserved'
    }
    elseif ($runtimeUnlockInitialActivationReceiveRecoveryHoldReleaseDeliveryProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_initial_activation_receive_recovery_hold_release_delivery_missing'
    }
    elseif ($runtimeUnlockInitialActivationReceiveRecoveryHoldReleasedPathLeaseExpiredProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_initial_activation_receive_recovery_hold_released_path_lease_expired'
    }
    elseif ($runtimeUnlockInitialActivationReceiveRecoveryHoldReleasedOfferExpiredProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_initial_activation_receive_recovery_hold_released_offer_expired'
    }
    elseif ($regularV4PeerSilenceReplayMissingDispatchRangeProof.UnresolvedCount -gt 0) {
        $class = 'regular_v4_peer_silence_replay_missing_dispatch_range_not_preserved'
    }
    elseif ($regularV4PeerSilenceReplayInstalledAuthorityDispatchProof.UnresolvedCount -gt 0) {
        $class = 'regular_v4_peer_silence_replay_installed_authority_not_carried_to_dispatch'
    }
    elseif ($regularV4FrontierRepairInitialPressureInstallProof.UnresolvedCount -gt 0) {
        $class = 'regular_v4_frontier_repair_initial_pressure_install_missing'
    }
    elseif ($regularV4FrontierRepairSuccessorPressureInstallProof.UnresolvedCount -gt 0) {
        $class = 'regular_v4_frontier_repair_successor_pressure_install_missing'
    }
    elseif ($runtimeUnlockRetryDispatchAuthorityTupleMismatchClassificationEvents.Count -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_authority_tuple_mismatch'
    }
    elseif ($publicationAuthorityFieldCoverageProof.Verdict -eq 'fail') {
        $class = 'publication_authority_missing'
    }
    elseif ($fileTransferReceiveRecoveryFallbackCheckpointScopeHandoffProof.UnresolvedCount -gt 0) {
        $class = 'filetransfer_receive_recovery_fallback_checkpoint_scope_handoff_missing'
    }
    elseif ($fileTransferRouteTransitionDrainingTransportGraceProof.UnresolvedCount -gt 0) {
        $class =
            'filetransfer_route_transition_draining_transport_grace_terminalization'
    }
    elseif ($runtimeUnlockResponderPeerProbeHandoffProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_responder_acked_probe_route_transition_handoff_missing'
    }
    elseif ($fileTransferRouteTransitionProof.FallbackV6ProofBootstrapMissingUnresolvedCount -gt 0) {
        $class =
            'filetransfer_route_transition_tuna_v4_to_post_tuna_fallback_v6_proof_bootstrap_missing'
    }
    elseif ($fileTransferRouteTransitionProof.UnresolvedCount -gt 0) {
        $class = 'filetransfer_route_transition_incomplete'
    }
    elseif ($fileTransferRouteTransitionLiveEpochProjectionProof.UnresolvedCount -gt 0) {
        $class = 'filetransfer_live_route_epoch_projection_missing'
    }
    elseif ($runtimeUnlockRegularV4RouteCommitSendDrainProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_regular_v4_route_commit_send_drain_missing'
    }
    elseif ($fileTunaV4DataPathProof.Verdict -eq 'fail') {
        $class = 'file_tuna_data_path_mismatch'
    }
    elseif ($runtimeUnlockRetryDispatchPostGrantHoldProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_held_after_authority_granted'
    }
    elseif ($runtimeUnlockPreCommitProbeStartHandoffProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_precommit_probe_start_handoff_missing'
    }
    elseif ($runtimeUnlockRetryDispatchMissingAfterAuthorityGrantedCount -gt 0) {
        $class = 'runtime_unlock_retry_dispatch_missing_after_authority_granted'
    }
    elseif ($runtimeUnlockRecoveryLeaseClosureNotAdoptedUnresolvedCount -gt 0) {
        $class = 'runtime_unlock_regular_v4_recovery_lease_closure_not_adopted'
    }
    elseif ($bridgeRecoveryExecutionPayloadHoldProof.UnresolvedCount -gt 0) {
        $class = 'filetransfer_bridge_recovery_execution_payload_hold_missing'
    }
    elseif ($fileTransferReceiveRecoveryCompletedUnprovenPayloadHoldProof.UnresolvedCount -gt 0) {
        $class =
            'filetransfer_receive_recovery_completed_unproven_payload_hold_not_preserved'
    }
    elseif ($fileTransferReceiveRecoveryCompletedRetainedProofStatePublicationProof.UnresolvedCount -gt 0) {
        $class =
            'filetransfer_receive_recovery_completed_retained_proof_state_publication_missing'
    }
    elseif ($fileTransferReceiveRecoveryCompletedRetainedProofStateRecheckHeartbeatSuppressionProof.UnresolvedCount -gt 0) {
        $class =
            'filetransfer_receive_recovery_completed_retained_proof_state_recheck_heartbeat_suppressed'
    }
    elseif ($bridgeRecoveryExecutionSubmissionBarrierDrainProof.UnresolvedCount -gt 0) {
        $class = 'filetransfer_bridge_recovery_execution_submission_barrier_drain_missing'
    }
    elseif ($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureLivenessUnresolvedCount -gt 0) {
        $class = 'runtime_unlock_regular_v4_recovery_lease_closure_liveness_not_preserved'
    }
    elseif ($bridgeRecoveryExecutionStartupPayloadIsolationProof.UnresolvedCount -gt 0) {
        $class = 'filetransfer_bridge_recovery_execution_startup_payload_isolation_missing'
    }
    elseif ($bridgeRecoveryExecutionSoftToHardHandoffProof.UnresolvedCount -gt 0) {
        $class = 'filetransfer_bridge_recovery_execution_soft_to_hard_handoff_missing'
    }
    elseif ($runtimeUnlockRegularV4RecoveryLeaseIssuanceProof.ClosureHoldNotPreservedUnresolvedCount -gt 0) {
        $class = 'runtime_unlock_retry_regular_v4_recovery_lease_closure_hold_not_preserved'
    }
    elseif ($runtimeUnlockRetryRegularV4SettlementHandoffBypassedCount -gt 0) {
        $class = 'runtime_unlock_retry_regular_v4_settlement_handoff_bypassed'
    }
    elseif ($runtimeUnlockRetryDispatchProofVerdict -eq 'fail') {
        $class = 'runtime_unlock_retry_dispatch_missing'
    }
    elseif ($regularV4RecoveryPredecessorSettlementClosedSuccessorEvents.Count -gt 0) {
        $class = 'regular_v4_recovery_predecessor_settlement_closed_successor'
    }
    elseif ($regularV4ReceiveRecoveryRejectedBeforeRuntimeUnlock) {
        $class = 'regular_v4_receive_recovery_rejected_before_runtime_unlock'
    }
    elseif ($regularV4FrontierRepairSettlementDispositionUnverifiableEvents.Count -gt 0) {
        $class = 'regular_v4_frontier_repair_settlement_disposition_unverifiable'
    }
    elseif ($runtimeUnlockRetryRegularV4RecoverySettlementMissingCount -gt 0) {
        $class = 'runtime_unlock_retry_regular_v4_recovery_settlement_missing'
    }
    elseif ($runtimeUnlockUncommittedTunaFallbackProofAuthorityProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_uncommitted_tuna_fallback_proof_authority_missing'
    }
    elseif ($runtimeUnlockUncommittedTunaFallbackHandoffSuppressionProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_precommit_fallback_recovery_handoff_suppressed'
    }
    elseif ($runtimeUnlockUncommittedTunaFallbackPrecommitAuthorityProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_uncommitted_tuna_fallback_handoff_precommit_authority_misbound'
    }
    elseif ($runtimeUnlockPostTunaFallbackTransportProofHandoffProof.UnresolvedCount -gt 0) {
        $class = 'runtime_unlock_post_tuna_fallback_transport_proof_handoff_missing'
    }
    elseif ($regularV4FrontierRepairSendDeferred) {
        $class = 'regular_v4_frontier_repair_send_deferred_or_stalled'
    }
    elseif ($regularV4FrontierRepairStalled) {
        $class = 'regular_v4_frontier_repair_stalled'
    }
    elseif ($regularV4RepairLivenessAuthorityMissing) {
        $class = 'regular_v4_repair_liveness_authority_missing'
    }
    elseif ($staleRejectedActionEffectProof.Verdict -eq 'fail') {
        $class = 'stale_rejected_action_effect'
    }
    elseif ($fallbackRuntimeUnlockSeparationProof.FallbackUnavailableWithoutCoordinatorDenialCount -gt 0) {
        $class = 'stale_rejected_action_effect'
    }
    elseif ($fileTunaV6Events.Count -gt 0) {
        $class = 'active_file_tuna_v6_evidence'
    }
    elseif ($fallbackTailProof.YieldAuthorityRejectedCount -gt 0 -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_yield_authority_invalid'
    }
    elseif ($fallbackTailProof.OtherOwnerGenerationMismatchCount -gt 0 -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_owner_generation_mismatch'
    }
    elseif ($fallbackTailProof.FrontierRequestDispatchVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_frontier_request_dispatch_missing'
    }
    elseif ($fallbackTailProof.FrontierRepairVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_frontier_repair_stalled'
    }
    elseif ($fallbackTailProof.ProofReplayLocalYieldBlockedCount -gt 0 -and
        $fallbackTailProof.PairedYieldVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'post_fallback_frontier_replay_unsettled'
    }
    elseif ($fallbackTailProof.LocalYieldBlockedCount -gt 0 -and
        $fallbackTailProof.PairedYieldVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_local_yield_missing'
    }
    elseif ($fallbackTailProof.PairedYieldVerdict -eq 'fail' -and
        $fallbackTailProof.RuntimeUnlockProbeRejectedByInboundFallbackOwnerCount -gt 0 -and
        $hasPostTunaFallbackEvidence) {
        $class = 'runtime_unlock_probe_rejected_by_inbound_fallback_owner'
    }
    elseif ($fallbackTailProof.PairedYieldVerdict -eq 'fail' -and
        $fallbackTailProof.QuiescentYieldGrantedCount -gt 0 -and
        $hasPostTunaFallbackEvidence) {
        $class = 'paired_fallback_tail_yield_missing'
    }
    elseif ($fallbackTailProof.QuiescenceVerdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_quiescence_missing'
    }
    elseif ($fallbackRuntimeUnlockSeparationProof.Verdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = if ($fallbackRuntimeUnlockSeparationProof.FallbackUnavailableWithoutCoordinatorDenialCount -gt 0) {
            'stale_rejected_action_effect'
        }
        else {
            'runtime_fallback_separation_violation'
        }
    }
    elseif ($fallbackTailProof.Verdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_tail_reconciliation'
    }
    elseif ($postFallbackRuntimeUnlockResumeBlocked) {
        $class = if ($runtimeUnlockFallbackProofReplayPendingAfterPairedYieldUnresolvedEvents.Count -gt 0) {
            'fallback_proof_replay_pending_after_paired_yield'
        } else {
            'post_fallback_runtime_unlock_resume_blocked'
        }
    }
    elseif (($controlPlaneProof.StaleReplayTreadmillCount -gt $controlPlaneProof.StaleGenerationTreadmillScoreLimit -or
            $controlPlaneProof.CheckpointOwnerViolationCount -gt 0 -or
            $controlPlaneProof.ControlPlaneNonCurrentLegGenerationSendCount -gt 0) -and
        $hasPostTunaFallbackEvidence) {
        $class = 'fallback_control_plane_stale_generation_treadmill'
    }
    elseif ($hasPostTunaFallbackEvidence -and
        (
            $postTunaFallbackBulkActiveSuppressedDuringPressureEvents.Count -gt 0 -or
            (
                $postTunaFallbackControlPlanePressureMarkedEvents.Count -gt 0 -and
                $postTunaFallbackControlPlanePressureAllowedEvents.Count -eq 0 -and
                ($sessionLivenessTimeoutEvents.Count -gt 0 -or $peerDisconnectedTerminalEvents.Count -gt 0)
            ) -or
            (
                $postTunaFallbackLegacyControlLaneStarvationEvents.Count -gt 32 -and
                @($events | Where-Object {
                    $_.EventName -eq 'nkn_bridge_control_receive_recovery_suppressed' -and
                    (Get-FileTransferEventField -Event $_ -Name 'reason' -Default '') -in @('bulk_receive_active', 'filetransfer_bulk_receive_active')
                }).Count -gt 0
            )
        )) {
        $class = 'fallback_control_lane_starvation_under_bulk_receive'
    }
    elseif ($controlPlaneProof.Verdict -eq 'fail' -and
        $hasPostTunaFallbackEvidence -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or $peerDisconnectedTerminalEvents.Count -gt 0)) {
        $class = 'fallback_control_plane_starvation'
    }
    elseif ($runtimeUnlockAnswerRejectedTunaPathLeaseUnavailableEvents.Count -gt 0 -or
        $runtimeUnlockTunaPathLeaseRouteCommitRejectedEvents.Count -gt 0) {
        $class = 'tuna_path_lease_unavailable_at_answer'
    }
    elseif ($runtimeUnlockPreCommitProbeAckMissingCount -gt 0) {
        $class = 'runtime_unlock_precommit_probe_ack_missing'
    }
    elseif ($runtimeUnlockTransactionCommittedEvents.Count -gt 0 -and
        -not $runtimeUnlockHasPreCommitAckProof) {
        $class = 'runtime_unlock_route_commit_before_probe'
    }
    elseif ($runtimeUnlockProbeStartedEvents.Count -gt 0 -and
        $runtimeUnlockPreCommitProbeStartedEvents.Count -eq 0 -and
        $runtimeUnlockPreCommitProbeProtocolMismatchEvents.Count -gt 0 -and
        -not $runtimeUnlockHasPreCommitAckProof) {
        $class = 'runtime_unlock_precommit_probe_protocol_mismatch'
    }
    elseif ($runtimeUnlockTransactionPeerProofEvents.Count -gt 0 -and
        $runtimeUnlockPreCommitProbeStartedEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeSentEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeReceivedEvents.Count -eq 0 -and
        $runtimeUnlockTunaProbeAckReceivedEvents.Count -eq 0 -and
        $runtimeUnlockTunaProbeSidecarFailureEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        $runtimeUnlockTransactionCommittedEvents.Count -eq 0 -and
        ($cleanRegularV4TerminalEvents.Count -gt 0 -or
         $regularV4TerminalBeforeActivationEvents.Count -gt 0)) {
        $class = 'runtime_unlock_tuna_probe_sidecar_closed_regular_v4_terminal'
    }
    elseif ($runtimeUnlockListenerRearmAfterProbeCloseFailedEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeSidecarFailureEvents.Count -gt 0) {
        $class = 'runtime_unlock_tuna_listener_unavailable_after_probe_close'
    }
    elseif ($runtimeUnlockTransactionPeerProofEvents.Count -gt 0 -and
        $runtimeUnlockPreCommitProbeStartedEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeSentEvents.Count -gt 0 -and
        $runtimeUnlockTunaProbeReceivedEvents.Count -eq 0 -and
        $runtimeUnlockTunaProbeAckReceivedEvents.Count -eq 0 -and
        ($runtimeUnlockTunaProbeSidecarFailureEvents.Count -gt 0 -or
         $runtimeUnlockPreCommitProbeFailedEvents.Count -gt 0 -or
         $runtimeUnlockProbeFailedEvents.Count -gt 0)) {
        $class = 'runtime_unlock_tuna_probe_path_not_established'
    }
    elseif ($runtimeUnlockTransactionPeerProofEvents.Count -gt 0 -and
        -not $runtimeUnlockHasPreCommitAckProof -and
        ($runtimeUnlockProbeMissingRejectedEvents.Count -gt 0 -or
         $sessionLivenessTimeoutEvents.Count -gt 0 -or
         $peerDisconnectedTerminalEvents.Count -gt 0)) {
        $class = 'runtime_unlock_offer_answer_without_probe'
    }
    elseif ($fallbackRuntimeUnlockSeparationProof.Verdict -eq 'fail' -and
        $routeChanges -contains 'post_tuna_fallback_v6') {
        $class = if ($fallbackRuntimeUnlockSeparationProof.FallbackUnavailableWithoutCoordinatorDenialCount -gt 0) {
            'stale_rejected_action_effect'
        }
        else {
            'runtime_fallback_separation_violation'
        }
    }
    elseif ($runtimeUnlockProbeInvalidRejectedEvents.Count -gt 0 -or
        $runtimeUnlockProbeFailedEvents.Count -gt 0) {
        $class = 'runtime_unlock_probe_failed'
    }
    elseif ($runtimeUnlockRegularV4PeerVisibleWindowDeliveryStartedEvents.Count -gt 0 -and
        $runtimeUnlockRegularV4ActivationWindowPeerVisibleEvents.Count -eq 0 -and
        ($runtimeUnlockRegularV4PeerVisibleWindowDeliveryFailedEvents.Count -gt 0 -or
         $runtimeUnlockRegularV4ActivationWindowFailedEvents.Count -gt 0) -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        $runtimeUnlockTransactionCommittedEvents.Count -eq 0) {
        $class = 'runtime_unlock_regular_v4_peer_visible_window_delivery_failed'
    }
    elseif ($runtimeUnlockRegularV4ActivationWindowStartedEvents.Count -gt 0 -and
        $runtimeUnlockTransactionObservedSendEvents.Count -gt 0 -and
        $runtimeUnlockRegularV4ActivationWindowPeerVisibleEvents.Count -eq 0 -and
        ($runtimeUnlockRegularV4ActivationWindowFailedEvents.Count -gt 0 -or
         $runtimeUnlockRegularV4PeerVisibleWindowLateProofIgnoredEvents.Count -gt 0) -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        $runtimeUnlockTransactionCommittedEvents.Count -eq 0) {
        $class = 'runtime_unlock_peer_visible_window_race'
    }
    elseif (($runtimeUnlockRegularV4ActivationWindowFailedEvents.Count -gt 0 -or
            $runtimeUnlockDispatchDeferredForRegularV4RecoveryEvents.Count -gt 0 -or
            (
                $runtimeUnlockBrokenStateRetrySuppressedEvents.Count -gt 0 -and
                $regularV4FrontierStallMissingRangeEvents.Count -gt 0
            )) -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        $runtimeUnlockTransactionCommittedEvents.Count -eq 0 -and
        -not $runtimeUnlockHasPreCommitAckProof -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or
         $peerDisconnectedTerminalEvents.Count -gt 0 -or
         $runtimeUnlockTransactionFailedEvents.Count -gt 0)) {
        $class = 'runtime_unlock_regular_v4_recovery_arbitration'
    }
    elseif ($runtimeUnlockBrokenStateRetrySuppressedEvents.Count -gt 0 -or
        $runtimeUnlockBrokenStateTransactionFailedEvents.Count -gt 0 -or
        ($runtimeUnlockBrokenStateFreshRetryConsumedEvents.Count -gt 0 -and
         $runtimeUnlockOfferNotObservedEvents.Count -gt 1 -and
         $runtimeUnlockTransactionPeerProofEvents.Count -eq 0)) {
        $class = 'runtime_unlock_broken_state_retry_churn'
    }
    elseif ($runtimeUnlockTransactionObservedSendEvents.Count -gt 0 -and
        $runtimeUnlockTransactionPeerProofEvents.Count -eq 0 -and
        ($runtimeUnlockTransactionLocalOnlyRejectedEvents.Count -gt 0 -or $sessionLivenessTimeoutEvents.Count -gt 0)) {
        $class = 'runtime_unlock_transaction_local_only'
    }
    elseif ($runtimeUnlockTransactionCommitPendingEvents.Count -gt $runtimeUnlockTransactionCommittedEvents.Count -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or $runtimeUnlockTransactionFailedEvents.Count -gt 0)) {
        $class = 'runtime_unlock_transaction_commit_missing'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryDispatchedEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryAuthorityObservedEvents.Count -gt 0 -and
        $sessionLivenessTimeoutEvents.Count -eq 0 -and
        $peerDisconnectedTerminalEvents.Count -eq 0) {
        $class = '(none)'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $runtimeUnlockOfferPeerResponseTimeoutEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryDispatchedEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryAuthorityObservedEvents.Count -gt 0 -and
        $runtimeUnlockCutThroughPeerReceivedEvents.Count -eq 0 -and
        $sessionLivenessTimeoutEvents.Count -gt 0 -and
        $peerDisconnectedTerminalEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast') {
        $class = 'runtime_unlock_peer_response_not_received_under_regular_v4_recovery'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $sessionRecoveryContractRetryDispatchedEvents.Count -gt 0 -and
        ($runtimeUnlockOfferRejectedWithoutObservationEvents.Count -gt 0 -or $runtimeUnlockReceiveRecoveryBlockedOfferEvents.Count -gt 0) -and
        $sessionLivenessTimeoutEvents.Count -gt 0 -and
        $peerDisconnectedTerminalEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast') {
        $class = 'runtime_unlock_offer_observation_blocked_by_receive_recovery'
    }
    elseif ($runtimeUnlockDispatchDeferredForRegularV4RecoveryEvents.Count -gt 0 -and
        $sessionLivenessTimeoutEvents.Count -gt 0 -and
        $peerDisconnectedTerminalEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast') {
        $class = 'runtime_unlock_dispatch_deferred_by_regular_v4_receive_recovery'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $listenerRearmRequiredEvents.Count -gt 0 -and
        $listenerRearmCompletedEvents.Count -eq 0 -and
        ($listenerRearmFailedEvents.Count -gt 0 -or $listenerReadyUnavailableContradictionEvents.Count -gt 0) -and
        ($sessionLivenessTimeoutEvents.Count -gt 0 -or $peerDisconnectedTerminalEvents.Count -gt 0)) {
        $class = 'tuna_listener_rearm_coordination'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and
        $runtimeUnlockRetryScheduledEvents.Count -gt 0 -and
        $runtimeUnlockRetryQueuedBehindActiveNegotiationEvents.Count -gt 0 -and
        $sessionLivenessTimeoutEvents.Count -gt 0 -and
        $peerDisconnectedTerminalEvents.Count -gt 0 -and
        $routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast') {
        $class = 'runtime_unlock_recovery_coordination'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0 -and $sessionLivenessTimeoutEvents.Count -gt 0) {
        $class = 'runtime_unlock_liveness_timeout'
    }
    elseif ($runtimeUnlockOfferNotObservedEvents.Count -gt 0) {
        $class = 'runtime_unlock_offer_not_observed'
    }
    elseif ($sessionLivenessTimeoutEvents.Count -gt 0) {
        $class = 'session_liveness_timeout'
    }

    $regularV4EfficiencyPressureClass = if ($routeChanges.Count -eq 1 -and
        $routeChanges[0] -eq 'regular_nkn_v4_fast' -and
        (
            $regularV4FrontierRebindEvents.Count -gt 3 -or
            ($regularV4FrontierRebindEvents.Count -gt 0 -and $regularV4RepairSkippedNotYetSentEvents.Count -gt 0) -or
            (
                $regularV4FrontierRebindEvents.Count -gt 0 -and
                $regularV4FrontierStallMissingRangeEvents.Count -gt 0 -and
                ($regularV4RepairRequestedEvents.Count -gt 0 -or $regularV4RepairCachePressureEvents.Count -gt 0)
            )
        )) {
        'regular_v4_recovery_rewind_treadmill'
    }
    else {
        '(none)'
    }

    $runtimeUnlockHasMakeBeforeBreakEvidence =
        $runtimeUnlockTransactionStartedEvents.Count -gt 0 -or
        $runtimeUnlockPreCommitRouteEpochRecoveredEvents.Count -gt 0
    $runtimeUnlockHasMakeBeforeBreakInvalidEvidence =
        $runtimeUnlockProbeInvalidRejectedEvents.Count -gt 0 -or
        $runtimeUnlockProbeMissingRejectedEvents.Count -gt 0 -or
        $runtimeUnlockProbeFailedEvents.Count -gt 0 -or
        $runtimeUnlockPreCommitProbeFailedEvents.Count -gt 0
    $runtimeUnlockProbeCommitVerdict = if ($runtimeUnlockPreCommitProbeStartedEvents.Count -eq 0 -and
        $runtimeUnlockPairedCommitStartedEvents.Count -eq 0) {
        'none'
    } elseif ($runtimeUnlockPreCommitProbeAckMissingCount -gt 0) {
        'fail'
    } elseif ($runtimeUnlockPairedCommitConfirmedEvents.Count -gt 0 -and
        $runtimeUnlockPreCommitRouteEpochRecoveredEvents.Count -gt 0 -and
        $runtimeUnlockPairedCommitAbortedEvents.Count -eq 0) {
        'pass'
    } else {
        'fail'
    }

    $runtimeUnlockRegularV4RecoveryArbitrationVerdict = if ($runtimeUnlockRegularV4ActivationWindowStartedEvents.Count -eq 0 -and
        $runtimeUnlockDispatchDeferredForRegularV4RecoveryEvents.Count -eq 0) {
        'none'
    } elseif ($runtimeUnlockRegularV4ActivationWindowPeerVisibleEvents.Count -gt 0 -and
        $runtimeUnlockRegularV4ActivationWindowFailedEvents.Count -eq 0) {
        'pass'
    } else {
        'fail'
    }

    $classification = [pscustomobject]@{
        Class = $class
        FirstProofChainFailureClass = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.Class } else { '(none)' }
        FirstProofChainFailureEvent = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.Event } else { '(none)' }
        FirstProofChainFailureReason = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.Reason } else { '(none)' }
        FirstProofChainFailureSequence = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.Sequence } else { -1L }
        FirstProofChainFailureSourcePath = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.SourcePath } else { '(none)' }
        FirstProofChainFailureLineNumber = if ($null -ne $firstProofChainFailure) { $firstProofChainFailure.LineNumber } else { 0 }
        FirstProofChainFailureWriterSequence = if ($null -ne $firstProofChainFailure) {
            [int64]$firstProofChainFailure.WriterSequence
        } else { 0L }
        SemanticFailureDomain = if ($class -eq
                'filetransfer_gui_live_fallback_fault_window_missed') {
            'evidence_harness'
        }
        elseif ($class -in @(
                'filetransfer_live_route_epoch_projection_missing')) {
            'route_evidence'
