        fallback_tail_bridge_recovery_generation_mismatch_raw_count = [string]$recoveryClassification.FallbackTailBridgeRecoveryGenerationMismatchRawCount
        fallback_tail_bridge_recovery_generation_mismatch_distinct_count = [string]$recoveryClassification.FallbackTailBridgeRecoveryGenerationMismatchDistinctCount
        fallback_tail_bridge_recovery_generation_mismatch_recovered_count = [string]$recoveryClassification.FallbackTailBridgeRecoveryGenerationMismatchRecoveredCount
        fallback_tail_bridge_recovery_generation_mismatch_unresolved_count = [string]$recoveryClassification.FallbackTailBridgeRecoveryGenerationMismatchUnresolvedCount
        post_tuna_fallback_paired_yield_transport_epoch_reauthorization_verdict = $recoveryClassification.FallbackTailTransportEpochReauthorizationVerdict
        post_tuna_fallback_paired_yield_transport_epoch_reauthorization_missing_raw_count = [string]$recoveryClassification.FallbackTailTransportEpochReauthorizationRawCount
        post_tuna_fallback_paired_yield_transport_epoch_reauthorization_missing_distinct_count = [string]$recoveryClassification.FallbackTailTransportEpochReauthorizationDistinctCount
        post_tuna_fallback_paired_yield_transport_epoch_reauthorization_missing_recovered_count = [string]$recoveryClassification.FallbackTailTransportEpochReauthorizationRecoveredCount
        post_tuna_fallback_paired_yield_transport_epoch_reauthorization_missing_unresolved_count = [string]$recoveryClassification.FallbackTailTransportEpochReauthorizationUnresolvedCount
        runtime_unlock_probe_recovery_trigger_count = [string]$recoveryClassification.RuntimeUnlockProbeRecoveryTriggerCount
        runtime_unlock_probe_recovery_authority_lost_raw_count = [string]$recoveryClassification.RuntimeUnlockProbeRecoveryAuthorityLostRawCount
        runtime_unlock_probe_recovery_authority_lost_distinct_count = [string]$recoveryClassification.RuntimeUnlockProbeRecoveryAuthorityLostDistinctCount
        runtime_unlock_probe_recovery_authority_lost_recovered_count = [string]$recoveryClassification.RuntimeUnlockProbeRecoveryAuthorityLostRecoveredCount
        runtime_unlock_probe_recovery_authority_lost_unresolved_count = [string]$recoveryClassification.RuntimeUnlockProbeRecoveryAuthorityLostUnresolvedCount
        runtime_unlock_probe_recovery_authority_verdict = $recoveryClassification.RuntimeUnlockProbeRecoveryAuthorityVerdict
        first_proof_chain_failure_class = $recoveryClassification.FirstProofChainFailureClass
        first_proof_chain_failure_event = $recoveryClassification.FirstProofChainFailureEvent
        first_proof_chain_failure_reason = $recoveryClassification.FirstProofChainFailureReason
        first_proof_chain_failure_sequence = [string]$recoveryClassification.FirstProofChainFailureSequence
        first_proof_chain_failure_source_path = $recoveryClassification.FirstProofChainFailureSourcePath
        first_proof_chain_failure_line_number = [string]$recoveryClassification.FirstProofChainFailureLineNumber
        first_proof_chain_failure_writer_sequence = [string]$recoveryClassification.FirstProofChainFailureWriterSequence
        semantic_failure_domain = $recoveryClassification.SemanticFailureDomain
        runtime_unlock_retry_dispatch_proof_verdict = $recoveryClassification.RuntimeUnlockRetryDispatchProofVerdict
        runtime_unlock_retry_dispatch_post_grant_hold_raw_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchPostGrantHoldRawCount
        runtime_unlock_retry_dispatch_post_grant_hold_distinct_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchPostGrantHoldDistinctCount
        runtime_unlock_retry_dispatch_post_grant_hold_recovered_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchPostGrantHoldRecoveredCount
        runtime_unlock_retry_dispatch_post_grant_hold_unresolved_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchPostGrantHoldUnresolvedCount
        runtime_unlock_retry_dispatch_post_grant_hold_verdict = $recoveryClassification.RuntimeUnlockRetryDispatchPostGrantHoldVerdict
        runtime_unlock_precommit_probe_start_handoff_missing_raw_count = [string]$recoveryClassification.RuntimeUnlockPreCommitProbeStartHandoffMissingRawCount
        runtime_unlock_precommit_probe_start_handoff_missing_distinct_count = [string]$recoveryClassification.RuntimeUnlockPreCommitProbeStartHandoffMissingDistinctCount
        runtime_unlock_precommit_probe_start_handoff_missing_recovered_count = [string]$recoveryClassification.RuntimeUnlockPreCommitProbeStartHandoffMissingRecoveredCount
        runtime_unlock_precommit_probe_start_handoff_missing_unresolved_count = [string]$recoveryClassification.RuntimeUnlockPreCommitProbeStartHandoffMissingUnresolvedCount
        runtime_unlock_precommit_probe_start_handoff_verdict = $recoveryClassification.RuntimeUnlockPreCommitProbeStartHandoffVerdict
        runtime_unlock_responder_acked_probe_route_transition_handoff_missing_raw_count = [string]$recoveryClassification.RuntimeUnlockResponderPeerProbeHandoffMissingRawCount
        runtime_unlock_responder_acked_probe_route_transition_handoff_missing_distinct_count = [string]$recoveryClassification.RuntimeUnlockResponderPeerProbeHandoffMissingDistinctCount
        runtime_unlock_responder_acked_probe_route_transition_handoff_missing_recovered_count = [string]$recoveryClassification.RuntimeUnlockResponderPeerProbeHandoffMissingRecoveredCount
        runtime_unlock_responder_acked_probe_route_transition_handoff_missing_unresolved_count = [string]$recoveryClassification.RuntimeUnlockResponderPeerProbeHandoffMissingUnresolvedCount
        runtime_unlock_responder_acked_probe_route_transition_handoff_verdict = $recoveryClassification.RuntimeUnlockResponderPeerProbeHandoffVerdict
        runtime_unlock_retry_dispatch_chain_closure_proof_verdict = $recoveryClassification.RuntimeUnlockRetryDispatchChainClosureProofVerdict
        runtime_unlock_retry_dispatch_settlement_reported_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchSettlementReportedCount
        runtime_unlock_retry_dispatch_settlement_accepted_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchSettlementAcceptedCount
        runtime_unlock_retry_dispatch_settlement_idempotent_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchSettlementIdempotentCount
        runtime_unlock_retry_dispatch_settlement_rejected_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchSettlementRejectedCount
        runtime_unlock_retry_dispatch_settlement_decision_ignored_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchSettlementDecisionIgnoredCount
        runtime_unlock_retry_dispatch_settlement_acceptance_missing_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchSettlementAcceptanceMissingCount
        runtime_unlock_retry_dispatch_complete_bounded_closure_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchCompleteBoundedClosureCount
        runtime_unlock_retry_dispatch_incomplete_bounded_closure_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchIncompleteBoundedClosureCount
        runtime_unlock_retry_dispatch_fresh_independent_grant_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchFreshIndependentGrantCount
        runtime_unlock_retry_dispatch_invalid_fresh_grant_count = [string]$recoveryClassification.RuntimeUnlockRetryDispatchInvalidFreshGrantCount
    }
}

function New-FileTransferInvariantLedgerLines {
    param([Parameter(Mandatory = $true)]$Ledger)

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($property in @($Ledger.PSObject.Properties)) {
        $value = if ($null -eq $property.Value -or [string]::IsNullOrWhiteSpace([string]$property.Value)) { 'unknown' } else { [string]$property.Value }
        $lines.Add(("{0}={1}" -f $property.Name, $value)) | Out-Null
    }

    return $lines.ToArray()
}

function Write-FileTransferInvariantLedgerArtifacts {
    param(
        [Parameter(Mandatory = $true)][string]$ArtifactDir,
        [Parameter(Mandatory = $true)]$Summary,
        [Parameter(Mandatory = $true)]$GateResult,
        [ValidateSet('None', 'SwitchOff', 'MultiToggle', 'RegularActivationCycle')]
        [string]$LiveRouteProofMode = 'None'
    )

    $ledger = New-FileTransferInvariantLedgerObject -ArtifactDir $ArtifactDir -Summary $Summary -GateResult $GateResult -LiveRouteProofMode $LiveRouteProofMode
    $ledgerLines = New-FileTransferInvariantLedgerLines -Ledger $ledger
    Write-FileTransferArtifact -ArtifactDir $ArtifactDir -FileName 'phase0-invariant-ledger.txt' -Lines $ledgerLines | Out-Null
    Write-FileTransferArtifact -ArtifactDir $ArtifactDir -FileName 'filetransfer-invariant-summary.txt' -Lines $ledgerLines | Out-Null
    $ledger | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $ArtifactDir 'phase0-invariant-ledger.json') -Encoding UTF8
    $ledger | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $ArtifactDir 'filetransfer-invariant-summary.json') -Encoding UTF8
    return $ledger
}

function Write-FileTransferDiagnosticsArtifacts {
    param(
        [Parameter(Mandatory = $true)][string]$ArtifactDir,
        [Parameter(Mandatory = $true)]$Summary,
        [Parameter(Mandatory = $true)]$GateResult,
        [ValidateSet('None', 'SwitchOff', 'MultiToggle', 'RegularActivationCycle')]
        [string]$LiveRouteProofMode = 'None',
        [switch]$IncludeRawSlices
    )

    $analyzedFiles = if ($Summary.LogFiles.Count -gt 0) { $Summary.LogFiles -join ';' } else { '(none)' }
    $warningKinds = @(@(
        foreach ($warning in @($GateResult.Warnings)) {
            $text = [string]$warning
            if ($text -eq 'external bridge/NKN health churn overlapped the completed transfer') {
                'external_transport_churn'
            }
            elseif ($text -eq 'recovered post-Tuna fallback bridge queue clear overlapped the completed transfer') {
                'recovered_post_tuna_fallback_bridge_clear'
            }
            elseif ($text -eq 'recovered runtime-unlock bridge queue clear overlapped the completed transfer' -or
                $text -eq 'recovered runtime unlock bridge queue clear overlapped the completed transfer') {
                'recovered_runtime_unlock_bridge_clear'
            }
            elseif ($text -eq 'recovered regular NKN V4 bridge queue clear overlapped the completed transfer') {
                'recovered_regular_v4_bridge_clear'
            }
            elseif ($text -eq 'post-Tuna fallback V6 send timeout churn recovered before terminal completion') {
                'fallback_v6_send_timeout_churn'
            }
            elseif ($text -eq 'post-Tuna fallback frontier repair churn recovered before terminal completion') {
                'fallback_frontier_repair_churn'
            }
            elseif ($text -eq 'post-Tuna fallback receiver state churn recovered before terminal completion') {
                'fallback_receiver_state_churn'
            }
            elseif ($text -eq 'screen-share media pressure overlapped the completed transfer') {
                'cohabitation_pressure'
            }
            elseif ($text -eq 'repair/reorder/degraded pressure recovered before terminal completion') {
                'recovered_pressure'
            }
            elseif ($text -eq 'progress_timeout_with_receiver_gap_stall') {
                'progress_timeout_with_receiver_gap_stall'
            }
            elseif (-not [string]::IsNullOrWhiteSpace($text)) {
                ($text.ToLowerInvariant() -replace '[^a-z0-9]+', '_' -replace '^_+|_+$', '')
            }
        }
    ) | Select-Object -Unique)
    $warningCap = Get-FileTransferGateWarningCap -GateResult $GateResult
    $fallbackDiagnostics = Get-FileTransferGateFallbackDiagnostics -GateResult $GateResult
    $liveRouteProof = Get-FileTransferLiveRouteEpochProof -TransferEvents $Summary.TransferEvents -Mode $LiveRouteProofMode
    $recoveryClassification = Get-FileTransferRecoveryFailureClassification `
        -Summary $Summary `
        -LiveRouteProofMode $LiveRouteProofMode
    $fallbackAuthorityProof = Get-FileTransferFallbackLegAuthorityProof -TransferEvents $Summary.TransferEvents
    $fallbackTailProof = Get-FileTransferFallbackTailReconciliationProof -Summary $Summary
    $bridgeLivenessProof = Get-FileTransferBridgeLivenessIntegrationProof -Summary $Summary
    $controlPlaneProof = Get-FileTransferControlPlaneIsolationProof -Summary $Summary
    $staleRejectedActionEffectProof = Get-FileTransferStaleRejectedActionEffectProof -Summary $Summary
    $fallbackRuntimeUnlockSeparationProof = Get-FileTransferFallbackRuntimeUnlockSeparationProof -Summary $Summary
    $publicationAuthorityFieldCoverageProof = Get-FileTransferPublicationAuthorityFieldCoverageProof -Summary $Summary
    $fileTunaV4DataPathProof = Get-FileTransferFileTunaV4DataPathProof -Summary $Summary
    $invariantLedger = New-FileTransferInvariantLedgerObject -ArtifactDir $ArtifactDir -Summary $Summary -GateResult $GateResult -LiveRouteProofMode $LiveRouteProofMode
    $releaseRouteLaw = Get-FileTransferInvariantRouteLawResult -Summary $Summary
    $terminalLifecycleInvariant = Get-FileTransferInvariantTerminalLifecycleResult -Summary $Summary -LateFrameClassification $invariantLedger.late_frame_classification
    $controlPriorityInvariant = Get-FileTransferInvariantControlPriorityResult -Summary $Summary
    $runtimeOwnerInvariant = Get-FileTransferInvariantRuntimeOwnerResult -Summary $Summary
    $combinedInvariant = Get-FileTransferInvariantCombinedGateResult -RouteLaw $releaseRouteLaw -TerminalLifecycle $terminalLifecycleInvariant -ControlPriority $controlPriorityInvariant -RuntimeOwner $runtimeOwnerInvariant -StaleRejectedActionEffect $staleRejectedActionEffectProof -FallbackRuntimeUnlockSeparation $fallbackRuntimeUnlockSeparationProof -PublicationAuthorityFieldCoverage $publicationAuthorityFieldCoverageProof -FileTunaV4DataPathProof $fileTunaV4DataPathProof

    $effectiveVerdict = $GateResult.Verdict
    $effectiveGateStatus = $GateResult.GateStatus
    $effectiveNextArtifact = $GateResult.NextArtifact
    $effectiveHardFailures = New-Object System.Collections.Generic.List[string]
    foreach ($failure in @($GateResult.HardFailures)) {
        $effectiveHardFailures.Add([string]$failure) | Out-Null
    }
    [object[]]$effectiveEvidenceEvents = @($GateResult.EvidenceEvents)
    $baseVerdictText = if ($null -eq $GateResult.Verdict) { '' } else { [string]$GateResult.Verdict }
    $invariantMayOwnAcceptanceFailure = $combinedInvariant.Verdict -eq 'fail' -and -not $baseVerdictText.StartsWith('INCONCLUSIVE', [System.StringComparison]::OrdinalIgnoreCase)
    if ($invariantMayOwnAcceptanceFailure -and $GateResult.GateStatus -ne 'fail') {
        $effectiveVerdict = 'FAIL_PROTOCOL_OR_INTEGRITY'
        $effectiveGateStatus = 'fail'
        $effectiveNextArtifact = 'filetransfer-invariant-summary.txt'
        foreach ($finding in @($combinedInvariant.Findings)) {
            $effectiveHardFailures.Add(("invariant: {0}" -f $finding)) | Out-Null
        }
        $effectiveEvidenceEvents = @($combinedInvariant.EvidenceEvents + $effectiveEvidenceEvents | Select-Object -First 30)
    }

    if ($recoveryClassification.Class -in @(
            'runtime_unlock_retry_dispatch_successor_attempt_mismatch',
            'runtime_unlock_retry_dispatch_settlement_unaccepted',
            'runtime_unlock_retry_dispatch_chain_closure_incomplete',
            'runtime_unlock_retry_dispatch_fresh_chain_invalid_after_closure',
            'runtime_unlock_retry_dispatch_missing',
            'runtime_unlock_retry_dispatch_missing_after_authority_granted',
            'runtime_unlock_retry_dispatch_successor_missing_after_missing_dispatch',
            'runtime_unlock_retry_dispatch_fallback_paired_yield_successor_release_invalid',
            'runtime_unlock_retry_dispatch_grant_bypassed_by_retry_budget',
            'runtime_unlock_retry_dispatch_contract_unsettled',
            'runtime_unlock_retry_dispatch_held_after_authority_granted',
            'runtime_unlock_precommit_probe_start_handoff_missing',
            'runtime_unlock_responder_acked_probe_route_transition_handoff_missing',
            'runtime_unlock_tuna_probe_recovery_authority_lost',
            'runtime_unlock_regular_v4_recovery_lease_not_issued',
            'runtime_unlock_regular_v4_recovery_lease_closure_not_adopted',
            'runtime_unlock_regular_v4_recovery_lease_closure_liveness_not_preserved',
            'filetransfer_receive_recovery_completed_unproven_successor_missing',
            'filetransfer_receive_recovery_completed_proven_successor_missing',
            'filetransfer_receive_recovery_completed_unproven_payload_hold_not_preserved',
            'filetransfer_receive_recovery_completed_retained_proof_state_publication_missing',
            'filetransfer_receive_recovery_completed_retained_proof_state_recheck_heartbeat_suppressed',
            'filetransfer_bridge_recovery_execution_payload_hold_missing',
            'filetransfer_bridge_recovery_execution_submission_barrier_drain_missing',
            'filetransfer_bridge_recovery_execution_startup_payload_isolation_missing',
            'filetransfer_bridge_recovery_execution_soft_to_hard_handoff_missing',
            'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_handoff_missing',
            'runtime_unlock_initial_offer_retry_lifecycle_handoff_missing',
            'runtime_unlock_initial_activation_answer_peer_delivery_missing',
            'runtime_unlock_initial_offer_receive_recovery_hold_not_preserved',
            'runtime_unlock_initial_activation_receive_recovery_hold_release_delivery_missing',
            'runtime_unlock_initial_activation_receive_recovery_hold_released_path_lease_expired',
            'runtime_unlock_initial_activation_receive_recovery_hold_released_offer_expired',
            'runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_missing',
            'regular_v4_frontier_tail_repair_state_publication_missing',
            'regular_v4_frontier_repair_missing_range_not_preserved',
            'regular_v4_frontier_repair_settlement_disposition_unverifiable',
            'regular_v4_frontier_repair_pressure_authority_lifecycle_split',
            'regular_v4_frontier_repair_pressure_recovery_handoff_missing',
            'regular_v4_frontier_repair_initial_pressure_install_missing',
            'regular_v4_frontier_repair_successor_pressure_install_missing',
            'filetransfer_route_transition_draining_transport_grace_terminalization') -and
        ($effectiveGateStatus -ne 'fail' -or
            $recoveryClassification.Class -eq
                'filetransfer_route_transition_draining_transport_grace_terminalization')) {
        $effectiveVerdict = 'FAIL_PROTOCOL_OR_INTEGRITY'
        $effectiveGateStatus = 'fail'
        $effectiveNextArtifact = 'filetransfer-operator-verdict.txt'
        $dispatchFailureText = switch ($recoveryClassification.Class) {
            'runtime_unlock_retry_dispatch_successor_attempt_mismatch' {
                'recovery: runtime unlock retry successor attempt does not match the settled predecessor'
                break
            }
            'runtime_unlock_retry_dispatch_settlement_unaccepted' {
                'recovery: runtime unlock retry settlement was not accepted by Core'
                break
            }
            'runtime_unlock_retry_dispatch_chain_closure_incomplete' {
                'recovery: bounded runtime unlock retry rejection lacks authoritative chain-closure proof'
                break
            }
            'runtime_unlock_retry_dispatch_fresh_chain_invalid_after_closure' {
                'recovery: independent runtime unlock retry after bounded closure did not restart at 1/0 without a predecessor'
                break
            }
            'runtime_unlock_retry_dispatch_missing_after_authority_granted' {
                'recovery: runtime unlock retry dispatch authority granted without observed dispatch'
                break
            }
            'runtime_unlock_retry_dispatch_held_after_authority_granted' {
                'recovery: runtime unlock retry dispatch held by evidence after authority grant'
                break
            }
            'runtime_unlock_retry_dispatch_successor_missing_after_missing_dispatch' {
                'recovery: runtime unlock MissingDispatch settlement missing coordinator successor'
                break
            }
            'runtime_unlock_retry_dispatch_fallback_paired_yield_successor_release_invalid' {
                'recovery: fallback paired-yield retry successor rejected the predecessor release tuple'
                break
            }
            'runtime_unlock_retry_dispatch_grant_bypassed_by_retry_budget' {
                'recovery: coordinator retry grant bypassed by legacy retry budget'
                break
            }
            'runtime_unlock_retry_dispatch_contract_unsettled' {
                'recovery: coordinator retry grant missing exactly-once contract settlement'
                break
            }
            'runtime_unlock_tuna_probe_recovery_authority_lost' {
                'recovery: coordinator-held Tuna probe recovery authority was discarded before settlement consumption'
                break
            }
            'runtime_unlock_regular_v4_recovery_lease_not_issued' {
                'recovery: regular-V4 receive recovery completed without a coordinator recovery-liveness lease'
                break
            }
            'runtime_unlock_regular_v4_recovery_lease_closure_not_adopted' {
                'recovery: accepted regular-V4 recovery-lease closure was not adopted at the local receive-proof boundary'
                break
            }
            'runtime_unlock_regular_v4_recovery_lease_closure_liveness_not_preserved' {
                'recovery: regular-V4 closure-window session liveness was not preserved while awaiting local receive proof'
                break
            }
            'filetransfer_receive_recovery_completed_unproven_successor_missing' {
                'recovery: completed receive recovery without proof blocked a fresh coordinator successor'
                break
            }
            'filetransfer_receive_recovery_completed_proven_successor_missing' {
                'recovery: completed receive recovery with proof but an unreserved adopted closure blocked a fresh coordinator successor'
                break
            }
            'filetransfer_receive_recovery_completed_unproven_payload_hold_not_preserved' {
                'recovery: completed receive recovery resumed payload before exact receive proof'
                break
            }
            'filetransfer_receive_recovery_completed_retained_proof_state_publication_missing' {
                'recovery: completed receive recovery observed peer reachability without coordinator-authorized V4 proof-state publication'
                break
            }
            'filetransfer_receive_recovery_completed_retained_proof_state_recheck_heartbeat_suppressed' {
                'recovery: completed retained receive recovery could not recheck proof state because frozen outbound progress suppressed peer heartbeat evidence'
                break
            }
            'filetransfer_bridge_recovery_execution_soft_to_hard_handoff_missing' {
                'recovery: one-shot bridge recovery timed out before its authorized hard fallback could start'
                break
            }
            'filetransfer_bridge_recovery_execution_startup_payload_isolation_missing' {
                'recovery: bridge startup accepted payload before readiness and exhausted the one-shot command'
                break
            }
            'filetransfer_bridge_recovery_execution_payload_hold_missing' {
                'recovery: coordinator-authorized repair payload was escalated to terminal failure while bridge recovery held submissions'
                break
            }
            'filetransfer_bridge_recovery_execution_submission_barrier_drain_missing' {
                'recovery: one-shot bridge recovery exhausted before the source submission gate drained'
                break
            }
            'runtime_unlock_retry_regular_v4_recovery_lease_closure_hold_not_preserved' {
                'recovery: held runtime-unlock retry was terminally disposed inside an accepted regular-V4 closure window'
                break
            }
            'runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_handoff_missing' {
                'recovery: runtime-unlock offer timeout did not join the retained regular-V4 recovery closure window'
                break
            }
            'runtime_unlock_initial_offer_retry_lifecycle_handoff_missing' {
                'recovery: initial runtime-unlock offer retirement did not enter the coordinator retry lifecycle'
                break
            }
            'runtime_unlock_responder_acked_probe_route_transition_handoff_missing' {
                'recovery: accepted responder answer ACK did not bind the existing peer Tuna probe to the inbound route transition'
                break
            }
            'runtime_unlock_initial_activation_answer_peer_delivery_missing' {
                'recovery: validated runtime-unlock answer was not delivered to the initiating peer'
                break
            }
            'runtime_unlock_initial_offer_receive_recovery_hold_not_preserved' {
                'recovery: initial runtime-unlock activation exhausted its retry budget while receive recovery awaited proof'
                break
            }
            'runtime_unlock_initial_activation_receive_recovery_hold_release_delivery_missing' {
                'recovery: coordinator released the held initial activation through the invalidation boundary'
                break
            }
            'runtime_unlock_initial_activation_receive_recovery_hold_released_offer_expired' {
                'recovery: coordinator released a held initial activation with expired wire evidence'
                break
            }
            'runtime_unlock_initial_activation_receive_recovery_hold_released_path_lease_expired' {
                'recovery: coordinator released a held initial activation after its Tuna listener expired'
                break
            }
            'runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_missing' {
                'recovery: coordinator-held runtime unlock retry was not rechecked after fallback-tail recovery'
                break
            }
            'regular_v4_frontier_tail_repair_state_publication_missing' {
                'recovery: coordinator-authorized regular-V4 frontier-tail repair was not published to the peer'
                break
            }
            'regular_v4_frontier_repair_missing_range_not_preserved' {
                'recovery: unresolved regular-V4 frontier repair was omitted from a newer receiver state'
                break
            }
            'regular_v4_frontier_repair_settlement_disposition_unverifiable' {
                'recovery: accepted regular-V4 repair settlement is missing durable disposition evidence'
                break
            }
            'regular_v4_frontier_repair_pressure_authority_lifecycle_split' {
                'recovery: coordinator repair authority outlived the legacy adapter pressure TTL'
                break
            }
            'regular_v4_frontier_repair_pressure_recovery_handoff_missing' {
                'recovery: installed regular-V4 repair pressure blocked coordinator receive-recovery issuance'
                break
            }
            'regular_v4_frontier_repair_initial_pressure_install_missing' {
                'recovery: initial regular-V4 repair pressure was not installed before settlement'
                break
            }
            'regular_v4_frontier_repair_successor_pressure_install_missing' {
                'recovery: successor regular-V4 repair pressure was not installed before predecessor retirement'
                break
            }
            'filetransfer_route_transition_draining_transport_grace_terminalization' {
                'recovery: coordinator-owned route-transition pause was treated as an expired transport-disconnect grace'
                break
            }
            default {
                'recovery: runtime unlock retry release missing dispatch proof'
            }
        }
        $effectiveHardFailures.Add($dispatchFailureText) | Out-Null
    }

    if ($recoveryClassification.Class -in @(
            'runtime_unlock_precommit_probe_start_handoff_missing',
            'regular_v4_frontier_repair_initial_pressure_install_missing',
            'regular_v4_frontier_repair_pressure_recovery_handoff_missing')) {
        $effectiveVerdict = 'INCONCLUSIVE'
        $effectiveGateStatus = 'fail'
        $effectiveNextArtifact = 'filetransfer-operator-verdict.txt'
    }

    if ($recoveryClassification.FileTransferReceiveRecoveryOperationUnresolvedCount -gt 0) {
        $effectiveHardFailures.Add(
            'recovery: coordinator receive-recovery operation incomplete') | Out-Null
        $effectiveVerdict = 'FAIL_PROTOCOL_OR_INTEGRITY'
        $effectiveGateStatus = 'fail'
        $effectiveNextArtifact = 'filetransfer-operator-verdict.txt'
    }

